-- source: supabase/schemas/catalogue_private/functions/apply_v2_admin_model_capabilities.sql
CREATE OR REPLACE FUNCTION catalogue_private.apply_v2_admin_model_capabilities (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_capabilities  jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_capability jsonb;
  v_route_id text;
  v_provider_model_id text;
  v_provider_model_slug text;
  v_capability_id text;
  v_previous_capability_id text;
  v_existing_capability_id text;
  v_existing_effective_to timestamptz;
  v_has_previous boolean;
  v_has_target boolean;
begin
  if not exists (
    select 1
    from public.users
    where user_id = p_actor_user_id
      and lower(coalesce(role::text, '')) = 'admin'
  ) then
    raise exception 'actor must have the admin role';
  end if;

  if jsonb_typeof(coalesce(p_capabilities, '[]'::jsonb)) <> 'array' then
    raise exception 'provider capabilities must be an array';
  end if;

  if not exists (
    select 1 from public.v2_models where model_slug = p_model_slug
  ) then
    raise exception 'model not found';
  end if;

  -- The graph mutation locks the model before calling this helper. Reject
  -- duplicate target keys here so the error is deterministic before the
  -- per-row upserts run.
  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_capabilities, '[]'::jsonb)) as payload(value)
    join public.v2_model_provider_routes route
      on route.model_slug = p_model_slug
      and route.provider_slug = nullif(trim(payload.value->>'provider_id'), '')
      and route.provider_model_slug = coalesce(
        nullif(trim(payload.value->>'provider_model_slug'), ''),
        nullif(trim(payload.value->>'api_model_id'), '')
      )
      and (
        nullif(trim(payload.value->>'provider_model_id'), '') is null
        or route.provider_model_id = trim(payload.value->>'provider_model_id')
      )
    group by route.provider_model_id, lower(trim(payload.value->>'capability_id'))
    having count(*) > 1
  ) then
    raise exception 'a provider model cannot have duplicate capabilities';
  end if;

  for v_capability in
    select value
    from jsonb_array_elements(coalesce(p_capabilities, '[]'::jsonb))
  loop
    v_provider_model_id := nullif(trim(v_capability->>'provider_model_id'), '');
    v_provider_model_slug := coalesce(
      nullif(trim(v_capability->>'provider_model_slug'), ''),
      nullif(trim(v_capability->>'api_model_id'), '')
    );
    v_capability_id := nullif(lower(trim(v_capability->>'capability_id')), '');
    v_previous_capability_id := nullif(lower(trim(v_capability->>'previous_capability_id')), '');

    if v_capability_id is null then
      raise exception 'provider capability id is required';
    end if;

    select route.provider_model_id
    into v_route_id
    from public.v2_model_provider_routes route
    where route.model_slug = p_model_slug
      and route.provider_slug = nullif(trim(v_capability->>'provider_id'), '')
      and route.provider_model_slug = v_provider_model_slug
      and (v_provider_model_id is null or route.provider_model_id = v_provider_model_id)
    order by route.provider_model_id
    limit 1;

    if v_route_id is null then
      raise exception 'provider capability does not match a model route';
    end if;

    select exists (
      select 1
      from public.v2_route_capabilities capability
      where capability.provider_model_id = v_route_id
        and lower(capability.capability_id) = v_capability_id
    )
    into v_has_target;

    v_existing_capability_id := null;
    v_existing_effective_to := null;
    v_has_previous := false;
    select capability.capability_id, capability.effective_to
    into v_existing_capability_id, v_existing_effective_to
    from public.v2_route_capabilities capability
    where capability.provider_model_id = v_route_id
      and lower(capability.capability_id) = coalesce(v_previous_capability_id, v_capability_id)
    for update;

    v_has_previous := v_existing_capability_id is not null;
    -- Historical rows are immutable even when the editor keeps the same
    -- capability identity. Lock and validate the source before any upsert.
    if v_has_previous and v_existing_effective_to is not null
       and v_existing_effective_to <= now() then
      raise exception 'historical capabilities cannot be changed';
    end if;

    if v_previous_capability_id is not null
       and v_previous_capability_id <> v_capability_id then
      if v_has_previous and v_has_target then
        raise exception 'provider model already has capability %', v_capability_id;
      end if;

      -- A historical row is immutable. An active or future row can be
      -- reassigned in place, which is the operation the editor needs.
      if v_has_previous and exists (
        select 1
        from public.v2_route_parameter_support support
        where support.provider_model_id = v_route_id
          and lower(support.capability_id) = lower(v_existing_capability_id)
      ) then
        raise exception 'capability has parameter support records and cannot be reassigned';
      end if;

      if v_has_previous and exists (
        select 1
        from public.v2_execution_plans plan
        where plan.provider_model_id = v_route_id
          and lower(plan.capability_id) = lower(v_existing_capability_id)
      ) then
        raise exception 'capability has execution plans and cannot be reassigned';
      end if;

      if v_has_previous then
        update public.v2_route_capabilities
        set capability_id = v_capability_id,
            updated_at = now()
        where provider_model_id = v_route_id
          and capability_id = v_existing_capability_id;
      end if;
    end if;

    insert into public.v2_route_capabilities(
      provider_model_id,
      capability_id,
      status,
      params,
      effective_from,
      effective_to,
      metadata,
      updated_at
    )
    values (
      v_route_id,
      v_capability_id,
      case
        when coalesce(v_capability->>'status', '') like 'deranked_%' then 'degraded'
        else coalesce(nullif(trim(v_capability->>'status'), ''), 'active')
      end,
      coalesce(v_capability->'params', '{}'::jsonb),
      nullif(v_capability->>'effective_from', '')::timestamptz,
      nullif(v_capability->>'effective_to', '')::timestamptz,
      jsonb_build_object('editor_status', v_capability->>'status', 'source', 'admin'),
      now()
    )
    on conflict (provider_model_id, capability_id) do update set
      status = excluded.status,
      params = excluded.params,
      effective_from = excluded.effective_from,
      effective_to = excluded.effective_to,
      metadata = public.v2_route_capabilities.metadata || excluded.metadata,
      updated_at = now();
  end loop;
end;
$function$;

GRANT EXECUTE ON FUNCTION "catalogue_private"."apply_v2_admin_model_capabilities"(uuid, text, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "catalogue_private"."apply_v2_admin_model_capabilities"(uuid, text, jsonb) FROM PUBLIC;

-- source: supabase/schemas/catalogue_private/functions/apply_v2_admin_model_provider_routes.sql
CREATE OR REPLACE FUNCTION catalogue_private.apply_v2_admin_model_provider_routes (
  p_actor_user_id   uuid,
  p_model_slug      text,
  p_provider_models jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_route jsonb;
  v_existing public.v2_model_provider_routes%rowtype;
  v_requested_route_id text;
  v_route_id text;
  v_provider_slug text;
  v_provider_model_slug text;
  v_status text;
  v_routing_enabled boolean;
  v_provider_availability_status text;
  v_phaseo_status text;
  v_access_scope text;
  v_input_modalities text[];
  v_output_modalities text[];
  v_regions text[];
  v_context_length integer;
  v_max_output_tokens integer;
  v_effective_from timestamptz;
  v_effective_to timestamptz;
  v_metadata jsonb;
begin
  if not exists (
    select 1
    from public.users
    where user_id = p_actor_user_id
      and lower(coalesce(role::text, '')) = 'admin'
  ) then
    raise exception 'actor must have the admin role';
  end if;

  if jsonb_typeof(coalesce(p_provider_models, '[]'::jsonb)) <> 'array' then
    raise exception 'provider models must be an array';
  end if;

  if not exists (
    select 1 from public.v2_models where model_slug = p_model_slug
  ) then
    raise exception 'model not found';
  end if;

  for v_route in
    select value
    from jsonb_array_elements(coalesce(p_provider_models, '[]'::jsonb))
  loop
    v_existing := null;
    v_provider_slug := nullif(trim(coalesce(v_route->>'provider_id', v_route->>'provider_slug')), '');
    v_provider_model_slug := nullif(trim(coalesce(v_route->>'provider_model_slug', v_route->>'api_model_id')), '');
    v_requested_route_id := nullif(trim(coalesce(v_route->>'provider_model_id', v_route->>'id')), '');

    if v_provider_slug is null then
      raise exception 'provider id is required';
    end if;
    if v_provider_model_slug is null then
      raise exception 'provider model slug is required';
    end if;
    if not exists (
      select 1 from public.v2_providers where provider_slug = v_provider_slug
    ) then
      raise exception 'provider not found';
    end if;

    -- Resolve by the database key first, then by the natural route identity.
    -- This keeps an editor save from inserting a duplicate route when an
    -- older source adapter supplied a stale provider-model id.
    if v_requested_route_id is not null and v_requested_route_id not like 'new-%' then
      if exists (
        select 1
        from public.v2_model_provider_routes route
        where route.provider_model_id = v_requested_route_id
          and route.model_slug <> p_model_slug
      ) then
        raise exception 'provider model id belongs to another model';
      end if;

      select route.*
      into v_existing
      from public.v2_model_provider_routes route
      where route.provider_model_id = v_requested_route_id
        and route.model_slug = p_model_slug
      for update;
    end if;

    if v_existing.provider_model_id is null then
      select route.*
      into v_existing
      from public.v2_model_provider_routes route
      where route.model_slug = p_model_slug
        and route.provider_slug = v_provider_slug
        and route.provider_model_slug = v_provider_model_slug
      order by route.created_at, route.provider_model_id
      limit 1
      for update;
    end if;

    v_route_id := coalesce(
      v_existing.provider_model_id,
      case
        when v_requested_route_id is null or v_requested_route_id like 'new-%' then null
        else v_requested_route_id
      end,
      v_provider_slug || ':' || p_model_slug || ':' || v_provider_model_slug
    );

    v_status := lower(coalesce(
      nullif(trim(coalesce(v_route->>'status', v_route->>'routing_status')), ''),
      nullif(trim(v_existing.status), ''),
      'active'
    ));
    if v_status not in ('active', 'degraded', 'disabled', 'retired') then
      v_status := 'active';
    end if;

    v_routing_enabled := coalesce(
      nullif(v_route->>'is_active_gateway', '')::boolean,
      nullif(v_route->>'routing_enabled', '')::boolean,
      coalesce(v_existing.routing_enabled, false)
    );

    v_phaseo_status := lower(coalesce(
      nullif(trim(v_route->>'phaseo_status'), ''),
      nullif(trim(v_existing.phaseo_status), ''),
      case when v_routing_enabled then 'enabled' else 'disabled' end
    ));
    if v_routing_enabled and v_phaseo_status <> 'enabled' then
      if not (v_route ? 'phaseo_status') then
        v_phaseo_status := 'enabled';
      else
        raise exception 'routable provider routes require phaseo_status=enabled';
      end if;
    end if;

    -- The editor does not currently send provider availability. Preserve an
    -- existing deprecated route during its future-dated retirement window.
    v_provider_availability_status := lower(case
      when v_route ? 'provider_availability_status' then
        coalesce(nullif(trim(v_route->>'provider_availability_status'), ''), 'unknown')
      when v_existing.provider_model_id is not null then
        coalesce(nullif(trim(v_existing.provider_availability_status), ''), 'unknown')
      when v_routing_enabled then 'available'
      else 'unknown'
    end);
    if v_routing_enabled
       and v_provider_availability_status not in ('available', 'preview', 'limited_access', 'deprecated') then
      if not (v_route ? 'provider_availability_status') then
        v_provider_availability_status := 'available';
      else
        raise exception 'routable provider routes require an available provider';
      end if;
    end if;

    v_access_scope := lower(coalesce(
      nullif(trim(v_route->>'access_scope'), ''),
      nullif(trim(v_existing.access_scope), ''),
      'public'
    ));
    if v_routing_enabled and v_access_scope <> 'public' then
      raise exception 'routable provider routes must have public access scope';
    end if;

    v_input_modalities := case
      when v_route ? 'input_modalities' then case
        when jsonb_typeof(v_route->'input_modalities') = 'array' then
          array(select jsonb_array_elements_text(v_route->'input_modalities'))
        when nullif(trim(v_route->>'input_modalities'), '') is not null then
          string_to_array(v_route->>'input_modalities', ',')
        else '{}'::text[]
      end
      when v_existing.provider_model_id is not null then
        coalesce(v_existing.input_modalities, '{}'::text[])
      else '{}'::text[]
    end;
    v_output_modalities := case
      when v_route ? 'output_modalities' then case
        when jsonb_typeof(v_route->'output_modalities') = 'array' then
          array(select jsonb_array_elements_text(v_route->'output_modalities'))
        when nullif(trim(v_route->>'output_modalities'), '') is not null then
          string_to_array(v_route->>'output_modalities', ',')
        else '{}'::text[]
      end
      when v_existing.provider_model_id is not null then
        coalesce(v_existing.output_modalities, '{}'::text[])
      else '{}'::text[]
    end;
    v_regions := case
      when jsonb_typeof(v_route->'regions') = 'array' then
        array(select jsonb_array_elements_text(v_route->'regions'))
      when v_existing.provider_model_id is not null then
        coalesce(v_existing.regions, '{}'::text[])
      else '{}'::text[]
    end;
    v_context_length := case
      when v_route ? 'context_length' then nullif(v_route->>'context_length', '')::integer
      else v_existing.context_length
    end;
    v_max_output_tokens := case
      when v_route ? 'max_output_tokens' then nullif(v_route->>'max_output_tokens', '')::integer
      else v_existing.max_output_tokens
    end;
    v_effective_from := case
      when v_route ? 'effective_from' then nullif(v_route->>'effective_from', '')::timestamptz
      else v_existing.effective_from
    end;
    v_effective_to := case
      when v_route ? 'effective_to' then nullif(v_route->>'effective_to', '')::timestamptz
      else v_existing.effective_to
    end;
    v_metadata := jsonb_strip_nulls(jsonb_build_object(
      'prompt_training_policy_override', v_route->>'prompt_training_policy_override',
      'prompt_training_override_notes', v_route->>'prompt_training_override_notes',
      'prompt_training_override_source_url', v_route->>'prompt_training_override_source_url',
      'quantization_scheme', v_route->>'quantization_scheme',
      'source', 'admin'
    ));

    insert into public.v2_model_provider_routes(
      provider_model_id,
      model_slug,
      provider_slug,
      provider_model_slug,
      status,
      routing_enabled,
      input_modalities,
      output_modalities,
      regions,
      context_length,
      max_output_tokens,
      effective_from,
      effective_to,
      metadata,
      provider_availability_status,
      phaseo_status,
      access_scope,
      updated_at
    )
    values (
      v_route_id,
      p_model_slug,
      v_provider_slug,
      v_provider_model_slug,
      v_status,
      v_routing_enabled,
      v_input_modalities,
      v_output_modalities,
      v_regions,
      v_context_length,
      v_max_output_tokens,
      v_effective_from,
      v_effective_to,
      v_metadata,
      v_provider_availability_status,
      v_phaseo_status,
      v_access_scope,
      now()
    )
    on conflict (provider_model_id) do update set
      model_slug = excluded.model_slug,
      provider_slug = excluded.provider_slug,
      provider_model_slug = excluded.provider_model_slug,
      status = excluded.status,
      routing_enabled = excluded.routing_enabled,
      input_modalities = excluded.input_modalities,
      output_modalities = excluded.output_modalities,
      regions = excluded.regions,
      context_length = excluded.context_length,
      max_output_tokens = excluded.max_output_tokens,
      effective_from = excluded.effective_from,
      effective_to = excluded.effective_to,
      metadata = (
        coalesce(public.v2_model_provider_routes.metadata, '{}'::jsonb)
          - 'prompt_training_policy_override'
          - 'prompt_training_override_notes'
          - 'prompt_training_override_source_url'
          - 'quantization_scheme'
      ) || excluded.metadata,
      provider_availability_status = excluded.provider_availability_status,
      phaseo_status = excluded.phaseo_status,
      access_scope = excluded.access_scope,
      updated_at = now();
  end loop;
end;
$function$;

GRANT EXECUTE ON FUNCTION "catalogue_private"."apply_v2_admin_model_provider_routes"(uuid, text, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "catalogue_private"."apply_v2_admin_model_provider_routes"(uuid, text, jsonb) FROM PUBLIC;

-- source: supabase/schemas/catalogue_private/functions/history_model.sql
CREATE OR REPLACE FUNCTION catalogue_private.history_model (
  p_row jsonb
)
  RETURNS text
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select coalesce(p_row->>'model_slug',
    (select model_slug from public.v2_model_provider_routes where provider_model_id=p_row->>'provider_model_id'),
    (select r.model_slug from public.v2_pricing_skus s join public.v2_model_provider_routes r using(provider_model_id) where s.sku_id=(p_row->>'sku_id')::uuid));
$function$;

REVOKE ALL ON FUNCTION "catalogue_private"."history_model"(jsonb) FROM PUBLIC;

-- source: supabase/schemas/catalogue_private/functions/record_row_history.sql
CREATE OR REPLACE FUNCTION catalogue_private.record_row_history()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
begin
  if TG_OP='UPDATE' and to_jsonb(OLD)=to_jsonb(NEW) then return NEW; end if;
  insert into public.v2_catalogue_row_history(table_name,model_slug,operation,actor_user_id,before_state,after_state)
  values(TG_TABLE_NAME,catalogue_private.history_model(coalesce(to_jsonb(NEW),to_jsonb(OLD))),TG_OP,nullif(current_setting('phaseo.catalogue_actor',true),'')::uuid,
    case when TG_OP<>'INSERT' then to_jsonb(OLD) end,case when TG_OP<>'DELETE' then to_jsonb(NEW) end);
  return coalesce(NEW,OLD);
end $function$;

REVOKE ALL ON FUNCTION "catalogue_private"."record_row_history"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/build_mobile_push_digests.sql
CREATE OR REPLACE FUNCTION private.build_mobile_push_digests (
  p_now   timestamp with time zone,
  p_limit integer
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
-- Writes the weekly digest of up to p_limit users once one of their devices has reached 18:00 on
-- Sunday in its own time zone (private.mobile_push_digest_week), and queues it for each of the
-- user's active devices on channel scheme 2 or later; a device in its quiet hours gets it when
-- they end. Recipients have push and the digest category on and own or administer a workspace.
-- Each user gets one digest per ISO week (mobile_push_digests_user_id_iso_week_key); a week with
-- nothing to report is recorded as skipped and sends nothing. 18:00 on Sunday reaches UTC+14 at
-- 04:00 UTC on Sunday, and the window closes at 06:00 on Monday, which UTC-12 reaches at 18:00 UTC
-- on Monday: outside those hours no device can be due and nothing is read. Inside them, one scan
-- of the active devices' time zones finds the due ones, and users already written are skipped
-- through the unique key. Overlapping runs leave building to whichever started first. more is
-- true when p_limit users were taken, so the caller knows others may still be waiting.
declare
  v_into_week interval := (p_now at time zone 'UTC') - date_trunc('week', p_now at time zone 'UTC');
  v_zone text;
  v_week record;
  v_known text[] := '{}';
  v_due_zones text[] := '{}';
  v_due_weeks text[] := '{}';
  v_due_starts timestamp with time zone[] := '{}';
  v_due_cutoffs timestamp with time zone[] := '{}';
  v_candidate record;
  v_facts jsonb;
  v_message jsonb;
  v_lead uuid;
  v_digest uuid;
  v_built integer := 0;
  v_skipped integer := 0;
  v_queued integer := 0;
  v_deferred integer := 0;
  v_taken integer := 0;
begin
  if p_now is null or p_limit is null or p_limit < 1 then
    raise exception 'invalid_mobile_push_digest_build';
  end if;
  if v_into_week >= interval '18 hours' and v_into_week < interval '6 days 4 hours' then
    return jsonb_build_object('built', 0, 'skipped', 0, 'queued', 0, 'deferred', 0, 'more', false);
  end if;
  if not pg_try_advisory_xact_lock(hashtextextended('build_mobile_push_digests', 0)) then
    return jsonb_build_object('built', 0, 'skipped', 0, 'queued', 0, 'deferred', 0, 'more', false);
  end if;

  for v_zone in
    select distinct coalesce(d.time_zone, 'UTC') from public.mobile_push_devices d
    where d.status = 'active' and d.channel_scheme >= 2
  loop
    begin
      select w.* into v_week from private.mobile_push_digest_week(v_zone, p_now) w;
    exception when invalid_parameter_value then
      -- A time zone this database does not know: its devices are never due.
      continue;
    end;
    v_known := v_known || v_zone;
    if v_week.due then
      v_due_zones := v_due_zones || v_zone;
      v_due_weeks := v_due_weeks || v_week.iso_week;
      v_due_starts := v_due_starts || v_week.week_start;
      v_due_cutoffs := v_due_cutoffs || v_week.week_cutoff;
    end if;
  end loop;

  if cardinality(v_due_zones) > 0 then
    for v_candidate in
      -- A user with devices in several due time zones takes the week of the first to reach 18:00.
      select distinct on (d.user_id) d.user_id, z.time_zone, z.iso_week, z.week_start, z.week_cutoff
      from unnest(v_due_zones, v_due_weeks, v_due_starts, v_due_cutoffs) as z(time_zone, iso_week, week_start, week_cutoff)
      join public.mobile_push_devices d
        on coalesce(d.time_zone, 'UTC') = z.time_zone and d.status = 'active' and d.channel_scheme >= 2
      join public.mobile_notification_preferences p on p.user_id = d.user_id
      where p.enabled
        and (p.categories -> 'digest') is distinct from 'false'::jsonb
        and not exists (select 1 from public.mobile_push_digests g where g.user_id = d.user_id and g.iso_week = z.iso_week)
        and (
          exists (select 1 from public.workspace_members m where m.user_id = d.user_id and m.role::text in ('owner', 'admin'))
          or exists (select 1 from public.workspaces w where w.owner_user_id = d.user_id)
        )
      order by d.user_id, z.week_cutoff, d.created_at, d.id
      limit p_limit
    loop
      v_taken := v_taken + 1;
      v_facts := private.mobile_push_digest_facts(v_candidate.user_id, v_candidate.week_start, v_candidate.week_cutoff, v_candidate.time_zone);
      v_lead := (v_facts -> 'lead' ->> 'id')::uuid;
      v_message := case when v_lead is not null then private.mobile_push_digest_message(v_facts) end;
      v_digest := null;

      insert into public.mobile_push_digests as g
        (user_id, iso_week, time_zone, week_start, week_cutoff, status, workspace_id, title, body, href, summary, created_at)
      values (
        v_candidate.user_id, v_candidate.iso_week, v_candidate.time_zone, v_candidate.week_start, v_candidate.week_cutoff,
        case when v_message is null then 'skipped' else 'queued' end,
        v_lead,
        v_message ->> 'title',
        v_message ->> 'body',
        case when v_message is not null then '/account/week?workspace=' || v_lead || '&week=' || v_candidate.iso_week end,
        v_facts,
        p_now
      )
      on conflict (user_id, iso_week) do nothing
      returning g.id into v_digest;

      -- Another run wrote this user's digest first.
      continue when v_digest is null;
      if v_message is null then
        v_skipped := v_skipped + 1;
        continue;
      end if;
      v_built := v_built + 1;

      with inserted as (
        insert into public.mobile_push_deliveries as x (event_id, digest_id, workspace_id, device_id, user_id, status, not_before, created_at)
        select
          null,
          v_digest,
          v_lead,
          d.id,
          d.user_id,
          case when quiet.release_local is null then 'pending' else 'deferred' end,
          coalesce(quiet.release_local at time zone coalesce(d.time_zone, 'UTC'), p_now),
          p_now
        from public.mobile_push_devices d
        join public.mobile_notification_preferences p on p.user_id = d.user_id
        cross join lateral (select p_now at time zone coalesce(d.time_zone, 'UTC') as moment) here
        cross join lateral (select here.moment::time as clock_time, here.moment::date as calendar_day) wall
        cross join lateral (
          select case
            when p.quiet_start is null or p.quiet_end is null or p.quiet_start = p.quiet_end then null
            when p.quiet_start < p.quiet_end then
              case when wall.clock_time >= p.quiet_start and wall.clock_time < p.quiet_end then wall.calendar_day + p.quiet_end end
            when wall.clock_time >= p.quiet_start then (wall.calendar_day + 1) + p.quiet_end
            when wall.clock_time < p.quiet_end then wall.calendar_day + p.quiet_end
          end as release_local
        ) quiet
        where d.user_id = v_candidate.user_id and d.status = 'active' and d.channel_scheme >= 2
          and coalesce(d.time_zone, 'UTC') = any (v_known)
        on conflict do nothing
        returning x.status
      )
      select v_queued + count(*) filter (where i.status = 'pending'), v_deferred + count(*) filter (where i.status = 'deferred')
      into v_queued, v_deferred
      from inserted i;
    end loop;
  end if;

  return jsonb_build_object('built', v_built, 'skipped', v_skipped, 'queued', v_queued, 'deferred', v_deferred, 'more', v_taken >= p_limit);
end;
$function$;

REVOKE ALL ON FUNCTION "private"."build_mobile_push_digests"(timestamp with time zone, integer) FROM PUBLIC;

-- source: supabase/schemas/private/functions/capture_gateway_workspace_publication.sql
CREATE OR REPLACE FUNCTION private.capture_gateway_workspace_publication()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  old_row jsonb;
  new_row jsonb;
  target uuid;
begin
  if tg_op <> 'INSERT' then old_row := to_jsonb(old); end if;
  if tg_op <> 'DELETE' then new_row := to_jsonb(new); end if;
  -- Advisory BYOK usage updates must never create publication traffic.
  if tg_op = 'UPDATE' and
    (old_row - array['updated_at','last_used_at']) is not distinct from
    (new_row - array['updated_at','last_used_at']) then return null; end if;
  for target in
    select distinct id from (
      select case
        when tg_table_name = 'workspaces' then (r->>'id')::uuid
        when tg_table_name = 'key_guardrails' then
          (select g.workspace_id from public.workspace_guardrails g where g.id = (r->>'guardrail_id')::uuid)
        when tg_table_name = 'gateway_dynamic_route_keys' then
          (select d.workspace_id from public.gateway_dynamic_routes d where d.id = (r->>'route_id')::uuid)
        else (r->>'workspace_id')::uuid end as id
      from (values(old_row),(new_row)) rows(r) where r is not null
    ) targets where id is not null order by id
  loop
    perform private.enqueue_gateway_workspace_publication(target);
  end loop;
  return null;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."capture_gateway_workspace_publication"() FROM PUBLIC;

