-- source: supabase/schemas/private/functions/capture_workspace_notification_events.sql
CREATE OR REPLACE FUNCTION private.capture_workspace_notification_events (
  p_limit integer
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
-- Turns new workspace events into push events (workspace_notification_events), one per dedupe key:
--   email_outbox            auto_top_up_failed, payment_method_expiring, spend_alert and
--                           spend_blocked (money; a spend alert or block also reaches the scoped
--                           key's creator, or the member of a member rule, through key_created_by),
--                           model_deprecation (deprecations), model_substitution and
--                           rate_limit_throttled (traffic), and security_leaked_key (security; one
--                           per exposed key, though the email has a row per recipient, with the
--                           API or management key's creator as a recipient)
--   workspace_audit_events  api_key.created, .rotated, .deleted, .paused and .resumed (security),
--                           except for the web chat's managed key
-- Each source is read from its cursor, in (created_at, id) order, up to p_limit rows per source:
--   * normally from ten minutes before the previous complete read up to the start of this call,
--     so a row whose transaction commits a little late is still read, and reading the overlap
--     again adds nothing;
--   * after a read cut short by p_limit, from just after its last row (a keyset position), so
--     each call moves on even when the overlap alone holds more than p_limit rows.
-- Nothing older than two days is read, and the first call only sets the cursors.
-- Low balance emails are not read: sweep_low_balance_pushes pushes low balance once per drop
-- whatever the email setting, so an email row is never a second push. The email is unchanged.
declare
  v_uuid constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_now timestamptz := now();
  v_cursor public.workspace_notification_cursors%rowtype;
  v_from timestamptz;
  v_from_id uuid;
  v_last timestamptz;
  v_last_id uuid;
  v_read integer;
  v_row record;
  v_inserted integer;
  v_captured integer := 0;
begin
  if p_limit is null or p_limit < 1 then
    raise exception 'invalid_workspace_notification_capture_limit';
  end if;

  select c.* into v_cursor from public.workspace_notification_cursors c where c.source = 'email_outbox' for update;
  if v_cursor.source is null then
    insert into public.workspace_notification_cursors (source, read_until) values ('email_outbox', v_now) on conflict (source) do nothing;
  else
    v_read := 0;
    v_from := coalesce(v_cursor.resume_created_at, v_cursor.read_until - interval '10 minutes');
    v_from_id := coalesce(v_cursor.resume_id, '00000000-0000-0000-0000-000000000000'::uuid);
    for v_row in
      select o.id, o.created_at, o.kind, o.workspace_id, o.payload
      from public.email_outbox o
      where (o.created_at, o.id) > (v_from, v_from_id)
        and o.created_at > v_now - interval '2 days'
        and o.created_at <= v_now
        and o.kind in ('auto_top_up_failed', 'payment_method_expiring', 'model_deprecation', 'model_substitution',
          'rate_limit_throttled', 'security_leaked_key', 'spend_alert', 'spend_blocked')
        and o.workspace_id is not null
      order by o.created_at, o.id
      limit p_limit
    loop
      v_read := v_read + 1;
      v_last := v_row.created_at;
      v_last_id := v_row.id;

      insert into public.workspace_notification_events (workspace_id, kind, category, dedupe_key, key_id, key_created_by, payload, occurred_at)
      select
        v_row.workspace_id,
        v_row.kind,
        case
          when v_row.kind in ('auto_top_up_failed', 'payment_method_expiring', 'spend_alert', 'spend_blocked') then 'money'
          when v_row.kind = 'model_deprecation' then 'deprecations'
          when v_row.kind = 'security_leaked_key' then 'security'
          else 'traffic'
        end,
        case
          when v_row.kind = 'security_leaked_key' then 'security_leaked_key:' || v_row.workspace_id || ':'
            || coalesce(v_row.payload ->> 'key_id', v_row.payload ->> 'key_preview', v_row.payload ->> 'key_name', '') || ':' || extract(epoch from v_row.created_at)
          else 'email_outbox:' || v_row.id
        end,
        coalesce(k.id, mk.id),
        coalesce(k.created_by, mk.created_by,
          case when v_row.kind in ('spend_alert', 'spend_blocked') and v_row.payload #>> '{scope,type}' = 'member' and v_row.payload #>> '{scope,user_id}' ~* v_uuid
            then (v_row.payload #>> '{scope,user_id}')::uuid end),
        v_row.payload - 'user_first_name',
        v_row.created_at
      from (select 1) one
      left join public.keys k
        on k.workspace_id = v_row.workspace_id
        and ((v_row.kind = 'security_leaked_key' and coalesce(v_row.payload ->> 'key_type', 'api_key') = 'api_key'
            and k.id = case when v_row.payload ->> 'key_id' ~* v_uuid then (v_row.payload ->> 'key_id')::uuid end)
          or (v_row.kind in ('spend_alert', 'spend_blocked') and v_row.payload #>> '{scope,type}' = 'key'
            and k.id = case when v_row.payload #>> '{scope,key_id}' ~* v_uuid then (v_row.payload #>> '{scope,key_id}')::uuid end))
      left join public.management_keys mk
        on v_row.kind = 'security_leaked_key' and v_row.payload ->> 'key_type' = 'management_key'
        and mk.workspace_id = v_row.workspace_id
        and mk.id = case when v_row.payload ->> 'key_id' ~* v_uuid then (v_row.payload ->> 'key_id')::uuid end
      on conflict (dedupe_key) do nothing;
      get diagnostics v_inserted = row_count;
      v_captured := v_captured + v_inserted;
    end loop;

    -- A full page leaves a keyset position to carry on from; a short one completes the read.
    update public.workspace_notification_cursors
    set read_until = case when v_read < p_limit then v_now else read_until end,
        resume_created_at = case when v_read < p_limit then null else v_last end,
        resume_id = case when v_read < p_limit then null else v_last_id end,
        updated_at = v_now
    where source = 'email_outbox';
  end if;

  select c.* into v_cursor from public.workspace_notification_cursors c where c.source = 'workspace_audit_events' for update;
  if v_cursor.source is null then
    insert into public.workspace_notification_cursors (source, read_until) values ('workspace_audit_events', v_now) on conflict (source) do nothing;
  else
    v_read := 0;
    v_from := coalesce(v_cursor.resume_created_at, v_cursor.read_until - interval '10 minutes');
    v_from_id := coalesce(v_cursor.resume_id, '00000000-0000-0000-0000-000000000000'::uuid);
    for v_row in
      select a.id, a.created_at, a.workspace_id, a.actor_user_id, a.action, a.target_id, a.target_name, a.metadata
      from public.workspace_audit_events a
      where a.target_type = 'api_key'
        and (a.created_at, a.id) > (v_from, v_from_id)
        and a.created_at > v_now - interval '2 days'
        and a.created_at <= v_now
        and a.action in ('api_key.created', 'api_key.rotated', 'api_key.deleted', 'api_key.paused', 'api_key.resumed')
      order by a.created_at, a.id
      limit p_limit
    loop
      v_read := v_read + 1;
      v_last := v_row.created_at;
      v_last_id := v_row.id;

      insert into public.workspace_notification_events (workspace_id, kind, category, dedupe_key, actor_user_id, key_id, key_created_by, payload, occurred_at)
      select
        v_row.workspace_id,
        replace(v_row.action, '.', '_'),
        'security',
        'workspace_audit_events:' || v_row.id,
        v_row.actor_user_id,
        coalesce(k.id, case when v_row.target_id ~* v_uuid then v_row.target_id::uuid end),
        k.created_by,
        jsonb_strip_nulls(jsonb_build_object(
          'key_name', coalesce(nullif(btrim(v_row.target_name), ''), k.name),
          'actor_name', (
            select left(coalesce(nullif(btrim(u.display_name), ''), nullif(btrim(au.raw_user_meta_data ->> 'full_name'), ''),
              nullif(btrim(au.raw_user_meta_data ->> 'name'), ''), nullif(split_part(au.email, '@', 1), '')), 40)
            from auth.users au
            left join public.users u on u.user_id = au.id
            where au.id = v_row.actor_user_id
          ),
          'app_name', v_row.metadata ->> 'appName',
          'replacement_key_name', coalesce(v_row.metadata ->> 'replacementKeyName', v_row.metadata ->> 'replacement_key_name'),
          'previous_key_expires_at', coalesce(v_row.metadata ->> 'previousKeyExpiresAt', v_row.metadata ->> 'previous_key_expires_at')
        )),
        v_row.created_at
      from (select 1) one
      left join public.keys k
        on k.workspace_id = v_row.workspace_id
        and k.id = case when v_row.target_id ~* v_uuid then v_row.target_id::uuid end
      where coalesce(k.name, v_row.target_name, '') <> '__chat_route_managed_key__'
      on conflict (dedupe_key) do nothing;
      get diagnostics v_inserted = row_count;
      v_captured := v_captured + v_inserted;
    end loop;

    -- A full page leaves a keyset position to carry on from; a short one completes the read.
    update public.workspace_notification_cursors
    set read_until = case when v_read < p_limit then v_now else read_until end,
        resume_created_at = case when v_read < p_limit then null else v_last end,
        resume_id = case when v_read < p_limit then null else v_last_id end,
        updated_at = v_now
    where source = 'workspace_audit_events';
  end if;

  return jsonb_build_object('captured', v_captured);
end;
$function$;

REVOKE ALL ON FUNCTION "private"."capture_workspace_notification_events"(integer) FROM PUBLIC;

-- source: supabase/schemas/private/functions/catalogue_notification_usd.sql
CREATE OR REPLACE FUNCTION private.catalogue_notification_usd (
  p_amount numeric
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  -- Plain dollar amounts for notification text: $15, $2.50, $0.28, $0.075.
  select '$' || case
    when p_amount is null then '?'
    when p_amount = trunc(p_amount) then trunc(p_amount)::text
    when round(p_amount, 2) = p_amount then to_char(p_amount, 'FM999999999990.00')
    else trim_scale(round(p_amount, 8))::text
  end;
$function$;

REVOKE ALL ON FUNCTION "private"."catalogue_notification_usd"(numeric) FROM PUBLIC;

-- source: supabase/schemas/private/functions/department_budget_key_departments.sql
CREATE OR REPLACE FUNCTION private.department_budget_key_departments (
  p_workspace_id uuid
)
  RETURNS TABLE (
    key_id        uuid,
    department_id uuid
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  -- The API keys whose cost counts toward each department that has a budget in the workspace,
  -- one row per key and department. A department's keys are the keys linked to it
  -- (keys.department_id), plus, for keys not linked to any department, the keys its members
  -- created and their OAuth keys (OAuth requests use the user's delegated key). A member's
  -- departments are their directory override when one is enabled, otherwise every department
  -- grant, or with workspace_settings.department_spend_attribution = 'primary' only the grant
  -- spend_scope_departments picks (the primary one, then manual over SCIM, then the oldest).
  -- The gateway's department rate limits count members the same way.
  -- Shared by workspace_department_budget_status (alerts) and gateway_spend_limit_seed (blocking).
  with budgeted as (
    select distinct b.department_id
    from public.workspace_department_budgets b
    where b.workspace_id = p_workspace_id
  ),
  overrides as (
    select o.user_id, o.department_id
    from public.workspace_member_overrides o
    where o.workspace_id = p_workspace_id
      and o.department_override_enabled
  ),
  primary_only as (
    select coalesce((
      select s.department_spend_attribution = 'primary'
      from public.workspace_settings s
      where s.workspace_id = p_workspace_id
    ), false) as value
  ),
  ranked_grants as (
    select g.user_id, g.department_id,
      row_number() over (
        partition by g.user_id
        order by g.is_primary desc, (g.source_type = 'manual') desc, g.created_at, g.department_id
      ) as rank
    from public.workspace_department_grants g
    where g.workspace_id = p_workspace_id
      and not exists (select 1 from overrides o where o.user_id = g.user_id)
  ),
  member_departments as (
    select g.user_id, g.department_id
    from ranked_grants g, primary_only
    where not primary_only.value or g.rank = 1
    union
    select o.user_id, o.department_id from overrides o where o.department_id is not null
  )
  select k.id, k.department_id
  from public.keys k
  where k.workspace_id = p_workspace_id
    and k.department_id in (select budgeted.department_id from budgeted)
  union
  select k.id, m.department_id
  from public.keys k
  join member_departments m on m.user_id = coalesce(k.oauth_user_id, k.created_by)
  where k.workspace_id = p_workspace_id
    and k.department_id is null
    and m.department_id in (select budgeted.department_id from budgeted);
$function$;

COMMENT ON FUNCTION "private"."department_budget_key_departments"(uuid) IS 'API keys counting toward each budgeted department of a workspace: keys linked to the department, plus unlinked keys created by (or OAuth-delegated to) its members. Members'' departments are their directory override when enabled, else their grants (only the primary one when workspace_settings.department_spend_attribution is primary).';

REVOKE ALL ON FUNCTION "private"."department_budget_key_departments"(uuid) FROM PUBLIC;

-- source: supabase/schemas/private/functions/drain_provider_health_refresh.sql
CREATE OR REPLACE FUNCTION private.drain_provider_health_refresh (
  p_limit integer DEFAULT 25
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  item record;
  provider_value text;
  completed integer := 0;
  completed_keys jsonb := '[]'::jsonb;
  failed_keys jsonb := '[]'::jsonb;
  started_at timestamptz := clock_timestamp();
begin
  -- Only workers take this lock. Ingestion never waits for a reporting scan.
  if not pg_try_advisory_xact_lock(hashtextextended('provider_health_refresh_worker', 0)) then return 0; end if;
  for item in select * from private.provider_health_refresh_queue
    where retry_after <= clock_timestamp()
    order by retry_after, usage_date, model_slug, provider_model_id
    limit greatest(1, least(coalesce(p_limit, 25), 25))
  loop
    exit when clock_timestamp() - started_at > interval '5 seconds';
    begin
      select provider_slug into provider_value from public.v2_model_provider_routes
        where provider_model_id = item.provider_model_id;
      -- Remove old provider-slug rows as well when route metadata was corrected.
      delete from public.v2_public_provider_health_daily
        where usage_date = item.usage_date and model_slug = item.model_slug
          and provider_model_id = item.provider_model_id;
      if provider_value is not null then
        insert into public.v2_public_provider_health_daily (
          usage_date, model_slug, provider_model_id, provider_slug, request_count,
          successful_request_count, attempt_count, successful_attempts, failed_attempts,
          fallback_attempts, latency_sum_ms, latency_count, updated_at
        )
        select item.usage_date, item.model_slug, item.provider_model_id, provider_value,
          count(distinct fact.request_event_id), count(distinct fact.request_event_id) filter (where attempt.success),
          count(*), count(*) filter (where attempt.success), count(*) filter (where not attempt.success),
          count(*) filter (where attempt.attempt_number > 1),
          coalesce(sum(attempt.latency_ms), 0), count(attempt.latency_ms), clock_timestamp()
        from public.reporting_request_facts fact
        join public.v2_request_attempts attempt on attempt.request_event_id = fact.request_event_id
        where fact.occurred_at >= item.usage_date::timestamptz
          and fact.occurred_at < (item.usage_date + 1)::timestamptz
          and (fact.routed_model_slug = item.model_slug
            or (fact.routed_model_slug is null and fact.requested_model_slug = item.model_slug))
          and attempt.provider_model_id = item.provider_model_id
        having count(*) > 0;
      end if;
      completed_keys := completed_keys || jsonb_build_array(jsonb_build_object(
        'usage_date', item.usage_date, 'model_slug', item.model_slug,
        'provider_model_id', item.provider_model_id, 'generation', item.generation));
      completed := completed + 1;
    exception when query_canceled or lock_not_available or others then
      failed_keys := failed_keys || jsonb_build_array(jsonb_build_object(
        'usage_date', item.usage_date, 'model_slug', item.model_slug,
        'provider_model_id', item.provider_model_id, 'error_code', sqlstate));
    end;
  end loop;
  -- Acknowledge only after ALL scans. Earlier deletions would hold queue row
  -- locks across later scans and make new ingestion wait for reporting again.
  delete from private.provider_health_refresh_queue queue
  using jsonb_to_recordset(completed_keys) as done(
    usage_date date, model_slug text, provider_model_id text, generation bigint)
  where queue.usage_date = done.usage_date and queue.model_slug = done.model_slug
    and queue.provider_model_id = done.provider_model_id and queue.generation = done.generation;
  update private.provider_health_refresh_queue queue
    set retry_after = clock_timestamp() + interval '5 minutes', last_error_code = failed.error_code
  from jsonb_to_recordset(failed_keys) as failed(
    usage_date date, model_slug text, provider_model_id text, error_code text)
  where queue.usage_date = failed.usage_date and queue.model_slug = failed.model_slug
    and queue.provider_model_id = failed.provider_model_id;
  return completed;
end;
$function$;

GRANT EXECUTE ON FUNCTION "private"."drain_provider_health_refresh"(integer) TO "service_role";

REVOKE ALL ON FUNCTION "private"."drain_provider_health_refresh"(integer) FROM PUBLIC;

-- source: supabase/schemas/private/functions/drain_public_reporting_refresh.sql
CREATE OR REPLACE FUNCTION private.drain_public_reporting_refresh()
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare item record;
begin
  if not pg_try_advisory_xact_lock(hashtextextended('public-reporting-refresh-worker',0)) then return 0; end if;
  select q.report,q.bucket_start,array_agg(q.generation) as generations into item
  from private.public_reporting_refresh_queue q
  where not exists(select 1 from private.public_reporting_refresh_backoff b
    where b.report=q.report and b.bucket_start=q.bucket_start and b.retry_after>clock_timestamp())
  group by q.report,q.bucket_start order by min(q.requested_at),q.report,q.bucket_start limit 1;
  if not found then return 0; end if;
  begin
    if item.report='users_daily' then
      perform public.refresh_public_model_user_usage_daily(
        item.bucket_start::timestamp at time zone 'utc',(item.bucket_start+1)::timestamp at time zone 'utc');
    else
      perform public.refresh_public_model_workspace_usage_weekly(
        item.bucket_start::timestamp at time zone 'utc',(item.bucket_start+7)::timestamp at time zone 'utc');
    end if;
  exception when query_canceled or lock_not_available or others then
    insert into private.public_reporting_refresh_backoff values
      (item.report,item.bucket_start,clock_timestamp()+interval '2 hours',sqlstate)
    on conflict(report,bucket_start) do update set retry_after=excluded.retry_after,last_error_code=excluded.last_error_code;
    update private.public_reporting_refresh_queue
    set retry_after=clock_timestamp()+interval '2 hours',last_error_code=sqlstate
    where generation=any(item.generations);
    return 0;
  end;
  -- Capture exact visible IDs, not a sequence cutoff: an older sequence value
  -- can belong to a transaction that commits AFTER the source scan.
  delete from private.public_reporting_refresh_queue where generation=any(item.generations);
  delete from private.public_reporting_refresh_backoff where report=item.report and bucket_start=item.bucket_start;
  return 1;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."drain_public_reporting_refresh"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/enforce_workspace_enterprise_member_capacity.sql
CREATE OR REPLACE FUNCTION private.enforce_workspace_enterprise_member_capacity()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_member_limit integer;
  v_member_count bigint;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('enterprise-member-limit:' || new.workspace_id::text, 0)
  );

  if exists (
    select 1 from public.workspace_members member
    where member.workspace_id = new.workspace_id and member.user_id = new.user_id
  ) then return new; end if;

  select subscription.included_members into v_member_limit
  from public.workspace_addon_subscriptions subscription
  where subscription.workspace_id = new.workspace_id
    and subscription.addon_key = 'identity'
    and subscription.included_members < 100000
    and (
      subscription.status in ('active', 'trialing')
      or (subscription.status = 'past_due' and subscription.grace_until > pg_catalog.now())
    );

  if v_member_limit is null then return new; end if;

  select pg_catalog.count(*) into v_member_count
  from public.workspace_members member where member.workspace_id = new.workspace_id;

  if v_member_count >= v_member_limit then
    raise exception using errcode = '23514', message = 'workspace_enterprise_member_limit_reached';
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."enforce_workspace_enterprise_member_capacity"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/enforce_workspace_enterprise_subscription_capacity.sql
CREATE OR REPLACE FUNCTION private.enforce_workspace_enterprise_subscription_capacity()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('enterprise-member-limit:' || new.workspace_id::text, 0)
  );
  if new.addon_key = 'identity' and new.included_members < 100000
    and (new.status in ('active', 'trialing')
      or (new.status = 'past_due' and new.grace_until > pg_catalog.now()))
    and (select pg_catalog.count(*) from public.workspace_members member
      where member.workspace_id = new.workspace_id) > new.included_members then
    raise exception using errcode = '23514', message = 'workspace_enterprise_member_limit_reached';
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION private.enforce_workspace_enterprise_subscription_capacity() FROM PUBLIC;

