-- source: supabase/schemas/private/functions/enqueue_provider_health_for_fact.sql
CREATE OR REPLACE FUNCTION private.enqueue_provider_health_for_fact()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare provider_value text;
begin
  if tg_op = 'UPDATE' and old.occurred_at::date is not distinct from new.occurred_at::date
    and coalesce(old.routed_model_slug, old.requested_model_slug) is not distinct from
        coalesce(new.routed_model_slug, new.requested_model_slug) then
    return new;
  end if;
  for provider_value in select distinct provider_model_id from public.v2_request_attempts
    where request_event_id = old.request_event_id and provider_model_id is not null
    order by provider_model_id
  loop
    perform private.enqueue_provider_health_refresh(old.occurred_at::date,
      coalesce(old.routed_model_slug, old.requested_model_slug), provider_value);
    if tg_op = 'UPDATE' then
      perform private.enqueue_provider_health_refresh(new.occurred_at::date,
        coalesce(new.routed_model_slug, new.requested_model_slug), provider_value);
    end if;
  end loop;
  if tg_op = 'UPDATE' then return new; end if;
  return old;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."enqueue_provider_health_for_fact"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/enqueue_provider_health_refresh.sql
CREATE OR REPLACE FUNCTION private.enqueue_provider_health_refresh (
  p_date     date,
  p_model    text,
  p_provider text
)
  RETURNS void
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  insert into private.provider_health_refresh_queue (usage_date, model_slug, provider_model_id)
  select p_date, p_model, p_provider
  where p_date is not null and p_model is not null and p_provider is not null
  on conflict (usage_date, model_slug, provider_model_id) do update
    set generation = excluded.generation, requested_at = excluded.requested_at;
$function$;

REVOKE ALL ON FUNCTION "private"."enqueue_provider_health_refresh"(date, text, text) FROM PUBLIC;

-- source: supabase/schemas/private/functions/enqueue_public_reporting_for_fact.sql
CREATE OR REPLACE FUNCTION private.enqueue_public_reporting_for_fact()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if tg_op = 'UPDATE' and old is not distinct from new then return new; end if;
  if tg_op <> 'INSERT' then
    perform private.enqueue_public_reporting_refresh(old.occurred_at);
  end if;
  if tg_op <> 'DELETE' then
    if tg_op = 'INSERT' or new.occurred_at is distinct from old.occurred_at then
      perform private.enqueue_public_reporting_refresh(new.occurred_at);
    end if;
    return new;
  end if;
  return old;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."enqueue_public_reporting_for_fact"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/enqueue_public_reporting_for_request.sql
CREATE OR REPLACE FUNCTION private.enqueue_public_reporting_for_request()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if row(old.api_model_id, old.pricing_plan, old.is_free_variant)
    is distinct from row(new.api_model_id, new.pricing_plan, new.is_free_variant) then
    perform private.enqueue_public_reporting_refresh(f.occurred_at)
    from public.v2_request_facts f
    where f.gateway_request_id = new.id and f.gateway_request_created_at = new.created_at;
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."enqueue_public_reporting_for_request"() FROM PUBLIC;

