-- source: supabase/schemas/private/functions/enqueue_public_reporting_refresh.sql
CREATE OR REPLACE FUNCTION private.enqueue_public_reporting_refresh (
  p_occurred_at timestamp with time zone
)
  RETURNS void
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  insert into private.public_reporting_refresh_queue as queue(report,bucket_start)
  select 'users_daily',(p_occurred_at at time zone 'utc')::date where p_occurred_at is not null and coalesce(current_setting('phaseo.pruning_byok_metadata', true), '') <> 'on'
  union all
  select 'workspaces_weekly',date_trunc('week',p_occurred_at at time zone 'utc')::date where p_occurred_at is not null and coalesce(current_setting('phaseo.pruning_byok_metadata', true), '') <> 'on'
  on conflict(report,bucket_start,signal_shard) do update
  set generation=excluded.generation,transaction_id=excluded.transaction_id,requested_at=excluded.requested_at
  -- At most one update per period per ingestion transaction. 64 lanes spread
  -- concurrent transactions instead of serializing all writes on two tuples.
  where queue.transaction_id<>excluded.transaction_id;
$function$;

REVOKE ALL ON FUNCTION "private"."enqueue_public_reporting_refresh"(timestamp WITH time zone) FROM PUBLIC;

-- source: supabase/schemas/private/functions/enqueue_v2_analytics_correction.sql
CREATE OR REPLACE FUNCTION private.enqueue_v2_analytics_correction (
  p_request_event_id uuid
)
  RETURNS void
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  insert into public.v2_analytics_outbox as outbox
    (request_event_id,workspace_id,occurred_at,status,attempt_count,available_at,last_error,updated_at)
  select request_event_id,workspace_id,occurred_at,'pending',0,now(),null,now()
  from public.v2_request_facts where request_event_id=p_request_event_id and coalesce(current_setting('phaseo.pruning_byok_metadata', true), '') <> 'on'
  on conflict(request_event_id) do update set workspace_id=excluded.workspace_id,
    occurred_at=excluded.occurred_at,status='pending',attempt_count=0,
    available_at=now(),last_error=null,updated_at=now()
  where outbox.status<>'pending' or outbox.workspace_id is distinct from excluded.workspace_id
    or outbox.occurred_at is distinct from excluded.occurred_at;
$function$;

REVOKE ALL ON FUNCTION "private"."enqueue_v2_analytics_correction"(uuid) FROM PUBLIC;

-- source: supabase/schemas/private/functions/enqueue_v2_analytics_fact_correction.sql
CREATE OR REPLACE FUNCTION private.enqueue_v2_analytics_fact_correction()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if coalesce(current_setting('phaseo.pruning_byok_metadata',true),'')='on' then
    if tg_op='DELETE' then return old; end if;
    return new;
  end if;
  -- Queue the old hour even without a model slug: the usage overview rebuilds whole
  -- workspace hours and counts requests that only name their input model.
  if (tg_op='DELETE' or row(old.workspace_id,date_trunc('hour',old.occurred_at at time zone 'utc'),old.app_id,
    coalesce(old.routed_model_slug,old.requested_model_slug),old.provider_model_id,old.cloudflare_colo)
    is distinct from row(new.workspace_id,date_trunc('hour',new.occurred_at at time zone 'utc'),new.app_id,
    coalesce(new.routed_model_slug,new.requested_model_slug),new.provider_model_id,new.cloudflare_colo)) then
    insert into private.v2_analytics_previous_grains as queued(workspace_id,occurred_at,app_id,model_slug,provider_model_id,cloudflare_colo)
    values(old.workspace_id,date_trunc('hour',old.occurred_at at time zone 'utc') at time zone 'utc',old.app_id,
      coalesce(old.routed_model_slug,old.requested_model_slug),old.provider_model_id,old.cloudflare_colo)
    on conflict(workspace_id,occurred_at,app_id,model_slug,provider_model_id,cloudflare_colo) do update
    set grain_id=excluded.grain_id,transaction_id=excluded.transaction_id
    where queued.transaction_id<>excluded.transaction_id;
  end if;
  if tg_op='DELETE' then return old; end if;
  if old is distinct from new then perform private.enqueue_v2_analytics_correction(new.request_event_id); end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."enqueue_v2_analytics_fact_correction"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/enqueue_v2_analytics_meter_correction.sql
CREATE OR REPLACE FUNCTION private.enqueue_v2_analytics_meter_correction()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if tg_op<>'INSERT' then perform private.enqueue_v2_analytics_correction(old.request_event_id); end if;
  if tg_op<>'DELETE' then
    if tg_op='INSERT' or new.request_event_id is distinct from old.request_event_id then
      perform private.enqueue_v2_analytics_correction(new.request_event_id);
    end if;
    return new;
  end if;
  return old;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."enqueue_v2_analytics_meter_correction"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/evaluate_workspace_spend_rules.sql
CREATE OR REPLACE FUNCTION private.evaluate_workspace_spend_rules (
  p_workspace_id uuid,
  p_now          timestamp with time zone,
  p_blocks       boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Evaluates a workspace's enabled spend rules at p_now, queues an alert for each rule that
-- crossed a threshold, and starts or lifts the blocks of rules with action = 'block'.
--   * Rules: private.spend_rule_evaluable (spend, budget_percent and forecast over a calendar day,
--     Monday week or month; spend and budget_percent over a rolling window; balance and spike
--     rules). Each calendar rule's period is in its own time zone, or the
--     workspace's billing_time_zone (private.spend_rule_period).
--   * Spend: v2_private_usage_15m from the period (or window) start up to p_now, plus successful async jobs
--     and realtime sessions from gateway_requests (as sweep_spend_limit_warnings adds them).
--     The rollup is read as it stands: hours the outbox has yet to rebuild count once it marks
--     the workspace dirty again. Values come from private.spend_rule_values and the text from
--     private.spend_rule_alert_text, which the API preview and test sends share.
--   * Scopes: workspace; key (key_id); member (actor_user_id: their keys and OAuth requests);
--     department (private.spend_scope_departments, read now, so moving someone moves their
--     spend for the current period); model (model_id); provider (the route's provider_slug,
--     or gateway_requests.provider for async jobs).
--   * Bases for budget_percent and forecast: amount (base_amount_nanos), workspace_budget (the
--     workspace_budgets row for base_ref), key_limit (the key's *_limit_cost_nanos) and
--     previous_period (spend at the same point in the previous period, the window before a
--     rolling one, or the whole previous period for a forecast). A rule whose base is missing
--     or 0 does not fire.
--   * Forecast: projected period-end spend (private.spend_rule_values: the usage dashboard's
--     straight line from the period start, ready 3 hours into a day, 24 into a week and 72 into
--     a month) against threshold_amount_nanos or threshold_percents of the base. It fires only
--     once the projection is ready and at least a cent has been spent this period.
--   * Firing: each threshold at most once per period. Several crossed at once make one event
--     naming the highest. A spend rule fires once per period at threshold_amount_nanos.
--     Rolling rules use cooldown_minutes instead (state row period_start '-infinity'): while
--     over a threshold they fire again once the cooldown since the last alert ends, and within
--     it only for a higher threshold.
--   * Each event is an email_outbox row of kind spend_alert, deduped by
--     spend_alert:<rule id>:<period start, UTC ISO>:<threshold percent, amount-<nanos>,
--     projected-<percent> or projected-amount-<nanos>> (rolling rules:
--     spend_alert:<rule id>:cooldown:<epoch / cooldown>:<threshold>), with
--     its text in payload.title / payload.message and a payload.push for the mobile app. The
--     routed delivery job sends it to the rule's destinations, or else the workspace's
--     spend_alert routes; mobile push picks it up as a money push.
--   * workspace_spend_rule_state is written only when a rule fires, or for the first evaluation
--     in a period (the rollover row), never on a quiet re-evaluation.
--   * Blocks (grace margin): a block rule's block point is block_at_amount_nanos (spend rules) or
--     block_at_percent of the base (budget_percent rules). Once spend this period reaches it, a
--     workspace_spend_blocks row starts, unless the rule already has an active block or an
--     admin lifted one manually this period (a manual lift holds until the period resets, or
--     for one window of a rolling rule). A rolling rule's block has no reset (resets_at null)
--     and lifts once spend over the window is below the block point.
--     Blocks start only when p_blocks is true (SPEND_RULE_BLOCKS_ENABLED) and p_now is within
--     15 minutes of the database clock, so a late or replayed evaluation never starts one; a
--     failed evaluation rolls back. Active blocks are lifted, whatever p_blocks says, when the
--     period resets (period_reset), spend is below the block point again, for example because
--     the budget was raised (below_limit, or rule_changed when the rule was edited since the
--     block started), or the rule was deleted, disabled or no longer blocks (rule_deleted,
--     rule_disabled, rule_changed; the rule-change trigger usually lifts these first). An active
--     block whose rule stopped or started covering free models takes the rule's setting.
--     Each start and lift queues a spend_blocked event (private.queue_spend_block_event).
--   * Balance rules (workspace scope, rolling): values from private.spend_balance_rule_values
--     (available balance = balance - reserved, as the gateway admits requests; burn over
--     window_hours from the rollup plus async jobs; runway = available / burn per day). A rule is
--     low when the balance is at or below threshold_amount_nanos or the runway at or below
--     runway_days. Armed/unarmed, as the low-balance push and email: one state row
--     (period_start '-infinity'), armed until a drop. Found armed and low, that is a drop: one
--     alert, unless the last one was within cooldown_minutes (then it stays armed and fires once
--     the cooldown ends, if still low) or auto top-up is working
--     (private.workspace_auto_top_up_covers; the drop is recorded unarmed without an alert). It
--     re-arms once neither threshold holds. Dedupe:
--     spend_alert:<rule id>:cooldown:<epoch / cooldown>:<balance|runway>. The state row is written
--     only when armed changes or the rule fires.
--   * Spike rules (rolling; never block): values from private.spend_spike_rule_values (spend over
--     the last window_hours in the rule's scope against the median of the same window over the
--     previous 7 days; ready once the workspace spent in at least 3 baseline windows). A rule
--     fires when spend is at least spike_multiplier x the median and at least spike_floor_nanos
--     (a median of 0 leaves only the floor, and the message says so), at most once per
--     cooldown_minutes (state row '-infinity', written only on fire). Dedupe:
--     spend_alert:<rule id>:cooldown:<epoch / cooldown>:spike. Sweep events carry the multiplier
--     as threshold and trigger 'spike'.
-- Returns {rules, fired, state_rows, events: [{event_id, rule_id, dedupe_key, threshold}],
-- blocks: [{block_id, rule_id, state: started|lifted, reason, event_id}], block_scope}, where
-- block_scope says the workspace has block rules or blocks, so its gateway entry is republished.
declare
  v_workspace record;
  v_result jsonb;
  v_block_rules jsonb;
  v_block record;
  v_blocks jsonb := '[]'::jsonb;
  v_changed integer := 0;
  v_fresh boolean;
  v_balance jsonb;
  v_spike jsonb;
begin
  if p_workspace_id is null or p_now is null then
    raise exception 'invalid_spend_rule_evaluation';
  end if;

  select w.id, w.name, w.owner_user_id, coalesce(settings.billing_time_zone, 'UTC') as time_zone, owner.email as owner_email
    into v_workspace
  from public.workspaces w
  left join public.workspace_settings settings on settings.workspace_id = w.id
  left join auth.users owner on owner.id = w.owner_user_id
  where w.id = p_workspace_id;
  if not found then
    return jsonb_build_object('rules', 0, 'fired', 0, 'state_rows', 0, 'events', '[]'::jsonb, 'blocks', '[]'::jsonb,
      'block_scope', false, 'missing', true);
  end if;

  with valued as materialized (
    -- Spend so far and the base of every enabled, evaluable rule (shared with the API preview).
    select * from private.spend_rule_values(p_workspace_id, p_now)
  ),
  decided as (
    -- A rolling rule's state is its '-infinity' row, and what it fired counts only within
    -- cooldown_minutes of the last alert: within it only a higher threshold fires, after it the
    -- rule fires again while it is still over.
    select valued.*, valued.period = 'rolling' as rolling, state.rule_id is not null as has_state,
      case when valued.period <> 'rolling' or cooling.active then state.highest_percent_fired end as highest_percent_fired,
      case when valued.period <> 'rolling' or cooling.active then state.amount_fired_at end as amount_fired_at,
      crossed.highest as crossed_percent,
      -- A forecast fires only once the projection is ready and at least a cent has been spent.
      valued.metric = 'forecast' and valued.projected_nanos is not null and valued.value_nanos >= 10000000 as forecast_ready
    from valued
    left join public.workspace_spend_rule_state state
      on state.rule_id = valued.id
      and state.period_start = case when valued.period = 'rolling' then '-infinity'::timestamptz else valued.period_start end
    cross join lateral (
      select coalesce(state.last_fired_at > p_now - make_interval(mins => valued.cooldown_minutes), false) as active
    ) cooling
    cross join lateral (
      select max(threshold) as highest
      from unnest(valued.threshold_percents) threshold
      where valued.base_nanos > 0
        and case valued.metric
          when 'budget_percent' then valued.value_nanos * 100 >= threshold::numeric * valued.base_nanos
          when 'forecast' then valued.projected_nanos is not null and valued.value_nanos >= 10000000
            and valued.projected_nanos * 100 >= threshold::numeric * valued.base_nanos
          else false
        end
    ) crossed
  ),
  firing as (
    select decided.*,
      case
        when decided.metric = 'spend' then 'amount-' || decided.threshold_amount_nanos
        when decided.metric = 'forecast' and decided.threshold_amount_nanos is not null then 'projected-amount-' || decided.threshold_amount_nanos
        when decided.metric = 'forecast' then 'projected-' || decided.crossed_percent
        else decided.crossed_percent::text
      end as threshold_key,
      case
        when decided.rolling then 'cooldown:' || floor(extract(epoch from p_now) / (decided.cooldown_minutes * 60))::bigint
        else to_char(decided.period_start at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
      end as period_key
    from decided
    where (decided.metric = 'spend' and decided.amount_fired_at is null and decided.value_nanos >= decided.threshold_amount_nanos)
      or (decided.metric in ('budget_percent', 'forecast') and decided.crossed_percent > coalesce(decided.highest_percent_fired, 0))
      or (decided.metric = 'forecast' and decided.threshold_amount_nanos is not null and decided.amount_fired_at is null
        and decided.forecast_ready and decided.projected_nanos >= decided.threshold_amount_nanos)
  ),
  rendered as (
    select firing.*, alert.scope_label, alert.title, alert.message,
      'spend_alert:' || firing.id || ':' || firing.period_key || ':' || firing.threshold_key as dedupe_key
    from firing
    cross join lateral private.spend_rule_alert_text(
      v_workspace.name, firing.name, firing.metric, firing.scope_type, firing.scope_id, firing.scope_key_id,
      firing.scope_user_id, firing.scope_department_id, firing.period, firing.period_end, firing.time_zone,
      firing.base_kind, firing.base_ref, firing.base_nanos, firing.threshold_percents, firing.threshold_amount_nanos,
      firing.value_nanos, firing.crossed_percent, firing.window_hours, firing.projected_nanos, firing.reaches_at
    ) alert
  ),
  queued as (
    insert into public.email_outbox (kind, template, to_email, subject, workspace_id, user_id, payload, dedupe_key)
    select
      'spend_alert',
      'spend_alert',
      coalesce(v_workspace.owner_email, ''),
      rendered.title,
      p_workspace_id,
      v_workspace.owner_user_id,
      jsonb_build_object(
        'title', rendered.title,
        'message', rendered.message,
        'workspace_name', v_workspace.name,
        'rule_id', rendered.id,
        'rule_name', rendered.name,
        'metric', rendered.metric,
        'action', rendered.action,
        'scope', jsonb_strip_nulls(jsonb_build_object(
          'type', rendered.scope_type,
          'id', rendered.scope_id,
          'label', rendered.scope_label,
          'key_id', rendered.scope_key_id,
          'user_id', rendered.scope_user_id,
          'department_id', rendered.scope_department_id
        )),
        'period', jsonb_strip_nulls(jsonb_build_object(
          'kind', rendered.period,
          'start', rendered.period_start,
          'end', rendered.period_end,
          'time_zone', rendered.time_zone,
          'window_hours', rendered.window_hours
        )),
        'value_nanos', rendered.value_nanos,
        'base_kind', rendered.base_kind,
        'base_ref', rendered.base_ref,
        'base_nanos', rendered.base_nanos,
        'previous_period', case when rendered.previous_start is not null then jsonb_build_object(
          'start', rendered.previous_start, 'end', rendered.previous_end) end,
        'percent', case when rendered.base_nanos > 0 then round(rendered.value_nanos * 100 / rendered.base_nanos, 1) end,
        'threshold_percent', rendered.crossed_percent,
        'threshold_percents', to_jsonb(rendered.threshold_percents),
        'thresholds_crossed', case when rendered.metric in ('budget_percent', 'forecast') and rendered.crossed_percent is not null then (
          select coalesce(jsonb_agg(threshold order by threshold), '[]'::jsonb)
          from unnest(rendered.threshold_percents) threshold
          where threshold <= rendered.crossed_percent and threshold > coalesce(rendered.highest_percent_fired, 0)
        ) end,
        'threshold_amount_nanos', rendered.threshold_amount_nanos,
        'forecast', case when rendered.metric = 'forecast' then jsonb_build_object(
          'projected_nanos', rendered.projected_nanos,
          'projected_percent', case when rendered.base_nanos > 0 then round(rendered.projected_nanos * 100 / rendered.base_nanos, 1) end,
          'by', rendered.period_end,
          'limit_nanos', rendered.limit_nanos,
          'reaches_at', rendered.reaches_at,
          'from', rendered.forecast_from
        ) end,
        'cooldown_minutes', case when rendered.rolling then rendered.cooldown_minutes end,
        'evaluated_at', p_now,
        'url', 'https://phaseo.app/settings/notifications',
        'push', jsonb_build_object(
          'title', left(rendered.title, 120),
          'body', left(rendered.message, 240),
          'href', '/settings/notifications',
          'lowerLead', false
        )
      ),
      rendered.dedupe_key
    from rendered
    on conflict (dedupe_key) do nothing
    returning id, dedupe_key, payload
  ),
  saved as (
    -- A fired rule records what it sent; a calendar rule seen for the first time this period
    -- gets its rollover row. Rules already recorded this period that fire nothing are not
    -- written. A rolling rule has one '-infinity' row, written only when it fires, which then
    -- holds what this alert named (the cooldown starts again).
    insert into public.workspace_spend_rule_state as state (
      rule_id, workspace_id, period_start, period_end, highest_percent_fired, amount_fired_at, last_fired_at,
      fire_count, last_value_nanos, last_base_nanos, last_dedupe_key
    )
    select
      decided.id, p_workspace_id,
      case when decided.rolling then '-infinity'::timestamptz else decided.period_start end,
      case when decided.rolling then null else decided.period_end end,
      case when rendered.id is not null then rendered.crossed_percent end,
      case when rendered.id is not null and decided.threshold_amount_nanos is not null and decided.metric in ('spend', 'forecast') then p_now end,
      case when rendered.id is not null then p_now end,
      case when rendered.id is not null then 1 else 0 end,
      case when rendered.id is not null then round(decided.value_nanos)::bigint end,
      case when rendered.id is not null then decided.base_nanos end,
      rendered.dedupe_key
    from decided
    left join rendered on rendered.id = decided.id
    where rendered.id is not null or not (decided.has_state or decided.rolling)
    on conflict (rule_id, period_start) do update set
      -- A rolling rule fires within its cooldown only past what it last named, so the new
      -- values are the ones to keep.
      highest_percent_fired = case when state.period_start = '-infinity'::timestamptz then excluded.highest_percent_fired
        else greatest(state.highest_percent_fired, excluded.highest_percent_fired) end,
      amount_fired_at = case when state.period_start = '-infinity'::timestamptz
        then coalesce(excluded.amount_fired_at, state.amount_fired_at)
        else coalesce(state.amount_fired_at, excluded.amount_fired_at) end,
      last_fired_at = coalesce(excluded.last_fired_at, state.last_fired_at),
      fire_count = state.fire_count + excluded.fire_count,
      last_value_nanos = coalesce(excluded.last_value_nanos, state.last_value_nanos),
      last_base_nanos = coalesce(excluded.last_base_nanos, state.last_base_nanos),
      last_dedupe_key = coalesce(excluded.last_dedupe_key, state.last_dedupe_key)
    returning 1
  )
  select jsonb_build_object(
    'rules', (select count(*) from valued),
    'fired', (select count(*) from queued),
    'state_rows', (select count(*) from saved),
    'events', coalesce((
      select jsonb_agg(jsonb_build_object(
        'event_id', queued.id,
        'rule_id', queued.payload ->> 'rule_id',
        'dedupe_key', queued.dedupe_key,
        'threshold', coalesce(nullif(queued.payload -> 'threshold_percent', 'null'::jsonb), queued.payload -> 'threshold_amount_nanos')
      ) order by queued.dedupe_key)
      from queued
    ), '[]'::jsonb),
    -- The block point and spend of each block rule, for the block statements below.
    'block_rules', coalesce((
      -- A rolling rule's block covers the window it started in and has no reset: it lifts once
      -- spend over the window is below the block point again.
      select jsonb_agg(jsonb_build_object(
        'rule_id', valued.id,
        'rolling', valued.period = 'rolling',
        'window_hours', valued.window_hours,
        'period_start', valued.period_start,
        'period_end', case when valued.period <> 'rolling' then valued.period_end end,
        'value_nanos', valued.value_nanos,
        'limit_nanos', case valued.metric
          when 'spend' then rule.block_at_amount_nanos
          when 'budget_percent' then case when valued.base_nanos > 0
            then ceil(rule.block_at_percent::numeric * valued.base_nanos / 100)::bigint end
        end,
        'scope_type', valued.scope_type,
        'scope_id', valued.scope_id,
        'block_free_models', rule.block_free_models
      ))
      from valued
      join public.workspace_spend_rules rule on rule.id = valued.id
      where valued.action = 'block'
    ), '[]'::jsonb)
  ) into v_result;

  -- Balance rules: armed until the balance (or runway) drops to the threshold, then one alert.
  with balance as materialized (
    select * from private.spend_balance_rule_values(p_workspace_id, p_now)
  ),
  decided as (
    select balance.*, coalesce(state.armed, true) as armed,
      balance.low_balance or balance.low_runway as low,
      state.last_fired_at is not null and state.last_fired_at > p_now - make_interval(mins => balance.cooldown_minutes) as cooling,
      case when balance.low_balance then 'balance' else 'runway' end as trigger
    from balance
    left join public.workspace_spend_rule_state state
      on state.rule_id = balance.id and state.period_start = '-infinity'::timestamptz
  ),
  acted as materialized (
    select decided.*,
      case
        when decided.armed and decided.low and decided.cooling then 'waiting'
        when decided.armed and decided.low and private.workspace_auto_top_up_covers(p_workspace_id) then 'covered'
        when decided.armed and decided.low then 'fire'
        when not decided.armed and not decided.low then 'rearm'
        else 'idle'
      end as outcome
    from decided
  ),
  rendered as (
    select acted.*, alert.title, alert.message,
      'spend_alert:' || acted.id || ':cooldown:' || floor(extract(epoch from p_now) / (acted.cooldown_minutes * 60))::bigint
        || ':' || acted.trigger as dedupe_key
    from acted
    cross join lateral private.spend_balance_alert_text(
      acted.name, acted.available_nanos, acted.threshold_amount_nanos, acted.runway_days, acted.burn_per_day_nanos,
      acted.runway_days_left, acted.window_hours, acted.trigger
    ) alert
    where acted.outcome = 'fire'
  ),
  queued as (
    insert into public.email_outbox (kind, template, to_email, subject, workspace_id, user_id, payload, dedupe_key)
    select
      'spend_alert',
      'spend_alert',
      coalesce(v_workspace.owner_email, ''),
      rendered.title,
      p_workspace_id,
      v_workspace.owner_user_id,
      jsonb_build_object(
        'title', rendered.title,
        'message', rendered.message,
        'workspace_name', v_workspace.name,
        'rule_id', rendered.id,
        'rule_name', rendered.name,
        'metric', 'balance',
        'action', rendered.action,
        'scope', jsonb_build_object('type', 'workspace', 'label', coalesce(nullif(btrim(v_workspace.name), ''), 'Workspace')),
        'period', jsonb_build_object(
          'kind', 'rolling',
          'start', p_now - make_interval(hours => rendered.window_hours),
          'end', p_now,
          'time_zone', v_workspace.time_zone,
          'window_hours', rendered.window_hours
        ),
        'trigger', rendered.trigger,
        'value_nanos', rendered.available_nanos,
        'balance_nanos', rendered.balance_nanos,
        'reserved_nanos', rendered.reserved_nanos,
        'available_nanos', rendered.available_nanos,
        'burn_nanos', round(rendered.burn_nanos),
        'burn_per_day_nanos', round(rendered.burn_per_day_nanos),
        'runway_days_left', rendered.runway_days_left,
        'runway_days', rendered.runway_days,
        'threshold_amount_nanos', rendered.threshold_amount_nanos,
        'evaluated_at', p_now,
        'url', 'https://phaseo.app/settings/credits',
        'push', jsonb_build_object(
          'title', left(rendered.title, 120),
          'body', left(rendered.message, 240),
          'href', '/settings/credits',
          'lowerLead', false
        )
      ),
      rendered.dedupe_key
    from rendered
    on conflict (dedupe_key) do nothing
    returning id, dedupe_key, payload
  ),
  saved as (
    -- A drop (fired or covered by auto top-up) clears armed, a recovery sets it. A waiting or
    -- unchanged rule is not written.
    insert into public.workspace_spend_rule_state as state (
      rule_id, workspace_id, period_start, period_end, armed, amount_fired_at, last_fired_at, fire_count, last_value_nanos, last_dedupe_key
    )
    select acted.id, p_workspace_id, '-infinity'::timestamptz, null, acted.outcome = 'rearm',
      case when rendered.id is not null and acted.trigger = 'balance' then p_now end,
      case when rendered.id is not null then p_now end,
      case when rendered.id is not null then 1 else 0 end,
      case when rendered.id is not null then acted.available_nanos end,
      rendered.dedupe_key
    from acted
    left join rendered on rendered.id = acted.id
    where acted.outcome in ('fire', 'covered', 'rearm')
    on conflict (rule_id, period_start) do update set
      armed = excluded.armed,
      amount_fired_at = coalesce(excluded.amount_fired_at, state.amount_fired_at),
      last_fired_at = coalesce(excluded.last_fired_at, state.last_fired_at),
      fire_count = state.fire_count + excluded.fire_count,
      last_value_nanos = coalesce(excluded.last_value_nanos, state.last_value_nanos),
      last_dedupe_key = coalesce(excluded.last_dedupe_key, state.last_dedupe_key)
    returning 1
  )
  select jsonb_build_object(
    'rules', (select count(*) from balance),
    'fired', (select count(*) from queued),
    'state_rows', (select count(*) from saved),
    'events', coalesce((
      select jsonb_agg(jsonb_build_object(
        'event_id', queued.id,
        'rule_id', queued.payload ->> 'rule_id',
        'dedupe_key', queued.dedupe_key,
        'threshold', case queued.payload ->> 'trigger'
          when 'balance' then queued.payload -> 'threshold_amount_nanos'
          else queued.payload -> 'runway_days'
        end,
        'trigger', queued.payload ->> 'trigger'
      ) order by queued.dedupe_key)
      from queued
    ), '[]'::jsonb)
  ) into v_balance;

  -- Spike rules: spend over the window against the median of the same window over the previous
  -- 7 days, at most one alert per cooldown. Skipped (and free) for workspaces without them.
  v_spike := jsonb_build_object('rules', 0, 'fired', 0, 'state_rows', 0, 'events', '[]'::jsonb);
  if exists (
    select 1 from public.workspace_spend_rules rule
    where rule.workspace_id = p_workspace_id and rule.metric = 'spike' and rule.enabled and rule.deleted_at is null
  ) then
    with spike as materialized (
      select * from private.spend_spike_rule_values(p_workspace_id, p_now)
    ),
    decided as (
      select spike.*,
        coalesce(state.last_fired_at > p_now - make_interval(mins => spike.cooldown_minutes), false) as cooling
      from spike
      left join public.workspace_spend_rule_state state
        on state.rule_id = spike.id and state.period_start = '-infinity'::timestamptz
      where spike.spiking
    ),
    rendered as (
      select decided.*, alert.scope_label, alert.title, alert.message,
        'spend_alert:' || decided.id || ':cooldown:' || floor(extract(epoch from p_now) / (decided.cooldown_minutes * 60))::bigint
          || ':spike' as dedupe_key
      from decided
      cross join lateral private.spend_spike_alert_text(
        v_workspace.name, decided.name, decided.scope_type, decided.scope_id, decided.scope_key_id, decided.scope_user_id,
        decided.scope_department_id, decided.window_hours, decided.current_nanos, decided.baseline_nanos, decided.multiple,
        decided.spike_multiplier, decided.spike_floor_nanos, decided.baseline_windows
      ) alert
      where not decided.cooling
    ),
    queued as (
      insert into public.email_outbox (kind, template, to_email, subject, workspace_id, user_id, payload, dedupe_key)
      select
        'spend_alert',
        'spend_alert',
        coalesce(v_workspace.owner_email, ''),
        rendered.title,
        p_workspace_id,
        v_workspace.owner_user_id,
        jsonb_build_object(
          'title', rendered.title,
          'message', rendered.message,
          'workspace_name', v_workspace.name,
          'rule_id', rendered.id,
          'rule_name', rendered.name,
          'metric', 'spike',
          'action', rendered.action,
          'scope', jsonb_strip_nulls(jsonb_build_object(
            'type', rendered.scope_type,
            'id', rendered.scope_id,
            'label', rendered.scope_label,
            'key_id', rendered.scope_key_id,
            'user_id', rendered.scope_user_id,
            'department_id', rendered.scope_department_id
          )),
          'period', jsonb_build_object(
            'kind', 'rolling',
            'start', rendered.period_start,
            'end', rendered.period_end,
            'time_zone', rendered.time_zone,
            'window_hours', rendered.window_hours
          ),
          'value_nanos', rendered.current_nanos,
          'base_nanos', rendered.baseline_nanos,
          'threshold_percent', null,
          'threshold_amount_nanos', null,
          'spike', jsonb_build_object(
            'current_nanos', rendered.current_nanos,
            'baseline_nanos', rendered.baseline_nanos,
            'multiple', rendered.multiple,
            'multiplier', rendered.spike_multiplier,
            'floor_nanos', rendered.spike_floor_nanos,
            'fires_at_nanos', rendered.fires_at_nanos,
            'baseline_windows', rendered.baseline_windows,
            'active_windows', rendered.active_windows,
            'floor_only', not (rendered.baseline_nanos > 0)
          ),
          'cooldown_minutes', rendered.cooldown_minutes,
          'evaluated_at', p_now,
          'url', 'https://phaseo.app/settings/notifications',
          'push', jsonb_build_object(
            'title', left(rendered.title, 120),
            'body', left(rendered.message, 240),
            'href', '/settings/notifications',
            'lowerLead', false
          )
        ),
        rendered.dedupe_key
      from rendered
      on conflict (dedupe_key) do nothing
      returning id, dedupe_key, payload
    ),
    saved as (
      -- One '-infinity' row per spike rule, written only when it fires (the cooldown starts again).
      insert into public.workspace_spend_rule_state as state (
        rule_id, workspace_id, period_start, period_end, last_fired_at, fire_count, last_value_nanos, last_base_nanos, last_dedupe_key
      )
      select rendered.id, p_workspace_id, '-infinity'::timestamptz, null, p_now, 1, round(rendered.current_nanos)::bigint,
        round(rendered.baseline_nanos)::bigint, rendered.dedupe_key
      from rendered
      on conflict (rule_id, period_start) do update set
        last_fired_at = excluded.last_fired_at,
        fire_count = state.fire_count + 1,
        last_value_nanos = excluded.last_value_nanos,
        last_base_nanos = excluded.last_base_nanos,
        last_dedupe_key = excluded.last_dedupe_key
      returning 1
    )
    select jsonb_build_object(
      'rules', (select count(*) from spike),
      'fired', (select count(*) from queued),
      'state_rows', (select count(*) from saved),
      'events', coalesce((
        select jsonb_agg(jsonb_build_object(
          'event_id', queued.id,
          'rule_id', queued.payload ->> 'rule_id',
          'dedupe_key', queued.dedupe_key,
          'threshold', queued.payload -> 'spike' -> 'multiplier',
          'trigger', 'spike'
        ) order by queued.dedupe_key)
        from queued
      ), '[]'::jsonb)
    ) into v_spike;
  end if;

  v_result := v_result || jsonb_build_object(
    'rules', (v_result ->> 'rules')::integer + (v_balance ->> 'rules')::integer + (v_spike ->> 'rules')::integer,
    'fired', (v_result ->> 'fired')::integer + (v_balance ->> 'fired')::integer + (v_spike ->> 'fired')::integer,
    'state_rows', (v_result ->> 'state_rows')::integer + (v_balance ->> 'state_rows')::integer + (v_spike ->> 'state_rows')::integer,
    'events', (v_result -> 'events') || (v_balance -> 'events') || (v_spike -> 'events')
  );

  v_block_rules := v_result -> 'block_rules';
  v_result := v_result - 'block_rules';

  -- Lift active blocks that no longer apply. Lifts come before starts: a rule's new block cannot
  -- start while its old one is still active (one active block per rule).
  for v_block in
    with block_rule as (
      select * from jsonb_to_recordset(v_block_rules) as x(
        rule_id uuid, rolling boolean, period_start timestamptz, period_end timestamptz, value_nanos numeric, limit_nanos bigint,
        scope_type text, scope_id text, block_free_models boolean)
    ),
    decided as (
      select block.id, case
          when block.rule_id is null or rule.id is null or rule.deleted_at is not null then 'rule_deleted'
          when not rule.enabled then 'rule_disabled'
          when rule.action <> 'block' or block_rule.rule_id is null then 'rule_changed'
          when block_rule.rolling and block.resets_at is not null then 'rule_changed'
          when not block_rule.rolling and block.period_start <> block_rule.period_start then
            case when block.resets_at is not null and block.resets_at <= p_now then 'period_reset' else 'rule_changed' end
          when block.scope_type <> block_rule.scope_type or block.scope_id is distinct from block_rule.scope_id then 'rule_changed'
          when block_rule.limit_nanos is null or block_rule.value_nanos < block_rule.limit_nanos then
            case when rule.updated_at > block.started_at then 'rule_changed' else 'below_limit' end
        end as reason
      from public.workspace_spend_blocks block
      left join public.workspace_spend_rules rule on rule.id = block.rule_id
      left join block_rule on block_rule.rule_id = block.rule_id
      where block.workspace_id = p_workspace_id
        and block.lifted_at is null
    )
    update public.workspace_spend_blocks block
    set lifted_at = greatest(p_now, block.started_at), lift_reason = decided.reason
    from decided
    where block.id = decided.id
      and decided.reason is not null
    returning block.id, block.rule_id, block.lift_reason
  loop
    v_blocks := v_blocks || jsonb_build_array(jsonb_build_object(
      'block_id', v_block.id, 'rule_id', v_block.rule_id, 'state', 'lifted', 'reason', v_block.lift_reason,
      'event_id', private.queue_spend_block_event(v_block.id, 'lifted', p_now)));
  end loop;

  -- An active block follows its rule's free-model setting.
  with block_rule as (
    select * from jsonb_to_recordset(v_block_rules) as x(rule_id uuid, block_free_models boolean)
  )
  update public.workspace_spend_blocks block
  set block_free_models = block_rule.block_free_models
  from block_rule
  where block.rule_id = block_rule.rule_id
    and block.workspace_id = p_workspace_id
    and block.lifted_at is null
    and block.block_free_models <> block_rule.block_free_models;
  get diagnostics v_changed = row_count;

  -- Start blocks: only on a current evaluation, never for a rule lifted by hand this period.
  v_fresh := p_blocks and p_now between now() - interval '15 minutes' and now() + interval '5 minutes';
  if v_fresh then
    for v_block in
      insert into public.workspace_spend_blocks as block (
        workspace_id, rule_id, scope_type, scope_id, block_free_models, period_start, resets_at, spend_nanos, limit_nanos, started_at
      )
      select p_workspace_id, block_rule.rule_id, block_rule.scope_type, block_rule.scope_id, block_rule.block_free_models,
        block_rule.period_start, block_rule.period_end, round(block_rule.value_nanos)::bigint, block_rule.limit_nanos, p_now
      from jsonb_to_recordset(v_block_rules) as block_rule(
        rule_id uuid, rolling boolean, window_hours integer, period_start timestamptz, period_end timestamptz, value_nanos numeric,
        limit_nanos bigint, scope_type text, scope_id text, block_free_models boolean)
      where block_rule.limit_nanos > 0
        and block_rule.value_nanos >= block_rule.limit_nanos
        and (block_rule.rolling or p_now < block_rule.period_end)
        and not exists (
          select 1 from public.workspace_spend_blocks active
          where active.rule_id = block_rule.rule_id and active.lifted_at is null
        )
        -- A manual lift holds for the rest of the period, or for one window of a rolling rule.
        and not exists (
          select 1 from public.workspace_spend_blocks lifted
          where lifted.rule_id = block_rule.rule_id
            and lifted.lift_reason = 'manual'
            and case when block_rule.rolling
              then lifted.lifted_at > p_now - make_interval(hours => block_rule.window_hours)
              else lifted.period_start = block_rule.period_start
            end
        )
      on conflict do nothing
      returning block.id, block.rule_id
    loop
      v_blocks := v_blocks || jsonb_build_array(jsonb_build_object(
        'block_id', v_block.id, 'rule_id', v_block.rule_id, 'state', 'started', 'reason', null,
        'event_id', private.queue_spend_block_event(v_block.id, 'started', p_now)));
    end loop;
  end if;

  return v_result || jsonb_build_object(
    'blocks', v_blocks,
    'block_scope', jsonb_array_length(v_block_rules) > 0 or jsonb_array_length(v_blocks) > 0 or v_changed > 0
      or exists (select 1 from public.workspace_spend_blocks block where block.workspace_id = p_workspace_id and block.lifted_at is null)
  );
end;
$function$;

COMMENT ON FUNCTION "private"."evaluate_workspace_spend_rules"(uuid, timestamp with time zone, boolean) IS 'Evaluates a workspace''s enabled spend, budget_percent and forecast rules over their calendar period (or rolling window, with a cooldown) at p_now: queues one spend_alert event per rule that crossed, or is projected to cross, a new threshold (the highest one) and per balance rule whose balance or runway dropped to its threshold (armed/unarmed with a cooldown, never while auto top-up is working) and per spike rule whose spend over its window reached spike_multiplier x the median of the same window over the previous 7 days and its floor (with a cooldown), lifts blocks that no longer apply and, when p_blocks is true and p_now is current, starts blocks for block rules past their block point. Writes rule state only on fire or period rollover. Called by public.sweep_spend_rules.';

REVOKE ALL ON FUNCTION "private"."evaluate_workspace_spend_rules"(uuid, timestamp with time zone, boolean) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."evaluate_workspace_spend_rules"(uuid, timestamp with time zone, boolean) TO "service_role";

-- source: supabase/schemas/private/functions/gateway_compiled_context_access.sql
CREATE OR REPLACE FUNCTION private.gateway_compiled_context_access (
  workspace_id uuid,
  model        text,
  endpoint     text,
  api_key_id   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  credit_status       jsonb;
  key_status          jsonb;
  key_limit_status    jsonb;
  min_balance_nanos bigint := case when endpoint like 'video.%' or endpoint like 'batch%' then 1000000000 else 100000000 end; -- 1.00 USD

  providers           jsonb;
  pricing             jsonb;
  preset_data         jsonb := null;

  -- key row fields
  v_key_active        boolean;
  v_key_team_ok       boolean;
  v_soft_blocked      boolean;

  v_day_req_limit     bigint;
  v_wk_req_limit      bigint;
  v_mo_req_limit      bigint;
  v_day_cost_limit    bigint;
  v_wk_cost_limit     bigint;
  v_mo_cost_limit     bigint;

  now_utc             timestamptz := (now() at time zone 'utc');
  day_start           timestamptz := date_trunc('day',  now_utc);
  week_start          timestamptz := date_trunc('week', now_utc);   -- Monday 00:00 UTC
  month_start         timestamptz := date_trunc('month', now_utc);

  used_day_reqs       bigint;
  used_wk_reqs        bigint;
  used_mo_reqs        bigint;
  used_day_cost       bigint;
  used_wk_cost        bigint;
  used_mo_cost        bigint;

  within_limits       boolean := true;
  limit_reason        text := null;
  limit_window        text := null;
  limit_metric        text := null;
  current_value       bigint := null;
  limit_value         bigint := null;
  limit_reset_at      timestamptz := null;

  -- Preset handling
  is_preset           boolean := false;
  preset_name         text := null;
  preset_publisher    text := null;

  -- Resolve model from alias if exists
  resolved_model      text := gateway_compiled_context_access.model;
  base_model          text;

  team_enrichment     jsonb;
  key_enrichment      jsonb;

  -- Team aggregates
  team_total_requests bigint;
  team_total_spend_nanos bigint;
  team_spend_24h_nanos bigint;
  team_spend_7d_nanos bigint;
  team_spend_30d_nanos bigint;
  team_requests_1h bigint;
  team_requests_24h bigint;
  team_created_at timestamptz;
  team_tier text;
  team_balance_nanos bigint;
  team_reserved_nanos bigint;

  -- Key aggregates
  key_name text;
  key_created_at timestamptz;
  key_total_requests bigint;
  key_total_spend_nanos bigint;
begin
  base_model := gateway_compiled_context_access.model;
  -- hard requirement: key must be provided
  if gateway_compiled_context_access.api_key_id is null then
    raise exception using errcode = '22023', message = 'missing_api_key', detail = 'api_key_id is required';
  end if;

  -- Check if model is a preset (starts with @)
  if base_model like '@%' then
    is_preset := true;
    preset_name := substring(base_model from 2); -- Remove @ prefix

    -- Fetch preset configuration. Qualified references resolve a
    -- public publisher globally; unqualified references remain workspace-local.
    if position('/' in preset_name) > 0 then
      preset_publisher := split_part(preset_name, '/', 1);
      preset_name := substring(preset_name from position('/' in preset_name) + 1);
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'slug', p.slug, 'description', p.description,
        'config', p.config, 'visibility', p.visibility, 'publisher', w.publisher_handle
      ) into preset_data
      from public.presets p
      join public.workspaces w on w.id = p.workspace_id
      where p.archived_at is null and lower(p.slug) = lower(preset_name)
        and p.visibility = 'public'
        and true
        and (lower(w.publisher_handle) = lower(preset_publisher) or exists (select 1 from public.workspace_publisher_handle_aliases alias where alias.workspace_id = w.id and alias.handle = lower(preset_publisher)))
      limit 1;
    else
      select jsonb_build_object(
        'id', p.id, 'name', p.name,
        'slug', coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', '')),
        'description', p.description, 'config', p.config, 'visibility', p.visibility
      ) into preset_data
      from public.presets p
      where p.archived_at is null and lower(coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', ''))) = lower(preset_name)
        and p.workspace_id = gateway_compiled_context_access.workspace_id
        and (
          p.visibility in ('public', 'team')
          or p.created_by = (
            select ak.created_by from public.keys ak
            where ak.id = gateway_compiled_context_access.api_key_id
              and ak.workspace_id = gateway_compiled_context_access.workspace_id
              and ak.status = 'active'
          )
        )
      limit 1;
    end if;

    if preset_data is null then
      raise exception using
        errcode = '22023',
        message = 'preset_not_found',
        detail = format('Preset "%s" not found or not accessible', preset_name);
    end if;

    -- Extract model from preset config (fallback to default/default_model/model/first models entry)
    base_model := coalesce(
      preset_data->'config'->>'defaultModel',
      preset_data->'config'->>'default_model',
      preset_data->'config'->>'model',
      preset_data->'config'->'models'->>0,
      preset_data->'config'->'allowedModels'->>0,
      preset_data->'config'->'allowed_models'->>0
    );

    if base_model is null then
      raise exception using
        errcode = '22023',
        message = 'preset_no_model',
        detail = format('Preset "%s" has no model configured', preset_name);
    end if;
  end if;

  resolved_model := base_model;

  -- validate key row, status, and team
  select
    (k.status = 'active'),
    (k.workspace_id = gateway_compiled_context_access.workspace_id),
    k.soft_blocked,
    k.daily_limit_requests,   k.weekly_limit_requests,   k.monthly_limit_requests,
    k.daily_limit_cost_nanos, k.weekly_limit_cost_nanos, k.monthly_limit_cost_nanos
  into
    v_key_active,
    v_key_team_ok,
    v_soft_blocked,
    v_day_req_limit, v_wk_req_limit, v_mo_req_limit,
    v_day_cost_limit, v_wk_cost_limit, v_mo_cost_limit
  from public.keys k
  where k.id = gateway_compiled_context_access.api_key_id
  limit 1;

  if v_key_active is null then
    raise exception using errcode = '22023', message = 'api_key_not_found', detail = 'key id does not exist';
  end if;
  if not v_key_team_ok then
    raise exception using errcode = '22023', message = 'api_key_wrong_team', detail = 'key does not belong to provided workspace_id';
  end if;
  if not v_key_active then
    raise exception using errcode = '22023', message = 'api_key_inactive', detail = 'key status is not active';
  end if;

  key_status := jsonb_build_object('ok', true, 'mode', 'first_party');

  -- credit check
  credit_status :=
    coalesce((
      select case
        when greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0) >= min_balance_nanos then
          jsonb_build_object(
            'ok', true,
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
        else
          jsonb_build_object(
            'ok', false,
            'reason', 'insufficient_funds',
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
      end
      from public.wallets w
      where w.workspace_id = gateway_compiled_context_access.workspace_id
      limit 1
    ), jsonb_build_object('ok', false, 'reason', 'wallet_missing'));

  -- per-key limits (requests + cost)
  -- Unlimited keys need no history read. Unknown telemetry stays NULL.
  if greatest(v_day_req_limit, v_wk_req_limit, v_mo_req_limit,
      v_day_cost_limit, v_wk_cost_limit, v_mo_cost_limit) > 0 then
  select
    count(*) filter (where gr.created_at >= day_start)                                  as used_day_reqs,
    count(*) filter (where gr.created_at >= week_start)                                 as used_wk_reqs,
    count(*) filter (where gr.created_at >= month_start)                                as used_mo_reqs,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= day_start), 0)::bigint   as used_day_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= week_start), 0)::bigint  as used_wk_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= month_start), 0)::bigint as used_mo_cost
  into
    used_day_reqs, used_wk_reqs, used_mo_reqs,
    used_day_cost, used_wk_cost, used_mo_cost
  from public.gateway_requests gr
  where gr.key_id  = gateway_compiled_context_access.api_key_id
    and gr.workspace_id = gateway_compiled_context_access.workspace_id
    and gr.success is true
    and gr.created_at >= least(week_start, month_start);
  end if;

  if v_soft_blocked then
    within_limits := false;
    limit_reason := 'key_limit_soft_blocked';
    limit_metric := 'soft_blocked';
  end if;
  if within_limits and v_day_req_limit > 0 and used_day_reqs >= v_day_req_limit then
    within_limits := false;
    limit_reason := 'daily_request_limit_reached';
    limit_window := 'daily';
    limit_metric := 'requests';
    current_value := used_day_reqs;
    limit_value := v_day_req_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_req_limit > 0 and used_wk_reqs >= v_wk_req_limit then
    within_limits := false;
    limit_reason := 'weekly_request_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'requests';
    current_value := used_wk_reqs;
    limit_value := v_wk_req_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_req_limit > 0 and used_mo_reqs >= v_mo_req_limit then
    within_limits := false;
    limit_reason := 'monthly_request_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'requests';
    current_value := used_mo_reqs;
    limit_value := v_mo_req_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;
  if within_limits and v_day_cost_limit > 0 and used_day_cost >= v_day_cost_limit then
    within_limits := false;
    limit_reason := 'daily_cost_limit_reached';
    limit_window := 'daily';
    limit_metric := 'cost';
    current_value := used_day_cost;
    limit_value := v_day_cost_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_cost_limit > 0 and used_wk_cost >= v_wk_cost_limit then
    within_limits := false;
    limit_reason := 'weekly_cost_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'cost';
    current_value := used_wk_cost;
    limit_value := v_wk_cost_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_cost_limit > 0 and used_mo_cost >= v_mo_cost_limit then
    within_limits := false;
    limit_reason := 'monthly_cost_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'cost';
    current_value := used_mo_cost;
    limit_value := v_mo_cost_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;

  key_limit_status :=
    jsonb_build_object(
      'ok', within_limits,
      'reason', limit_reason,
      'limit_window', limit_window,
      'limit_metric', limit_metric,
      'current_value', current_value,
      'limit_value', limit_value,
      'reset_at', to_jsonb(limit_reset_at),
      'now', to_jsonb(now_utc),
      'buckets', jsonb_build_object(
        'daily', jsonb_build_object(
          'window_start', to_jsonb(day_start),
          'requests_used', used_day_reqs,
          'requests_limit', v_day_req_limit,
          'cost_used_nanos', used_day_cost,
          'cost_limit_nanos', v_day_cost_limit
        ),
        'weekly', jsonb_build_object(
          'window_start', to_jsonb(week_start),
          'requests_used', used_wk_reqs,
          'requests_limit', v_wk_req_limit,
          'cost_used_nanos', used_wk_cost,
          'cost_limit_nanos', v_wk_cost_limit
        ),
        'monthly', jsonb_build_object(
          'window_start', to_jsonb(month_start),
          'requests_used', used_mo_reqs,
          'requests_limit', v_mo_req_limit,
          'cost_used_nanos', used_mo_cost,
          'cost_limit_nanos', v_mo_cost_limit
        )
      )
    );

  -- ============================================================================
  -- TEAM & KEY ENRICHMENT (Wide Event Context for Observability)
  -- Purpose: Gather user/team context for comprehensive logging (loggingsucks.com pattern)
  -- ============================================================================
  -- Team metadata & wallet
  select
    t.created_at,
    coalesce(t.tier, 'basic'),
    greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
    coalesce(w.reserved_nanos, 0)::bigint
  into
    team_created_at,
    team_tier,
    team_balance_nanos,
    team_reserved_nanos
  from public.workspaces t
  left join public.wallets w on w.workspace_id = t.id
  where t.id = gateway_compiled_context_access.workspace_id
  limit 1;

  -- Historical analytics belong in reporting, not request admission.
  -- Leave their enrichment fields NULL instead of scanning lifetime logs.

  -- Calculate tier using calendar-month qualification + lock-window grace.
  -- Function maintains team tier/counters in database when state changes.
  team_tier := public.calculate_tier_with_grace(gateway_compiled_context_access.workspace_id, team_spend_30d_nanos);

  team_enrichment := jsonb_build_object(
    'tier', team_tier,
    'created_at', to_jsonb(team_created_at),
    'account_age_days', extract(epoch from (now_utc - team_created_at)) / 86400,
    'balance_nanos', team_balance_nanos,
    'available_nanos', team_balance_nanos,
    'reserved_nanos', team_reserved_nanos,
    'balance_usd', round((team_balance_nanos::numeric / 1000000000.0)::numeric, 2),
    'balance_is_low', team_balance_nanos < min_balance_nanos,
    'total_requests', team_total_requests,
    'total_spend_nanos', team_total_spend_nanos,
    'total_spend_usd', round((team_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_24h_nanos', team_spend_24h_nanos,
    'spend_24h_usd', round((team_spend_24h_nanos::numeric / 1000000000.0)::numeric, 4),
    'spend_7d_nanos', team_spend_7d_nanos,
    'spend_7d_usd', round((team_spend_7d_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_30d_nanos', team_spend_30d_nanos,
    'spend_30d_usd', round((team_spend_30d_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_1h', team_requests_1h,
    'requests_24h', team_requests_24h
  );

  -- Key metadata & aggregates
  select
    k.name,
    k.created_at
  into
    key_name,
    key_created_at
  from public.keys k
  where k.id = gateway_compiled_context_access.api_key_id
  limit 1;

  -- Lifetime key analytics are not required to authenticate or enforce limits.

  key_enrichment := jsonb_build_object(
    'name', key_name,
    'created_at', to_jsonb(key_created_at),
    'key_age_days', extract(epoch from (now_utc - key_created_at)) / 86400,
    'total_requests', key_total_requests,
    'total_spend_nanos', key_total_spend_nanos,
    'total_spend_usd', round((key_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_today', used_day_reqs,
    'spend_today_nanos', used_day_cost,
    'spend_today_usd', round((used_day_cost::numeric / 1000000000.0)::numeric, 4),
    'daily_limit_pct', case
      when v_day_req_limit > 0 then round((used_day_reqs::numeric / v_day_req_limit::numeric * 100)::numeric, 1)
      else null
    end
  );

  providers := '[]'::jsonb;
  pricing := '{}'::jsonb;

  return jsonb_build_object(
    'workspace_id', gateway_compiled_context_access.workspace_id,
    'resolved_model', resolved_model,
    'preset', preset_data,
    'key_ok', key_status,
    'key_limit_ok', key_limit_status,
    'credit_ok', credit_status,
    'providers', providers,
    'pricing', pricing,
    'team_enrichment', team_enrichment,
    'key_enrichment', key_enrichment
  );
end;

$function$;

GRANT EXECUTE ON FUNCTION "private"."gateway_compiled_context_access"(uuid, text, text, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "private"."gateway_compiled_context_access"(uuid, text, text, uuid) FROM PUBLIC;

-- source: supabase/schemas/private/functions/gateway_context_access.sql
CREATE OR REPLACE FUNCTION private.gateway_context_access (
  workspace_id uuid,
  model        text,
  endpoint     text,
  api_key_id   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  credit_status       jsonb;
  key_status          jsonb;
  key_limit_status    jsonb;
  min_balance_nanos bigint := case when endpoint like 'video.%' or endpoint like 'batch%' then 1000000000 else 100000000 end; -- 1.00 USD

  providers           jsonb;
  pricing             jsonb;
  preset_data         jsonb := null;

  -- key row fields
  v_key_active        boolean;
  v_key_team_ok       boolean;
  v_soft_blocked      boolean;

  v_day_req_limit     bigint;
  v_wk_req_limit      bigint;
  v_mo_req_limit      bigint;
  v_day_cost_limit    bigint;
  v_wk_cost_limit     bigint;
  v_mo_cost_limit     bigint;

  now_utc             timestamptz := (now() at time zone 'utc');
  day_start           timestamptz := date_trunc('day',  now_utc);
  week_start          timestamptz := date_trunc('week', now_utc);   -- Monday 00:00 UTC
  month_start         timestamptz := date_trunc('month', now_utc);

  used_day_reqs       bigint;
  used_wk_reqs        bigint;
  used_mo_reqs        bigint;
  used_day_cost       bigint;
  used_wk_cost        bigint;
  used_mo_cost        bigint;

  within_limits       boolean := true;
  limit_reason        text := null;
  limit_window        text := null;
  limit_metric        text := null;
  current_value       bigint := null;
  limit_value         bigint := null;
  limit_reset_at      timestamptz := null;

  -- Preset handling
  is_preset           boolean := false;
  preset_name         text := null;
  preset_publisher    text := null;

  -- Resolve model from alias if exists
  resolved_model      text := gateway_context_access.model;
  base_model          text;

  team_enrichment     jsonb;
  key_enrichment      jsonb;

  -- Team aggregates
  team_total_requests bigint;
  team_total_spend_nanos bigint;
  team_spend_24h_nanos bigint;
  team_spend_7d_nanos bigint;
  team_spend_30d_nanos bigint;
  team_requests_1h bigint;
  team_requests_24h bigint;
  team_created_at timestamptz;
  team_tier text;
  team_balance_nanos bigint;
  team_reserved_nanos bigint;

  -- Key aggregates
  key_name text;
  key_created_at timestamptz;
  key_total_requests bigint;
  key_total_spend_nanos bigint;
begin
  base_model := gateway_context_access.model;
  -- hard requirement: key must be provided
  if gateway_context_access.api_key_id is null then
    raise exception using errcode = '22023', message = 'missing_api_key', detail = 'api_key_id is required';
  end if;

  -- Check if model is a preset (starts with @)
  if base_model like '@%' then
    is_preset := true;
    preset_name := substring(base_model from 2); -- Remove @ prefix

    -- Fetch preset configuration. Qualified references resolve a
    -- public publisher globally; unqualified references remain workspace-local.
    if position('/' in preset_name) > 0 then
      preset_publisher := split_part(preset_name, '/', 1);
      preset_name := substring(preset_name from position('/' in preset_name) + 1);
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'slug', p.slug, 'description', p.description,
        'config', p.config, 'visibility', p.visibility, 'publisher', w.publisher_handle
      ) into preset_data
      from public.presets p
      join public.workspaces w on w.id = p.workspace_id
      where p.archived_at is null and lower(p.slug) = lower(preset_name)
        and p.visibility = 'public'
        and true
        and (lower(w.publisher_handle) = lower(preset_publisher) or exists (select 1 from public.workspace_publisher_handle_aliases alias where alias.workspace_id = w.id and alias.handle = lower(preset_publisher)))
      limit 1;
    else
      select jsonb_build_object(
        'id', p.id, 'name', p.name,
        'slug', coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', '')),
        'description', p.description, 'config', p.config, 'visibility', p.visibility
      ) into preset_data
      from public.presets p
      where p.archived_at is null and lower(coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', ''))) = lower(preset_name)
        and p.workspace_id = gateway_context_access.workspace_id
        and (
          p.visibility in ('public', 'team')
          or p.created_by = (
            select ak.created_by from public.keys ak
            where ak.id = gateway_context_access.api_key_id
              and ak.workspace_id = gateway_context_access.workspace_id
              and ak.status = 'active'
          )
        )
      limit 1;
    end if;

    if preset_data is null then
      raise exception using
        errcode = '22023',
        message = 'preset_not_found',
        detail = format('Preset "%s" not found or not accessible', preset_name);
    end if;

    -- Extract model from preset config (fallback to default/default_model/model/first models entry)
    base_model := coalesce(
      preset_data->'config'->>'defaultModel',
      preset_data->'config'->>'default_model',
      preset_data->'config'->>'model',
      preset_data->'config'->'models'->>0,
      preset_data->'config'->'allowedModels'->>0,
      preset_data->'config'->'allowed_models'->>0
    );

    if base_model is null then
      raise exception using
        errcode = '22023',
        message = 'preset_no_model',
        detail = format('Preset "%s" has no model configured', preset_name);
    end if;
  end if;

  -- Resolve alias/model indirection:
  -- 1) explicit alias table (`v2_model_aliases`)
  -- 2) provider-scoped slug form (`provider/provider_model_slug`)
  resolved_model := coalesce(
    (
      select a.api_model_id
      from (select alias_slug, model_slug as api_model_id, enabled as is_enabled from public.v2_model_aliases) a
      where a.alias_slug = base_model
        and a.is_enabled = true
        and a.api_model_id is not null
      limit 1
    ),
    (
      select m.api_model_id
      from (select provider_model_id as provider_api_model_id, provider_slug as provider_id, model_slug as api_model_id, model_slug as model_id, provider_model_slug, routing_enabled as is_active_gateway, status as routing_status, input_modalities, output_modalities, context_length, max_output_tokens, effective_from, effective_to, created_at, updated_at from public.v2_model_provider_routes) m
      where position('/' in base_model) > 0
        and m.provider_id = split_part(base_model, '/', 1)
        and m.provider_model_slug = regexp_replace(base_model, '^[^/]+/', '')
        and m.is_active_gateway
        and (m.effective_from is null or m.effective_from <= now() at time zone 'utc')
        and (m.effective_to   is null or (now() at time zone 'utc') < m.effective_to)
      order by coalesce(m.effective_from, to_timestamp(0)) desc, m.provider_api_model_id
      limit 1
    ),
    base_model
  );

  -- validate key row, status, and team
  select
    (k.status = 'active'),
    (k.workspace_id = gateway_context_access.workspace_id),
    k.soft_blocked,
    k.daily_limit_requests,   k.weekly_limit_requests,   k.monthly_limit_requests,
    k.daily_limit_cost_nanos, k.weekly_limit_cost_nanos, k.monthly_limit_cost_nanos
  into
    v_key_active,
    v_key_team_ok,
    v_soft_blocked,
    v_day_req_limit, v_wk_req_limit, v_mo_req_limit,
    v_day_cost_limit, v_wk_cost_limit, v_mo_cost_limit
  from public.keys k
  where k.id = gateway_context_access.api_key_id
  limit 1;

  if v_key_active is null then
    raise exception using errcode = '22023', message = 'api_key_not_found', detail = 'key id does not exist';
  end if;
  if not v_key_team_ok then
    raise exception using errcode = '22023', message = 'api_key_wrong_team', detail = 'key does not belong to provided workspace_id';
  end if;
  if not v_key_active then
    raise exception using errcode = '22023', message = 'api_key_inactive', detail = 'key status is not active';
  end if;

  key_status := jsonb_build_object('ok', true, 'mode', 'first_party');

  -- credit check
  credit_status :=
    coalesce((
      select case
        when greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0) >= min_balance_nanos then
          jsonb_build_object(
            'ok', true,
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
        else
          jsonb_build_object(
            'ok', false,
            'reason', 'insufficient_funds',
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
      end
      from public.wallets w
      where w.workspace_id = gateway_context_access.workspace_id
      limit 1
    ), jsonb_build_object('ok', false, 'reason', 'wallet_missing'));

  -- per-key limits (requests + cost)
  -- Unlimited keys need no history read. Unknown telemetry stays NULL.
  if greatest(v_day_req_limit, v_wk_req_limit, v_mo_req_limit,
      v_day_cost_limit, v_wk_cost_limit, v_mo_cost_limit) > 0 then
  select
    count(*) filter (where gr.created_at >= day_start)                                  as used_day_reqs,
    count(*) filter (where gr.created_at >= week_start)                                 as used_wk_reqs,
    count(*) filter (where gr.created_at >= month_start)                                as used_mo_reqs,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= day_start), 0)::bigint   as used_day_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= week_start), 0)::bigint  as used_wk_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= month_start), 0)::bigint as used_mo_cost
  into
    used_day_reqs, used_wk_reqs, used_mo_reqs,
    used_day_cost, used_wk_cost, used_mo_cost
  from public.gateway_requests gr
  where gr.key_id  = gateway_context_access.api_key_id
    and gr.workspace_id = gateway_context_access.workspace_id
    and gr.success is true
    and gr.created_at >= least(week_start, month_start);
  end if;

  if v_soft_blocked then
    within_limits := false;
    limit_reason := 'key_limit_soft_blocked';
    limit_metric := 'soft_blocked';
  end if;
  if within_limits and v_day_req_limit > 0 and used_day_reqs >= v_day_req_limit then
    within_limits := false;
    limit_reason := 'daily_request_limit_reached';
    limit_window := 'daily';
    limit_metric := 'requests';
    current_value := used_day_reqs;
    limit_value := v_day_req_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_req_limit > 0 and used_wk_reqs >= v_wk_req_limit then
    within_limits := false;
    limit_reason := 'weekly_request_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'requests';
    current_value := used_wk_reqs;
    limit_value := v_wk_req_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_req_limit > 0 and used_mo_reqs >= v_mo_req_limit then
    within_limits := false;
    limit_reason := 'monthly_request_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'requests';
    current_value := used_mo_reqs;
    limit_value := v_mo_req_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;
  if within_limits and v_day_cost_limit > 0 and used_day_cost >= v_day_cost_limit then
    within_limits := false;
    limit_reason := 'daily_cost_limit_reached';
    limit_window := 'daily';
    limit_metric := 'cost';
    current_value := used_day_cost;
    limit_value := v_day_cost_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_cost_limit > 0 and used_wk_cost >= v_wk_cost_limit then
    within_limits := false;
    limit_reason := 'weekly_cost_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'cost';
    current_value := used_wk_cost;
    limit_value := v_wk_cost_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_cost_limit > 0 and used_mo_cost >= v_mo_cost_limit then
    within_limits := false;
    limit_reason := 'monthly_cost_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'cost';
    current_value := used_mo_cost;
    limit_value := v_mo_cost_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;

  key_limit_status :=
    jsonb_build_object(
      'ok', within_limits,
      'reason', limit_reason,
      'limit_window', limit_window,
      'limit_metric', limit_metric,
      'current_value', current_value,
      'limit_value', limit_value,
      'reset_at', to_jsonb(limit_reset_at),
      'now', to_jsonb(now_utc),
      'buckets', jsonb_build_object(
        'daily', jsonb_build_object(
          'window_start', to_jsonb(day_start),
          'requests_used', used_day_reqs,
          'requests_limit', v_day_req_limit,
          'cost_used_nanos', used_day_cost,
          'cost_limit_nanos', v_day_cost_limit
        ),
        'weekly', jsonb_build_object(
          'window_start', to_jsonb(week_start),
          'requests_used', used_wk_reqs,
          'requests_limit', v_wk_req_limit,
          'cost_used_nanos', used_wk_cost,
          'cost_limit_nanos', v_wk_cost_limit
        ),
        'monthly', jsonb_build_object(
          'window_start', to_jsonb(month_start),
          'requests_used', used_mo_reqs,
          'requests_limit', v_mo_req_limit,
          'cost_used_nanos', used_mo_cost,
          'cost_limit_nanos', v_mo_cost_limit
        )
      )
    );

  -- ============================================================================
  -- TEAM & KEY ENRICHMENT (Wide Event Context for Observability)
  -- Purpose: Gather user/team context for comprehensive logging (loggingsucks.com pattern)
  -- ============================================================================
  -- Team metadata & wallet
  select
    t.created_at,
    coalesce(t.tier, 'basic'),
    greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
    coalesce(w.reserved_nanos, 0)::bigint
  into
    team_created_at,
    team_tier,
    team_balance_nanos,
    team_reserved_nanos
  from public.workspaces t
  left join public.wallets w on w.workspace_id = t.id
  where t.id = gateway_context_access.workspace_id
  limit 1;

  -- Historical analytics belong in reporting, not request admission.
  -- Leave their enrichment fields NULL instead of scanning lifetime logs.

  -- Calculate tier using calendar-month qualification + lock-window grace.
  -- Function maintains team tier/counters in database when state changes.
  team_tier := public.calculate_tier_with_grace(gateway_context_access.workspace_id, team_spend_30d_nanos);

  team_enrichment := jsonb_build_object(
    'tier', team_tier,
    'created_at', to_jsonb(team_created_at),
    'account_age_days', extract(epoch from (now_utc - team_created_at)) / 86400,
    'balance_nanos', team_balance_nanos,
    'available_nanos', team_balance_nanos,
    'reserved_nanos', team_reserved_nanos,
    'balance_usd', round((team_balance_nanos::numeric / 1000000000.0)::numeric, 2),
    'balance_is_low', team_balance_nanos < min_balance_nanos,
    'total_requests', team_total_requests,
    'total_spend_nanos', team_total_spend_nanos,
    'total_spend_usd', round((team_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_24h_nanos', team_spend_24h_nanos,
    'spend_24h_usd', round((team_spend_24h_nanos::numeric / 1000000000.0)::numeric, 4),
    'spend_7d_nanos', team_spend_7d_nanos,
    'spend_7d_usd', round((team_spend_7d_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_30d_nanos', team_spend_30d_nanos,
    'spend_30d_usd', round((team_spend_30d_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_1h', team_requests_1h,
    'requests_24h', team_requests_24h
  );

  -- Key metadata & aggregates
  select
    k.name,
    k.created_at
  into
    key_name,
    key_created_at
  from public.keys k
  where k.id = gateway_context_access.api_key_id
  limit 1;

  -- Lifetime key analytics are not required to authenticate or enforce limits.

  key_enrichment := jsonb_build_object(
    'name', key_name,
    'created_at', to_jsonb(key_created_at),
    'key_age_days', extract(epoch from (now_utc - key_created_at)) / 86400,
    'total_requests', key_total_requests,
    'total_spend_nanos', key_total_spend_nanos,
    'total_spend_usd', round((key_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_today', used_day_reqs,
    'spend_today_nanos', used_day_cost,
    'spend_today_usd', round((used_day_cost::numeric / 1000000000.0)::numeric, 4),
    'daily_limit_pct', case
      when v_day_req_limit > 0 then round((used_day_reqs::numeric / v_day_req_limit::numeric * 100)::numeric, 1)
      else null
    end
  );

  providers := '[]'::jsonb;
  pricing := '{}'::jsonb;

  return jsonb_build_object(
    'workspace_id', gateway_context_access.workspace_id,
    'resolved_model', resolved_model,
    'preset', preset_data,
    'key_ok', key_status,
    'key_limit_ok', key_limit_status,
    'credit_ok', credit_status,
    'providers', providers,
    'pricing', pricing,
    'team_enrichment', team_enrichment,
    'key_enrichment', key_enrichment
  );
end;

$function$;

GRANT EXECUTE ON FUNCTION "private"."gateway_context_access"(uuid, text, text, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "private"."gateway_context_access"(uuid, text, text, uuid) FROM PUBLIC;

-- source: supabase/schemas/private/functions/guard_model_replacement_cycle.sql
CREATE OR REPLACE FUNCTION private.guard_model_replacement_cycle()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_current text := new.replacement_model_slug;
  v_seen text[] := array[new.model_slug];
begin
  -- Serialise successor edits so two concurrent writes cannot close a loop
  -- that neither sees on its own.
  perform pg_advisory_xact_lock(hashtext('v2_models.replacement_model_slug'));
  -- Follow the chain, remembering every model visited. Reaching the edited
  -- model again is a loop; reaching any other visited model means the chain
  -- loops further on without this model, so the walk stops there. Chains of
  -- any length that end are accepted.
  while v_current is not null loop
    if v_current = new.model_slug then
      raise exception 'recommended successor % would loop back to %', new.replacement_model_slug, new.model_slug
        using errcode = '23514';
    end if;
    exit when v_current = any (v_seen);
    v_seen := v_seen || v_current;
    select model.replacement_model_slug into v_current
    from public.v2_models model
    where model.model_slug = v_current;
  end loop;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."guard_model_replacement_cycle"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/invalidate_routing_catalogue.sql
CREATE OR REPLACE FUNCTION private.invalidate_routing_catalogue()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  update private.routing_catalogue_revision set revision=revision+1 where singleton;
  return null;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."invalidate_routing_catalogue"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/is_valid_time_zone.sql
CREATE OR REPLACE FUNCTION private.is_valid_time_zone (
  p_time_zone text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  -- Names from the server's IANA database. The posix/ and right/ trees and the server-local
  -- aliases are not zones a user picks. Case-sensitive, as browsers report them.
  select p_time_zone is not null
    and pg_catalog.char_length(p_time_zone) between 1 and 64
    and p_time_zone !~ '^(posix|right)/'
    and p_time_zone not in ('posixrules', 'localtime', 'Factory')
    and exists (
      select 1
      from pg_catalog.pg_timezone_names zone
      where zone.name = p_time_zone
    );
$function$;

COMMENT ON FUNCTION "private"."is_valid_time_zone"(text) IS 'True when the text is an IANA time zone name the server knows (pg_timezone_names), excluding the posix/ and right/ trees and server-local aliases. Used by spend rule and billing time zone validation.';

REVOKE ALL ON FUNCTION "private"."is_valid_time_zone"(text) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."is_valid_time_zone"(text) TO "service_role";

-- source: supabase/schemas/private/functions/materialize_free_admission_usage.sql
CREATE OR REPLACE FUNCTION private.materialize_free_admission_usage()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
    admission jsonb := new.detail_metadata #> '{routing_diagnostics,freeQuota}';
    owner uuid;
    day date;
    used integer;
begin
    if admission is null or admission ->> 'admitted' is distinct from 'true' then return new; end if;
    -- Audit metadata is advisory. Invalid reporting must not break request audit.
    begin
        owner := (admission ->> 'ownerId')::uuid;
        day := (admission ->> 'utcDay')::date;
        used := (admission ->> 'used')::integer;
    exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format or numeric_value_out_of_range then
        return new;
    end;
    if owner is null or day is null or used is null or used not between 1 and 1500 then return new; end if;
    -- Cumulative admission sequence makes duplicate and out-of-order audit delivery
    -- idempotent and recovers earlier missing audit events on the next delivery.
    insert into public.free_model_usage_daily(owner_id, usage_date, included_requests)
    values (owner, day, used)
    on conflict (owner_id, usage_date) do update
      set included_requests = excluded.included_requests, updated_at = now()
      where public.free_model_usage_daily.included_requests < excluded.included_requests;
    return new;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."materialize_free_admission_usage"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/mobile_iso_week_monday.sql
CREATE OR REPLACE FUNCTION private.mobile_iso_week_monday (
  p_week text
)
  RETURNS date
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  -- The Monday that starts ISO week p_week, written "2026-W43", or null when there is no such
  -- week (a malformed value, or week 53 of a year with 52).
  select case when candidate.monday is not null and to_char(candidate.monday, 'IYYY-"W"IW') = p_week then candidate.monday end
  from (
    select case
      when p_week ~ '^[0-9]{4}-W(0[1-9]|[1-4][0-9]|5[0-3])$' and left(p_week, 4) >= '1000' then
        make_date(left(p_week, 4)::integer, 1, 4)
          - (extract(isodow from make_date(left(p_week, 4)::integer, 1, 4))::integer - 1)
          + (right(p_week, 2)::integer - 1) * 7
    end as monday
  ) candidate;
$function$;

REVOKE ALL ON FUNCTION "private"."mobile_iso_week_monday"(text) FROM PUBLIC;

-- source: supabase/schemas/private/functions/mobile_push_category.sql
CREATE OR REPLACE FUNCTION private.mobile_push_category (
  p_kind text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  -- The category of a catalogue push: the key users switch off in
  -- mobile_notification_preferences.categories, and the Android channel from channel scheme 2.
  select case
    when p_kind in ('model_released', 'gateway_available') then 'new-models'
    when p_kind in ('price_changed', 'provider_added', 'provider_launched') then 'prices-providers'
    when p_kind = 'deprecation_announced' then 'deprecations'
  end;
$function$;

REVOKE ALL ON FUNCTION "private"."mobile_push_category"(text) FROM PUBLIC;

-- source: supabase/schemas/private/functions/mobile_push_compact_number.sql
CREATE OR REPLACE FUNCTION private.mobile_push_compact_number (
  p_value numeric
)
  RETURNS text
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  -- Counts for push text: whole numbers with commas below 100,000 ("12,340"), then "124K",
  -- "18.2M", "124M", "1.2B", with one decimal below 100 of a unit.
  select case
    when n.value < 100000 then to_char(n.value, 'FM999,990')
    when n.value < 999500 then to_char(round(n.value / 1e3), 'FM990') || 'K'
    when n.value < 99950000 then trim_scale(round(n.value / 1e6, 1))::text || 'M'
    when n.value < 999500000 then to_char(round(n.value / 1e6), 'FM990') || 'M'
    when n.value < 99950000000 then trim_scale(round(n.value / 1e9, 1))::text || 'B'
    else to_char(round(n.value / 1e9), 'FM999,999,990') || 'B'
  end
  from (select round(greatest(coalesce(p_value, 0), 0)) as value) n;
$function$;

REVOKE ALL ON FUNCTION "private"."mobile_push_compact_number"(numeric) FROM PUBLIC;

-- source: supabase/schemas/private/functions/mobile_push_digest_facts.sql
CREATE OR REPLACE FUNCTION private.mobile_push_digest_facts (
  p_user_id   uuid,
  p_from      timestamp with time zone,
  p_to        timestamp with time zone,
  p_time_zone text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
-- What one user's weekly digest reports, summed over every workspace they own or administer:
-- spend, requests and tokens from p_from up to p_to, spend over the same local span a week
-- earlier, the workspaces with usage (most requests first, then spend), the model with the
-- most requests, and the releases their rules match. The lead workspace is the most active
-- one, or the one the user opened last when none had usage.
with spans as (
  select
    ((p_from at time zone p_time_zone) - interval '7 days') at time zone p_time_zone as previous_from,
    ((p_to at time zone p_time_zone) - interval '7 days') at time zone p_time_zone as previous_to
),
administered as (
  select m.workspace_id as id from public.workspace_members m
  where m.user_id = p_user_id and m.role::text in ('owner', 'admin')
  union
  select w.id from public.workspaces w where w.owner_user_id = p_user_id
),
usage as materialized (
  select
    w.id,
    w.name,
    w.created_at,
    member.last_accessed_at,
    private.mobile_week_usage(w.id, p_from, p_to, p_time_zone) as current_week,
    private.mobile_week_usage(w.id, spans.previous_from, spans.previous_to, p_time_zone) as previous_week
  from administered a
  join public.workspaces w on w.id = a.id
  left join public.workspace_members member on member.workspace_id = w.id and member.user_id = p_user_id
  cross join spans
),
ranked as (
  select
    u.*,
    (u.current_week ->> 'requests')::numeric as requests,
    (u.current_week ->> 'spendNanos')::numeric as spend_nanos,
    row_number() over (
      order by (u.current_week ->> 'requests')::numeric desc, (u.current_week ->> 'spendNanos')::numeric desc,
        u.last_accessed_at desc nulls last, u.created_at, u.id
    ) as position
  from usage u
),
models as (
  select model ->> 'modelId' as model_id, sum((model ->> 'requests')::numeric) as requests, sum((model ->> 'spendNanos')::numeric) as spend_nanos
  from usage u
  cross join lateral jsonb_array_elements(u.current_week -> 'models') model
  group by 1
),
releases as (
  select private.mobile_week_releases(p_user_id, p_from, p_to) as items
)
select jsonb_build_object(
  'workspaceCount', (select count(*) from ranked),
  'lead', (select jsonb_build_object('id', r.id, 'name', r.name) from ranked r where r.position = 1),
  'activeWorkspaces', coalesce((
    select jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name, 'requests', r.requests, 'spendNanos', r.spend_nanos) order by r.position)
    from ranked r where r.requests > 0 or r.spend_nanos > 0
  ), '[]'::jsonb),
  'requests', (select coalesce(sum(r.requests), 0) from ranked r),
  'spendNanos', (select coalesce(sum(r.spend_nanos), 0) from ranked r),
  'previousSpendNanos', (select coalesce(sum((r.previous_week ->> 'spendNanos')::numeric), 0) from ranked r),
  'tokens', (select coalesce(sum((r.current_week ->> 'tokens')::numeric), 0) from ranked r),
  'inputTokens', (select coalesce(sum((r.current_week ->> 'inputTokens')::numeric), 0) from ranked r),
  'outputTokens', (select coalesce(sum((r.current_week ->> 'outputTokens')::numeric), 0) from ranked r),
  'topModel', (
    select jsonb_build_object('id', m.model_id, 'name', coalesce(catalogue.name, m.model_id), 'requests', m.requests)
    from models m
    left join public.v2_models catalogue on catalogue.model_slug = m.model_id
    order by m.requests desc, m.spend_nanos desc, m.model_id
    limit 1
  ),
  'releaseCount', jsonb_array_length(releases.items),
  'releaseNames', coalesce((
    select jsonb_agg(item.value ->> 'name' order by item.position)
    from jsonb_array_elements(releases.items) with ordinality as item(value, position)
    where item.position <= 2
  ), '[]'::jsonb)
)
from releases;
$function$;

REVOKE ALL ON FUNCTION "private"."mobile_push_digest_facts"(uuid, timestamp with time zone, timestamp with time zone, text) FROM PUBLIC;

-- source: supabase/schemas/private/functions/mobile_push_digest_message.sql
CREATE OR REPLACE FUNCTION private.mobile_push_digest_message (
  p_facts jsonb
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  -- The weekly digest's title and body from private.mobile_push_digest_facts, or null when the
  -- week had neither usage nor a release the user's rules match. Money is in US dollars
  -- ("$42.18") and counts are compact ("18.2M").
  --   * Usage: "Your Phaseo week: $42.18 spent, up 12%", with the change only when both weeks
  --     had spend, and "12,340 requests · 18.2M tokens · Top model: Claude Sonnet 5.5 · 6 new
  --     models launched". A user with more than one workspace is told which were active, most
  --     active first: "Acme: …" or "Acme and 2 other workspaces: …".
  --   * No usage: "Your Phaseo week" and "A quiet week: 6 new models launched, including A and B".
  select case
    when f.requests = 0 and f.spend_nanos = 0 and f.releases = 0 then null
    when f.requests = 0 and f.spend_nanos = 0 then jsonb_build_object(
      'title', 'Your Phaseo week',
      'body', 'A quiet week: ' || f.releases
        || case when f.releases = 1 then ' new model launched, ' else ' new models launched, ' end
        || case
          when f.releases = 1 or f.second_release is null then f.first_release
          when f.releases = 2 then f.first_release || ' and ' || f.second_release
          else 'including ' || f.first_release || ' and ' || f.second_release
        end)
    else jsonb_build_object(
      'title', 'Your Phaseo week' || case when f.spend_nanos > 0 then ': ' || f.money || ' spent' || coalesce(', ' || f.change, '') else '' end,
      'body', f.scope || array_to_string(f.parts, ' · '))
  end
  from (
    select
      t.requests,
      t.spend_nanos,
      t.releases,
      coalesce(t.release_names ->> 0, 'new models') as first_release,
      t.release_names ->> 1 as second_release,
      case
        when t.spend_nanos < 5000000 then 'under $0.01'
        else '$' || to_char(round(t.spend_nanos / 1e9, 2), 'FM999,999,999,990.00')
      end as money,
      case when t.spend_nanos > 0 and t.previous_spend_nanos > 0 then
        case sign(change.percent)
          when 1 then 'up ' || to_char(change.percent, 'FM999,999,990') || '%'
          when -1 then 'down ' || to_char(-change.percent, 'FM999,999,990') || '%'
          else 'same as last week'
        end
      end as change,
      case when t.workspace_count > 1 and t.active_count > 0 then
        coalesce(nullif(btrim(t.active -> 0 ->> 'name'), ''), 'Your workspace')
          || case
            when t.active_count = 2 then ' and 1 other workspace'
            when t.active_count > 2 then ' and ' || (t.active_count - 1) || ' other workspaces'
            else ''
          end
          || ': '
      else '' end as scope,
      array_remove(array[
        private.mobile_push_compact_number(t.requests) || case when t.requests = 1 then ' request' else ' requests' end,
        case when round(t.tokens) > 0 then private.mobile_push_compact_number(t.tokens) || case when round(t.tokens) = 1 then ' token' else ' tokens' end end,
        'Top model: ' || t.top_model,
        case when t.releases > 0 then t.releases || case when t.releases = 1 then ' new model launched' else ' new models launched' end end
      ], null) as parts
    from (
      select
        coalesce((p_facts ->> 'requests')::numeric, 0) as requests,
        coalesce((p_facts ->> 'spendNanos')::numeric, 0) as spend_nanos,
        coalesce((p_facts ->> 'previousSpendNanos')::numeric, 0) as previous_spend_nanos,
        coalesce((p_facts ->> 'tokens')::numeric, 0) as tokens,
        coalesce((p_facts ->> 'workspaceCount')::integer, 0) as workspace_count,
        coalesce(p_facts -> 'activeWorkspaces', '[]'::jsonb) as active,
        coalesce(jsonb_array_length(p_facts -> 'activeWorkspaces'), 0) as active_count,
        nullif(btrim(p_facts -> 'topModel' ->> 'name'), '') as top_model,
        coalesce((p_facts ->> 'releaseCount')::integer, 0) as releases,
        coalesce(p_facts -> 'releaseNames', '[]'::jsonb) as release_names
    ) t
    cross join lateral (
      select round((t.spend_nanos - t.previous_spend_nanos) * 100 / nullif(t.previous_spend_nanos, 0)) as percent
    ) change
  ) f;
$function$;

REVOKE ALL ON FUNCTION "private"."mobile_push_digest_message"(jsonb) FROM PUBLIC;

-- source: supabase/schemas/private/functions/mobile_push_digest_week.sql
CREATE OR REPLACE FUNCTION private.mobile_push_digest_week (
  p_time_zone text,
  p_now       timestamp with time zone
)
  RETURNS TABLE (
    due         boolean,
    iso_week    text,
    week_start  timestamp with time zone,
    week_cutoff timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  -- Where p_now falls for the weekly digest in p_time_zone. The digest is due from 18:00 on
  -- Sunday until 06:00 on Monday, local time, so a late or missed run still sends it that
  -- evening or night. It covers the ISO week from Monday 00:00 up to that Sunday 18:00. Moving
  -- the clock on six hours turns the window into the first twelve hours of the next ISO week.
  select
    shifted.local_time < monday.next_start + interval '12 hours',
    to_char(monday.next_start - interval '7 days', 'IYYY-"W"IW'),
    (monday.next_start - interval '7 days') at time zone p_time_zone,
    (monday.next_start - interval '6 hours') at time zone p_time_zone
  from (select (p_now at time zone p_time_zone) + interval '6 hours' as local_time) shifted
  cross join lateral (select date_trunc('week', shifted.local_time) as next_start) monday;
$function$;

REVOKE ALL ON FUNCTION "private"."mobile_push_digest_week"(text, timestamp with time zone) FROM PUBLIC;

-- source: supabase/schemas/private/functions/mobile_push_group_key.sql
CREATE OR REPLACE FUNCTION private.mobile_push_group_key (
  p_kind          text,
  p_lab_slug      text,
  p_provider_slug text,
  p_model_slug    text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  -- Pushes for one device that share a key and are due together are sent as one: a lab's
  -- releases and models reaching Phaseo, a provider newly serving several models, or repeated
  -- price changes to one model. Other kinds are always sent alone.
  select case
    when p_kind in ('model_released', 'gateway_available') and p_lab_slug is not null then 'release:' || p_lab_slug
    when p_kind = 'provider_added' and p_provider_slug is not null then 'provider:' || p_provider_slug
    when p_kind = 'price_changed' and p_model_slug is not null then 'price:' || p_model_slug
  end;
$function$;

REVOKE ALL ON FUNCTION "private"."mobile_push_group_key"(text, text, text, text) FROM PUBLIC;

-- source: supabase/schemas/private/functions/mobile_push_group_message.sql
CREATE OR REPLACE FUNCTION private.mobile_push_group_message (
  p_group_key text,
  p_items     jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
-- Writes the push for one group. p_items lists every event in it, oldest first, including those
-- already sent to the device since midnight UTC: the new push replaces that notification on
-- screen, so it counts them all. Items carry kind, modelSlug, labSlug, providerSlug, modelName,
-- labName, providerName, title, body and href. Returns kind, modelSlug, title, body, href and
-- count (models for release and provider groups, changes for price groups).
--   one        the event as written.
--   2 or 3     every model named: "OpenAI released GPT-6 Astra and GPT-6 Astra Pro".
--   4 or more  counted, the first three named in the body, and the lab or provider page opened:
--              "DeepSeek released 12 models", "DeepSeek V5, V5 Lite, V5 Coder and 9 more".
-- Names after the first drop a leading lab name when the model is from the first model's lab.
declare
  v_size integer := coalesce(jsonb_array_length(p_items), 0);
  v_first jsonb := p_items -> 0;
  v_last jsonb := p_items -> (coalesce(jsonb_array_length(p_items), 0) - 1);
  v_scope text := split_part(coalesce(p_group_key, ''), ':', 1);
  v_names text[];
  v_count integer;
  v_joined text;
  v_released boolean;
  v_on_phaseo boolean;
  v_owner text;
begin
  if v_size = 0 then
    return null;
  end if;

  if v_size > 1 and v_scope = 'price' then
    return jsonb_build_object(
      'kind', 'price_changed',
      'modelSlug', v_last ->> 'modelSlug',
      'title', left(coalesce(v_last ->> 'modelName', v_last ->> 'modelSlug') || ' prices changed', 300),
      'body', left(rtrim(v_last ->> 'title', '.') || coalesce(' at ' || (v_last ->> 'providerName'), '') || '. '
        || (v_size - 1) || case when v_size = 2 then ' other change today.' else ' other changes today.' end, 1000),
      'href', v_last ->> 'href',
      'count', v_size);
  end if;

  if v_size > 1 and v_scope in ('release', 'provider') then
    -- Each model once, in the order it first appeared.
    select array_agg(n.name order by n.ord), count(*)::integer
      into v_names, v_count
    from (
      select distinct on (coalesce(i.item ->> 'modelSlug', i.item ->> 'modelName'))
        i.ord,
        case
          when i.ord > 1 and (i.item ->> 'labSlug') = (v_first ->> 'labSlug') and nullif(i.item ->> 'labName', '') is not null
            and char_length(i.item ->> 'modelName') > char_length(i.item ->> 'labName') + 1
            and left(i.item ->> 'modelName', char_length(i.item ->> 'labName') + 1) = (i.item ->> 'labName') || ' '
            then substr(i.item ->> 'modelName', char_length(i.item ->> 'labName') + 2)
          else coalesce(i.item ->> 'modelName', i.item ->> 'modelSlug')
        end as name
      from jsonb_array_elements(p_items) with ordinality as i(item, ord)
      order by coalesce(i.item ->> 'modelSlug', i.item ->> 'modelName'), i.ord
    ) n;

    if v_count > 1 then
      v_joined := case
        when v_count <= 3 then array_to_string(v_names[1:v_count - 1], ', ') || ' and ' || v_names[v_count]
        else array_to_string(v_names[1:3], ', ') || ' and ' || (v_count - 3) || ' more'
      end;

      if v_scope = 'release' then
        v_owner := coalesce(nullif(v_first ->> 'labName', ''), v_first ->> 'labSlug');
        select bool_or(i ->> 'kind' = 'model_released'),
               bool_and(i ->> 'kind' = 'gateway_available' or i ->> 'body' = 'You can use it on Phaseo now.')
          into v_released, v_on_phaseo
        from jsonb_array_elements(p_items) as i;
        return jsonb_build_object(
          'kind', case when v_released then 'model_released' else 'gateway_available' end,
          'modelSlug', null,
          'title', left(case
            when v_released and v_count <= 3 then v_owner || ' released ' || v_joined
            when v_released then v_owner || ' released ' || v_count || ' models'
            when v_count <= 3 then v_joined || ' are now on Phaseo'
            else v_count || ' ' || v_owner || ' models are now on Phaseo'
          end, 300),
          'body', left(case
            when v_count > 3 then v_joined
            when not v_released then 'You can now use them through Phaseo.'
            when v_on_phaseo then 'You can use them on Phaseo now.'
            else 'See the details on Phaseo.'
          end, 1000),
          'href', '/organisations/' || (v_first ->> 'labSlug'),
          'count', v_count);
      end if;

      v_owner := coalesce(nullif(v_first ->> 'providerName', ''), v_first ->> 'providerSlug');
      return jsonb_build_object(
        'kind', 'provider_added',
        'modelSlug', null,
        'title', left(case
          when v_count <= 3 then v_joined || ' are now available from ' || v_owner
          else v_count || ' models are now available from ' || v_owner
        end, 300),
        'body', left(case when v_count <= 3 then v_owner || ' is now a provider for them on Phaseo.' else v_joined end, 1000),
        'href', '/api-providers/' || (v_first ->> 'providerSlug'),
        'count', v_count);
    end if;
  end if;

  -- One event, or one model told about twice: the newest event as written.
  return jsonb_build_object('kind', v_last ->> 'kind', 'modelSlug', v_last ->> 'modelSlug', 'title', v_last ->> 'title',
    'body', v_last ->> 'body', 'href', v_last ->> 'href', 'count', 1);
end;
$function$;

REVOKE ALL ON FUNCTION "private"."mobile_push_group_message"(text, jsonb) FROM PUBLIC;

-- source: supabase/schemas/private/functions/mobile_week_releases.sql
CREATE OR REPLACE FUNCTION private.mobile_week_releases (
  p_user_id uuid,
  p_from    timestamp with time zone,
  p_to      timestamp with time zone
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
-- Models released, or newly available on Phaseo, from p_from up to but not including p_to that
-- one of the user's enabled notify rules matches and none of their enabled mute rules does, as
-- fan-out would judge them today: each model once, newest first. Models no longer public are
-- left out.
with events as (
  select
    e.kind,
    e.model_slug,
    e.lab_slug,
    e.provider_slug,
    e.occurred_at,
    e.href,
    coalesce(nullif(btrim(e.payload ->> 'modelName'), ''), m.name, e.model_slug) as model_name,
    coalesce(nullif(btrim(e.payload ->> 'labName'), ''), lab.name, e.lab_slug) as lab_name,
    m.input_modalities,
    m.output_modalities,
    e.kind = 'gateway_available' or exists (
      select 1 from public.v2_model_provider_routes r
      where r.model_slug = e.model_slug and r.routing_enabled and r.access_scope = 'public'
        and not r.is_stealth and r.status in ('active', 'degraded')
    ) as on_phaseo
  from public.catalogue_notification_events e
  left join public.v2_models m on m.model_slug = e.model_slug
  left join public.v2_labs lab on lab.lab_slug = e.lab_slug
  where e.kind in ('model_released', 'gateway_available')
    and e.occurred_at >= p_from and e.occurred_at < p_to
    and e.model_slug is not null
    and public.catalog_model_is_public(e.model_slug)
),
matched as (
  select distinct on (ev.model_slug) ev.*
  from events ev
  where exists (
      select 1 from public.mobile_notification_rules r
      where r.user_id = p_user_id and r.action = 'notify'
        and private.mobile_notification_rule_matches(r, ev.kind, ev.lab_slug, ev.provider_slug, ev.model_slug,
          ev.input_modalities, ev.output_modalities, ev.on_phaseo)
    )
    and not exists (
      select 1 from public.mobile_notification_rules r
      where r.user_id = p_user_id and r.action = 'mute'
        and private.mobile_notification_rule_matches(r, ev.kind, ev.lab_slug, ev.provider_slug, ev.model_slug,
          ev.input_modalities, ev.output_modalities, ev.on_phaseo)
    )
  order by ev.model_slug, ev.occurred_at, ev.kind desc
)
select coalesce(jsonb_agg(jsonb_build_object(
  'modelId', matched.model_slug,
  'name', matched.model_name,
  'labId', matched.lab_slug,
  'labName', matched.lab_name,
  'kind', matched.kind,
  'occurredAt', to_char(matched.occurred_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
  'href', matched.href
) order by matched.occurred_at desc, matched.model_slug), '[]'::jsonb)
from matched;
$function$;

REVOKE ALL ON FUNCTION "private"."mobile_week_releases"(uuid, timestamp with time zone, timestamp with time zone) FROM PUBLIC;

-- source: supabase/schemas/private/functions/mobile_week_usage.sql
CREATE OR REPLACE FUNCTION private.mobile_week_usage (
  p_workspace_id uuid,
  p_from         timestamp with time zone,
  p_to           timestamp with time zone,
  p_time_zone    text,
  p_days         boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
-- One workspace's usage from p_from up to, but not including, p_to, summed from the exact usage
-- overview (public.get_private_usage_overview, which fills hours the rollup has yet to rebuild
-- from the requests): totals, every model with its requests and spend, most requests first,
-- and with p_days the same totals per local day in p_time_zone. Spend is in nanodollars.
with cells as materialized (
  select
    (overview.cell ->> 'bucket')::timestamp with time zone as bucket,
    nullif(overview.cell ->> 'modelId', '') as model_id,
    coalesce((overview.cell ->> 'requests')::numeric, 0) as requests,
    coalesce((overview.cell ->> 'successfulRequests')::numeric, 0) as successful_requests,
    coalesce((overview.cell ->> 'costNanos')::numeric, 0) as cost_nanos,
    coalesce((overview.cell ->> 'tokens')::numeric, 0) as tokens,
    coalesce((overview.cell ->> 'inputTokens')::numeric, 0) as input_tokens,
    coalesce((overview.cell ->> 'outputTokens')::numeric, 0) as output_tokens
  from jsonb_array_elements(case
    when p_to > p_from then public.get_private_usage_overview(p_workspace_id, p_from, p_to - interval '1 microsecond',
      case when p_days then 'day' end, p_time_zone)
    else '[]'::jsonb
  end) as overview(cell)
)
select jsonb_build_object(
  'requests', coalesce(sum(c.requests), 0),
  'successfulRequests', coalesce(sum(c.successful_requests), 0),
  'spendNanos', coalesce(sum(c.cost_nanos), 0),
  'tokens', coalesce(sum(c.tokens), 0),
  'inputTokens', coalesce(sum(c.input_tokens), 0),
  'outputTokens', coalesce(sum(c.output_tokens), 0),
  'models', coalesce((
    select jsonb_agg(jsonb_build_object('modelId', m.model_id, 'requests', m.requests, 'spendNanos', m.cost_nanos)
      order by m.requests desc, m.cost_nanos desc, m.model_id)
    from (
      select model.model_id, sum(model.requests) as requests, sum(model.cost_nanos) as cost_nanos
      from cells model
      where model.model_id is not null
      group by model.model_id
    ) m
  ), '[]'::jsonb),
  'days', coalesce((
    select jsonb_agg(jsonb_build_object(
      'date', d.day, 'requests', d.requests, 'successfulRequests', d.successful_requests, 'spendNanos', d.cost_nanos,
      'tokens', d.tokens, 'inputTokens', d.input_tokens, 'outputTokens', d.output_tokens
    ) order by d.day)
    from (
      select
        (day.bucket at time zone p_time_zone)::date as day,
        sum(day.requests) as requests,
        sum(day.successful_requests) as successful_requests,
        sum(day.cost_nanos) as cost_nanos,
        sum(day.tokens) as tokens,
        sum(day.input_tokens) as input_tokens,
        sum(day.output_tokens) as output_tokens
      from cells day
      where day.bucket is not null
      group by 1
    ) d
  ), '[]'::jsonb)
)
from cells c;
$function$;

REVOKE ALL ON FUNCTION "private"."mobile_week_usage"(uuid, timestamp with time zone, timestamp with time zone, text, boolean) FROM PUBLIC;

-- source: supabase/schemas/private/functions/project_routing_catalogue_row.sql
CREATE OR REPLACE FUNCTION private.project_routing_catalogue_row (
  input jsonb
)
  RETURNS jsonb
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) || jsonb_build_object('metadata',
  (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb)
   from jsonb_each(case when jsonb_typeof(input->'metadata')='object' then input->'metadata' else '{}'::jsonb end)
   where key in ('availability','self_serve','quantization_scheme','match','priority',
     'included_quantity','billing_timestamp_basis','time_windows')))
from jsonb_each(input) where key in (
 'model_slug','provider_slug','provider_model_id','variant_id','sku_id','sku_meter_id',
 'provider_region_id','service_tier_slug','capability_id','alias_slug','enabled',
 'status','hidden','access_scope','is_stealth','availability','provider_availability_status',
 'phaseo_status','available_from','effective_from','effective_to','released_at','retired_at',
 'routable','routing_enabled','route_variant_id','region','execution_region','data_region',
 'region_code','execution_supported','data_residency_supported','currency','operation',
 'billable','meter_key','unit','unit_quantity','price_nanos','meter_order','params',
 'regions','default_execution_regions','default_data_regions','provider_family_slug',
 'provider_model_slug','context_length','max_input_tokens','max_output_tokens',
 'input_modalities','output_modalities','zero_data_retention','credential_mode',
 'residency_mode','prompt_training_policy','data_policy_tier','data_policy_confidence',
 'data_policy_contract_mode','data_policy_variant','stream_cancellation_support',
 'stream_cancellation_stops_provider_billing','stream_cancellation_usage_recovery',
 'stream_cancellation_evidence_kind','benchmark_id','score_numeric','is_self_reported'
);
$function$;

