-- source: supabase/schemas/private/functions/prune_completed_analytics_outbox.sql
CREATE OR REPLACE FUNCTION private.prune_completed_analytics_outbox (
  p_batch_size integer DEFAULT 500
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  SET statement_timeout TO '10s'
  SET lock_timeout TO '500ms'
  AS $function$
declare v_deleted integer;
begin
  if p_batch_size is null or p_batch_size < 1 or p_batch_size > 5000 then
    raise exception 'Completed outbox prune batch size must be between 1 and 5000';
  end if;
  with candidates as (
    select request_event_id from public.v2_analytics_outbox
    where status = 'complete' and updated_at < now() - interval '7 days'
    order by updated_at, request_event_id
    limit p_batch_size for update skip locked
  )
  delete from public.v2_analytics_outbox outbox using candidates
  where outbox.request_event_id = candidates.request_event_id
    and outbox.status = 'complete' and outbox.updated_at < now() - interval '7 days';
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$function$;

GRANT EXECUTE ON FUNCTION "private"."prune_completed_analytics_outbox"(integer) TO "service_role";

COMMENT ON FUNCTION "private"."prune_completed_analytics_outbox"(integer) IS 'Bounded deletion of completed queue rows last updated more than seven days ago; preserves all usage sources and incomplete work.';

REVOKE ALL ON FUNCTION "private"."prune_completed_analytics_outbox"(integer) FROM PUBLIC;

-- source: supabase/schemas/private/functions/queue_spend_block_event.sql
CREATE OR REPLACE FUNCTION private.queue_spend_block_event (
  p_block_id uuid,
  p_state    text,
  p_now      timestamp with time zone
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Queues the spend_blocked event for a block that started (p_state 'started') or was lifted
-- ('lifted'): one email_outbox row deduped by spend_blocked:<block id>:<state>, so calling it twice
-- queues one event. Like spend_alert, the routed delivery job sends it to the rule's own
-- destinations or the workspace's spend_blocked routes, and the mobile push job sends it as a
-- money push (private.capture_workspace_notification_events). The rule id is in the payload, so
-- the event shows in the rule's history.
-- Returns the event id, or null when nothing was queued (no such block, a lift event for a block
-- that is still active, the workspace is being deleted, or the event already exists).
declare
  v_block record;
  v_label text;
  v_subject text;
  v_where text;
  v_so_far text;
  v_resets text;
  v_title text;
  v_message text;
  v_id uuid;
begin
  if p_block_id is null or p_state is null or p_state not in ('started', 'lifted') then
    raise exception 'invalid_spend_block_event';
  end if;

  select block.*, rule.name as rule_name, rule.period, rule.metric, workspace.name as workspace_name,
    workspace.owner_user_id, owner.email as owner_email, actor.email as lifted_by_email,
    coalesce(rule.time_zone, settings.billing_time_zone, 'UTC') as time_zone,
    case when block.scope_type = 'key' and block.scope_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then block.scope_id::uuid end as scope_key_id,
    case when block.scope_type = 'member' and block.scope_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then block.scope_id::uuid end as scope_user_id,
    case when block.scope_type = 'department' and block.scope_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then block.scope_id::uuid end as scope_department_id
    into v_block
  from public.workspace_spend_blocks block
  join public.workspaces workspace on workspace.id = block.workspace_id
  left join public.workspace_spend_rules rule on rule.id = block.rule_id
  left join public.workspace_settings settings on settings.workspace_id = block.workspace_id
  left join auth.users owner on owner.id = workspace.owner_user_id
  left join auth.users actor on actor.id = block.lifted_by
  where block.id = p_block_id;
  if not found or (p_state = 'lifted' and v_block.lifted_at is null) then
    return null;
  end if;

  v_label := private.spend_scope_label(v_block.workspace_id, v_block.scope_type, v_block.scope_id);
  v_subject := case v_block.scope_type
    when 'workspace' then 'The workspace'
    when 'key' then 'API key ''' || left(v_label, 60) || ''''
    when 'member' then v_label
    when 'department' then 'Department ''' || left(v_label, 60) || ''''
    when 'model' then v_label
    else 'Provider ' || v_block.scope_id
  end;
  v_where := case v_block.scope_type
    when 'workspace' then 'in this workspace'
    when 'key' then 'with this key'
    when 'member' then 'by this member (their keys and OAuth apps)'
    when 'department' then 'by this department'
    when 'model' then 'to this model'
    else 'routed to this provider'
  end;
  v_so_far := case v_block.period when 'day' then 'today' when 'week' then 'this week' when 'month' then 'this month' else 'this period' end;
  v_resets := case when v_block.resets_at is not null
    then to_char(v_block.resets_at at time zone v_block.time_zone, 'Mon FMDD, HH24:MI') || ' ' || v_block.time_zone end;

  if p_state = 'started' then
    v_title := 'Requests blocked: ' || left(coalesce(v_block.rule_name, 'spend rule'), 100);
    v_message := v_subject || ' has spent ' || private.workspace_push_usd(v_block.spend_nanos) || ' ' || v_so_far
      || ', past the ' || private.workspace_push_usd(v_block.limit_nanos) || ' block limit of '
      || coalesce('"' || left(v_block.rule_name, 100) || '"', 'a spend rule') || '. New requests ' || v_where
      || case when v_block.block_free_models then '' else ' to paid models' end
      || ' get a 429 until ' || coalesce(v_resets, 'spend falls below the limit')
      || ', or until an owner or admin lifts the block. Blocks start within minutes of the limit, so spend can pass it a little.';
  else
    v_title := 'Spend block lifted: ' || left(coalesce(v_block.rule_name, 'spend rule'), 100);
    v_message := v_subject || ' can send requests again. '
      || case v_block.lift_reason
        when 'manual' then coalesce(v_block.lifted_by_email, 'An owner or admin') || ' lifted the block; it stays lifted until the period resets.'
        when 'period_reset' then 'The ' || case v_block.period when 'day' then 'day' when 'week' then 'week' when 'month' then 'month' else 'period' end || ' reset.'
        when 'below_limit' then 'Spend is below the block limit again.'
        when 'rule_changed' then 'The rule changed and spend is no longer past its block limit.'
        when 'rule_disabled' then 'The rule was turned off.'
        else 'The rule was deleted.'
      end;
  end if;

  insert into public.email_outbox (kind, template, to_email, subject, workspace_id, user_id, payload, dedupe_key)
  values (
    'spend_blocked',
    'spend_blocked',
    coalesce(v_block.owner_email, ''),
    v_title,
    v_block.workspace_id,
    v_block.owner_user_id,
    jsonb_build_object(
      'title', v_title,
      'message', v_message,
      'workspace_name', v_block.workspace_name,
      'state', p_state,
      'block_id', v_block.id,
      'rule_id', v_block.rule_id,
      'rule_name', v_block.rule_name,
      'metric', v_block.metric,
      'action', 'block',
      'scope', jsonb_strip_nulls(jsonb_build_object(
        'type', v_block.scope_type,
        'id', v_block.scope_id,
        'label', v_label,
        'key_id', v_block.scope_key_id,
        'user_id', v_block.scope_user_id,
        'department_id', v_block.scope_department_id
      )),
      'period', jsonb_build_object(
        'kind', v_block.period,
        'start', v_block.period_start,
        'end', v_block.resets_at,
        'time_zone', v_block.time_zone
      ),
      'resets_at', v_block.resets_at,
      'value_nanos', v_block.spend_nanos,
      'limit_nanos', v_block.limit_nanos,
      'block_free_models', v_block.block_free_models,
      'started_at', v_block.started_at,
      'lifted_at', v_block.lifted_at,
      'lift_reason', v_block.lift_reason,
      'lifted_by', v_block.lifted_by,
      'evaluated_at', p_now,
      'url', 'https://phaseo.app/settings/notifications#spend-alerts',
      'push', jsonb_build_object(
        'title', left(v_title, 120),
        'body', left(v_message, 240),
        'href', '/settings/notifications',
        'lowerLead', false
      )
    ),
    'spend_blocked:' || v_block.id || ':' || p_state
  )
  on conflict (dedupe_key) do nothing
  returning id into v_id;

  return v_id;
end;
$function$;

COMMENT ON FUNCTION "private"."queue_spend_block_event"(uuid, text, timestamp with time zone) IS 'Queues the spend_blocked event (payload.state started or lifted) for a spend block, deduped per block and state. Called by the evaluator, the lift function and the rule-change trigger.';

REVOKE ALL ON FUNCTION "private"."queue_spend_block_event"(uuid, text, timestamp with time zone) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."queue_spend_block_event"(uuid, text, timestamp with time zone) TO "service_role";

-- source: supabase/schemas/private/functions/record_model_released_notification.sql
CREATE OR REPLACE FUNCTION private.record_model_released_notification()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- The public announcer marks a model announced once it is public and available or in
-- preview, after its public post went out. That transition is the release signal; a
-- model is only ever released once, however often it is announced again.
begin
  insert into public.catalogue_notification_events (kind, dedupe_key, model_slug, lab_slug, title, body, href, payload, occurred_at)
  select
    'model_released',
    'model_released:' || m.model_slug,
    m.model_slug,
    m.lab_slug,
    left(coalesce(nullif(btrim(l.name), ''), m.lab_slug) || ' released ' || coalesce(nullif(btrim(m.name), ''), m.model_slug), 300),
    case
      when exists (
        select 1 from public.v2_model_provider_routes r
        where r.model_slug = m.model_slug and r.routing_enabled and r.access_scope = 'public'
          and not r.is_stealth and r.status in ('active', 'degraded')
      ) then 'You can use it on Phaseo now.'
      else 'See the details on Phaseo.'
    end,
    '/models/' || m.model_slug,
    jsonb_build_object('modelName', m.name, 'labName', l.name, 'catalogueStatus', m.catalogue_status),
    coalesce(new.announced_at, now())
  from public.v2_models m
  left join public.v2_labs l on l.lab_slug = m.lab_slug
  where m.model_slug = new.model_slug
    and public.catalog_model_is_public(m.model_slug)
  on conflict (dedupe_key) do nothing;
  return null;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."record_model_released_notification"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/record_workspace_enterprise_member_overage.sql
CREATE OR REPLACE FUNCTION private.record_workspace_enterprise_member_overage()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_period_start date;
  v_included_members integer;
  v_monthly_unique_members bigint;
  v_overage_count bigint;
begin
  select subscription.included_members,
         coalesce(subscription.current_period_start::date, pg_catalog.date_trunc('month', pg_catalog.now() at time zone 'UTC')::date)
  into v_included_members, v_period_start
  from public.workspace_addon_subscriptions subscription
  where subscription.workspace_id = new.workspace_id
    and subscription.addon_key = 'identity'
    and subscription.included_members >= 100000
    and (
      subscription.status in ('active', 'trialing')
      or (subscription.status = 'past_due' and subscription.grace_until > pg_catalog.now())
    );

  if v_included_members is null then return new; end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('enterprise-member-overage:' || new.workspace_id::text || ':' || v_period_start::text, 0)
  );

  if not exists (
    select 1 from public.workspace_enterprise_member_overages usage
    where usage.workspace_id = new.workspace_id and usage.period_start = v_period_start
  ) then
    insert into public.workspace_enterprise_member_overages (workspace_id, period_start, user_id)
    select member.workspace_id, v_period_start, member.user_id
    from public.workspace_members member
    where member.workspace_id = new.workspace_id
    on conflict do nothing;
  end if;

  insert into public.workspace_enterprise_member_overages (workspace_id, period_start, user_id)
  values (new.workspace_id, v_period_start, new.user_id)
  on conflict do nothing;

  select pg_catalog.count(*) into v_monthly_unique_members
  from public.workspace_enterprise_member_overages usage
  where usage.workspace_id = new.workspace_id and usage.period_start = v_period_start;

  v_overage_count := greatest(v_monthly_unique_members - v_included_members, 0);

  insert into public.workspace_addon_usage_monthly as usage_monthly (
    workspace_id, addon_key, metric_key, period_start, quantity, updated_at
  ) values (
    new.workspace_id, 'identity', 'member_overage', v_period_start, v_overage_count, pg_catalog.now()
  )
  on conflict (workspace_id, addon_key, metric_key, period_start) do update set
    quantity = greatest(usage_monthly.quantity, excluded.quantity),
    updated_at = excluded.updated_at;

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."record_workspace_enterprise_member_overage"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/seed_workspace_enterprise_member_overages.sql
CREATE OR REPLACE FUNCTION private.seed_workspace_enterprise_member_overages()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_period_start date := coalesce(new.current_period_start::date, pg_catalog.date_trunc('month', pg_catalog.now() at time zone 'UTC')::date);
  v_monthly_unique_members bigint;
  v_overage_count bigint;
begin
  if new.addon_key <> 'identity'
     or new.included_members < 100000
     or not (
       new.status in ('active', 'trialing')
       or (new.status = 'past_due' and new.grace_until > pg_catalog.now())
     ) then
    return new;
  end if;

  insert into public.workspace_enterprise_member_overages (workspace_id, period_start, user_id)
  select member.workspace_id, v_period_start, member.user_id
  from public.workspace_members member
  where member.workspace_id = new.workspace_id
  on conflict do nothing;

  select pg_catalog.count(*) into v_monthly_unique_members
  from public.workspace_enterprise_member_overages usage
  where usage.workspace_id = new.workspace_id and usage.period_start = v_period_start;

  v_overage_count := greatest(v_monthly_unique_members - new.included_members, 0);

  insert into public.workspace_addon_usage_monthly as usage_monthly (
    workspace_id, addon_key, metric_key, period_start, quantity, updated_at
  ) values (
    new.workspace_id, 'identity', 'member_overage', v_period_start, v_overage_count, pg_catalog.now()
  )
  on conflict (workspace_id, addon_key, metric_key, period_start) do update set
    quantity = greatest(usage_monthly.quantity, excluded.quantity),
    updated_at = excluded.updated_at;

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "private"."seed_workspace_enterprise_member_overages"() FROM PUBLIC;

-- source: supabase/schemas/private/functions/set_contribution_public_reporting_scope.sql
CREATE OR REPLACE FUNCTION private.set_contribution_public_reporting_scope()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  new.public_reporting_allowed := new.provider_slug is not null
    and public.public_reporting_route_is_visible(new.model_slug, null, new.provider_slug, new.occurred_at);
  if tg_op = 'UPDATE' then
    new.public_reporting_allowed := old.public_reporting_allowed and new.public_reporting_allowed;
  end if;
  return new;
end;
$function$;

revoke all on function private.set_contribution_public_reporting_scope() from public, anon, authenticated;

-- source: supabase/schemas/private/functions/set_request_public_reporting_scope.sql
CREATE OR REPLACE FUNCTION private.set_request_public_reporting_scope()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  new.public_reporting_allowed := new.provider_model_id is not null
    and public.public_reporting_route_is_visible(
      coalesce(new.routed_model_slug, new.requested_model_slug), new.provider_model_id, null, new.occurred_at
    )
    and coalesce(new.safe_metadata->>'testing_mode', 'false') <> 'true';
  if tg_op = 'UPDATE' then
    new.public_reporting_allowed := old.public_reporting_allowed and new.public_reporting_allowed;
  end if;
  return new;
end;
$function$;

revoke all on function private.set_request_public_reporting_scope() from public, anon, authenticated;

-- source: supabase/schemas/private/functions/spend_balance_alert_text.sql
CREATE OR REPLACE FUNCTION private.spend_balance_alert_text (
  p_rule_name              text,
  p_available_nanos        bigint,
  p_threshold_amount_nanos bigint,
  p_runway_days            integer,
  p_burn_per_day_nanos     numeric,
  p_runway_days_left       numeric,
  p_window_hours           integer,
  p_trigger                text
)
  RETURNS TABLE (
    title   text,
    message text
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- The text of a balance spend alert, in US money format. p_trigger: 'balance' when the balance
  -- is at or below the rule's amount, else 'runway' (days of credit left at or below runway_days).
  -- Used by private.evaluate_workspace_spend_rules and by public.preview_workspace_spend_rule for
  -- previews and test sends, so both read the same.
  with parts as (
    select
      case
        when p_window_hours % 24 = 0 and p_window_hours > 24 then (p_window_hours / 24) || ' days'
        when p_window_hours = 1 then 'hour'
        else p_window_hours || ' hours'
      end as window_text,
      case
        when p_runway_days_left is null then null
        when p_runway_days_left < 1 then 'less than a day'
        else 'about ' || to_char(p_runway_days_left, 'FM999,999,990.0') || ' days'
      end as runway_text
  )
  select
    left(p_rule_name, 100) || ': ' || case when p_trigger = 'balance'
        then 'balance at or below ' || private.workspace_push_usd(p_threshold_amount_nanos)
        else coalesce(parts.runway_text, 'little') || ' of credit left'
      end,
    'The workspace balance is ' || private.workspace_push_usd(greatest(p_available_nanos, 0))
      || case when p_trigger = 'balance'
        then ', at or below the ' || private.workspace_push_usd(p_threshold_amount_nanos) || ' alert threshold. '
        else '. '
      end
      || case when p_burn_per_day_nanos > 0
        then 'Spend over the last ' || parts.window_text || ' averages ' || private.workspace_push_usd(round(p_burn_per_day_nanos)::bigint)
          || ' a day, so it lasts ' || parts.runway_text
          || case when p_runway_days is not null then ' (alert at ' || p_runway_days || case when p_runway_days = 1 then ' day' else ' days' end || ')' else '' end
          || '. '
        else 'There was no spend in the last ' || parts.window_text || '. '
      end
      || 'Top up credits in Settings > Credits.'
  from parts;
$function$;

COMMENT ON FUNCTION "private"."spend_balance_alert_text"(text, bigint, bigint, integer, numeric, numeric, integer, text) IS 'Title and message of a balance spend alert (balance at or below an amount, or runway at or below a number of days). Shared by the evaluator and the API preview / test send.';

REVOKE ALL ON FUNCTION "private"."spend_balance_alert_text"(text, bigint, bigint, integer, numeric, numeric, integer, text) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_balance_alert_text"(text, bigint, bigint, integer, numeric, numeric, integer, text) TO "service_role";

-- source: supabase/schemas/private/functions/spend_balance_rule_values.sql
CREATE OR REPLACE FUNCTION private.spend_balance_rule_values (
  p_workspace_id uuid,
  p_now          timestamp with time zone,
  p_rule_id      uuid DEFAULT NULL::uuid
)
  RETURNS TABLE (
    id                     uuid,
    name                   text,
    action                 text,
    window_hours           integer,
    threshold_amount_nanos bigint,
    runway_days            integer,
    cooldown_minutes       integer,
    balance_nanos          bigint,
    reserved_nanos         bigint,
    available_nanos        bigint,
    burn_nanos             numeric,
    burn_per_day_nanos     numeric,
    runway_days_left       numeric,
    low_balance            boolean,
    low_runway             boolean
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- Where balance spend rules stand at p_now: the one definition the evaluator
  -- (private.evaluate_workspace_spend_rules) and the API preview (public.preview_workspace_spend_rule)
  -- share.
  --   * Without p_rule_id: the workspace's enabled, non-deleted balance rules that
  --     private.spend_rule_evaluable accepts. With p_rule_id: that balance rule if it is not deleted.
  --   * Balance: what the gateway admits requests against, balance_nanos - reserved_nanos (at
  --     least 0). No wallet: no values, so the rule does not fire.
  --   * Burn: spend over the rule's window_hours before p_now, as the other rules count spend
  --     (v2_private_usage_15m plus successful async jobs and realtime sessions from
  --     gateway_requests), scaled to a day. Runway: available / burn per day; none without spend.
  --   * low_balance: available at or below threshold_amount_nanos. low_runway: runway at or below
  --     runway_days.
  with rules as materialized (
    select rule.id, rule.name, rule.action, rule.window_hours, rule.threshold_amount_nanos, rule.runway_days, rule.cooldown_minutes
    from public.workspace_spend_rules rule
    where rule.workspace_id = p_workspace_id
      and rule.deleted_at is null
      and rule.metric = 'balance'
      and rule.window_hours is not null
      and case
        when p_rule_id is null then rule.enabled and private.spend_rule_evaluable(rule.metric, rule.period, rule.base_kind)
        else rule.id = p_rule_id
      end
  ),
  wallet as (
    select w.balance_nanos, w.reserved_nanos, greatest(w.balance_nanos - coalesce(w.reserved_nanos, 0), 0) as available_nanos
    from public.wallets w
    where w.workspace_id = p_workspace_id
  ),
  burned as (
    select rules.*, (
        select coalesce(sum(rollup.cost_nanos), 0)
        from public.v2_private_usage_15m rollup
        where rollup.workspace_id = p_workspace_id
          and rollup.bucket_start >= p_now - make_interval(hours => rules.window_hours)
          and rollup.bucket_start < p_now
      ) + (
        -- gateway_requests_async_spend_idx
        select coalesce(sum(request.cost_nanos), 0)
        from public.gateway_requests request
        where request.success is true
          and request.endpoint = any (array['video.generation', 'batch', 'music.generate', 'audio.realtime'])
          and request.workspace_id = p_workspace_id
          and request.created_at >= p_now - make_interval(hours => rules.window_hours)
          and request.created_at < p_now
      ) as burn_nanos
    from rules
  )
  select burned.id, burned.name, burned.action, burned.window_hours, burned.threshold_amount_nanos, burned.runway_days,
    burned.cooldown_minutes, wallet.balance_nanos, wallet.reserved_nanos, wallet.available_nanos, burned.burn_nanos,
    per_day.burn_per_day_nanos,
    case when per_day.burn_per_day_nanos > 0 then round(wallet.available_nanos / per_day.burn_per_day_nanos, 2) end,
    burned.threshold_amount_nanos is not null and wallet.available_nanos <= burned.threshold_amount_nanos,
    burned.runway_days is not null and per_day.burn_per_day_nanos > 0
      and wallet.available_nanos <= burned.runway_days * per_day.burn_per_day_nanos
  from burned
  cross join wallet
  cross join lateral (select burned.burn_nanos * 24 / burned.window_hours as burn_per_day_nanos) per_day;
$function$;

COMMENT ON FUNCTION "private"."spend_balance_rule_values"(uuid, timestamp with time zone, uuid) IS 'Available balance (balance - reserved), burn over the rule''s window_hours (rollup plus async jobs), burn per day and runway of balance spend rules at p_now, and whether each is at or below its balance or runway threshold. Shared by the evaluator and the API preview.';

REVOKE ALL ON FUNCTION "private"."spend_balance_rule_values"(uuid, timestamp with time zone, uuid) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_balance_rule_values"(uuid, timestamp with time zone, uuid) TO "service_role";

-- source: supabase/schemas/private/functions/spend_department_totals.sql
CREATE OR REPLACE FUNCTION private.spend_department_totals (
  p_workspace_id uuid,
  p_from         timestamp with time zone,
  p_to           timestamp with time zone
)
  RETURNS TABLE (
    department_id uuid,
    cost_nanos    numeric,
    requests      bigint
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- Spend per department from p_from (inclusive) to p_to (exclusive), in one query for spend
  -- rules. Usage is summed per key and actor first, then each pair is spread over the
  -- departments private.spend_scope_departments gives it, so a person in two departments
  -- counts in full toward both (unless the workspace counts primary departments only).
  -- Whole quarter hours from v2_private_usage_15m, plus async jobs and realtime sessions
  -- from gateway_requests as sweep_spend_limit_warnings adds them. Like that sweep, it reads
  -- the rollup as it stands: hours the outbox has yet to rebuild count late.
  with usage as (
    select usage.key_id, usage.actor_user_id, sum(usage.cost_nanos) as cost_nanos, sum(usage.requests)::bigint as requests
    from (
      select rollup.key_id, rollup.actor_user_id, rollup.cost_nanos, rollup.requests
      from public.v2_private_usage_15m rollup
      where rollup.workspace_id = p_workspace_id
        and rollup.bucket_start >= p_from
        and rollup.bucket_start < p_to
      union all
      -- gateway_requests_async_spend_idx
      select request.key_id, coalesce(request.oauth_user_id, key.oauth_user_id, key.created_by),
        coalesce(request.cost_nanos, 0)::numeric, 1::bigint
      from public.gateway_requests request
      left join public.keys key on key.id = request.key_id
      where request.success is true
        and request.endpoint = any (array['video.generation', 'batch', 'music.generate', 'audio.realtime'])
        and request.workspace_id = p_workspace_id
        and request.created_at >= p_from
        and request.created_at < p_to
    ) usage
    group by usage.key_id, usage.actor_user_id
  )
  select scope.department_id, sum(usage.cost_nanos), sum(usage.requests)::bigint
  from usage
  cross join lateral private.spend_scope_departments(p_workspace_id, usage.key_id, usage.actor_user_id) scope(department_id)
  group by scope.department_id;
$function$;

COMMENT ON FUNCTION "private"."spend_department_totals"(uuid, timestamp with time zone, timestamp with time zone) IS 'Spend and requests per department for a workspace over [p_from, p_to), attributed by private.spend_scope_departments. Spend with no department is left out; a person in several departments counts toward each unless the workspace counts primary departments only.';

REVOKE ALL ON FUNCTION "private"."spend_department_totals"(uuid, timestamp with time zone, timestamp with time zone) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_department_totals"(uuid, timestamp with time zone, timestamp with time zone) TO "service_role";

-- source: supabase/schemas/private/functions/spend_limit_amount.sql
CREATE OR REPLACE FUNCTION private.spend_limit_amount (
  p_metric text,
  p_value  numeric
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  -- An amount counted against a budget or key limit: dollars for cost ($80.00, from nanos),
  -- otherwise a request count (1,000 requests).
  select case
    when p_metric = 'cost' then private.workspace_push_usd(p_value)
    else to_char(p_value, 'FM999,999,999,990') || case when p_value = 1 then ' request' else ' requests' end
  end;
$function$;

REVOKE ALL ON FUNCTION "private"."spend_limit_amount"(text, numeric) FROM PUBLIC;

-- source: supabase/schemas/private/functions/spend_limit_period.sql
CREATE OR REPLACE FUNCTION private.spend_limit_period (
  p_window       text,
  p_now          timestamp with time zone,
  OUT period_start timestamp with time zone,
  OUT reset_at     timestamp with time zone
)
  RETURNS record
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  -- The UTC period a budget or API key limit counts over at p_now, as the gateway counts it: a
  -- day, a week from Monday, a calendar month, or all time (lifetime, with no start or reset).
  select start_utc at time zone 'UTC',
    (start_utc + case p_window when 'daily' then interval '1 day' when 'weekly' then interval '1 week' else interval '1 month' end) at time zone 'UTC'
  from (
    select case p_window
      when 'daily' then date_trunc('day', p_now at time zone 'UTC')
      when 'weekly' then date_trunc('week', p_now at time zone 'UTC')
      when 'monthly' then date_trunc('month', p_now at time zone 'UTC')
    end as start_utc
  ) period;
$function$;

REVOKE ALL ON FUNCTION "private"."spend_limit_period"(text, timestamp with time zone) FROM PUBLIC;

-- source: supabase/schemas/private/functions/spend_report_due_workspaces.sql
CREATE OR REPLACE FUNCTION private.spend_report_due_workspaces (
  p_now timestamp with time zone
)
  RETURNS TABLE (
    workspace_id   uuid,
    owner_user_id  uuid,
    cadence        text,
    include_admins boolean,
    time_zone      text,
    period_start   timestamp with time zone,
    period_end     timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  -- Workspaces whose spend report is due at p_now (private.spend_report_period in their
  -- billing_time_zone) and has not been handled for that period yet (workspace_spend_report_runs).
  -- A workspace without settings uses the defaults: weekly, owners only, UTC. Periods are worked
  -- out once per cadence and zone in use, not per workspace, so an idle tick is one pass over
  -- workspaces with a hash join. A period counts as handled when the last handled one covers its
  -- middle: changing billing_time_zone moves the same local day, week or month to another UTC
  -- instant, which is not a new period, while the next real period starts at or after its end.
  with settings as materialized (
    select
      workspace.id,
      workspace.owner_user_id,
      coalesce(stored.spend_report_cadence, 'weekly') as cadence,
      coalesce(stored.spend_report_include_admins, false) as include_admins,
      coalesce(stored.billing_time_zone, 'UTC') as time_zone
    from public.workspaces workspace
    left join public.workspace_settings stored on stored.workspace_id = workspace.id
  ),
  due as materialized (
    select zone.cadence, zone.time_zone, report.period_start, report.period_end
    from (select distinct settings.cadence, settings.time_zone from settings where settings.cadence <> 'off') zone
    cross join lateral private.spend_report_period(zone.cadence, zone.time_zone, p_now) report
    where report.due
  )
  select settings.id, settings.owner_user_id, settings.cadence, settings.include_admins, settings.time_zone,
    due.period_start, due.period_end
  from settings
  join due on due.cadence = settings.cadence and due.time_zone = settings.time_zone
  left join public.workspace_spend_report_runs run
    on run.workspace_id = settings.id and run.cadence = settings.cadence
  where run.period_start is null
    or (run.period_start < due.period_start
      and run.period_end <= due.period_start + (due.period_end - due.period_start) / 2);
$function$;

COMMENT ON FUNCTION "private"."spend_report_due_workspaces"(timestamp with time zone) IS 'Workspaces whose daily, weekly or monthly spend report is due at p_now in their billing_time_zone and not yet handled for that period.';

REVOKE ALL ON FUNCTION "private"."spend_report_due_workspaces"(timestamp with time zone) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_report_due_workspaces"(timestamp with time zone) TO "service_role";

-- source: supabase/schemas/private/functions/spend_report_facts.sql
CREATE OR REPLACE FUNCTION private.spend_report_facts (
  p_workspace_id uuid,
  p_cadence      text,
  p_now          timestamp with time zone
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- Everything one workspace's spend report says, for the last complete daily, weekly or monthly
  -- period before p_now in its billing_time_zone (private.spend_report_period). Every figure is
  -- summed here; the email and the routed message only format it.
  --   * Totals (spend, requests, tokens) and top keys and models: the dashboard's exact usage
  --     overview (public.get_private_usage_overview, rollup plus hours the outbox has yet to
  --     rebuild), so they match the usage page and the weekly mobile digest. The period before
  --     comes from private.mobile_week_usage, the digest's own summary of the same overview.
  --   * Top members and departments: attributed the way spend rules count them (rollup by
  --     actor_user_id plus successful async jobs and realtime sessions; departments through
  --     private.spend_department_totals, which follows department_spend_attribution, so a person
  --     in two departments counts toward both unless the workspace counts primary ones only).
  --   * Forecast: the current billing month (in billing_time_zone) projected the way forecast spend
  --     rules project it (private.spend_rule_values): spend so far x month length / time elapsed,
  --     from 72 hours into the month; 0 without spend.
  --   * Runway: the available balance (balance - reserved) over the burn of the last 7 days, the
  --     way balance spend rules compute it (private.spend_balance_rule_values). Null without a
  --     wallet; runway_days null without spend.
  --   * Alerts: spend_alert events queued in the period, per rule. Blocks: spend blocks started in
  --     the period or active at any point of it.
  -- Null when the workspace does not exist or the cadence is not daily, weekly or monthly.
  with ws as (
    select
      workspace.id,
      coalesce(nullif(btrim(workspace.name), ''), 'Your workspace') as name,
      coalesce(settings.billing_time_zone, 'UTC') as time_zone,
      coalesce(settings.department_spend_attribution, 'all') as attribution
    from public.workspaces workspace
    left join public.workspace_settings settings on settings.workspace_id = workspace.id
    where workspace.id = p_workspace_id
  ),
  period as materialized (
    select ws.*, report.period_start, report.period_end, report.previous_start, report.previous_end,
      month.period_start as month_start, month.period_end as month_end
    from ws
    cross join lateral private.spend_report_period(p_cadence, ws.time_zone, p_now) report
    cross join lateral private.spend_rule_period('month', ws.time_zone, p_now) month
  ),
  cells as materialized (
    select
      nullif(overview.cell ->> 'modelId', '') as model_id,
      nullif(overview.cell ->> 'keyId', '')::uuid as key_id,
      coalesce((overview.cell ->> 'requests')::numeric, 0) as requests,
      coalesce((overview.cell ->> 'successfulRequests')::numeric, 0) as successful_requests,
      coalesce((overview.cell ->> 'costNanos')::numeric, 0) as cost_nanos,
      coalesce((overview.cell ->> 'tokens')::numeric, 0) as tokens,
      coalesce((overview.cell ->> 'inputTokens')::numeric, 0) as input_tokens,
      coalesce((overview.cell ->> 'outputTokens')::numeric, 0) as output_tokens
    from period
    -- The overview's upper bound is inclusive, as private.mobile_week_usage calls it.
    cross join lateral jsonb_array_elements(public.get_private_usage_overview(
      p_workspace_id, period.period_start, period.period_end - interval '1 microsecond', null, period.time_zone
    )) as overview(cell)
  ),
  totals as (
    select
      coalesce(sum(cells.cost_nanos), 0) as spend_nanos,
      coalesce(sum(cells.requests), 0) as requests,
      coalesce(sum(cells.successful_requests), 0) as successful_requests,
      coalesce(sum(cells.tokens), 0) as tokens,
      coalesce(sum(cells.input_tokens), 0) as input_tokens,
      coalesce(sum(cells.output_tokens), 0) as output_tokens
    from cells
  ),
  previous as (
    select
      coalesce((usage.summary ->> 'spendNanos')::numeric, 0) as spend_nanos,
      coalesce((usage.summary ->> 'requests')::numeric, 0) as requests,
      coalesce((usage.summary ->> 'tokens')::numeric, 0) as tokens
    from period
    cross join lateral (
      select private.mobile_week_usage(p_workspace_id, period.previous_start, period.previous_end, period.time_zone) as summary
    ) usage
  ),
  top_keys as (
    select keyed.key_id, key.name, keyed.spend_nanos, keyed.requests
    from (
      select cells.key_id, sum(cells.cost_nanos) as spend_nanos, sum(cells.requests) as requests
      from cells
      group by cells.key_id
      having sum(cells.cost_nanos) > 0
    ) keyed
    left join public.keys key on key.id = keyed.key_id and key.workspace_id = p_workspace_id
    order by keyed.spend_nanos desc, keyed.requests desc, keyed.key_id nulls last
    limit 5
  ),
  top_models as (
    select modelled.model_id, coalesce(catalogue.name, modelled.model_id) as name, modelled.spend_nanos, modelled.requests
    from (
      select cells.model_id, sum(cells.cost_nanos) as spend_nanos, sum(cells.requests) as requests
      from cells
      where cells.model_id is not null
      group by cells.model_id
      having sum(cells.cost_nanos) > 0
    ) modelled
    left join public.v2_models catalogue on catalogue.model_slug = modelled.model_id
    order by modelled.spend_nanos desc, modelled.requests desc, modelled.model_id
    limit 5
  ),
  spend as materialized (
    -- One read of the spend spend rules count (rollup plus successful async jobs and realtime
    -- sessions), from the earliest of the report period, the billing month and the last 7 days,
    -- up to p_now. Members, the month so far and the 7-day burn are all summed from it.
    select usage.at, usage.actor_user_id, usage.cost_nanos, usage.requests
    from period
    cross join lateral (
      select rollup.bucket_start as at, rollup.actor_user_id, rollup.cost_nanos, rollup.requests::numeric as requests
      from public.v2_private_usage_15m rollup
      where rollup.workspace_id = p_workspace_id
        and rollup.bucket_start >= least(period.period_start, period.month_start, p_now - interval '168 hours')
        and rollup.bucket_start < p_now
      union all
      -- gateway_requests_async_spend_idx
      select request.created_at, coalesce(request.oauth_user_id, key.oauth_user_id, key.created_by), coalesce(request.cost_nanos, 0)::numeric, 1::numeric
      from public.gateway_requests request
      left join public.keys key on key.id = request.key_id
      where request.success is true
        and request.endpoint = any (array['video.generation', 'batch', 'music.generate', 'audio.realtime'])
        and request.workspace_id = p_workspace_id
        and request.created_at >= least(period.period_start, period.month_start, p_now - interval '168 hours')
        and request.created_at < p_now
    ) usage
  ),
  member_usage as (
    select spend.actor_user_id, sum(spend.cost_nanos) as spend_nanos, sum(spend.requests) as requests
    from spend
    cross join period
    where spend.actor_user_id is not null
      and spend.at >= period.period_start
      and spend.at < period.period_end
    group by spend.actor_user_id
    having sum(spend.cost_nanos) > 0
  ),
  spend_sums as materialized (
    select
      coalesce(sum(spend.cost_nanos) filter (where spend.at >= period.month_start), 0) as month_nanos,
      coalesce(sum(spend.cost_nanos) filter (where spend.at >= p_now - interval '168 hours'), 0) as burn_nanos
    from period
    left join spend on true
    group by period.month_start
  ),
  top_members as (
    select member_usage.actor_user_id, nullif(btrim(person.display_name), '') as display_name,
      nullif(btrim(account.email), '') as email, member_usage.spend_nanos, member_usage.requests
    from member_usage
    left join public.users person on person.user_id = member_usage.actor_user_id
    left join auth.users account on account.id = member_usage.actor_user_id
    order by member_usage.spend_nanos desc, member_usage.requests desc, member_usage.actor_user_id
    limit 5
  ),
  top_departments as (
    select totals.department_id, department.name, totals.cost_nanos as spend_nanos, totals.requests
    from period
    cross join lateral private.spend_department_totals(p_workspace_id, period.period_start, period.period_end) totals
    left join public.workspace_departments department
      on department.id = totals.department_id and department.workspace_id = p_workspace_id
    where totals.cost_nanos > 0
    order by totals.cost_nanos desc, totals.requests desc, totals.department_id
    limit 5
  ),
  month_spend as (
    select period.month_start, period.month_end, spend_sums.month_nanos as spend_nanos,
      period.month_start + interval '72 hours' as forecast_from,
      (extract(epoch from p_now) - extract(epoch from period.month_start)) * 1000 as elapsed_ms,
      (extract(epoch from period.month_end) - extract(epoch from period.month_start)) * 1000 as length_ms
    from period
    cross join spend_sums
  ),
  forecast as materialized (
    select month_spend.*,
      case
        when p_now < month_spend.forecast_from then null
        when month_spend.spend_nanos <= 0 then 0::numeric
        else round(month_spend.spend_nanos * month_spend.length_ms / month_spend.elapsed_ms)
      end as projected_nanos
    from month_spend
  ),
  runway as materialized (
    select wallet.balance_nanos, wallet.reserved_nanos, wallet.available_nanos, burned.burn_nanos,
      burned.burn_nanos * 24 / 168 as burn_per_day_nanos,
      case when burned.burn_nanos > 0 then round(wallet.available_nanos / (burned.burn_nanos * 24 / 168), 2) end as runway_days
    from (
      select w.balance_nanos, coalesce(w.reserved_nanos, 0) as reserved_nanos,
        greatest(w.balance_nanos - coalesce(w.reserved_nanos, 0), 0) as available_nanos
      from public.wallets w
      where w.workspace_id = p_workspace_id
    ) wallet
    cross join (select spend_sums.burn_nanos from spend_sums) burned
  ),
  alerts as (
    -- email_outbox_workspace_id_idx
    select event.payload ->> 'rule_id' as rule_id, max(event.payload ->> 'rule_name') as rule_name,
      max(event.payload ->> 'metric') as metric, count(*) as fired, max(event.created_at) as last_at,
      (array_agg(coalesce(event.payload ->> 'title', event.subject) order by event.created_at desc, event.id desc))[1] as last_title
    from period
    join public.email_outbox event
      on event.workspace_id = p_workspace_id
      and event.kind = 'spend_alert'
      and event.created_at >= period.period_start
      and event.created_at < period.period_end
    group by event.payload ->> 'rule_id'
  ),
  blocks as (
    select block.id, block.rule_id, coalesce(rule.name, 'Deleted rule') as rule_name, block.scope_type, block.scope_id,
      private.spend_scope_label(p_workspace_id, block.scope_type, block.scope_id) as scope_label,
      block.started_at, block.lifted_at, block.lift_reason, block.resets_at, block.limit_nanos,
      block.lifted_at is null as active_now,
      block.started_at >= period.period_start as started_in_period
    from period
    join public.workspace_spend_blocks block
      on block.workspace_id = p_workspace_id
      and block.started_at < period.period_end
      and (block.lifted_at is null or block.lifted_at >= period.period_start)
    left join public.workspace_spend_rules rule on rule.id = block.rule_id
  ),
  facts as (
    select
      period.*,
      totals.*,
      previous.spend_nanos as previous_spend_nanos,
      previous.requests as previous_requests,
      previous.tokens as previous_tokens,
      case when previous.spend_nanos > 0 then round((totals.spend_nanos - previous.spend_nanos) * 100 / previous.spend_nanos, 1) end
        as spend_change_percent,
      (period.period_start at time zone period.time_zone) as local_start,
      (period.period_end at time zone period.time_zone) as local_end,
      case p_cadence when 'daily' then 'day' when 'weekly' then 'week' else 'month' end as unit
    from period
    cross join totals
    cross join previous
  ),
  labelled as (
    select facts.*,
      case p_cadence
        when 'daily' then to_char(facts.local_start, 'Mon FMDD, YYYY')
        when 'weekly' then to_char(facts.local_start, 'Mon FMDD') || ' – ' || to_char(facts.local_end - interval '1 day', 'Mon FMDD, YYYY')
        else to_char(facts.local_start, 'FMMonth YYYY')
      end as label,
      to_char(forecast.month_start at time zone facts.time_zone, 'FMMonth') as month_label,
      to_char(forecast.forecast_from at time zone facts.time_zone, 'Mon FMDD') as forecast_from_label
    from facts
    cross join forecast
  ),
  body as (
    select labelled.*,
      labelled.name || ' ' || case p_cadence when 'daily' then 'daily' when 'weekly' then 'weekly' else 'monthly' end
        || ' spend: ' || private.workspace_push_usd(labelled.spend_nanos) || ' (' || labelled.label || ')' as title,
      concat_ws(E'\n',
        'Spent ' || private.workspace_push_usd(labelled.spend_nanos)
          || case p_cadence when 'daily' then ' on ' when 'weekly' then ' in the week of ' else ' in ' end || labelled.label
          || case
            when labelled.spend_change_percent is null then ', with no spend the ' || labelled.unit || ' before.'
            when labelled.spend_change_percent > 0 then ', up ' || trim_scale(labelled.spend_change_percent) || '% on the ' || labelled.unit || ' before ('
              || private.workspace_push_usd(labelled.previous_spend_nanos) || ').'
            when labelled.spend_change_percent < 0 then ', down ' || trim_scale(abs(labelled.spend_change_percent)) || '% on the ' || labelled.unit || ' before ('
              || private.workspace_push_usd(labelled.previous_spend_nanos) || ').'
            else ', the same as the ' || labelled.unit || ' before.'
          end
          || ' ' || private.mobile_push_compact_number(labelled.requests) || case when labelled.requests = 1 then ' request, ' else ' requests, ' end
          || private.mobile_push_compact_number(labelled.tokens) || ' tokens.',
        (select 'Top models: ' || string_agg(top_models.name || ' ' || private.workspace_push_usd(top_models.spend_nanos), ', '
            order by top_models.spend_nanos desc, top_models.requests desc, top_models.model_id) || '.'
          from (select * from top_models order by spend_nanos desc, requests desc, model_id limit 3) top_models
          having count(*) > 0),
        (select 'Top keys: ' || string_agg(coalesce(top_keys.name, 'No API key') || ' ' || private.workspace_push_usd(top_keys.spend_nanos), ', '
            order by top_keys.spend_nanos desc, top_keys.requests desc, top_keys.key_id nulls last) || '.'
          from (select * from top_keys order by spend_nanos desc, requests desc, key_id nulls last limit 3) top_keys
          having count(*) > 0),
        (select case
            when forecast.projected_nanos is null then labelled.month_label || ' forecast: from ' || labelled.forecast_from_label
              || ' (' || private.workspace_push_usd(forecast.spend_nanos) || ' so far).'
            else labelled.month_label || ' forecast: ' || private.workspace_push_usd(forecast.projected_nanos)
              || ' (' || private.workspace_push_usd(forecast.spend_nanos) || ' so far).'
          end from forecast),
        (select 'Balance: ' || private.workspace_push_usd(runway.available_nanos)
            || case when runway.runway_days is not null
              then ', about ' || trim_scale(round(runway.runway_days, case when runway.runway_days < 10 then 1 else 0 end)) || ' days at the last 7 days'' pace.'
              else '.' end
          from runway),
        (select 'Spend alerts: ' || sum(alerts.fired) || ' fired.' from alerts having count(*) > 0),
        (select 'Spend blocks: ' || count(*) filter (where blocks.active_now) || ' active, '
            || count(*) filter (where blocks.started_in_period) || ' started.'
          from blocks having count(*) > 0),
        'Usage: https://phaseo.app/settings/usage/overview'
      ) as message
    from labelled
  )
  select jsonb_build_object(
    'version', 1,
    'workspace_id', body.id,
    'workspace_name', body.name,
    'cadence', p_cadence,
    'time_zone', body.time_zone,
    'title', body.title,
    'message', body.message,
    'period', jsonb_build_object('start', body.period_start, 'end', body.period_end, 'label', body.label,
      'local_start', to_char(body.local_start, 'YYYY-MM-DD'), 'local_end', to_char(body.local_end - interval '1 day', 'YYYY-MM-DD')),
    'previous_period', jsonb_build_object('start', body.previous_start, 'end', body.previous_end),
    'totals', jsonb_build_object('spend_nanos', body.spend_nanos, 'requests', body.requests, 'successful_requests', body.successful_requests,
      'tokens', body.tokens, 'input_tokens', body.input_tokens, 'output_tokens', body.output_tokens),
    'previous_totals', jsonb_build_object('spend_nanos', body.previous_spend_nanos, 'requests', body.previous_requests, 'tokens', body.previous_tokens),
    'change', jsonb_build_object('spend_nanos', body.spend_nanos - body.previous_spend_nanos, 'spend_percent', body.spend_change_percent),
    'top_keys', coalesce((select jsonb_agg(jsonb_build_object('id', top_keys.key_id, 'name', top_keys.name,
        'spend_nanos', top_keys.spend_nanos, 'requests', top_keys.requests)
      order by top_keys.spend_nanos desc, top_keys.requests desc, top_keys.key_id nulls last) from top_keys), '[]'::jsonb),
    'top_models', coalesce((select jsonb_agg(jsonb_build_object('id', top_models.model_id, 'name', top_models.name,
        'spend_nanos', top_models.spend_nanos, 'requests', top_models.requests)
      order by top_models.spend_nanos desc, top_models.requests desc, top_models.model_id) from top_models), '[]'::jsonb),
    'top_members', coalesce((select jsonb_agg(jsonb_build_object('user_id', top_members.actor_user_id,
        'name', coalesce(top_members.display_name, top_members.email), 'email', top_members.email,
        'spend_nanos', top_members.spend_nanos, 'requests', top_members.requests)
      order by top_members.spend_nanos desc, top_members.requests desc, top_members.actor_user_id) from top_members), '[]'::jsonb),
    'top_departments', coalesce((select jsonb_agg(jsonb_build_object('id', top_departments.department_id, 'name', top_departments.name,
        'spend_nanos', top_departments.spend_nanos, 'requests', top_departments.requests)
      order by top_departments.spend_nanos desc, top_departments.requests desc, top_departments.department_id) from top_departments), '[]'::jsonb),
    'department_attribution', body.attribution,
    'forecast', (select jsonb_build_object('month_start', forecast.month_start, 'month_end', forecast.month_end,
        'month_label', body.month_label, 'from', forecast.forecast_from, 'spend_nanos', forecast.spend_nanos,
        'projected_nanos', forecast.projected_nanos) from forecast),
    'runway', (select jsonb_build_object('balance_nanos', runway.balance_nanos, 'reserved_nanos', runway.reserved_nanos,
        'available_nanos', runway.available_nanos, 'window_hours', 168, 'burn_nanos', runway.burn_nanos,
        'burn_per_day_nanos', round(runway.burn_per_day_nanos), 'runway_days', runway.runway_days,
        'auto_top_up', private.workspace_auto_top_up_covers(p_workspace_id)) from runway),
    'alerts', jsonb_build_object(
      'fired', coalesce((select sum(alerts.fired) from alerts), 0),
      'rules', coalesce((select jsonb_agg(jsonb_build_object('rule_id', alerts.rule_id, 'rule_name', alerts.rule_name, 'metric', alerts.metric,
          'fired', alerts.fired, 'last_at', alerts.last_at, 'last_title', alerts.last_title)
        order by alerts.fired desc, alerts.last_at desc, alerts.rule_id)
        from (select * from alerts order by fired desc, last_at desc, rule_id limit 5) alerts), '[]'::jsonb)),
    'blocks', jsonb_build_object(
      'active', (select count(*) filter (where blocks.active_now) from blocks),
      'started', (select count(*) filter (where blocks.started_in_period) from blocks),
      'items', coalesce((select jsonb_agg(jsonb_build_object('block_id', blocks.id, 'rule_id', blocks.rule_id, 'rule_name', blocks.rule_name,
          'scope_type', blocks.scope_type, 'scope_label', blocks.scope_label, 'started_at', blocks.started_at, 'lifted_at', blocks.lifted_at,
          'lift_reason', blocks.lift_reason, 'resets_at', blocks.resets_at, 'limit_nanos', blocks.limit_nanos, 'active', blocks.active_now)
        order by blocks.active_now desc, blocks.started_at desc, blocks.id)
        from (select * from blocks order by active_now desc, started_at desc, id limit 5) blocks), '[]'::jsonb)),
    'url', 'https://phaseo.app/settings/usage/overview',
    'settings_url', 'https://phaseo.app/settings/notifications#spend-alerts',
    'generated_at', p_now
  )
  from body;
$function$;

COMMENT ON FUNCTION "private"."spend_report_facts"(uuid, text, timestamp with time zone) IS 'One workspace''s spend report for the last complete daily, weekly or monthly period before p_now in its billing_time_zone: totals and change (the usage overview), top keys, models, members and departments, the month forecast, runway, spend alerts and blocks, plus the routed title and message. Every figure is aggregated in SQL.';

REVOKE ALL ON FUNCTION "private"."spend_report_facts"(uuid, text, timestamp with time zone) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_report_facts"(uuid, text, timestamp with time zone) TO "service_role";

-- source: supabase/schemas/private/functions/spend_report_people.sql
CREATE OR REPLACE FUNCTION private.spend_report_people (
  p_workspace_id   uuid,
  p_include_admins boolean
)
  RETURNS TABLE (
    user_id uuid,
    role    text,
    email   text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  -- Who a workspace's spend report is for: the owner and every member with the owner role, plus
  -- members with the admin role when p_include_admins. One row per person (owner wins over admin),
  -- with their sign-in email, or null when they have none. Unsubscribes are applied by the caller.
  select distinct on (person.user_id) person.user_id, person.role, nullif(btrim(account.email), '')
  from (
    select workspace.owner_user_id as user_id, 'owner' as role, 0 as rank
    from public.workspaces workspace
    where workspace.id = p_workspace_id and workspace.owner_user_id is not null
    union all
    select member.user_id, member.role::text, case when member.role::text = 'owner' then 0 else 1 end
    from public.workspace_members member
    where member.workspace_id = p_workspace_id
      and (member.role::text = 'owner' or (p_include_admins and member.role::text = 'admin'))
  ) person
  left join auth.users account on account.id = person.user_id
  order by person.user_id, person.rank;
$function$;

COMMENT ON FUNCTION "private"."spend_report_people"(uuid, boolean) IS 'The owner and owner-role members of a workspace, plus admins when p_include_admins, with their emails: who its spend report is emailed to (before unsubscribes).';

REVOKE ALL ON FUNCTION "private"."spend_report_people"(uuid, boolean) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_report_people"(uuid, boolean) TO "service_role";

-- source: supabase/schemas/private/functions/spend_report_period.sql
CREATE OR REPLACE FUNCTION private.spend_report_period (
  p_cadence   text,
  p_time_zone text,
  p_now       timestamp with time zone
)
  RETURNS TABLE (
    due            boolean,
    period_start   timestamp with time zone,
    period_end     timestamp with time zone,
    previous_start timestamp with time zone,
    previous_end   timestamp with time zone,
    due_from       timestamp with time zone,
    due_until      timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  -- The last complete spend report period before p_now in p_time_zone, and the period before it
  -- (for the change): the day before (daily), the Monday-to-Sunday ISO week before (weekly) or the
  -- calendar month before (monthly), local midnight to local midnight. The current period comes
  -- from private.spend_rule_period, the spend rules' calendar, so a DST change makes a day 23 or 25
  -- hours long here too. The report is due from 09:00 local time on the first day of the current
  -- period until 21:00, so a late or missed run still sends it that day; outside that window the
  -- period is not due. No row for 'off' or anything else.
  select
    p_now >= due.due_from and p_now < due.due_until,
    (local.current_start - cadence.unit) at time zone p_time_zone,
    current_period.period_start,
    (local.current_start - cadence.unit - cadence.unit) at time zone p_time_zone,
    (local.current_start - cadence.unit) at time zone p_time_zone,
    due.due_from,
    due.due_until
  from (
    select
      case p_cadence when 'daily' then 'day' when 'weekly' then 'week' when 'monthly' then 'month' end as calendar,
      case p_cadence when 'daily' then interval '1 day' when 'weekly' then interval '7 days' when 'monthly' then interval '1 month' end as unit
  ) cadence
  cross join lateral private.spend_rule_period(cadence.calendar, p_time_zone, p_now) current_period
  cross join lateral (select current_period.period_start at time zone p_time_zone as current_start) local
  cross join lateral (
    select
      (local.current_start + interval '9 hours') at time zone p_time_zone as due_from,
      (local.current_start + interval '21 hours') at time zone p_time_zone as due_until
  ) due
  where cadence.calendar is not null;
$function$;

COMMENT ON FUNCTION "private"."spend_report_period"(text, text, timestamp with time zone) IS 'The last complete daily, weekly (ISO, Monday) or monthly spend report period before p_now in p_time_zone, the period before it, and whether the report is due (09:00 to 21:00 local time on the first day after the period).';

REVOKE ALL ON FUNCTION "private"."spend_report_period"(text, text, timestamp with time zone) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_report_period"(text, text, timestamp with time zone) TO "service_role";

-- source: supabase/schemas/private/functions/spend_rule_alert_text.sql
CREATE OR REPLACE FUNCTION private.spend_rule_alert_text (
  p_workspace_name         text,
  p_rule_name              text,
  p_metric                 text,
  p_scope_type             text,
  p_scope_id               text,
  p_scope_key_id           uuid,
  p_scope_user_id          uuid,
  p_scope_department_id    uuid,
  p_period                 text,
  p_period_end             timestamp with time zone,
  p_time_zone              text,
  p_base_kind              text,
  p_base_ref               text,
  p_base_nanos             bigint,
  p_threshold_percents     integer[],
  p_threshold_amount_nanos bigint,
  p_value_nanos            numeric,
  p_threshold_percent      integer,
  p_window_hours           integer,
  p_projected_nanos        numeric,
  p_reaches_at             timestamp with time zone
)
  RETURNS TABLE (
    scope_label text,
    title       text,
    message     text
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- The text of a spend alert (spend, budget_percent and forecast rules over a calendar period or
  -- a rolling window): the scope's label, the title and the message, in US money format with
  -- times in the rule's zone. Used by private.evaluate_workspace_spend_rules for real alerts and
  -- by public.preview_workspace_spend_rule for previews and test sends, so both read the same.
  --   p_threshold_percent: the threshold the alert names (budget_percent, forecast by percent).
  --   p_window_hours: a rolling rule's window.
  --   p_projected_nanos / p_reaches_at: a forecast's projected period total, and when the pace
  --   so far reaches the limit (the amount threshold, else the base), if it does this period.
  with label as (
    select case p_scope_type
      when 'workspace' then nullif(btrim(p_workspace_name), '')
      when 'key' then (select nullif(btrim(key.name), '') from public.keys key where key.id = p_scope_key_id)
      when 'member' then (select nullif(btrim(member.email), '') from auth.users member where member.id = p_scope_user_id)
      when 'department' then (
        select nullif(btrim(department.name), '') from public.workspace_departments department
        where department.id = p_scope_department_id
      )
      when 'model' then (select nullif(btrim(model.name), '') from public.v2_models model where model.model_slug = p_scope_id limit 1)
    end as label
  ),
  parts as (
    select
      coalesce(label.label, p_scope_id, p_workspace_name, 'Workspace') as scope_label,
      case p_scope_type
        when 'workspace' then 'The workspace'
        when 'key' then 'API key ''' || coalesce(left(label.label, 60), 'deleted key') || ''''
        when 'member' then coalesce(label.label, 'A former member')
        when 'department' then 'Department ''' || coalesce(left(label.label, 60), 'deleted department') || ''''
        when 'model' then coalesce(label.label, p_scope_id)
        else 'Provider ' || p_scope_id
      end as subject,
      case p_base_kind
        when 'workspace_budget' then 'the ' || p_base_ref || ' budget'
        when 'key_limit' then 'the key''s ' || p_base_ref || ' limit'
        when 'previous_period' then case
          when p_period = 'rolling' then 'the ' || case when p_window_hours = 1 then 'hour' else p_window_hours || ' hours' end || ' before'
          when p_metric = 'forecast' then case p_period when 'day' then 'yesterday''s total' else 'last ' || p_period || '''s total' end
          else case p_period when 'day' then 'yesterday at this time' else 'the same point last ' || p_period end
        end
        else private.workspace_push_usd(p_base_nanos)
      end as base_short,
      case p_period
        when 'day' then 'today'
        when 'week' then 'this week'
        when 'month' then 'this month'
        else 'in the last ' || case when p_window_hours = 1 then 'hour' else p_window_hours || ' hours' end
      end as so_far,
      case when p_period = 'rolling' then ''
        else ' The ' || p_period || ' resets ' || to_char(p_period_end at time zone p_time_zone, 'Mon FMDD, HH24:MI') || ' ' || p_time_zone || '.'
      end as resets,
      to_char(p_period_end at time zone p_time_zone, 'Mon FMDD, HH24:MI') || ' ' || p_time_zone as period_end_text,
      to_char(p_reaches_at at time zone p_time_zone, 'Mon FMDD, HH24:MI') as reaches_text
    from label
  ),
  texts as (
    select parts.*,
      case p_base_kind
        when 'amount' then private.workspace_push_usd(p_base_nanos)
        else parts.base_short || ' (' || private.workspace_push_usd(p_base_nanos) || ')'
      end as base_long,
      'Alerts at ' || (select string_agg(threshold || '%', ', ' order by threshold) from unnest(p_threshold_percents) threshold) || '.' as alerts_at,
      -- The forecast's limit: the amount threshold, else the base.
      case when p_threshold_amount_nanos is not null then private.workspace_push_usd(p_threshold_amount_nanos) end as limit_amount
    from parts
  )
  select
    texts.scope_label,
    left(p_rule_name, 100) || ': ' || case
        when p_metric = 'spend' then private.workspace_push_usd(p_threshold_amount_nanos) || ' reached'
        when p_metric = 'forecast' and p_threshold_amount_nanos is not null
          then 'projected to reach ' || private.workspace_push_usd(p_projected_nanos) || ' ' || texts.so_far
        when p_metric = 'forecast' then 'projected to pass ' || p_threshold_percent || '% of ' || texts.base_short
        else p_threshold_percent || '% of ' || texts.base_short || ' reached'
      end,
    case
      when p_metric = 'forecast' then
        texts.subject || ' has spent ' || private.workspace_push_usd(p_value_nanos) || ' ' || texts.so_far
          || ' and is projected to reach ' || private.workspace_push_usd(p_projected_nanos) || ' by ' || texts.period_end_text
          || case
            when p_threshold_amount_nanos is not null then ', past the ' || texts.limit_amount || ' alert threshold.'
            else ': ' || to_char(floor(p_projected_nanos * 100 / p_base_nanos), 'FM999,999,990') || '% of ' || texts.base_long || '. ' || texts.alerts_at
          end
          || case
            when p_reaches_at is not null then ' At this pace it reaches '
              || coalesce(texts.limit_amount, texts.base_long) || ' on ' || texts.reaches_text || '.'
            when p_value_nanos >= coalesce(p_threshold_amount_nanos, p_base_nanos) then ' It has already passed '
              || coalesce(texts.limit_amount, texts.base_long) || '.'
            else ''
          end
      else
        texts.subject || ' has spent ' || private.workspace_push_usd(p_value_nanos) || ' ' || texts.so_far
          || case when p_metric = 'spend'
            then ', past the ' || private.workspace_push_usd(p_threshold_amount_nanos) || ' alert threshold.'
            else ': ' || to_char(floor(p_value_nanos * 100 / p_base_nanos), 'FM999,999,990') || '% of ' || texts.base_long || '. ' || texts.alerts_at
          end
          || texts.resets
    end
  from texts;
$function$;

COMMENT ON FUNCTION "private"."spend_rule_alert_text"(text, text, text, text, text, uuid, uuid, uuid, text, timestamp with time zone, text, text, text, bigint, integer[], bigint, numeric, integer, integer, numeric, timestamp with time zone) IS 'Scope label, title and message of a spend alert for a spend, budget_percent or forecast rule over a calendar period or rolling window. Shared by the evaluator and the API preview / test send.';

REVOKE ALL ON FUNCTION "private"."spend_rule_alert_text"(text, text, text, text, text, uuid, uuid, uuid, text, timestamp with time zone, text, text, text, bigint, integer[], bigint, numeric, integer, integer, numeric, timestamp with time zone) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_rule_alert_text"(text, text, text, text, text, uuid, uuid, uuid, text, timestamp with time zone, text, text, text, bigint, integer[], bigint, numeric, integer, integer, numeric, timestamp with time zone) TO "service_role";

-- source: supabase/schemas/private/functions/spend_rule_evaluable.sql
CREATE OR REPLACE FUNCTION private.spend_rule_evaluable (
  p_metric    text,
  p_period    text,
  p_base_kind text
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  -- Which spend rules private.evaluate_workspace_spend_rules handles so far:
  --   * spend, budget_percent and forecast over a calendar day, week or month, with an amount,
  --     workspace budget, key limit or previous-period base;
  --   * spend and budget_percent over a rolling window (window_hours), with an amount or
  --     previous-window base (cooldown_minutes between alerts);
  --   * balance rules (workspace scope, rolling: window_hours is the burn-rate lookback);
  --   * spike rules (rolling: window_hours is the spike window, compared with the median of the
  --     same window over the previous 7 days; private.spend_spike_rule_values).
  -- Every metric is evaluated now; this stays the one switch the sweep's passes and the
  -- evaluator share.
  select (p_metric in ('spend', 'budget_percent', 'forecast')
      and p_period in ('day', 'week', 'month')
      and (p_base_kind is null or p_base_kind in ('amount', 'workspace_budget', 'key_limit', 'previous_period')))
    or (p_metric in ('spend', 'budget_percent') and p_period = 'rolling' and (p_base_kind is null or p_base_kind in ('amount', 'previous_period')))
    or (p_metric in ('balance', 'spike') and p_period = 'rolling' and p_base_kind is null);
$function$;

COMMENT ON FUNCTION "private"."spend_rule_evaluable"(text, text, text) IS 'True for the spend rules the evaluator handles: spend, budget_percent and forecast over a calendar day, week or month (amount, workspace_budget, key_limit or previous_period base), spend and budget_percent over a rolling window (amount or previous_period base), balance rules (rolling burn-rate window) and spike rules (a rolling window against the median of the same window over the previous 7 days).';

REVOKE ALL ON FUNCTION "private"."spend_rule_evaluable"(text, text, text) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_rule_evaluable"(text, text, text) TO "service_role";

-- source: supabase/schemas/private/functions/spend_rule_period.sql
CREATE OR REPLACE FUNCTION private.spend_rule_period (
  p_period    text,
  p_time_zone text,
  p_now       timestamp with time zone
)
  RETURNS TABLE (
    period_start timestamp with time zone,
    period_end   timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  -- The calendar period of a spend rule that contains p_now, in p_time_zone: a day, a week from
  -- Monday, or a month, from local midnight to local midnight. Computed on the local wall clock
  -- and converted back, so a day across a DST change lasts 23 or 25 hours. No row for any
  -- other period (rolling rules have none).
  select
    local.start_at at time zone p_time_zone,
    (local.start_at + case p_period when 'day' then interval '1 day' when 'week' then interval '7 days' else interval '1 month' end)
      at time zone p_time_zone
  from (
    select date_trunc(case when p_period in ('day', 'week', 'month') then p_period else 'day' end, p_now at time zone p_time_zone) as start_at
  ) local
  where p_period in ('day', 'week', 'month');
$function$;

COMMENT ON FUNCTION "private"."spend_rule_period"(text, text, timestamp with time zone) IS 'The day, Monday week or month containing p_now in p_time_zone, as [period_start, period_end). No row for rolling periods.';

REVOKE ALL ON FUNCTION "private"."spend_rule_period"(text, text, timestamp with time zone) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_rule_period"(text, text, timestamp with time zone) TO "service_role";

-- source: supabase/schemas/private/functions/spend_rule_values.sql
CREATE OR REPLACE FUNCTION private.spend_rule_values (
  p_workspace_id uuid,
  p_now          timestamp with time zone,
  p_rule_id      uuid DEFAULT NULL::uuid
)
  RETURNS TABLE (
    id                     uuid,
    name                   text,
    metric                 text,
    action                 text,
    scope_type             text,
    scope_id               text,
    scope_key_id           uuid,
    scope_user_id          uuid,
    scope_department_id    uuid,
    period                 text,
    base_kind              text,
    base_ref               text,
    base_amount_nanos      bigint,
    threshold_percents     integer[],
    threshold_amount_nanos bigint,
    time_zone              text,
    period_start           timestamp with time zone,
    period_end             timestamp with time zone,
    value_nanos            numeric,
    base_nanos             bigint,
    window_hours           integer,
    cooldown_minutes       integer,
    previous_start         timestamp with time zone,
    previous_end           timestamp with time zone,
    forecast_from          timestamp with time zone,
    projected_nanos        numeric,
    limit_nanos            bigint,
    reaches_at             timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- The current value and base of spend rules at p_now: the one definition of "spend so far"
  -- that the evaluator (private.evaluate_workspace_spend_rules), the API preview
  -- (public.preview_workspace_spend_rule) and test sends share.
  --   * Without p_rule_id: the workspace's enabled, non-deleted rules that
  --     private.spend_rule_evaluable accepts (what the evaluator fires on), except balance rules
  --     (private.spend_balance_rule_values).
  --   * With p_rule_id: that rule if it is not deleted, enabled or not: a calendar rule of any
  --     metric, or a rolling spend or budget_percent rule. Other rolling rules have no row.
  --   * Window: a calendar rule's day, Monday week or month in its zone
  --     (private.spend_rule_period); a rolling rule's last window_hours, as period_start = p_now
  --     - window_hours and period_end = p_now.
  --   * Zone: the rule's time_zone, else the workspace's billing_time_zone, else UTC.
  --   * Spend: v2_private_usage_15m buckets starting in the window up to p_now, plus successful
  --     async jobs and realtime sessions from gateway_requests (as sweep_spend_limit_warnings
  --     adds them). The rollup is read as it stands. Usage is read once per workspace and split
  --     at each distinct window boundary, so every rule sums a handful of rows.
  --   * Scopes: workspace; key (key_id); member (actor_user_id: their keys and OAuth requests);
  --     department (private.spend_scope_departments, read now); model (model_id); provider (the
  --     route's provider_slug, or gateway_requests.provider for async jobs).
  --   * Bases: amount (base_amount_nanos), workspace_budget (the workspace_budgets row for
  --     base_ref), key_limit (the key's *_limit_cost_nanos, 0 = none), previous_period (spend in
  --     [previous_start, previous_end), null when there was none). The previous period follows the
  --     usage dashboard's calendar comparisons: a period so far is compared with the same point in
  --     the one before (today until 09:12 with yesterday until 09:12, 31 March with 28 February,
  --     on the local wall clock), a rolling window with the same length immediately before it, and
  --     a forecast (a whole period, projected) with the whole period before.
  --   * Forecast (metric forecast): the usage dashboard's straight-line projection, as the key
  --     limit forecast computes it: projected = spend so far x period length / time elapsed,
  --     from forecast_from = period_start + 3 hours (day), 24 hours (week) or 72 hours (month); null
  --     before then, 0 without spend. limit_nanos is what the forecast is measured against
  --     (threshold_amount_nanos, else the base); reaches_at is when the pace so far reaches it,
  --     only when that happens before the period ends and it has not been reached yet.
  with settings as (
    select coalesce((
      select s.billing_time_zone from public.workspace_settings s where s.workspace_id = p_workspace_id
    ), 'UTC') as time_zone
  ),
  rules as materialized (
    select
      rule.id, rule.name, rule.metric, rule.action, rule.scope_type, rule.scope_id, rule.scope_key_id, rule.scope_user_id,
      rule.scope_department_id, rule.period, rule.base_kind, rule.base_ref, rule.base_amount_nanos,
      rule.threshold_percents, rule.threshold_amount_nanos, zone.time_zone, window_bounds.period_start, window_bounds.period_end,
      rule.window_hours, rule.cooldown_minutes,
      case when rule.base_kind = 'previous_period' then
        case
          when rule.period = 'rolling' then window_bounds.period_start - make_interval(hours => rule.window_hours)
          else ((window_bounds.period_start at time zone zone.time_zone) - unit.step) at time zone zone.time_zone
        end
      end as previous_start,
      case when rule.base_kind = 'previous_period' then
        case
          when rule.period = 'rolling' or rule.metric = 'forecast' then window_bounds.period_start
          else ((p_now at time zone zone.time_zone) - unit.step) at time zone zone.time_zone
        end
      end as previous_end
    from public.workspace_spend_rules rule
    cross join settings
    cross join lateral (select coalesce(rule.time_zone, settings.time_zone) as time_zone) zone
    cross join lateral (
      select calendar.period_start, calendar.period_end
      from private.spend_rule_period(rule.period, zone.time_zone, p_now) calendar
      union all
      select p_now - make_interval(hours => rule.window_hours), p_now
      where rule.period = 'rolling' and rule.window_hours is not null
    ) window_bounds
    cross join lateral (
      select case rule.period when 'day' then interval '1 day' when 'week' then interval '7 days' else interval '1 month' end as step
    ) unit
    where rule.workspace_id = p_workspace_id
      and rule.deleted_at is null
      and (rule.period <> 'rolling' or rule.metric in ('spend', 'budget_percent'))
      and case
        when p_rule_id is null then rule.enabled and private.spend_rule_evaluable(rule.metric, rule.period, rule.base_kind)
        else rule.id = p_rule_id
      end
  ),
  starts as materialized (
    -- Every window boundary: a row of usage belongs to the segment of the latest one at or
    -- before it, and each window is a run of whole segments.
    select distinct boundary.at
    from rules
    cross join lateral (values (rules.period_start), (rules.previous_start), (rules.previous_end)) boundary(at)
    where boundary.at is not null and boundary.at < p_now
  ),
  raw as (
    select rollup.bucket_start as at, rollup.key_id, rollup.actor_user_id, rollup.model_id, rollup.provider_model_id,
      null::text as provider, rollup.cost_nanos
    from public.v2_private_usage_15m rollup
    where rollup.workspace_id = p_workspace_id
      and rollup.bucket_start >= (select min(starts.at) from starts)
      and rollup.bucket_start < p_now
    union all
    -- gateway_requests_async_spend_idx
    select request.created_at, request.key_id, coalesce(request.oauth_user_id, key.oauth_user_id, key.created_by), request.model_id,
      null, request.provider, coalesce(request.cost_nanos, 0)::numeric
    from public.gateway_requests request
    left join public.keys key on key.id = request.key_id
    where request.success is true
      and request.endpoint = any (array['video.generation', 'batch', 'music.generate', 'audio.realtime'])
      and request.workspace_id = p_workspace_id
      and request.created_at >= (select min(starts.at) from starts)
      and request.created_at < p_now
  ),
  segments as materialized (
    -- Spend per segment (the latest boundary at or before the usage) and attribution.
    select segment.at as segment_start, raw.key_id, raw.actor_user_id, raw.model_id, raw.provider_model_id, raw.provider,
      sum(raw.cost_nanos) as cost_nanos
    from raw
    cross join lateral (select max(starts.at) as at from starts where starts.at <= raw.at) segment
    group by 1, 2, 3, 4, 5, 6
  ),
  usage as materialized (
    select segments.segment_start, segments.key_id, segments.actor_user_id, segments.model_id,
      coalesce(segments.provider, route.provider_slug) as provider, segments.cost_nanos
    from segments
    left join public.v2_model_provider_routes route on route.provider_model_id = segments.provider_model_id
  ),
  departments as materialized (
    select pair.key_id, pair.actor_user_id, scope.department_id
    from (select distinct usage.key_id, usage.actor_user_id from usage) pair
    cross join lateral private.spend_scope_departments(p_workspace_id, pair.key_id, pair.actor_user_id) scope(department_id)
    where exists (select 1 from rules where rules.scope_type = 'department')
  ),
  summed as (
    select rules.*,
      coalesce(sums.value_nanos, 0) as value_nanos,
      case rules.base_kind
        when 'amount' then rules.base_amount_nanos
        when 'workspace_budget' then (
          select budget.limit_nanos from public.workspace_budgets budget
          where budget.workspace_id = p_workspace_id and budget.interval = rules.base_ref
        )
        when 'key_limit' then (
          select nullif(case rules.base_ref
              when 'daily' then key.daily_limit_cost_nanos
              when 'weekly' then key.weekly_limit_cost_nanos
              when 'monthly' then key.monthly_limit_cost_nanos
            end, 0)
          from public.keys key
          where key.id = rules.scope_key_id and key.workspace_id = p_workspace_id
        )
        when 'previous_period' then nullif(round(coalesce(sums.previous_nanos, 0)), 0)::bigint
      end as base_nanos,
      -- Elapsed time and length in milliseconds, as the dashboard's helpers count them.
      (extract(epoch from p_now) - extract(epoch from rules.period_start)) * 1000 as elapsed_ms,
      (extract(epoch from rules.period_end) - extract(epoch from rules.period_start)) * 1000 as length_ms,
      case when rules.metric = 'forecast' then
        rules.period_start + case rules.period when 'day' then interval '3 hours' when 'week' then interval '24 hours' else interval '72 hours' end
      end as forecast_from
    from rules
    cross join lateral (
      select
        sum(usage.cost_nanos) filter (where usage.segment_start >= rules.period_start) as value_nanos,
        sum(usage.cost_nanos) filter (where usage.segment_start >= rules.previous_start and usage.segment_start < rules.previous_end) as previous_nanos
      from usage
      where usage.segment_start >= least(rules.period_start, coalesce(rules.previous_start, rules.period_start))
        and case rules.scope_type
          when 'workspace' then true
          when 'key' then usage.key_id = rules.scope_key_id
          when 'member' then usage.actor_user_id = rules.scope_user_id
          when 'model' then usage.model_id = rules.scope_id
          when 'provider' then usage.provider = rules.scope_id
          when 'department' then exists (
            select 1 from departments
            where departments.department_id = rules.scope_department_id
              and departments.key_id is not distinct from usage.key_id
              and departments.actor_user_id is not distinct from usage.actor_user_id
          )
          else false
        end
    ) sums
  ),
  projected as (
    select summed.*,
      case
        when summed.metric <> 'forecast' or p_now < summed.forecast_from then null
        when summed.value_nanos <= 0 then 0::numeric
        else summed.value_nanos * summed.length_ms / summed.elapsed_ms
      end as projected_nanos,
      case when summed.metric = 'forecast' then coalesce(summed.threshold_amount_nanos, summed.base_nanos) end as limit_nanos
    from summed
  )
  select projected.id, projected.name, projected.metric, projected.action, projected.scope_type, projected.scope_id,
    projected.scope_key_id, projected.scope_user_id, projected.scope_department_id, projected.period, projected.base_kind,
    projected.base_ref, projected.base_amount_nanos, projected.threshold_percents, projected.threshold_amount_nanos,
    projected.time_zone, projected.period_start, projected.period_end, projected.value_nanos, projected.base_nanos,
    projected.window_hours, projected.cooldown_minutes, projected.previous_start, projected.previous_end,
    projected.forecast_from, round(projected.projected_nanos), projected.limit_nanos,
    -- Reaching the limit exactly as the period ends is not a hit: the reset comes first.
    case when projected.limit_nanos > 0 and projected.value_nanos > 0 and projected.value_nanos < projected.limit_nanos
        and projected.projected_nanos > projected.limit_nanos
      then projected.period_start
        + (round(projected.elapsed_ms * projected.limit_nanos / projected.value_nanos) / 1000)::double precision * interval '1 second'
    end
  from projected;
$function$;

COMMENT ON FUNCTION "private"."spend_rule_values"(uuid, timestamp with time zone, uuid) IS 'Spend so far (value_nanos), the percentage base (base_nanos, including the previous period''s spend) and, for forecast rules, the straight-line projection to the period end with the time the pace reaches the limit, for spend rules over their calendar period or rolling window at p_now. Without p_rule_id: the enabled rules the evaluator handles (balance rules aside); with it: that non-deleted rule. Shared by the evaluator, the API preview and test sends.';

REVOKE ALL ON FUNCTION "private"."spend_rule_values"(uuid, timestamp with time zone, uuid) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_rule_values"(uuid, timestamp with time zone, uuid) TO "service_role";

-- source: supabase/schemas/private/functions/spend_scope_departments.sql
CREATE OR REPLACE FUNCTION private.spend_scope_departments (
  p_workspace_id  uuid,
  p_key_id        uuid,
  p_actor_user_id uuid
)
  RETURNS SETOF uuid
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- The departments spend rules count one key and actor's spend toward, as of now:
  -- 1. A standard key's own department wins.
  -- 2. Otherwise the actor's (the key's creator or the OAuth user): a manual override on
  --    workspace_member_overrides replaces their directory departments, as it does for their
  --    entitlements (an override with no department means none).
  -- 3. Otherwise every department in workspace_department_grants, or with
  --    workspace_settings.department_spend_attribution = 'primary' only the one their
  --    entitlements pick: the primary grant, then manual over SCIM, then the oldest.
  -- OAuth-delegated keys always use the user, as keys.department_id documents.
  -- Membership is read at call time, so moving someone moves their spend for the period.
  with explicit as (
    select key.department_id
    from public.keys key
    where key.id = p_key_id
      and key.workspace_id = p_workspace_id
      and key.key_kind = 'standard'
      and key.department_id is not null
  ),
  override as (
    select override.department_id
    from public.workspace_member_overrides override
    where override.workspace_id = p_workspace_id
      and override.user_id = p_actor_user_id
      and override.department_override_enabled
  ),
  grants as (
    select grant_row.department_id,
      row_number() over (
        order by grant_row.is_primary desc, (grant_row.source_type = 'manual') desc, grant_row.created_at, grant_row.department_id
      ) as rank
    from public.workspace_department_grants grant_row
    where grant_row.workspace_id = p_workspace_id
      and grant_row.user_id = p_actor_user_id
  ),
  primary_only as (
    select coalesce((
      select settings.department_spend_attribution = 'primary'
      from public.workspace_settings settings
      where settings.workspace_id = p_workspace_id
    ), false) as value
  )
  select explicit.department_id from explicit
  union
  select override.department_id from override
  where override.department_id is not null
    and not exists (select 1 from explicit)
  union
  select grants.department_id from grants, primary_only
  where not exists (select 1 from explicit)
    and not exists (select 1 from override)
    and (not primary_only.value or grants.rank = 1);
$function$;

COMMENT ON FUNCTION "private"."spend_scope_departments"(uuid, uuid, uuid) IS 'Departments that spend by one key and actor counts toward for spend rules: a standard key''s own department, else the actor''s override department, else all their departments (or only the primary one when workspace_settings.department_spend_attribution is primary). Empty when none apply.';

REVOKE ALL ON FUNCTION "private"."spend_scope_departments"(uuid, uuid, uuid) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_scope_departments"(uuid, uuid, uuid) TO "service_role";

-- source: supabase/schemas/private/functions/spend_scope_label.sql
CREATE OR REPLACE FUNCTION private.spend_scope_label (
  p_workspace_id uuid,
  p_scope_type   text,
  p_scope_id     text
)
  RETURNS text
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- What a spend block's scope is called right now: the workspace, key or department name, the
  -- member's email, the model's name, or the id itself when it has no name (a provider, or a
  -- key, member, department or model that no longer exists).
  select coalesce(case p_scope_type
    when 'workspace' then (select nullif(btrim(workspace.name), '') from public.workspaces workspace where workspace.id = p_workspace_id)
    when 'key' then (
      select nullif(btrim(key.name), '') from public.keys key
      where key.workspace_id = p_workspace_id and key.id::text = lower(p_scope_id)
    )
    when 'member' then (select nullif(btrim(member.email), '') from auth.users member where member.id::text = lower(p_scope_id))
    when 'department' then (
      select nullif(btrim(department.name), '') from public.workspace_departments department
      where department.workspace_id = p_workspace_id and department.id::text = lower(p_scope_id)
    )
    when 'model' then (select nullif(btrim(model.name), '') from public.v2_models model where model.model_slug = p_scope_id limit 1)
  end, p_scope_id, 'Workspace');
$function$;

COMMENT ON FUNCTION "private"."spend_scope_label"(uuid, text, text) IS 'Display name of a spend rule or block scope (workspace, key or department name, member email, model name, else the id). Used by the spend block event text and lists.';

REVOKE ALL ON FUNCTION "private"."spend_scope_label"(uuid, text, text) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_scope_label"(uuid, text, text) TO "service_role";

-- source: supabase/schemas/private/functions/spend_spike_alert_text.sql
CREATE OR REPLACE FUNCTION private.spend_spike_alert_text (
  p_workspace_name      text,
  p_rule_name           text,
  p_scope_type          text,
  p_scope_id            text,
  p_scope_key_id        uuid,
  p_scope_user_id       uuid,
  p_scope_department_id uuid,
  p_window_hours        integer,
  p_current_nanos       numeric,
  p_baseline_nanos      numeric,
  p_multiple            numeric,
  p_multiplier          numeric,
  p_floor_nanos         bigint,
  p_baseline_windows    integer
)
  RETURNS TABLE (
    scope_label text,
    title       text,
    message     text
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- The text of a spike alert, in US money format: the scope's label, the title and the message,
  -- e.g. "Spend in the last 3 hours is $42.10, 4.2× your usual $10.02 for this time of day." With
  -- a baseline of 0 the message says that only the floor applied. Used by
  -- private.evaluate_workspace_spend_rules for real alerts and by public.preview_workspace_spend_rule
  -- for previews and test sends, so both read the same.
  with label as (
    select case p_scope_type
      when 'workspace' then nullif(btrim(p_workspace_name), '')
      when 'key' then (select nullif(btrim(key.name), '') from public.keys key where key.id = p_scope_key_id)
      when 'member' then (select nullif(btrim(member.email), '') from auth.users member where member.id = p_scope_user_id)
      when 'department' then (
        select nullif(btrim(department.name), '') from public.workspace_departments department
        where department.id = p_scope_department_id
      )
      when 'model' then (select nullif(btrim(model.name), '') from public.v2_models model where model.model_slug = p_scope_id limit 1)
    end as label
  ),
  parts as (
    select
      coalesce(label.label, p_scope_id, p_workspace_name, 'Workspace') as scope_label,
      case p_scope_type
        when 'workspace' then ''
        when 'key' then ' by API key ''' || coalesce(left(label.label, 60), 'deleted key') || ''''
        when 'member' then ' by ' || coalesce(label.label, 'a former member')
        when 'department' then ' by department ''' || coalesce(left(label.label, 60), 'deleted department') || ''''
        when 'model' then ' on ' || coalesce(label.label, p_scope_id)
        else ' on provider ' || p_scope_id
      end as subject,
      case when p_scope_type = 'workspace' then 'your' else 'its' end as whose,
      case when p_window_hours = 1 then 'hour' else p_window_hours || ' hours' end as hours,
      private.workspace_push_usd(round(p_current_nanos)::bigint) as current_text,
      private.workspace_push_usd(round(p_baseline_nanos)::bigint) as baseline_text,
      private.workspace_push_usd(p_floor_nanos) as floor_text,
      pg_catalog.trim_scale(round(p_multiple, 1))::text || '×' as multiple_text,
      pg_catalog.trim_scale(p_multiplier)::text || '×' as multiplier_text
    from label
  )
  select
    parts.scope_label,
    left(p_rule_name, 100) || ': ' || case
      when p_baseline_nanos > 0 then 'spend ' || parts.multiple_text || ' usual in the last ' || parts.hours
      else parts.current_text || ' spent in the last ' || parts.hours
    end,
    'Spend' || parts.subject || ' in the last ' || parts.hours || ' is ' || parts.current_text
      || case
        when p_baseline_nanos > 0 then
          ', ' || parts.multiple_text || ' ' || parts.whose || ' usual ' || parts.baseline_text
            || case when p_window_hours < 24 then ' for this time of day.' else ' for ' || p_window_hours || ' hours.' end
            || case when p_window_hours < 24
              then ' The usual is the median of the same ' || parts.hours || ' on each of the previous 7 days.'
              else ' The usual is the median of the previous ' || p_baseline_windows || ' windows of ' || p_window_hours || ' hours.'
            end
            || ' Alerts at ' || parts.multiplier_text || ' and ' || parts.floor_text || ' or more.'
        else
          '. There was no spend in '
            || case when p_window_hours < 24 then 'the same ' || parts.hours || ' on the previous 7 days' else 'the previous 7 days' end
            || ', so this alert uses only the ' || parts.floor_text || ' floor.'
      end
  from parts;
$function$;

COMMENT ON FUNCTION "private"."spend_spike_alert_text"(text, text, text, text, uuid, uuid, uuid, integer, numeric, numeric, numeric, numeric, bigint, integer) IS 'Scope label, title and message of a spike spend alert (spend over the last window_hours against the median of the same window over the previous 7 days). Shared by the evaluator and the API preview / test send.';

REVOKE ALL ON FUNCTION "private"."spend_spike_alert_text"(text, text, text, text, uuid, uuid, uuid, integer, numeric, numeric, numeric, numeric, bigint, integer) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_spike_alert_text"(text, text, text, text, uuid, uuid, uuid, integer, numeric, numeric, numeric, numeric, bigint, integer) TO "service_role";

-- source: supabase/schemas/private/functions/spend_spike_rule_values.sql
CREATE OR REPLACE FUNCTION private.spend_spike_rule_values (
  p_workspace_id uuid,
  p_now          timestamp with time zone,
  p_rule_id      uuid DEFAULT NULL::uuid
)
  RETURNS TABLE (
    id                  uuid,
    name                text,
    action              text,
    scope_type          text,
    scope_id            text,
    scope_key_id        uuid,
    scope_user_id       uuid,
    scope_department_id uuid,
    time_zone           text,
    window_hours        integer,
    cooldown_minutes    integer,
    spike_multiplier    numeric,
    spike_floor_nanos   bigint,
    period_start        timestamp with time zone,
    period_end          timestamp with time zone,
    current_nanos       numeric,
    baseline_nanos      numeric,
    multiple            numeric,
    baseline_windows    integer,
    active_windows      integer,
    history_ready       boolean,
    fires_at_nanos      numeric,
    spiking             boolean
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- Where spike spend rules stand at p_now: the one definition the evaluator
  -- (private.evaluate_workspace_spend_rules) and the API preview (public.preview_workspace_spend_rule)
  -- share.
  --   * Without p_rule_id: the workspace's enabled, non-deleted spike rules that
  --     private.spend_rule_evaluable accepts. With p_rule_id: that spike rule if it is not deleted.
  --   * Current: spend in the rule's scope over the last window_hours, [p_now - window, p_now).
  --   * Baseline: the median of the same window over the previous 7 days. A window under 24 hours
  --     is compared with the same hours on each of the 7 days before (the windows ending exactly
  --     1..7 x 24 hours before p_now); a window of 24 hours or more with the non-overlapping
  --     windows before it that fit in 7 days (floor(168 / window_hours) of them). Windows are
  --     counted in hours, not on a local clock, so a rule's time zone never changes the result.
  --     Windows without spend count as 0. baseline_windows is how many there are.
  --   * Spend is counted as the other rules count it: v2_private_usage_15m buckets starting in a
  --     window, plus successful async jobs and realtime sessions from gateway_requests, with the
  --     same scopes (workspace, key, member, department read now, model, provider).
  --   * History: a rule is ready once it has at least 3 baseline windows and the workspace (any
  --     scope) spent something in at least 3 of them. Measured on the workspace so that a new
  --     key, member or model that suddenly spends in an established workspace still alerts.
  --     A window over 56 hours leaves fewer than 3 windows in 7 days and is never ready.
  --   * Spiking: ready, current > 0, current >= spike_multiplier x baseline and current >=
  --     spike_floor_nanos (fires_at_nanos is the larger of the two). A baseline of 0 leaves only
  --     the floor.
  --   * Cost: each window is read with one index range scan of the rollup (and of
  --     gateway_requests_async_spend_idx), once per distinct window across the workspace's
  --     spike rules: 1 + baseline_windows windows, so about 8 x window_hours of buckets.
  with settings as (
    select coalesce((
      select s.billing_time_zone from public.workspace_settings s where s.workspace_id = p_workspace_id
    ), 'UTC') as time_zone
  ),
  rules as materialized (
    select rule.id, rule.name, rule.action, rule.scope_type, rule.scope_id, rule.scope_key_id, rule.scope_user_id,
      rule.scope_department_id, coalesce(rule.time_zone, settings.time_zone) as time_zone, rule.window_hours,
      rule.cooldown_minutes, rule.spike_multiplier, rule.spike_floor_nanos,
      case when rule.window_hours < 24 then 7 else 168 / rule.window_hours end as baseline_windows,
      case when rule.window_hours < 24 then 24 else rule.window_hours end as step_hours
    from public.workspace_spend_rules rule
    cross join settings
    where rule.workspace_id = p_workspace_id
      and rule.deleted_at is null
      and rule.metric = 'spike'
      and rule.period = 'rolling'
      and rule.window_hours is not null
      and case
        when p_rule_id is null then rule.enabled and private.spend_rule_evaluable(rule.metric, rule.period, rule.base_kind)
        else rule.id = p_rule_id
      end
  ),
  windows as materialized (
    -- Window 0 is the current one; 1..baseline_windows the baseline. Rules with the same
    -- window_hours share their windows.
    select distinct rules.window_hours, slot.k,
      p_now - make_interval(hours => slot.k * rules.step_hours + rules.window_hours) as window_start,
      p_now - make_interval(hours => slot.k * rules.step_hours) as window_end
    from rules
    cross join lateral generate_series(0, rules.baseline_windows) slot(k)
  ),
  raw as (
    select windows.window_hours, windows.k, rollup.key_id, rollup.actor_user_id, rollup.model_id, rollup.provider_model_id,
      null::text as provider, sum(rollup.cost_nanos) as cost_nanos
    from windows
    join public.v2_private_usage_15m rollup
      on rollup.workspace_id = p_workspace_id
      and rollup.bucket_start >= windows.window_start
      and rollup.bucket_start < windows.window_end
    group by 1, 2, 3, 4, 5, 6
    union all
    -- gateway_requests_async_spend_idx
    select windows.window_hours, windows.k, request.key_id, coalesce(request.oauth_user_id, key.oauth_user_id, key.created_by),
      request.model_id, null, request.provider, sum(coalesce(request.cost_nanos, 0))::numeric
    from windows
    join public.gateway_requests request
      on request.success is true
      and request.endpoint = any (array['video.generation', 'batch', 'music.generate', 'audio.realtime'])
      and request.workspace_id = p_workspace_id
      and request.created_at >= windows.window_start
      and request.created_at < windows.window_end
    left join public.keys key on key.id = request.key_id
    group by 1, 2, 3, 4, 5, 6, 7
  ),
  usage as materialized (
    select raw.window_hours, raw.k, raw.key_id, raw.actor_user_id, raw.model_id,
      coalesce(raw.provider, route.provider_slug) as provider, raw.cost_nanos
    from raw
    left join public.v2_model_provider_routes route on route.provider_model_id = raw.provider_model_id
  ),
  departments as materialized (
    select pair.key_id, pair.actor_user_id, scope.department_id
    from (select distinct usage.key_id, usage.actor_user_id from usage) pair
    cross join lateral private.spend_scope_departments(p_workspace_id, pair.key_id, pair.actor_user_id) scope(department_id)
    where exists (select 1 from rules where rules.scope_type = 'department')
  ),
  per_window as (
    -- Spend in the rule's scope and in the whole workspace, per window.
    select rules.id, windows.k, sums.scoped_nanos, sums.workspace_nanos,
      row_number() over (partition by rules.id, windows.k = 0 order by sums.scoped_nanos) as rank
    from rules
    join windows on windows.window_hours = rules.window_hours and windows.k <= rules.baseline_windows
    cross join lateral (
      select
        coalesce(sum(usage.cost_nanos) filter (where case rules.scope_type
          when 'workspace' then true
          when 'key' then usage.key_id = rules.scope_key_id
          when 'member' then usage.actor_user_id = rules.scope_user_id
          when 'model' then usage.model_id = rules.scope_id
          when 'provider' then usage.provider = rules.scope_id
          when 'department' then exists (
            select 1 from departments
            where departments.department_id = rules.scope_department_id
              and departments.key_id is not distinct from usage.key_id
              and departments.actor_user_id is not distinct from usage.actor_user_id
          )
          else false
        end), 0) as scoped_nanos,
        coalesce(sum(usage.cost_nanos), 0) as workspace_nanos
      from usage
      where usage.window_hours = windows.window_hours and usage.k = windows.k
    ) sums
  ),
  summary as (
    -- The median of the baseline windows: the middle one, or the mean of the middle two.
    select rules.id,
      coalesce(max(per_window.scoped_nanos) filter (where per_window.k = 0), 0) as current_nanos,
      avg(per_window.scoped_nanos) filter (where per_window.k > 0
        and per_window.rank in ((rules.baseline_windows + 1) / 2, (rules.baseline_windows + 2) / 2)) as baseline_nanos,
      count(*) filter (where per_window.k > 0 and per_window.workspace_nanos > 0)::integer as active_windows
    from rules
    left join per_window on per_window.id = rules.id
    group by rules.id, rules.baseline_windows
  ),
  measured as (
    select rules.*, summary.current_nanos, round(coalesce(summary.baseline_nanos, 0)) as baseline_nanos, summary.active_windows,
      rules.baseline_windows >= 3 and summary.active_windows >= 3 as history_ready
    from rules
    join summary on summary.id = rules.id
  )
  select measured.id, measured.name, measured.action, measured.scope_type, measured.scope_id, measured.scope_key_id,
    measured.scope_user_id, measured.scope_department_id, measured.time_zone, measured.window_hours, measured.cooldown_minutes,
    measured.spike_multiplier, measured.spike_floor_nanos,
    p_now - make_interval(hours => measured.window_hours), p_now,
    measured.current_nanos, measured.baseline_nanos,
    case when measured.baseline_nanos > 0 then round(measured.current_nanos / measured.baseline_nanos, 2) end,
    measured.baseline_windows, measured.active_windows, measured.history_ready,
    greatest(ceil(measured.spike_multiplier * measured.baseline_nanos), measured.spike_floor_nanos),
    measured.history_ready and measured.current_nanos > 0
      and measured.current_nanos >= measured.spike_multiplier * measured.baseline_nanos
      and measured.current_nanos >= measured.spike_floor_nanos
  from measured;
$function$;

COMMENT ON FUNCTION "private"."spend_spike_rule_values"(uuid, timestamp with time zone, uuid) IS 'Spike spend rules at p_now: spend over the last window_hours, the median of the same window over the previous 7 days (same hours on each of the 7 days before for windows under 24 hours, else the non-overlapping windows that fit in 7 days), the multiple, whether the workspace has enough history (spend in at least 3 baseline windows) and whether the rule is spiking (current at least spike_multiplier x baseline and spike_floor_nanos). Shared by the evaluator and the API preview.';

REVOKE ALL ON FUNCTION "private"."spend_spike_rule_values"(uuid, timestamp with time zone, uuid) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."spend_spike_rule_values"(uuid, timestamp with time zone, uuid) TO "service_role";

-- source: supabase/schemas/private/functions/workspace_auto_top_up_covers.sql
CREATE OR REPLACE FUNCTION private.workspace_auto_top_up_covers (
  p_workspace_id uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- Whether the workspace's auto top-up is on and working, so a low balance refills by itself and
  -- a drop is recorded without an alert. The one test the low-balance push sweep
  -- (sweep_low_balance_pushes), the low-balance email sweep (sweep_low_balance_emails) and
  -- balance spend rules (evaluate_workspace_spend_rules) share, so they agree.
  -- Working means: enabled with at least $1 to add (smaller amounts are skipped without an alert),
  -- a trigger above $0 (a $0 trigger never fires), failure alerts on (a failed top-up has its own
  -- email and push), and no failed top-up since the last card payment. No wallet: false.
  select coalesce((
    select w.auto_top_up_enabled
      and w.auto_top_up_amount >= 1000000000
      and w.low_balance_threshold > 0
      and s.auto_top_up_failure_email_enabled is distinct from false
      and not exists (
        select 1
        from (
          select f.occurred_at
          from public.workspace_notification_events f
          where f.workspace_id = w.workspace_id and f.kind = 'auto_top_up_failed'
          order by f.occurred_at desc
          limit 1
        ) failed
        where not exists (
          select 1
          from public.credit_ledger l
          where l.workspace_id = w.workspace_id
            and l.ref_type = 'Stripe_Payment_Intent'
            and l.amount_nanos > 0
            and l.created_at > failed.occurred_at
        )
      )
    from public.wallets w
    left join public.workspace_settings s on s.workspace_id = w.workspace_id
    where w.workspace_id = p_workspace_id
  ), false);
$function$;

COMMENT ON FUNCTION "private"."workspace_auto_top_up_covers"(uuid) IS 'True while the workspace''s auto top-up is on and working (enabled, at least $1 to add, a trigger above $0, failure alerts on, no failed top-up since the last card payment). Low-balance pushes, low-balance emails and balance spend rules record a drop without alerting while it is.';

REVOKE ALL ON FUNCTION "private"."workspace_auto_top_up_covers"(uuid) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "private"."workspace_auto_top_up_covers"(uuid) TO "service_role";

-- source: supabase/schemas/private/functions/workspace_push_message.sql
CREATE OR REPLACE FUNCTION private.workspace_push_message (
  p_kind           text,
  p_category       text,
  p_payload        jsonb,
  p_is_actor       boolean,
  p_workspace_name text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
-- Writes one workspace push for one recipient: kind, category, title, body, href and modelSlug,
-- or null for a kind it cannot write.
--   p_is_actor        the recipient did what the push is about: "You created API key 'prod'".
--   p_workspace_name  set when the recipient belongs to more than one workspace. The title then
--                     starts with it, and an ordinary first word is lower-cased: "Acme: balance
--                     is $3.20", but "Acme: GPT-4o retires Nov 30".
-- Money is in US format ($3.20) and dates are UTC (Nov 30). Kinds not written here carry their
-- own text in payload.push: title, body, href, modelSlug and lowerLead.
-- Low balance says how long the balance lasts at the pace of the last spend_window_days days
-- (recent_spend_nanos), as the web's credit runway does: not below a cent a day, and "more than
-- 90 days" past that.
declare
  v_number constant text := '^-?[0-9]+(\.[0-9]+)?$';
  v_title text;
  v_body text;
  v_href text;
  v_model text;
  v_lower boolean := false;
  v_name text := nullif(btrim(coalesce(p_payload ->> 'key_name', '')), '');
  v_key text;
  v_actor text := left(nullif(btrim(coalesce(p_payload ->> 'actor_name', '')), ''), 40);
  v_source text := nullif(btrim(coalesce(p_payload ->> 'reported_source', '')), '');
  v_count numeric;
  v_retires timestamptz;
  v_deprecates timestamptz;
  v_expires timestamptz;
  v_balance numeric;
  v_daily numeric;
  v_days numeric;
begin
  v_key := '''' || case when v_name is null then 'unnamed' when char_length(v_name) > 40 then left(v_name, 39) || '…' else v_name end || '''';

  if p_kind = 'low_balance' then
    v_lower := true;
    v_balance := case when p_payload ->> 'balance_nanos' ~ v_number then (p_payload ->> 'balance_nanos')::numeric end;
    v_daily := case when p_payload ->> 'recent_spend_nanos' ~ v_number and p_payload ->> 'spend_window_days' ~ '^[1-9][0-9]*$'
      then (p_payload ->> 'recent_spend_nanos')::numeric / (p_payload ->> 'spend_window_days')::numeric end;
    v_days := case when v_balance > 0 and v_daily >= 10000000 then v_balance / v_daily end;
    v_title := 'Balance is ' || coalesce(private.workspace_push_usd(greatest(0, v_balance)), 'low');
    v_body := case
        when v_days is null then ''
        when v_days < 1 then 'Less than a day left at this week''s pace. '
        when v_days > 90 then 'More than 90 days left at this week''s pace. '
        when round(v_days) = 1 then 'About 1 day left at this week''s pace. '
        else 'About ' || round(v_days) || ' days left at this week''s pace. '
      end || 'Add credits to keep requests running.';
    v_href := '/settings/credits';

  elsif p_kind = 'auto_top_up_failed' then
    v_lower := true;
    v_title := 'Auto top-up failed';
    v_body := left(coalesce(nullif(btrim(p_payload ->> 'reason'), ''), 'The saved payment method could not be charged.'), 200);
    v_href := '/settings/credits';

  elsif p_kind = 'payment_method_expiring' then
    v_lower := true;
    v_title := coalesce('Card ending ' || nullif(btrim(p_payload ->> 'last4'), '') || ' expires soon', 'Your card expires soon');
    v_body := 'Your ' || coalesce(initcap(replace(nullif(btrim(p_payload ->> 'brand'), ''), '_', ' ')), 'card')
      || ' expires ' || coalesce(nullif(btrim(p_payload ->> 'expiry'), ''), 'soon') || '. Update it to keep top-ups working.';
    v_href := '/settings/payment-methods';

  elsif p_kind = 'model_deprecation' then
    v_model := nullif(btrim(p_payload ->> 'model_id'), '');
    v_name := coalesce(nullif(btrim(p_payload ->> 'model_name'), ''), v_model, 'A model you use');
    v_retires := case when p_payload ->> 'retirement_date' ~ '^\d{4}-\d{2}-\d{2}' then (p_payload ->> 'retirement_date')::timestamptz end;
    v_deprecates := case when p_payload ->> 'deprecation_date' ~ '^\d{4}-\d{2}-\d{2}' then (p_payload ->> 'deprecation_date')::timestamptz end;
    v_title := v_name || case
      when v_retires > now() then ' retires ' || to_char(v_retires at time zone 'UTC', 'Mon FMDD')
      when v_deprecates > now() then ' is deprecated from ' || to_char(v_deprecates at time zone 'UTC', 'Mon FMDD')
      else ' is deprecated'
    end;
    v_body := coalesce('Switch to ' || nullif(btrim(coalesce(p_payload ->> 'replacement_model_name', p_payload ->> 'replacement_model_id')), '')
      || case when v_retires > now() then ' before then.' else '.' end, 'Choose a supported replacement.');
    v_href := coalesce('/models/' || v_model, '/');

  elsif p_kind = 'model_substitution' then
    v_model := nullif(btrim(p_payload ->> 'replacement_model_id'), '');
    v_name := coalesce(nullif(btrim(p_payload ->> 'model_name'), ''), nullif(btrim(p_payload ->> 'model_id'), ''), 'A retired model');
    v_title := v_name || ' requests now go to ' || coalesce(nullif(btrim(p_payload ->> 'replacement_model_name'), ''), v_model, 'its replacement');
    v_body := 'No provider serves ' || v_name || ' any more.';
    v_href := coalesce('/models/' || v_model, '/');

  elsif p_kind = 'rate_limit_throttled' then
    v_lower := true;
    v_count := case when p_payload ->> 'throttled_requests' ~ v_number then (p_payload ->> 'throttled_requests')::numeric end;
    v_title := 'Rate limits blocked ' || coalesce(to_char(v_count, 'FM999,999,999,990') || case when v_count = 1 then ' request' else ' requests' end, 'requests');
    v_body := 'In the last ' || coalesce(case when p_payload ->> 'window_minutes' ~ '^[0-9]+$' then p_payload ->> 'window_minutes' end, '15') || ' minutes.'
      || coalesce(' Most were under ''' || (
        select left(nullif(btrim(p ->> 'policy_name'), ''), 40)
        from jsonb_array_elements(case when jsonb_typeof(p_payload -> 'policies') = 'array' then p_payload -> 'policies' else '[]'::jsonb end) p
        order by case when p ->> 'throttled_requests' ~ v_number then (p ->> 'throttled_requests')::numeric end desc nulls last
        limit 1
      ) || '''.', '');
    v_href := '/settings/usage/overview';

  elsif p_kind = 'security_leaked_key' then
    v_title := case when p_payload ->> 'key_type' = 'management_key' then 'Management key ' else 'API key ' end || v_key || ' was exposed';
    v_body := coalesce('Reported by ' || case
        when v_source ~* 'github' then 'GitHub'
        when v_source ~* 'gitlab' then 'GitLab'
        else left(btrim(regexp_replace(v_source, '[_-]+', ' ', 'g')), 40)
      end || '. ', 'Reported as public. ')
      || case when p_payload ->> 'auto_revoked' = 'true' then 'It has been revoked, so replace it.' else 'Rotate it now.' end;
    v_href := case when p_payload ->> 'key_type' = 'management_key' then '/settings/management-api-keys' else '/settings/keys' end;

  elsif p_kind in ('api_key_created', 'api_key_rotated', 'api_key_deleted', 'api_key_paused', 'api_key_resumed') then
    if coalesce(p_is_actor, false) then
      v_lower := true;
      v_title := 'You ' || substr(p_kind, 9) || ' API key ' || v_key;
    elsif p_kind = 'api_key_created' then
      v_lower := true;
      v_title := 'New API key ' || v_key || ' created' || coalesce(' by ' || v_actor, '');
    else
      v_title := 'API key ' || v_key || ' ' || substr(p_kind, 9) || coalesce(' by ' || v_actor, '');
    end if;
    v_expires := case when p_payload ->> 'previous_key_expires_at' ~ '^\d{4}-\d{2}-\d{2}' then (p_payload ->> 'previous_key_expires_at')::timestamptz end;
    v_body := case p_kind
      when 'api_key_created' then case
        when nullif(btrim(p_payload ->> 'app_name'), '') is not null then 'Issued to ' || left(btrim(p_payload ->> 'app_name'), 60) || ' through OAuth.'
        when coalesce(p_is_actor, false) then 'Owners and admins get this alert too.'
        else 'Review your keys if you didn''t expect this.'
      end
      when 'api_key_rotated' then coalesce('The new key is ''' || left(nullif(btrim(p_payload ->> 'replacement_key_name'), ''), 40) || '''. ', '')
        || coalesce('The old one stops working ' || to_char(v_expires at time zone 'UTC', 'Mon FMDD, HH24:MI') || ' UTC.', 'The old one works until you delete it.')
      when 'api_key_deleted' then 'Requests using it are now rejected.'
      when 'api_key_paused' then 'Requests using it are rejected until it''s resumed.'
      else 'It can make requests again.'
    end;
    v_href := '/settings/keys';

  elsif jsonb_typeof(p_payload -> 'push') = 'object' then
    v_title := nullif(btrim(p_payload -> 'push' ->> 'title'), '');
    v_body := p_payload -> 'push' ->> 'body';
    v_href := p_payload -> 'push' ->> 'href';
    v_model := nullif(btrim(p_payload -> 'push' ->> 'modelSlug'), '');
    v_lower := coalesce(p_payload -> 'push' ->> 'lowerLead' = 'true', false);
  end if;

  if v_title is null then
    return null;
  end if;
  if nullif(btrim(p_workspace_name), '') is not null then
    v_title := left(btrim(p_workspace_name), 40) || ': '
      || case when v_lower then lower(left(v_title, 1)) || substr(v_title, 2) else v_title end;
  end if;

  return jsonb_build_object('kind', p_kind, 'category', p_category, 'title', left(v_title, 300), 'body', left(coalesce(v_body, ''), 1000),
    'href', coalesce(nullif(btrim(v_href), ''), '/'), 'modelSlug', v_model);
end;
$function$;

REVOKE ALL ON FUNCTION "private"."workspace_push_message"(text, text, jsonb, boolean, text) FROM PUBLIC;

-- source: supabase/schemas/private/functions/workspace_push_usd.sql
CREATE OR REPLACE FUNCTION private.workspace_push_usd (
  p_nanos numeric
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  -- Dollars in US format for workspace push text: $3.20, $1,250.00. Null stays null.
  select '$' || to_char(round(p_nanos / 1000000000, 2), 'FM999,999,999,990.00');
$function$;

REVOKE ALL ON FUNCTION "private"."workspace_push_usd"(numeric) FROM PUBLIC;

-- source: supabase/schemas/public/functions/acknowledge_model_discovery_issue_signals.sql
CREATE OR REPLACE FUNCTION public.acknowledge_model_discovery_issue_signals (
  p_entries jsonb
)
  RETURNS integer
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with acknowledged as (
    update public.model_discovery_issue_signals signal
    set emitted_at = now()
    where signal.action = 'delete'
      and signal.emitted_at is null
      and exists (
        select 1
        from jsonb_array_elements(coalesce(p_entries, '[]'::jsonb)) entry(value)
        where entry.value ->> 'source' = signal.source
          and entry.value ->> 'providerId' = signal.provider_id
          and entry.value ->> 'action' = signal.action
          and entry.value ->> 'modelId' = signal.model_id
      )
    returning 1
  )
  select count(*)::integer from acknowledged;
$function$;

GRANT EXECUTE ON FUNCTION "public"."acknowledge_model_discovery_issue_signals"(jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."acknowledge_model_discovery_issue_signals"(jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/activate_due_provider_catalog_releases.sql
CREATE OR REPLACE FUNCTION public.activate_due_provider_catalog_releases()
  RETURNS integer
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  activated_count integer := 0;
  activated_route_ids text[] := '{}';
  due_route_ids text[];
  due_statuses text[];
begin
  -- Every catalogue table bumps the routing catalogue revision once per
  -- statement, even when no row changes. This runs every minute, so it must
  -- not issue updates when nothing is due.
  select coalesce(array_agg(due.provider_model_id), '{}'), coalesce(array_agg(due.next_status), '{}')
  into due_route_ids, due_statuses
  from (
    select route.provider_model_id,
      case when candidate.availability = 'ready' then 'active' else 'degraded' end as next_status
    from public.v2_model_provider_routes route
    join public.provider_catalog_route_candidates candidate
      on candidate.provider_slug = route.provider_slug
     and candidate.canonical_model_slug = route.model_slug
     and candidate.provider_model_slug = route.provider_model_slug
     and route.metadata ->> 'source_run_id' = candidate.run_id::text
    where candidate.status = 'promoted'
      and candidate.availability in ('ready', 'degraded')
      and route.metadata ->> 'managed_by' = 'provider_catalog'
      and route.metadata ->> 'release_scheduled' = 'true'
      and route.access_scope = 'internal'
      and route.status = 'disabled'
      and route.provider_availability_status = 'coming_soon'
      and route.effective_from is not null
      and route.effective_from <= now()
      and (route.effective_to is null or route.effective_to > now())
      and not route.is_stealth
      and route.phaseo_status not in ('blocked', 'unsupported')
      and jsonb_array_length(candidate.pricing) > 0
      and exists (select 1 from public.v2_models model where model.model_slug = route.model_slug
        and (not model.hidden or (model.metadata ->> 'provider_catalog_owner' = route.provider_slug and model.released_at is null)))
      and not exists (
        select 1 from public.v2_model_provider_routes stealth_route
        where stealth_route.model_slug = route.model_slug and stealth_route.is_stealth
      )
      and exists (
        select 1 from public.v2_providers provider
        where provider.provider_slug = route.provider_slug
          and (provider.status = 'not_ready' or (provider.status <> 'disabled' and provider.routable and provider.routing_enabled))
          and (not (coalesce(provider.metadata, '{}'::jsonb) ? 'self_serve')
            or provider.metadata -> 'self_serve' ->> 'provider_review_status' = 'approved')
          and coalesce((provider.metadata ->> 'adapter_ready')::boolean, false)
          and coalesce((provider.metadata ->> 'credentials_ready')::boolean, false)
          and nullif(trim(provider.base_url), '') is not null
      )
    for update of route skip locked
  ) due;
  if cardinality(due_route_ids) = 0 then
    return 0;
  end if;

  with due as (
    select * from unnest(due_route_ids, due_statuses) as due(provider_model_id, next_status)
  ), activated as (
    update public.v2_model_provider_routes route
    set status = due.next_status,
        routing_enabled = true,
        provider_availability_status = case when due.next_status = 'active' then 'available' else 'preview' end,
        phaseo_status = 'enabled', access_scope = 'public',
        metadata = route.metadata || jsonb_build_object('release_scheduled', false, 'release_activated_at', now()),
        updated_at = now()
    from due where route.provider_model_id = due.provider_model_id
    returning route.provider_model_id
  ) select coalesce(array_agg(provider_model_id), '{}'::text[]) into activated_route_ids from activated;
  activated_count := cardinality(activated_route_ids);

  update public.v2_route_variants variant
  set status = route.status, routing_enabled = true, updated_at = now()
  from public.v2_model_provider_routes route
  where route.provider_model_id = variant.provider_model_id
    and route.provider_model_id = any(activated_route_ids)
    and route.metadata ->> 'managed_by' = 'provider_catalog'
    and route.metadata ->> 'release_scheduled' = 'false'
    and route.metadata ->> 'release_activated_at' is not null
    and variant.metadata ->> 'managed_by' = 'provider_catalog'
    and variant.metadata ->> 'source_run_id' = route.metadata ->> 'source_run_id';

  update public.v2_route_capabilities capability
  set status = case when route.status = 'active' then 'active' else 'degraded' end, updated_at = now()
  from public.v2_model_provider_routes route
  where route.provider_model_id = capability.provider_model_id
    and capability.capability_id = public.canonical_routing_capability_id(capability.capability_id)
    and route.provider_model_id = any(activated_route_ids)
    and route.metadata ->> 'managed_by' = 'provider_catalog'
    and route.metadata ->> 'release_scheduled' = 'false'
    and route.metadata ->> 'release_activated_at' is not null
    and capability.metadata ->> 'managed_by' = 'provider_catalog'
    and capability.metadata ->> 'source_run_id' = route.metadata ->> 'source_run_id';

  update public.v2_providers provider
  set status = case
        when provider.status = 'not_ready'
          or (provider.status = 'disabled' and provider.metadata -> 'self_serve' ->> 'status' = 'submitted')
          then 'beta'
        else provider.status
      end,
      routable = true, routing_enabled = true, updated_at = now()
  where (not (coalesce(provider.metadata, '{}'::jsonb) ? 'self_serve')
      or provider.metadata -> 'self_serve' ->> 'provider_review_status' = 'approved')
    and provider.provider_slug in (
      select distinct route.provider_slug
      from public.v2_model_provider_routes route
      where route.metadata ->> 'managed_by' = 'provider_catalog'
        and route.provider_model_id = any(activated_route_ids)
        and route.metadata ->> 'release_scheduled' = 'false'
        and route.metadata ->> 'release_activated_at' is not null
    );

  update public.v2_models model
  set hidden = false, released_at = coalesce(model.released_at, route.effective_from, now()), updated_at = now()
  from public.v2_model_provider_routes route
  where route.model_slug = model.model_slug
    and route.provider_model_id = any(activated_route_ids)
    and model.metadata ->> 'provider_catalog_owner' = route.provider_slug
    and route.metadata ->> 'managed_by' = 'provider_catalog'
    and route.metadata ->> 'release_scheduled' = 'false'
    and route.metadata ->> 'release_activated_at' is not null;

  update public.v2_labs lab
  set status = case when lab.status = 'disabled' then 'active' else lab.status end, updated_at = now()
  where lab.lab_slug in (
    select distinct model.lab_slug
    from public.v2_models model
    join public.v2_model_provider_routes route on route.model_slug = model.model_slug
    where model.metadata ->> 'created_from_provider_proposal' = 'true'
      and route.provider_model_id = any(activated_route_ids)
      and route.metadata ->> 'managed_by' = 'provider_catalog'
      and route.metadata ->> 'release_scheduled' = 'false'
      and route.metadata ->> 'release_activated_at' is not null
  );

  return activated_count;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."activate_due_provider_catalog_releases"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."activate_due_provider_catalog_releases"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/active_workload_identity_issuers.sql
CREATE OR REPLACE FUNCTION public.active_workload_identity_issuers ()
  RETURNS text[]
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select coalesce(array_agg(distinct policy.issuer order by policy.issuer), array[]::text[])
  from public.workload_identity_policies policy
  where policy.status = 'active';
$function$;

GRANT EXECUTE ON FUNCTION "public"."active_workload_identity_issuers"() TO "service_role";

COMMENT ON FUNCTION "public"."active_workload_identity_issuers"() IS 'Issuers named by at least one active workload identity policy. The gateway fetches signing keys only for these, so tokens naming any other Vercel team cannot make it fetch keys. Returns one array so the result is never cut off by a row limit.';

REVOKE ALL ON FUNCTION "public"."active_workload_identity_issuers"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/api_app_public_slug.sql
CREATE OR REPLACE FUNCTION public.api_app_public_slug (
  p_title  text,
  p_url    text,
  p_app_id text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  PARALLEL SAFE
  SET search_path TO ''
  AS $function$
  select public.api_app_slug_base(p_title) || '--' || left(md5(coalesce(p_app_id, '')), 12);
$function$;

GRANT EXECUTE ON FUNCTION "public"."api_app_public_slug"(text, text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."api_app_public_slug"(text, text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/api_app_slug_base.sql
CREATE OR REPLACE FUNCTION public.api_app_slug_base (
  p_title text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  PARALLEL SAFE
  SET search_path TO ''
  AS $function$
  select coalesce(
    nullif(
      trim(both '-' from regexp_replace(lower(coalesce(p_title, '')), '[^a-z0-9]+', '-', 'g')),
      ''
    ),
    'app'
  );
$function$;

GRANT EXECUTE ON FUNCTION "public"."api_app_slug_base"(text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."api_app_slug_base"(text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/api_app_url_group_key.sql
CREATE OR REPLACE FUNCTION public.api_app_url_group_key (
  p_url    text,
  p_app_id text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  PARALLEL SAFE
  SET search_path TO ''
  AS $function$
  select coalesce(
    nullif(lower(regexp_replace(btrim(coalesce(p_url, '')), '/+$', '')), ''),
    'app-id:' || p_app_id
  );
$function$;

GRANT EXECUTE ON FUNCTION "public"."api_app_url_group_key"(text, text) TO "anon", "authenticated";

