-- source: supabase/schemas/public/functions/approve_workspace_join_request.sql
CREATE OR REPLACE FUNCTION public.approve_workspace_join_request (
  p_request_id uuid
)
  RETURNS TABLE (
    id                uuid,
    workspace_id      uuid,
    requester_user_id uuid,
    invite_id         uuid
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_user_id uuid := auth.uid();
  v_req public.workspace_join_requests%rowtype;
  v_role public.workspace_role := 'member'::public.workspace_role;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'Unauthorized';
  end if;

  select *
    into v_req
  from public.workspace_join_requests
  where workspace_join_requests.id = p_request_id
    and public.is_workspace_admin(workspace_join_requests.workspace_id)
  for update;

  if not found then
    raise exception using errcode = '42501', message = 'Join request not found or not authorized';
  end if;

  if v_req.status <> 'pending'::public.join_request_status then
    raise exception using errcode = '23514', message = 'Request already decided';
  end if;

  if not public.is_workspace_admin(v_req.workspace_id) then
    raise exception using errcode = '42501', message = 'Only owners or admins may approve join requests.';
  end if;

  if v_req.invite_id is not null then
    update public.workspace_invites ti
      set uses_count = coalesce(ti.uses_count, 0) + 1
    where ti.id = v_req.invite_id
      and ti.workspace_id = v_req.workspace_id
      and (ti.expires_at is null or ti.expires_at > now())
      and (ti.max_uses is null or coalesce(ti.uses_count, 0) < ti.max_uses)
    returning ti.role into v_role;

    if not found then
      raise exception using errcode = '23514', message = 'Invite is invalid for this request';
    end if;
  end if;

  insert into public.workspace_members (workspace_id, user_id, role)
  values (v_req.workspace_id, v_req.requester_user_id, v_role)
  on conflict on constraint workspace_members_pkey do nothing;

  return query
  update public.workspace_join_requests r
     set status = 'approved'::public.join_request_status,
         decided_by = v_user_id,
         decided_at = now()
   where r.id = v_req.id
     and r.status = 'pending'::public.join_request_status
  returning r.id, r.workspace_id, r.requester_user_id, r.invite_id;

  if not found then
    raise exception using errcode = '23514', message = 'Request already decided';
  end if;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."approve_workspace_join_request"(uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."approve_workspace_join_request"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."approve_workspace_join_request"(uuid) FROM PUBLIC, "anon";

-- source: supabase/schemas/public/functions/attach_v2_request_fact_to_gateway_request.sql
CREATE OR REPLACE FUNCTION public.attach_v2_request_fact_to_gateway_request()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if new.gateway_request_id is null or new.gateway_request_created_at is null then
    select request.id, request.created_at
    into new.gateway_request_id, new.gateway_request_created_at
    from public.gateway_requests request
    where request.workspace_id = new.workspace_id
      and request.request_id = new.request_id
    order by
      case when request.created_at = new.occurred_at then 0 else 1 end,
      abs(extract(epoch from (request.created_at - new.occurred_at))),
      request.created_at desc
    limit 1;
  end if;

  if new.gateway_request_id is null or new.gateway_request_created_at is null then
    raise exception using
      errcode = '23503',
      message = 'v2_request_fact_requires_gateway_request';
  end if;

  update public.gateway_requests request
  set detail_metadata = coalesce(request.detail_metadata, '{}'::jsonb)
    || jsonb_build_object(
      'client_source', new.safe_metadata->'client_source',
      'request', coalesce(request.detail_metadata->'request', '{}'::jsonb)
        || jsonb_build_object('user_agent', new.user_agent)
    )
  where request.id = new.gateway_request_id
    and request.created_at = new.gateway_request_created_at;

  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."attach_v2_request_fact_to_gateway_request"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."attach_v2_request_fact_to_gateway_request"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/audit_catalog_policy_approval.sql
CREATE OR REPLACE FUNCTION public.audit_catalog_policy_approval()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
BEGIN
  INSERT INTO public.provider_catalog_policy_approval_events(provider_slug, previous_approval, current_approval)
  VALUES (coalesce(NEW.provider_slug, OLD.provider_slug), CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,
    CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END);
  RETURN NULL;
END $function$;

REVOKE ALL ON FUNCTION public.audit_catalog_policy_approval() FROM PUBLIC, anon, authenticated;

-- source: supabase/schemas/public/functions/backfill_gateway_request_normalized_usage.sql
CREATE OR REPLACE FUNCTION public.backfill_gateway_request_normalized_usage (
  p_since timestamp with time zone DEFAULT (now() - '90 days'::interval),
  p_until timestamp with time zone DEFAULT now()
)
  RETURNS bigint
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_count bigint;
begin
  update public.gateway_requests
  set usage = usage
  where created_at >= p_since
    and created_at < p_until;

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."backfill_gateway_request_normalized_usage"(timestamp WITH time zone, timestamp WITH time zone) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."backfill_gateway_request_normalized_usage"(timestamp WITH time zone, timestamp WITH time zone) TO "service_role";

COMMENT ON FUNCTION "public"."backfill_gateway_request_normalized_usage"(timestamp with time zone, timestamp with time zone) IS 'Recomputes normalized per-request usage columns for gateway_requests in a bounded created_at window.';

-- source: supabase/schemas/public/functions/begin_provider_catalog_refresh.sql
CREATE OR REPLACE FUNCTION public.begin_provider_catalog_refresh (
  p_provider_slug text
)
  RETURNS void
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  update public.provider_catalog_sources
  set refresh_requested = false,
      next_poll_at = case when management_mode = 'managed' then null else next_poll_at end
  where provider_slug = p_provider_slug;
$function$;

GRANT EXECUTE ON FUNCTION "public"."begin_provider_catalog_refresh"(text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."begin_provider_catalog_refresh"(text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/broadcast_destination_health_summary.sql
CREATE OR REPLACE FUNCTION public.broadcast_destination_health_summary (
  p_workspace_id uuid
)
  RETURNS TABLE (
    destination_id uuid,
    last_success_at timestamp with time zone,
    last_failure_at timestamp with time zone,
    last_http_status integer,
    last_error text,
    consecutive_failures integer,
    delivered_24h bigint,
    failed_24h bigint
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  SET statement_timeout TO '5s'
  AS $function$
  -- Counts are hourly, so the last 24 hours are the current UTC hour and the 23
  -- before it: between 23 and 24 hours of traffic, never more than 24.
  select
    destination.id,
    health.last_success_at,
    health.last_failure_at,
    health.last_http_status,
    health.last_error,
    coalesce(health.consecutive_failures, 0),
    coalesce(counts.delivered, 0),
    coalesce(counts.failed, 0)
  from public.workspace_broadcast_destinations destination
  left join public.broadcast_destination_health health on health.destination_id = destination.id
  left join (
    select hourly.destination_id, sum(hourly.delivered) as delivered, sum(hourly.failed) as failed
    from public.broadcast_destination_delivery_hourly hourly
    where hourly.workspace_id = p_workspace_id
      and hourly.hour > date_trunc('hour', now(), 'UTC') - interval '24 hours'
    group by hourly.destination_id
  ) counts on counts.destination_id = destination.id
  where destination.workspace_id = p_workspace_id;
$function$;

GRANT EXECUTE ON FUNCTION "public"."broadcast_destination_health_summary"(uuid) TO "service_role";

COMMENT ON FUNCTION "public"."broadcast_destination_health_summary"(uuid) IS 'Each Broadcast destination in a workspace with its latest delivery outcome, failure streak, and events delivered and failed in the last 24 hours.';

REVOKE ALL ON FUNCTION "public"."broadcast_destination_health_summary"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/bump_web_cache_generation.sql
CREATE OR REPLACE FUNCTION public.bump_web_cache_generation (
  p_scope         text,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
  RETURNS bigint
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  insert into public.web_cache_generations (scope, generation, updated_at, updated_by)
  values (p_scope, 2, now(), p_actor_user_id)
  on conflict (scope) do update
    set generation = public.web_cache_generations.generation + 1,
        updated_at = now(),
        updated_by = excluded.updated_by
  returning generation;
$function$;

GRANT EXECUTE ON FUNCTION "public"."bump_web_cache_generation"(text, uuid) TO "service_role";

COMMENT ON FUNCTION "public"."bump_web_cache_generation"(text, uuid) IS 'Atomically advances a browser-visible cache generation after an administrative cache purge.';

REVOKE ALL ON FUNCTION "public"."bump_web_cache_generation"(text, uuid) FROM PUBLIC, "anon", "authenticated";

