-- source: supabase/schemas/public/functions/calculate_workspace_previous_month_spend.sql
CREATE OR REPLACE FUNCTION public.calculate_workspace_previous_month_spend (
  p_team_id uuid
)
  RETURNS numeric
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
DECLARE
    v_spend_nanos bigint;
    v_spend_usd numeric(12, 2);
    v_prev_month_start timestamptz;
    v_prev_month_end timestamptz;
BEGIN
    -- Calculate previous calendar month boundaries
    v_prev_month_start := date_trunc('month', now() - interval '1 month');
    v_prev_month_end := date_trunc('month', now());

    -- Sum all successful request costs from previous month
    SELECT COALESCE(SUM(cost_nanos), 0)
    INTO v_spend_nanos
    FROM private.v2_rpc_gateway_requests_compat
    WHERE team_id = p_team_id
      AND success = true
      AND created_at >= v_prev_month_start
      AND created_at < v_prev_month_end;

    -- Convert nanos to USD
    v_spend_usd := ROUND((v_spend_nanos::numeric / 1000000000.0)::numeric, 2);

    RETURN v_spend_usd;
END;
$function$;

GRANT EXECUTE ON FUNCTION "public"."calculate_workspace_previous_month_spend"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."calculate_workspace_previous_month_spend"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/cancel_slack_agent_schedule.sql
CREATE OR REPLACE FUNCTION public.cancel_slack_agent_schedule (
  p_installation_id uuid,
  p_schedule_id     uuid,
  p_slack_user_id   text
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- The Slack agent's cancel_schedule tool: deletes one of the installation's
-- schedules for the person who set it up, or for someone whose Slack account is
-- linked to an owner or admin of the installation's Phaseo workspace. Returns
-- deleted, not_allowed or not_found. Service role only.
declare
  v_created_by text;
  v_workspace_id uuid;
begin
  select schedule.created_by, installation.workspace_id into v_created_by, v_workspace_id
  from public.slack_agent_schedules schedule
  join public.slack_installations installation on installation.id = schedule.installation_id
  where schedule.id = p_schedule_id and schedule.installation_id = p_installation_id
  for update of schedule;
  if not found then
    return 'not_found';
  end if;
  if v_created_by is distinct from p_slack_user_id and not exists (
    select 1
    from public.slack_user_links link
    where link.installation_id = p_installation_id and link.slack_user_id = p_slack_user_id
      and (
        exists (
          select 1 from public.workspace_members member
          where member.workspace_id = v_workspace_id and member.user_id = link.user_id and member.role in ('owner', 'admin')
        )
        or exists (
          select 1 from public.workspaces workspace
          where workspace.id = v_workspace_id and workspace.owner_user_id = link.user_id
        )
      )
  ) then
    return 'not_allowed';
  end if;
  delete from public.slack_agent_schedules schedule where schedule.id = p_schedule_id;
  return 'deleted';
end;
$function$;

COMMENT ON FUNCTION "public"."cancel_slack_agent_schedule"(uuid, uuid, text) IS 'For the Slack Worker''s cancel_schedule tool: deletes a schedule for its creator, or for a Slack person linked to an owner or admin of the workspace. Returns deleted, not_allowed or not_found.';

GRANT EXECUTE ON FUNCTION "public"."cancel_slack_agent_schedule"(uuid, uuid, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."cancel_slack_agent_schedule"(uuid, uuid, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/canonical_routing_capability_id.sql
create or replace function public.canonical_routing_capability_id(p_id text)
returns text language sql immutable strict parallel safe
set search_path = pg_catalog
as $$
  select case replace(lower(trim(p_id)), '/', '.')
    when 'image.generations' then 'image.generate'
    when 'image.edits' then 'image.edit'
    when 'decision.make' then 'decisions.make'
    when 'systemone' then 'decisions.make'
    when 'system.one' then 'decisions.make'
    when 'typed.decisions' then 'decisions.make'
    when 'audio.translation' then 'audio.translations'
    when 'batch.create' then 'batch'
    when 'document.parse' then 'parse'
    when 'videos' then 'video.generate'
    when 'audio.transcribe' then 'audio.transcription'
    when 'audio.transcriptions' then 'audio.transcription'
    when 'embeddings' then 'text.embed'
    when 'rerank' then 'text.rerank'
    when 'rerank.create' then 'text.rerank'
    when 'images.generations' then 'image.generate'
    when 'images.generate' then 'image.generate'
    when 'images.edits' then 'image.edit'
    when 'realtime' then 'audio.realtime'
    when 'chat.completions' then 'text.generate'
    when 'responses' then 'text.generate'
    when 'messages' then 'text.generate'
    when 'chat.generate' then 'text.generate'
    when 'moderations' then 'text.moderate'
    when 'moderations.create' then 'text.moderate'
    when 'moderation' then 'text.moderate'
    when 'audio.translate' then 'audio.translations'
    when 'video.generation' then 'video.generate'
    when 'video.generations' then 'video.generate'
    else case when replace(lower(trim(p_id)), '/', '.') = any(array[
      'text.generate','text.embed','text.rerank','text.moderate',
      'image.generate','image.edit','image.vary','video.generate','video.edit',
      'audio.speech','audio.transcription','audio.translations','audio.realtime',
      'music.generate','decisions.make','extraction.extract','ocr','parse','batch',
      'tool.call','structured.output','voice.design'
    ]) then replace(lower(trim(p_id)), '/', '.') else null end
  end;
$$;

GRANT EXECUTE ON FUNCTION "public"."canonical_routing_capability_id"(text) TO "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."canonical_routing_capability_id"(text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."canonical_routing_capability_id"(text) FROM PUBLIC;

-- source: supabase/schemas/public/functions/canonicalize_subscription_identity.sql
create function public.canonicalize_subscription_identity() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$ begin
  if tg_table_name='v2_subscription_plans' then
    new.canonical_plan_uuid:=coalesce(new.canonical_plan_uuid,new.plan_uuid);
  else
    select coalesce(canonical_plan_uuid,plan_uuid) into new.plan_uuid from v2_subscription_plans where plan_uuid=new.plan_uuid;
  end if;
  return new;
end $$;

revoke all on function public.canonicalize_subscription_identity() from public,anon,authenticated;

grant execute on function public.canonicalize_subscription_identity() to service_role;

-- source: supabase/schemas/public/functions/capture_catalogue_notification_events.sql
CREATE OR REPLACE FUNCTION public.capture_catalogue_notification_events (
  p_limit                      integer DEFAULT 2000,
  p_max_models_per_transaction integer DEFAULT 20
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Turns new v2_catalogue_row_history rows about public models into notification events:
--   gateway_available      the first public route Phaseo routes for a model
--   provider_added         a further provider routed for a model already on Phaseo
--   price_changed          a standard, global price of a public route changed, in place or
--                          through a new SKU version (one event per model, provider and transaction)
--   deprecation_announced  a model newly marked deprecated or retired
--   provider_launched      a bulk transaction gave a provider its first public routes
-- model_released comes from the public announcer (private.record_model_released_notification).
--
-- Rows are read in id order, but only up to the sequence position the previous call recorded
-- and only once every transaction older than that call has finished, so a long transaction
-- that commits after later ids cannot be skipped. A transaction touching more than
-- p_max_models_per_transaction models is a bulk sync or backfill: it is recorded and its rows
-- are skipped, and it produces at most one provider_launched event per provider it brings to
-- Phaseo. It is sized by all of its unread rows before any of them is read, so a transaction
-- that spans several calls is skipped from its first row.
-- Rows older than two days only move the cursor, so resuming the job sends no stale news.
declare
  v_source constant text := 'v2_catalogue_row_history';
  v_cursor public.catalogue_notification_cursors%rowtype;
  v_sequence bigint;
  v_xmin bigint;
  v_xmax bigint;
  v_upper bigint;
  v_last bigint;
  v_ids bigint[] := '{}';
  v_transactions bigint[] := '{}';
  v_bulk bigint[] := '{}';
  v_fresh boolean := false;
  v_relevant bigint[] := '{}';
  v_scanned integer := 0;
  v_skipped integer := 0;
  v_emitted integer := 0;
  v_count integer;
begin
  if p_limit is null or p_limit < 1 or p_limit > 10000 then
    raise exception 'invalid_catalogue_notification_capture_limit';
  end if;
  if p_max_models_per_transaction is null or p_max_models_per_transaction < 1 then
    raise exception 'invalid_catalogue_notification_bulk_threshold';
  end if;

  select * into v_cursor from public.catalogue_notification_cursors c where c.source = v_source for update;

  -- Sequence first, then the snapshot: any transaction that takes a history id after this
  -- read was given its transaction id after the snapshot, so it is at or above v_xmax.
  v_sequence := coalesce(pg_catalog.pg_sequence_last_value(
    pg_catalog.pg_get_serial_sequence('public.v2_catalogue_row_history', 'event_id')::regclass), 0);
  v_xmin := pg_catalog.pg_snapshot_xmin(pg_catalog.pg_current_snapshot())::text::bigint;
  v_xmax := pg_catalog.pg_snapshot_xmax(pg_catalog.pg_current_snapshot())::text::bigint;

  if v_cursor.source is null then
    -- First run: start from now rather than replaying the whole history.
    insert into public.catalogue_notification_cursors (source, last_history_event_id, checkpoint_event_id, checkpoint_xmax)
    values (v_source, v_sequence, v_sequence, v_xmax)
    on conflict (source) do nothing;
    return jsonb_build_object('initialized', true, 'scanned', 0, 'emitted', 0, 'skippedTransactions', 0, 'cursor', v_sequence);
  end if;

  if v_cursor.checkpoint_xmax is not null and v_xmin >= v_cursor.checkpoint_xmax then
    v_upper := v_cursor.checkpoint_event_id;
  end if;

  if v_upper is not null and v_upper > v_cursor.last_history_event_id then
    select coalesce(array_agg(w.event_id order by w.event_id), '{}'), max(w.event_id), count(*)
      into v_ids, v_last, v_scanned
    from (
      select h.event_id
      from public.v2_catalogue_row_history h
      where h.event_id > v_cursor.last_history_event_id and h.event_id <= v_upper
      order by h.event_id
      limit p_limit
    ) w;
    if v_scanned < p_limit then
      v_last := v_upper;
    end if;

    -- Size each transaction in this page by every unread row it wrote, not only those in the
    -- page (a primary key range scan from the cursor). Every transaction with a row up to
    -- v_upper has finished, so all of its rows are visible now; any below the cursor were read
    -- by an earlier call, which sized the whole transaction then and recorded it if it was bulk.
    -- A page that is all older than two days emits nothing and is not sized.
    select coalesce(array_agg(distinct h.transaction_id) filter (where h.operation <> 'BASELINE'), '{}'),
           coalesce(bool_or(h.recorded_at > now() - interval '2 days'), false)
      into v_transactions, v_fresh
    from public.v2_catalogue_row_history h
    where h.event_id = any (v_ids);

    if v_fresh and cardinality(v_transactions) > 0 then
      with recorded as (
        insert into public.catalogue_notification_skipped_transactions (transaction_id, model_count, row_count, first_history_event_id)
        select h.transaction_id, count(distinct h.model_slug)::integer, count(*)::integer, min(h.event_id)
        from public.v2_catalogue_row_history h
        where h.event_id > v_cursor.last_history_event_id
          and h.transaction_id = any (v_transactions)
          and h.operation <> 'BASELINE'
        group by h.transaction_id
        having count(distinct h.model_slug) > p_max_models_per_transaction
        on conflict (transaction_id) do nothing
        returning transaction_id
      )
      select coalesce(array_agg(r.transaction_id), '{}'), count(*)::integer into v_bulk, v_skipped from recorded r;
    end if;

    -- A bulk transaction that switches on public routes for a provider with none before is one
    -- piece of news: the provider launched on Phaseo, with the newest of its models named. A
    -- provider counts as already public when one of its routes is routed now and the history
    -- does not show that route switched on in this transaction or later, or when this
    -- transaction changed a route that was routed before it.
    if cardinality(v_bulk) > 0 then
      with launched_models as (
        select distinct on (h.transaction_id, r.provider_slug, r.model_slug)
          h.transaction_id,
          s.first_history_event_id,
          r.provider_slug,
          r.model_slug,
          h.event_id,
          h.recorded_at,
          coalesce(nullif(btrim(m.name), ''), m.model_slug) as model_name,
          m.released_at
        from public.catalogue_notification_skipped_transactions s
        join public.v2_catalogue_row_history h on h.event_id >= s.first_history_event_id and h.transaction_id = s.transaction_id
        join public.v2_model_provider_routes r on r.provider_model_id = h.after_state ->> 'provider_model_id'
        join public.v2_models m on m.model_slug = r.model_slug
        where s.transaction_id = any (v_bulk)
          and h.table_name = 'v2_model_provider_routes'
          and h.operation in ('INSERT', 'UPDATE')
          and h.after_state ->> 'routing_enabled' = 'true'
          and coalesce(h.before_state ->> 'routing_enabled', 'false') <> 'true'
          and h.recorded_at > now() - interval '2 days'
          and r.routing_enabled and r.access_scope = 'public' and not r.is_stealth and r.status in ('active', 'degraded')
          and public.catalog_model_is_public(r.model_slug)
        order by h.transaction_id, r.provider_slug, r.model_slug, h.event_id
      ),
      launched as (
        select
          lm.transaction_id,
          lm.provider_slug,
          min(lm.first_history_event_id) as first_event_id,
          count(*)::integer as model_count,
          (array_agg(lm.model_name order by lm.released_at desc nulls last, lm.model_name))[1:3] as names,
          (array_agg(lm.model_slug order by lm.released_at desc nulls last, lm.model_name))[1:3] as model_slugs,
          min(lm.event_id) as event_id,
          max(lm.recorded_at) as recorded_at
        from launched_models lm
        group by lm.transaction_id, lm.provider_slug
      )
      insert into public.catalogue_notification_events (
        kind, dedupe_key, provider_slug, title, body, href, payload, source_history_event_id, occurred_at
      )
      select
        'provider_launched',
        'provider_launched:' || l.provider_slug || ':' || l.transaction_id,
        l.provider_slug,
        left(v.provider_name || ' is now on Phaseo', 300),
        left(case
          when l.model_count = 1 then 'Serving ' || l.names[1] || '.'
          when l.model_count <= 3 then 'Serving ' || array_to_string(l.names[1:l.model_count - 1], ', ') || ' and ' || l.names[l.model_count] || '.'
          else l.model_count || ' models, including ' || l.names[1] || ', ' || l.names[2] || ' and ' || l.names[3] || '.'
        end, 1000),
        '/api-providers/' || l.provider_slug,
        jsonb_build_object('providerName', v.provider_name, 'modelCount', l.model_count, 'modelIds', to_jsonb(l.model_slugs)),
        l.event_id,
        l.recorded_at
      from launched l
      left join public.v2_providers p on p.provider_slug = l.provider_slug
      cross join lateral (select coalesce(nullif(btrim(p.name), ''), l.provider_slug) as provider_name) v
      where not exists (
          select 1
          from public.v2_model_provider_routes o
          where o.provider_slug = l.provider_slug
            and o.routing_enabled and o.access_scope = 'public' and not o.is_stealth and o.status in ('active', 'degraded')
            and not exists (
              select 1 from public.v2_catalogue_row_history e
              where e.model_slug = o.model_slug and e.event_id >= l.first_event_id
                and e.table_name = 'v2_model_provider_routes'
                and e.after_state ->> 'provider_model_id' = o.provider_model_id
                and e.after_state ->> 'routing_enabled' = 'true'
                and coalesce(e.before_state ->> 'routing_enabled', 'false') <> 'true'
            )
            and public.catalog_model_is_public(o.model_slug)
        )
        and not exists (
          select 1 from public.v2_catalogue_row_history b
          where b.event_id >= l.first_event_id and b.transaction_id = l.transaction_id
            and b.table_name = 'v2_model_provider_routes'
            and b.before_state ->> 'provider_slug' = l.provider_slug
            and b.before_state ->> 'routing_enabled' = 'true'
            and coalesce(b.before_state ->> 'access_scope', 'public') = 'public'
            and coalesce(b.before_state ->> 'is_stealth', 'false') <> 'true'
        )
      on conflict (dedupe_key) do nothing;
      get diagnostics v_count = row_count;
      v_emitted := v_emitted + v_count;
    end if;

    select coalesce(array_agg(h.event_id), '{}') into v_relevant
    from public.v2_catalogue_row_history h
    where h.event_id = any (v_ids)
      and h.operation in ('INSERT', 'UPDATE')
      and h.table_name in ('v2_models', 'v2_model_provider_routes', 'v2_pricing_sku_meters')
      and h.model_slug is not null
      and h.recorded_at > now() - interval '2 days'
      and not exists (
        select 1 from public.catalogue_notification_skipped_transactions s where s.transaction_id = h.transaction_id
      );

    -- Routing switched on for a public route.
    insert into public.catalogue_notification_events (
      kind, dedupe_key, model_slug, lab_slug, provider_slug, title, body, href, payload, source_history_event_id, occurred_at
    )
    select distinct on (c.dedupe_key)
      c.kind,
      c.dedupe_key,
      c.model_slug,
      c.lab_slug,
      c.provider_slug,
      left(case
        when c.kind = 'gateway_available' then c.model_name || ' is now on Phaseo'
        else c.model_name || ' is now available from ' || c.provider_name
      end, 300),
      left(case
        when c.kind = 'gateway_available' then 'You can now use it through Phaseo, served by ' || c.provider_name || '.'
        else c.provider_name || ' is now a provider for ' || c.model_name || ' on Phaseo.'
      end, 1000),
      '/models/' || c.model_slug,
      jsonb_build_object('modelName', c.model_name, 'labName', c.lab_name, 'providerName', c.provider_name, 'providerModelId', c.provider_model_id),
      c.event_id,
      c.recorded_at
    from (
      select
        h.event_id,
        h.recorded_at,
        r.model_slug,
        r.provider_slug,
        r.provider_model_id,
        m.lab_slug,
        coalesce(nullif(btrim(m.name), ''), m.model_slug) as model_name,
        coalesce(nullif(btrim(l.name), ''), m.lab_slug) as lab_name,
        coalesce(nullif(btrim(p.name), ''), r.provider_slug) as provider_name,
        case when routed_before.model_on_phaseo then 'provider_added' else 'gateway_available' end as kind,
        case
          when routed_before.model_on_phaseo then 'provider_added:' || r.model_slug || ':' || r.provider_slug
          else 'gateway_available:' || r.model_slug
        end as dedupe_key,
        routed_before.provider_on_phaseo
      from public.v2_catalogue_row_history h
      join public.v2_model_provider_routes r on r.provider_model_id = h.after_state ->> 'provider_model_id'
      join public.v2_models m on m.model_slug = r.model_slug
      left join public.v2_labs l on l.lab_slug = m.lab_slug
      left join public.v2_providers p on p.provider_slug = r.provider_slug
      cross join lateral (
        -- Routed before: by an earlier transaction in the history, or by another route that is
        -- routed now and was not switched on in this same transaction.
        select
          exists (
            select 1 from public.v2_catalogue_row_history e
            where e.model_slug = r.model_slug and e.event_id < h.event_id and e.transaction_id <> h.transaction_id
              and e.table_name = 'v2_model_provider_routes'
              and e.after_state ->> 'routing_enabled' = 'true'
              and coalesce(e.after_state ->> 'access_scope', 'public') = 'public'
              and coalesce(e.after_state ->> 'is_stealth', 'false') <> 'true'
          ) or exists (
            select 1 from public.v2_model_provider_routes o
            where o.model_slug = r.model_slug and o.provider_model_id <> r.provider_model_id
              and o.routing_enabled and o.access_scope = 'public' and not o.is_stealth
              and not exists (
                select 1 from public.v2_catalogue_row_history t
                where t.model_slug = r.model_slug and t.transaction_id = h.transaction_id
                  and t.table_name = 'v2_model_provider_routes' and t.after_state ->> 'provider_model_id' = o.provider_model_id
              )
          ) as model_on_phaseo,
          exists (
            select 1 from public.v2_catalogue_row_history e
            where e.model_slug = r.model_slug and e.event_id < h.event_id and e.transaction_id <> h.transaction_id
              and e.table_name = 'v2_model_provider_routes'
              and e.after_state ->> 'provider_slug' = r.provider_slug
              and e.after_state ->> 'routing_enabled' = 'true'
              and coalesce(e.after_state ->> 'access_scope', 'public') = 'public'
              and coalesce(e.after_state ->> 'is_stealth', 'false') <> 'true'
          ) or exists (
            select 1 from public.v2_model_provider_routes o
            where o.model_slug = r.model_slug and o.provider_slug = r.provider_slug and o.provider_model_id <> r.provider_model_id
              and o.routing_enabled and o.access_scope = 'public' and not o.is_stealth
              and not exists (
                select 1 from public.v2_catalogue_row_history t
                where t.model_slug = r.model_slug and t.transaction_id = h.transaction_id
                  and t.table_name = 'v2_model_provider_routes' and t.after_state ->> 'provider_model_id' = o.provider_model_id
              )
          ) as provider_on_phaseo
      ) routed_before
      where h.event_id = any (v_relevant)
        and h.table_name = 'v2_model_provider_routes'
        and h.after_state ->> 'routing_enabled' = 'true'
        and coalesce(h.before_state ->> 'routing_enabled', 'false') <> 'true'
        and r.routing_enabled and r.access_scope = 'public' and not r.is_stealth and r.status in ('active', 'degraded')
        and public.catalog_model_is_public(r.model_slug)
    ) c
    where not c.provider_on_phaseo
    order by c.dedupe_key, c.event_id
    on conflict (dedupe_key) do nothing;
    get diagnostics v_count = row_count;
    v_emitted := v_emitted + v_count;

    -- Price changes on the standard global price of a public route.
    with changed as (
      select
        h.event_id,
        h.transaction_id,
        h.recorded_at,
        s.provider_model_id,
        s.effective_from,
        h.after_state ->> 'meter_key' as meter_key,
        h.after_state ->> 'modality' as modality,
        h.after_state ->> 'direction' as direction,
        h.after_state ->> 'unit' as unit,
        nullif(btrim(h.after_state ->> 'display_unit'), '') as display_unit,
        nullif(btrim(h.after_state ->> 'display_label'), '') as display_label,
        coalesce((h.after_state ->> 'meter_order')::integer, 100) as meter_order,
        (h.after_state ->> 'unit_quantity')::numeric as unit_quantity,
        (h.after_state ->> 'price_nanos')::numeric / (h.after_state ->> 'unit_quantity')::numeric as new_per_unit,
        previous.price_nanos / nullif(previous.unit_quantity, 0) as old_per_unit
      from public.v2_catalogue_row_history h
      join public.v2_pricing_skus s on s.sku_id = (h.after_state ->> 'sku_id')::uuid
      cross join lateral (
        -- The price this row replaced: its own previous value, or the same meter on the
        -- previous version of the SKU.
        select (h.before_state ->> 'price_nanos')::numeric as price_nanos, (h.before_state ->> 'unit_quantity')::numeric as unit_quantity
        where h.operation = 'UPDATE'
        union all
        select * from (
          select pm.price_nanos, pm.unit_quantity
          from public.v2_pricing_skus ps
          join public.v2_pricing_sku_meters pm on pm.sku_id = ps.sku_id and pm.meter_key = h.after_state ->> 'meter_key' and pm.billable
          where h.operation = 'INSERT' and ps.provider_model_id = s.provider_model_id and ps.sku_code = s.sku_code and ps.version < s.version
          order by ps.version desc
          limit 1
        ) previous_version
      ) previous
      where h.event_id = any (v_relevant)
        and h.table_name = 'v2_pricing_sku_meters'
        and coalesce(h.after_state ->> 'billable', 'true') = 'true'
        and (h.after_state ->> 'meter_key') !~ 'cache'
        and (h.after_state ->> 'unit_quantity')::numeric > 0
        and s.region is null and coalesce(s.service_tier_slug, 'standard') = 'standard'
        -- The SKU was live when the price changed; one superseded since still reports it.
        and s.status in ('active', 'deprecated')
        and (s.effective_to is null or s.effective_to > h.recorded_at)
    ),
    described as (
      select distinct on (r.model_slug, r.provider_slug, c.transaction_id, c.meter_key)
        c.*,
        r.model_slug,
        r.provider_slug,
        case when c.modality = 'text' and c.direction = 'input' then 0 when c.modality = 'text' and c.direction = 'output' then 1 else 2 end as headline_rank,
        case
          when c.modality = 'text' and c.direction in ('input', 'output') then c.direction
          else lower(coalesce(c.display_label, c.meter_key))
        end as label,
        case when c.unit = 'token' then '1M tokens' else coalesce(c.display_unit, c.unit) end as unit_label,
        case when c.unit = 'token' then c.old_per_unit / 1000 else c.old_per_unit * c.unit_quantity / 1000000000 end as old_amount,
        case when c.unit = 'token' then c.new_per_unit / 1000 else c.new_per_unit * c.unit_quantity / 1000000000 end as new_amount
      from changed c
      join public.v2_model_provider_routes r on r.provider_model_id = c.provider_model_id
      where c.old_per_unit is not null and c.old_per_unit <> c.new_per_unit
        and r.access_scope = 'public' and not r.is_stealth and r.status in ('active', 'degraded')
        and public.catalog_model_is_public(r.model_slug)
      order by r.model_slug, r.provider_slug, c.transaction_id, c.meter_key, c.event_id
    ),
    grouped as (
      select
        d.model_slug,
        d.provider_slug,
        d.transaction_id,
        min(d.event_id) as event_id,
        max(d.recorded_at) as recorded_at,
        max(d.effective_from) as effective_from,
        jsonb_agg(jsonb_build_object(
          'meter', d.meter_key, 'label', d.label, 'unit', d.unit_label, 'old', d.old_amount, 'new', d.new_amount,
          'direction', case when d.new_amount < d.old_amount then 'down' else 'up' end
        ) order by d.headline_rank, d.meter_order, d.meter_key) as changes
      from described d
      group by d.model_slug, d.provider_slug, d.transaction_id
    )
    insert into public.catalogue_notification_events (
      kind, dedupe_key, model_slug, lab_slug, provider_slug, title, body, href, payload, source_history_event_id, occurred_at
    )
    select
      'price_changed',
      'price_changed:' || g.model_slug || ':' || g.provider_slug || ':' || g.transaction_id,
      g.model_slug,
      m.lab_slug,
      g.provider_slug,
      left(v.model_name || ' ' || (g.changes -> 0 ->> 'label') || ' price '
        || case
          when v.scheduled then case when g.changes -> 0 ->> 'direction' = 'down' then 'will fall' else 'will rise' end
          else case when g.changes -> 0 ->> 'direction' = 'down' then 'fell' else 'rose' end
        end
        || ' from ' || private.catalogue_notification_usd((g.changes -> 0 ->> 'old')::numeric)
        || ' to ' || private.catalogue_notification_usd((g.changes -> 0 ->> 'new')::numeric)
        || ' per ' || (g.changes -> 0 ->> 'unit')
        || case when v.scheduled then ' on ' || to_char(g.effective_from at time zone 'UTC', 'FMDD Mon YYYY') else '' end, 300),
      left('From ' || v.provider_name || '.' || coalesce((
        select string_agg(
          ' ' || upper(left(x.change ->> 'label', 1)) || substr(x.change ->> 'label', 2) || ': '
            || private.catalogue_notification_usd((x.change ->> 'old')::numeric) || ' to '
            || private.catalogue_notification_usd((x.change ->> 'new')::numeric) || ' per ' || (x.change ->> 'unit') || '.',
          '' order by x.ord)
        from jsonb_array_elements(g.changes) with ordinality as x(change, ord)
        where x.ord > 1
      ), ''), 1000),
      '/models/' || g.model_slug,
      jsonb_build_object(
        'modelName', v.model_name, 'providerName', v.provider_name, 'direction', g.changes -> 0 ->> 'direction',
        'effectiveFrom', g.effective_from, 'changes', g.changes
      ),
      g.event_id,
      g.recorded_at
    from grouped g
    join public.v2_models m on m.model_slug = g.model_slug
    left join public.v2_providers p on p.provider_slug = g.provider_slug
    cross join lateral (
      select
        coalesce(nullif(btrim(m.name), ''), m.model_slug) as model_name,
        coalesce(nullif(btrim(p.name), ''), g.provider_slug) as provider_name,
        g.effective_from > now() + interval '1 hour' as scheduled
    ) v
    on conflict (dedupe_key) do nothing;
    get diagnostics v_count = row_count;
    v_emitted := v_emitted + v_count;

    -- A model newly marked deprecated or retired, and still marked now.
    insert into public.catalogue_notification_events (
      kind, dedupe_key, model_slug, lab_slug, title, body, href, payload, source_history_event_id, occurred_at
    )
    select distinct on (m.model_slug)
      'deprecation_announced',
      'deprecation_announced:' || m.model_slug,
      m.model_slug,
      m.lab_slug,
      left(case
        when v.retires_at > now() then v.model_name || ' will be retired on ' || to_char(v.retires_at at time zone 'UTC', 'FMDD Mon YYYY')
        when v.retires_at is not null or m.status = 'retired' or m.catalogue_status = 'retired' then v.model_name || ' has been retired'
        else v.model_name || ' is deprecated'
      end, 300),
      left(v.lab_name || ' has deprecated ' || v.model_name || '.'
        || coalesce(' Suggested replacement: ' || nullif(btrim(replacement.name), '') || '.', ''), 1000),
      '/models/' || m.model_slug,
      jsonb_build_object(
        'modelName', v.model_name, 'labName', v.lab_name, 'deprecatedAt', m.deprecated_at, 'retiresAt', v.retires_at,
        'replacementModelId', replacement.model_slug
      ),
      h.event_id,
      h.recorded_at
    from public.v2_catalogue_row_history h
    join public.v2_models m on m.model_slug = h.model_slug
    left join public.v2_labs l on l.lab_slug = m.lab_slug
    left join public.v2_models replacement
      on replacement.model_slug = m.replacement_model_slug and public.catalog_model_is_public(replacement.model_slug)
    cross join lateral (
      select
        coalesce(m.retired_at, m.removal_date) as retires_at,
        coalesce(nullif(btrim(m.name), ''), m.model_slug) as model_name,
        coalesce(nullif(btrim(l.name), ''), m.lab_slug) as lab_name
    ) v
    where h.event_id = any (v_relevant)
      and h.table_name = 'v2_models'
      and h.operation = 'UPDATE'
      and not (
        coalesce(h.before_state ->> 'status', '') in ('deprecated', 'retired')
        or coalesce(h.before_state ->> 'catalogue_status', '') in ('deprecated', 'retired')
        or h.before_state ->> 'deprecated_at' is not null
        or h.before_state ->> 'retired_at' is not null
      )
      and (
        coalesce(h.after_state ->> 'status', '') in ('deprecated', 'retired')
        or coalesce(h.after_state ->> 'catalogue_status', '') in ('deprecated', 'retired')
        or h.after_state ->> 'deprecated_at' is not null
        or h.after_state ->> 'retired_at' is not null
      )
      and (
        m.status in ('deprecated', 'retired') or m.catalogue_status in ('deprecated', 'retired')
        or m.deprecated_at is not null or m.retired_at is not null
      )
      and public.catalog_model_is_public(m.model_slug)
    order by m.model_slug, h.event_id
    on conflict (dedupe_key) do nothing;
    get diagnostics v_count = row_count;
    v_emitted := v_emitted + v_count;

    update public.catalogue_notification_cursors
    set last_history_event_id = v_last, updated_at = now()
    where source = v_source;
    v_cursor.last_history_event_id := v_last;
  end if;

  -- Record the next checkpoint once the current one has been read up to.
  if v_cursor.checkpoint_xmax is null or v_cursor.last_history_event_id >= v_cursor.checkpoint_event_id then
    update public.catalogue_notification_cursors
    set checkpoint_event_id = greatest(v_sequence, v_cursor.last_history_event_id), checkpoint_xmax = v_xmax, updated_at = now()
    where source = v_source;
  end if;

  return jsonb_build_object(
    'initialized', false,
    'scanned', v_scanned,
    'emitted', v_emitted,
    'skippedTransactions', v_skipped,
    'cursor', v_cursor.last_history_event_id
  );
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."capture_catalogue_notification_events"(integer, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."capture_catalogue_notification_events"(integer, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/capture_gateway_billing_alert.sql
CREATE OR REPLACE FUNCTION public.capture_gateway_billing_alert()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare alert_uuid uuid;
begin
  if new.billed_at is not null then
    update public.gateway_billing_alerts set status = 'resolved', resolved_at = now()
    where operation_id = new.id and status = 'open';
    return new;
  end if;
  if new.kind not in ('video', 'batch') or new.meta->>'billingReason' is distinct from 'unexpected_zero_cost' then
    return new;
  end if;
  insert into public.gateway_billing_alerts(operation_id, workspace_id, resource_id, kind, provider, reason)
  values(new.id, new.workspace_id, new.internal_id, new.kind, new.provider, 'unexpected_zero_cost')
  on conflict(operation_id, reason) do nothing;
  select id into alert_uuid from public.gateway_billing_alerts
    where operation_id = new.id and reason = 'unexpected_zero_cost';
  perform public.queue_gateway_billing_alert(alert_uuid);
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."capture_gateway_billing_alert"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/capture_manual_workspace_grant.sql
CREATE OR REPLACE FUNCTION public.capture_manual_workspace_grant()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if current_setting('phaseo.entitlement_reconcile', true) = 'on' then
    return coalesce(new, old);
  end if;

  if tg_op = 'DELETE' then
    delete from public.workspace_access_grants
    where workspace_id = old.workspace_id
      and user_id = old.user_id
      and source_type = 'manual';

    perform public.reconcile_scim_entitlements(old.workspace_id);
    return old;
  end if;

  insert into public.workspace_access_grants(
    workspace_id,
    user_id,
    source_type,
    source_id,
    access_role
  )
  values (
    new.workspace_id,
    new.user_id,
    'manual',
    new.user_id,
    lower(new.role::text)
  )
  on conflict (workspace_id, user_id, source_type, source_id)
  do update set
    access_role = excluded.access_role,
    updated_at = now();

  perform public.reconcile_scim_entitlements(new.workspace_id);
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."capture_manual_workspace_grant"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."capture_manual_workspace_grant"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/catalog_model_is_public.sql
CREATE OR REPLACE FUNCTION public.catalog_model_is_public (
  p_model_slug text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from public.v2_models m
    where m.model_slug = p_model_slug and m.hidden = false
      and m.status not in ('disabled', 'not_ready', 'coming_soon', 'testing', 'draft', 'pending')
      and (m.released_at is null or m.released_at <= now())
      and not exists (select 1 from public.v2_model_provider_routes r where r.model_slug = m.model_slug and r.is_stealth)
  );
$function$;

GRANT EXECUTE ON FUNCTION "public"."catalog_model_is_public"(text) TO "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."catalog_model_is_public"(text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."catalog_model_is_public"(text) FROM PUBLIC;

-- source: supabase/schemas/public/functions/charge_slack_agent_month.sql
CREATE OR REPLACE FUNCTION public.charge_slack_agent_month (
  p_installation_id uuid,
  p_period_start    date,
  p_people          integer,
  p_answers         bigint,
  p_amount_nanos    bigint
)
  RETURNS TABLE (
    status               text,
    amount_nanos         bigint,
    before_balance_nanos bigint,
    after_balance_nanos  bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_installation public.slack_installations%rowtype;
  v_charge public.slack_agent_charges%rowtype;
  v_wallet public.wallets%rowtype;
  v_amount bigint;
  v_ref text;
  v_ledger_id uuid;
begin
  if p_period_start is null or p_period_start <> date_trunc('month', p_period_start)::date then
    raise exception 'invalid_period_start' using errcode = '22023';
  end if;
  if p_period_start >= date_trunc('month', now() at time zone 'utc')::date then
    raise exception 'period_not_finished' using errcode = '22023';
  end if;
  if coalesce(p_people, -1) < 0 or coalesce(p_answers, -1) < 0 or coalesce(p_amount_nanos, -1) < 0 then
    raise exception 'invalid_quantity' using errcode = '22023';
  end if;

  select * into v_installation from public.slack_installations where id = p_installation_id;
  if not found then
    raise exception 'installation_not_found' using errcode = 'P0002';
  end if;

  -- The first attempt fixes the month's people, answers and amount, capped at the
  -- spending cap set in Settings. Retries while credits are short charge exactly
  -- that, even if prices, the cap or late usage change afterwards. The row lock
  -- also makes a concurrent run wait here and then see the month charged.
  insert into public.slack_agent_charges as charge
    (installation_id, workspace_id, period_start, people, answers, amount_nanos, attempted_at)
  values (p_installation_id, v_installation.workspace_id, p_period_start, p_people, p_answers,
    least(p_amount_nanos, v_installation.monthly_cap_nanos), now())
  on conflict (installation_id, period_start) do update
  set attempted_at = excluded.attempted_at
  where charge.status = 'pending'
  returning * into v_charge;

  if not found then
    select * into v_charge from public.slack_agent_charges charge
    where charge.installation_id = p_installation_id and charge.period_start = p_period_start;
    return query select 'already_charged'::text, v_charge.amount_nanos, null::bigint, null::bigint;
    return;
  end if;

  v_amount := v_charge.amount_nanos;
  v_ref := p_installation_id::text || ':' || to_char(p_period_start, 'YYYY-MM');

  if v_amount > 0 then
    select * into v_wallet from public.wallets wallet
    where wallet.workspace_id = v_installation.workspace_id
    for update;

    if not found or v_wallet.balance_nanos - v_wallet.reserved_nanos < v_amount then
      update public.slack_installations installation set status = 'payment_due'
      where installation.id = p_installation_id and installation.status = 'active';
      return query select
        (case when v_wallet.workspace_id is null then 'wallet_not_found' else 'insufficient_balance' end)::text,
        v_amount, v_wallet.balance_nanos, v_wallet.balance_nanos;
      return;
    end if;

    insert into public.credit_ledger (
      workspace_id, kind, amount_nanos, before_balance_nanos, after_balance_nanos,
      ref_type, ref_id, source_ref_type, source_ref_id, status
    ) values (
      v_installation.workspace_id, 'charge', -v_amount, v_wallet.balance_nanos, v_wallet.balance_nanos - v_amount,
      'slack_agent_month', v_ref, 'slack_installation', p_installation_id::text, 'captured'
    )
    on conflict (ref_type, ref_id) do nothing
    returning id into v_ledger_id;

    -- A ledger row without a charged month can only come from a manual repair; never debit twice.
    if v_ledger_id is not null then
      update public.wallets wallet
      set balance_nanos = wallet.balance_nanos - v_amount, updated_at = now()
      where wallet.workspace_id = v_installation.workspace_id;
    end if;
  end if;

  update public.slack_agent_charges charge
  set status = 'charged', charged_at = now(), ledger_ref_id = case when v_amount > 0 then v_ref end
  where charge.installation_id = p_installation_id and charge.period_start = p_period_start;

  update public.slack_installations installation set status = 'active'
  where installation.id = p_installation_id and installation.status = 'payment_due'
    and not exists (
      select 1 from public.slack_agent_charges charge
      where charge.installation_id = p_installation_id and charge.status = 'pending'
    );

  return query select
    (case when v_amount > 0 and v_ledger_id is null then 'already_charged' else 'charged' end)::text,
    v_amount,
    case when v_amount > 0 then v_wallet.balance_nanos end,
    case when v_amount > 0 then v_wallet.balance_nanos - (case when v_ledger_id is null then 0 else v_amount end) end;
end;
$function$;

COMMENT ON FUNCTION "public"."charge_slack_agent_month"(uuid, date, integer, bigint, bigint) IS 'Takes one installation''s charge for a finished UTC month from credits, capped at its monthly spending cap and fixed at the first attempt, as a single credit_ledger charge (ref_type slack_agent_month, idempotent per installation and month). If the available balance is too low the month stays pending, the installation is marked payment_due, and the next call retries.';

GRANT EXECUTE ON FUNCTION "public"."charge_slack_agent_month"(uuid, date, integer, bigint, bigint) TO "service_role";

REVOKE ALL ON FUNCTION "public"."charge_slack_agent_month"(uuid, date, integer, bigint, bigint) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_gateway_async_operations_for_reconciliation.sql
CREATE OR REPLACE FUNCTION public.claim_gateway_async_operations_for_reconciliation (
  p_kind          text,
  p_limit         integer DEFAULT 100,
  p_statuses      text[]  DEFAULT NULL::text[],
  p_worker_id     text    DEFAULT 'gateway-reconciler'::text,
  p_lease_seconds integer DEFAULT 120,
  p_shard_count   integer DEFAULT 1,
  p_shard_index   integer DEFAULT 0
)
  RETURNS TABLE (
    workspace_id         uuid,
    kind                 text,
    internal_id          text,
    request_id           text,
    session_id           text,
    app_id               uuid,
    provider             text,
    native_id            text,
    model                text,
    status               text,
    meta                 jsonb,
    billed_at            timestamp with time zone,
    next_reconcile_at    timestamp with time zone,
    reconcile_attempts   integer,
    reconcile_locked_at  timestamp with time zone,
    reconcile_locked_by  text,
    last_reconcile_error text,
    created_at           timestamp with time zone,
    updated_at           timestamp with time zone
  )
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 2000));
  v_lease_seconds integer := greatest(30, least(coalesce(p_lease_seconds, 120), 3600));
  v_shard_count integer := greatest(1, least(coalesce(p_shard_count, 1), 256));
  v_shard_index integer := greatest(0, least(coalesce(p_shard_index, 0), greatest(1, least(coalesce(p_shard_count, 1), 256)) - 1));
  v_worker_id text := left(coalesce(nullif(trim(p_worker_id), ''), 'gateway-reconciler'), 200);
begin
  return query
  with candidates as (
    select op.id
    from public.gateway_async_operations op
    where op.kind = p_kind
      and op.billed_at is null
      and (op.next_reconcile_at is null or op.next_reconcile_at <= now())
      and (
        op.reconcile_locked_at is null
        or op.reconcile_locked_at < now() - make_interval(secs => v_lease_seconds)
      )
      and (
        p_statuses is null
        or coalesce(op.status, '') = any(p_statuses)
      )
      and not (op.kind = 'batch' and op.meta->>'resource' = 'file')
      and (
        v_shard_count = 1
        or mod(
          mod(hashtextextended(op.workspace_id::text || ':' || op.internal_id, 0), v_shard_count::bigint)
            + v_shard_count::bigint,
          v_shard_count::bigint
        ) = v_shard_index::bigint
      )
    order by op.next_reconcile_at asc nulls first, op.updated_at asc
    limit v_limit
    for update skip locked
  ),
  claimed as (
    update public.gateway_async_operations op
    set
      reconcile_locked_at = now(),
      reconcile_locked_by = v_worker_id,
      reconcile_attempts = op.reconcile_attempts + 1,
      updated_at = now()
    from candidates
    where op.id = candidates.id
    returning op.*
  )
  select
    claimed.workspace_id,
    claimed.kind,
    claimed.internal_id,
    claimed.request_id,
    claimed.session_id,
    claimed.app_id,
    claimed.provider,
    claimed.native_id,
    claimed.model,
    claimed.status,
    claimed.meta,
    claimed.billed_at,
    claimed.next_reconcile_at,
    claimed.reconcile_attempts,
    claimed.reconcile_locked_at,
    claimed.reconcile_locked_by,
    claimed.last_reconcile_error,
    claimed.created_at,
    claimed.updated_at
  from claimed
  order by claimed.next_reconcile_at asc nulls first, claimed.updated_at asc;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_gateway_async_operations_for_reconciliation"(text, integer, text[], text, integer, integer, integer) TO "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."claim_gateway_async_operations_for_reconciliation"(text, integer, text[], text, integer, integer, integer) TO "service_role";

COMMENT ON FUNCTION "public"."claim_gateway_async_operations_for_reconciliation"(text, integer, text[], text, integer, integer, integer) IS 'Atomically claims due, unbilled async operations for reconciliation using a short service-role lease and FOR UPDATE SKIP LOCKED.';

REVOKE ALL ON FUNCTION "public"."claim_gateway_async_operations_for_reconciliation"(text, integer, text[], text, integer, integer, integer) FROM PUBLIC;

-- source: supabase/schemas/public/functions/claim_gateway_async_webhook_delivery.sql
CREATE OR REPLACE FUNCTION public.claim_gateway_async_webhook_delivery (
  p_workspace_id        uuid,
  p_kind                text,
  p_internal_id         text,
  p_delivery_key        text,
  p_claim_token         text,
  p_stale_after_seconds integer          DEFAULT 300,
  p_event_type          text             DEFAULT NULL::text,
  p_phase               text             DEFAULT NULL::text,
  p_progress            double precision DEFAULT NULL::double precision,
  p_previous_status     text             DEFAULT NULL::text,
  p_current_status      text             DEFAULT NULL::text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_row public.gateway_async_webhook_deliveries%rowtype;
begin
  if p_workspace_id is null or coalesce(trim(p_kind), '') = ''
     or coalesce(trim(p_internal_id), '') = '' or coalesce(trim(p_delivery_key), '') = ''
     or coalesce(trim(p_claim_token), '') = '' then
    raise exception 'invalid_webhook_delivery_claim';
  end if;

  insert into public.gateway_async_webhook_deliveries (
    workspace_id, kind, internal_id, delivery_key, status, claim_token, claimed_at, updated_at
  ) values (
    p_workspace_id, p_kind, p_internal_id, p_delivery_key, 'claimed', p_claim_token, now(), now()
  ) on conflict do nothing;

  select * into v_row
  from public.gateway_async_webhook_deliveries
  where workspace_id = p_workspace_id and kind = p_kind
    and internal_id = p_internal_id and delivery_key = p_delivery_key
  for update;

  if v_row.status in ('delivered', 'failed') then return false; end if;
  if v_row.status = 'pending' and v_row.next_attempt_at > now() then return false; end if;
  if v_row.status = 'claimed' and v_row.claim_token <> p_claim_token
     and v_row.claimed_at > now() - make_interval(secs => greatest(30, p_stale_after_seconds)) then
    return false;
  end if;

  update public.gateway_async_webhook_deliveries
  set status = 'claimed', claim_token = p_claim_token, claimed_at = now(), updated_at = now(),
      event_type = coalesce(event_type, p_event_type, split_part(p_delivery_key, ':', 1)),
      phase = coalesce(phase, p_phase, split_part(split_part(p_delivery_key, ':', 1), '.', 2)),
      progress = coalesce(progress, p_progress),
      previous_status = coalesce(previous_status, p_previous_status),
      current_status = coalesce(current_status, p_current_status)
  where workspace_id = p_workspace_id and kind = p_kind
    and internal_id = p_internal_id and delivery_key = p_delivery_key;
  return true;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_gateway_async_webhook_delivery"(uuid, text, text, text, text, integer, text, text, double precision, text, text) TO "service_role";

REVOKE ALL
  ON FUNCTION "public"."claim_gateway_async_webhook_delivery"(uuid, text, text, text, text, integer, text, text, double precision, text, text)
  FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_mobile_push_deliveries.sql
CREATE OR REPLACE FUNCTION public.claim_mobile_push_deliveries (
  p_limit       integer,
  p_claim_token uuid
)
  RETURNS TABLE (
    id              uuid,
    attempts        integer,
    expo_push_token text,
    channel_scheme  smallint,
    kind            text,
    category        text,
    model_slug      text,
    title           text,
    body            text,
    href            text,
    group_key       text,
    group_count     integer,
    tag             text,
    deliveries      integer,
    workspace_id    uuid,
    workspace_name  text
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Claims up to p_limit due pushes under the caller's token, skipping rows another run holds.
-- A device's rows that share a group key go out as one push, once at least one is due and none
-- is still settling (due within the next five minutes), or once the oldest has been due for ten
-- minutes; rows waiting for quiet hours to end, or for a later retry, stay behind. A grouped push
-- also counts what the device was sent for that group since midnight UTC, and its tag (the group
-- key and the UTC date) makes it replace that earlier notification. Each push is returned under
-- its oldest row's id; the other rows point at it through merged_into. Workspace alerts carry
-- their own message and workspace, have no group key, and so always go alone.
-- Before claiming, rows over two days old, for a device that is no longer active, for a user who
-- has since switched push or the push's category off, or for a workspace the user has left are
-- closed instead of sent, and rows a crashed run left processing for ten minutes go back to the
-- queue to be grouped again.
-- Claims run one at a time: a call that finds another claim in progress returns nothing, and
-- the next run picks the work up. Otherwise two overlapping calls could each lock part of the
-- same group and send it as two pushes. The lock ends with the transaction; claimed rows are
-- processing by then, so a later claim cannot take them.
-- Weekly digest rows (digest_id) are never read here, so a backlog of them cannot use up
-- p_limit; claim_mobile_push_digests claims, closes and requeues them.
#variable_conflict use_column
declare
  v_day_start timestamp with time zone := date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
begin
  if p_limit is null or p_limit < 1 or p_limit > 500 then
    raise exception 'invalid_mobile_push_claim_limit';
  end if;
  if p_claim_token is null then
    raise exception 'invalid_mobile_push_claim_token';
  end if;
  if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('claim_mobile_push_deliveries', 0)) then
    return;
  end if;

  update public.mobile_push_deliveries x
  set status = case when x.created_at <= now() - interval '2 days' then 'failed' else 'suppressed' end,
      error_code = case
        when x.created_at <= now() - interval '2 days' then 'expired'
        when dev.status <> 'active' then 'device_inactive'
        when not coalesce(p.enabled, false) then 'notifications_disabled'
        when x.workspace_id is not null and not exists (
          select 1 from public.workspace_members m where m.workspace_id = x.workspace_id and m.user_id = x.user_id
        ) then 'not_a_member'
        else 'category_disabled'
      end,
      merged_into = null,
      claim_token = null,
      claimed_at = null,
      updated_at = now()
  from public.mobile_push_devices dev
  left join public.mobile_notification_preferences p on p.user_id = dev.user_id
  where dev.id = x.device_id
    and x.digest_id is null
    and (x.status in ('pending', 'deferred') or (x.status = 'processing' and x.claimed_at < now() - interval '10 minutes'))
    and (
      x.created_at <= now() - interval '2 days' or dev.status <> 'active' or not coalesce(p.enabled, false)
      or (p.categories -> coalesce(x.message ->> 'category',
        (select private.mobile_push_category(e.kind) from public.catalogue_notification_events e where e.id = x.event_id))) = 'false'::jsonb
      or (x.workspace_id is not null and not exists (
        select 1 from public.workspace_members m where m.workspace_id = x.workspace_id and m.user_id = x.user_id
      ))
    );

  update public.mobile_push_deliveries x
  set status = 'pending', merged_into = null, claim_token = null, claimed_at = null, updated_at = now()
  where x.status = 'processing' and x.claimed_at < now() - interval '10 minutes' and x.digest_id is null;

  return query
  with due as (
    select w.device_id, coalesce(w.group_key, w.id::text) as unit
    from public.mobile_push_deliveries w
    where w.status in ('pending', 'deferred') and w.digest_id is null
    group by w.device_id, coalesce(w.group_key, w.id::text)
    having min(w.not_before) <= now()
      and (
        not bool_or(w.not_before > now() and w.not_before <= now() + interval '5 minutes')
        or min(w.not_before) <= now() - interval '10 minutes'
      )
    order by min(w.not_before), min(w.created_at)
    limit p_limit
  ),
  locked as (
    select x.id, x.device_id, x.group_key, x.event_id, x.created_at, x.attempts, x.message, x.workspace_id, d.unit
    from public.mobile_push_deliveries x
    join due d on d.device_id = x.device_id and d.unit = coalesce(x.group_key, x.id::text)
    where x.status in ('pending', 'deferred') and x.not_before <= now() and x.digest_id is null
    for update of x skip locked
  ),
  members as (
    select
      l.*,
      coalesce(e.occurred_at, l.created_at) as occurred_at,
      first_value(l.id) over (partition by l.device_id, l.unit order by l.created_at, l.id) as lead_id,
      count(*) over (partition by l.device_id, l.unit) as member_count,
      max(l.attempts) over (partition by l.device_id, l.unit) as max_attempts,
      case when e.id is null then l.message else jsonb_build_object(
        'kind', e.kind, 'modelSlug', e.model_slug, 'labSlug', e.lab_slug, 'providerSlug', e.provider_slug,
        'modelName', coalesce(nullif(btrim(e.payload ->> 'modelName'), ''), e.model_slug),
        'labName', coalesce(nullif(btrim(e.payload ->> 'labName'), ''), e.lab_slug),
        'providerName', coalesce(nullif(btrim(e.payload ->> 'providerName'), ''), e.provider_slug),
        'title', e.title, 'body', e.body, 'href', e.href
      ) end as item
    from locked l
    left join public.catalogue_notification_events e on e.id = l.event_id
  ),
  sent_today as (
    select g.device_id, g.unit, e.occurred_at, x.created_at, x.id,
      jsonb_build_object(
        'kind', e.kind, 'modelSlug', e.model_slug, 'labSlug', e.lab_slug, 'providerSlug', e.provider_slug,
        'modelName', coalesce(nullif(btrim(e.payload ->> 'modelName'), ''), e.model_slug),
        'labName', coalesce(nullif(btrim(e.payload ->> 'labName'), ''), e.lab_slug),
        'providerName', coalesce(nullif(btrim(e.payload ->> 'providerName'), ''), e.provider_slug),
        'title', e.title, 'body', e.body, 'href', e.href
      ) as item
    from (select distinct m.device_id, m.unit, m.group_key from members m where m.group_key is not null) g
    join public.mobile_push_deliveries x
      on x.device_id = g.device_id and x.group_key = g.group_key and x.status = 'sent'
      and x.sent_at >= v_day_start and x.created_at > now() - interval '2 days'
    join public.catalogue_notification_events e on e.id = x.event_id
  ),
  composed as (
    -- What the device was already shown comes first, then what is new, each oldest first.
    select
      i.device_id,
      i.unit,
      private.mobile_push_group_message(max(i.group_key), jsonb_agg(i.item order by i.is_new, i.occurred_at, i.created_at, i.id)) as message
    from (
      select m.device_id, m.unit, m.group_key, true as is_new, m.occurred_at, m.created_at, m.id, m.item from members m
      union all
      select s.device_id, s.unit, s.unit, false, s.occurred_at, s.created_at, s.id, s.item from sent_today s
    ) i
    group by i.device_id, i.unit
  ),
  claimed as (
    update public.mobile_push_deliveries x
    set status = 'processing',
        claim_token = p_claim_token,
        claimed_at = now(),
        attempts = x.attempts + 1,
        merged_into = nullif(m.lead_id, x.id),
        updated_at = now()
    from members m
    where x.id = m.id
    returning x.id
  )
  select
    m.id,
    (m.max_attempts + 1)::integer,
    dev.expo_push_token,
    dev.channel_scheme,
    c.message ->> 'kind',
    coalesce(m.item ->> 'category', private.mobile_push_category(c.message ->> 'kind')),
    c.message ->> 'modelSlug',
    c.message ->> 'title',
    c.message ->> 'body',
    c.message ->> 'href',
    m.group_key,
    case when m.group_key is not null then (c.message ->> 'count')::integer end,
    case when m.group_key is not null then m.group_key || ':' || to_char(now() at time zone 'UTC', 'YYYY-MM-DD') end,
    m.member_count::integer,
    m.workspace_id,
    ws.name
  from members m
  join composed c on c.device_id = m.device_id and c.unit = m.unit
  join public.mobile_push_devices dev on dev.id = m.device_id
  left join public.workspaces ws on ws.id = m.workspace_id
  where m.id = m.lead_id
  order by m.id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_mobile_push_deliveries"(integer, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."claim_mobile_push_deliveries"(integer, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_mobile_push_digests.sql
CREATE OR REPLACE FUNCTION public.claim_mobile_push_digests (
  p_limit       integer,
  p_claim_token uuid,
  p_now         timestamp with time zone DEFAULT now()
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- The weekly digest's half of the push job. Writes the digests that have come due
-- (private.build_mobile_push_digests, for up to 20 users a call, since each sums every workspace
-- the user administers; more says others are waiting), then claims up to p_limit due digest
-- pushes under the caller's token and returns them with their text:
-- { built, skipped, queued, deferred, more, closed, pushes: [{ id, attempts, expoPushToken,
-- channelScheme, title, body, href, tag, isoWeek, workspaceId, workspaceName }] }.
-- Results go to complete_mobile_push_deliveries like any other push. Before claiming, rows a
-- crashed run left processing for ten minutes become claimable again, and rows over two days
-- old, for a device that is no longer active or has gone back to an app build without the digest
-- channel (channel scheme below 2), or for a user who has since switched push or the digest off
-- are closed instead of sent; a device that changes in the meantime is skipped until the next
-- run closes its row. Digest rows are never grouped, never count against the daily cap, and are
-- never read by claim_mobile_push_deliveries. When idle, each step reads an empty partial index.
-- A backlog larger than one run sends is left pending, oldest first, for the next run.
declare
  v_built jsonb;
  v_closed integer;
  v_pushes jsonb;
begin
  if p_limit is null or p_limit < 1 or p_limit > 500 then
    raise exception 'invalid_mobile_push_claim_limit';
  end if;
  if p_claim_token is null then
    raise exception 'invalid_mobile_push_claim_token';
  end if;
  if p_now is null then
    raise exception 'invalid_mobile_push_claim_time';
  end if;

  v_built := private.build_mobile_push_digests(p_now, least(p_limit, 20));

  update public.mobile_push_deliveries x
  set status = 'pending', claim_token = null, claimed_at = null, updated_at = now()
  where x.status = 'processing' and x.claimed_at < p_now - interval '10 minutes' and x.digest_id is not null;

  with closed as (
    update public.mobile_push_deliveries x
    set status = case when x.created_at <= p_now - interval '2 days' then 'failed' else 'suppressed' end,
        error_code = case
          when x.created_at <= p_now - interval '2 days' then 'expired'
          when dev.status <> 'active' then 'device_inactive'
          when dev.channel_scheme < 2 then 'channel_scheme_unsupported'
          when not coalesce(p.enabled, false) then 'notifications_disabled'
          else 'category_disabled'
        end,
        updated_at = now()
    from public.mobile_push_devices dev
    left join public.mobile_notification_preferences p on p.user_id = dev.user_id
    where dev.id = x.device_id
      and x.digest_id is not null
      and x.status in ('pending', 'deferred')
      and (
        x.created_at <= p_now - interval '2 days' or dev.status <> 'active' or dev.channel_scheme < 2
        or not coalesce(p.enabled, false) or (p.categories -> 'digest') = 'false'::jsonb
      )
    returning x.id
  )
  select count(*) into v_closed from closed;

  with due as (
    select x.id
    from public.mobile_push_deliveries x
    join public.mobile_push_devices dev on dev.id = x.device_id and dev.status = 'active' and dev.channel_scheme >= 2
    where x.digest_id is not null and x.status in ('pending', 'deferred') and x.not_before <= p_now
    order by x.not_before, x.created_at, x.id
    limit p_limit
    for update of x skip locked
  ),
  claimed as (
    update public.mobile_push_deliveries x
    set status = 'processing', claim_token = p_claim_token, claimed_at = p_now, attempts = x.attempts + 1, updated_at = now()
    from due
    where x.id = due.id
    returning x.id, x.attempts, x.device_id, x.digest_id, x.workspace_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', c.id,
    'attempts', c.attempts,
    'expoPushToken', dev.expo_push_token,
    'channelScheme', dev.channel_scheme,
    'title', g.title,
    'body', g.body,
    'href', g.href,
    'tag', 'digest:' || g.iso_week,
    'isoWeek', g.iso_week,
    'workspaceId', c.workspace_id,
    'workspaceName', w.name
  ) order by c.id), '[]'::jsonb)
  into v_pushes
  from claimed c
  join public.mobile_push_devices dev on dev.id = c.device_id
  join public.mobile_push_digests g on g.id = c.digest_id
  left join public.workspaces w on w.id = c.workspace_id;

  return v_built || jsonb_build_object('closed', v_closed, 'pushes', v_pushes);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_mobile_push_digests"(integer, uuid, timestamp with time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."claim_mobile_push_digests"(integer, uuid, timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_mobile_push_receipts.sql
CREATE OR REPLACE FUNCTION public.claim_mobile_push_receipts (
  p_limit integer
)
  RETURNS TABLE (
    id             uuid,
    expo_ticket_id text
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Hands out Expo tickets whose receipts should be ready (sent 15 minutes to a day ago) under
-- a claim that lapses after 15 minutes. Only record_mobile_push_receipts closes a ticket, for
-- the receipts Expo returned, so a failed request or a receipt that is not ready yet is
-- asked for again on a later run. Expo keeps receipts for a day; tickets still unchecked
-- after that are closed without a check.
#variable_conflict use_column
begin
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception 'invalid_mobile_push_receipt_limit';
  end if;

  update public.mobile_push_deliveries x
  set receipt_checked_at = now(), updated_at = now()
  where x.status = 'sent' and x.expo_ticket_id is not null and x.receipt_checked_at is null
    and x.sent_at <= now() - interval '1 day';

  return query
  with due as (
    select x.id
    from public.mobile_push_deliveries x
    where x.status = 'sent' and x.expo_ticket_id is not null and x.receipt_checked_at is null
      and x.sent_at <= now() - interval '15 minutes'
      and (x.receipt_claimed_at is null or x.receipt_claimed_at <= now() - interval '15 minutes')
    order by x.sent_at, x.id
    for update skip locked
    limit p_limit
  )
  update public.mobile_push_deliveries x
  set receipt_claimed_at = now(), updated_at = now()
  from due
  where x.id = due.id
  returning x.id, x.expo_ticket_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_mobile_push_receipts"(integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."claim_mobile_push_receipts"(integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_mobile_push_test.sql
CREATE OR REPLACE FUNCTION public.claim_mobile_push_test (
  p_user_id         uuid,
  p_installation_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Allows three test pushes per user in any ten minutes. Returns the device's token and channel
-- scheme, or {"error": "device_not_registered" | "rate_limited", "retryAfterSeconds"}.
declare
  v_recent timestamp with time zone[];
  v_device_id uuid;
  v_token text;
  v_channel_scheme smallint;
begin
  if p_user_id is null or p_installation_id is null then
    return jsonb_build_object('error', 'device_not_registered');
  end if;

  select d.id, d.expo_push_token, d.channel_scheme into v_device_id, v_token, v_channel_scheme
  from public.mobile_push_devices d
  where d.user_id = p_user_id and d.installation_id = p_installation_id and d.status = 'active';
  if v_device_id is null then
    return jsonb_build_object('error', 'device_not_registered');
  end if;

  insert into public.mobile_notification_preferences (user_id) values (p_user_id) on conflict (user_id) do nothing;
  select array(
    select t from unnest(p.test_push_sent_at) as t where t > now() - interval '10 minutes' order by t
  ) into v_recent
  from public.mobile_notification_preferences p
  where p.user_id = p_user_id
  for update;

  if cardinality(v_recent) >= 3 then
    return jsonb_build_object(
      'error', 'rate_limited',
      'retryAfterSeconds', greatest(1, ceil(extract(epoch from (v_recent[1] + interval '10 minutes' - now()))))::integer
    );
  end if;

  update public.mobile_notification_preferences
  set test_push_sent_at = v_recent || now(), updated_at = now()
  where user_id = p_user_id;

  return jsonb_build_object('deviceId', v_device_id, 'expoPushToken', v_token, 'channelScheme', v_channel_scheme);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_mobile_push_test"(uuid, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."claim_mobile_push_test"(uuid, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_model_discovery_public_announcements.sql
CREATE OR REPLACE FUNCTION public.claim_model_discovery_public_announcements (
  p_run_id        uuid,
  p_model_slugs   text[],
  p_now           timestamp with time zone,
  p_lease_seconds integer                  DEFAULT 300
)
  RETURNS TABLE (
    model_slug    text,
    attempt_count integer
  )
  LANGUAGE sql
  SET search_path TO 'public'
  AS $function$
  update public.model_discovery_public_announcements
  set
    claim_run_id = p_run_id,
    claim_expires_at = coalesce(p_now, now()) + make_interval(secs => greatest(coalesce(p_lease_seconds, 300), 1)),
    last_run_id = p_run_id,
    updated_at = coalesce(p_now, now())
  where model_slug = any(coalesce(p_model_slugs, array[]::text[]))
    and status = 'pending'
    and (
      claim_run_id is null
      or claim_expires_at <= coalesce(p_now, now())
      or claim_run_id = p_run_id
    )
  returning model_slug, attempt_count;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_model_discovery_public_announcements"(uuid, text[], timestamp WITH time zone, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."claim_model_discovery_public_announcements"(uuid, text[], timestamp WITH time zone, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_notification_delivery_attempts.sql
CREATE OR REPLACE FUNCTION public.claim_notification_delivery_attempts (
  p_limit integer DEFAULT 25
)
  RETURNS TABLE (
    id             uuid,
    event_id       uuid,
    destination_id uuid,
    attempts       integer,
    claim_token    uuid
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  if p_limit is null or p_limit < 1 or p_limit > 100 then
    raise exception 'invalid_notification_delivery_claim_limit';
  end if;

  return query
  with candidates as (
    select attempt.id
    from public.notification_delivery_attempts attempt
    where (
      attempt.status in ('pending', 'retry')
      and attempt.next_attempt_at <= now()
    ) or (
      attempt.status = 'processing'
      and attempt.claimed_at < now() - interval '5 minutes'
    )
    order by attempt.created_at, attempt.id
    for update skip locked
    limit p_limit
  )
  update public.notification_delivery_attempts attempt
  set status = 'processing',
      claim_token = gen_random_uuid(),
      claimed_at = now(),
      updated_at = now()
  from candidates
  where attempt.id = candidates.id
  returning attempt.id, attempt.event_id, attempt.destination_id, attempt.attempts, attempt.claim_token;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_notification_delivery_attempts"(integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."claim_notification_delivery_attempts"(integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_payment_method_mutation.sql
CREATE OR REPLACE FUNCTION public.claim_payment_method_mutation (
  p_workspace_id uuid,
  p_claim_token  uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  claimed uuid;
begin
  insert into public.payment_method_mutation_leases (workspace_id, claim_token, expires_at, updated_at)
  values (p_workspace_id, p_claim_token, now() + interval '10 minutes', now())
  on conflict (workspace_id) do update
    set claim_token = excluded.claim_token,
        expires_at = excluded.expires_at,
        updated_at = now()
    where public.payment_method_mutation_leases.expires_at <= now()
  returning claim_token into claimed;
  return claimed = p_claim_token;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_payment_method_mutation"(uuid, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."claim_payment_method_mutation"(uuid, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_provider_catalog_sync.sql
CREATE OR REPLACE FUNCTION public.claim_provider_catalog_sync (
  p_provider_slug text,
  p_lease_token   uuid,
  p_lease_seconds integer DEFAULT 120
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  affected integer;
begin
  update public.provider_catalog_sources
  set sync_lease_token = p_lease_token,
      sync_lease_expires_at = now() + make_interval(secs => greatest(30, least(p_lease_seconds, 300))),
      updated_at = now()
  where provider_slug = p_provider_slug
    and status = 'active'
    and (sync_lease_expires_at is null or sync_lease_expires_at <= now());
  get diagnostics affected = row_count;
  return affected > 0;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_provider_catalog_sync"(text, uuid, integer) TO "service_role";

