-- source: supabase/schemas/public/functions/claim_slack_agent_schedules.sql
CREATE OR REPLACE FUNCTION public.claim_slack_agent_schedules (
  p_limit integer
)
  RETURNS TABLE (
    schedule_id     uuid,
    installation_id uuid,
    channel_id      text,
    title           text,
    prompt          text,
    created_by      text,
    frequency       text,
    hour            smallint,
    minute          smallint,
    day_of_week     smallint,
    day_of_month    smallint,
    timezone        text,
    run_at          timestamp with time zone
  )
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- The Slack Worker's cron trigger calls this every minute: it claims the active
  -- schedules that are due, oldest first, at most p_limit (1 to 200, default 50),
  -- through the partial index on next_run_at. A claimed row's last_run_at becomes
  -- the time this run was due and last_claimed_at the time it was claimed, and
  -- its next_run_at moves on to its next local time at least 50 minutes after the
  -- claim, so no schedule runs more than once an hour, even when a run is claimed
  -- late. Rows another claim holds are skipped, so a run is claimed once,
  -- whichever tick gets there first; run_at keys the run for the Worker's retries.
  -- While a schedule's installation isn't active (paused by an admin, or a charge
  -- unpaid) its runs are skipped with that reason, and so are all runs while
  -- admins have turned recurring tasks off. A skipped run isn't returned; the
  -- schedule stays active with its failures in a row as they were, and runs again
  -- at its next time once the agent is back on. Uninstalling deletes an
  -- installation's schedules (delete_slack_agent_schedules).
  -- Service role only.
  with due as (
    select schedule.id
    from public.slack_agent_schedules schedule
    where schedule.status = 'active' and schedule.next_run_at <= now()
    order by schedule.next_run_at
    limit least(greatest(coalesce(p_limit, 50), 1), 200)
    for update skip locked
  ), claimed as (
    update public.slack_agent_schedules schedule
    set last_run_at = schedule.next_run_at,
        last_claimed_at = now(),
        next_run_at = public.slack_agent_schedule_next_run(
          schedule.frequency, schedule.hour, schedule.minute, schedule.day_of_week, schedule.day_of_month, schedule.timezone,
          now() + interval '50 minutes'
        ),
        last_result = case when installation.status <> 'active' or not installation.schedules_enabled then 'skipped' end,
        last_result_reason = case
          when installation.status = 'payment_due' then 'payment_due'
          when installation.status <> 'active' then 'installation_paused'
          when not installation.schedules_enabled then 'schedules_off'
        end
    from due, public.slack_installations installation
    where schedule.id = due.id and installation.id = schedule.installation_id
    returning schedule.id, schedule.installation_id, schedule.channel_id, schedule.title, schedule.prompt, schedule.created_by,
      schedule.frequency, schedule.hour, schedule.minute, schedule.day_of_week, schedule.day_of_month, schedule.timezone,
      schedule.last_run_at, schedule.last_result
  )
  select claimed.id, claimed.installation_id, claimed.channel_id, claimed.title, claimed.prompt, claimed.created_by,
    claimed.frequency, claimed.hour, claimed.minute, claimed.day_of_week, claimed.day_of_month, claimed.timezone, claimed.last_run_at
  from claimed
  where claimed.last_result is null
  order by claimed.last_run_at;
$function$;

COMMENT ON FUNCTION "public"."claim_slack_agent_schedules"(integer) IS 'For the Slack Worker''s cron trigger: claims due schedules once (FOR UPDATE SKIP LOCKED), moves each to its next local time at least 50 minutes after the claim, skips (without pausing them) those of installations that aren''t active and all of them while recurring tasks are off, and returns the runs to start.';

GRANT EXECUTE ON FUNCTION "public"."claim_slack_agent_schedules"(integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."claim_slack_agent_schedules"(integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_workspace_top_up_fee_policy.sql
CREATE OR REPLACE FUNCTION public.claim_workspace_top_up_fee_policy (
  p_workspace_id             uuid,
  p_stripe_payment_intent_id text,
  p_gross_nanos              bigint,
  p_payment_rail             text,
  p_seen_at                  timestamp with time zone DEFAULT now()
)
  RETURNS TABLE (
    fee_waived             boolean,
    reason                 text,
    allowance_before_nanos bigint,
    allowance_after_nanos  bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_period_start date := date_trunc('month', p_seen_at at time zone 'UTC')::date;
  v_subscription public.workspace_addon_subscriptions%rowtype;
  v_used bigint := 0;
  v_waived boolean := false;
  v_reason text := 'standard_fee';
  v_before bigint := 0;
  v_after bigint := 0;
begin
  if p_gross_nanos < 0 or p_stripe_payment_intent_id is null or trim(p_stripe_payment_intent_id) = '' then
    raise exception 'invalid top-up fee claim';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_workspace_id::text || ':' || v_period_start::text || ':top_up_fee', 0)
  );

  return query
  select d.fee_waived, d.reason, d.allowance_before_nanos, d.allowance_after_nanos
  from public.workspace_top_up_fee_decisions d
  where d.stripe_payment_intent_id = p_stripe_payment_intent_id;
  if found then return; end if;

  select * into v_subscription
  from public.workspace_addon_subscriptions s
  where s.workspace_id = p_workspace_id
    and s.addon_key = 'identity'
    and (
      s.status in ('active', 'trialing')
      or (s.status = 'past_due' and s.grace_until > p_seen_at)
    )
  limit 1;

  if v_subscription.id is not null and v_subscription.fee_policy = 'included_allowance' then
    select coalesce(sum(d.gross_nanos), 0) into v_used
    from public.workspace_top_up_fee_decisions d
    where d.workspace_id = p_workspace_id
      and d.period_start = v_period_start
      and d.fee_waived
      and d.payment_rail <> 'bank_transfer';
    v_before := greatest(v_subscription.included_card_top_up_nanos - v_used, 0);

    if p_payment_rail = 'bank_transfer' then
      v_waived := true;
      v_reason := 'included_bank_transfer';
      v_after := v_before;
    elsif p_gross_nanos <= v_before then
      v_waived := true;
      v_reason := 'included_card_allowance';
      v_after := v_before - p_gross_nanos;
    else
      v_reason := 'allowance_exceeded';
      v_after := v_before;
    end if;
  elsif v_subscription.id is null then
    v_reason := 'no_active_subscription';
  end if;

  insert into public.workspace_top_up_fee_decisions (
    stripe_payment_intent_id, workspace_id, period_start, payment_rail,
    gross_nanos, fee_waived, allowance_before_nanos, allowance_after_nanos, reason
  ) values (
    p_stripe_payment_intent_id, p_workspace_id, v_period_start,
    case when p_payment_rail in ('card', 'ach', 'bank_transfer') then p_payment_rail else 'unknown' end,
    p_gross_nanos, v_waived, v_before, v_after, v_reason
  );

  return query select v_waived, v_reason, v_before, v_after;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_workspace_top_up_fee_policy"(uuid, text, bigint, text, timestamp WITH time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."claim_workspace_top_up_fee_policy"(uuid, text, bigint, text, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

