-- source: supabase/schemas/public/functions/complete_mobile_push_deliveries.sql
CREATE OR REPLACE FUNCTION public.complete_mobile_push_deliveries (
  p_claim_token uuid,
  p_results     jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Records one batch of Expo results: [{ "id", "status": "sent" | "failed" | "retry",
-- "ticketId", "errorCode", "errorMessage" }], one per push under the id the claim returned.
-- A result applies to every row the push carried (merged_into); the ticket is kept on the
-- push's own row. Only rows still held by this claim change. Retries back off from 30 seconds
-- to an hour and give up after five attempts; a retried row is grouped again when it is next
-- due. DeviceNotRegistered retires the device. Counts are per push.
declare
  v_result jsonb;
begin
  if p_claim_token is null or jsonb_typeof(p_results) is distinct from 'array' then
    raise exception 'invalid_mobile_push_results';
  end if;

  with results as (
    select distinct on (r.id)
      r.id,
      r.status,
      left(r."ticketId", 200) as ticket_id,
      left(r."errorCode", 100) as error_code,
      left(r."errorMessage", 1000) as error_message
    from jsonb_to_recordset(p_results) as r(id uuid, status text, "ticketId" text, "errorCode" text, "errorMessage" text)
    where r.id is not null and r.status in ('sent', 'failed', 'retry')
    order by r.id
  ),
  completed as (
    update public.mobile_push_deliveries x
    set status = case when r.status = 'sent' then 'sent' when r.status = 'retry' and x.attempts < 5 then 'pending' else 'failed' end,
        not_before = case
          when r.status = 'retry' and x.attempts < 5 then now() + make_interval(secs => least(3600, 30 * power(2, x.attempts)))
          else x.not_before
        end,
        expo_ticket_id = case when r.status = 'sent' and x.id = r.id then r.ticket_id end,
        sent_at = case when r.status = 'sent' then now() end,
        error_code = case when r.status = 'sent' then null else coalesce(r.error_code, 'push_failed') end,
        error_message = case when r.status = 'sent' then null else r.error_message end,
        merged_into = case when r.status = 'retry' and x.attempts < 5 then null else x.merged_into end,
        claim_token = null,
        claimed_at = null,
        updated_at = now()
    from results r
    where (x.id = r.id or x.merged_into = r.id) and x.claim_token = p_claim_token and x.status = 'processing'
    returning x.id = r.id as is_push, x.device_id, x.status, x.error_code
  ),
  invalidated as (
    update public.mobile_push_devices dev
    set status = 'invalid', invalidated_at = now(), updated_at = now()
    where dev.id in (select c.device_id from completed c where c.error_code = 'DeviceNotRegistered')
      and dev.status = 'active'
    returning dev.id
  )
  select jsonb_build_object(
    'sent', count(*) filter (where c.is_push and c.status = 'sent'),
    'retrying', count(*) filter (where c.is_push and c.status = 'pending'),
    'failed', count(*) filter (where c.is_push and c.status = 'failed'),
    'invalidated', (select count(*) from invalidated)
  ) into v_result
  from completed c;

  return v_result;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."complete_mobile_push_deliveries"(uuid, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."complete_mobile_push_deliveries"(uuid, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/complete_provider_enrollment.sql
CREATE OR REPLACE FUNCTION public.complete_provider_enrollment (
  p_user_id                   uuid,
  p_provider_slug             text,
  p_provider_name             text,
  p_provider_metadata         jsonb,
  p_website_url               text,
  p_logo_url                  text,
  p_catalog_url               text,
  p_catalog_mode              text,
  p_catalog_sha256            text,
  p_catalog_preview           jsonb,
  p_validation_summary        jsonb,
  p_model_count               integer,
  p_proof_method              text,
  p_proof_subject             text,
  p_claim_challenge_id        uuid    DEFAULT NULL::uuid,
  p_webhook_secret_ciphertext text    DEFAULT NULL::text,
  p_webhook_secret_iv         text    DEFAULT NULL::text,
  p_webhook_secret_hash       text    DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  v_submission public.provider_onboarding_submissions%rowtype;
  v_previous_submission public.provider_onboarding_submissions%rowtype;
  v_workspace_id uuid;
  v_link public.provider_account_links%rowtype;
  v_provider public.v2_providers%rowtype;
  v_provider_exists boolean := false;
  v_source_exists boolean := false;
  v_application_type text := 'new';
  v_workspace_slug text;
begin
  if p_catalog_mode not in ('remote', 'managed') then raise exception 'invalid_catalog_mode'; end if;
  if p_proof_method not in ('catalog_domain_match', 'domain_file', 'self_declared') then raise exception 'invalid_provider_proof_method'; end if;
  if p_catalog_mode = 'remote' and nullif(btrim(p_catalog_url), '') is null then raise exception 'remote_catalog_url_required'; end if;
  if p_model_count < 0 then raise exception 'invalid_model_count'; end if;

  perform 1 from public.users where user_id = p_user_id for update;
  if not found then raise exception 'provider_account_user_missing'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_provider_slug, 0));

  select * into v_provider
  from public.v2_providers
  where provider_slug = p_provider_slug
  for update;
  v_provider_exists := found;
  select * into v_previous_submission
  from public.provider_onboarding_submissions
  where provider_slug = p_provider_slug
  order by created_at desc
  limit 1
  for update;
  if p_claim_challenge_id is not null
    or (v_provider_exists and not (coalesce(v_provider.metadata, '{}'::jsonb) ? 'self_serve'))
    or (v_previous_submission.id is not null
      and v_previous_submission.application_type = 'claim'
      and v_previous_submission.provider_review_status <> 'approved') then
    v_application_type := 'claim';
  end if;
  if v_application_type = 'claim' and not v_provider_exists then
    raise exception 'provider_claim_target_missing';
  end if;

  if p_claim_challenge_id is not null then
    update public.provider_claim_challenges
       set status = 'verified', verified_at = now()
     where id = p_claim_challenge_id
       and provider_slug = p_provider_slug
       and requested_by = p_user_id
       and status = 'pending'
       and expires_at > now();
    if not found then raise exception 'provider_claim_challenge_unavailable'; end if;
  end if;

  select link.* into v_link from public.provider_account_links link
   where link.provider_slug = p_provider_slug
     and link.status in ('pending', 'active')
     and (
       exists (
         select 1 from public.workspaces workspace
         where workspace.id = link.workspace_id and workspace.owner_user_id = p_user_id
       )
       or exists (
         select 1 from public.workspace_members membership
         where membership.workspace_id = link.workspace_id
           and membership.user_id = p_user_id
           and membership.role in ('owner', 'admin')
       )
     )
   order by case when link.status = 'active' then 0 else 1 end limit 1 for update of link;
  if found then
    v_workspace_id := v_link.workspace_id;
  elsif v_application_type = 'claim' then
    if p_proof_method <> 'domain_file' then raise exception 'provider_claim_proof_required'; end if;
    if exists (
      select 1 from public.provider_account_links pending_link
      where pending_link.provider_slug = p_provider_slug
        and pending_link.status = 'pending'
        and pending_link.role = 'owner'
        and pending_link.proof_method = 'domain_file'
        and pending_link.linked_by is distinct from p_user_id
    ) then
      raise exception 'provider_claim_already_pending';
    end if;
    v_workspace_slug := 'provider-' || substr(md5(p_user_id::text || ':' || p_provider_slug), 1, 32);
    select id into v_workspace_id from public.workspaces
    where owner_user_id = p_user_id and slug = v_workspace_slug;
    if v_workspace_id is null then
      insert into public.workspaces (name, slug, owner_user_id, workspace_kind)
      values (left(p_provider_name || ' workspace', 120), v_workspace_slug, p_user_id, 'provider')
      returning id into v_workspace_id;
    end if;
    insert into public.workspace_members (workspace_id, user_id, role)
    values (v_workspace_id, p_user_id, 'owner')
    on conflict on constraint workspace_members_pkey do update set role = 'owner';
    insert into public.workspace_settings (workspace_id) values (v_workspace_id)
    on conflict on constraint workspace_settings_pkey do nothing;
    insert into public.provider_account_links as existing_link (
      provider_slug, workspace_id, linked_by, role, status, proof_method, proof_subject, verified_at
    ) values (
      p_provider_slug, v_workspace_id, p_user_id, 'owner', 'pending', 'domain_file', p_proof_subject, now()
    ) on conflict (provider_slug, workspace_id) do update
      set linked_by = excluded.linked_by,
          role = 'owner',
          status = case when existing_link.status = 'active' then 'active' else 'pending' end,
          proof_method = excluded.proof_method,
          proof_subject = excluded.proof_subject,
          verified_at = excluded.verified_at,
          updated_at = now();
  end if;

  if v_application_type <> 'claim' then
    insert into public.v2_providers (provider_slug, name, status, routing_enabled, routable, metadata)
    values (p_provider_slug, p_provider_name, 'not_ready', false, false, p_provider_metadata)
    on conflict (provider_slug) do update
      set name = excluded.name, metadata = excluded.metadata, updated_at = now();
  end if;

  perform 1 from public.provider_catalog_sources where provider_slug = p_provider_slug for update;
  v_source_exists := found;
  if v_application_type = 'claim' then
    if not v_source_exists and (
      p_webhook_secret_ciphertext is null or p_webhook_secret_iv is null or p_webhook_secret_hash is null
    ) then
      raise exception 'provider_webhook_secret_required';
    end if;
  elsif not v_source_exists then
    if p_webhook_secret_ciphertext is null or p_webhook_secret_iv is null or p_webhook_secret_hash is null then
      raise exception 'provider_webhook_secret_required';
    end if;
    insert into public.provider_catalog_sources (
      provider_slug, catalog_url, management_mode, managed_catalog,
      managed_updated_by, managed_updated_at, status, delivery_mode, created_by,
      webhook_secret_ciphertext, webhook_secret_iv, webhook_secret_hash, next_poll_at
    ) values (
      p_provider_slug, p_catalog_url, p_catalog_mode,
      case when p_catalog_mode = 'managed' then '{"data":[]}'::jsonb else null end,
      case when p_catalog_mode = 'managed' then p_user_id else null end,
      case when p_catalog_mode = 'managed' then now() else null end,
      'active', 'webhook_and_polling', p_user_id,
      p_webhook_secret_ciphertext, p_webhook_secret_iv, p_webhook_secret_hash,
      case when p_catalog_mode = 'managed' then null else now() end
    );
  elsif v_application_type <> 'claim' and p_catalog_mode = 'remote' then
    update public.provider_catalog_sources
       set catalog_url = p_catalog_url, management_mode = 'remote', managed_catalog = null,
           managed_updated_by = null, managed_updated_at = null, etag = null,
           last_modified = null, next_poll_at = now(), updated_at = now()
     where provider_slug = p_provider_slug;
  elsif v_application_type <> 'claim' then
    update public.provider_catalog_sources
       set catalog_url = null, management_mode = 'managed', managed_catalog = '{"data":[]}'::jsonb,
           managed_updated_by = p_user_id, managed_updated_at = now(), etag = null,
           last_modified = null, next_poll_at = null, refresh_requested = true, updated_at = now()
     where provider_slug = p_provider_slug;
  end if;

  insert into public.provider_onboarding_submissions (
    provider_slug, submitted_by, provider_name, website_url, logo_url, catalog_url,
    status, model_count, catalog_sha256, catalog_preview, validation_summary,
    application_type, catalog_mode, provider_review_status,
    pending_webhook_secret_ciphertext, pending_webhook_secret_iv, pending_webhook_secret_hash
  ) values (
    p_provider_slug, p_user_id, p_provider_name, p_website_url, p_logo_url, p_catalog_url,
    'submitted', p_model_count, p_catalog_sha256, p_catalog_preview, p_validation_summary,
    v_application_type, p_catalog_mode, 'awaiting_approval',
    case when v_application_type = 'claim' and not v_source_exists then p_webhook_secret_ciphertext end,
    case when v_application_type = 'claim' and not v_source_exists then p_webhook_secret_iv end,
    case when v_application_type = 'claim' and not v_source_exists then p_webhook_secret_hash end
  ) returning * into v_submission;

  if v_link.provider_slug is not null then
    if v_link.status = 'pending' and v_application_type <> 'claim' then
      update public.provider_account_links
         set status = 'active', proof_method = p_proof_method, proof_subject = p_proof_subject,
             verified_at = case when p_proof_method = 'self_declared' then null else now() end,
             updated_at = now()
       where provider_slug = p_provider_slug and workspace_id = v_link.workspace_id;
    end if;
  elsif v_application_type <> 'claim' then
    v_workspace_id := public.link_provider_personal_account(p_user_id, p_provider_slug, p_proof_subject, p_proof_method);
  end if;

  return jsonb_build_object(
    'provider', (select to_jsonb(p) from public.v2_providers p where p.provider_slug = p_provider_slug),
    'submission', to_jsonb(v_submission)
      - 'pending_webhook_secret_ciphertext'
      - 'pending_webhook_secret_iv'
      - 'pending_webhook_secret_hash',
    'providerWorkspaceId', v_workspace_id,
    'sourceCreated', not v_source_exists and v_application_type <> 'claim',
    'applicationType', v_application_type
  );
end;
$function$;

GRANT EXECUTE
  ON FUNCTION "public"."complete_provider_enrollment"(uuid, text, text, jsonb, text, text, text, text, text, jsonb, jsonb, integer, text, text, uuid, text, text, text)
  TO "service_role";

REVOKE ALL
  ON FUNCTION "public"."complete_provider_enrollment"(uuid, text, text, jsonb, text, text, text, text, text, jsonb, jsonb, integer, text, text, uuid, text, text, text)
  FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/confirm_model_discovery_issue_signals.sql
CREATE OR REPLACE FUNCTION public.confirm_model_discovery_issue_signals (
  p_run_id                  uuid,
  p_successful_provider_ids text[],
  p_entries                 jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  confirmed jsonb := '[]'::jsonb;
begin
  -- A returning model cancels its pending deletion signal.
  delete from public.model_discovery_issue_signals signal
  where signal.action = 'delete'
    and signal.provider_id = any(coalesce(p_successful_provider_ids, array[]::text[]))
    and exists (
      select 1
      from public.model_discovery_seen_models seen
      where seen.provider_id = signal.provider_id
        and seen.model_id = signal.model_id
    );

  -- Existing absent candidates have now survived another successful sweep.
  update public.model_discovery_issue_signals signal
  set
    consecutive_sweeps = signal.consecutive_sweeps + 1,
    last_observed_at = now(),
    last_observed_run_id = p_run_id
  where signal.action = 'delete'
    and signal.emitted_at is null
    and signal.provider_id = any(coalesce(p_successful_provider_ids, array[]::text[]))
    and signal.last_observed_run_id is distinct from p_run_id
    and not exists (
      select 1
      from public.model_discovery_seen_models seen
      where seen.provider_id = signal.provider_id
        and seen.model_id = signal.model_id
    );

  -- New deletion candidates begin at one observed sweep. Other actions are
  -- returned immediately and do not require confirmation.
  insert into public.model_discovery_issue_signals (
    source,
    provider_id,
    action,
    model_id,
    entry,
    consecutive_sweeps,
    first_observed_at,
    last_observed_at,
    last_observed_run_id
  )
  select
    raw.value ->> 'source',
    raw.value ->> 'providerId',
    raw.value ->> 'action',
    raw.value ->> 'modelId',
    raw.value,
    1,
    now(),
    now(),
    p_run_id
  from jsonb_array_elements(coalesce(p_entries, '[]'::jsonb)) raw(value)
  where raw.value ->> 'action' = 'delete'
    and raw.value ->> 'providerId' = any(coalesce(p_successful_provider_ids, array[]::text[]))
  on conflict (source, provider_id, action, model_id) do update set
    entry = excluded.entry,
    last_observed_at = excluded.last_observed_at,
    last_observed_run_id = excluded.last_observed_run_id;

  with immediate_entries as (
    select value as entry
    from jsonb_array_elements(coalesce(p_entries, '[]'::jsonb))
    where value ->> 'action' <> 'delete'
  ), confirmed_deletions as (
    select signal.entry
    from public.model_discovery_issue_signals signal
    where signal.action = 'delete'
      and signal.emitted_at is null
      and signal.consecutive_sweeps >= 2
      and signal.provider_id = any(coalesce(p_successful_provider_ids, array[]::text[]))
  ), all_confirmed as (
    select entry from immediate_entries
    union all
    select entry from confirmed_deletions
  )
  select coalesce(jsonb_agg(entry), '[]'::jsonb)
  into confirmed
  from all_confirmed;

  return confirmed;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."confirm_model_discovery_issue_signals"(uuid, text[], jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."confirm_model_discovery_issue_signals"(uuid, text[], jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/consume_checkout_rate_limit.sql
CREATE OR REPLACE FUNCTION public.consume_checkout_rate_limit (
  p_workspace_id uuid,
  p_user_id      uuid,
  p_limit        integer DEFAULT 10
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  accepted integer;
  bucket timestamptz := date_trunc('minute', now());
begin
  if p_limit is null or p_limit < 1 or p_limit > 100 then
    raise exception 'invalid_checkout_rate_limit';
  end if;
  delete from public.checkout_rate_limits target
  using (
    select workspace_id, user_id, bucket_start
    from public.checkout_rate_limits
    where bucket_start < now() - interval '1 day'
    order by bucket_start
    limit 100
  ) expired
  where target.workspace_id = expired.workspace_id
    and target.user_id = expired.user_id
    and target.bucket_start = expired.bucket_start;
  insert into public.checkout_rate_limits (workspace_id, user_id, bucket_start, request_count)
  values (p_workspace_id, p_user_id, bucket, 1)
  on conflict (workspace_id, user_id, bucket_start) do update
    set request_count = public.checkout_rate_limits.request_count + 1
    where public.checkout_rate_limits.request_count < p_limit
  returning request_count into accepted;
  return accepted is not null;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."consume_checkout_rate_limit"(uuid, uuid, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."consume_checkout_rate_limit"(uuid, uuid, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/consume_oauth_code_and_issue_delegated_grant.sql
CREATE OR REPLACE FUNCTION public.consume_oauth_code_and_issue_delegated_grant (
  p_code_id              uuid,
  p_key_hash             text,
  p_key_kid              text,
  p_key_prefix           text,
  p_key_name             text,
  p_user_id              uuid,
  p_workspace_id         uuid,
  p_client_id            text,
  p_scopes               text[],
  p_resource             text,
  p_refresh_token_hash   text,
  p_refresh_expires_at   timestamp with time zone
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  granted_scopes text[];
  granted_resource text;
  approved_monthly_limit bigint;
  resource_is_gateway boolean;
  resource_class text;
  existing_key public.keys%rowtype;
  issued_key_id uuid;
  issued_kid text;
  outcome text;
begin
  if nullif(btrim(p_refresh_token_hash), '') is null or p_refresh_expires_at is null then
    return jsonb_build_object('status', 'invalid');
  end if;

  resource_is_gateway := coalesce(
    btrim(p_resource) ~* '^https://api\.phaseo\.app(?::443)?/v1/*$',
    false
  );

  -- Unbound and Gateway-bound credentials both authorize billable API use.
  if (nullif(btrim(p_resource), '') is null or resource_is_gateway)
    and not (coalesce(p_scopes, array[]::text[]) @> array['gateway:access']::text[])
  then
    return jsonb_build_object('status', 'invalid');
  end if;

  -- Lock order, as in both refresh-token rotations, revoke_oauth_refresh_token_grant and the
  -- member-delete trigger: membership -> authorization -> key -> refresh tokens.
  perform 1
  from public.workspace_members member
  where member.user_id = p_user_id
    and member.workspace_id = p_workspace_id
  for key share;

  if not found then
    return jsonb_build_object('status', 'invalid');
  end if;

  perform 1
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = p_user_id
    and authorization_row.workspace_id = p_workspace_id
    and authorization_row.client_id = p_client_id
    and authorization_row.revoked_at is null
    and coalesce(authorization_row.scopes, array[]::text[]) @> coalesce(p_scopes, array[]::text[])
    and (
      (nullif(btrim(p_resource), '') is not null and not resource_is_gateway)
      or coalesce(authorization_row.scopes, array[]::text[]) @> array['gateway:access']::text[]
    )
  for update;

  if not found then
    return jsonb_build_object('status', 'invalid');
  end if;

  update public.oauth_authorization_codes authorization_code
  set used_at = now()
  where authorization_code.id = p_code_id
    and authorization_code.used_at is null
    and authorization_code.expires_at > now()
    and authorization_code.user_id = p_user_id
    and authorization_code.workspace_id = p_workspace_id
    and authorization_code.client_id = p_client_id
    and authorization_code.resource is not distinct from nullif(btrim(p_resource), '')
    and (
      (authorization_code.resource is not null and not resource_is_gateway)
      or coalesce(authorization_code.scopes, array[]::text[]) @> array['gateway:access']::text[]
    )
    and coalesce(authorization_code.scopes, array[]::text[]) <@ coalesce(p_scopes, array[]::text[])
    and coalesce(p_scopes, array[]::text[]) <@ coalesce(authorization_code.scopes, array[]::text[])
  returning authorization_code.scopes, authorization_code.resource, authorization_code.key_monthly_limit_cost_nanos
    into granted_scopes, granted_resource, approved_monthly_limit;

  if not found then
    return jsonb_build_object('status', 'invalid');
  end if;

  -- A key an owner or admin paused (or a storage incident paused) is never turned back on, or
  -- replaced, by signing in again: while any of this app's keys for the person in this workspace is
  -- paused or disabled, whatever resource it was issued for, nothing is issued. The code is spent.
  if exists (
    select 1
    from public.keys key_row
    where key_row.key_kind = 'oauth_delegated'
      and key_row.issued_via <> 'desktop'
      and key_row.oauth_user_id = p_user_id
      and key_row.workspace_id = p_workspace_id
      and key_row.oauth_client_id = p_client_id
      and key_row.status not in ('active', 'revoked', 'compromised', 'deleted')
  ) then
    return jsonb_build_object('status', 'key_inactive');
  end if;

  -- An unbound key and every spelling of the Gateway's resource are the same credential to the
  -- gateway, so renewal finds the app's key whichever of them the app asks for.
  resource_class := case
    when nullif(btrim(granted_resource), '') is null or resource_is_gateway then 'https://api.phaseo.app/v1'
    else btrim(granted_resource)
  end;

  -- Approving the same app again renews its key instead of adding one, so the key keeps its id,
  -- limits, month-to-date spend and history. Revoked, compromised and deleted keys are final.
  select * into existing_key
  from public.keys key_row
  where key_row.key_kind = 'oauth_delegated'
    and key_row.issued_via = 'oauth_pkce'
    and key_row.oauth_user_id = p_user_id
    and key_row.workspace_id = p_workspace_id
    and key_row.oauth_client_id = p_client_id
    and case
      when nullif(btrim(key_row.oauth_resource), '') is null
        or btrim(key_row.oauth_resource) ~* '^https://api\.phaseo\.app(?::443)?/v1/*$'
        then 'https://api.phaseo.app/v1'
      else btrim(key_row.oauth_resource)
    end = resource_class
    and key_row.status not in ('revoked', 'compromised', 'deleted')
  order by (key_row.status = 'active') desc, key_row.created_at desc
  limit 1
  for update;

  if found then
    -- Paused after the check above, while this exchange waited for the key's lock.
    if existing_key.status <> 'active' then
      return jsonb_build_object('status', 'key_inactive');
    end if;

    -- Every earlier sign-in's refresh-token family is retired here, spent tokens included, and the
    -- new secret ends its access token. Presenting a retired token later is just refused, never
    -- treated as reuse, so it can't end this key or the family issued below.
    update public.oauth_refresh_tokens
    set revoked_at = coalesce(revoked_at, now()), revoked_reason = 'superseded'
    where key_id = existing_key.id
      and revoked_reason is null;

    -- The monthly limit the person just approved on the consent screen wins; a code from before the
    -- screen asked keeps the key's limit. Spend already counted this month stays counted.
    update public.keys
    set hash = p_key_hash,
      oauth_scopes = granted_scopes,
      expires_at = now() + interval '7 days',
      monthly_limit_cost_nanos = coalesce(approved_monthly_limit, existing_key.monthly_limit_cost_nanos)
    where id = existing_key.id;

    issued_key_id := existing_key.id;
    issued_kid := existing_key.kid;
    outcome := 'renewed';
  else
    -- The gateway enforces the approved amount like any key's monthly cost limit (0 is no limit).
    insert into public.keys (
      workspace_id, name, hash, prefix, status, scopes, created_by, kid,
      key_kind, oauth_client_id, oauth_user_id, oauth_scopes, oauth_resource, issued_via, expires_at,
      monthly_limit_cost_nanos
    ) values (
      p_workspace_id, p_key_name, p_key_hash, p_key_prefix, 'active', '[]', p_user_id, p_key_kid,
      'oauth_delegated', p_client_id, p_user_id, granted_scopes, granted_resource, 'oauth_pkce', now() + interval '7 days',
      coalesce(approved_monthly_limit, 0)
    )
    returning id, kid into issued_key_id, issued_kid;
    outcome := 'issued';
  end if;

  -- The refresh token renews this key (same row, new secret) until it is revoked or unused for 90 days.
  insert into public.oauth_refresh_tokens (
    token_hash, user_id, workspace_id, client_id, scopes, expires_at, family_id, key_id
  ) values (
    p_refresh_token_hash, p_user_id, p_workspace_id, p_client_id, granted_scopes, p_refresh_expires_at,
    gen_random_uuid(), issued_key_id
  );

  return jsonb_build_object('status', outcome, 'kid', issued_kid);
end;
$function$;

COMMENT ON FUNCTION "public"."consume_oauth_code_and_issue_delegated_grant"(uuid, text, text, text, text, uuid, uuid, text, text[], text, text, timestamp WITH time zone) IS 'Exchanges a third-party OAuth authorization code for a delegated gateway key (the access token, 7 days) and a refresh token bound to that key (90 days, rotated by rotate_oauth_delegated_refresh_token), in one transaction. Approving the same app again renews its existing key (same row, new secret, new refresh-token family) instead of adding one, retires the earlier families (revoked_reason superseded), and issues nothing while any of the app''s keys for that person and workspace is paused or disabled, whatever resource it is bound to (an unbound key and the Gateway''s resource count as one). The monthly spending limit approved with the code becomes the key''s monthly cost limit, on a new or a renewed key. Returns {status: issued|renewed|key_inactive|invalid, kid}.';

GRANT EXECUTE ON FUNCTION "public"."consume_oauth_code_and_issue_delegated_grant"(uuid, text, text, text, text, uuid, uuid, text, text[], text, text, timestamp WITH time zone) TO "service_role";

REVOKE ALL
  ON FUNCTION "public"."consume_oauth_code_and_issue_delegated_grant"(uuid, text, text, text, text, uuid, uuid, text, text[], text, text, timestamp WITH time zone)
  FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/consume_oauth_code_and_issue_managed_key.sql
CREATE OR REPLACE FUNCTION public.consume_oauth_code_and_issue_managed_key (
  p_code_id      uuid,
  p_key_hash     text,
  p_key_kid      text,
  p_key_prefix   text,
  p_key_name     text,
  p_user_id      uuid,
  p_workspace_id uuid,
  p_client_id    text,
  p_scopes       text[]
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  granted_scopes text[];
begin
  if not (coalesce(p_scopes, array[]::text[]) @> array['gateway:access']::text[]) then
    return 'invalid';
  end if;

  -- Match the workspace-member deletion trigger's lock order.
  perform 1
  from public.workspace_members member
  where member.user_id = p_user_id
    and member.workspace_id = p_workspace_id
  for key share;

  if not found then
    return 'invalid';
  end if;

  perform 1
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = p_user_id
    and authorization_row.workspace_id = p_workspace_id
    and authorization_row.client_id = p_client_id
    and authorization_row.revoked_at is null
    and coalesce(authorization_row.scopes, array[]::text[]) @> array['gateway:access']::text[]
  for update;

  if not found then
    return 'invalid';
  end if;

  update public.oauth_authorization_codes authorization_code
  set used_at = now()
  where authorization_code.id = p_code_id
    and authorization_code.used_at is null
    and authorization_code.expires_at > now()
    and authorization_code.user_id = p_user_id
    and authorization_code.workspace_id = p_workspace_id
    and authorization_code.client_id = p_client_id
    and coalesce(authorization_code.scopes, array[]::text[]) @> array['gateway:access']::text[]
    and coalesce(authorization_code.scopes, array[]::text[]) <@ coalesce(p_scopes, array[]::text[])
    and coalesce(p_scopes, array[]::text[]) <@ coalesce(authorization_code.scopes, array[]::text[])
  returning authorization_code.scopes into granted_scopes;

  if not found then
    return 'invalid';
  end if;

  update public.keys
  set status = 'revoked'
  where key_kind = 'oauth_delegated'
    and oauth_user_id = p_user_id
    and workspace_id = p_workspace_id
    and oauth_client_id = p_client_id
    and status = 'active';

  insert into public.keys (
    workspace_id, name, hash, prefix, status, scopes, created_by, kid,
    key_kind, oauth_client_id, oauth_user_id, oauth_scopes, issued_via
  ) values (
    p_workspace_id, p_key_name, p_key_hash, p_key_prefix, 'active', '[]', p_user_id, p_key_kid,
    'oauth_delegated', p_client_id, p_user_id, granted_scopes, 'oauth_pkce'
  );

  return 'issued';
end;
$function$;

CREATE OR REPLACE FUNCTION public.consume_oauth_code_and_issue_managed_key (
  p_code_id      uuid,
  p_key_hash     text,
  p_key_kid      text,
  p_key_prefix   text,
  p_key_name     text,
  p_user_id      uuid,
  p_workspace_id uuid,
  p_client_id    text,
  p_scopes       text[],
  p_resource     text
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  granted_scopes text[];
  granted_resource text;
  resource_is_gateway boolean;
begin
  resource_is_gateway := coalesce(
    btrim(p_resource) ~* '^https://api\.phaseo\.app(?::443)?/v1/*$',
    false
  );

  -- Unbound and Gateway-bound credentials both authorize billable API use.
  if (nullif(btrim(p_resource), '') is null or resource_is_gateway)
    and not (coalesce(p_scopes, array[]::text[]) @> array['gateway:access']::text[])
  then
    return 'invalid';
  end if;

  perform 1
  from public.workspace_members member
  where member.user_id = p_user_id
    and member.workspace_id = p_workspace_id
  for key share;

  if not found then
    return 'invalid';
  end if;

  perform 1
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = p_user_id
    and authorization_row.workspace_id = p_workspace_id
    and authorization_row.client_id = p_client_id
    and authorization_row.revoked_at is null
    and coalesce(authorization_row.scopes, array[]::text[]) @> coalesce(p_scopes, array[]::text[])
    and (
      (nullif(btrim(p_resource), '') is not null and not resource_is_gateway)
      or coalesce(authorization_row.scopes, array[]::text[]) @> array['gateway:access']::text[]
    )
  for update;

  if not found then
    return 'invalid';
  end if;

  update public.oauth_authorization_codes authorization_code
  set used_at = now()
  where authorization_code.id = p_code_id
    and authorization_code.used_at is null
    and authorization_code.expires_at > now()
    and authorization_code.user_id = p_user_id
    and authorization_code.workspace_id = p_workspace_id
    and authorization_code.client_id = p_client_id
    and authorization_code.resource is not distinct from nullif(btrim(p_resource), '')
    and (
      (authorization_code.resource is not null and not resource_is_gateway)
      or coalesce(authorization_code.scopes, array[]::text[]) @> array['gateway:access']::text[]
    )
    and coalesce(authorization_code.scopes, array[]::text[]) <@ coalesce(p_scopes, array[]::text[])
    and coalesce(p_scopes, array[]::text[]) <@ coalesce(authorization_code.scopes, array[]::text[])
  returning authorization_code.scopes, authorization_code.resource
    into granted_scopes, granted_resource;

  if not found then
    return 'invalid';
  end if;

  update public.keys
  set status = 'revoked'
  where key_kind = 'oauth_delegated'
    and oauth_user_id = p_user_id
    and workspace_id = p_workspace_id
    and oauth_client_id = p_client_id
    and oauth_resource is not distinct from granted_resource
    and status = 'active';

  insert into public.keys (
    workspace_id, name, hash, prefix, status, scopes, created_by, kid,
    key_kind, oauth_client_id, oauth_user_id, oauth_scopes, oauth_resource, issued_via, expires_at
  ) values (
    p_workspace_id, p_key_name, p_key_hash, p_key_prefix, 'active', '[]', p_user_id, p_key_kid,
    'oauth_delegated', p_client_id, p_user_id, granted_scopes, granted_resource, 'oauth_pkce', now() + interval '7 days'
  );

  return 'issued';
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."consume_oauth_code_and_issue_managed_key"(uuid, text, text, text, text, uuid, uuid, text, text[]) TO "service_role";

GRANT EXECUTE ON FUNCTION "public"."consume_oauth_code_and_issue_managed_key"(uuid, text, text, text, text, uuid, uuid, text, text[], text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."consume_oauth_code_and_issue_managed_key"(uuid, text, text, text, text, uuid, uuid, text, text[]) FROM PUBLIC, "anon", "authenticated";

