-- source: supabase/schemas/public/functions/consume_spend_rule_test_send.sql
CREATE OR REPLACE FUNCTION public.consume_spend_rule_test_send (
  p_workspace_id uuid,
  p_limit        integer DEFAULT 5
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Takes one spend rule test send from the workspace's allowance for the current minute (5 by
-- default, the same on every plan): true if allowed, false once the minute's allowance is used.
-- The same fixed-window counter as public.consume_checkout_rate_limit, keyed by workspace so the
-- control API and the settings page share it.
declare
  v_accepted integer;
  v_bucket timestamptz := date_trunc('minute', now());
begin
  if p_workspace_id is null or p_limit is null or p_limit < 1 or p_limit > 100 then
    raise exception 'invalid_spend_rule_test_send_limit' using errcode = '22023';
  end if;
  delete from public.workspace_spend_rule_test_sends target
  using (
    select expired.workspace_id, expired.bucket_start
    from public.workspace_spend_rule_test_sends expired
    where expired.bucket_start < now() - interval '1 day'
    order by expired.bucket_start
    limit 100
  ) old
  where target.workspace_id = old.workspace_id
    and target.bucket_start = old.bucket_start;
  insert into public.workspace_spend_rule_test_sends as sends (workspace_id, bucket_start, request_count)
  values (p_workspace_id, v_bucket, 1)
  on conflict (workspace_id, bucket_start) do update
    set request_count = sends.request_count + 1
    where sends.request_count < p_limit
  returning sends.request_count into v_accepted;
  return v_accepted is not null;
end;
$function$;

COMMENT ON FUNCTION "public"."consume_spend_rule_test_send"(uuid, integer) IS 'Fixed-window limiter for spend rule test sends: true while the workspace has sent fewer than p_limit (default 5) this minute. Service role only.';

REVOKE ALL ON FUNCTION "public"."consume_spend_rule_test_send"(uuid, integer) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."consume_spend_rule_test_send"(uuid, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."consume_spend_rule_test_send"(uuid, integer) FROM "anon", "authenticated";

-- source: supabase/schemas/public/functions/copy_v2_performance_metrics_from_metadata.sql
CREATE OR REPLACE FUNCTION public.copy_v2_performance_metrics_from_metadata()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  performance jsonb := coalesce(new.safe_metadata->'performance', '{}'::jsonb);
begin
  if performance ? 'provider_ttft_ms' then
    new.provider_ttft_ms := nullif(greatest(0, round(nullif(performance->>'provider_ttft_ms', '')::numeric)), 0)::integer;
  end if;
  if performance ? 'gateway_ttft_ms' then
    new.gateway_ttft_ms := nullif(greatest(0, round(nullif(performance->>'gateway_ttft_ms', '')::numeric)), 0)::integer;
  end if;
  if performance ? 'output_speed_tps' then
    new.output_speed_tps := nullif(greatest(0, nullif(performance->>'output_speed_tps', '')::numeric), 0);
  end if;
  if performance ? 'tpot_ms' then
    new.tpot_ms := nullif(greatest(0, nullif(performance->>'tpot_ms', '')::numeric), 0);
  end if;
  if performance ? 'itl_ms' then
    new.itl_ms := nullif(greatest(0, nullif(performance->>'itl_ms', '')::numeric), 0);
  end if;
  if performance ? 'phaseo_overhead_ms' then
    -- Zero is a real overhead reading; only a missing value becomes NULL.
    new.phaseo_overhead_ms := case
      when nullif(performance->>'phaseo_overhead_ms', '') is null then null
      else greatest(0, round((performance->>'phaseo_overhead_ms')::numeric))::integer
    end;
  end if;
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."copy_v2_performance_metrics_from_metadata"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."copy_v2_performance_metrics_from_metadata"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/create_credit_topup_request.sql
CREATE OR REPLACE FUNCTION public.create_credit_topup_request (
  p_workspace_id          uuid,
  p_requested_by          uuid,
  p_requested_via         text,
  p_oauth_client_id       text,
  p_flow                  text,
  p_amount_cents          integer,
  p_payment_method_id     text,
  p_payment_method_brand  text,
  p_payment_method_last4  text,
  p_confirm_token_hash    text,
  p_idempotency_key       text,
  p_ttl_seconds           integer DEFAULT 1800,
  p_max_pending           integer DEFAULT 5
)
  RETURNS TABLE (
    request_id uuid,
    created    boolean
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Creates a pending credit top-up request, or returns the earlier one for the same
-- (workspace, idempotency key). Serialised per workspace so the pending cap holds under
-- concurrent calls. Pending requests past their expiry are marked expired first.
declare
  v_existing public.credit_topup_requests%rowtype;
  v_pending integer;
  v_id uuid;
begin
  if p_workspace_id is null or p_amount_cents is null or p_confirm_token_hash is null
    or p_ttl_seconds is null or p_ttl_seconds < 60 or p_ttl_seconds > 86400
    or p_max_pending is null or p_max_pending < 1 or p_max_pending > 100 then
    raise exception 'credit_topup_invalid_arguments' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('credit_topup_requests:' || p_workspace_id::text, 0));

  if p_idempotency_key is not null then
    select * into v_existing
    from public.credit_topup_requests r
    where r.workspace_id = p_workspace_id
      and r.idempotency_key = p_idempotency_key;
    if found then
      if v_existing.amount_cents <> p_amount_cents
        or v_existing.requested_by is distinct from p_requested_by then
        raise exception 'credit_topup_idempotency_conflict' using errcode = '22023';
      end if;
      return query select v_existing.id, false;
      return;
    end if;
  end if;

  update public.credit_topup_requests r
  set status = 'expired', reason = 'expired', updated_at = now()
  where r.workspace_id = p_workspace_id
    and r.status = 'pending'
    and r.expires_at <= now();

  select count(*) into v_pending
  from public.credit_topup_requests r
  where r.workspace_id = p_workspace_id
    and r.status = 'pending';
  if v_pending >= p_max_pending then
    raise exception 'credit_topup_too_many_pending' using errcode = 'P0001';
  end if;

  insert into public.credit_topup_requests (
    workspace_id, requested_by, requested_via, oauth_client_id, flow, amount_cents,
    payment_method_id, payment_method_brand, payment_method_last4,
    confirm_token_hash, idempotency_key, expires_at
  )
  values (
    p_workspace_id, p_requested_by, p_requested_via, p_oauth_client_id, p_flow, p_amount_cents,
    p_payment_method_id, p_payment_method_brand, p_payment_method_last4,
    p_confirm_token_hash, p_idempotency_key, now() + make_interval(secs => p_ttl_seconds)
  )
  returning id into v_id;

  return query select v_id, true;
end;
$function$;

COMMENT ON FUNCTION "public"."create_credit_topup_request"(uuid, uuid, text, text, text, integer, text, text, text, text, text, integer, integer) IS 'Creates a pending credit top-up request (at most p_max_pending, default 5, pending per workspace), or returns the existing request for the same idempotency key. Service role only.';

REVOKE ALL ON FUNCTION "public"."create_credit_topup_request"(uuid, uuid, text, text, text, integer, text, text, text, text, text, integer, integer) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."create_credit_topup_request"(uuid, uuid, text, text, text, integer, text, text, text, text, text, integer, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."create_credit_topup_request"(uuid, uuid, text, text, text, integer, text, text, text, text, text, integer, integer) FROM "anon", "authenticated";

-- source: supabase/schemas/public/functions/create_mobile_notification_rule.sql
CREATE OR REPLACE FUNCTION public.create_mobile_notification_rule (
  p_user_id   uuid,
  p_rule      jsonb,
  p_max_rules integer
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Adds a rule after the user's last one, unless they already have p_max_rules. p_rule holds
-- mobile_notification_rules columns; omitted ones take the table's defaults, and id, user_id
-- and position are ignored. Creates for one user run one at a time, so concurrent requests
-- can neither pass the limit nor share a position. Returns {"rule": {...}} or
-- {"error": "rule_limit_reached"}.
declare
  v_count integer;
  v_last_position integer;
  v_rule public.mobile_notification_rules%rowtype;
begin
  if p_user_id is null or jsonb_typeof(p_rule) is distinct from 'object' then
    raise exception 'invalid_mobile_notification_rule';
  end if;
  if p_max_rules is null or p_max_rules < 1 or p_max_rules > 1000 then
    raise exception 'invalid_mobile_notification_rule_limit';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('mobile_notification_rules:' || p_user_id::text, 0));

  select count(*)::integer, max(r."position") into v_count, v_last_position
  from public.mobile_notification_rules r
  where r.user_id = p_user_id;

  if v_count >= p_max_rules then
    return jsonb_build_object('error', 'rule_limit_reached');
  end if;

  insert into public.mobile_notification_rules as r (
    user_id, name, enabled, action, event_kinds, lab_mode, lab_slugs, provider_mode, provider_slugs, model_slugs,
    input_modalities, output_modalities, only_on_phaseo, include_free_variants, "position"
  )
  select
    p_user_id,
    x.name,
    coalesce(x.enabled, true),
    coalesce(x.action, 'notify'),
    x.event_kinds,
    coalesce(x.lab_mode, 'all'),
    coalesce(x.lab_slugs, '{}'),
    coalesce(x.provider_mode, 'all'),
    coalesce(x.provider_slugs, '{}'),
    coalesce(x.model_slugs, '{}'),
    coalesce(x.input_modalities, '{}'),
    coalesce(x.output_modalities, '{}'),
    coalesce(x.only_on_phaseo, false),
    coalesce(x.include_free_variants, false),
    coalesce(v_last_position + 1, 0)
  from jsonb_populate_record(null::public.mobile_notification_rules, p_rule) as x
  returning r.* into v_rule;

  return jsonb_build_object('rule', to_jsonb(v_rule) - 'user_id' - 'created_at' - 'updated_at');
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."create_mobile_notification_rule"(uuid, jsonb, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."create_mobile_notification_rule"(uuid, jsonb, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/create_workload_identity_policy.sql
CREATE OR REPLACE FUNCTION public.create_workload_identity_policy (
  p_workspace_id               uuid,
  p_created_by                 uuid,
  p_name                       text,
  p_provider                   text,
  p_issuer                     text,
  p_pinned_owner_id            text,
  p_claim_conditions           jsonb,
  p_max_token_lifetime_seconds integer
)
  RETURNS TABLE (policy_id uuid, key_id uuid)
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  new_key_id uuid;
begin
  -- Serialise creates per workspace so concurrent requests cannot both pass
  -- the policy cap.
  perform pg_advisory_xact_lock(hashtextextended('workload_identity_policy:' || p_workspace_id::text, 0));
  if (select count(*) from public.workload_identity_policies p where p.workspace_id = p_workspace_id) >= 50 then
    raise exception 'workload_identity_policy_limit' using errcode = 'P0001';
  end if;

  -- The key row has no usable secret: its hash is random and never shown, and
  -- the gateway refuses workload_identity keys presented as API keys.
  insert into public.keys (
    workspace_id, name, hash, prefix, status, scopes, created_by, kid, key_kind, issued_via
  ) values (
    p_workspace_id, p_name, 'workload_identity:' || gen_random_uuid()::text, 'oidc', 'active', '[]', p_created_by,
    replace(gen_random_uuid()::text, '-', ''), 'workload_identity', 'workload_identity'
  )
  returning id into new_key_id;

  return query
  insert into public.workload_identity_policies as policy (
    workspace_id, key_id, name, provider, issuer, pinned_owner_id, claim_conditions,
    max_token_lifetime_seconds, created_by
  ) values (
    p_workspace_id, new_key_id, p_name, p_provider, p_issuer, p_pinned_owner_id,
    coalesce(p_claim_conditions, '{}'::jsonb), coalesce(p_max_token_lifetime_seconds, 43200), p_created_by
  )
  returning policy.id, policy.key_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."create_workload_identity_policy"(uuid, uuid, text, text, text, text, jsonb, integer) TO "service_role";

COMMENT ON FUNCTION "public"."create_workload_identity_policy"(uuid, uuid, text, text, text, text, jsonb, integer) IS 'Creates a workload identity trust policy together with the secretless keys row it authenticates as. Raises workload_identity_policy_limit when the workspace already has 50 policies; creates for one workspace are serialised so the cap holds under concurrency. The caller must already have checked that p_created_by is a workspace admin and validated the policy.';

REVOKE ALL ON FUNCTION "public"."create_workload_identity_policy"(uuid, uuid, text, text, text, text, jsonb, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/decide_credit_topup_request.sql
CREATE OR REPLACE FUNCTION public.decide_credit_topup_request (
  p_request_id         uuid,
  p_confirm_token_hash text,
  p_user_id            uuid,
  p_decision           text,
  p_expected_checkout_session_id text DEFAULT NULL::text
)
  RETURNS TABLE (
    status  text,
    reason  text,
    changed boolean
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Records a workspace owner's or admin's answer to a credit top-up request. Needs the
-- confirm link's token and an owner or admin of the request's workspace. Only a pending,
-- unexpired request changes: confirm -> confirmed, decline -> declined. Asking again
-- returns the current status with changed = false, so a confirmed request can resume its
-- payment (for example after 3D Secure) without being confirmed twice.
-- A decline only commits while the request's Checkout Session is the one the caller saw and
-- expired (p_expected_checkout_session_id; NULL when it saw none). If checkout attached a
-- session in the meantime it raises credit_topup_checkout_changed, so the caller expires that
-- session and declines again. A declined request never keeps a payable session.
declare
  v_request public.credit_topup_requests%rowtype;
begin
  if p_request_id is null or p_confirm_token_hash is null or p_user_id is null
    or p_decision is null or p_decision not in ('confirm', 'decline') then
    raise exception 'credit_topup_invalid_arguments' using errcode = '22023';
  end if;

  select * into v_request
  from public.credit_topup_requests r
  where r.id = p_request_id
  for update;
  if not found or v_request.confirm_token_hash <> p_confirm_token_hash then
    raise exception 'credit_topup_not_found' using errcode = 'P0002';
  end if;

  if not exists (
    select 1 from public.workspace_members m
    where m.workspace_id = v_request.workspace_id
      and m.user_id = p_user_id
      and m.role::text in ('owner', 'admin')
  ) and not exists (
    select 1 from public.workspaces w
    where w.id = v_request.workspace_id
      and w.owner_user_id = p_user_id
  ) then
    raise exception 'credit_topup_forbidden' using errcode = '42501';
  end if;

  if v_request.status = 'pending' and v_request.expires_at <= now() then
    update public.credit_topup_requests r
    set status = 'expired', reason = 'expired', updated_at = now()
    where r.id = v_request.id;
    return query select 'expired'::text, 'expired'::text, true;
    return;
  end if;

  if v_request.status <> 'pending' then
    return query select v_request.status, v_request.reason, false;
    return;
  end if;

  if p_decision = 'decline'
    and v_request.stripe_checkout_session_id is distinct from p_expected_checkout_session_id then
    raise exception 'credit_topup_checkout_changed' using errcode = '40001';
  end if;

  update public.credit_topup_requests r
  set status = case when p_decision = 'confirm' then 'confirmed' else 'declined' end,
      reason = case when p_decision = 'confirm' then null else 'declined' end,
      decided_by = p_user_id,
      decided_at = now(),
      updated_at = now()
  where r.id = v_request.id;

  return query select
    case when p_decision = 'confirm' then 'confirmed' else 'declined' end,
    case when p_decision = 'confirm' then null else 'declined' end,
    true;
end;
$function$;

COMMENT ON FUNCTION "public"."decide_credit_topup_request"(uuid, text, uuid, text, text) IS 'Confirms or declines a pending credit top-up request for a workspace owner or admin holding the confirm link token. Service role only.';

