-- source: supabase/schemas/public/functions/declare_key_storage_incident.sql
CREATE OR REPLACE FUNCTION public.declare_key_storage_incident (
  p_client_request_id   uuid,
  p_location_id         text,
  p_action              text,
  p_keys_created_before timestamp with time zone,
  p_title               text,
  p_customer_message    text,
  p_source_url          text,
  p_declared_by         uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_incident_id uuid;
  v_created boolean := false;
begin
  -- Declares an incident and applies it in the same transaction, so there is
  -- never a declared but unapplied incident. Retrying with the same
  -- p_client_request_id returns the first result instead of declaring again,
  -- so a caller that lost the response (or failed to send the emails) can
  -- safely retry. Service-only.
  insert into public.key_storage_incidents (client_request_id, location_id, action, keys_created_before, title, customer_message, source_url, declared_by)
  values (p_client_request_id, p_location_id, p_action, p_keys_created_before, p_title, p_customer_message, p_source_url, p_declared_by)
  on conflict (client_request_id) do nothing
  returning id into v_incident_id;

  if v_incident_id is null then
    select incident.id into v_incident_id
    from public.key_storage_incidents as incident
    where incident.client_request_id = p_client_request_id;
  else
    v_created := true;
    perform public.apply_key_storage_incident(v_incident_id);
  end if;

  return jsonb_build_object(
    'incident_id', v_incident_id,
    'created', v_created,
    'keys', coalesce((
      select jsonb_agg(jsonb_build_object('key_id', changed.key_id, 'workspace_id', changed.workspace_id) order by changed.key_id)
      from public.key_storage_incident_keys as changed
      where changed.incident_id = v_incident_id
    ), '[]'::jsonb)
  );
end;
$function$;

COMMENT ON FUNCTION "public"."declare_key_storage_incident"(uuid, text, text, timestamp with time zone, text, text, text, uuid) IS 'Declares and applies a key storage incident in one transaction; idempotent per client request id. Returns the incident id and the keys it changed. Service-only.';

GRANT EXECUTE ON FUNCTION "public"."declare_key_storage_incident"(uuid, text, text, timestamp with time zone, text, text, text, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."declare_key_storage_incident"(uuid, text, text, timestamp with time zone, text, text, text, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/deduct_and_check_top_up.sql
CREATE OR REPLACE FUNCTION public.deduct_and_check_top_up (
  p_workspace_id uuid,
  p_cost_nanos   bigint
)
  RETURNS json
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_new_balance bigint;
  v_low_threshold bigint;
  v_auto_top_up_amount bigint;
  v_auto_top_up_enabled boolean;
  v_auto_top_up_account_id text;
  v_stripe_customer_id text;
begin
  if p_cost_nanos is null or p_cost_nanos <= 0 then
    raise exception 'invalid_cost_nanos';
  end if;
  update public.wallets
  set balance_nanos = balance_nanos - p_cost_nanos
  where workspace_id = p_workspace_id
    and balance_nanos - p_cost_nanos >= coalesce(reserved_nanos, 0)
  returning balance_nanos, low_balance_threshold, auto_top_up_amount,
    auto_top_up_enabled, auto_top_up_account_id, stripe_customer_id
  into v_new_balance, v_low_threshold, v_auto_top_up_amount,
    v_auto_top_up_enabled, v_auto_top_up_account_id, v_stripe_customer_id;

  if v_new_balance is null then
    if exists (select 1 from public.wallets where workspace_id = p_workspace_id) then
      raise exception 'insufficient_unreserved_balance';
    end if;
    return json_build_object('status', 'wallet_not_found');
  end if;
  if v_auto_top_up_enabled and v_new_balance < v_low_threshold then
    return json_build_object(
      'status', 'top_up_required',
      'auto_top_up_amount_nanos', v_auto_top_up_amount,
      'auto_top_up_account_id', v_auto_top_up_account_id,
      'stripe_customer_id', v_stripe_customer_id,
      'new_balance_nanos', v_new_balance
    );
  end if;
  return json_build_object('status', 'top_up_not_required', 'new_balance_nanos', v_new_balance);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."deduct_and_check_top_up"(uuid, bigint) TO "service_role";

REVOKE ALL ON FUNCTION "public"."deduct_and_check_top_up"(uuid, bigint) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/default_workspace_publisher_handle.sql
CREATE OR REPLACE FUNCTION public.default_workspace_publisher_handle()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
begin
  if nullif(new.publisher_handle, '') is null then
    new.publisher_handle := lower(regexp_replace(regexp_replace(coalesce(nullif(new.slug, ''), new.name), '[^a-zA-Z0-9_-]+', '-', 'g'), '^-+|-+$', '', 'g'));

    if length(new.publisher_handle) < 3 then
      new.publisher_handle := 'workspace-' || left(new.id::text, 8);
    end if;

    new.publisher_handle := left(new.publisher_handle, 40);
  end if;

  return new;
end
$function$;

GRANT EXECUTE ON FUNCTION "public"."default_workspace_publisher_handle"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."default_workspace_publisher_handle"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/delete_slack_agent_memory.sql
CREATE OR REPLACE FUNCTION public.delete_slack_agent_memory()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  -- Uninstalling, from Phaseo settings (web-api) or in Slack
  -- (uninstall_slack_agent_from_slack), deletes what the agent kept: its notes,
  -- pins and to-dos and its saved skills. As a trigger it runs in the transaction
  -- that marks the installation uninstalled, so neither path can leave them
  -- behind, and the save functions, which lock the installation row, wait for it.
  delete from public.slack_agent_notes note where note.installation_id = new.id;
  delete from public.slack_agent_skills skill where skill.installation_id = new.id;
  return new;
end;
$function$;

COMMENT ON FUNCTION "public"."delete_slack_agent_memory"() IS 'Deletes a Slack agent installation''s notes and saved skills when it is marked uninstalled, whichever path uninstalls it.';

REVOKE ALL ON FUNCTION "public"."delete_slack_agent_memory"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/delete_slack_agent_schedules.sql
CREATE OR REPLACE FUNCTION public.delete_slack_agent_schedules()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  -- Uninstalling, from Phaseo settings (web-api) or in Slack
  -- (uninstall_slack_agent_from_slack), deletes the installation's recurring
  -- tasks in the transaction that marks it uninstalled, like its memory
  -- (delete_slack_agent_memory). save_slack_agent_schedule locks the installation
  -- row, so a schedule being saved waits for this and then finds no installation.
  delete from public.slack_agent_schedules schedule where schedule.installation_id = new.id;
  return new;
end;
$function$;

COMMENT ON FUNCTION "public"."delete_slack_agent_schedules"() IS 'Deletes a Slack agent installation''s recurring tasks when it is marked uninstalled, whichever path uninstalls it.';

REVOKE ALL ON FUNCTION "public"."delete_slack_agent_schedules"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enforce_broadcast_destination_limit.sql
CREATE OR REPLACE FUNCTION public.enforce_broadcast_destination_limit()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_limit integer;
  v_existing integer;
begin
  if tg_op = 'UPDATE'
    and new.workspace_id is not distinct from old.workspace_id
    and new.destination_id is not distinct from old.destination_id then
    return new;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('broadcast_destination:' || new.workspace_id::text || ':' || new.destination_id, 0)
  );

  -- Definer rights let this read the operator-only override table when an admin
  -- inserts through RLS.
  select coalesce((
    select override.max_destinations_per_type
    from public.workspace_broadcast_destination_limits override
    where override.workspace_id = new.workspace_id
  ), 5) into v_limit;

  select count(*) into v_existing
  from public.workspace_broadcast_destinations destination
  where destination.workspace_id = new.workspace_id
    and destination.destination_id = new.destination_id
    and destination.id <> new.id;

  if v_existing >= v_limit then
    raise exception 'broadcast_destination_limit_reached'
      using errcode = '23514',
        detail = pg_catalog.format('A workspace may have %s %s destinations.', v_limit, new.destination_id);
  end if;

  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."enforce_broadcast_destination_limit"() TO "service_role";

COMMENT ON FUNCTION "public"."enforce_broadcast_destination_limit"() IS 'Caps Broadcast destinations per workspace and type (default 5, overridable in workspace_broadcast_destination_limits) using a transaction-scoped advisory lock.';

REVOKE ALL ON FUNCTION "public"."enforce_broadcast_destination_limit"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enforce_byok_key_provider_limit.sql
CREATE OR REPLACE FUNCTION public.enforce_byok_key_provider_limit()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  existing_provider_count integer;
  existing_mode_count integer;
  excluded_key_id uuid;
begin
  if tg_op = 'UPDATE'
    and new.workspace_id is not distinct from old.workspace_id
    and new.provider_id is not distinct from old.provider_id
    and new.routing_mode is not distinct from old.routing_mode then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    excluded_key_id := old.id;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.workspace_id::text || ':' || new.provider_id, 0)
  );

  select
    count(*),
    count(*) filter (where routing_mode = new.routing_mode)
  into existing_provider_count, existing_mode_count
  from public.byok_keys
  where workspace_id = new.workspace_id
    and provider_id = new.provider_id
    and (excluded_key_id is null or id <> excluded_key_id);

  if existing_provider_count >= 32 then
    raise exception 'BYOK key limit reached for workspace provider'
      using errcode = '23514';
  end if;
  if existing_mode_count >= 16 then
    raise exception 'BYOK key routing-mode limit reached for workspace provider'
      using errcode = '23514';
  end if;

  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."enforce_byok_key_provider_limit"() TO "service_role";

COMMENT ON FUNCTION "public"."enforce_byok_key_provider_limit"() IS 'Caps stored BYOK credentials at 32 per workspace/provider using a transaction-scoped advisory lock.';

REVOKE ALL ON FUNCTION "public"."enforce_byok_key_provider_limit"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enforce_canonical_routing_capability.sql
create or replace function public.enforce_canonical_routing_capability()
returns trigger language plpgsql security invoker
set search_path = pg_catalog, public
as $$
declare canonical text;
begin
  if tg_table_name = 'v2_route_capabilities' and tg_op = 'UPDATE' then
    if old.status = 'disabled' and old.effective_to is not null and old.effective_to <= now()
      and old.capability_id is distinct from public.canonical_routing_capability_id(old.capability_id)
    then
      if to_jsonb(new) is distinct from to_jsonb(old) then
        raise exception 'Historical capability aliases cannot be changed' using errcode='23514';
      end if;
      return new;
    end if;
  end if;
  canonical := public.canonical_routing_capability_id(new.capability_id);
  if canonical is null then raise exception 'Unsupported routing capability: %',new.capability_id using errcode='23514'; end if;
  new.capability_id := canonical;
  return new;
end $$;

GRANT EXECUTE ON FUNCTION "public"."enforce_canonical_routing_capability"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."enforce_canonical_routing_capability"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enforce_oauth_device_poll_interval.sql
CREATE OR REPLACE FUNCTION public.enforce_oauth_device_poll_interval (
  p_device_id uuid
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  device public.oauth_device_codes%rowtype;
begin
  select * into device
  from public.oauth_device_codes
  where id = p_device_id
  for update;

  if not found then return 'invalid'; end if;

  if device.last_polled_at is not null
     and device.last_polled_at + make_interval(secs => device.interval_seconds) > now() then
    update public.oauth_device_codes
    set last_polled_at = now(), interval_seconds = interval_seconds + 5
    where id = p_device_id;
    return 'slow_down';
  end if;

  update public.oauth_device_codes set last_polled_at = now() where id = p_device_id;
  return 'ok';
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."enforce_oauth_device_poll_interval"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."enforce_oauth_device_poll_interval"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enforce_provider_catalog_source_owner_limit.sql
CREATE OR REPLACE FUNCTION public.enforce_provider_catalog_source_owner_limit()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if new.created_by is null then
    return new;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(new.created_by::text, 918273));
  if (
    select count(*)
    from public.provider_catalog_sources source
    where source.created_by = new.created_by
  ) >= 5 then
    raise exception using
      errcode = '23514',
      message = 'provider_catalog_source_owner_limit';
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."enforce_provider_catalog_source_owner_limit"() FROM PUBLIC, "anon", "authenticated", "service_role";

