-- source: supabase/schemas/public/functions/enforce_workspace_join_request_write_rules.sql
CREATE OR REPLACE FUNCTION public.enforce_workspace_join_request_write_rules()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  if new.invite_id is not null then
    if not exists (
      select 1
      from public.team_invites ti
      where ti.id = new.invite_id
        and ti.team_id = new.team_id
    ) then
      raise exception using
        errcode = '23514',
        message = 'invite_team_mismatch',
        detail = 'Join request invite must belong to the same team.';
    end if;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'pending'::join_request_status
       or new.decided_by is not null
       or new.decided_at is not null then
      raise exception using
        errcode = '23514',
        message = 'invalid_join_request_insert_state',
        detail = 'New join requests must be pending and undecided.';
    end if;
    return new;
  end if;

  -- UPDATE path
  if old.status <> 'pending'::join_request_status then
    raise exception using
      errcode = '23514',
      message = 'join_request_already_decided',
      detail = 'Only pending join requests can be updated.';
  end if;

  if new.status not in ('approved'::join_request_status, 'denied'::join_request_status) then
    raise exception using
      errcode = '23514',
      message = 'invalid_join_request_status_transition',
      detail = 'Join request updates must transition to approved or denied.';
  end if;

  if new.decided_by is null or new.decided_at is null then
    raise exception using
      errcode = '23514',
      message = 'join_request_decision_metadata_required',
      detail = 'Decided join requests must include decided_by and decided_at.';
  end if;

  if new.team_id <> old.team_id or new.requester_user_id <> old.requester_user_id then
    raise exception using
      errcode = '23514',
      message = 'join_request_immutable_fields_modified',
      detail = 'team_id and requester_user_id are immutable.';
  end if;

  if new.invite_id is distinct from old.invite_id then
    raise exception using
      errcode = '23514',
      message = 'join_request_invite_immutable',
      detail = 'invite_id is immutable after request creation.';
  end if;

  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."enforce_workspace_join_request_write_rules"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."enforce_workspace_join_request_write_rules"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enforce_workspace_member_role_policy.sql
CREATE OR REPLACE FUNCTION public.enforce_workspace_member_role_policy()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_owner_user_id uuid;
begin
  select w.owner_user_id
    into v_owner_user_id
  from public.workspaces w
  where w.id = new.workspace_id;

  if v_owner_user_id is null then
    raise exception using
      errcode = '23514',
      message = 'workspace_not_found_for_membership';
  end if;

  if new.user_id = v_owner_user_id then
    new.role := 'owner'::public.workspace_role;
    return new;
  end if;

  if lower(coalesce(new.role::text, '')) = 'owner' then
    raise exception using
      errcode = '23514',
      message = 'owner_role_reserved_for_workspace_owner',
      detail = 'Only workspaces.owner_user_id may have role=owner.';
  end if;

  if lower(coalesce(new.role::text, '')) not in ('admin', 'member') then
    raise exception using
      errcode = '23514',
      message = 'invalid_workspace_member_role',
      detail = 'Assignable roles are admin and member.';
  end if;

  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."enforce_workspace_member_role_policy"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."enforce_workspace_member_role_policy"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enforce_workspace_spend_rule_limit.sql
CREATE OR REPLACE FUNCTION public.enforce_workspace_spend_rule_limit()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_limit constant integer := 50;
  v_existing integer;
begin
  -- Only rules that become live count: inserts, restores and moves. Deleting never blocks.
  if new.deleted_at is not null then
    return new;
  end if;
  if tg_op = 'UPDATE'
    and old.deleted_at is null
    and new.workspace_id is not distinct from old.workspace_id then
    return new;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('workspace_spend_rules:' || new.workspace_id::text, 0)
  );

  select count(*) into v_existing
  from public.workspace_spend_rules rule
  where rule.workspace_id = new.workspace_id
    and rule.deleted_at is null
    and rule.id <> new.id;

  if v_existing >= v_limit then
    raise exception 'spend_rule_limit_reached'
      using errcode = '23514',
        detail = pg_catalog.format('A workspace may have %s spend rules.', v_limit);
  end if;

  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."enforce_workspace_spend_rule_limit"() TO "service_role";

COMMENT ON FUNCTION "public"."enforce_workspace_spend_rule_limit"() IS 'Caps each workspace at 50 non-deleted spend rules (an abuse cap, the same on every plan), using a transaction-scoped advisory lock per workspace.';

REVOKE ALL ON FUNCTION "public"."enforce_workspace_spend_rule_limit"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enqueue_broadcast_destination_alerts.sql
CREATE OR REPLACE FUNCTION public.enqueue_broadcast_destination_alerts ()
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  SET statement_timeout TO '10s'
  SET lock_timeout TO '2s'
  AS $function$
declare
  -- A destination is failing once this many export requests in a row have
  -- failed and nothing has been delivered for the quiet period.
  v_min_failures constant integer := 5;
  v_quiet constant interval := interval '15 minutes';
  v_realert constant interval := interval '6 hours';
  v_inserted integer := 0;
begin
  if not pg_try_advisory_xact_lock(hashtextextended('enqueue_broadcast_destination_alerts', 0)) then
    return 0;
  end if;

  -- Only workspaces that routed this alert to an active destination are alerted,
  -- at most once per hour each. A destination is included once per failing
  -- streak: again only after a later success and at least six hours. The routed
  -- delivery job sends the event.
  --
  -- The quiet period runs from the last success, or from creation for a
  -- destination that has never delivered. Candidate health rows are locked, so a
  -- success recorded concurrently is waited for and the row rechecked rather than
  -- marked alerted from a stale read.
  with routed as (
    select distinct route.workspace_id
    from public.notification_event_destinations route
    join public.notification_destinations destination on destination.id = route.destination_id
    where route.event_kind = 'broadcast_destination_failing'
      and destination.status = 'active'
  ),
  candidates as (
    select
      health.destination_id,
      health.workspace_id,
      destination.name,
      destination.destination_id as destination_type,
      health.consecutive_failures,
      health.last_http_status,
      health.last_error,
      health.last_success_at,
      health.last_failure_at
    from public.broadcast_destination_health health
    join routed on routed.workspace_id = health.workspace_id
    join public.workspace_broadcast_destinations destination on destination.id = health.destination_id
    where destination.enabled
      and health.consecutive_failures >= v_min_failures
      and health.last_failure_at > now() - interval '24 hours'
      and coalesce(health.last_success_at, destination.created_at) < now() - v_quiet
      and (
        health.alerted_at is null
        or (health.alerted_at < health.last_success_at and health.alerted_at < now() - v_realert)
      )
    for update of health
  ),
  ranked as (
    select
      candidates.*,
      row_number() over (partition by candidates.workspace_id order by candidates.consecutive_failures desc, candidates.destination_id) as position
    from candidates
  ),
  summary as (
    select
      ranked.workspace_id,
      count(*)::integer as failing_destinations,
      jsonb_agg(
        jsonb_build_object(
          'destination_id', ranked.destination_id,
          'name', ranked.name,
          'destination_type', ranked.destination_type,
          'consecutive_failures', ranked.consecutive_failures,
          'last_http_status', ranked.last_http_status,
          'last_error', ranked.last_error,
          'last_success_at', ranked.last_success_at,
          'last_failure_at', ranked.last_failure_at
        )
        order by ranked.position
      ) filter (where ranked.position <= 5) as destinations
    from ranked
    group by ranked.workspace_id
  ),
  inserted as (
    insert into public.email_outbox (kind, template, to_email, subject, workspace_id, user_id, payload, dedupe_key)
    select
      'broadcast_destination_failing',
      'broadcast_destination_failing',
      coalesce(owner.email, ''),
      'Broadcast destination failing',
      summary.workspace_id,
      workspace.owner_user_id,
      jsonb_build_object(
        'workspace_name', workspace.name,
        'failing_destinations', summary.failing_destinations,
        'destinations', summary.destinations
      ),
      'broadcast_destination_failing:' || summary.workspace_id || ':' || to_char(date_trunc('hour', now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24')
    from summary
    join public.workspaces workspace on workspace.id = summary.workspace_id
    left join auth.users owner on owner.id = workspace.owner_user_id
    where not exists (
      select 1
      from public.email_outbox previous
      where previous.workspace_id = summary.workspace_id
        and previous.kind = 'broadcast_destination_failing'
        and previous.created_at > now() - interval '1 hour'
    )
    on conflict (dedupe_key) do nothing
    returning workspace_id
  ),
  marked as (
    update public.broadcast_destination_health health
    set alerted_at = now()
    from candidates
    where candidates.destination_id = health.destination_id
      and candidates.workspace_id in (select inserted.workspace_id from inserted)
    returning health.destination_id
  )
  select count(*) into v_inserted from inserted;

  return v_inserted;
end;
$function$;

COMMENT ON FUNCTION "public"."enqueue_broadcast_destination_alerts"() IS 'Queues one broadcast_destination_failing notification event per routed workspace whose enabled Broadcast destinations have failed at least five requests in a row with nothing delivered for 15 minutes, at most once per hour.';

GRANT EXECUTE ON FUNCTION "public"."enqueue_broadcast_destination_alerts"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."enqueue_broadcast_destination_alerts"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enqueue_feedback_request_emails.sql
CREATE OR REPLACE FUNCTION public.enqueue_feedback_request_emails (
  p_campaign              text,
  p_min_account_age_days  integer,
  p_limit                 integer,
  p_reward_cap            integer
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Queues at most p_limit feedback emails, oldest accounts first, for users who signed
-- up at least p_min_account_age_days ago and have not been asked in this campaign.
-- The segment picks the email's question and the recency its opening line, and
-- reward_available drops the thank-you offer once the campaign's codes run out.
declare
  v_queued integer;
  v_reward_available boolean;
begin
  if p_limit is null or p_limit <= 0 then
    return 0;
  end if;

  select coalesce(p_reward_cap, 0) > count(*) into v_reward_available
  from public.credit_grants
  where note = 'Feedback thank-you (' || p_campaign || ')';

  with candidates as (
    select
      a.id as user_id,
      lower(trim(a.email)) as email,
      a.last_sign_in_at,
      nullif(split_part(trim(coalesce(
        nullif(trim(u.display_name), ''),
        a.raw_user_meta_data ->> 'full_name',
        a.raw_user_meta_data ->> 'name',
        ''
      )), ' ', 1), '') as first_name
    from public.users u
    join auth.users a on a.id = u.user_id
    where a.created_at <= now() - make_interval(days => greatest(coalesce(p_min_account_age_days, 0), 0))
      and nullif(trim(a.email), '') is not null
      and a.deleted_at is null
      and not coalesce(a.is_anonymous, false)
      and u.role::text <> 'admin'
      and u.product_emails_opted_out_at is null
      and not exists (
        select 1 from public.feedback_requests r
        where r.user_id = a.id and r.campaign = p_campaign
      )
    order by a.created_at asc
    limit p_limit
  ),
  segmented as (
    select
      c.*,
      case
        when exists (
          select 1
          from public.workspace_members wm
          join public.credit_ledger cl on cl.workspace_id = wm.workspace_id
          where wm.user_id = c.user_id and cl.ref_type = 'Stripe_Payment_Intent'
        ) then 'paid'
        when exists (
          select 1
          from public.workspace_members wm
          join public.v2_private_usage_daily d on d.workspace_id = wm.workspace_id
          where wm.user_id = c.user_id
        ) or exists (
          select 1
          from public.workspace_members wm
          join public.gateway_requests g on g.workspace_id = wm.workspace_id
          where wm.user_id = c.user_id
        ) then 'used_not_paid'
        else 'never_requested'
      end as segment,
      case
        when c.last_sign_in_at >= now() - interval '30 days' then 'active'
        when c.last_sign_in_at >= now() - interval '180 days' then 'lapsed'
        else 'dormant'
      end as recency
    from candidates c
  ),
  requested as (
    insert into public.feedback_requests (user_id, campaign, segment, recency)
    select s.user_id, p_campaign, s.segment, s.recency
    from segmented s
    on conflict (user_id, campaign) do nothing
    returning user_id, access_token, segment, recency
  ),
  queued as (
    insert into public.email_outbox (kind, template, to_email, user_id, payload, dedupe_key)
    select
      'feedback_request',
      'feedback_request',
      s.email,
      r.user_id,
      jsonb_build_object(
        'campaign', p_campaign,
        'token', r.access_token,
        'segment', r.segment,
        'recency', r.recency,
        'first_name', s.first_name,
        'reward_available', v_reward_available
      ),
      'feedback_request:' || p_campaign || ':' || r.user_id
    from requested r
    join segmented s on s.user_id = r.user_id
    on conflict (dedupe_key) do nothing
    returning 1
  )
  select count(*)::integer into v_queued from queued;

  return v_queued;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."enqueue_feedback_request_emails"(text, integer, integer, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."enqueue_feedback_request_emails"(text, integer, integer, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enqueue_gateway_async_webhook_delivery.sql
CREATE OR REPLACE FUNCTION public.enqueue_gateway_async_webhook_delivery (
  p_workspace_id    uuid,
  p_kind            text,
  p_internal_id     text,
  p_delivery_key    text,
  p_event_type      text,
  p_phase           text,
  p_progress        double precision DEFAULT NULL::double precision,
  p_previous_status text             DEFAULT NULL::text,
  p_current_status  text             DEFAULT NULL::text
)
  RETURNS void
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  insert into public.gateway_async_webhook_deliveries (
    workspace_id, kind, internal_id, delivery_key, status,
    event_type, phase, progress, previous_status, current_status,
    next_attempt_at, updated_at
  ) values (
    p_workspace_id, p_kind, p_internal_id, p_delivery_key, 'pending',
    p_event_type, p_phase, p_progress, p_previous_status, p_current_status,
    now(), now()
  ) on conflict (workspace_id, kind, internal_id, delivery_key) do nothing;
$function$;

GRANT EXECUTE ON FUNCTION "public"."enqueue_gateway_async_webhook_delivery"(uuid, text, text, text, text, text, double precision, text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."enqueue_gateway_async_webhook_delivery"(uuid, text, text, text, text, text, double precision, text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enqueue_gateway_routing_archive_deletion.sql
CREATE OR REPLACE FUNCTION public.enqueue_gateway_routing_archive_deletion()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $function$
begin
  -- Queue even when no reference exists yet: an upload may be in flight when
  -- retention deletes the source. The prefix includes all immutable revisions.
  insert into public.gateway_routing_archive_deletions(object_prefix) values(
    'workspaces/' || old.workspace_id::text || '/routing/v1/' ||
    encode(sha256(convert_to(old.request_id, 'UTF8')), 'hex') || '/'
  ) on conflict (object_prefix) do nothing;
  return old;
end;
$function$;

REVOKE ALL ON FUNCTION public.enqueue_gateway_routing_archive_deletion() FROM PUBLIC, anon, authenticated;

-- source: supabase/schemas/public/functions/enqueue_mobile_push_deliveries.sql
CREATE OR REPLACE FUNCTION public.enqueue_mobile_push_deliveries (
  p_event_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Fans one catalogue event out to the active devices of users who switched push and the
-- event's category on, in a single statement. A device gets the event when one of its user's
-- enabled notify rules matches and none of their enabled mute rules does. Each push waits five
-- minutes after its event to settle, so claim_mobile_push_deliveries can send a burst for the
-- same device and group key as one push; if that moment falls in the user's quiet hours (in
-- the device's time zone) it is deferred until they end. Past the daily cap, counted per device
-- over catalogue pushes only (never digests or other pushes without an event) and with a
-- grouped push counting once, it is recorded as suppressed; a push that joins a group
-- already waiting for the device adds nothing to the count. A device already told about a
-- model's release is not told again that the same model reached Phaseo, and vice versa. Events
-- more than two days old or about a model that is no longer public are closed without sending.
declare
  v_event public.catalogue_notification_events%rowtype;
  v_category text;
  v_group_key text;
  v_result jsonb;
begin
  select * into v_event from public.catalogue_notification_events e where e.id = p_event_id for update;
  if v_event.id is null or v_event.fanned_out_at is not null then
    return jsonb_build_object('queued', 0, 'deferred', 0, 'suppressed', 0);
  end if;

  v_category := private.mobile_push_category(v_event.kind);
  v_group_key := private.mobile_push_group_key(v_event.kind, v_event.lab_slug, v_event.provider_slug, v_event.model_slug);

  if v_event.occurred_at > now() - interval '2 days'
    and (v_event.model_slug is null or public.catalog_model_is_public(v_event.model_slug)) then
    with model as (
      select
        m.input_modalities,
        m.output_modalities,
        v_event.kind = 'provider_launched' or exists (
          select 1 from public.v2_model_provider_routes r
          where r.model_slug = m.model_slug and r.routing_enabled and r.access_scope = 'public'
            and not r.is_stealth and r.status in ('active', 'degraded')
        ) as on_phaseo
      from (select 1) one
      left join public.v2_models m on m.model_slug = v_event.model_slug
    ),
    candidates as (
      select
        d.id as device_id,
        d.user_id,
        coalesce(d.time_zone, 'UTC') as time_zone,
        p.quiet_start,
        p.quiet_end,
        p.daily_cap,
        (
          select r.id from public.mobile_notification_rules r
          where r.user_id = p.user_id and r.action = 'notify'
            and private.mobile_notification_rule_matches(r, v_event.kind, v_event.lab_slug, v_event.provider_slug,
              v_event.model_slug, model.input_modalities, model.output_modalities, model.on_phaseo)
          order by r."position", r.created_at, r.id
          limit 1
        ) as rule_id
      from public.mobile_notification_preferences p
      join public.mobile_push_devices d on d.user_id = p.user_id and d.status = 'active'
      cross join model
      where p.enabled
        and (p.categories -> v_category) is distinct from 'false'::jsonb
        and not exists (
          select 1 from public.mobile_notification_rules r
          where r.user_id = p.user_id and r.action = 'mute'
            and private.mobile_notification_rule_matches(r, v_event.kind, v_event.lab_slug, v_event.provider_slug,
              v_event.model_slug, model.input_modalities, model.output_modalities, model.on_phaseo)
        )
        and not (
          v_event.kind in ('model_released', 'gateway_available')
          and exists (
            select 1
            from public.mobile_push_deliveries x
            join public.catalogue_notification_events e on e.id = x.event_id
            where x.device_id = d.id and x.created_at > now() - interval '1 day' and x.status <> 'failed'
              and e.model_slug = v_event.model_slug and e.kind in ('model_released', 'gateway_available')
          )
        )
    ),
    scheduled as (
      select
        c.*,
        sent.recent,
        sent.joins_group,
        settle.at as settle_at,
        case
          when c.quiet_start is null or c.quiet_end is null or c.quiet_start = c.quiet_end then null
          when c.quiet_start < c.quiet_end then
            case when wall.clock_time >= c.quiet_start and wall.clock_time < c.quiet_end then wall.calendar_day + c.quiet_end end
          when wall.clock_time >= c.quiet_start then (wall.calendar_day + 1) + c.quiet_end
          when wall.clock_time < c.quiet_end then wall.calendar_day + c.quiet_end
        end as release_local
      from candidates c
      cross join lateral (select greatest(now(), v_event.occurred_at + interval '5 minutes') as at) settle
      cross join lateral (select settle.at at time zone c.time_zone as moment) here
      cross join lateral (select here.moment::time as clock_time, here.moment::date as calendar_day) wall
      cross join lateral (
        -- Pushes this device was sent or is due in the last day: a group still waiting counts
        -- once, as does a push that carried several deliveries.
        select
          count(distinct case
            when x.status in ('pending', 'deferred') and x.group_key is not null then 'group:' || x.group_key
            else coalesce(x.merged_into, x.id)::text
          end) as recent,
          coalesce(bool_or(x.status in ('pending', 'deferred') and x.group_key = v_group_key), false) as joins_group
        from public.mobile_push_deliveries x
        where x.device_id = c.device_id and x.created_at > now() - interval '1 day'
          and x.status in ('pending', 'processing', 'sent', 'deferred') and x.event_id is not null
      ) sent
      where c.rule_id is not null
    ),
    inserted as (
      insert into public.mobile_push_deliveries as x (event_id, device_id, user_id, rule_id, group_key, status, not_before, error_code)
      select
        v_event.id,
        s.device_id,
        s.user_id,
        s.rule_id,
        v_group_key,
        case when s.capped then 'suppressed' when s.release_local is not null then 'deferred' else 'pending' end,
        case
          when s.capped then now()
          when s.release_local is not null then s.release_local at time zone s.time_zone
          else s.settle_at
        end,
        case when s.capped then 'daily_cap' end
      from (select s.*, not s.joins_group and s.recent >= s.daily_cap as capped from scheduled s) s
      on conflict (event_id, device_id) do nothing
      returning x.status
    )
    select jsonb_build_object(
      'queued', count(*) filter (where i.status = 'pending'),
      'deferred', count(*) filter (where i.status = 'deferred'),
      'suppressed', count(*) filter (where i.status = 'suppressed')
    ) into v_result
    from inserted i;
  end if;

  update public.catalogue_notification_events set fanned_out_at = now() where id = v_event.id;
  return coalesce(v_result, jsonb_build_object('queued', 0, 'deferred', 0, 'suppressed', 0));
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."enqueue_mobile_push_deliveries"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."enqueue_mobile_push_deliveries"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enqueue_notification_event_deliveries.sql
CREATE OR REPLACE FUNCTION public.enqueue_notification_event_deliveries (
  p_event_id                 uuid,
  p_workspace_id             uuid,
  p_event_kind               text,
  p_requested_destination_id uuid DEFAULT NULL::uuid
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  claimed_event_id uuid;
  inserted_count integer := 0;
  spend_rule_id uuid;
begin
  insert into public.notification_routed_events (event_id, workspace_id)
  values (p_event_id, p_workspace_id)
  on conflict (event_id) do nothing
  returning event_id into claimed_event_id;

  if claimed_event_id is null then
    return 0;
  end if;

  if p_event_kind = 'notification_test' and p_requested_destination_id is not null then
    insert into public.notification_delivery_attempts (event_id, destination_id, workspace_id, status)
    select p_event_id, destination.id, p_workspace_id, 'pending'
    from public.notification_destinations destination
    where destination.id = p_requested_destination_id
      and destination.workspace_id = p_workspace_id
      and destination.status = 'active'
    on conflict (event_id, destination_id) do nothing;
    get diagnostics inserted_count = row_count;
    return inserted_count;
  end if;

  -- A spend rule with destinations of its own sends there instead of the workspace's routes for
  -- the kind (active destinations only); a rule without any uses the routes.
  if p_event_kind in ('spend_alert', 'spend_blocked') then
    select rule.id into spend_rule_id
    from public.email_outbox event
    join public.workspace_spend_rules rule
      on rule.workspace_id = p_workspace_id
      and rule.id = case when event.payload ->> 'rule_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then (event.payload ->> 'rule_id')::uuid end
    where event.id = p_event_id
      and exists (
        select 1 from public.workspace_spend_rule_destinations rule_destination
        where rule_destination.rule_id = rule.id and rule_destination.workspace_id = p_workspace_id
      );
  end if;

  if spend_rule_id is not null then
    insert into public.notification_delivery_attempts (event_id, destination_id, workspace_id, status)
    select p_event_id, rule_destination.destination_id, p_workspace_id, 'pending'
    from public.workspace_spend_rule_destinations rule_destination
    join public.notification_destinations destination on destination.id = rule_destination.destination_id
    where rule_destination.rule_id = spend_rule_id
      and rule_destination.workspace_id = p_workspace_id
      and destination.status = 'active'
    on conflict (event_id, destination_id) do nothing;
  else
    insert into public.notification_delivery_attempts (event_id, destination_id, workspace_id, status)
    select p_event_id, route.destination_id, p_workspace_id, 'pending'
    from public.notification_event_destinations route
    join public.notification_destinations destination on destination.id = route.destination_id
    where route.workspace_id = p_workspace_id
      and route.event_kind = p_event_kind
      and destination.status = 'active'
    on conflict (event_id, destination_id) do nothing;
  end if;

  get diagnostics inserted_count = row_count;
  return inserted_count;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."enqueue_notification_event_deliveries"(uuid, uuid, text, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."enqueue_notification_event_deliveries"(uuid, uuid, text, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enqueue_provider_catalog_event_email.sql
CREATE OR REPLACE FUNCTION public.enqueue_provider_catalog_event_email()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if new.workspace_id is null then return new; end if;
  insert into public.email_outbox (kind, template, to_email, subject, workspace_id, user_id, payload)
  select
    new.event_type, 'generic', a.email, new.title, new.workspace_id, u.user_id,
    jsonb_build_object('message', new.message, 'provider_slug', new.provider_slug, 'run_id', new.run_id)
  from public.workspace_members wm
  join public.users u on u.user_id = wm.user_id
  join auth.users a on a.id = u.user_id
  where wm.workspace_id = new.workspace_id and nullif(trim(a.email), '') is not null;
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."enqueue_provider_catalog_event_email"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."enqueue_provider_catalog_event_email"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/enqueue_rate_limit_throttle_alerts.sql
CREATE OR REPLACE FUNCTION public.enqueue_rate_limit_throttle_alerts ()
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  SET statement_timeout TO '10s'
  SET lock_timeout TO '2s'
  AS $function$
declare
  v_window_minutes constant integer := 15;
  v_to timestamptz := date_trunc('minute', now());
  v_from timestamptz := date_trunc('minute', now()) - make_interval(mins => v_window_minutes);
  v_inserted integer := 0;
begin
  if not pg_try_advisory_xact_lock(hashtextextended('enqueue_rate_limit_throttle_alerts', 0)) then
    return 0;
  end if;

  -- Only workspaces that routed this alert to an active destination are alerted,
  -- at most once per hour each. The routed delivery job sends the event.
  with routed as (
    select distinct route.workspace_id
    from public.notification_event_destinations route
    join public.notification_destinations destination on destination.id = route.destination_id
    where route.event_kind = 'rate_limit_throttled'
      and destination.status = 'active'
  ),
  throttles as (
    select
      throttle.workspace_id,
      throttle.policy_id,
      throttle.limit_scope,
      sum(throttle.throttled_requests)::bigint as throttled_requests
    from public.workspace_rate_limit_throttles_minute throttle
    join routed on routed.workspace_id = throttle.workspace_id
    where throttle.bucket_start >= v_from
    group by throttle.workspace_id, throttle.policy_id, throttle.limit_scope
  ),
  ranked as (
    select
      throttles.*,
      row_number() over (partition by throttles.workspace_id order by throttles.throttled_requests desc, throttles.policy_id, throttles.limit_scope) as position
    from throttles
  ),
  summary as (
    select
      ranked.workspace_id,
      sum(ranked.throttled_requests)::bigint as throttled_requests,
      jsonb_agg(
        jsonb_build_object(
          'policy_id', ranked.policy_id,
          'policy_name', policy.name,
          'limit_scope', ranked.limit_scope,
          'throttled_requests', ranked.throttled_requests
        )
        order by ranked.position
      ) filter (where ranked.position <= 5) as policies
    from ranked
    left join public.workspace_rate_limit_policies policy on policy.id = ranked.policy_id
    group by ranked.workspace_id
  )
  insert into public.email_outbox (kind, template, to_email, subject, workspace_id, user_id, payload, dedupe_key)
  select
    'rate_limit_throttled',
    'rate_limit_throttled',
    coalesce(owner.email, ''),
    'Rate limit alert',
    summary.workspace_id,
    workspace.owner_user_id,
    jsonb_build_object(
      'workspace_name', workspace.name,
      'throttled_requests', summary.throttled_requests,
      'window_minutes', v_window_minutes,
      'window_start', v_from,
      'window_end', v_to,
      'policies', summary.policies
    ),
    'rate_limit_throttled:' || summary.workspace_id || ':' || to_char(date_trunc('hour', now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24')
  from summary
  join public.workspaces workspace on workspace.id = summary.workspace_id
  left join auth.users owner on owner.id = workspace.owner_user_id
  where not exists (
    select 1
    from public.email_outbox previous
    where previous.workspace_id = summary.workspace_id
      and previous.kind = 'rate_limit_throttled'
      and previous.created_at > now() - interval '1 hour'
  )
  on conflict (dedupe_key) do nothing;

  get diagnostics v_inserted = row_count;
  return v_inserted;
end;
$function$;

COMMENT ON FUNCTION "public"."enqueue_rate_limit_throttle_alerts"() IS 'Queues one rate_limit_throttled notification event per routed workspace with policy throttles in the last 15 minutes, at most once per hour.';

GRANT EXECUTE ON FUNCTION "public"."enqueue_rate_limit_throttle_alerts"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."enqueue_rate_limit_throttle_alerts"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/ensure_gateway_requests_partitions.sql
CREATE OR REPLACE FUNCTION public.ensure_gateway_requests_partitions (
  months_ahead integer DEFAULT 1
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
DECLARE
  v_cur_month timestamptz;
  v_last_month timestamptz;
  v_partition_name text;
  v_parent_name text;
BEGIN
  IF months_ahead IS NULL OR months_ahead < 0 THEN
    RAISE EXCEPTION 'months_ahead must be >= 0';
  END IF;
  v_cur_month := date_trunc('month', now());
  v_last_month := v_cur_month + make_interval(months => months_ahead);
  WHILE v_cur_month <= v_last_month LOOP
    FOREACH v_parent_name IN ARRAY ARRAY['gateway_requests', 'gateway_upstream_requests'] LOOP
      v_partition_name := format('%s_%s', v_parent_name, to_char(v_cur_month, 'YYYY_MM'));
      EXECUTE format(
        'CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.%I FOR VALUES FROM (%L) TO (%L)',
        v_partition_name, v_parent_name, v_cur_month, v_cur_month + interval '1 month'
      );
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', v_partition_name);
      IF NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_policy
        WHERE polrelid = to_regclass(format('public.%I', v_partition_name))
          AND polname = 'deny_direct_client_access'
      ) THEN
        EXECUTE format(
          'CREATE POLICY deny_direct_client_access ON public.%I AS RESTRICTIVE FOR ALL TO anon, authenticated USING (false) WITH CHECK (false)',
          v_partition_name
        );
      END IF;
    END LOOP;
    v_cur_month := v_cur_month + interval '1 month';
  END LOOP;
END;
$function$;

GRANT EXECUTE ON FUNCTION "public"."ensure_gateway_requests_partitions"(integer) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."ensure_gateway_requests_partitions"(integer) TO "service_role";

COMMENT ON FUNCTION "public"."ensure_gateway_requests_partitions"(integer) IS 'Maintains physical legacy operational partitions while V2 dual-write remains enabled; not an analytical read path.';

