-- source: supabase/schemas/public/functions/gateway_catalogue_source.sql
CREATE OR REPLACE FUNCTION public.gateway_catalogue_source()
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
with selected_routes as materialized (
 select * from public.v2_model_provider_routes
 where is_stealth is true or (access_scope='public' and routing_enabled is true
   and status in ('active','degraded') and (effective_to is null or effective_to>statement_timestamp()))
), selected_skus as materialized (
 select s.* from public.v2_pricing_skus s join selected_routes r using(provider_model_id)
 where s.status in ('active','degraded') and (s.effective_to is null or s.effective_to>statement_timestamp())
), projected as materialized (
 select 'models' as kind,private.project_routing_catalogue_row(to_jsonb(t)) as row from public.v2_models t
 union all select 'providers',private.project_routing_catalogue_row(to_jsonb(t)) from public.v2_providers t
 union all select 'routes',private.project_routing_catalogue_row(to_jsonb(t)) from selected_routes t
 union all select 'capabilities',private.project_routing_catalogue_row(to_jsonb(t)) from public.v2_route_capabilities t where exists(select 1 from selected_routes r where r.provider_model_id=t.provider_model_id)
 union all select 'variants',private.project_routing_catalogue_row(to_jsonb(t)) from public.v2_route_variants t where exists(select 1 from selected_routes r where r.provider_model_id=t.provider_model_id)
 union all select 'regions',private.project_routing_catalogue_row(to_jsonb(t)) from public.v2_provider_regions t
 union all select 'serviceTiers',private.project_routing_catalogue_row(to_jsonb(t)) from public.v2_service_tiers t
 union all select 'skus',private.project_routing_catalogue_row(to_jsonb(t)) from selected_skus t
 union all select 'meters',private.project_routing_catalogue_row(to_jsonb(t)||jsonb_build_object('price_nanos',t.price_nanos::text)) from public.v2_pricing_sku_meters t where exists(select 1 from selected_skus s where s.sku_id=t.sku_id)
 union all select 'aliases',private.project_routing_catalogue_row(to_jsonb(t)) from public.v2_model_aliases t
 union all select 'benchmarks',jsonb_build_object('model_slug',t.model_slug,'benchmark_id',t.benchmark_id,
   'score_numeric',t.score_numeric,'is_self_reported',t.is_self_reported,'effective_to',t.effective_to)
   from public.v2_benchmark_results t join public.v2_benchmarks b using(benchmark_id)
   where t.is_self_reported=false and (t.effective_to is null or t.effective_to>statement_timestamp())
     and concat_ws(' ',t.benchmark_id,t.result_key,t.other_info,b.name) !~* '\minternal\M'
), budget as (
 select count(*) as rows,coalesce(sum(octet_length(row::text)),0) as bytes,
   coalesce(max(octet_length(row::text)),0) as largest from projected
)
select case when rows > 100000 or bytes > 16777216 or largest > 262144
 then jsonb_build_object('error','catalogue_source_too_large')
 else jsonb_build_object(
  'revision',(select revision::text from private.routing_catalogue_revision where singleton),
  'generatedAt',floor(extract(epoch from statement_timestamp())*1000),
  'source',(select jsonb_object_agg(k.kind,coalesce(p.items,'[]'::jsonb))
    from unnest(array['models','providers','routes','capabilities','variants','regions','serviceTiers','skus','meters','aliases','benchmarks']) k(kind)
    left join (select kind,jsonb_agg(row) as items from projected group by kind) p using(kind))
 ) end from budget;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_catalogue_source"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_catalogue_source"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_charge_with_credit_cache.sql
CREATE OR REPLACE FUNCTION public.gateway_charge_with_credit_cache (
  p_workspace_id                  uuid,
  p_request_id                    text,
  p_cost_nanos                    bigint,
  p_credit_snapshot_balance_nanos bigint DEFAULT NULL::bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_result jsonb;
  v_legacy jsonb;
  v_available numeric;
  v_invalidate boolean := true;
begin
  -- Keep the existing idempotency key, debit, wallet lock and top-up behavior.
  -- A successful debit holds its wallet row lock until this transaction ends.
  select to_jsonb(charged) into v_result
  from public.gateway_deduct_and_check_top_up_once(
    p_workspace_id, p_request_id, p_cost_nanos
  ) as charged;

  if v_result is null then raise exception 'gateway_charge_result_missing'; end if;

  -- Some deployed debit functions return JSON through a scalar result column.
  -- The older idempotency wrapper stores that JSON as the status string.
  -- Normalize the known fields here without replacing either existing function.
  begin
    v_legacy := (v_result ->> 'status')::jsonb;
    if jsonb_typeof(v_legacy) = 'object' and jsonb_typeof(v_legacy -> 'status') = 'string' then
      v_result := v_result || jsonb_build_object(
        'status', v_legacy -> 'status',
        'auto_top_up_amount_nanos', coalesce(v_legacy -> 'auto_top_up_amount_nanos', v_result -> 'auto_top_up_amount_nanos'),
        'auto_top_up_account_id', coalesce(v_legacy -> 'auto_top_up_account_id', v_result -> 'auto_top_up_account_id'),
        'stripe_customer_id', coalesce(v_legacy -> 'stripe_customer_id', v_result -> 'stripe_customer_id')
      );
    end if;
  exception when invalid_text_representation then
    null; -- Ordinary textual status; no legacy conversion is needed.
  end;

  if (v_result ->> 'applied')::boolean is true then
    -- Read under the debit's wallet row lock: this is the exact post-charge
    -- available balance, which the gateway can write back to its cache instead
    -- of deleting the entry and re-reading the wallet on the next request.
    select w.balance_nanos::numeric - coalesce(w.reserved_nanos, 0)::numeric
    into v_available from public.wallets w where w.workspace_id = p_workspace_id;

    -- Compare to the request's original snapshot, NOT just this request's cost.
    -- This catches cumulative spending by other requests and includes holds.
    -- Numeric arithmetic avoids bigint multiplication overflow at large balances.
    if v_result ->> 'status' = 'top_up_not_required'
       and p_credit_snapshot_balance_nanos >= 10000000000
       and v_available >= 10000000000
       and v_available * 10 > p_credit_snapshot_balance_nanos::numeric * 9 then
      v_invalidate := false;
    end if;
  end if;

  -- Replays invalidate conservatively: an earlier response/invalidation may
  -- have been lost after the debit committed. Never debit a replay twice.
  return v_result || jsonb_build_object(
    'invalidate_credit_cache', v_invalidate,
    'available_nanos', case when v_available is null then null else greatest(v_available, 0)::bigint end
  );
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_charge_with_credit_cache"(uuid, text, bigint, bigint) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_charge_with_credit_cache"(uuid, text, bigint, bigint) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_claim_batch_file_upload.sql
CREATE OR REPLACE FUNCTION public.gateway_claim_batch_file_upload (
  p_workspace_id uuid,
  p_upload_id    text,
  p_bytes        bigint
)
  RETURNS TABLE (
    ok     boolean,
    reason text
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_hour_count bigint;
  v_day_bytes bigint;
begin
  if p_workspace_id is null or coalesce(trim(p_upload_id), '') = '' or p_bytes is null or p_bytes <= 0 then
    raise exception 'invalid_batch_file_upload_claim';
  end if;
  if p_bytes > 20971520 then
    return query select false, 'batch_file_too_large'::text;
    return;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('batch-file:' || p_workspace_id::text, 0));
  if not exists (
    select 1 from public.wallets
    where workspace_id = p_workspace_id
      and coalesce(balance_nanos, 0) - coalesce(reserved_nanos, 0) > 0
  ) then
    return query select false, 'insufficient_funds'::text;
    return;
  end if;
  select count(*) into v_hour_count
  from public.gateway_batch_file_uploads
  where workspace_id = p_workspace_id and created_at >= now() - interval '1 hour';
  if v_hour_count >= 20 then
    return query select false, 'batch_file_hourly_quota_exceeded'::text;
    return;
  end if;
  select coalesce(sum(bytes), 0) into v_day_bytes
  from public.gateway_batch_file_uploads
  where workspace_id = p_workspace_id and created_at >= now() - interval '24 hours';
  if v_day_bytes + p_bytes > 104857600 then
    return query select false, 'batch_file_daily_bytes_exceeded'::text;
    return;
  end if;
  insert into public.gateway_batch_file_uploads (workspace_id, upload_id, bytes, status)
  values (p_workspace_id, p_upload_id, p_bytes, 'claimed')
  on conflict (workspace_id, upload_id) do nothing;
  if not found then
    return query select false, 'batch_file_upload_already_claimed'::text;
    return;
  end if;
  return query select true, null::text;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_claim_batch_file_upload"(uuid, text, bigint) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_claim_batch_file_upload"(uuid, text, bigint) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_claim_provider_event.sql
CREATE OR REPLACE FUNCTION public.gateway_claim_provider_event (
  p_provider          text,
  p_provider_event_id text,
  p_worker_id         text    DEFAULT 'batch-provider-webhook'::text,
  p_lease_seconds     integer DEFAULT 120
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_claimed integer;
begin
  update public.gateway_provider_events event
  set replay_locked_at = now(),
      replay_locked_by = left(coalesce(nullif(trim(p_worker_id), ''), 'batch-provider-webhook'), 200),
      updated_at = now()
  where event.provider = nullif(trim(p_provider), '')
    and event.provider_event_id = nullif(trim(p_provider_event_id), '')
    and event.processed_at is null
    and event.dead_lettered_at is null
    and (event.next_attempt_at is null or event.next_attempt_at <= now())
    and (
      event.replay_locked_at is null
      or event.replay_locked_at < now() - make_interval(
        secs => greatest(30, least(coalesce(p_lease_seconds, 120), 3600))
      )
    );

  get diagnostics v_claimed = row_count;
  return v_claimed = 1;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_claim_provider_event"(text, text, text, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_claim_provider_event"(text, text, text, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_claim_workspace_publications.sql
CREATE OR REPLACE FUNCTION public.gateway_claim_workspace_publications (
  p_limit        integer DEFAULT 25,
  p_workspace_id uuid    DEFAULT NULL::uuid
)
  RETURNS TABLE (
    workspace_id uuid,
    revision     uuid,
    lease_id     uuid
  )
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if p_limit is null or p_limit < 1 or p_limit > 100 then
    raise exception 'invalid_publication_limit' using errcode='22023';
  end if;
  -- The existing authenticated explicit-invalidation route can also request
  -- publication when there was no preceding mutation. A busy lease is not stolen.
  if p_workspace_id is not null then
    insert into public.gateway_workspace_publications (workspace_id)
      select w.id from public.workspaces w where w.id = p_workspace_id
      on conflict on constraint gateway_workspace_publications_pkey do nothing;
  end if;
  return query
  with due as (
    select p.workspace_id from public.gateway_workspace_publications p
    where p.attempts < 10 and p.available_at <= clock_timestamp()
      and (p.lease_until is null or p.lease_until <= clock_timestamp())
      and (p_workspace_id is null or p.workspace_id = p_workspace_id)
    order by p.available_at, p.workspace_id limit p_limit for update skip locked
  )
  update public.gateway_workspace_publications p set
    lease_id = gen_random_uuid(), lease_until = clock_timestamp() + interval '3 minutes',
    attempts = p.attempts + 1
  from due where p.workspace_id = due.workspace_id
  returning p.workspace_id, p.revision, p.lease_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_claim_workspace_publications"(integer, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_claim_workspace_publications"(integer, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_cleanup_batch_hold_key_usage.sql
CREATE OR REPLACE FUNCTION public.gateway_cleanup_batch_hold_key_usage()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if new.status = 'released' and old.status is distinct from new.status and new.key_id is not null then
    delete from public.gateway_requests
    where workspace_id = new.workspace_id
      and key_id = new.key_id
      and request_id like 'batch_hold_usage:' || new.reservation_id || ':%';
  end if;
  return new;
end;
$function$;

