REVOKE ALL ON FUNCTION "public"."gateway_cleanup_batch_hold_key_usage"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_commit_routing_archive.sql
CREATE OR REPLACE FUNCTION public.gateway_commit_routing_archive(
  p_id uuid, p_created_at timestamptz, p_source_hash text, p_reference jsonb
)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
SET statement_timeout TO '5s' SET lock_timeout TO '500ms'
AS $function$
declare
  v_request public.gateway_requests%rowtype;
  v_fact_id uuid;
  v_source jsonb;
begin
  select * into v_request from public.gateway_requests
  where id = p_id and created_at = p_created_at;
  if not found then return false; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_request.workspace_id::text || ':' || v_request.request_id, 0));
  select * into v_request from public.gateway_requests
  where id = p_id and created_at = p_created_at for update;
  if not found then return false; end if;
  if v_request.detail_metadata->'routing_archive' = p_reference then return true; end if;

  if p_reference->>'version' is distinct from '1'
    or coalesce(p_reference->>'sha256', '') !~ '^[a-f0-9]{64}$'
    or coalesce(p_reference->>'bytes', '') !~ '^[0-9]{1,7}$'
    or (p_reference->>'bytes')::integer not between 1 and 1048576
    or p_reference->>'key' is distinct from 'workspaces/' || v_request.workspace_id::text || '/routing/v1/' ||
      encode(sha256(convert_to(v_request.request_id, 'UTF8')), 'hex') || '/' || (p_reference->>'sha256') || '.json' then
    raise exception using errcode = '22023', message = 'routing_archive_reference_invalid';
  end if;
  select request_event_id into v_fact_id from public.v2_request_facts
  where gateway_request_id = p_id and gateway_request_created_at = p_created_at for update;
  perform 1 from public.v2_request_routing_decisions where request_event_id = v_fact_id for update;
  perform 1 from public.v2_request_routing_traces where request_event_id = v_fact_id for update;
  v_source := public.gateway_routing_archive_source(p_id, p_created_at);
  if v_source is null or v_source->>'source_hash' is distinct from p_source_hash then return false; end if;

  update public.gateway_requests
  set detail_metadata = (coalesce(detail_metadata, '{}'::jsonb) - 'routing_snapshot' - 'routing_diagnostics')
    || jsonb_build_object('routing_archive', p_reference)
  where id = p_id and created_at = p_created_at;
  delete from public.v2_request_routing_decisions where request_event_id = v_fact_id;
  delete from public.v2_request_routing_traces where request_event_id = v_fact_id;
  return true;
end;
$function$;

REVOKE ALL ON FUNCTION public.gateway_commit_routing_archive(uuid, timestamptz, text, jsonb) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.gateway_commit_routing_archive(uuid, timestamptz, text, jsonb) TO service_role;

-- source: supabase/schemas/public/functions/gateway_customer_rate_limit_inputs.sql
CREATE OR REPLACE FUNCTION public.gateway_customer_rate_limit_inputs (
  p_after        uuid    DEFAULT NULL::uuid,
  p_limit        integer DEFAULT 500,
  p_workspace_id uuid    DEFAULT NULL::uuid
)
  RETURNS TABLE (
    workspace_id                   uuid,
    created_at                     timestamp with time zone,
    billing_mode                   text,
    has_paid_top_up                boolean,
    lifetime_paid_spend_nanos      bigint,
    override_requests_per_minute   integer,
    override_free_requests_per_day integer,
    override_expires_at            timestamp with time zone,
    raise_tier                     text,
    raise_expires_at               timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  -- Signals:
  -- * Paid top-up: a settled Stripe payment-intent credit of a top-up kind
  --   (the same rule the dashboard uses for paid workspaces). Promo/credit
  --   code grants are written with kind 'promo_code' and are excluded.
  -- * Lifetime paid spend: settled Stripe top-ups net of succeeded Stripe
  --   refunds, i.e. money the customer actually paid. Usage rollups mix in
  --   spending of granted credits, and gateway_requests is too large to scan.
  --   credit_ledger holds payments, grants and async-job charges but no
  --   per-request usage, so the per-workspace index lookup stays small.
  -- Overrides are returned with their expiry; callers ignore expired rows.
  -- * Self-serve raise: the newest raise that is unexpired, not revoked, and
  --   not followed by a succeeded Stripe refund (a refund revokes it). A refund
  --   row is created when Stripe reports it and its event_time is set again when
  --   its status changes, so a refund pending before the raise that succeeds
  --   after it still counts.
  -- p_workspace_id limits the page to one workspace, for the raise endpoint.
  with page as (
    select w.id, w.created_at, w.billing_mode
    from public.workspaces w
    where (p_after is null or w.id > p_after)
      and (p_workspace_id is null or w.id = p_workspace_id)
    order by w.id
    limit least(greatest(coalesce(p_limit, 500), 1), 1000)
  )
  select
    p.id,
    p.created_at,
    p.billing_mode,
    coalesce(pay.paid_nanos > 0, false),
    greatest(coalesce(pay.paid_nanos, 0) + coalesce(pay.refunded_nanos, 0), 0)::bigint,
    o.requests_per_minute,
    o.free_requests_per_day,
    o.expires_at,
    raise.to_tier,
    raise.expires_at
  from page p
  left join lateral (
    select
      sum(cl.amount_nanos) filter (where cl.ref_type = 'Stripe_Payment_Intent') as paid_nanos,
      sum(cl.amount_nanos) filter (where cl.ref_type = 'Stripe_Refund') as refunded_nanos
    from public.credit_ledger cl
    where cl.workspace_id = p.id
      and (
        (cl.ref_type = 'Stripe_Payment_Intent'
          and cl.kind in ('top_up', 'top_up_one_off', 'auto_top_up')
          and lower(coalesce(cl.status, '')) in ('paid', 'succeeded')
          and cl.amount_nanos > 0)
        or (cl.ref_type = 'Stripe_Refund'
          and lower(coalesce(cl.status, '')) = 'succeeded'
          and cl.amount_nanos < 0)
      )
  ) pay on true
  left join public.workspace_rate_limit_overrides o on o.workspace_id = p.id
  left join lateral (
    select r.to_tier, r.expires_at
    from public.workspace_rate_limit_raises r
    where r.workspace_id = p.id
      and r.revoked_at is null
      and r.expires_at > now()
      and not exists (
        select 1
        from public.credit_ledger cl
        where cl.workspace_id = p.id
          and cl.ref_type = 'Stripe_Refund'
          and lower(coalesce(cl.status, '')) = 'succeeded'
          and greatest(cl.created_at, cl.event_time) >= r.created_at
      )
    order by r.created_at desc
    limit 1
  ) raise on true
  order by p.id
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_customer_rate_limit_inputs"(uuid, integer, uuid) TO "service_role";

COMMENT ON FUNCTION "public"."gateway_customer_rate_limit_inputs"(uuid, integer, uuid) IS 'Keyset-paginated (by workspace id) trust-ladder inputs for the gateway customer rate-limit tier publisher.';

REVOKE ALL ON FUNCTION "public"."gateway_customer_rate_limit_inputs"(uuid, integer, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_deduct_and_check_top_up_once.sql
CREATE OR REPLACE FUNCTION public.gateway_deduct_and_check_top_up_once (
  p_workspace_id uuid,
  p_request_id   text,
  p_cost_nanos   bigint
)
  RETURNS TABLE (
    applied                  boolean,
    already_applied          boolean,
    status                   text,
    auto_top_up_amount_nanos bigint,
    auto_top_up_account_id   text,
    stripe_customer_id       text
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_charge public.gateway_request_charges%rowtype;
  v_result record;
  v_result_json jsonb;
  v_status text;
  v_auto_top_up_amount_nanos bigint;
  v_auto_top_up_account_id text;
  v_stripe_customer_id text;
begin
  if p_workspace_id is null then
    raise exception 'missing_workspace_id';
  end if;

  if coalesce(trim(p_request_id), '') = '' then
    raise exception 'missing_request_id';
  end if;

  if p_cost_nanos is null or p_cost_nanos <= 0 then
    raise exception 'invalid_cost_nanos';
  end if;

  insert into public.gateway_request_charges (
    workspace_id,
    request_id,
    cost_nanos,
    status,
    created_at,
    updated_at
  ) values (
    p_workspace_id,
    p_request_id,
    p_cost_nanos,
    'applying',
    now(),
    now()
  )
  on conflict (workspace_id, request_id) do nothing;

  select *
  into v_charge
  from public.gateway_request_charges
  where workspace_id = p_workspace_id
    and request_id = p_request_id
  for update;

  if not found then
    raise exception 'gateway_request_charge_row_missing';
  end if;

  if v_charge.cost_nanos <> p_cost_nanos then
    raise exception 'request_charge_amount_mismatch';
  end if;

  if v_charge.status = 'applied' then
    return query
    select
      false,
      true,
      coalesce(v_charge.deducted_status, 'already_applied')::text,
      0::bigint,
      null::text,
      null::text;
    return;
  end if;

  update public.gateway_request_charges
  set status = 'applying',
      error_message = null,
      updated_at = now()
  where workspace_id = p_workspace_id
    and request_id = p_request_id;

  begin
    select *
    into v_result
    from public.deduct_and_check_top_up(
      p_workspace_id := p_workspace_id,
      p_cost_nanos := p_cost_nanos
    );

    v_result_json := to_jsonb(v_result);
  exception when others then
    update public.gateway_request_charges
    set status = 'failed',
        error_message = sqlerrm,
        updated_at = now()
    where workspace_id = p_workspace_id
      and request_id = p_request_id;
    raise;
  end;

  v_status := coalesce(
    nullif(trim(v_result_json ->> 'status'), ''),
    nullif(trim(v_result_json ->> 'result'), ''),
    nullif(trim(v_result_json ->> 'deduct_and_check_top_up'), ''),
    'unknown'
  );

  v_auto_top_up_amount_nanos := case
    when coalesce(v_result_json ->> 'auto_top_up_amount_nanos', '') ~ '^-?[0-9]+$'
      then (v_result_json ->> 'auto_top_up_amount_nanos')::bigint
    when coalesce(v_result_json ->> 'auto_top_up_amount', '') ~ '^-?[0-9]+$'
      then (v_result_json ->> 'auto_top_up_amount')::bigint
    else 0::bigint
  end;

  v_auto_top_up_account_id := nullif(
    coalesce(
      v_result_json ->> 'auto_top_up_account_id',
      v_result_json ->> 'auto_top_up_payment_method_id',
      ''
    ),
    ''
  );

  v_stripe_customer_id := nullif(v_result_json ->> 'stripe_customer_id', '');

  update public.gateway_request_charges
  set status = 'applied',
      deducted_status = v_status,
      auto_top_up_required = v_status = 'top_up_required',
      updated_at = now()
  where workspace_id = p_workspace_id
    and request_id = p_request_id;

  return query
  select
    true,
    false,
    v_status,
    v_auto_top_up_amount_nanos,
    v_auto_top_up_account_id,
    v_stripe_customer_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_deduct_and_check_top_up_once"(uuid, text, bigint) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_deduct_and_check_top_up_once"(uuid, text, bigint) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_defer_provider_event.sql
CREATE OR REPLACE FUNCTION public.gateway_defer_provider_event (
  p_provider          text,
  p_provider_event_id text,
  p_reason            text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_next_attempt integer;
begin
  select attempt_count + 1 into v_next_attempt
  from public.gateway_provider_events
  where provider = p_provider and provider_event_id = p_provider_event_id
  for update;
  if not found then return; end if;

  update public.gateway_provider_events
  set attempt_count = v_next_attempt,
      last_error = left(coalesce(p_reason, 'provider_event_deferred'), 500),
      next_attempt_at = case
        when v_next_attempt >= 20 then null
        else now() + make_interval(secs => least(1800, 5 * (2 ^ least(v_next_attempt, 8))::integer))
      end,
      dead_lettered_at = case when v_next_attempt >= 20 then now() else dead_lettered_at end,
      processed_at = case when v_next_attempt >= 20 then now() else processed_at end,
      replay_locked_at = null,
      replay_locked_by = null,
      updated_at = now()
  where provider = p_provider and provider_event_id = p_provider_event_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_defer_provider_event"(text, text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_defer_provider_event"(text, text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_feedback_summary.sql
CREATE OR REPLACE FUNCTION public.gateway_feedback_summary (
  p_workspace_id       uuid,
  p_visible_preset_ids uuid[],
  p_group_by           text                     DEFAULT 'preset_id'::text,
  p_metadata_key       text                     DEFAULT NULL::text,
  p_request_id         text                     DEFAULT NULL::text,
  p_session_id         text                     DEFAULT NULL::text,
  p_preset_id          uuid                     DEFAULT NULL::uuid,
  p_test_run_id        uuid                     DEFAULT NULL::uuid,
  p_created_since      timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  p_created_until      timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  p_metadata_filters   jsonb                    DEFAULT '{}'::jsonb,
  p_limit              integer                  DEFAULT 5000
)
  RETURNS TABLE (
    group_value      text,
    count            bigint,
    positive         bigint,
    negative         bigint,
    partial          bigint,
    average_score    numeric,
    ratings          jsonb,
    last_feedback_at timestamp with time zone
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if p_group_by not in ('preset_id', 'test_run_id', 'metadata') then
    raise exception 'invalid feedback summary grouping' using errcode = '22023';
  end if;
  if p_group_by = 'metadata'
     and (p_metadata_key is null or p_metadata_key !~ '^[a-zA-Z0-9_.:-]{1,64}$') then
    raise exception 'valid metadata key required for metadata grouping' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_metadata_filters, '{}'::jsonb)) <> 'object' then
    raise exception 'metadata filters must be a JSON object' using errcode = '22023';
  end if;

  return query
  with filtered as (
    select
      case p_group_by
        when 'preset_id' then feedback.preset_id::text
        when 'test_run_id' then feedback.test_run_id::text
        when 'metadata' then feedback.metadata_dimensions ->> p_metadata_key
      end as summary_group,
      feedback.rating,
      feedback.score,
      feedback.created_at
    from public.gateway_feedback as feedback
    where feedback.workspace_id = p_workspace_id
      and (feedback.preset_id is null or feedback.preset_id = any(coalesce(p_visible_preset_ids, '{}'::uuid[])))
      and (p_request_id is null or feedback.request_id = p_request_id)
      and (p_session_id is null or feedback.session_id = p_session_id)
      and (p_preset_id is null or feedback.preset_id = p_preset_id)
      and (p_test_run_id is null or feedback.test_run_id = p_test_run_id)
      and (p_created_since is null or feedback.created_at >= p_created_since)
      and (p_created_until is null or feedback.created_at <= p_created_until)
      and feedback.metadata_dimensions @> coalesce(p_metadata_filters, '{}'::jsonb)
  ),
  grouped as (
    select summary_group,
      count(*) as feedback_count,
      count(*) filter (where rating in ('thumbs_up', 'correct')) as positive_count,
      count(*) filter (where rating in ('thumbs_down', 'incorrect', 'unsafe')) as negative_count,
      count(*) filter (where rating = 'partly_correct') as partial_count,
      avg(score) filter (where score is not null) as mean_score,
      max(created_at) as latest_feedback_at
    from filtered
    where summary_group is not null and summary_group <> ''
    group by summary_group
  ),
  rating_counts as (
    select summary_group, coalesce(rating, 'unrated') as rating_key, count(*) as rating_count
    from filtered
    where summary_group is not null and summary_group <> ''
    group by summary_group, coalesce(rating, 'unrated')
  ),
  rating_totals as (
    select summary_group, jsonb_object_agg(rating_key, rating_count) as rating_map
    from rating_counts group by summary_group
  )
  select grouped.summary_group, grouped.feedback_count, grouped.positive_count,
    grouped.negative_count, grouped.partial_count, grouped.mean_score,
    coalesce(rating_totals.rating_map, '{}'::jsonb), grouped.latest_feedback_at
  from grouped left join rating_totals using (summary_group)
  order by grouped.latest_feedback_at desc, grouped.summary_group asc
  limit greatest(1, least(coalesce(p_limit, 5000), 10000));
end;
$function$;

GRANT EXECUTE
  ON FUNCTION "public"."gateway_feedback_summary"(uuid, uuid[], text, text, text, text, uuid, uuid, timestamp WITH time zone, timestamp WITH time zone, jsonb, integer)
  TO "service_role";

COMMENT ON FUNCTION "public"."gateway_feedback_summary"(uuid, uuid[], text, text, text, text, uuid, uuid, timestamp with time zone, timestamp
  with time zone, jsonb, integer) IS 'Service-role-only feedback aggregation constrained to caller-visible presets.';

