-- source: supabase/schemas/public/functions/gateway_realtime_settle_once.sql
CREATE OR REPLACE FUNCTION public.gateway_realtime_settle_once (
  p_workspace_id      uuid,
  p_session_id        text,
  p_final_cost_nanos  bigint,
  p_usage             jsonb   DEFAULT '{}'::jsonb,
  p_pricing_lines     jsonb   DEFAULT '[]'::jsonb,
  p_status            text    DEFAULT 'completed'::text,
  p_disconnect_reason text    DEFAULT NULL::text,
  p_error_code        text    DEFAULT NULL::text,
  p_error_message     text    DEFAULT NULL::text,
  p_estimated         boolean DEFAULT false,
  p_estimate_basis    text    DEFAULT NULL::text
)
  RETURNS TABLE (
    applied               boolean,
    already_applied       boolean,
    status                text,
    final_cost_nanos      bigint,
    reserved_nanos        bigint,
    captured_nanos        bigint,
    released_nanos        bigint,
    before_balance_nanos  bigint,
    after_balance_nanos   bigint,
    before_reserved_nanos bigint,
    after_reserved_nanos  bigint,
    debt_nanos            bigint,
    uncollected_nanos     bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  -- REALTIME_MAX_OVERDRAFT_NANOS: a settlement may leave the wallet at most $1 negative.
  c_max_overdraft_nanos constant bigint := 1000000000;
  v_session public.gateway_realtime_sessions%rowtype;
  v_wallet public.wallets%rowtype;
  v_reservation public.gateway_wallet_reservations%rowtype;
  v_cost bigint := greatest(0, coalesce(p_final_cost_nanos, 0));
  v_held bigint := 0;
  v_prepaid bigint := 0;
  v_total bigint;
  v_due bigint;
  v_free bigint;
  v_release bigint;
  v_charge bigint;
  v_debt bigint;
  v_uncollected bigint;
  v_anomaly text;
  v_capture_remaining bigint;
  v_row_capture bigint;
  v_before_balance bigint;
  v_before_reserved bigint;
  v_request_count integer;
  v_next_status text := lower(coalesce(nullif(trim(p_status), ''), 'completed'));
begin
  if v_next_status not in ('completed', 'failed', 'cancelled', 'expired') then
    raise exception 'invalid_realtime_terminal_status';
  end if;

  select * into v_session from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id;
  if not found then
    return query select false, false, 'not_found'::text, 0::bigint, 0::bigint,
      0::bigint, 0::bigint, null::bigint, null::bigint, null::bigint, null::bigint, 0::bigint, 0::bigint;
    return;
  end if;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return query select false, true, v_session.status, coalesce(v_session.final_cost_nanos, 0),
      v_session.reserved_nanos, v_session.captured_nanos, v_session.released_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint, v_session.debt_nanos, v_session.uncollected_nanos;
    return;
  end if;

  perform 1 from public.gateway_wallet_reservations gwr
  where gwr.workspace_id = p_workspace_id and gwr.status in ('held', 'reserved')
    and (gwr.hold_ref_id = p_session_id or gwr.reservation_id like v_session.reservation_prefix || '%')
  order by gwr.created_at, gwr.reservation_id
  for update;

  select * into v_wallet from public.wallets
  where workspace_id = p_workspace_id for update;
  if not found then raise exception 'wallet_not_found'; end if;

  select * into v_session from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id for update;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return query select false, true, v_session.status, coalesce(v_session.final_cost_nanos, 0),
      v_session.reserved_nanos, v_session.captured_nanos, v_session.released_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint, v_session.debt_nanos, v_session.uncollected_nanos;
    return;
  end if;

  select coalesce(sum(gwr.amount_nanos), 0)::bigint into v_held
  from public.gateway_wallet_reservations gwr
  where gwr.workspace_id = p_workspace_id and gwr.status in ('held', 'reserved')
    and (gwr.hold_ref_id = p_session_id or gwr.reservation_id like v_session.reservation_prefix || '%');

  -- Confirmed usage may already have been captured when the session entered
  -- billing review; only the remainder is charged now, and never refunded.
  v_prepaid := greatest(0, coalesce(v_session.captured_nanos, 0));
  v_total := greatest(v_cost, v_prepaid);
  v_due := v_total - v_prepaid;

  v_before_balance := coalesce(v_wallet.balance_nanos, 0);
  v_before_reserved := coalesce(v_wallet.reserved_nanos, 0);
  v_release := v_held;
  if v_before_reserved < v_held then
    -- Clamp instead of failing forever: the session holds are still released.
    v_anomaly := 'reserved_balance_mismatch';
    v_release := greatest(0, v_before_reserved);
    raise warning 'realtime_settlement_reserved_balance_mismatch session=% held=% wallet_reserved=%',
      p_session_id, v_held, v_before_reserved;
  end if;

  -- Charge the full cost from the holds and free balance. Beyond that the
  -- wallet may go negative up to the overdraft cap (recorded as debt); any
  -- remainder is recorded as uncollected instead of retrying settlement.
  v_free := v_before_balance - v_before_reserved;
  v_charge := least(v_due, greatest(v_release, v_free + v_release + c_max_overdraft_nanos));
  v_uncollected := v_due - v_charge;
  v_debt := greatest(0, v_charge - v_release - greatest(0, v_free));
  if v_uncollected > 0 then
    v_anomaly := coalesce(v_anomaly || ',', '') || 'overdraft_cap_reached';
    raise warning 'realtime_settlement_overdraft_cap_reached session=% uncollected=%', p_session_id, v_uncollected;
  end if;

  update public.wallets w
  set balance_nanos = w.balance_nanos - v_charge,
      reserved_nanos = greatest(0, w.reserved_nanos - v_held),
      updated_at = now()
  where workspace_id = p_workspace_id;

  v_capture_remaining := least(v_charge, v_held);
  for v_reservation in
    select gwr.* from public.gateway_wallet_reservations gwr
    where gwr.workspace_id = p_workspace_id and gwr.status in ('held', 'reserved')
      and (gwr.hold_ref_id = p_session_id or gwr.reservation_id like v_session.reservation_prefix || '%')
    order by gwr.created_at, gwr.reservation_id
    for update
  loop
    v_row_capture := least(v_reservation.amount_nanos, v_capture_remaining);
    update public.gateway_wallet_reservations
    set status = case when v_row_capture > 0 then 'captured' else 'released' end,
        captured_nanos = v_row_capture,
        released_nanos = v_reservation.amount_nanos - v_row_capture,
        capture_ref_id = case when v_row_capture > 0 then p_session_id else null end,
        release_ref_id = case when v_row_capture < v_reservation.amount_nanos then p_session_id else null end,
        captured_at = case when v_row_capture > 0 then now() else null end,
        released_at = case when v_row_capture < v_reservation.amount_nanos then now() else null end,
        updated_at = now()
    where workspace_id = p_workspace_id and reservation_id = v_reservation.reservation_id;
    v_capture_remaining := greatest(0, v_capture_remaining - v_row_capture);
  end loop;

  if v_charge > 0 then
    insert into public.credit_ledger (
      workspace_id, event_time, kind, amount_nanos, before_balance_nanos,
      after_balance_nanos, before_reserved_nanos, after_reserved_nanos,
      ref_type, ref_id, created_at, status
    ) values (
      p_workspace_id, now(), 'charge', -v_charge, v_before_balance,
      v_before_balance - v_charge, v_before_reserved, greatest(0, v_before_reserved - v_held),
      'realtime_session', p_session_id, now(), 'captured'
    ) on conflict (ref_type, ref_id) do nothing;
  end if;

  update public.gateway_realtime_sessions
  set status = v_next_status,
      ended_at = coalesce(ended_at, now()),
      final_cost_nanos = v_total,
      captured_nanos = v_prepaid + v_charge,
      released_nanos = greatest(0, v_held - least(v_charge, v_held)),
      reserved_nanos = greatest(coalesce(v_session.reserved_nanos, 0), v_held),
      usage = coalesce(p_usage, '{}'::jsonb),
      pricing_lines = case when jsonb_typeof(coalesce(p_pricing_lines, '[]'::jsonb)) = 'array'
        then p_pricing_lines else '[]'::jsonb end,
      disconnect_reason = nullif(trim(coalesce(p_disconnect_reason, '')), ''),
      error_code = nullif(trim(coalesce(p_error_code, '')), ''),
      error_message = nullif(trim(coalesce(p_error_message, '')), ''),
      billing_estimated = coalesce(p_estimated, false),
      estimate_basis = case when coalesce(p_estimated, false)
        then left(coalesce(nullif(trim(p_estimate_basis), ''), 'metered_audio'), 120) end,
      debt_nanos = v_debt,
      uncollected_nanos = v_uncollected,
      billing_anomaly = v_anomaly,
      updated_at = now()
  where id = v_session.id
  returning * into v_session;

  update public.gateway_requests
  set native_response_id = coalesce(v_session.provider_session_id, v_session.provider_native_id),
      status_code = case when v_next_status = 'completed' then 200 else 499 end,
      success = v_next_status = 'completed',
      error_code = nullif(trim(coalesce(p_error_code, '')), ''),
      error_message = nullif(trim(coalesce(p_error_message, '')), ''),
      generation_ms = greatest(0, floor(extract(epoch from (v_session.ended_at - v_session.started_at)) * 1000))::integer,
      usage = coalesce(p_usage, '{}'::jsonb),
      -- The full priced cost; any uncollected part stays on the session.
      cost_nanos = v_total,
      currency = 'USD',
      pricing_lines = case when jsonb_typeof(coalesce(p_pricing_lines, '[]'::jsonb)) = 'array'
        then p_pricing_lines else '[]'::jsonb end
  where realtime_session_id = p_session_id
    and created_at = v_session.started_at;
  get diagnostics v_request_count = row_count;
  if v_request_count <> 1 then
    raise exception 'realtime_request_summary_missing';
  end if;

  return query select true, false, v_session.status, v_total, v_held, v_prepaid + v_charge,
    greatest(0, v_held - least(v_charge, v_held)), v_before_balance,
    v_before_balance - v_charge, v_before_reserved, greatest(0, v_before_reserved - v_held),
    v_debt, v_uncollected;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_realtime_settle_once"(uuid, text, bigint, jsonb, jsonb, text, text, text, text, boolean, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_realtime_settle_once"(uuid, text, bigint, jsonb, jsonb, text, text, text, text, boolean, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_record_batch_key_usage.sql
CREATE OR REPLACE FUNCTION public.gateway_record_batch_key_usage (
  p_workspace_id uuid,
  p_key_id       uuid,
  p_batch_id     text,
  p_provider     text,
  p_rows         jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_inserted integer := 0;
begin
  if p_workspace_id is null or p_key_id is null or coalesce(trim(p_batch_id), '') = '' then
    raise exception 'invalid_batch_key_usage_identity';
  end if;
  if not exists (
    select 1 from public.keys
    where id = p_key_id and workspace_id = p_workspace_id
  ) then
    raise exception 'batch_key_not_owned_by_workspace';
  end if;
  if jsonb_typeof(p_rows) <> 'array' then
    raise exception 'invalid_batch_key_usage_rows';
  end if;

  delete from public.gateway_requests gr
  where gr.workspace_id = p_workspace_id
    and gr.key_id = p_key_id
    and gr.request_id like 'batch_hold_usage:%'
    and exists (
      select 1
      from public.gateway_wallet_reservations reservation
      where reservation.workspace_id = p_workspace_id
        and reservation.key_id = p_key_id
        and reservation.capture_ref_id = p_batch_id
        and reservation.status = 'captured'
        and gr.request_id like 'batch_hold_usage:' || reservation.reservation_id || ':%'
    );

  with source_rows as (
    select
      coalesce(nullif(trim(row ->> 'custom_id'), ''), ordinality::text) as custom_id,
      coalesce(nullif(trim(row ->> 'endpoint'), ''), 'batch') as endpoint,
      coalesce(nullif(trim(row ->> 'model'), ''), 'batch/unknown') as model,
      greatest(0, coalesce((row ->> 'cost_nanos')::bigint, 0)) as cost_nanos,
      case when jsonb_typeof(row -> 'usage') = 'object' then row -> 'usage' else '{}'::jsonb end as usage
    from jsonb_array_elements(p_rows) with ordinality as entries(row, ordinality)
  ), claimed_rows as (
    insert into public.gateway_batch_key_usage_records (
      workspace_id, batch_id, custom_id, key_id, provider, endpoint, model, cost_nanos, usage
    )
    select
      p_workspace_id, p_batch_id, source.custom_id, p_key_id,
      nullif(trim(coalesce(p_provider, '')), ''), source.endpoint,
      source.model, source.cost_nanos, source.usage
    from source_rows source
    on conflict (workspace_id, batch_id, custom_id) do nothing
    returning custom_id, provider, endpoint, model, cost_nanos, usage
  )
  insert into public.gateway_requests (
    workspace_id, request_id, endpoint, model_id, provider,
    status_code, success, usage, cost_nanos, currency, key_id
  )
  select
    p_workspace_id,
    'batch_usage:' || p_batch_id || ':' || claimed.custom_id,
    claimed.endpoint,
    claimed.model,
    claimed.provider,
    200,
    true,
    claimed.usage,
    claimed.cost_nanos,
    'USD',
    p_key_id
  from claimed_rows claimed;
  get diagnostics v_inserted = row_count;

  update public.gateway_wallet_reservations
  set key_usage_recorded_at = coalesce(key_usage_recorded_at, now()), updated_at = now()
  where workspace_id = p_workspace_id
    and key_id = p_key_id
    and capture_ref_id = p_batch_id
    and status = 'captured';

  return v_inserted;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_record_batch_key_usage"(uuid, uuid, text, text, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_record_batch_key_usage"(uuid, uuid, text, text, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_request_usage_rollup_rows.sql
CREATE OR REPLACE FUNCTION public.gateway_request_usage_rollup_rows (
  p_since timestamp with time zone,
  p_until timestamp with time zone DEFAULT now()
)
  RETURNS TABLE (
    day_bucket                  date,
    model_id                    text,
    provider_id                 text,
    endpoint                    text,
    requests                    bigint,
    success_requests            bigint,
    failed_requests             bigint,
    neutral_requests            bigint,
    rate_limited_requests       bigint,
    total_tokens                bigint,
    input_tokens                bigint,
    output_tokens               bigint,
    reasoning_tokens            bigint,
    input_text_tokens           bigint,
    output_text_tokens          bigint,
    input_image_tokens          bigint,
    output_image_tokens         bigint,
    input_audio_tokens          bigint,
    output_audio_tokens         bigint,
    input_video_tokens          bigint,
    output_video_tokens         bigint,
    image_inputs                bigint,
    image_outputs               bigint,
    audio_inputs                bigint,
    audio_outputs               bigint,
    video_inputs                bigint,
    video_outputs               bigint,
    cached_read_tokens          bigint,
    cached_write_tokens         bigint,
    cached_read_text_tokens     bigint,
    cached_write_text_tokens    bigint,
    cached_write_text_tokens_5m bigint,
    cached_write_text_tokens_1h bigint,
    cached_read_image_tokens    bigint,
    cached_write_image_tokens   bigint,
    cached_read_audio_tokens    bigint,
    cached_write_audio_tokens   bigint,
    cached_read_video_tokens    bigint,
    cached_write_video_tokens   bigint,
    input_quad_tokens           bigint,
    output_quad_tokens          bigint,
    total_quad_tokens           bigint,
    text_quad_tokens            bigint,
    rerank_quad_tokens          bigint,
    embedding_quad_tokens       bigint,
    moderation_quad_tokens      bigint,
    ocr_quad_tokens             bigint,
    image_megapixels            numeric,
    audio_seconds               numeric,
    video_pixel_seconds         numeric,
    input_characters            bigint,
    output_characters           bigint,
    total_characters            bigint,
    total_cost_nanos            bigint,
    latency_sum_ms              bigint,
    latency_samples             bigint,
    generation_sum_ms           bigint,
    generation_samples          bigint,
    throughput_sum              numeric,
    throughput_samples          bigint,
    last_request_at             timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with base as (
    select
      date_trunc('day', gr.created_at at time zone 'utc')::date as day_bucket,
      coalesce(
        nullif(gr.canonical_model_id, ''),
        public.resolve_public_model_id(gr.model_id, gr.provider),
        nullif(gr.routed_model_id, ''),
        nullif(gr.requested_model_id, ''),
        nullif(gr.model_id, ''),
        'unknown'
      ) as model_id,
      coalesce(nullif(gr.provider, ''), 'unknown') as provider_id,
      coalesce(nullif(gr.endpoint, ''), 'unknown') as endpoint,
      gr.created_at,
      gr.success,
      gr.status_code,
      lower(coalesce(gr.error_code, '')) as error_code,
      gr.cost_nanos,
      gr.latency_ms,
      gr.generation_ms,
      gr.throughput,
      gr.usage_total_tokens,
      gr.usage_input_tokens,
      gr.usage_output_tokens,
      gr.usage_reasoning_tokens,
      gr.usage_input_text_tokens,
      gr.usage_output_text_tokens,
      gr.usage_input_image_tokens,
      gr.usage_output_image_tokens,
      gr.usage_input_audio_tokens,
      gr.usage_output_audio_tokens,
      gr.usage_input_video_tokens,
      gr.usage_output_video_tokens,
      gr.usage_image_inputs,
      gr.usage_image_outputs,
      gr.usage_audio_inputs,
      gr.usage_audio_outputs,
      gr.usage_video_inputs,
      gr.usage_video_outputs,
      gr.usage_cached_read_tokens,
      gr.usage_cached_write_tokens,
      gr.usage_cached_read_text_tokens,
      gr.usage_cached_write_text_tokens,
      gr.usage_cached_write_text_tokens_5m,
      gr.usage_cached_write_text_tokens_1h,
      gr.usage_cached_read_image_tokens,
      gr.usage_cached_write_image_tokens,
      gr.usage_cached_read_audio_tokens,
      gr.usage_cached_write_audio_tokens,
      gr.usage_cached_read_video_tokens,
      gr.usage_cached_write_video_tokens,
      gr.usage_input_quad_tokens,
      gr.usage_output_quad_tokens,
      gr.usage_total_quad_tokens,
      gr.usage_text_quad_tokens,
      gr.usage_rerank_quad_tokens,
      gr.usage_embedding_quad_tokens,
      gr.usage_moderation_quad_tokens,
      gr.usage_ocr_quad_tokens,
      gr.usage_image_megapixels,
      gr.usage_audio_seconds,
      gr.usage_video_pixel_seconds,
      gr.usage_input_characters,
      gr.usage_output_characters,
      gr.usage_total_characters
    from private.v2_rpc_gateway_requests_compat gr
    where gr.created_at >= p_since
      and gr.created_at < p_until
  ),
  classified as (
    select
      b.*,
      case
        when b.success is true then 'success'
        when b.status_code = 429
          or b.error_code like '%rate limit%'
          or b.error_code like '%rate_limit%'
          or b.error_code like '%ratelimit%'
          or b.error_code like '%too many requests%'
          or b.error_code like '%quota exceeded%'
          or b.error_code like '%abort%'
          or b.error_code like '%cancel%'
          or b.error_code like '%client_closed%'
        then 'neutral'
        else 'failure'
      end as health_outcome,
      case
        when b.status_code = 429
          or b.error_code like '%rate limit%'
          or b.error_code like '%rate_limit%'
          or b.error_code like '%ratelimit%'
          or b.error_code like '%too many requests%'
          or b.error_code like '%quota exceeded%'
        then true
        else false
      end as is_rate_limited
    from base b
  )
  select
    c.day_bucket,
    c.model_id,
    c.provider_id,
    c.endpoint,
    count(*)::bigint as requests,
    count(*) filter (where c.success is true)::bigint as success_requests,
    count(*) filter (where c.health_outcome = 'failure')::bigint as failed_requests,
    count(*) filter (where c.health_outcome = 'neutral')::bigint as neutral_requests,
    count(*) filter (where c.is_rate_limited)::bigint as rate_limited_requests,
    sum(c.usage_total_tokens)::bigint as total_tokens,
    sum(c.usage_input_tokens)::bigint as input_tokens,
    sum(c.usage_output_tokens)::bigint as output_tokens,
    sum(c.usage_reasoning_tokens)::bigint as reasoning_tokens,
    sum(c.usage_input_text_tokens)::bigint as input_text_tokens,
    sum(c.usage_output_text_tokens)::bigint as output_text_tokens,
    sum(c.usage_input_image_tokens)::bigint as input_image_tokens,
    sum(c.usage_output_image_tokens)::bigint as output_image_tokens,
    sum(c.usage_input_audio_tokens)::bigint as input_audio_tokens,
    sum(c.usage_output_audio_tokens)::bigint as output_audio_tokens,
    sum(c.usage_input_video_tokens)::bigint as input_video_tokens,
    sum(c.usage_output_video_tokens)::bigint as output_video_tokens,
    sum(c.usage_image_inputs)::bigint as image_inputs,
    sum(c.usage_image_outputs)::bigint as image_outputs,
    sum(c.usage_audio_inputs)::bigint as audio_inputs,
    sum(c.usage_audio_outputs)::bigint as audio_outputs,
    sum(c.usage_video_inputs)::bigint as video_inputs,
    sum(c.usage_video_outputs)::bigint as video_outputs,
    sum(c.usage_cached_read_tokens)::bigint as cached_read_tokens,
    sum(c.usage_cached_write_tokens)::bigint as cached_write_tokens,
    sum(c.usage_cached_read_text_tokens)::bigint as cached_read_text_tokens,
    sum(c.usage_cached_write_text_tokens)::bigint as cached_write_text_tokens,
    sum(c.usage_cached_write_text_tokens_5m)::bigint as cached_write_text_tokens_5m,
    sum(c.usage_cached_write_text_tokens_1h)::bigint as cached_write_text_tokens_1h,
    sum(c.usage_cached_read_image_tokens)::bigint as cached_read_image_tokens,
    sum(c.usage_cached_write_image_tokens)::bigint as cached_write_image_tokens,
    sum(c.usage_cached_read_audio_tokens)::bigint as cached_read_audio_tokens,
    sum(c.usage_cached_write_audio_tokens)::bigint as cached_write_audio_tokens,
    sum(c.usage_cached_read_video_tokens)::bigint as cached_read_video_tokens,
    sum(c.usage_cached_write_video_tokens)::bigint as cached_write_video_tokens,
    sum(c.usage_input_quad_tokens)::bigint as input_quad_tokens,
    sum(c.usage_output_quad_tokens)::bigint as output_quad_tokens,
    sum(c.usage_total_quad_tokens)::bigint as total_quad_tokens,
    sum(c.usage_text_quad_tokens)::bigint as text_quad_tokens,
    sum(c.usage_rerank_quad_tokens)::bigint as rerank_quad_tokens,
    sum(c.usage_embedding_quad_tokens)::bigint as embedding_quad_tokens,
    sum(c.usage_moderation_quad_tokens)::bigint as moderation_quad_tokens,
    sum(c.usage_ocr_quad_tokens)::bigint as ocr_quad_tokens,
    sum(c.usage_image_megapixels)::numeric as image_megapixels,
    sum(c.usage_audio_seconds)::numeric as audio_seconds,
    sum(c.usage_video_pixel_seconds)::numeric as video_pixel_seconds,
    sum(c.usage_input_characters)::bigint as input_characters,
    sum(c.usage_output_characters)::bigint as output_characters,
    sum(c.usage_total_characters)::bigint as total_characters,
    sum(coalesce(c.cost_nanos, 0))::bigint as total_cost_nanos,
    sum(coalesce(c.latency_ms, 0)) filter (where c.latency_ms is not null)::bigint as latency_sum_ms,
    count(c.latency_ms)::bigint as latency_samples,
    sum(coalesce(c.generation_ms, 0)) filter (where c.generation_ms is not null)::bigint as generation_sum_ms,
    count(c.generation_ms)::bigint as generation_samples,
    sum(coalesce(c.throughput, 0)) filter (where c.throughput is not null)::numeric as throughput_sum,
    count(c.throughput)::bigint as throughput_samples,
    max(c.created_at) as last_request_at
  from classified c
  where c.model_id is not null
    and c.model_id <> ''
  group by c.day_bucket, c.model_id, c.provider_id, c.endpoint;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_request_usage_rollup_rows"(timestamp WITH time zone, timestamp WITH time zone) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."gateway_request_usage_rollup_rows"(timestamp WITH time zone, timestamp WITH time zone) TO "service_role";

-- source: supabase/schemas/public/functions/gateway_requests_attach_chat_app_id.sql
CREATE OR REPLACE FUNCTION public.gateway_requests_attach_chat_app_id()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_key_name text;
  v_chat_app_key constant text := 'https://phaseo.app/chat';
  v_app_id uuid;
begin
  if new.app_id is not null then
    return new;
  end if;

  if new.workspace_id is null or new.key_id is null then
    return new;
  end if;

  select k.name into v_key_name
  from public.keys k
  where k.id = new.key_id
  limit 1;

  if coalesce(v_key_name, '') <> '__chat_route_managed_key__' then
    return new;
  end if;

  insert into public.api_apps (
    workspace_id,
    app_key,
    title,
    url,
    is_active,
    last_seen,
    updated_at,
    meta
  )
  values (
    new.workspace_id,
    v_chat_app_key,
    'AI Stats Chat',
    v_chat_app_key,
    true,
    coalesce(new.created_at, now()),
    now(),
    jsonb_build_object(
      'identityUrl', v_chat_app_key,
      'managed', true
    )
  )
  on conflict (workspace_id, app_key) do update
    set title = excluded.title,
        url = excluded.url,
        is_active = true,
        last_seen = greatest(public.api_apps.last_seen, excluded.last_seen),
        updated_at = now(),
        meta = coalesce(public.api_apps.meta, '{}'::jsonb) || excluded.meta
  returning id into v_app_id;

  new.app_id := v_app_id;
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_requests_attach_chat_app_id"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_requests_attach_chat_app_id"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_resolve_model_successor.sql
CREATE OR REPLACE FUNCTION public.gateway_resolve_model_successor (
  p_model_slug text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare v_model public.v2_models%rowtype; v_state public.v2_model_successor_routing%rowtype;
  v_current text; v_next text; v_next_replacement text; v_chain text[] := '{}'; v_target text; v_reason text;
  v_variant text; v_ratio numeric; v_comparable boolean := false; v_price jsonb;
begin
  -- Called by the gateway only when a request found no provider for the model.
  -- Lifecycle is public catalogue data; hidden models never match.
  select * into v_model from public.v2_models where model_slug=p_model_slug and not hidden;
  if not found then return null; end if;
  select * into v_state from public.v2_model_successor_routing where model_slug=p_model_slug;

  if v_state.unserved_since is null or v_state.unserved_since > now() - interval '72 hours' then
    v_reason := 'within_grace_period';
  else
    -- Follow approved successors to the first one a provider serves, at most 3 hops.
    -- Every hop needs a current approval: approved for today's replacement.
    v_current := p_model_slug;
    for i in 1..3 loop
      select m.replacement_model_slug into v_next from public.v2_models m where m.model_slug=v_current;
      if v_next is null or not exists (
        select 1 from public.v2_model_successor_routing s
        where s.model_slug=v_current and s.auto_route_enabled and s.approved_successor_slug=v_next
      ) then
        v_reason := case when i=1 then 'not_approved' else 'no_served_successor' end;
        exit;
      end if;
      if v_next = any(v_chain) or v_next=p_model_slug then v_reason := 'no_served_successor'; exit; end if;
      v_chain := v_chain || v_next;
      if exists (select 1 from public.v2_models m where m.model_slug=v_next and not m.hidden and m.status in ('active','deprecated','retired'))
        and public.v2_model_has_routable_route(v_next) then
        v_target := v_next; exit;
      end if;
      v_current := v_next;
    end loop;
    if v_target is null and v_reason is null then v_reason := 'no_served_successor'; end if;
  end if;

  if v_target is not null then
    select variant_kind into v_variant from public.v2_models where model_slug=v_target;
    if v_model.variant_kind='free' and v_variant<>'free' then
      v_reason := 'free_to_paid'; v_target := null;
    end if;
  end if;

  if v_target is not null then
    v_price := public.v2_model_successor_price_ratio(p_model_slug, v_target);
    v_comparable := (v_price->>'comparable')::boolean;
    v_ratio := (v_price->>'ratio')::numeric;
    v_reason := 'eligible';
  end if;

  return jsonb_build_object(
    'model', v_model.model_slug,
    'status', v_model.status,
    'retired_at', v_model.retired_at,
    'replacement_model', v_model.replacement_model_slug,
    'unserved_since', v_state.unserved_since,
    'target', v_target,
    'chain', to_jsonb(v_chain),
    'reason', v_reason,
    'price_ratio', v_ratio,
    'price_comparable', coalesce(v_comparable, false),
    'price_skipped_meters', coalesce(v_price->'skipped_meters', '[]'::jsonb));
end $function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_resolve_model_successor"(text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_resolve_model_successor"(text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_resolve_workspace_model_successor.sql
CREATE OR REPLACE FUNCTION public.gateway_resolve_workspace_model_successor (
  p_model_slug     text,
  p_successor_slug text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare v_model public.v2_models%rowtype; v_successor public.v2_models%rowtype; v_unserved_since timestamptz;
  v_target text; v_reason text; v_price jsonb;
begin
  -- A workspace's own replacement for a model no provider serves. It needs no
  -- admin approval and is one hop only, but keeps the grace period, a served
  -- target and the free-to-paid block. The workspace price policy does not
  -- apply: choosing the replacement is the workspace's decision.
  select * into v_model from public.v2_models where model_slug=p_model_slug and not hidden;
  if not found then return null; end if;
  select unserved_since into v_unserved_since from public.v2_model_successor_routing where model_slug=p_model_slug;
  select * into v_successor from public.v2_models where model_slug=p_successor_slug;

  if v_unserved_since is null or v_unserved_since > now() - interval '72 hours' then
    v_reason := 'within_grace_period';
  elsif v_successor.model_slug is null or v_successor.hidden or v_successor.status not in ('active','deprecated','retired')
    or not public.v2_model_has_routable_route(v_successor.model_slug) then
    v_reason := 'no_served_successor';
  elsif v_model.variant_kind='free' and v_successor.variant_kind<>'free' then
    v_reason := 'free_to_paid';
  else
    v_target := v_successor.model_slug;
    v_reason := 'eligible';
    v_price := public.v2_model_successor_price_ratio(p_model_slug, v_target);
  end if;

  return jsonb_build_object(
    'model', v_model.model_slug,
    'status', v_model.status,
    'retired_at', v_model.retired_at,
    'replacement_model', p_successor_slug,
    'unserved_since', v_unserved_since,
    'target', v_target,
    'chain', case when v_target is null then '[]'::jsonb else jsonb_build_array(v_target) end,
    'reason', v_reason,
    'price_ratio', (v_price->>'ratio')::numeric,
    'price_comparable', coalesce((v_price->>'comparable')::boolean, false),
    'price_skipped_meters', coalesce(v_price->'skipped_meters', '[]'::jsonb),
    'workspace_override', true);
end $function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_resolve_workspace_model_successor"(text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_resolve_workspace_model_successor"(text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_routing_archive_batch.sql
CREATE OR REPLACE FUNCTION public.gateway_routing_archive_batch(
  p_after_id uuid, p_after_created_at timestamptz, p_cutoff timestamptz, p_limit integer DEFAULT 25
)
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO ''
SET statement_timeout TO '5s'
AS $function$
  select public.gateway_routing_archive_source(candidate.id, candidate.created_at)
  from (
    select request.id, request.created_at
    from public.gateway_requests request
    where (request.id, request.created_at) > (p_after_id, p_after_created_at)
      -- Routing snapshots began on 2026-08-19. Older partitions hold only requests
      -- that can never qualify; without this bound every batch rescans all of them.
      and request.created_at >= timestamptz '2026-08-19 00:00:00+00'
      and request.created_at < least(p_cutoff, now() - interval '1 hour')
      and not coalesce(request.detail_metadata ? 'routing_archive', false)
      and (request.detail_metadata ? 'routing_snapshot' or exists (
        select 1 from public.v2_request_facts fact
        join public.v2_request_routing_decisions decision using (request_event_id)
        where fact.gateway_request_id = request.id and fact.gateway_request_created_at = request.created_at
      ))
    order by request.id, request.created_at
    limit greatest(1, least(p_limit, 100))
  ) candidate;
$function$;

REVOKE ALL ON FUNCTION public.gateway_routing_archive_batch(uuid, timestamptz, timestamptz, integer) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.gateway_routing_archive_batch(uuid, timestamptz, timestamptz, integer) TO service_role;

-- source: supabase/schemas/public/functions/gateway_routing_archive_source.sql
CREATE OR REPLACE FUNCTION public.gateway_routing_archive_source(p_id uuid, p_created_at timestamptz)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO ''
AS $function$
  with source as (
    select jsonb_build_object(
      'id', request.id, 'created_at', request.created_at,
      'workspace_id', request.workspace_id, 'request_id', request.request_id,
      'metadata', jsonb_build_object(
        'routing_snapshot', request.detail_metadata->'routing_snapshot',
        'routing_diagnostics', request.detail_metadata->'routing_diagnostics'
      ),
      'routing_trace', (select to_jsonb(trace) from public.v2_request_routing_traces trace
        where trace.request_event_id = fact.request_event_id),
      'routing_decisions', coalesce((select jsonb_agg(to_jsonb(routing_row) order by routing_row.decision_order)
        from public.v2_request_routing_decisions routing_row
        where routing_row.request_event_id = fact.request_event_id), '[]'::jsonb)
    ) payload
    from public.gateway_requests request
    left join public.v2_request_facts fact
      on fact.gateway_request_id = request.id and fact.gateway_request_created_at = request.created_at
    where request.id = p_id and request.created_at = p_created_at
      and not coalesce(request.detail_metadata ? 'routing_archive', false)
  )
  select payload || jsonb_build_object('source_hash', md5(payload::text)) from source;
$function$;

REVOKE ALL ON FUNCTION public.gateway_routing_archive_source(uuid, timestamptz) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.gateway_routing_archive_source(uuid, timestamptz) TO service_role;

-- source: supabase/schemas/public/functions/gateway_set_async_operation_status.sql
CREATE OR REPLACE FUNCTION public.gateway_set_async_operation_status (
  p_workspace_id          uuid,
  p_kind                  text,
  p_internal_id           text,
  p_status                text                     DEFAULT NULL::text,
  p_meta_patch            jsonb                    DEFAULT '{}'::jsonb,
  p_update_next_reconcile boolean                  DEFAULT false,
  p_next_reconcile_at     timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if p_kind not in ('video', 'batch') then
    raise exception 'invalid async operation kind';
  end if;

  update public.gateway_async_operations
  set
    status = case
      when p_status is null then status
      when lower(coalesce(status, '')) in ('completed', 'failed', 'cancelled', 'canceled', 'expired') then status
      when (
        case lower(p_status)
          when 'queued' then 1 when 'pending' then 1
          when 'in_progress' then 2 when 'processing' then 2 when 'running' then 2
          when 'completed' then 3 when 'failed' then 3 when 'cancelled' then 3 when 'canceled' then 3 when 'expired' then 3
          else 0
        end
      ) < (
        case lower(coalesce(status, ''))
          when 'queued' then 1 when 'pending' then 1
          when 'in_progress' then 2 when 'processing' then 2 when 'running' then 2
          when 'completed' then 3 when 'failed' then 3 when 'cancelled' then 3 when 'canceled' then 3 when 'expired' then 3
          else 0
        end
      ) then status
      else p_status
    end,
    meta = coalesce(meta, '{}'::jsonb) || coalesce(p_meta_patch, '{}'::jsonb),
    next_reconcile_at = case
      when p_update_next_reconcile then p_next_reconcile_at
      else next_reconcile_at
    end,
    updated_at = now()
  where workspace_id = p_workspace_id
    and kind = p_kind
    and internal_id = p_internal_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_set_async_operation_status"(uuid, text, text, text, jsonb, boolean, timestamp WITH time zone) TO "service_role";

