CREATE OR REPLACE FUNCTION public.gateway_usage_nonnegative_bigint (
  p_value numeric
)
  RETURNS bigint
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select greatest(coalesce(floor(p_value), 0), 0)::bigint;
$function$;

