-- source: supabase/schemas/public/functions/get_artificial_analysis_coverage.sql
CREATE OR REPLACE FUNCTION public.get_artificial_analysis_coverage()
RETURNS TABLE (benchmark_id text, total_models bigint, published boolean)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = ''
AS $function$
  WITH publications AS (
    SELECT DISTINCT ON (major_version) major_version, methodology_version
    FROM public.artificial_analysis_snapshots ORDER BY major_version, fetched_at DESC
  )
  SELECT b.benchmark_id, count(DISTINCT r.model_slug), s.major_version IS NOT NULL
  FROM public.v2_benchmarks b
  LEFT JOIN publications s ON s.major_version = substring(b.benchmark_id FROM '-v([1-9][0-9]*)$')::integer
  LEFT JOIN public.v2_benchmark_results r ON r.benchmark_id = b.benchmark_id
    AND (r.effective_to IS NULL OR r.effective_to > now())
    AND r.score_numeric IS NOT NULL
    AND r.score_numeric NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric)
    AND (s.major_version IS NULL OR substring(r.other_info FROM 'Intelligence Index v([0-9]+\.[0-9]+(?:\.[0-9]+)?)') = s.methodology_version)
    AND EXISTS (SELECT 1 FROM public.v2_models m WHERE m.model_slug = r.model_slug AND m.hidden = false)
  WHERE b.benchmark_id LIKE 'aa-%' OR b.benchmark_id = 'artificial-analysis'
  GROUP BY b.benchmark_id, s.major_version;
$function$;

REVOKE ALL ON FUNCTION public.get_artificial_analysis_coverage() FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.get_artificial_analysis_coverage() TO service_role;

-- source: supabase/schemas/public/functions/get_artificial_analysis_public_models.sql
CREATE OR REPLACE FUNCTION public.get_artificial_analysis_public_models(
  p_model_slug text DEFAULT NULL, p_major integer DEFAULT NULL, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0
) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = ''
AS $function$
  WITH snapshot AS (
    SELECT * FROM public.artificial_analysis_public_snapshots
    WHERE p_major IS NULL OR major_version = p_major
    ORDER BY major_version DESC, fetched_at DESC LIMIT 1
  ), owners AS MATERIALIZED (
    SELECT jsonb_object_agg(owner.value->>'id', owner.value->>'model_id') AS by_source
    FROM snapshot s CROSS JOIN LATERAL jsonb_array_elements(s.payload->'matching'->'sources') owner
  ), source_models AS MATERIALIZED (
    SELECT m.value - 'sourceData' AS data, m.value->>'id' AS source_id
    FROM snapshot s CROSS JOIN LATERAL jsonb_array_elements(s.payload->'models') m
  ), visible AS (
    SELECT m.data || jsonb_build_object('model_id', model.model_slug) AS data, m.source_id
    FROM source_models m CROSS JOIN owners owner
    JOIN public.v2_models model ON model.model_slug = owner.by_source->>m.source_id AND NOT coalesce(model.hidden, false)
    WHERE p_model_slug IS NULL OR model.model_slug = p_model_slug
  )
  SELECT jsonb_build_object(
    'snapshot_id', s.snapshot_id, 'methodology_version', s.methodology_version, 'fetched_at', s.fetched_at,
    'source_url', s.payload->>'sourceUrl', 'total', (SELECT count(*) FROM visible),
    'models', coalesce((SELECT jsonb_agg(page.data ORDER BY page.source_id) FROM (
      SELECT * FROM visible ORDER BY source_id LIMIT greatest(1, least(coalesce(p_limit, 50), 200)) OFFSET greatest(0, least(coalesce(p_offset, 0), 10000))
    ) page), '[]'::jsonb)
  ) FROM snapshot s;
$function$;

REVOKE ALL ON FUNCTION public.get_artificial_analysis_public_models(text, integer, integer, integer) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.get_artificial_analysis_public_models(text, integer, integer, integer) TO service_role;

-- source: supabase/schemas/public/functions/get_benchmark_result_rankings.sql
CREATE OR REPLACE FUNCTION public.get_benchmark_result_rankings (
  p_benchmark_ids       text[]  DEFAULT NULL::text[],
  p_model_id            text    DEFAULT NULL::text,
  p_include_hidden      boolean DEFAULT false,
  p_limit_per_benchmark integer DEFAULT NULL::integer
)
  RETURNS TABLE (
    result_id           uuid,
    model_id            text,
    benchmark_id        text,
    score               text,
    score_numeric       numeric,
    is_self_reported    boolean,
    other_info          text,
    source_link         text,
    created_at          timestamp with time zone,
    updated_at          timestamp with time zone,
    occur_idx           integer,
    variant             text,
    result_key          text,
    benchmark_rank      bigint,
    total_ranked_models bigint,
    is_primary_result   boolean,
    model_name          text,
    release_date        timestamp with time zone,
    announcement_date   timestamp with time zone,
    organisation_id     text,
    organisation_name   text,
    organisation_colour text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with target_benchmarks as (
    select
      b.id,
      b.ascending_order,
      b.type
    from private.v2_rpc_benchmarks_compat b
    where
      (p_benchmark_ids is null or b.id = any (p_benchmark_ids))
      and (
        p_model_id is null
        or exists (
          select 1
          from private.v2_rpc_benchmark_results_compat requested_result
          where requested_result.benchmark_id = b.id
            and requested_result.model_id = p_model_id
        )
      )
  ),
  scoped_results as (
    select
      result.*,
      model.name as model_name,
      model.release_date,
      model.announcement_date,
      model.organisation_id,
      organisation.name as organisation_name,
      organisation.colour as organisation_colour,
      target.ascending_order,
      case
        when target.type = 'percentage'
          and abs(result.score_numeric) > 0
          and abs(result.score_numeric) <= 1
          then result.score_numeric * 100
        else result.score_numeric
      end as comparable_score
    from target_benchmarks target
    join private.v2_rpc_benchmark_results_compat result
      on result.benchmark_id = target.id
    join private.v2_rpc_models_compat model
      on model.model_id = result.model_id
    left join private.v2_rpc_labs_compat organisation
      on organisation.organisation_id = model.organisation_id
    where p_include_hidden or not coalesce(model.hidden, false)
  ),
  model_scores as (
    select
      scoped.benchmark_id,
      scoped.model_id,
      bool_or(scoped.ascending_order is false) as lower_is_better,
      case
        when bool_or(scoped.ascending_order is false)
          then min(scoped.comparable_score)
        else max(scoped.comparable_score)
      end as primary_score
    from scoped_results scoped
    where scoped.comparable_score is not null
    group by scoped.benchmark_id, scoped.model_id
  ),
  ranked_models as (
    select
      scores.benchmark_id,
      scores.model_id,
      scores.primary_score,
      rank() over (
        partition by scores.benchmark_id
        order by
          case when scores.lower_is_better then scores.primary_score end asc nulls last,
          case when not scores.lower_is_better then scores.primary_score end desc nulls last
      ) as benchmark_rank,
      count(*) over (
        partition by scores.benchmark_id
      ) as total_ranked_models
    from model_scores scores
  ),
  selected_models as (
    select
      roster.benchmark_id,
      roster.model_id,
      ranked.primary_score,
      ranked.benchmark_rank,
      ranked.total_ranked_models
    from (
      select distinct scoped.benchmark_id, scoped.model_id
      from scoped_results scoped
    ) roster
    left join ranked_models ranked
      on ranked.benchmark_id = roster.benchmark_id
     and ranked.model_id = roster.model_id
    where
      (p_model_id is null or roster.model_id = p_model_id)
      and (
        p_limit_per_benchmark is null
        or ranked.benchmark_rank <= greatest(p_limit_per_benchmark, 1)
      )
  )
  select
    scoped.id as result_id,
    scoped.model_id,
    scoped.benchmark_id,
    scoped.score,
    scoped.score_numeric,
    scoped.is_self_reported,
    scoped.other_info,
    scoped.source_link,
    scoped.created_at,
    scoped.updated_at,
    scoped.occur_idx,
    scoped.variant,
    scoped.result_key,
    ranked.benchmark_rank,
    ranked.total_ranked_models,
    ranked.primary_score is not null
      and scoped.comparable_score is not distinct from ranked.primary_score
      as is_primary_result,
    scoped.model_name,
    scoped.release_date,
    scoped.announcement_date,
    scoped.organisation_id,
    scoped.organisation_name,
    scoped.organisation_colour
  from scoped_results scoped
  join selected_models ranked
    on ranked.benchmark_id = scoped.benchmark_id
   and ranked.model_id = scoped.model_id
  order by
    scoped.benchmark_id,
    ranked.benchmark_rank,
    scoped.model_id,
    scoped.occur_idx,
    scoped.id;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_benchmark_result_rankings"(text[], text, boolean, integer) TO "service_role";

