-- source: supabase/schemas/public/functions/get_public_tool_call_timeseries.sql
CREATE OR REPLACE FUNCTION public.get_public_tool_call_timeseries (
  p_time_range  text    DEFAULT 'year'::text,
  p_bucket_size text    DEFAULT 'week'::text,
  p_top_n       integer DEFAULT 10
)
  RETURNS TABLE (
    bucket   timestamp with time zone,
    model_id text,
    requests bigint,
    tokens   bigint,
    colour   text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with bounds as (
    select case p_time_range
      when 'today' then current_date
      when 'week' then current_date - 7
      when 'month' then current_date - 30
      when 'year' then current_date - 365
      else current_date - 365
    end as since_date
  ),
  top_models as (
    select usage.model_slug
    from public.reporting_usage_daily usage
    cross join bounds
    where usage.usage_date >= bounds.since_date
      and usage.tool_call_count > 0
      and lower(usage.model_slug) not in ('unknown', 'other')
    group by usage.model_slug
    order by sum(usage.tool_call_count) desc, usage.model_slug
    limit greatest(1, least(coalesce(p_top_n, 10), 100))
  )
  select
    (
      case p_bucket_size
        when 'day' then date_trunc('day', usage.usage_date::timestamp)
        else date_trunc('week', usage.usage_date::timestamp)
      end at time zone 'UTC'
    ) as bucket,
    usage.model_slug as model_id,
    sum(usage.tool_call_count)::bigint as requests,
    0::bigint as tokens,
    null::text as colour
  from public.reporting_usage_daily usage
  join top_models on top_models.model_slug = usage.model_slug
  cross join bounds
  where usage.usage_date >= bounds.since_date
    and usage.tool_call_count > 0
  group by 1, usage.model_slug
  order by 1, sum(usage.tool_call_count) desc, usage.model_slug;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_public_tool_call_timeseries"(text, text, integer) TO "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_public_tool_call_timeseries"(text, text, integer) TO "service_role";

COMMENT ON FUNCTION "public"."get_public_tool_call_timeseries"(text, text, integer) IS 'Privacy-safe tool-call counts by canonical model and day/week from V2 public usage rollups.';

REVOKE ALL ON FUNCTION "public"."get_public_tool_call_timeseries"(text, text, integer) FROM PUBLIC;

-- source: supabase/schemas/public/functions/get_public_top_apps_rolling.sql
create or replace function public.get_public_top_apps_rolling(
  p_limit integer default 20, p_time_range text default 'week', p_as_of timestamptz default now()
)
returns table (app_id text, app_name text, requests bigint, tokens bigint, unique_models integer)
language plpgsql stable security invoker set search_path = ''
as $$
declare
  v_from timestamptz;
begin
  v_from := case p_time_range
    when 'today' then (p_as_of at time zone 'UTC')::date::timestamp at time zone 'UTC'
    when '24h' then p_as_of - interval '24 hours'
    when 'week' then p_as_of - interval '168 hours'
    when '4w' then p_as_of - interval '672 hours'
    when 'month' then p_as_of - interval '720 hours'
    when 'year' then p_as_of - interval '8760 hours'
  end;
  if v_from is null or p_as_of is null then raise exception 'Invalid ranking period'; end if;
  if v_from = p_as_of then return; end if;
  return query
  with eligible_usage as (
    select public.api_app_url_group_key(a.url, a.id::text) as url_group,
      a.id::text as member_id, a.title as member_name, a.last_seen,
      u.model_id, u.requests, public.public_ranking_metric_value('tokens', u.meters) as tokens
    from public.get_public_ranking_usage_window(v_from, p_as_of) u
    join public.api_apps a on a.id = u.app_id and a.is_public = true and a.is_active = true
  ), member_totals as (
    select e.url_group, e.member_id, e.member_name, e.last_seen,
      sum(e.requests) as requests, sum(e.tokens) as tokens
    from eligible_usage e group by e.url_group, e.member_id, e.member_name, e.last_seen
  ), representatives as (
    select distinct on (m.url_group) m.url_group, m.member_id, m.member_name
    from member_totals m order by m.url_group, m.tokens desc, m.requests desc, m.last_seen desc nulls last, m.member_id
  ), totals as (
    select e.url_group, sum(e.requests)::bigint as requests, sum(e.tokens)::bigint as tokens,
      count(distinct e.model_id)::integer as models
    from eligible_usage e group by e.url_group
  )
  select r.member_id, r.member_name, t.requests, t.tokens, t.models
  from totals t join representatives r on r.url_group = t.url_group
  order by t.tokens desc, t.requests desc, r.member_id
  limit greatest(1, least(coalesce(p_limit, 20), 100));
end;
$$;

revoke all on function public.get_public_top_apps_rolling(integer, text, timestamptz) from public;

grant execute on function public.get_public_top_apps_rolling(integer, text, timestamptz) to service_role;

-- source: supabase/schemas/public/functions/get_public_top_apps.sql
CREATE OR REPLACE FUNCTION public.get_public_top_apps (
  p_limit      integer DEFAULT 20,
  p_time_range text    DEFAULT 'week'::text
)
  RETURNS TABLE (
    app_id        text,
    app_name      text,
    requests      bigint,
    tokens        bigint,
    unique_models integer
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_today date := (now() at time zone 'utc')::date;
  v_since date;
begin
  case p_time_range
    when 'today' then v_since := v_today;
    when 'week' then v_since := v_today - 7;
    when '4w' then v_since := v_today - 28;
    when 'month' then v_since := v_today - 30;
    else v_since := v_today - 7;
  end case;

  return query
  with eligible_usage as (
    select
      public.api_app_url_group_key(aa.url, aa.id::text) as url_group,
      aa.id::text as member_id,
      aa.title as member_name,
      aa.last_seen,
      d.model_id,
      d.requests,
      d.tokens
    from public.v2_rpc_public_app_model_usage_daily d
    join public.api_apps aa on aa.id::text = d.app_id
    where d.day_bucket >= v_since
      and aa.is_public = true
      and aa.is_active = true
  ),
  member_totals as (
    select
      url_group,
      member_id,
      member_name,
      last_seen,
      sum(eligible_usage.requests)::bigint as member_requests,
      sum(eligible_usage.tokens)::bigint as member_tokens
    from eligible_usage
    group by
      eligible_usage.url_group,
      eligible_usage.member_id,
      eligible_usage.member_name,
      eligible_usage.last_seen
  ),
  representatives as (
    select distinct on (url_group)
      url_group,
      member_id,
      member_name
    from member_totals
    order by
      url_group,
      member_tokens desc,
      member_requests desc,
      last_seen desc nulls last,
      member_id
  ),
  group_totals as (
    select
      url_group,
      sum(eligible_usage.requests)::bigint as request_count,
      sum(eligible_usage.tokens)::bigint as token_count,
      count(distinct eligible_usage.model_id)::integer as model_count
    from eligible_usage
    group by eligible_usage.url_group
  )
  select
    representatives.member_id,
    representatives.member_name,
    group_totals.request_count,
    group_totals.token_count,
    group_totals.model_count
  from group_totals
  join representatives using (url_group)
  order by group_totals.token_count desc, group_totals.request_count desc
  limit greatest(p_limit, 1);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_public_top_apps"(integer, text) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_public_top_apps"(integer, text) TO "service_role";

COMMENT ON FUNCTION "public"."get_public_top_apps"(integer, text) IS 'Ranks active public apps by combined usage for each normalized public app URL.';

-- source: supabase/schemas/public/functions/get_public_top_models_with_metadata.sql
CREATE OR REPLACE FUNCTION public.get_public_top_models_with_metadata (
  p_time_range text    DEFAULT 'week'::text,
  p_limit      integer DEFAULT 6
)
  RETURNS TABLE (
    model_id          text,
    model_name        text,
    organisation_id   text,
    organisation_name text,
    total_tokens      bigint
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_since timestamptz;
  v_now timestamptz := now();
begin
  case p_time_range
    when 'today' then
      v_since := date_trunc('day', v_now);
    when 'week' then
      v_since := v_now - interval '7 days';
    when 'month' then
      v_since := date_trunc('month', v_now);
    else
      v_since := v_now - interval '7 days';
  end case;

  return query
  with base_requests as (
    select
      gr.provider,
      gr.model_id as raw_model_id,
      public.gateway_usage_total_tokens(gr.usage) as tokens
    from private.v2_rpc_gateway_requests_compat gr
    where gr.created_at >= v_since
      and gr.model_id is not null
      and gr.provider is not null
      and gr.provider <> ''
  ),
  resolved as (
    select
      br.raw_model_id,
      br.tokens,
      public.resolve_public_model_id(br.raw_model_id, br.provider) as canonical_model_id
    from base_requests br
  ),
  enriched as (
    select
      coalesce(r.canonical_model_id, r.raw_model_id) as resolved_model_id,
      coalesce(dm.name, r.raw_model_id) as resolved_model_name,
      coalesce(dm.organisation_id, org_guess.organisation_id) as resolved_org_id,
      coalesce(org.name, org_guess.name) as resolved_org_name,
      r.tokens
    from resolved r
    left join private.v2_rpc_models_compat dm
      on dm.model_id = r.canonical_model_id
    left join private.v2_rpc_labs_compat org
      on org.organisation_id = dm.organisation_id
    left join lateral (
      select o.organisation_id, o.name
      from private.v2_rpc_labs_compat o
      where lower(o.organisation_id) = lower(split_part(r.raw_model_id, '/', 1))
         or lower(o.name) = lower(split_part(r.raw_model_id, '/', 1))
      order by
        case
          when lower(o.organisation_id) = lower(split_part(r.raw_model_id, '/', 1))
            then 0
          else 1
        end
      limit 1
    ) org_guess on true
  ),
  aggregated as (
    select
      e.resolved_model_id,
      max(e.resolved_model_name) as resolved_model_name,
      max(e.resolved_org_id) as resolved_org_id,
      max(e.resolved_org_name) as resolved_org_name,
      sum(e.tokens)::bigint as summed_tokens
    from enriched e
    where e.tokens >= 0
    group by e.resolved_model_id
  )
  select
    a.resolved_model_id as model_id,
    a.resolved_model_name as model_name,
    a.resolved_org_id as organisation_id,
    a.resolved_org_name as organisation_name,
    a.summed_tokens as total_tokens
  from aggregated a
  order by a.summed_tokens desc
  limit greatest(1, p_limit);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_public_top_models_with_metadata"(text, integer) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_public_top_models_with_metadata"(text, integer) TO "service_role";

COMMENT ON FUNCTION "public"."get_public_top_models_with_metadata"(text, integer) IS 'Public top models by token usage resolved to canonical API model ids with metadata enrichment.';

-- source: supabase/schemas/public/functions/get_public_trending_apps.sql
CREATE OR REPLACE FUNCTION public.get_public_trending_apps (
  p_limit           integer DEFAULT 20,
  p_min_week_tokens bigint  DEFAULT 0
)
  RETURNS TABLE (
    app_id               text,
    app_name             text,
    current_week_tokens  bigint,
    previous_week_tokens bigint,
    growth_tokens        bigint,
    growth_pct           numeric
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_today date := (now() at time zone 'utc')::date;
begin
  return query
  with eligible_usage as (
    select
      public.api_app_url_group_key(aa.url, aa.id::text) as url_group,
      aa.id::text as member_id,
      aa.title as member_name,
      aa.last_seen,
      d.day_bucket,
      d.tokens
    from public.v2_rpc_public_app_model_usage_daily d
    join public.api_apps aa on aa.id::text = d.app_id
    where d.day_bucket >= v_today - 14
      and aa.is_public = true
      and aa.is_active = true
  ),
  member_totals as (
    select
      url_group,
      member_id,
      member_name,
      last_seen,
      sum(eligible_usage.tokens)::bigint as member_tokens
    from eligible_usage
    group by
      eligible_usage.url_group,
      eligible_usage.member_id,
      eligible_usage.member_name,
      eligible_usage.last_seen
  ),
  representatives as (
    select distinct on (url_group)
      url_group,
      member_id,
      member_name
    from member_totals
    order by
      url_group,
      member_tokens desc,
      last_seen desc nulls last,
      member_id
  ),
  weekly as (
    select
      url_group,
      sum(eligible_usage.tokens) filter (
        where eligible_usage.day_bucket >= v_today - 7
      )::bigint as week_0_tokens,
      sum(eligible_usage.tokens) filter (
        where eligible_usage.day_bucket >= v_today - 14
          and eligible_usage.day_bucket < v_today - 7
      )::bigint as week_1_tokens
    from eligible_usage
    group by eligible_usage.url_group
  )
  select
    representatives.member_id,
    representatives.member_name,
    coalesce(weekly.week_0_tokens, 0)::bigint,
    coalesce(weekly.week_1_tokens, 0)::bigint,
    (coalesce(weekly.week_0_tokens, 0) - coalesce(weekly.week_1_tokens, 0))::bigint,
    case
      when coalesce(weekly.week_1_tokens, 0) > 0 then
        round(
          (
            (coalesce(weekly.week_0_tokens, 0) - coalesce(weekly.week_1_tokens, 0))::numeric
            / weekly.week_1_tokens::numeric
          ) * 100,
          2
        )
      when coalesce(weekly.week_0_tokens, 0) > 0 then null
      else 0
    end
  from weekly
  join representatives using (url_group)
  where coalesce(weekly.week_0_tokens, 0) > coalesce(weekly.week_1_tokens, 0)
    and coalesce(weekly.week_0_tokens, 0) >= p_min_week_tokens
  order by
    (coalesce(weekly.week_0_tokens, 0) - coalesce(weekly.week_1_tokens, 0)) desc,
    coalesce(weekly.week_0_tokens, 0) desc
  limit greatest(p_limit, 1);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_public_trending_apps"(integer, bigint) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_public_trending_apps"(integer, bigint) TO "service_role";

