-- source: supabase/schemas/public/functions/get_public_trending_models.sql
CREATE OR REPLACE FUNCTION public.get_public_trending_models (
  p_limit        integer DEFAULT 20,
  p_min_requests integer DEFAULT 0
)
  RETURNS TABLE (
    model_id               text,
    provider               text,
    current_week_requests  bigint,
    previous_week_requests bigint,
    two_weeks_ago_requests bigint,
    velocity               numeric,
    momentum_score         numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with weekly as (
    select usage.model_slug, coalesce(route.provider_slug,'unknown') as provider,
      sum(usage.requests) filter (where usage.usage_date >= current_date - 7)::bigint as week_0,
      sum(usage.requests) filter (where usage.usage_date >= current_date - 14 and usage.usage_date < current_date - 7)::bigint as week_1,
      sum(usage.requests) filter (where usage.usage_date >= current_date - 21 and usage.usage_date < current_date - 14)::bigint as week_2
    from public.reporting_usage_daily usage
    left join public.v2_model_provider_routes route on route.provider_model_id = usage.provider_model_id
    where usage.usage_date >= current_date - 21 and lower(usage.model_slug) not in ('unknown','other')
    group by usage.model_slug, coalesce(route.provider_slug,'unknown')
  )
  select model_slug, provider, coalesce(week_0,0), coalesce(week_1,0), coalesce(week_2,0),
    ((coalesce(week_0,0)-coalesce(week_1,0))-(coalesce(week_1,0)-coalesce(week_2,0)))::numeric,
    (((coalesce(week_0,0)-coalesce(week_1,0))-(coalesce(week_1,0)-coalesce(week_2,0)))*2.0 + (coalesce(week_0,0)-coalesce(week_1,0)))::numeric
  from weekly
  where coalesce(week_0,0) >= p_min_requests and coalesce(week_0,0) > coalesce(week_1,0)
  order by 7 desc limit greatest(1, least(coalesce(p_limit,20),100));
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_public_trending_models"(integer, integer) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_public_trending_models"(integer, integer) TO "service_role";

-- source: supabase/schemas/public/functions/get_public_unique_user_timeseries.sql
CREATE OR REPLACE FUNCTION public.get_public_unique_user_timeseries (
  p_time_range  text    DEFAULT 'year'::text,
  p_bucket_size text    DEFAULT 'week'::text,
  p_top_n       integer DEFAULT 10
)
  RETURNS TABLE (
    bucket   timestamp with time zone,
    model_id text,
    requests bigint,
    tokens   bigint,
    users    bigint,
    colour   text
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
#variable_conflict use_column
declare
  v_since date;
begin
  case p_time_range
    when '24h' then v_since := (now() at time zone 'utc')::date - 1;
    when 'today' then v_since := (now() at time zone 'utc')::date;
    when 'week' then v_since := (now() at time zone 'utc')::date - 7;
    when 'month' then v_since := (now() at time zone 'utc')::date - 30;
    when 'year' then v_since := (now() at time zone 'utc')::date - 365;
    else v_since := (now() at time zone 'utc')::date - 365;
  end case;

  return query
  with actor_rows as (
    select
      case
        when p_bucket_size = 'month' then date_trunc('month', d.day_bucket::timestamp)::timestamptz
        when p_bucket_size = 'day' then d.day_bucket::timestamptz
        else date_trunc('week', d.day_bucket::timestamp)::timestamptz
      end as time_bucket,
      d.model_id,
      d.actor_hash,
      sum(d.requests)::bigint as req_count,
      sum(d.tokens)::bigint as tok_count
    from public.reporting_model_user_usage_daily d
    where d.day_bucket >= v_since
      and lower(d.model_id) not in ('unknown', 'other')
    group by 1, 2, 3
  ),
  base as (
    select
      ar.time_bucket,
      ar.model_id,
      sum(ar.req_count)::bigint as req_count,
      sum(ar.tok_count)::bigint as tok_count,
      count(distinct ar.actor_hash)::bigint as user_count
    from actor_rows ar
    group by ar.time_bucket, ar.model_id
  ),
  ranked_base as (
    select
      b.*,
      row_number() over (
        partition by b.time_bucket
        order by b.user_count desc, b.tok_count desc, b.req_count desc, b.model_id
      ) as bucket_rank
    from base b
    where b.user_count > 0
  ),
  bucketed as (
    select
      ar.time_bucket,
      case
        when rb.bucket_rank <= greatest(p_top_n, 1) then ar.model_id
        else 'Other'
      end as model_group,
      sum(ar.req_count)::bigint as req_count,
      sum(ar.tok_count)::bigint as tok_count,
      count(distinct ar.actor_hash)::bigint as user_count
    from actor_rows ar
    left join ranked_base rb
      on rb.time_bucket = ar.time_bucket
      and rb.model_id = ar.model_id
    group by ar.time_bucket, model_group
  )
  select
    b.time_bucket as bucket,
    b.model_group as model_id,
    b.req_count as requests,
    b.tok_count as tokens,
    b.user_count as users,
    case
      when b.model_group = 'Other' then null
      else org.colour
    end as colour
  from bucketed b
  left join private.v2_rpc_models_compat dm on dm.model_id = b.model_group
  left join private.v2_rpc_labs_compat org on dm.organisation_id = org.organisation_id
  where b.user_count > 0
  order by b.time_bucket, b.user_count desc, b.tok_count desc;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_public_unique_user_timeseries"(text, text, integer) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_public_unique_user_timeseries"(text, text, integer) TO "service_role";

-- source: supabase/schemas/public/functions/get_public_usage_timeseries.sql
CREATE OR REPLACE FUNCTION public.get_public_usage_timeseries (
  p_time_range  text    DEFAULT 'week'::text,
  p_bucket_size text    DEFAULT 'hour'::text,
  p_top_n       integer DEFAULT 10
)
  RETURNS TABLE (
    bucket   timestamp with time zone,
    model_id text,
    requests bigint,
    tokens   bigint,
    colour   text
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
#variable_conflict use_column
declare
  v_since date;
begin
  case p_time_range
    when '24h' then v_since := (now() at time zone 'utc')::date - 1;
    when 'today' then v_since := (now() at time zone 'utc')::date;
    when 'week' then v_since := (now() at time zone 'utc')::date - 7;
    when 'month' then v_since := (now() at time zone 'utc')::date - 30;
    when 'year' then v_since := (now() at time zone 'utc')::date - 365;
    else v_since := (now() at time zone 'utc')::date - 7;
  end case;
  return query
  with base as (
    select
      case
        when p_bucket_size = 'month' then date_trunc('month', d.day_bucket::timestamp)::timestamptz
        when p_bucket_size = 'week' then date_trunc('week', d.day_bucket::timestamp)::timestamptz
        else d.day_bucket::timestamptz
      end as time_bucket,
      d.model_id,
      sum(d.requests)::bigint as req_count,
      sum(d.total_tokens)::bigint as tok_count
    from public.v2_rpc_gateway_model_usage_daily d
    where d.day_bucket >= v_since
    group by 1, 2
  ),
  ranked_base as (
    select
      b.*,
      row_number() over (
        partition by b.time_bucket
        order by b.tok_count desc, b.req_count desc, b.model_id
      ) as bucket_rank
    from base b
    where lower(b.model_id) not in ('unknown', 'other')
      and b.tok_count > 0
  ),
  bucketed as (
    select
      b.time_bucket,
      case
        when rb.bucket_rank <= greatest(p_top_n, 1) then b.model_id
        else 'Other'
      end as model_group,
      sum(b.req_count)::bigint as req_count,
      sum(b.tok_count)::bigint as tok_count
    from base b
    left join ranked_base rb
      on rb.time_bucket = b.time_bucket
      and rb.model_id = b.model_id
    where lower(b.model_id) <> 'unknown'
      and b.tok_count > 0
    group by b.time_bucket, model_group
  )
  select
    b.time_bucket as bucket,
    b.model_group as model_id,
    b.req_count as requests,
    b.tok_count as tokens,
    case
      when b.model_group = 'Other' then null
      else org.colour
    end as colour
  from bucketed b
  left join private.v2_rpc_models_compat dm on dm.model_id = b.model_group
  left join private.v2_rpc_labs_compat org on dm.organisation_id = org.organisation_id
  where b.tok_count > 0
  order by b.time_bucket, b.tok_count desc;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_public_usage_timeseries"(text, text, integer) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_public_usage_timeseries"(text, text, integer) TO "service_role";

-- source: supabase/schemas/public/functions/get_release_gaps_by_org.sql
CREATE OR REPLACE FUNCTION public.get_release_gaps_by_org (
  p_iso text DEFAULT NULL::text
)
  RETURNS TABLE (
    organisation_id   text,
    organisation_name text,
    country_code      text,
    releases          integer,
    median_gap_days   numeric,
    p90_gap_days      numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
with org_models as (
    select
        m.organisation_id,
        coalesce(o.name, m.organisation_id) as organisation_name,
        coalesce(o.country_code, '') as country_code,
        coalesce(m.release_date, m.announcement_date)::date as d
    from private.v2_rpc_models_compat m
    join private.v2_rpc_labs_compat o on o.organisation_id = m.organisation_id
    where coalesce(m.release_date, m.announcement_date) is not null
      and (p_iso is null or lower(o.country_code) = lower(p_iso))
    group by m.organisation_id, organisation_name, country_code, d
),
ordered as (
    select
        organisation_id,
        organisation_name,
        country_code,
        d,
        lead(d) over(partition by organisation_id order by d) as next_d
    from org_models
),
gaps as (
    select
        organisation_id,
        organisation_name,
        country_code,
        (next_d - d)::numeric as gap_days
    from ordered
    where next_d is not null
      and next_d > d -- ignore zero/negative gaps
      and (next_d - d) >= 1 -- ignore sub-day gaps
)
select
    organisation_id,
    organisation_name,
    country_code,
    (select count(*) from org_models om where om.organisation_id = gaps.organisation_id)::int as releases,
    percentile_cont(0.5) within group (order by gap_days) as median_gap_days,
    percentile_cont(0.9) within group (order by gap_days) as p90_gap_days
from gaps
group by organisation_id, organisation_name, country_code
order by median_gap_days nulls last;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_release_gaps_by_org"(text) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_release_gaps_by_org"(text) TO "service_role";

-- source: supabase/schemas/public/functions/get_requested_model_last_used_by_workspace.sql
CREATE OR REPLACE FUNCTION public.get_requested_model_last_used_by_workspace (
  p_model_slugs  text[],
  p_since        timestamp with time zone,
  p_workspace_id uuid DEFAULT NULL::uuid
)
  RETURNS TABLE (
    workspace_id uuid,
    model_slug   text,
    last_used_at timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  -- Keyed on the model the caller asked for, not the one we routed to, so a
  -- workspace still calling a deprecated model is found even when another
  -- model served the request.
  select
    fact.workspace_id,
    fact.requested_model_slug as model_slug,
    max(fact.occurred_at) as last_used_at
  from public.v2_request_facts fact
  where fact.requested_model_slug = any (p_model_slugs)
    and fact.occurred_at >= p_since
    and (p_workspace_id is null or fact.workspace_id = p_workspace_id)
  group by fact.workspace_id, fact.requested_model_slug;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_requested_model_last_used_by_workspace"(text[], timestamp WITH time zone, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_requested_model_last_used_by_workspace"(text[], timestamp WITH time zone, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_slack_agent_model_spend.sql
CREATE OR REPLACE FUNCTION public.get_slack_agent_model_spend (
  p_workspace_id uuid,
  p_periods      date[]
)
  RETURNS TABLE (
    installation_id uuid,
    period_start    date,
    requests        bigint,
    cost_nanos      bigint
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
-- What each of a workspace's Slack agent installations spent on models through
-- its managed key, per UTC month, for up to 12 months given as their first days.
-- Summed here from the 15-minute rollup so the settings page never adds up rows.
-- These are normal requests billed from credits, not part of the agent's own
-- monthly charge. Uninstalling deletes the key but keeps key_id, so past months
-- still count. A month without spend has no row. Service role only: the account
-- route checks the caller is an owner or admin first.
begin
  if p_workspace_id is null or p_periods is null then
    raise exception 'invalid_periods' using errcode = '22023';
  end if;
  if cardinality(p_periods) > 12 then
    raise exception 'too_many_periods' using errcode = '22023';
  end if;
  if exists (
    select 1 from unnest(p_periods) as given(period_start)
    where given.period_start is null or extract(day from given.period_start) <> 1
  ) then
    raise exception 'invalid_periods' using errcode = '22023';
  end if;

  return query
  select installation.id,
    period.period_start,
    sum(usage.requests)::bigint,
    sum(usage.cost_nanos)::bigint
  from public.slack_installations installation
  cross join (select distinct given.period_start from unnest(p_periods) as given(period_start)) period
  -- Served by the (workspace_id, bucket_start, ...) unique index, one month at a time.
  join public.v2_private_usage_15m usage
    on usage.workspace_id = p_workspace_id
    and usage.bucket_start >= period.period_start::timestamp at time zone 'UTC'
    and usage.bucket_start < (period.period_start + interval '1 month') at time zone 'UTC'
    and usage.key_id = installation.key_id
  where installation.workspace_id = p_workspace_id
    and installation.key_id is not null
  group by installation.id, period.period_start
  order by period.period_start desc, installation.id;
end;
$function$;

COMMENT ON FUNCTION "public"."get_slack_agent_model_spend"(uuid, date[]) IS 'Model spend and requests through each Slack agent installation''s managed key, per UTC month for up to 12 given months, summed in the database from v2_private_usage_15m. Billed from credits as normal requests, separately from the Slack agent charge. For the settings page; service role only.';

GRANT EXECUTE ON FUNCTION "public"."get_slack_agent_model_spend"(uuid, date[]) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_slack_agent_model_spend"(uuid, date[]) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_slack_agent_month_usage.sql
CREATE OR REPLACE FUNCTION public.get_slack_agent_month_usage (
  p_installation_id uuid,
  p_period_start    date
)
  RETURNS TABLE (
    people  integer,
    answers bigint
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- People answered and their pooled answers for one installation and UTC month,
  -- counted here so the settings page never sums rows itself. Served by the
  -- primary key (installation_id, period_start, slack_user_id).
  select count(*)::integer, coalesce(sum(person.answers), 0)::bigint
  from public.slack_agent_monthly_people person
  where person.installation_id = p_installation_id
    and person.period_start = p_period_start;
$function$;

COMMENT ON FUNCTION "public"."get_slack_agent_month_usage"(uuid, date) IS 'People the Slack agent answered and their pooled answers for one installation and UTC month, for the settings page.';

