-- source: supabase/schemas/public/functions/get_v2_model_overview.sql
CREATE OR REPLACE FUNCTION public.get_v2_model_overview (
  p_model_slug   text,
  p_region       text DEFAULT NULL::text,
  p_service_tier text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'pg_catalog', 'public'
  AS $function$
  with overview as materialized (
    select public.get_v2_model_overview_without_stealth_redaction(
      p_model_slug,
      p_region,
      p_service_tier
    ) as payload
  ), redacted as (
    select
      overview.payload,
      coalesce(routes.items, '[]'::jsonb) as routes
    from overview
    left join lateral (
      select jsonb_agg(case when route.is_stealth = true then
        (route_item.item - 'variant_id' - 'variant_key') || jsonb_build_object(
          'provider_model_id', 'stealth:' || lower(trim(overview.payload->>'model_id')),
          'provider_slug', 'stealth',
          'provider_name', 'stealth',
          'provider_model_slug', lower(trim(overview.payload->>'model_id')),
          'execution_region', null,
          'data_region', null
        )
        else route_item.item end) as items
      from jsonb_array_elements(
        coalesce(overview.payload->'routes', '[]'::jsonb)
      ) as route_item(item)
      left join public.v2_model_provider_routes route
        on route.provider_model_id = route_item.item->>'provider_model_id'
    ) routes on true
  )
  select case
    when redacted.payload is null or jsonb_typeof(redacted.payload) <> 'object'
      then redacted.payload
    else redacted.payload || jsonb_build_object(
      'routes', redacted.routes,
      'regions', coalesce((
        select jsonb_agg(distinct lower(region.value) order by lower(region.value))
        from jsonb_array_elements(redacted.routes) as route_item(item)
        cross join lateral (values
          (nullif(item->>'execution_region', '')),
          (nullif(item->>'data_region', ''))
        ) as region(value)
        where region.value is not null
      ), '[]'::jsonb)
    )
  end
  from redacted;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_v2_model_overview"(text, text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_v2_model_overview"(text, text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_v2_model_performance_colos_unfiltered.sql
CREATE OR REPLACE FUNCTION public.get_v2_model_performance_colos_unfiltered (
  p_model_slug text
)
  RETURNS TABLE (
    cloudflare_colo text,
    request_count   bigint
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select
    upper(trim(usage.cloudflare_colo)) as cloudflare_colo,
    sum(usage.requests)::bigint as request_count
  from public.reporting_usage_hourly usage
  where usage.model_slug = lower(trim(p_model_slug))
    and usage.cloudflare_colo is not null
    and usage.bucket_start >= now() - interval '30 days'
  group by upper(trim(usage.cloudflare_colo))
  order by request_count desc, cloudflare_colo asc;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_v2_model_performance_colos_unfiltered"(text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_v2_model_performance_colos_unfiltered"(text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_v2_model_performance_colos.sql
CREATE OR REPLACE FUNCTION public.get_v2_model_performance_colos (
  p_model_slug text
)
  RETURNS TABLE (
    cloudflare_colo text,
    request_count   bigint
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
select colos.*
from public.v2_models model
cross join lateral public.get_v2_model_performance_colos_unfiltered(model.model_slug) colos
where model.model_slug = lower(trim(p_model_slug))
  and model.hidden = false
  and model.status <> 'disabled'
  and colos.request_count >= 20;
$function$;

