-- source: supabase/schemas/public/functions/get_v2_model_quality_hourly_v1.sql
CREATE OR REPLACE FUNCTION public.get_v2_model_quality_hourly_v1 (
  p_model_slug      text,
  p_cloudflare_colo text DEFAULT NULL::text,
  p_stream_mode     text DEFAULT 'all'::text,
  p_context_bucket  text DEFAULT 'all'::text
)
  RETURNS TABLE (
    bucket                            timestamp with time zone,
    requests                          bigint,
    tool_call_responses               bigint,
    tool_call_errors                  bigint,
    tool_invalid_json_errors          bigint,
    tool_schema_mismatch_errors       bigint,
    tool_unknown_name_errors          bigint,
    structured_output_responses       bigint,
    structured_output_errors          bigint,
    structured_invalid_json_errors    bigint,
    structured_schema_mismatch_errors bigint,
    structured_missing_output_errors  bigint,
    cache_telemetry_requests          bigint,
    input_tokens                      numeric,
    cached_read_tokens                numeric,
    cache_read_pct                    numeric
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
with params as not materialized (
  select
    lower(trim(p_model_slug)) model_slug,
    nullif(upper(trim(p_cloudflare_colo)), '') cloudflare_colo,
    case when lower(p_stream_mode) in ('stream', 'non_stream') then lower(p_stream_mode) else 'all' end stream_mode,
    case when lower(p_context_bucket) in ('lte_4k', '4k_16k', '16k_64k', 'gt_64k') then lower(p_context_bucket) else 'all' end context_bucket,
    now() now_ts
),
visible_model as (
  select model.model_slug
  from public.v2_models model
  cross join params
  where model.model_slug = params.model_slug
    and model.hidden = false
    and model.status <> 'disabled'
),
scoped_facts as (
  select
    fact.request_event_id,
    fact.workspace_id,
    fact.request_id,
    fact.gateway_request_id,
    fact.gateway_request_created_at,
    fact.occurred_at,
    fact.stream,
    fact.cloudflare_colo,
    fact.safe_metadata,
    fact.tool_call_count,
    fact.tool_call_succeeded,
    fact.structured_output_attempted,
    fact.structured_output_succeeded
  from public.reporting_request_facts fact
  join visible_model
    on visible_model.model_slug = coalesce(fact.routed_model_slug, fact.requested_model_slug)
  cross join params
  where fact.occurred_at >= params.now_ts - interval '7 days'
    and (params.cloudflare_colo is null or upper(trim(fact.cloudflare_colo)) = params.cloudflare_colo)
    and (params.stream_mode = 'all' or fact.stream = (params.stream_mode = 'stream'))
),
usage_by_request as (
  select
    fact.*,
    coalesce(
      meters.input_tokens,
      legacy.usage_input_tokens::numeric
    )::numeric input_tokens,
    coalesce(
      meters.cached_read_tokens,
      legacy.usage_cached_read_tokens::numeric
    )::numeric cached_read_tokens,
    coalesce(meters.cache_telemetry_observed, false) or legacy.request_id is not null cache_telemetry_observed
  from scoped_facts fact
  left join lateral (
    select
      coalesce(
        sum(usage.quantity) filter (where usage.meter_key = 'input_tokens'),
        sum(usage.quantity) filter (where usage.meter_key = 'prompt_tokens'),
        sum(usage.quantity) filter (
          where usage.meter_key in (
            'input_text_tokens',
            'input_image_tokens',
            'input_audio_tokens',
            'input_video_tokens'
          )
        )
      )::numeric input_tokens,
      sum(usage.quantity) filter (
        where usage.meter_key in ('cached_input_tokens', 'cached_read_tokens')
      )::numeric cached_read_tokens,
      bool_or(usage.meter_key in ('cached_input_tokens', 'cached_read_tokens')) cache_telemetry_observed
    from public.v2_request_usage usage
    where usage.request_event_id = fact.request_event_id
  ) meters on true
  -- Linked facts read their authoritative request by primary key, which prunes
  -- to one partition; only unlinked facts fall back to the nearest request.
  left join lateral (
    (
      select
        request.request_id,
        request.usage_input_tokens,
        request.usage_cached_read_tokens
      from public.gateway_requests request
      where fact.gateway_request_id is not null
        and request.id = fact.gateway_request_id
        and request.created_at = fact.gateway_request_created_at
        and request.workspace_id = fact.workspace_id
        and request.request_id = fact.request_id
    )
    union all
    (
      select
        request.request_id,
        request.usage_input_tokens,
        request.usage_cached_read_tokens
      from public.gateway_requests request
      where fact.gateway_request_id is null
        and request.workspace_id = fact.workspace_id
        and request.request_id = fact.request_id
      order by abs(extract(epoch from request.created_at - fact.occurred_at))
      limit 1
    )
    limit 1
  ) legacy on true
),
classified as (
  select
    date_trunc('hour', fact.occurred_at) bucket_start,
    fact.input_tokens,
    fact.cached_read_tokens,
    fact.cache_telemetry_observed,
    case
      when fact.safe_metadata #>> '{tool_call_validation,totalCalls}' ~ '^\d+$'
        then (fact.safe_metadata #>> '{tool_call_validation,totalCalls}')::bigint
      when fact.tool_call_count > 0 then fact.tool_call_count::bigint
      else 0
    end tool_call_responses,
    case
      when fact.safe_metadata #>> '{tool_call_validation,invalidCalls}' ~ '^\d+$'
        then (fact.safe_metadata #>> '{tool_call_validation,invalidCalls}')::bigint
      when fact.tool_call_count > 0 and fact.tool_call_succeeded = false
        then fact.tool_call_count::bigint
      else 0
    end tool_call_errors,
    case
      when fact.safe_metadata #>> '{tool_call_validation,invalidJson}' ~ '^\d+$'
        then (fact.safe_metadata #>> '{tool_call_validation,invalidJson}')::bigint
      else 0
    end tool_invalid_json_errors,
    case
      when fact.safe_metadata #>> '{tool_call_validation,schemaMismatch}' ~ '^\d+$'
        then (fact.safe_metadata #>> '{tool_call_validation,schemaMismatch}')::bigint
      else 0
    end tool_schema_mismatch_errors,
    case
      when fact.safe_metadata #>> '{tool_call_validation,unknownToolName}' ~ '^\d+$'
        then (fact.safe_metadata #>> '{tool_call_validation,unknownToolName}')::bigint
      else 0
    end tool_unknown_name_errors,
    coalesce(
      fact.safe_metadata ->> 'structured_output_error_reason',
      case
        when fact.structured_output_attempted and fact.structured_output_succeeded then 'none'
        when fact.structured_output_attempted then 'legacy_error'
        else null
      end
    ) structured_error_reason,
    case
      when fact.input_tokens is null then null
      else fact.input_tokens
    end context_input_tokens
  from usage_by_request fact
),
base as (
  select classified.*
  from classified
  cross join params
  where
    params.context_bucket = 'all'
    or (params.context_bucket = 'lte_4k' and classified.context_input_tokens <= 4096)
    or (params.context_bucket = '4k_16k' and classified.context_input_tokens > 4096 and classified.context_input_tokens <= 16384)
    or (params.context_bucket = '16k_64k' and classified.context_input_tokens > 16384 and classified.context_input_tokens <= 65536)
    or (params.context_bucket = 'gt_64k' and classified.context_input_tokens > 65536)
),
hourly as (
  select
    base.bucket_start,
    count(*)::bigint requests,
    sum(base.tool_call_responses)::bigint tool_call_responses,
    sum(base.tool_call_errors)::bigint tool_call_errors,
    sum(base.tool_invalid_json_errors)::bigint tool_invalid_json_errors,
    sum(base.tool_schema_mismatch_errors)::bigint tool_schema_mismatch_errors,
    sum(base.tool_unknown_name_errors)::bigint tool_unknown_name_errors,
    count(*) filter (
      where base.structured_error_reason in ('none', 'invalid_json', 'schema_mismatch', 'missing_output', 'legacy_error')
    )::bigint structured_output_responses,
    count(*) filter (
      where base.structured_error_reason in ('invalid_json', 'schema_mismatch', 'missing_output', 'legacy_error')
    )::bigint structured_output_errors,
    count(*) filter (where base.structured_error_reason = 'invalid_json')::bigint structured_invalid_json_errors,
    count(*) filter (where base.structured_error_reason = 'schema_mismatch')::bigint structured_schema_mismatch_errors,
    count(*) filter (where base.structured_error_reason = 'missing_output')::bigint structured_missing_output_errors,
    count(*) filter (where base.cache_telemetry_observed)::bigint cache_telemetry_requests,
    sum(base.input_tokens) filter (
      where base.cache_telemetry_observed and base.input_tokens > 0
    )::numeric input_tokens,
    sum(base.cached_read_tokens) filter (
      where base.cache_telemetry_observed and base.input_tokens > 0
    )::numeric cached_read_tokens
  from base
  group by base.bucket_start
)
select
  hourly.bucket_start bucket,
  hourly.requests,
  hourly.tool_call_responses,
  hourly.tool_call_errors,
  hourly.tool_invalid_json_errors,
  hourly.tool_schema_mismatch_errors,
  hourly.tool_unknown_name_errors,
  hourly.structured_output_responses,
  hourly.structured_output_errors,
  hourly.structured_invalid_json_errors,
  hourly.structured_schema_mismatch_errors,
  hourly.structured_missing_output_errors,
  hourly.cache_telemetry_requests,
  case when hourly.cache_telemetry_requests >= 20 then hourly.input_tokens else null end,
  case when hourly.cache_telemetry_requests >= 20 then hourly.cached_read_tokens else null end,
  case
    when hourly.cache_telemetry_requests >= 20 and hourly.input_tokens > 0
      then least(100, coalesce(hourly.cached_read_tokens, 0) * 100.0 / hourly.input_tokens)
    else null
  end cache_read_pct
from hourly
order by hourly.bucket_start;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_v2_model_quality_hourly_v1"(text, text, text, text) TO "service_role";

COMMENT ON FUNCTION "public"."get_v2_model_quality_hourly_v1"(text, text, text, text) IS 'Hourly tool-calling, structured-output, token, and cache aggregates, suppressed below twenty aggregated requests.';

REVOKE ALL ON FUNCTION "public"."get_v2_model_quality_hourly_v1"(text, text, text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_v2_model_resolution.sql
CREATE OR REPLACE FUNCTION public.get_v2_model_resolution (
  p_requested_slug text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with requested as (select lower(trim(p_requested_slug)) as slug),
  direct as (
    select model.model_slug
    from public.v2_models model, requested
    where model.model_slug = requested.slug
      and model.hidden = false and model.status <> 'disabled'
    limit 1
  ), alias as (
    select alias.model_slug
    from public.v2_model_aliases alias
    join public.v2_models model on model.model_slug = alias.model_slug
    cross join requested
    where alias.alias_slug = requested.slug and alias.enabled = true
      and (alias.effective_from is null or alias.effective_from <= now())
      and (alias.effective_to is null or alias.effective_to > now())
      and model.hidden = false and model.status <> 'disabled'
    limit 1
  ), route as (
    select route.model_slug
    from public.v2_model_provider_routes route
    join public.v2_models model on model.model_slug = route.model_slug
    cross join requested
    where (route.provider_model_id = requested.slug or route.provider_model_slug = requested.slug)
      and coalesce(route.is_stealth, false) = false
      and route.routing_enabled = true
      and route.status in ('active', 'degraded')
      and model.hidden = false and model.status <> 'disabled'
    order by route.status = 'active' desc, route.provider_model_id
    limit 1
  )
  select jsonb_build_object(
    'requestedModelId', p_requested_slug,
    'canonicalModelId', coalesce((select model_slug from direct), (select model_slug from alias), (select model_slug from route)),
    'internalModelId', coalesce((select model_slug from direct), (select model_slug from alias), (select model_slug from route)),
    'source', case
      when exists (select 1 from direct) then 'direct'
      when exists (select 1 from alias) then 'alias'
      when exists (select 1 from route) then 'provider_mapping'
      else 'unresolved'
    end
  );
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_v2_model_resolution"(text) TO "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_v2_model_resolution"(text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_v2_model_resolution"(text) FROM PUBLIC;

-- source: supabase/schemas/public/functions/get_v2_model_subscription_plans.sql
CREATE OR REPLACE FUNCTION public.get_v2_model_subscription_plans (
  p_model_slug text
)
  RETURNS TABLE (
    plan_uuid        uuid,
    plan_id          text,
    name             text,
    lab_slug         text,
    description      text,
    link             text,
    other_info       jsonb,
    created_at       timestamp with time zone,
    updated_at       timestamp with time zone,
    model_info       jsonb,
    rate_limit       jsonb,
    model_other_info jsonb,
    price            numeric,
    currency         text,
    frequency        text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select plan.plan_uuid, plan.plan_id, plan.name, plan.lab_slug, plan.description, plan.link,
    plan.other_info, plan.created_at, plan.updated_at, relation.model_info,
    relation.rate_limit, relation.other_info, plan.price, plan.currency, plan.frequency
  from public.v2_subscription_plan_models relation
  join public.v2_subscription_plans plan on plan.plan_uuid = relation.plan_uuid
  where relation.model_slug = lower(trim(p_model_slug))
    and (relation.effective_to is null or relation.effective_to > now())
    and (plan.effective_to is null or plan.effective_to > now())
  order by plan.plan_id, plan.frequency;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_v2_model_subscription_plans"(text) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_v2_model_subscription_plans"(text) TO "service_role";

-- source: supabase/schemas/public/functions/get_v2_model_usage_daily.sql
CREATE OR REPLACE FUNCTION public.get_v2_model_usage_daily (
  p_model_slug   text,
  p_provider_ids text[] DEFAULT NULL::text[],
  p_since        date   DEFAULT NULL::date,
  p_until        date   DEFAULT NULL::date
)
  RETURNS TABLE (
    day_bucket            date,
    model_id              text,
    provider_id           text,
    endpoint              text,
    requests              bigint,
    success_requests      bigint,
    failed_requests       bigint,
    neutral_requests      bigint,
    rate_limited_requests bigint,
    total_tokens          numeric,
    input_tokens          numeric,
    output_tokens         numeric,
    reasoning_tokens      numeric,
    cached_read_tokens    numeric,
    input_characters      numeric,
    output_characters     numeric,
    total_characters      numeric,
    image_inputs          numeric,
    image_outputs         numeric,
    audio_inputs          numeric,
    audio_outputs         numeric,
    video_inputs          numeric,
    video_outputs         numeric,
    total_cost_nanos      numeric,
    avg_latency_ms        numeric,
    avg_generation_ms     numeric,
    avg_throughput        numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with base as (
    select
      usage.usage_date as day_bucket,
      usage.model_slug as model_id,
      coalesce(route.provider_slug, usage.provider_model_id, '') as provider_id,
      usage.requests,
      usage.successful_requests as success_requests,
      usage.failed_requests,
      greatest(usage.requests - usage.successful_requests - usage.failed_requests, 0) as neutral_requests,
      usage.rate_limited_requests,
      0::numeric as total_cost_nanos,
      case when usage.latency_count > 0 then usage.latency_sum_ms::numeric / usage.latency_count else null end as avg_latency_ms,
      case when usage.generation_count > 0 then usage.generation_sum_ms::numeric / usage.generation_count else null end as avg_generation_ms,
      case when usage.throughput_count > 0 then usage.throughput_sum::numeric / usage.throughput_count else null end as avg_throughput,
      usage.rollup_id
    from public.reporting_usage_daily usage
    left join public.v2_model_provider_routes route on route.provider_model_id = usage.provider_model_id
    where usage.model_slug = lower(trim(p_model_slug))
      and (p_since is null or usage.usage_date >= p_since)
      and (p_until is null or usage.usage_date <= p_until)
      and (p_provider_ids is null or coalesce(route.provider_slug, usage.provider_model_id, '') = any(p_provider_ids))
  ),
  meters as (
    select rollup_id,
      sum(quantity) filter (where meter_key = 'input_tokens') as input_tokens,
      sum(quantity) filter (where meter_key = 'output_tokens') as output_tokens,
      sum(quantity) filter (where meter_key = 'reasoning_tokens') as reasoning_tokens,
      sum(quantity) filter (where meter_key = 'cached_input_tokens') as cached_read_tokens,
      sum(quantity) filter (where meter_key = 'input_characters') as input_characters,
      sum(quantity) filter (where meter_key = 'output_characters') as output_characters,
      sum(quantity) filter (where meter_key = 'image_inputs') as image_inputs,
      sum(quantity) filter (where meter_key = 'image_outputs') as image_outputs,
      sum(quantity) filter (where meter_key = 'audio_inputs') as audio_inputs,
      sum(quantity) filter (where meter_key = 'audio_outputs') as audio_outputs,
      sum(quantity) filter (where meter_key = 'video_inputs') as video_inputs,
      sum(quantity) filter (where meter_key = 'video_outputs') as video_outputs
    from public.v2_public_usage_daily_meters group by rollup_id
  )
  select b.day_bucket, b.model_id, b.provider_id, ''::text as endpoint,
    sum(b.requests)::bigint, sum(b.success_requests)::bigint, sum(b.failed_requests)::bigint,
    sum(b.neutral_requests)::bigint, sum(b.rate_limited_requests)::bigint,
    sum(coalesce(m.input_tokens, 0) + coalesce(m.output_tokens, 0) + coalesce(m.reasoning_tokens, 0)) as total_tokens,
    sum(coalesce(m.input_tokens, 0)), sum(coalesce(m.output_tokens, 0)), sum(coalesce(m.reasoning_tokens, 0)),
    sum(coalesce(m.cached_read_tokens, 0)), sum(coalesce(m.input_characters, 0)), sum(coalesce(m.output_characters, 0)),
    sum(coalesce(m.input_characters, 0) + coalesce(m.output_characters, 0)),
    sum(coalesce(m.image_inputs, 0)), sum(coalesce(m.image_outputs, 0)), sum(coalesce(m.audio_inputs, 0)), sum(coalesce(m.audio_outputs, 0)),
    sum(coalesce(m.video_inputs, 0)), sum(coalesce(m.video_outputs, 0)), sum(b.total_cost_nanos),
    case when sum(b.requests) > 0 then sum(b.avg_latency_ms * b.requests) / sum(b.requests) else null end,
    case when sum(b.requests) > 0 then sum(b.avg_generation_ms * b.requests) / sum(b.requests) else null end,
    case when sum(b.requests) > 0 then sum(b.avg_throughput * b.requests) / sum(b.requests) else null end
  from base b left join meters m on m.rollup_id = b.rollup_id
  group by b.day_bucket, b.model_id, b.provider_id
  order by b.day_bucket, b.provider_id;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_v2_model_usage_daily"(text, text[], date, date) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_v2_model_usage_daily"(text, text[], date, date) TO "service_role";

-- source: supabase/schemas/public/functions/get_v2_model_variants.sql
CREATE OR REPLACE FUNCTION public.get_v2_model_variants (
  p_model_slug text
)
  RETURNS TABLE (
    model_id     text,
    name         text,
    variant_kind text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with requested as (
    select coalesce(model.base_model_slug, model.model_slug) as base_model_slug
    from public.v2_models model
    where model.model_slug = lower(trim(p_model_slug))
      and model.hidden = false
      and model.status <> 'disabled'
  )
  select
    model.model_slug as model_id,
    model.name,
    model.variant_kind
  from public.v2_models model
  cross join requested
  where (
      model.model_slug = requested.base_model_slug
      or model.base_model_slug = requested.base_model_slug
    )
    and model.hidden = false
    and model.status <> 'disabled'
  order by
    case when model.variant_kind = 'standard' then 0 else 1 end,
    model.name,
    model.model_slug;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_v2_model_variants"(text) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_v2_model_variants"(text) TO "service_role";

COMMENT ON FUNCTION "public"."get_v2_model_variants"(text) IS 'Returns the visible base/free sibling identities for a canonical V2 model slug.';

-- source: supabase/schemas/public/functions/get_v2_provider_region_map.sql
CREATE OR REPLACE FUNCTION public.get_v2_provider_region_map (
  p_provider_slugs text[] DEFAULT NULL::text[]
)
  RETURNS TABLE (
    provider_slug text,
    regions       text[]
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select
    region.provider_slug,
    array_agg(distinct region.region_code order by region.region_code)
  from public.v2_provider_regions region
  where region.status <> 'disabled'
    and region.routing_enabled = true
    and (p_provider_slugs is null or region.provider_slug = any(p_provider_slugs))
  group by region.provider_slug;
$function$;

