-- source: supabase/schemas/public/functions/get_v2_public_models_page_rows_without_stealth_redaction.sql
CREATE OR REPLACE FUNCTION public.get_v2_public_models_page_rows_without_stealth_redaction (
  p_region       text DEFAULT NULL::text,
  p_service_tier text DEFAULT 'standard'::text
)
  RETURNS SETOF jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select
    page.payload || jsonb_build_object(
      'status', case
        when model.model_slug is null then null
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'rumoured' then 'Rumoured'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'announced' then 'Announced'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'preview' then 'Preview'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'available' then 'Available'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'limited_access' then 'Limited Access'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'deprecated' then 'Deprecated'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'retired' then 'Retired'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'withheld' then 'Withheld'
        else null
      end,
      'deprecation_date', model.deprecated_at,
      'retirement_date', model.retired_at,
      'removal_date', model.removal_date
    )
  from public.get_v2_public_models_page_rows_without_lifecycle(p_region, p_service_tier) as page(payload)
  left join lateral (
    select candidate.*
    from public.v2_models candidate
    where candidate.model_slug in (
      page.payload->>'model_id',
      case
        when page.payload->>'model_id' like '%:free'
          then left(page.payload->>'model_id', -5)
        else page.payload->>'model_id'
      end
    )
    order by (candidate.model_slug = page.payload->>'model_id') desc
    limit 1
  ) model on true;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_v2_public_models_page_rows_without_stealth_redaction"(text, text) TO "service_role";

COMMENT ON FUNCTION "public"."get_v2_public_models_page_rows_without_stealth_redaction"(text, text) IS 'SQL-owned public model catalogue projection with route metadata and model lifecycle fields.';

REVOKE ALL ON FUNCTION "public"."get_v2_public_models_page_rows_without_stealth_redaction"(text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_v2_public_models_page_rows.sql
CREATE OR REPLACE FUNCTION public.get_v2_public_models_page_rows (
  p_region       text DEFAULT NULL::text,
  p_service_tier text DEFAULT 'standard'::text
)
  RETURNS SETOF jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'pg_catalog', 'public'
  AS $function$
  with pages as (
    select page.payload
    from public.get_v2_public_models_page_rows_without_stealth_redaction(
      p_region,
      p_service_tier
    ) as page(payload)
  ), redacted as (
    select
      pages.payload,
      coalesce(details.items, '[]'::jsonb) as provider_details
    from pages
    left join lateral (
      select jsonb_agg(distinct case
        when exists (
          select 1
          from public.v2_model_provider_routes route
          where route.is_stealth = true
            and route.model_slug = pages.payload->>'model_id'
            and route.provider_slug = detail.item->>'id'
            and coalesce(route.provider_model_slug, '') = coalesce(detail.item->>'provider_model_slug', '')
        ) then detail.item || jsonb_build_object(
          'id', 'stealth',
          'name', 'stealth',
          'provider_model_slug', pages.payload->>'model_id',
          'execution_region', null,
          'data_region', null
        )
        else detail.item
      end) as items
      from jsonb_array_elements(
        coalesce(pages.payload->'gateway_provider_details', '[]'::jsonb)
      ) as detail(item)
    ) details on true
  )
  select redacted.payload || jsonb_build_object(
    'organisation_colour', coalesce(nullif(lab.colour, ''), nullif(lab.metadata->>'colour', '')),
    'gateway_provider_details', redacted.provider_details,
    'gateway_provider_names', coalesce((
      select to_jsonb(array_agg(distinct item->>'name' order by item->>'name'))
      from jsonb_array_elements(redacted.provider_details) as detail(item)
      where nullif(item->>'name', '') is not null
    ), '[]'::jsonb),
    'gateway_active_provider_names', coalesce((
      select to_jsonb(array_agg(distinct item->>'name' order by item->>'name'))
      from jsonb_array_elements(redacted.provider_details) as detail(item)
      where item->>'is_active' = 'true'
        and nullif(item->>'name', '') is not null
    ), '[]'::jsonb),
    'gateway_api_model_ids', coalesce((
      select to_jsonb(array_agg(distinct item->>'provider_model_slug' order by item->>'provider_model_slug'))
      from jsonb_array_elements(redacted.provider_details) as detail(item)
      where nullif(item->>'provider_model_slug', '') is not null
    ), '[]'::jsonb),
    'gateway_execution_regions', coalesce((
      select to_jsonb(array_agg(
        distinct lower(coalesce(nullif(item->>'execution_region', ''), nullif(item->>'data_region', '')))
        order by lower(coalesce(nullif(item->>'execution_region', ''), nullif(item->>'data_region', '')))
      ))
      from jsonb_array_elements(redacted.provider_details) as detail(item)
      where coalesce(nullif(item->>'execution_region', ''), nullif(item->>'data_region', '')) is not null
    ), '[]'::jsonb),
    'gateway_provider_count', coalesce((
      select count(distinct item->>'id')
      from jsonb_array_elements(redacted.provider_details) as detail(item)
      where nullif(item->>'id', '') is not null
    ), 0),
    'gateway_active_provider_count', coalesce((
      select count(distinct item->>'id')
      from jsonb_array_elements(redacted.provider_details) as detail(item)
      where item->>'is_active' = 'true'
        and nullif(item->>'id', '') is not null
    ), 0)
  )
  from redacted
  left join public.v2_labs lab on lab.lab_slug = redacted.payload->>'organisation_id';
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_v2_public_models_page_rows"(text, text) TO "service_role";

COMMENT ON FUNCTION "public"."get_v2_public_models_page_rows"(text, text) IS 'Service-only public model catalogue projection with stealth redaction and exact-variant lifecycle fields.';

REVOKE ALL ON FUNCTION "public"."get_v2_public_models_page_rows"(text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_v2_routing_candidates_raw.sql
CREATE OR REPLACE FUNCTION public.get_v2_routing_candidates_raw (
  p_model_slug    text,
  p_capability_id text DEFAULT NULL::text,
  p_region        text DEFAULT NULL::text,
  p_service_tier  text DEFAULT 'standard'::text
)
  RETURNS TABLE (
    provider_model_id   text,
    provider_slug       text,
    provider_name       text,
    model_slug          text,
    provider_model_slug text,
    variant_id          uuid,
    service_tier_slug   text,
    execution_region    text,
    data_region         text,
    route_status        text,
    provider_status     text,
    capability_status   text,
    routing_enabled     boolean
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select
    route.provider_model_id,
    route.provider_slug,
    provider.name,
    route.model_slug,
    route.provider_model_slug,
    variant.variant_id,
    variant.service_tier_slug,
    variant.execution_region,
    variant.data_region,
    route.status,
    provider.status,
    coalesce(capability.status, 'active'),
    route.routing_enabled and provider.routing_enabled and variant.routing_enabled
  from public.v2_model_provider_routes route
  join public.v2_providers provider on provider.provider_slug = route.provider_slug
  join public.v2_route_variants variant on variant.provider_model_id = route.provider_model_id
  left join lateral (
    select capability.status
    from public.v2_route_capabilities capability
    where capability.provider_model_id = route.provider_model_id
      and (p_capability_id is null or capability.capability_id = p_capability_id)
    order by case when capability.status = 'active' then 0 else 1 end, capability.capability_id
    limit 1
  ) capability on true
  where route.model_slug = lower(p_model_slug)
    and route.status in ('active', 'degraded')
    and provider.status not in ('disabled', 'deprecated')
    and variant.status in ('active', 'degraded')
    and (route.effective_from is null or route.effective_from <= now())
    and (route.effective_to is null or route.effective_to > now())
    and (
      route.provider_availability_status in ('available', 'preview', 'limited_access')
      or (
        route.provider_availability_status = 'deprecated'
        and route.effective_to is not null
        and route.effective_to > now()
      )
    )
    and (
      p_capability_id is null
      or capability.status = 'active'
      or (
        capability.status = 'degraded'
        and route.provider_availability_status = 'deprecated'
        and route.effective_to is not null
        and route.effective_to > now()
      )
    )
    and (p_service_tier is null or variant.service_tier_slug = lower(p_service_tier))
    and (
      p_region is null
      or lower(p_region) = lower(coalesce(variant.execution_region, ''))
      or lower(p_region) = lower(coalesce(variant.data_region, ''))
    )
  order by (route.routing_enabled and provider.routing_enabled and variant.routing_enabled) desc,
    case route.status when 'active' then 0 else 1 end,
    provider.name,
    route.provider_model_id;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_v2_routing_candidates_raw"(text, text, text, text) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_v2_routing_candidates_raw"(text, text, text, text) TO "service_role";

COMMENT ON FUNCTION "public"."get_v2_routing_candidates_raw"(text, text, text, text) IS 'Internal routing candidate query with provider/model, region, tier, capability, and status gates evaluated in SQL.';

REVOKE ALL ON FUNCTION "public"."get_v2_routing_candidates_raw"(text, text, text, text) FROM PUBLIC, "anon";

-- source: supabase/schemas/public/functions/get_v2_routing_candidates.sql
CREATE OR REPLACE FUNCTION public.get_v2_routing_candidates (
  p_model_slug    text,
  p_capability_id text DEFAULT NULL::text,
  p_region        text DEFAULT NULL::text,
  p_service_tier  text DEFAULT 'standard'::text
)
  RETURNS TABLE (
    provider_model_id   text,
    provider_slug       text,
    provider_name       text,
    model_slug          text,
    provider_model_slug text,
    variant_id          uuid,
    service_tier_slug   text,
    execution_region    text,
    data_region         text,
    route_status        text,
    provider_status     text,
    capability_status   text,
    routing_enabled     boolean
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select distinct on (candidate.provider_model_id, candidate.variant_id)
    candidate.provider_model_id,
    candidate.provider_slug,
    candidate.provider_name,
    candidate.model_slug,
    candidate.provider_model_slug,
    candidate.variant_id,
    candidate.service_tier_slug,
    candidate.execution_region,
    candidate.data_region,
    candidate.route_status,
    candidate.provider_status,
    candidate.capability_status,
    candidate.routing_enabled
  from public.get_v2_routing_candidates_raw(p_model_slug, p_capability_id, p_region, p_service_tier) candidate
  where candidate.provider_status not in ('disabled', 'deprecated')
    and (
      candidate.provider_status <> 'external'
      or exists (
        select 1
        from public.v2_model_provider_routes route_override
        where route_override.provider_model_id = candidate.provider_model_id
          and route_override.provider_slug = candidate.provider_slug
          and route_override.routing_enabled = true
          and coalesce(route_override.metadata->>'external_routing_override', 'false') = 'true'
      )
    )
  order by candidate.provider_model_id, candidate.variant_id, candidate.routing_enabled desc, candidate.capability_status;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_v2_routing_candidates"(text, text, text, text) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_v2_routing_candidates"(text, text, text, text) TO "service_role";

-- source: supabase/schemas/public/functions/get_v2_subscription_catalogue.sql
create function public.get_v2_subscription_catalogue(p_plan_id text default null,p_model_slug text default null,p_include_hidden boolean default false)
returns setof jsonb language sql stable security invoker set search_path=public,pg_temp as $$
select to_jsonb(p)-'price'-'currency'-'frequency' || jsonb_build_object(
  'organisation_id',p.lab_slug,
  'organisation',case when l.lab_slug is null then null else jsonb_build_object('organisation_id',l.lab_slug,'name',l.name,'colour',l.metadata->>'colour') end,
  'offers',coalesce((select jsonb_agg(to_jsonb(o)||jsonb_build_object('components',coalesce((select jsonb_agg(to_jsonb(c) order by c.starts_at_cycle,c.component_key)
    from v2_subscription_offer_prices c where c.offer_uuid=o.offer_uuid and c.effective_from<=now() and (c.effective_to is null or c.effective_to>now())),'[]'::jsonb)) order by o.billing_interval,o.billing_interval_count,o.offer_uuid)
    from v2_subscription_plan_offers o where o.plan_uuid=p.plan_uuid and o.effective_from<=now() and (o.effective_to is null or o.effective_to>now())),'[]'::jsonb),
  'features',coalesce((select jsonb_agg(to_jsonb(f) order by f.feature_name) from v2_subscription_plan_features f where f.plan_uuid=p.plan_uuid and f.effective_from<=now() and (f.effective_to is null or f.effective_to>now())),'[]'::jsonb),
  'allowances',coalesce((select jsonb_agg(to_jsonb(a) order by a.allowance_key) from v2_subscription_plan_allowances a where a.plan_uuid=p.plan_uuid and a.effective_from<=now() and (a.effective_to is null or a.effective_to>now()) and (a.offer_uuid is null or exists(select 1 from v2_subscription_plan_offers o where o.offer_uuid=a.offer_uuid and o.effective_from<=now() and (o.effective_to is null or o.effective_to>now())))),'[]'::jsonb),
  'models',coalesce((select jsonb_agg(to_jsonb(m)||jsonb_build_object('model_id',m.model_slug,'model',jsonb_build_object('model_id',v.model_slug,'name',v.name,'organisation_id',v.lab_slug,'organisation_name',ml.name)) order by m.model_slug)
    from v2_subscription_plan_models m join v2_models v on v.model_slug=m.model_slug left join v2_labs ml on ml.lab_slug=v.lab_slug
    where m.plan_uuid=p.plan_uuid and (not v.hidden or p_include_hidden) and m.effective_from<=now() and (m.effective_to is null or m.effective_to>now())),'[]'::jsonb))
from v2_subscription_plans p left join v2_labs l on l.lab_slug=p.lab_slug
where p.status='active' and p.effective_from<=now() and (p.effective_to is null or p.effective_to>now())
  and (not p_include_hidden or current_user in ('postgres','service_role'))
  and (p_plan_id is null or p.plan_id=p_plan_id)
  and (p_model_slug is null or exists(select 1 from v2_subscription_plan_models m join v2_models v on v.model_slug=m.model_slug
    where m.plan_uuid=p.plan_uuid and m.model_slug=p_model_slug and (not v.hidden or p_include_hidden) and m.effective_from<=now() and (m.effective_to is null or m.effective_to>now())))
order by p.name,p.plan_id;
$$;

revoke all on function public.get_v2_subscription_catalogue(text,text,boolean) from public;

grant execute on function public.get_v2_subscription_catalogue(text,text,boolean) to anon,authenticated,service_role;

-- source: supabase/schemas/public/functions/get_workspace_credit_ledger_net.sql
CREATE OR REPLACE FUNCTION public.get_workspace_credit_ledger_net (
  p_workspace_id uuid,
  p_since        timestamp with time zone
)
  RETURNS bigint
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
-- Net change in the workspace's credit ledger since p_since: credits added (top-ups, codes)
-- count as positive and charges as negative. GET /v1/credits reports it as
-- thirty_day_usage. Summed here so no PostgREST row cap can truncate the total.
-- Service role only: the route checks the management key's workspace before calling it.
select coalesce(sum(ledger.amount_nanos), 0)::bigint
from public.credit_ledger ledger
where ledger.workspace_id = p_workspace_id
  and ledger.created_at >= p_since;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_workspace_credit_ledger_net"(uuid, timestamp WITH time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_workspace_credit_ledger_net"(uuid, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_workspace_key_spend.sql
CREATE OR REPLACE FUNCTION public.get_workspace_key_spend (
  p_workspace_id uuid,
  p_from         date,
  p_to           date
)
  RETURNS TABLE (
    key_id     uuid,
    key_name   text,
    key_prefix text,
    requests   bigint,
    cost_nanos bigint
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
-- A workspace's requests and spend per API key between two inclusive UTC dates,
-- summed here from the 15-minute rollup, the 100 keys that cost the most first.
-- A null key_id is usage without a key (for example the web chat). Unlike
-- get_workspace_key_usage, which checks the signed-in member and only counts
-- since one day, this takes any range and is for the service role only: the
-- Slack agent checks the asker is a linked member first.
begin
  if p_workspace_id is null or p_from is null or p_to is null or p_from > p_to then
    raise exception 'invalid_range' using errcode = '22023';
  end if;
  if p_to - p_from > 366 then
    raise exception 'range_too_long' using errcode = '22023';
  end if;

  return query
  select usage.key_id,
    api_key.name,
    api_key.prefix,
    sum(usage.requests)::bigint,
    sum(usage.cost_nanos)::bigint
  from public.v2_private_usage_15m usage
  left join public.keys api_key on api_key.id = usage.key_id and api_key.workspace_id = p_workspace_id
  -- Served by the (workspace_id, bucket_start, ...) unique index.
  where usage.workspace_id = p_workspace_id
    and usage.bucket_start >= p_from::timestamp at time zone 'UTC'
    and usage.bucket_start < (p_to + 1)::timestamp at time zone 'UTC'
  group by usage.key_id, api_key.name, api_key.prefix
  order by sum(usage.cost_nanos) desc, usage.key_id nulls last
  limit 100;
end;
$function$;

COMMENT ON FUNCTION "public"."get_workspace_key_spend"(uuid, date, date) IS 'A workspace''s requests and spend per API key between two inclusive UTC dates, summed in the database from v2_private_usage_15m (top 100 keys). For the Slack agent''s usage tools; service role only.';

GRANT EXECUTE ON FUNCTION "public"."get_workspace_key_spend"(uuid, date, date) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_workspace_key_spend"(uuid, date, date) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_workspace_key_usage.sql
CREATE OR REPLACE FUNCTION public.get_workspace_key_usage (
  p_workspace_id uuid,
  p_day_start    timestamp with time zone
)
  RETURNS TABLE (
    key_id              uuid,
    daily_request_count bigint,
    daily_cost_nanos    bigint,
    last_used_at        timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  select
    gr.key_id,
    count(*) filter (where gr.created_at >= p_day_start)::bigint as daily_request_count,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= p_day_start), 0)::bigint as daily_cost_nanos,
    max(gr.created_at) as last_used_at
  from private.v2_rpc_gateway_requests_compat gr
  where gr.workspace_id = p_workspace_id
    and gr.key_id is not null
    and gr.success is true
    and public.is_workspace_member(p_workspace_id)
  group by gr.key_id;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_workspace_key_usage"(uuid, timestamp WITH time zone) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_workspace_key_usage"(uuid, timestamp WITH time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_workspace_key_usage"(uuid, timestamp WITH time zone) FROM PUBLIC, "anon";

-- source: supabase/schemas/public/functions/get_workspace_model_last_used.sql
CREATE OR REPLACE FUNCTION public.get_workspace_model_last_used (
  p_team_id uuid,
  p_since   timestamp with time zone
)
  RETURNS TABLE (
    model_id     text,
    last_used_at timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select
    gr.model_id::text as model_id,
    max(gr.created_at) as last_used_at
  from private.v2_rpc_gateway_requests_compat gr
  where gr.team_id = p_team_id
    and gr.created_at >= p_since
    and gr.model_id is not null
    and gr.model_id <> ''
    and public.is_workspace_member(p_team_id)
  group by gr.model_id
  order by last_used_at desc;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_workspace_model_last_used"(uuid, timestamp WITH time zone) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_workspace_model_last_used"(uuid, timestamp WITH time zone) TO "service_role";

-- source: supabase/schemas/public/functions/get_workspace_model_successor_overview.sql
CREATE OR REPLACE FUNCTION public.get_workspace_model_successor_overview (
  p_workspace_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare v_rows jsonb := '[]'::jsonb; r record; v_resolution jsonb; v_replacement text; v_price jsonb;
begin
  -- What retired model routing does for this workspace's models: those it
  -- asked for in the last 90 days that are deprecated, retired or no longer
  -- served, and those it set its own replacement for. Each row uses the
  -- gateway's own resolvers, so it matches what a request would get today.
  -- Keyed on the requested model, so requests already redirected still count.
  for r in
    with lifecycle as (
      select m.model_slug
      from public.v2_models m
      left join public.v2_model_successor_routing s on s.model_slug=m.model_slug
      where not m.hidden
        and (m.status in ('deprecated','retired') or m.retired_at is not null or s.unserved_since is not null)
    ), used as (
      select f.requested_model_slug as model_slug, max(f.occurred_at) as last_used_at, count(*) as requests
      from public.v2_request_facts f
      where f.workspace_id=p_workspace_id
        and f.occurred_at >= now() - interval '90 days'
        and f.requested_model_slug in (select model_slug from lifecycle)
      group by f.requested_model_slug
    ), overrides as (
      select o.model_slug, o.successor_model_slug
      from public.workspace_model_successor_overrides o
      where o.workspace_id=p_workspace_id
    ), candidates as (
      select coalesce(u.model_slug, o.model_slug) as model_slug, u.last_used_at, coalesce(u.requests, 0) as requests,
        o.model_slug is not null as has_override, o.successor_model_slug as override_successor
      from used u
      full join overrides o on o.model_slug=u.model_slug
    )
    select c.*, m.name, m.status, m.deprecated_at, m.retired_at, m.replacement_model_slug,
      s.unserved_since,
      coalesce(s.auto_route_enabled and s.approved_successor_slug is not distinct from m.replacement_model_slug, false) as approved
    from candidates c
    join public.v2_models m on m.model_slug=c.model_slug and not m.hidden
    left join public.v2_model_successor_routing s on s.model_slug=c.model_slug
    order by c.last_used_at desc nulls last, c.model_slug
    limit 200
  loop
    v_price := null;
    if r.has_override and r.override_successor is null then
      v_resolution := jsonb_build_object('reason', 'never', 'target', null);
      v_replacement := null;
    elsif r.has_override then
      v_resolution := public.gateway_resolve_workspace_model_successor(r.model_slug, r.override_successor);
      v_replacement := r.override_successor;
    else
      v_resolution := public.gateway_resolve_model_successor(r.model_slug);
      v_replacement := case when r.approved then r.replacement_model_slug end;
    end if;
    v_replacement := coalesce(v_resolution->>'target', v_replacement);
    -- Before the model stops being served there is no target yet, so price the
    -- replacement it would get.
    if v_resolution->>'target' is null and v_replacement is not null then
      v_price := public.v2_model_successor_price_ratio(r.model_slug, v_replacement);
    end if;

    v_rows := v_rows || jsonb_build_object(
      'model', r.model_slug,
      'name', r.name,
      'status', r.status,
      'deprecated_at', r.deprecated_at,
      'retired_at', r.retired_at,
      'unserved_since', r.unserved_since,
      'last_used_at', r.last_used_at,
      'requests', r.requests,
      'suggested_replacement', r.replacement_model_slug,
      'approved', r.approved,
      'workspace_override', r.has_override,
      'replacement', v_replacement,
      'replacement_name', (select name from public.v2_models where model_slug=v_replacement),
      'target', v_resolution->>'target',
      'reason', v_resolution->>'reason',
      'price_ratio', coalesce((v_price->>'ratio')::numeric, (v_resolution->>'price_ratio')::numeric),
      'price_comparable', coalesce((v_price->>'comparable')::boolean, (v_resolution->>'price_comparable')::boolean, false),
      'price_skipped_meters', coalesce(v_price->'skipped_meters', v_resolution->'price_skipped_meters', '[]'::jsonb),
      -- Requests for this model another model answered in the last 30 days.
      'served_by', coalesce((
        select jsonb_agg(jsonb_build_object('model', x.routed_model_slug, 'requests', x.requests, 'last_at', x.last_at) order by x.requests desc)
        from (
          select f.routed_model_slug, count(*) as requests, max(f.occurred_at) as last_at
          from public.v2_request_facts f
          where f.workspace_id=p_workspace_id
            and f.requested_model_slug=r.model_slug
            and f.occurred_at >= now() - interval '30 days'
            and f.success
            and f.routed_model_slug is not null
            and f.routed_model_slug<>r.model_slug
          group by f.routed_model_slug
        ) x
      ), '[]'::jsonb));
  end loop;
  return v_rows;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."get_workspace_model_successor_overview"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_workspace_model_successor_overview"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_workspace_recent_credit_spend.sql
CREATE OR REPLACE FUNCTION public.get_workspace_recent_credit_spend (
  p_workspace_id uuid,
  p_since        timestamp with time zone
)
  RETURNS bigint
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
-- Credits actually charged to the workspace's wallet since p_since, for the billing runway.
-- Requests record their wallet charge in gateway_request_charges; async jobs and realtime
-- sessions record theirs as credit_ledger charges instead. The two never overlap.
-- Service role only: the account route checks workspace membership before calling it.
select (
  coalesce((
    select sum(charge.cost_nanos)
    from public.gateway_request_charges charge
    where charge.workspace_id = p_workspace_id
      and charge.status = 'applied'
      and charge.created_at >= p_since
  ), 0)
  + coalesce((
    select sum(-ledger.amount_nanos)
    from public.credit_ledger ledger
    where ledger.workspace_id = p_workspace_id
      and ledger.kind = 'charge'
      and ledger.amount_nanos < 0
      and ledger.created_at >= p_since
  ), 0)
)::bigint;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_workspace_recent_credit_spend"(uuid, timestamp WITH time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_workspace_recent_credit_spend"(uuid, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_workspace_spend_block_entry.sql
CREATE OR REPLACE FUNCTION public.get_workspace_spend_block_entry (
  p_workspace_id uuid,
  p_now          timestamp with time zone DEFAULT now()
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- The compact entry the gateway enforces spend blocks from (KV spend-blocks:v1:{workspace}),
  -- or null when the workspace has nothing active, so the publisher deletes the key:
  --   * blocks: active blocks that have not reached their reset;
  --   * warnings: enabled block rules past their last warn threshold this period (every
  --     threshold_percents value, or threshold_amount_nanos) without an active block, i.e. in
  --     the grace margin. Requests they cover get the x-phaseo-spend-warning header;
  --   * departments: for each department scope above, who counts toward it, so the gateway can
  --     match a request without Postgres (private.spend_scope_departments as of now):
  --       keys          standard keys whose own department is this one (always count);
  --       users         actors (key creators, OAuth users) whose departments include it;
  --       exclude_keys  standard keys of those users that belong to another department.
  --     A request counts when its key is in keys, or its key is not in exclude_keys and its
  --     actor is in users.
  --   * expires_at: the earliest reset, which the KV entry's expiry must not pass.
  with blocks as (
    select block.id, block.rule_id, coalesce(rule.name, 'Deleted spend rule') as rule_name, block.scope_type, block.scope_id,
      block.resets_at, block.block_free_models, block.limit_nanos
    from public.workspace_spend_blocks block
    left join public.workspace_spend_rules rule on rule.id = block.rule_id
    where block.workspace_id = p_workspace_id
      and block.lifted_at is null
      and (block.resets_at is null or block.resets_at > p_now)
  ),
  warnings as (
    select rule.id as rule_id, rule.name as rule_name, rule.scope_type, rule.scope_id, state.period_end as resets_at, rule.block_free_models
    from public.workspace_spend_rules rule
    join public.workspace_spend_rule_state state
      on state.rule_id = rule.id
      and state.period_start <= p_now
      and state.period_end > p_now
    where rule.workspace_id = p_workspace_id
      and rule.enabled
      and rule.deleted_at is null
      and rule.action = 'block'
      and private.spend_rule_evaluable(rule.metric, rule.period, rule.base_kind)
      and case rule.metric
        when 'spend' then state.amount_fired_at is not null
        when 'budget_percent' then state.highest_percent_fired >= (select max(threshold) from unnest(rule.threshold_percents) threshold)
        else false
      end
      and not exists (select 1 from blocks where blocks.rule_id = rule.id)
  ),
  department_ids as materialized (
    select distinct lower(item.scope_id)::uuid as id
    from (select scope_type, scope_id from blocks union all select scope_type, scope_id from warnings) item
    where item.scope_type = 'department'
      and item.scope_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  actor_departments as materialized (
    select candidate.user_id, scope.department_id
    from (
      select grant_row.user_id from public.workspace_department_grants grant_row where grant_row.workspace_id = p_workspace_id
      union
      select override.user_id from public.workspace_member_overrides override
      where override.workspace_id = p_workspace_id and override.department_override_enabled
    ) candidate
    cross join lateral private.spend_scope_departments(p_workspace_id, null, candidate.user_id) scope(department_id)
    where exists (select 1 from department_ids)
  ),
  departments as (
    select department_ids.id,
      coalesce((
        select jsonb_agg(key.id order by key.id) from public.keys key
        where key.workspace_id = p_workspace_id and key.key_kind = 'standard' and key.department_id = department_ids.id
          and key.status <> 'deleted'
      ), '[]'::jsonb) as keys,
      coalesce((
        select jsonb_agg(actor.user_id order by actor.user_id) from actor_departments actor
        where actor.department_id = department_ids.id
      ), '[]'::jsonb) as users,
      coalesce((
        select jsonb_agg(key.id order by key.id) from public.keys key
        where key.workspace_id = p_workspace_id and key.key_kind = 'standard'
          and key.department_id is not null and key.department_id <> department_ids.id
          and key.status <> 'deleted'
          and key.created_by in (select actor.user_id from actor_departments actor where actor.department_id = department_ids.id)
      ), '[]'::jsonb) as exclude_keys
    from department_ids
  )
  select case when exists (select 1 from blocks) or exists (select 1 from warnings) then jsonb_build_object(
    'v', 1,
    'workspace_id', p_workspace_id,
    'generated_at', p_now,
    'expires_at', (select min(item.resets_at) from (select resets_at from blocks union all select resets_at from warnings) item),
    'blocks', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', blocks.id,
        'rule_id', blocks.rule_id,
        'rule_name', left(blocks.rule_name, 100),
        'scope_type', blocks.scope_type,
        'scope_id', blocks.scope_id,
        'resets_at', blocks.resets_at,
        'block_free_models', blocks.block_free_models,
        'limit_nanos', blocks.limit_nanos
      ) order by blocks.resets_at nulls last, blocks.id)
      from blocks
    ), '[]'::jsonb),
    'warnings', coalesce((
      select jsonb_agg(jsonb_build_object(
        'rule_id', warnings.rule_id,
        'rule_name', left(warnings.rule_name, 100),
        'scope_type', warnings.scope_type,
        'scope_id', warnings.scope_id,
        'resets_at', warnings.resets_at,
        'block_free_models', warnings.block_free_models
      ) order by warnings.resets_at, warnings.rule_id)
      from warnings
    ), '[]'::jsonb),
    'departments', coalesce((
      select jsonb_object_agg(departments.id, jsonb_build_object(
        'keys', departments.keys, 'users', departments.users, 'exclude_keys', departments.exclude_keys))
      from departments
    ), '{}'::jsonb)
  ) end;
$function$;

COMMENT ON FUNCTION "public"."get_workspace_spend_block_entry"(uuid, timestamp with time zone) IS 'The gateway''s spend block entry for a workspace (active blocks, grace-margin warnings and department membership for department scopes), or null when nothing is active. Published to KV spend-blocks:v1:{workspace} by the API. Service role only.';

REVOKE ALL ON FUNCTION "public"."get_workspace_spend_block_entry"(uuid, timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_workspace_spend_block_entry"(uuid, timestamp with time zone) TO "service_role";

-- source: supabase/schemas/public/functions/get_workspace_spend_buckets.sql
CREATE OR REPLACE FUNCTION public.get_workspace_spend_buckets (
  p_workspace_id uuid,
  p_from         date,
  p_to           date,
  p_bucket       text DEFAULT 'day'::text,
  p_group_by     text DEFAULT 'none'::text
)
  RETURNS TABLE (
    bucket_start date,
    group_key    text,
    requests     bigint,
    cost_nanos   bigint
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
-- A workspace's spend summed here per UTC day, week (starting Monday) or month,
-- optionally per model or provider, so callers never fetch usage rows to add
-- them up (PostgREST returns at most 1,000 rows). p_from and p_to are inclusive
-- UTC dates; the first and last week or month can be partial. Every bucket in the
-- range is returned, an empty one as a single 'all' row of zeros. Grouped results
-- keep the 8 groups that cost the most over the range and add the rest up as
-- 'other', so at most 100 buckets of 9 rows come back.
-- Service role only: the Slack agent checks the asker is a linked member first.
declare
  v_buckets integer;
  v_top constant integer := 8;
begin
  if p_workspace_id is null or p_from is null or p_to is null or p_from > p_to then
    raise exception 'invalid_range' using errcode = '22023';
  end if;
  if p_bucket is null or p_bucket not in ('day', 'week', 'month') then
    raise exception 'invalid_bucket' using errcode = '22023';
  end if;
  if p_group_by is null or p_group_by not in ('none', 'model', 'provider') then
    raise exception 'invalid_group_by' using errcode = '22023';
  end if;
  v_buckets := case p_bucket
    when 'day' then p_to - p_from + 1
    when 'week' then (date_trunc('week', p_to::timestamp)::date - date_trunc('week', p_from::timestamp)::date) / 7 + 1
    else (extract(year from p_to)::integer * 12 + extract(month from p_to)::integer)
      - (extract(year from p_from)::integer * 12 + extract(month from p_from)::integer) + 1
  end;
  if v_buckets > 100 then
    raise exception 'range_too_long' using errcode = '22023';
  end if;

  return query
  with usage as materialized (
    select date_trunc(p_bucket, daily.usage_date::timestamp)::date as bucket,
      case p_group_by
        when 'model' then coalesce(nullif(daily.model_slug, ''), 'unknown')
        when 'provider' then coalesce(nullif(route.provider_slug, ''), 'unknown')
        else 'all'
      end as grp,
      daily.requests,
      daily.cost_nanos
    from public.v2_private_usage_daily daily
    left join public.v2_model_provider_routes route
      on p_group_by = 'provider' and route.provider_model_id = daily.provider_model_id
    -- Served by the workspace/date index.
    where daily.workspace_id = p_workspace_id
      and daily.usage_date >= p_from
      and daily.usage_date <= p_to
  ), ranked as (
    select usage.grp, row_number() over (order by sum(usage.cost_nanos) desc, usage.grp) as position
    from usage
    group by usage.grp
  ), sums as (
    select usage.bucket,
      case when ranked.position <= v_top then usage.grp else 'other' end as grp,
      sum(usage.requests) as requests,
      sum(usage.cost_nanos) as cost_nanos
    from usage
    join ranked on ranked.grp = usage.grp
    group by 1, 2
  ), buckets as (
    select series::date as bucket
    from generate_series(date_trunc(p_bucket, p_from::timestamp), date_trunc(p_bucket, p_to::timestamp), ('1 ' || p_bucket)::interval) series
  )
  select buckets.bucket,
    coalesce(sums.grp, 'all'),
    coalesce(sums.requests, 0)::bigint,
    coalesce(sums.cost_nanos, 0)::bigint
  from buckets
  left join sums on sums.bucket = buckets.bucket
  order by buckets.bucket, coalesce(sums.cost_nanos, 0) desc, coalesce(sums.grp, 'all');
end;
$function$;

COMMENT ON FUNCTION "public"."get_workspace_spend_buckets"(uuid, date, date, text, text) IS 'A workspace''s requests and spend per UTC day, week (from Monday) or month, optionally by model or provider (top 8 plus other), summed in the database from v2_private_usage_daily. For the Slack agent''s usage tools; service role only.';

GRANT EXECUTE ON FUNCTION "public"."get_workspace_spend_buckets"(uuid, date, date, text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_workspace_spend_buckets"(uuid, date, date, text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_workspace_tier_info.sql
CREATE OR REPLACE FUNCTION public.get_workspace_tier_info (
  p_workspace_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_exists boolean := false;
  v_current_month_nanos bigint := 0;
  v_prev_month_nanos bigint := 0;
  v_current_month_spend numeric(12, 2);
  v_prev_month_spend numeric(12, 2);
  v_current_month_start_ts timestamptz := date_trunc('month', (now() at time zone 'utc'));
  v_prev_month_start_ts timestamptz := date_trunc('month', (now() at time zone 'utc')) - interval '1 month';
  v_next_month_start_ts timestamptz := date_trunc('month', (now() at time zone 'utc')) + interval '1 month';
begin
  select exists(
    select 1 from public.workspaces w where w.id = p_workspace_id
  )
  into v_exists;

  if not v_exists then
    raise exception 'Workspace not found: %', p_workspace_id;
  end if;

  select coalesce(sum(gr.cost_nanos), 0)::bigint
  into v_current_month_nanos
  from private.v2_rpc_gateway_requests_compat gr
  where gr.workspace_id = p_workspace_id
    and gr.success is true
    and gr.created_at >= v_current_month_start_ts
    and gr.created_at < v_next_month_start_ts;

  select coalesce(sum(gr.cost_nanos), 0)::bigint
  into v_prev_month_nanos
  from private.v2_rpc_gateway_requests_compat gr
  where gr.workspace_id = p_workspace_id
    and gr.success is true
    and gr.created_at >= v_prev_month_start_ts
    and gr.created_at < v_current_month_start_ts;

  v_current_month_spend := round((v_current_month_nanos::numeric / 1000000000.0)::numeric, 2);
  v_prev_month_spend := round((v_prev_month_nanos::numeric / 1000000000.0)::numeric, 2);

  return jsonb_build_object(
    'tier', 'basic',
    'tier_display', 'Standard',
    'markup_percentage', 5.00,
    'threshold_usd', 0,
    'current_month_spend_usd', v_current_month_spend,
    'previous_month_spend_usd', v_prev_month_spend,
    'progress_to_enterprise_pct', 100,
    'is_eligible_for_enterprise', false
  );
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_workspace_tier_info"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_workspace_tier_info"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_workspace_user_usage.sql
CREATE OR REPLACE FUNCTION public.get_workspace_user_usage (
  p_workspace_id uuid,
  p_user_id      uuid,
  p_from         timestamp with time zone,
  p_to           timestamp with time zone
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare result jsonb;
begin
  if p_workspace_id is null or p_user_id is null or p_from is null or p_to is null
     or p_to <= p_from or p_to - p_from > interval '31 days' then
    raise exception 'invalid usage window' using errcode = '22023';
  end if;
  with base as materialized (
    select gr.created_at, coalesce(nullif(gr.canonical_model_id, ''), nullif(gr.model_id, ''), 'unknown') as model_id,
           coalesce(gr.cost_nanos, 0)::numeric as cost_nanos
    from private.v2_rpc_gateway_requests_compat gr
    join public.keys k on k.id = gr.key_id and k.workspace_id = gr.workspace_id
    where gr.workspace_id = p_workspace_id and k.created_by = p_user_id
      and gr.success is true and gr.created_at >= p_from and gr.created_at < p_to
  ), daily as (
    select to_char(created_at at time zone 'UTC', 'YYYY-MM-DD') as date,
           count(*) as requests, sum(cost_nanos) / 1e9 as "spendUsd"
    from base group by 1
  ), models as (
    select model_id as "modelId", count(*) as requests, sum(cost_nanos) / 1e9 as "spendUsd"
    from base group by model_id order by count(*) desc, model_id limit 10
  )
  select jsonb_build_object(
    'requests', (select count(*) from base),
    'spendUsd', coalesce((select sum(cost_nanos) / 1e9 from base), 0),
    'points', coalesce((select jsonb_agg(to_jsonb(daily) order by date) from daily), '[]'::jsonb),
    'models', coalesce((select jsonb_agg(to_jsonb(models) order by requests desc, "modelId") from models), '[]'::jsonb)
  ) into result;
  return result;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."get_workspace_user_usage"(uuid, uuid, timestamp WITH time zone, timestamp WITH time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_workspace_user_usage"(uuid, uuid, timestamp WITH time zone, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/guard_conditional_provider_catalog_pricing.sql
CREATE OR REPLACE FUNCTION public.guard_conditional_provider_catalog_pricing()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
begin
  if new.metadata ->> 'managed_by' = 'provider_catalog'
    and exists (
      select 1
      from public.v2_model_provider_routes route
      join public.provider_catalog_route_candidates candidate
        on candidate.run_id = (new.metadata ->> 'source_run_id')::uuid
       and candidate.provider_slug = route.provider_slug
       and candidate.canonical_model_slug = route.model_slug
       and candidate.provider_model_slug = route.provider_model_slug
      cross join lateral jsonb_array_elements(candidate.pricing) as price(value)
      where route.provider_model_id = new.provider_model_id
        and case when jsonb_typeof(price.value -> 'conditions') = 'array'
          then jsonb_array_length(price.value -> 'conditions') > 0
          else false end
    ) then
    raise exception 'provider_catalog_conditional_pricing_requires_review';
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."guard_conditional_provider_catalog_pricing"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/handle_auth_user_created.sql
CREATE OR REPLACE FUNCTION public.handle_auth_user_created()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_stage text := 'start';
  v_error_message text;
  v_error_sqlstate text;
  v_error_detail text;
begin
  raise log '[signup-trigger] stage=start status=ok user_id=% email=%',
    new.id,
    coalesce(new.email, '');

  -- Mandatory: if this fails, abort signup.
  v_stage := 'public_users_upsert';
  begin
    insert into public.users (user_id)
    values (new.id)
    on conflict (user_id) do nothing;

    raise log '[signup-trigger] stage=% status=ok user_id=%', v_stage, new.id;
  exception when others then
    get stacked diagnostics
      v_error_message = message_text,
      v_error_sqlstate = returned_sqlstate,
      v_error_detail = pg_exception_detail;

    raise warning '[signup-trigger] stage=% status=error severity=mandatory user_id=% sqlstate=% message=% detail=%',
      v_stage,
      new.id,
      coalesce(v_error_sqlstate, ''),
      coalesce(v_error_message, sqlerrm),
      coalesce(v_error_detail, '');

    raise;
  end;

  -- PlanetScale port: the optional Discord signup notification (pg_net) moved to the
  -- Better Auth databaseHooks.user.create.after hook. See database/planetscale/SCHEMA-PORT.md.

  return new;
exception when others then
  get stacked diagnostics
    v_error_message = message_text,
    v_error_sqlstate = returned_sqlstate,
    v_error_detail = pg_exception_detail;

  raise warning '[signup-trigger] stage=% status=fatal user_id=% sqlstate=% message=% detail=%',
    coalesce(v_stage, 'unknown'),
    new.id,
    coalesce(v_error_sqlstate, ''),
    coalesce(v_error_message, sqlerrm),
    coalesce(v_error_detail, '');

  raise;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."handle_auth_user_created"() TO "service_role";

COMMENT ON FUNCTION "public"."handle_auth_user_created"() IS 'Provision the public user row for a new auth user. The Discord signup notification moved to the Better Auth databaseHooks.user.create.after hook.';

REVOKE ALL ON FUNCTION "public"."handle_auth_user_created"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/increment_workspace_byok_monthly_request_count_by.sql
CREATE OR REPLACE FUNCTION public.increment_workspace_byok_monthly_request_count_by (
  p_workspace_id  uuid,
  p_now           timestamp with time zone,
  p_request_count bigint
)
  RETURNS TABLE (
    month_start   timestamp with time zone,
    request_count bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_month_start timestamptz;
begin
  if p_workspace_id is null then raise exception 'p_workspace_id is required'; end if;
  if p_request_count is null or p_request_count < 1 then raise exception 'p_request_count must be positive'; end if;
  v_month_start := (date_trunc('month', p_now at time zone 'UTC') at time zone 'UTC');
  insert into public.workspace_byok_monthly_usage as usage (
    workspace_id, month_start, request_count, created_at, updated_at
  ) values (
    p_workspace_id, v_month_start, p_request_count, now(), now()
  ) on conflict (workspace_id, month_start) do update
    set request_count = usage.request_count + excluded.request_count,
        updated_at = now();
  return query select u.month_start, u.request_count
    from public.workspace_byok_monthly_usage u
    where u.workspace_id = p_workspace_id and u.month_start = v_month_start;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."increment_workspace_byok_monthly_request_count_by"(uuid, timestamp WITH time zone, bigint) TO "service_role";

REVOKE ALL ON FUNCTION "public"."increment_workspace_byok_monthly_request_count_by"(uuid, timestamp WITH time zone, bigint) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/increment_workspace_byok_monthly_request_count_once.sql
CREATE OR REPLACE FUNCTION public.increment_workspace_byok_monthly_request_count_once (
  p_workspace_id    uuid,
  p_now             timestamp with time zone,
  p_request_count   bigint,
  p_idempotency_key text
)
  RETURNS TABLE (
    month_start   timestamp with time zone,
    request_count bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_month_start timestamptz := (date_trunc('month', p_now at time zone 'UTC') at time zone 'UTC');
  v_inserted bigint;
begin
  if p_workspace_id is null or p_request_count < 1 or nullif(trim(p_idempotency_key),'') is null then
    raise exception 'workspace, positive request count, and idempotency key are required';
  end if;
  insert into public.workspace_byok_monthly_usage_events(workspace_id,month_start,idempotency_key,request_count)
  values(p_workspace_id,v_month_start,p_idempotency_key,p_request_count)
  on conflict do nothing returning workspace_byok_monthly_usage_events.request_count into v_inserted;
  if v_inserted is not null then
    insert into public.workspace_byok_monthly_usage as usage(workspace_id,month_start,request_count,created_at,updated_at)
    values(p_workspace_id,v_month_start,v_inserted,now(),now())
    on conflict(workspace_id,month_start) do update
      set request_count=usage.request_count+excluded.request_count,updated_at=now();
  end if;
  return query select u.month_start,u.request_count from public.workspace_byok_monthly_usage u
    where u.workspace_id=p_workspace_id and u.month_start=v_month_start;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."increment_workspace_byok_monthly_request_count_once"(uuid, timestamp WITH time zone, bigint, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."increment_workspace_byok_monthly_request_count_once"(uuid, timestamp WITH time zone, bigint, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/increment_workspace_byok_monthly_request_count.sql
CREATE OR REPLACE FUNCTION public.increment_workspace_byok_monthly_request_count (
  p_team_id uuid,
  p_now     timestamp with time zone DEFAULT now()
)
  RETURNS TABLE (
    month_start   timestamp with time zone,
    request_count bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_month_start timestamptz;
begin
  if p_team_id is null then
    raise exception 'p_team_id is required';
  end if;

  v_month_start := (date_trunc('month', p_now at time zone 'UTC') at time zone 'UTC');

  insert into public.team_byok_monthly_usage as usage (
    team_id,
    month_start,
    request_count,
    created_at,
    updated_at
  )
  values (
    p_team_id,
    v_month_start,
    1,
    now(),
    now()
  )
  on conflict (team_id, month_start)
  do update
    set request_count = usage.request_count + 1,
        updated_at = now();

  return query
  select u.month_start, u.request_count
  from public.team_byok_monthly_usage u
  where u.team_id = p_team_id
    and u.month_start = v_month_start;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."increment_workspace_byok_monthly_request_count"(uuid, timestamp WITH time zone) TO "service_role";

COMMENT ON FUNCTION "public"."increment_workspace_byok_monthly_request_count"(uuid, timestamp with time zone) IS 'Atomically increments BYOK request count for team/month (UTC month boundary) and returns updated count.';

REVOKE ALL ON FUNCTION "public"."increment_workspace_byok_monthly_request_count"(uuid, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/ingest_v2_gateway_request_with_routing.sql
CREATE OR REPLACE FUNCTION public.ingest_v2_gateway_request_with_routing (
  p_event jsonb
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_request_event_id uuid;
  v_gateway_request_id uuid;
  v_gateway_request_created_at timestamptz;
  v_attempts jsonb := coalesce(p_event->'attempts', '[]'::jsonb);
  v_routing_decisions jsonb := coalesce(p_event->'routing_decisions', '[]'::jsonb);
  v_routing_trace jsonb := coalesce(p_event->'routing_trace', '{}'::jsonb);
begin
  perform pg_advisory_xact_lock(hashtextextended(
    (p_event->>'workspace_id') || ':' || (p_event->>'request_id'), 0
  ));
  if jsonb_typeof(p_event->'routing_archive') = 'object' then
    select request.id, request.created_at
      into v_gateway_request_id, v_gateway_request_created_at
    from public.gateway_requests request
    where request.workspace_id = (p_event->>'workspace_id')::uuid
      and request.request_id = p_event->>'request_id'
    order by request.created_at desc limit 1 for update;
    if not found then
      raise exception using errcode = '22023', message = 'routing_archive_source_request_missing';
    end if;
  end if;
  if jsonb_typeof(v_routing_decisions) <> 'array'
     or jsonb_array_length(v_routing_decisions) > 128
     or jsonb_typeof(v_routing_trace) <> 'object'
     or pg_column_size(v_routing_trace) > 32768 then
    raise exception using errcode = '22023', message = 'gateway_event_routing_trace_invalid';
  end if;

  v_request_event_id := public.ingest_v2_gateway_request(
    p_event - 'routing_decisions' - 'routing_trace'
  );

  update public.v2_request_attempts attempt
  set provider_model_id = route.provider_model_id
  from jsonb_array_elements(v_attempts) with ordinality as item(value, ordinality)
  cross join lateral (
    select candidate.provider_model_id
    from public.v2_model_provider_routes candidate
    where candidate.provider_model_id = nullif(item.value->>'provider_model_id', '')
       or (
         candidate.provider_slug = nullif(item.value->>'provider', '')
         and candidate.provider_model_id =
           nullif(item.value->>'provider', '') || ':' || nullif(item.value->>'provider_api_model_id', '')
       )
       or (
         candidate.provider_slug = nullif(item.value->>'provider', '')
         and candidate.provider_model_slug = nullif(item.value->>'provider_api_model_id', '')
       )
    order by
      case when candidate.provider_model_id = nullif(item.value->>'provider_model_id', '') then 0 else 1 end,
      candidate.provider_model_id
    limit 1
  ) route
  where attempt.request_event_id = v_request_event_id
    and attempt.attempt_number = greatest(
      1,
      coalesce((item.value->>'attempt_number')::integer, item.ordinality::integer)
    );

  delete from public.v2_request_routing_decisions decision
  where decision.request_event_id = v_request_event_id;

  if jsonb_typeof(p_event->'routing_archive') = 'object' then
    -- The gateway inserted the request first, then durably uploaded R2. Keep
    -- its SQL explanation until this reference and normalized facts commit.
    update public.gateway_requests
    set detail_metadata = (coalesce(detail_metadata, '{}'::jsonb) - 'routing_snapshot' - 'routing_diagnostics')
      || jsonb_build_object('routing_archive', p_event->'routing_archive')
    where id = v_gateway_request_id and created_at = v_gateway_request_created_at;
    delete from public.v2_request_routing_traces
    where request_event_id = v_request_event_id;
    return v_request_event_id;
  end if;

  insert into public.v2_request_routing_decisions (
    request_event_id, decision_order, provider_model_id, provider_slug,
    provider_api_model_id, decision, rank, score, selected, attempted,
    breaker, breaker_until, provider_status, provider_routing_status,
    model_routing_status, capability_status, exclusion_stage, exclusion_reason,
    score_factors, score_trace
  )
  select
    v_request_event_id,
    greatest(1, coalesce((item.value->>'decision_order')::integer, item.ordinality::integer)),
    route.provider_model_id,
    left(nullif(trim(item.value->>'provider'), ''), 256),
    left(nullif(trim(item.value->>'provider_api_model_id'), ''), 512),
    coalesce(nullif(item.value->>'decision', ''), 'ranked'),
    nullif(item.value->>'rank', '')::integer,
    nullif(item.value->>'score', '')::numeric,
    coalesce((item.value->>'selected')::boolean, false),
    coalesce((item.value->>'attempted')::boolean, false),
    left(nullif(item.value->>'breaker', ''), 64),
    case
      when nullif(item.value->>'breaker_until_ms', '') is null then null
      else to_timestamp((item.value->>'breaker_until_ms')::double precision / 1000.0)
    end,
    left(nullif(item.value->>'provider_status', ''), 64),
    left(nullif(item.value->>'provider_routing_status', ''), 64),
    left(nullif(item.value->>'model_routing_status', ''), 64),
    left(nullif(item.value->>'capability_status', ''), 64),
    left(nullif(item.value->>'exclusion_stage', ''), 128),
    left(nullif(item.value->>'exclusion_reason', ''), 256),
    coalesce(item.value->'score_factors', '{}'::jsonb),
    coalesce(item.value->'score_trace', '{}'::jsonb)
  from jsonb_array_elements(v_routing_decisions) with ordinality as item(value, ordinality)
  left join lateral (
    select candidate.provider_model_id
    from public.v2_model_provider_routes candidate
    where candidate.provider_model_id = nullif(item.value->>'provider_model_id', '')
       or (
         candidate.provider_slug = nullif(item.value->>'provider', '')
         and candidate.provider_model_id =
           nullif(item.value->>'provider', '') || ':' || nullif(item.value->>'provider_api_model_id', '')
       )
       or (
         candidate.provider_slug = nullif(item.value->>'provider', '')
         and candidate.provider_model_slug = nullif(item.value->>'provider_api_model_id', '')
       )
    order by
      case when candidate.provider_model_id = nullif(item.value->>'provider_model_id', '') then 0 else 1 end,
      candidate.provider_model_id
    limit 1
  ) route on true
  where nullif(trim(item.value->>'provider'), '') is not null;

  insert into public.v2_request_routing_traces (
    request_event_id, algorithm_version, random_seed, selection_method,
    routing_mode, priority, requested_model, endpoint, final_candidate_count,
    pool_bounds, requested_routing, sticky_routing
  ) values (
    v_request_event_id,
    left(nullif(v_routing_trace#>>'{algorithm,version}', ''), 128),
    nullif(v_routing_trace#>>'{algorithm,seed}', '')::bigint,
    left(nullif(v_routing_trace#>>'{algorithm,selectionMethod}', ''), 64),
    left(nullif(v_routing_trace->>'routing_mode', ''), 64),
    left(nullif(v_routing_trace->>'priority', ''), 64),
    left(nullif(v_routing_trace->>'model', ''), 512),
    left(nullif(v_routing_trace->>'endpoint', ''), 128),
    nullif(v_routing_trace->>'final_candidate_count', '')::integer,
    coalesce(v_routing_trace#>'{algorithm,poolBounds}', '{}'::jsonb),
    coalesce(v_routing_trace->'requested_routing', '{}'::jsonb),
    coalesce(v_routing_trace->'sticky_routing', '{}'::jsonb)
  )
  on conflict (request_event_id) do update set
    algorithm_version = excluded.algorithm_version,
    random_seed = excluded.random_seed,
    selection_method = excluded.selection_method,
    routing_mode = excluded.routing_mode,
    priority = excluded.priority,
    requested_model = excluded.requested_model,
    endpoint = excluded.endpoint,
    final_candidate_count = excluded.final_candidate_count,
    pool_bounds = excluded.pool_bounds,
    requested_routing = excluded.requested_routing,
    sticky_routing = excluded.sticky_routing;

  return v_request_event_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."ingest_v2_gateway_request_with_routing"(jsonb) TO "service_role";

COMMENT ON FUNCTION "public"."ingest_v2_gateway_request_with_routing"(jsonb) IS 'Atomically ingests request telemetry while preserving exact provider/model route identities.';

REVOKE ALL ON FUNCTION "public"."ingest_v2_gateway_request_with_routing"(jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/ingest_v2_gateway_request.sql
CREATE OR REPLACE FUNCTION public.ingest_v2_gateway_request (
  p_event jsonb
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_request_event_id uuid;
  v_workspace_id uuid;
  v_request_id text;
  v_requested_input text;
  v_requested_model_slug text;
  v_routed_model_slug text;
  v_provider text;
  v_provider_api_model_id text;
  v_provider_model_id text;
  v_attempts jsonb := coalesce(p_event->'attempts', '[]'::jsonb);
  v_usage jsonb := coalesce(p_event->'usage_meters', '[]'::jsonb);
  v_pricing jsonb := coalesce(p_event->'pricing_lines', '[]'::jsonb);
  v_safe_metadata jsonb := coalesce(p_event->'safe_metadata', '{}'::jsonb);
  v_occurred_at timestamptz := coalesce(nullif(p_event->>'occurred_at', '')::timestamptz, now());
begin
  if jsonb_typeof(p_event) <> 'object' then
    raise exception using errcode = '22023', message = 'gateway_event_must_be_object';
  end if;

  v_workspace_id := nullif(p_event->>'workspace_id', '')::uuid;
  v_request_id := nullif(trim(p_event->>'request_id'), '');
  v_requested_input := nullif(trim(p_event->>'requested_model_input'), '');
  v_provider := nullif(trim(p_event->>'provider'), '');
  v_provider_api_model_id := nullif(trim(p_event->>'provider_api_model_id'), '');

  if v_workspace_id is null or v_request_id is null or v_requested_input is null then
    raise exception using errcode = '22023', message = 'gateway_event_missing_identity';
  end if;
  if length(v_request_id) > 256 or length(v_requested_input) > 512 then
    raise exception using errcode = '22023', message = 'gateway_event_identity_too_long';
  end if;
  if jsonb_typeof(v_attempts) <> 'array' then
    raise exception using errcode = '22023', message = 'gateway_event_attempts_invalid';
  end if;
  if jsonb_array_length(v_attempts) > 128 then
    raise exception using errcode = '22023', message = 'gateway_event_attempts_invalid';
  end if;
  if jsonb_typeof(v_usage) <> 'array' then
    raise exception using errcode = '22023', message = 'gateway_event_usage_invalid';
  end if;
  if jsonb_array_length(v_usage) > 256 then
    raise exception using errcode = '22023', message = 'gateway_event_usage_invalid';
  end if;
  if jsonb_typeof(v_pricing) <> 'array' then
    raise exception using errcode = '22023', message = 'gateway_event_pricing_invalid';
  end if;
  if jsonb_array_length(v_pricing) > 256 then
    raise exception using errcode = '22023', message = 'gateway_event_pricing_invalid';
  end if;
  if jsonb_typeof(v_safe_metadata) <> 'object' or pg_column_size(v_safe_metadata) > 16384 then
    raise exception using errcode = '22023', message = 'gateway_event_safe_metadata_invalid';
  end if;

  -- Serialize retries/concurrent finalizers for the same logical request.
  perform pg_advisory_xact_lock(hashtextextended(v_workspace_id::text || ':' || v_request_id, 0));

  select model.model_slug into v_requested_model_slug
  from public.v2_models model
  where model.model_slug = lower(v_requested_input)
  limit 1;
  if v_requested_model_slug is null then
    select alias.model_slug into v_requested_model_slug
    from public.v2_model_aliases alias
    where alias.alias_slug = lower(v_requested_input) and alias.enabled = true
    limit 1;
  end if;

  select model.model_slug into v_routed_model_slug
  from public.v2_models model
  where model.model_slug = lower(coalesce(nullif(trim(p_event->>'routed_model_slug'), ''), v_requested_model_slug, v_requested_input))
  limit 1;
  v_routed_model_slug := coalesce(v_routed_model_slug, v_requested_model_slug);

  if nullif(trim(p_event->>'provider_model_id'), '') is not null then
    select route.provider_model_id into v_provider_model_id
    from public.v2_model_provider_routes route
    where route.provider_model_id = trim(p_event->>'provider_model_id')
    limit 1;
  end if;
  if v_provider_model_id is null and v_provider is not null then
    select route.provider_model_id into v_provider_model_id
    from public.v2_model_provider_routes route
    where route.provider_slug = v_provider
      and (v_routed_model_slug is null or route.model_slug = v_routed_model_slug)
    order by
      case
        when v_provider_api_model_id is not null and route.provider_model_slug = v_provider_api_model_id then 0
        when v_provider_api_model_id is not null and route.provider_model_id = v_provider || ':' || v_provider_api_model_id then 1
        else 2
      end,
      case when route.routing_enabled then 0 else 1 end,
      route.provider_model_id
    limit 1;
  end if;


  -- The free router is a selector, not a catalogue model. Resolve its exact
  -- successful attempt before the privacy trigger sees the request. Never
  -- relax sticky exclusions or guess a route from the provider alone.
  if lower(v_requested_input) = 'phaseo/free' and v_routed_model_slug is null then
    select route.model_slug, route.provider_model_id
      into v_routed_model_slug, v_provider_model_id
    from jsonb_array_elements(v_attempts) with ordinality as item(value, ordinality)
    join public.v2_model_provider_routes route
      on route.provider_slug = nullif(item.value->>'provider', '')
      and (
        route.provider_model_id = nullif(item.value->>'provider_model_id', '')
        or route.provider_model_slug = nullif(item.value->>'provider_api_model_id', '')
      )
    where coalesce((item.value->>'success')::boolean, false)
      and route.provider_slug = v_provider
    order by item.ordinality desc,
      case when route.provider_model_id = item.value->>'provider_model_id' then 0 else 1 end,
      route.provider_model_id
    limit 1;
  end if;

  insert into public.v2_request_facts (
    workspace_id, request_id, occurred_at, app_id, key_id, endpoint,
    requested_model_input, requested_model_slug, routed_model_slug, provider_model_id,
    status_code, success, error_code, stop_reason, tool_call_count, tool_call_succeeded,
    structured_output_attempted, structured_output_succeeded, stream, byok,
    latency_ms, time_to_first_token_ms, generation_ms, internal_dispatch_ms,
    gateway_total_ms, upstream_attempt_count, throughput, user_agent,
    sdk_name, sdk_version, client_version,
    session_id, end_user_id, auth_method, native_response_id, cost_nanos, currency,
    cloudflare_colo, safe_metadata
  ) values (
    v_workspace_id, v_request_id, v_occurred_at,
    nullif(p_event->>'app_id', '')::uuid, nullif(p_event->>'key_id', '')::uuid,
    coalesce(nullif(trim(p_event->>'endpoint'), ''), 'unknown'),
    v_requested_input, v_requested_model_slug, v_routed_model_slug, v_provider_model_id,
    nullif(p_event->>'status_code', '')::integer, coalesce((p_event->>'success')::boolean, false),
    nullif(p_event->>'error_code', ''), nullif(p_event->>'stop_reason', ''),
    greatest(0, coalesce((p_event->>'tool_call_count')::integer, 0)),
    case when coalesce((p_event->>'tool_call_count')::integer, 0) > 0 then (p_event->>'tool_call_succeeded')::boolean else null end,
    coalesce((p_event->>'structured_output_attempted')::boolean, false),
    coalesce((p_event->>'structured_output_succeeded')::boolean, false),
    coalesce((p_event->>'stream')::boolean, false), coalesce((p_event->>'byok')::boolean, false),
    nullif(p_event->>'latency_ms', '')::integer,
    nullif(p_event->>'latency_ms', '')::integer,
    nullif(p_event->>'generation_ms', '')::integer,
    nullif(p_event->>'internal_dispatch_ms', '')::numeric,
    nullif(p_event->>'gateway_total_ms', '')::numeric,
    least(32767, jsonb_array_length(v_attempts))::smallint,
    nullif(p_event->>'throughput', '')::numeric,
    left(nullif(p_event->>'user_agent', ''), 1024),
    left(nullif(trim(p_event->>'sdk_name'), ''), 256),
    left(nullif(trim(p_event->>'sdk_version'), ''), 128),
    left(nullif(trim(p_event->>'client_version'), ''), 128),
    left(nullif(p_event->>'session_id', ''), 256),
    left(nullif(p_event->>'end_user_id', ''), 256),
    nullif(p_event->>'auth_method', ''),
    left(nullif(p_event->>'native_response_id', ''), 512),
    nullif(p_event->>'cost_nanos', '')::bigint,
    left(nullif(p_event->>'currency', ''), 8),
    nullif(upper(trim(p_event->>'cloudflare_colo')), ''),
    v_safe_metadata
  )
  on conflict (workspace_id, request_id) do update set
    occurred_at = excluded.occurred_at,
    app_id = excluded.app_id,
    key_id = excluded.key_id,
    endpoint = excluded.endpoint,
    requested_model_input = excluded.requested_model_input,
    requested_model_slug = excluded.requested_model_slug,
    routed_model_slug = excluded.routed_model_slug,
    provider_model_id = excluded.provider_model_id,
    status_code = excluded.status_code,
    success = excluded.success,
    error_code = excluded.error_code,
    stop_reason = excluded.stop_reason,
    tool_call_count = excluded.tool_call_count,
    tool_call_succeeded = excluded.tool_call_succeeded,
    structured_output_attempted = excluded.structured_output_attempted,
    structured_output_succeeded = excluded.structured_output_succeeded,
    stream = excluded.stream,
    byok = excluded.byok,
    latency_ms = excluded.latency_ms,
    time_to_first_token_ms = excluded.time_to_first_token_ms,
    generation_ms = excluded.generation_ms,
    internal_dispatch_ms = excluded.internal_dispatch_ms,
    gateway_total_ms = excluded.gateway_total_ms,
    upstream_attempt_count = excluded.upstream_attempt_count,
    throughput = excluded.throughput,
    user_agent = excluded.user_agent,
    sdk_name = excluded.sdk_name,
    sdk_version = excluded.sdk_version,
    client_version = excluded.client_version,
    session_id = excluded.session_id,
    end_user_id = excluded.end_user_id,
    auth_method = excluded.auth_method,
    native_response_id = excluded.native_response_id,
    cost_nanos = excluded.cost_nanos,
    currency = excluded.currency,
    cloudflare_colo = excluded.cloudflare_colo,
    safe_metadata = excluded.safe_metadata
  returning request_event_id into v_request_event_id;

  delete from public.v2_request_attempts attempt
  where attempt.request_event_id = v_request_event_id;

  insert into public.v2_request_attempts (
    request_event_id, attempt_number, provider_model_id, status_code, success,
    error_code, failure_class, upstream_response_id, latency_ms, cloudflare_colo, safe_metadata
  )
  select
    v_request_event_id,
    greatest(1, coalesce((item.value->>'attempt_number')::integer, item.ordinality::integer)),
    route.provider_model_id,
    nullif(item.value->>'status_code', '')::integer,
    coalesce((item.value->>'success')::boolean, false),
    nullif(item.value->>'error_code', ''),
    nullif(item.value->>'failure_class', ''),
    left(nullif(item.value->>'upstream_response_id', ''), 512),
    nullif(item.value->>'latency_ms', '')::integer,
    nullif(upper(trim(p_event->>'cloudflare_colo')), ''),
    jsonb_strip_nulls(jsonb_build_object(
      'provider', nullif(item.value->>'provider', ''),
      'credential_phase', nullif(item.value->>'credential_phase', ''),
      'key_source', nullif(item.value->>'key_source', ''),
      'response_kind', nullif(item.value->>'response_kind', ''),
      'retryable', nullif(item.value->>'retryable', '')::boolean,
      'was_probe', coalesce((item.value->>'was_probe')::boolean, false)
    ))
  from jsonb_array_elements(v_attempts) with ordinality as item(value, ordinality)
  left join lateral (
    select candidate.provider_model_id
    from public.v2_model_provider_routes candidate
    where candidate.provider_slug = nullif(item.value->>'provider', '')
      and (v_routed_model_slug is null or candidate.model_slug = v_routed_model_slug)
    order by
      case when nullif(item.value->>'provider_api_model_id', '') is not null
        and candidate.provider_model_slug = item.value->>'provider_api_model_id' then 0 else 1 end,
      candidate.provider_model_id
    limit 1
  ) route on true;

  delete from public.v2_request_usage usage
  where usage.request_event_id = v_request_event_id;

  insert into public.v2_request_usage (
    request_event_id, sku_meter_id, meter_key, modality, unit, quantity, source, billable, sequence
  )
  select
    v_request_event_id, meter.sku_meter_id,
    lower(item.value->>'meter_key'), lower(item.value->>'modality'), lower(item.value->>'unit'),
    greatest(0, (item.value->>'quantity')::numeric),
    coalesce(nullif(item.value->>'source', ''), 'gateway'),
    coalesce((item.value->>'billable')::boolean, true),
    greatest(0, coalesce((item.value->>'sequence')::integer, item.ordinality::integer - 1))
  from jsonb_array_elements(v_usage) with ordinality as item(value, ordinality)
  left join lateral (
    select sku_meter.sku_meter_id
    from public.v2_pricing_sku_meters sku_meter
    join public.v2_pricing_skus sku on sku.sku_id = sku_meter.sku_id
    where sku.provider_model_id = v_provider_model_id
      and sku_meter.meter_key = lower(item.value->>'meter_key')
      and sku.status = 'active'
      and sku.effective_from <= v_occurred_at
      and (sku.effective_to is null or sku.effective_to > v_occurred_at)
    order by sku.version desc, sku.effective_from desc
    limit 1
  ) meter on true
  where coalesce((item.value->>'quantity')::numeric, 0) > 0;

  delete from public.v2_request_pricing_lines pricing
  where pricing.request_event_id = v_request_event_id;

  insert into public.v2_request_pricing_lines (
    request_event_id, sku_id, sku_meter_id, meter_key, quantity, unit,
    unit_price_nanos, charged_nanos
  )
  select
    v_request_event_id, meter.sku_id, meter.sku_meter_id,
    lower(item.value->>'meter_key'),
    greatest(0, (item.value->>'quantity')::numeric),
    lower(coalesce(nullif(item.value->>'unit', ''), 'unit')),
    greatest(0, coalesce((item.value->>'unit_price_nanos')::numeric, 0)),
    greatest(0, coalesce((item.value->>'charged_nanos')::bigint, 0))
  from jsonb_array_elements(v_pricing) as item(value)
  left join lateral (
    select sku.sku_id, sku_meter.sku_meter_id
    from public.v2_pricing_skus sku
    left join public.v2_pricing_sku_meters sku_meter
      on sku_meter.sku_id = sku.sku_id
      and sku_meter.meter_key = lower(item.value->>'meter_key')
    where sku.provider_model_id = v_provider_model_id
      and sku.status = 'active'
      and sku.effective_from <= v_occurred_at
      and (sku.effective_to is null or sku.effective_to > v_occurred_at)
    order by sku.version desc, sku.effective_from desc
    limit 1
  ) meter on true;

  insert into public.v2_analytics_outbox (
    request_event_id, workspace_id, occurred_at, status, attempt_count,
    available_at, last_error, updated_at
  ) values (
    v_request_event_id, v_workspace_id, v_occurred_at, 'pending', 0,
    now(), null, now()
  )
  on conflict (request_event_id) do update set
    workspace_id = excluded.workspace_id,
    occurred_at = excluded.occurred_at,
    status = 'pending',
    attempt_count = 0,
    available_at = now(),
    last_error = null,
    updated_at = now();

  return v_request_event_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."ingest_v2_gateway_request"(jsonb) TO "service_role";

COMMENT ON FUNCTION "public"."ingest_v2_gateway_request"(jsonb) IS 'Service-only, idempotent and atomic ingestion of content-free gateway request facts, attempts, usage, pricing, and analytics outbox state.';

REVOKE ALL ON FUNCTION "public"."ingest_v2_gateway_request"(jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/is_active_invite_for_workspace.sql
CREATE OR REPLACE FUNCTION public.is_active_invite_for_workspace (
  p_invite_id uuid,
  p_team_id   uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select auth.uid() is not null and exists (
    select 1 from public.workspace_invites i
    where i.id = p_invite_id and i.workspace_id = p_team_id
      and (i.expires_at is null or i.expires_at > now())
      and (i.max_uses is null or coalesce(i.uses_count, 0) < i.max_uses)
  );
$function$;

GRANT EXECUTE ON FUNCTION "public"."is_active_invite_for_workspace"(uuid, uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."is_active_invite_for_workspace"(uuid, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."is_active_invite_for_workspace"(uuid, uuid) FROM PUBLIC, "anon";

