CREATE OR REPLACE FUNCTION public.is_admin_user()
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select exists (
    select 1
    from public.users u
    where u.user_id = auth.uid()
      and lower(coalesce(u.role::text, '')) = 'admin'
  );
$function$;

