-- source: supabase/schemas/public/functions/is_team_owner.sql
CREATE OR REPLACE FUNCTION public.is_team_owner (
  p_team_id uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from public.workspaces w
    where w.id = p_team_id and w.owner_user_id = auth.uid()
  ) or exists (
    select 1 from public.workspace_members wm
    where wm.workspace_id = p_team_id and wm.user_id = auth.uid() and wm.role = 'owner'
  );
$function$;

