-- source: supabase/schemas/public/functions/is_workspace_member.sql
CREATE OR REPLACE FUNCTION public.is_workspace_member (
  p_team_id uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  select
    exists (
      select 1
      from public.workspace_members wm
      where wm.workspace_id = p_team_id
        and wm.user_id = auth.uid()
    )
    or exists (
      select 1
      from public.workspaces w
      where w.id = p_team_id
        and w.owner_user_id = auth.uid()
    );
$function$;

GRANT EXECUTE ON FUNCTION "public"."is_workspace_member"(uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."is_workspace_member"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."is_workspace_member"(uuid) FROM PUBLIC, "anon";

-- source: supabase/schemas/public/functions/issue_desktop_session_key.sql
CREATE OR REPLACE FUNCTION public.issue_desktop_session_key (
  p_user_id      uuid,
  p_workspace_id uuid,
  p_key_hash     text,
  p_key_kid      text,
  p_key_prefix   text,
  p_key_name     text,
  p_resource     text,
  p_ttl_seconds  integer
)
  RETURNS timestamp with time zone
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  key_scopes constant text[] := array['gateway:access', 'models:read']::text[];
  key_expires_at timestamptz := now() + make_interval(secs => least(greatest(p_ttl_seconds, 60), 90 * 86400));
begin
  perform 1
  from public.workspace_members member
  where member.user_id = p_user_id
    and member.workspace_id = p_workspace_id
  for key share;

  if not found then
    return null;
  end if;

  -- Signing in again restores an authorisation revoked from Connected apps, with only what the app needs.
  insert into public.oauth_authorizations as authorization_row (user_id, client_id, workspace_id, scopes)
  values (p_user_id, 'phaseo_desktop', p_workspace_id, key_scopes)
  on conflict (user_id, client_id, workspace_id) do update
  set scopes = case
      when authorization_row.revoked_at is null then array(
        select distinct scope from unnest(authorization_row.scopes || key_scopes) as scope order by scope
      )
      else key_scopes
    end,
    revoked_at = null;

  insert into public.keys (
    workspace_id, name, hash, prefix, status, scopes, created_by, kid,
    key_kind, oauth_client_id, oauth_user_id, oauth_scopes, oauth_resource, issued_via, expires_at
  ) values (
    p_workspace_id, p_key_name, p_key_hash, p_key_prefix, 'active', '[]', p_user_id, p_key_kid,
    'oauth_delegated', 'phaseo_desktop', p_user_id, key_scopes, nullif(btrim(p_resource), ''), 'desktop', key_expires_at
  );

  return key_expires_at;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."issue_desktop_session_key"(uuid, uuid, text, text, text, text, text, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."issue_desktop_session_key"(uuid, uuid, text, text, text, text, text, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/key_storage_incident_recipients.sql
CREATE OR REPLACE FUNCTION public.key_storage_incident_recipients (
  p_incident_id uuid
)
  RETURNS TABLE (
    workspace_id   uuid,
    workspace_name text,
    user_id        uuid,
    email          text,
    keys           bigint
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- The owners and admins of each workspace an applied incident changed, with
  -- how many of that workspace's keys it changed. Service-only.
  with affected as (
    select changed.workspace_id, count(*) as keys
    from public.key_storage_incident_keys as changed
    where changed.incident_id = p_incident_id
    group by changed.workspace_id
  ), people as (
    select member.workspace_id, member.user_id
    from public.workspace_members as member
    join affected on affected.workspace_id = member.workspace_id
    where member.role::text in ('owner', 'admin')
    union
    select workspace.id, workspace.owner_user_id
    from public.workspaces as workspace
    join affected on affected.workspace_id = workspace.id
    where workspace.owner_user_id is not null
  )
  select people.workspace_id, workspace.name, people.user_id, account.email::text, affected.keys
  from people
  join affected on affected.workspace_id = people.workspace_id
  join public.workspaces as workspace on workspace.id = people.workspace_id
  join auth.users as account on account.id = people.user_id
  where nullif(btrim(account.email), '') is not null
  order by people.workspace_id, people.user_id;
$function$;

COMMENT ON FUNCTION "public"."key_storage_incident_recipients"(uuid) IS 'Owners and admins to email for each workspace a key storage incident changed. Service-only.';

GRANT EXECUTE ON FUNCTION "public"."key_storage_incident_recipients"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."key_storage_incident_recipients"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/lift_spend_blocks_on_rule_change.sql
CREATE OR REPLACE FUNCTION public.lift_spend_blocks_on_rule_change ()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Lifts a spend rule's active block in the same transaction as the change that ends it, so an
-- admin who turns a rule off or raises its limit unblocks at once rather than at the next sweep:
--   * the rule is deleted (DELETE, e.g. a cascade from its key, member or department, or
--     deleted_at set): rule_deleted;
--   * enabled turned off: rule_disabled;
--   * its action, metric, scope, period, time zone or base changed: rule_changed;
--   * its block point changed (block_at_amount_nanos, block_at_percent or base_amount_nanos) and
--     spend so far this period (private.spend_rule_values) is now below it: rule_changed.
-- A change to block_free_models is copied onto the active block. Each lift queues a
-- spend_blocked "lifted" event. Nothing happens while the workspace itself is being deleted
-- (its blocks go with it). The API that made the change republishes the gateway's entry.
declare
  v_rule public.workspace_spend_rules;
  v_block public.workspace_spend_blocks;
  v_reason text;
  v_value numeric;
  v_base bigint;
  v_limit numeric;
begin
  v_rule := case when tg_op = 'DELETE' then old else new end;
  select block.* into v_block
  from public.workspace_spend_blocks block
  where block.rule_id = old.id and block.lifted_at is null
  for update;
  if not found or not exists (select 1 from public.workspaces workspace where workspace.id = old.workspace_id) then
    return v_rule;
  end if;

  if tg_op = 'DELETE' or new.deleted_at is not null then
    v_reason := 'rule_deleted';
  elsif not new.enabled then
    v_reason := 'rule_disabled';
  elsif new.action <> 'block'
    or new.metric is distinct from old.metric
    or new.scope_type is distinct from old.scope_type
    or new.scope_id is distinct from old.scope_id
    or new.period is distinct from old.period
    or new.window_hours is distinct from old.window_hours
    or new.time_zone is distinct from old.time_zone
    or new.base_kind is distinct from old.base_kind
    or new.base_ref is distinct from old.base_ref then
    v_reason := 'rule_changed';
  elsif new.block_at_amount_nanos is distinct from old.block_at_amount_nanos
    or new.block_at_percent is distinct from old.block_at_percent
    or new.base_amount_nanos is distinct from old.base_amount_nanos then
    select value.value_nanos, value.base_nanos into v_value, v_base
    from private.spend_rule_values(new.workspace_id, now(), new.id) value;
    v_limit := case new.metric
      when 'spend' then new.block_at_amount_nanos
      when 'budget_percent' then case when v_base > 0 then ceil(new.block_at_percent::numeric * v_base / 100) end
    end;
    if v_limit is null or coalesce(v_value, 0) < v_limit then
      v_reason := 'rule_changed';
    end if;
  end if;

  if v_reason is null then
    if new.block_free_models is distinct from v_block.block_free_models then
      update public.workspace_spend_blocks set block_free_models = new.block_free_models where id = v_block.id;
    end if;
    return v_rule;
  end if;

  update public.workspace_spend_blocks
  set lifted_at = greatest(now(), started_at), lift_reason = v_reason
  where id = v_block.id;
  perform private.queue_spend_block_event(v_block.id, 'lifted', now());
  return v_rule;
end;
$function$;

COMMENT ON FUNCTION "public"."lift_spend_blocks_on_rule_change"() IS 'Trigger on workspace_spend_rules (after update, before delete): lifts the rule''s active spend block when the rule is deleted, disabled, changed in scope or period, or its block point rises above spend so far, and queues the spend_blocked lifted event.';

GRANT EXECUTE ON FUNCTION "public"."lift_spend_blocks_on_rule_change"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."lift_spend_blocks_on_rule_change"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/lift_workspace_spend_block.sql
CREATE OR REPLACE FUNCTION public.lift_workspace_spend_block (
  p_workspace_id  uuid,
  p_block_id      uuid,
  p_actor_user_id uuid                     DEFAULT NULL::uuid,
  p_now           timestamp with time zone DEFAULT now()
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Lifts an active spend block by hand (lift_reason manual, lifted_by the admin when known) and
-- queues the spend_blocked "lifted" event. The evaluator does not start the rule's block again
-- until its period resets. The caller (control API or web-api) checks the caller is an owner or
-- admin, writes the audit event and republishes the gateway's entry.
-- Errors: spend_block_not_found (no such block in the workspace), spend_block_not_active (it was
-- already lifted). Returns the block as public.list_workspace_spend_blocks shows it.
declare
  v_block public.workspace_spend_blocks;
begin
  if p_workspace_id is null or p_block_id is null or p_now is null then
    raise exception 'spend_block_not_found' using errcode = 'P0002';
  end if;
  select block.* into v_block
  from public.workspace_spend_blocks block
  where block.id = p_block_id and block.workspace_id = p_workspace_id
  for update;
  if not found then
    raise exception 'spend_block_not_found' using errcode = 'P0002';
  end if;
  if v_block.lifted_at is not null then
    raise exception 'spend_block_not_active' using errcode = '55000';
  end if;

  update public.workspace_spend_blocks
  set lifted_at = greatest(p_now, started_at),
      lift_reason = 'manual',
      lifted_by = case when exists (select 1 from auth.users actor where actor.id = p_actor_user_id) then p_actor_user_id end
  where id = v_block.id;
  perform private.queue_spend_block_event(v_block.id, 'lifted', p_now);

  return public.list_workspace_spend_blocks(p_workspace_id, true, 1, v_block.id) -> 0;
end;
$function$;

COMMENT ON FUNCTION "public"."lift_workspace_spend_block"(uuid, uuid, uuid, timestamp with time zone) IS 'Lifts an active spend block by hand (manual: it stays lifted until the period resets) and queues the spend_blocked lifted event. Service role only (control API and web-api, owners and admins).';

REVOKE ALL ON FUNCTION "public"."lift_workspace_spend_block"(uuid, uuid, uuid, timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."lift_workspace_spend_block"(uuid, uuid, uuid, timestamp with time zone) TO "service_role";

-- source: supabase/schemas/public/functions/link_provider_personal_account.sql
CREATE OR REPLACE FUNCTION public.link_provider_personal_account (
  p_user_id       uuid,
  p_provider_slug text,
  p_proof_subject text,
  p_proof_method  text DEFAULT 'catalog_domain_match'::text
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_workspace_id uuid;
begin
  if p_proof_method not in ('catalog_domain_match', 'domain_file', 'self_declared') then
    raise exception 'invalid_provider_proof_method';
  end if;
  -- Serialize submissions from one account, including different provider slugs.
  perform 1 from public.users where user_id = p_user_id for update;
  if not found then
    raise exception 'provider_account_user_missing';
  end if;

  select l.workspace_id into v_workspace_id from public.provider_account_links l
  join public.workspaces w on w.id = l.workspace_id
  where l.provider_slug = p_provider_slug and l.linked_by = p_user_id
    and l.status = 'active' and w.owner_user_id = p_user_id;
  if found then return v_workspace_id; end if;

  select id into v_workspace_id from public.workspaces
  where owner_user_id = p_user_id and workspace_kind = 'personal'
  order by created_at, id limit 1;

  if v_workspace_id is null then
    insert into public.workspaces (name, slug, owner_user_id, workspace_kind)
    values ('Personal', replace(p_user_id::text, '-', '')::text || '-p', p_user_id, 'personal')
    returning id into v_workspace_id;
  end if;

  insert into public.workspace_members (workspace_id, user_id, role)
  values (v_workspace_id, p_user_id, 'owner')
  on conflict on constraint workspace_members_pkey do nothing;
  insert into public.workspace_settings (workspace_id) values (v_workspace_id)
  on conflict on constraint workspace_settings_pkey do nothing;

  insert into public.provider_account_links
    (provider_slug, workspace_id, linked_by, role, status, proof_method, proof_subject, verified_at)
  values (p_provider_slug, v_workspace_id, p_user_id, 'owner', 'active',
    p_proof_method, p_proof_subject, case when p_proof_method = 'self_declared' then null else now() end);

  update public.users set default_workspace_id = v_workspace_id
  where user_id = p_user_id and lower(coalesce(role::text, 'user')) <> 'admin';
  return v_workspace_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."link_provider_personal_account"(uuid, text, text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."link_provider_personal_account"(uuid, text, text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/list_slack_agent_due_charges.sql
CREATE OR REPLACE FUNCTION public.list_slack_agent_due_charges (
  p_before date,
  p_limit  integer DEFAULT 200
)
  RETURNS TABLE (
    installation_id   uuid,
    workspace_id      uuid,
    period_start      date,
    people            integer,
    answers           bigint,
    monthly_cap_nanos bigint
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- Months that ended before p_before and have no completed charge. Never-tried
  -- months come first, then the longest-waiting retries, so a backlog of
  -- workspaces short of credits cannot starve the rest.
  select person.installation_id, installation.workspace_id, person.period_start,
    count(*)::integer, sum(person.answers)::bigint, installation.monthly_cap_nanos
  from public.slack_agent_monthly_people person
  join public.slack_installations installation on installation.id = person.installation_id
  left join public.slack_agent_charges charge
    on charge.installation_id = person.installation_id and charge.period_start = person.period_start
  where person.period_start < p_before
    and coalesce(charge.status, 'pending') = 'pending'
  group by person.installation_id, installation.workspace_id, person.period_start,
    installation.monthly_cap_nanos, charge.attempted_at
  order by charge.attempted_at nulls first, person.period_start, person.installation_id
  limit greatest(1, least(coalesce(p_limit, 200), 1000));
$function$;

COMMENT ON FUNCTION "public"."list_slack_agent_due_charges"(date, integer) IS 'People and pooled answers per installation for each finished UTC month that has not been charged yet, for the month-end charge job.';

GRANT EXECUTE ON FUNCTION "public"."list_slack_agent_due_charges"(date, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."list_slack_agent_due_charges"(date, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/list_slack_agent_installations.sql
CREATE OR REPLACE FUNCTION public.list_slack_agent_installations (
  p_period_start date,
  p_limit        integer DEFAULT 100,
  p_offset       integer DEFAULT 0
)
  RETURNS TABLE (
    installation_id   uuid,
    workspace_id      uuid,
    workspace_name    text,
    team_id           text,
    team_name         text,
    enterprise_id     text,
    custom_app        boolean,
    slack_app_id      text,
    status            text,
    installed_at      timestamp with time zone,
    uninstalled_at    timestamp with time zone,
    plan_people       integer,
    monthly_cap_nanos bigint,
    people            integer,
    answers           bigint,
    model_requests    bigint,
    model_cost_nanos  bigint,
    total             bigint
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
-- Every Slack agent installation, newest first, for the internal Slack agent page:
-- one row each with the month's people and pooled answers and the model requests
-- and spend through the installation's own key, all summed here so the page never
-- adds up rows itself. total counts every installation, for paging. Service role
-- only: web-api checks that the caller is a Phaseo admin first.
begin
  if p_period_start is null or p_period_start <> date_trunc('month', p_period_start)::date then
    raise exception 'invalid_period_start' using errcode = '22023';
  end if;

  return query
  with page as (
    select installation.*, count(*) over () as total
    from public.slack_installations installation
    order by installation.installed_at desc, installation.id desc
    limit greatest(1, least(coalesce(p_limit, 100), 200))
    offset greatest(0, coalesce(p_offset, 0))
  )
  select page.id,
    page.workspace_id,
    workspace.name,
    page.team_id,
    page.team_name,
    page.enterprise_id,
    page.slack_app_id is not null,
    app.slack_app_id,
    page.status,
    page.installed_at,
    page.uninstalled_at,
    page.plan_people,
    page.monthly_cap_nanos,
    this_month.people,
    this_month.answers,
    spend.requests,
    spend.cost_nanos,
    page.total
  from page
  left join public.workspaces workspace on workspace.id = page.workspace_id
  left join public.slack_apps app on app.id = page.slack_app_id
  -- Served by the primary key (installation_id, period_start, slack_user_id).
  cross join lateral (
    select count(*)::integer as people, coalesce(sum(person.answers), 0)::bigint as answers
    from public.slack_agent_monthly_people person
    where person.installation_id = page.id
      and person.period_start = p_period_start
  ) this_month
  -- Served by the (workspace_id, bucket_start, ...) unique index. The key is kept
  -- (deleted) after an uninstall, so its spend earlier in the month still counts.
  cross join lateral (
    select coalesce(sum(usage.requests), 0)::bigint as requests, coalesce(sum(usage.cost_nanos), 0)::bigint as cost_nanos
    from public.v2_private_usage_15m usage
    where page.key_id is not null
      and usage.workspace_id = page.workspace_id
      and usage.key_id = page.key_id
      and usage.bucket_start >= p_period_start::timestamp at time zone 'UTC'
      and usage.bucket_start < (p_period_start + interval '1 month') at time zone 'UTC'
  ) spend
  order by page.installed_at desc, page.id desc;
end;
$function$;

COMMENT ON FUNCTION "public"."list_slack_agent_installations"(date, integer, integer) IS 'Every Slack agent installation, newest first, with its Phaseo workspace, the UTC month''s people and pooled answers, and the model requests and spend through its key, summed in the database. For the internal Slack agent page; service role only.';

GRANT EXECUTE ON FUNCTION "public"."list_slack_agent_installations"(date, integer, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."list_slack_agent_installations"(date, integer, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/list_spend_block_workspaces.sql
CREATE OR REPLACE FUNCTION public.list_spend_block_workspaces (
  p_limit integer DEFAULT 2000
)
  RETURNS SETOF uuid
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- Workspaces that can have a gateway spend block entry: an enabled block rule, or an active
  -- block. The scheduled reconcile republishes these (plus every key already in KV), so a missed
  -- publish never lasts. Up to p_limit (1-10000), in id order.
  select workspace_id from (
    select rule.workspace_id from public.workspace_spend_rules rule
    where rule.action = 'block' and rule.enabled and rule.deleted_at is null
    union
    select block.workspace_id from public.workspace_spend_blocks block
    where block.lifted_at is null
  ) due
  order by workspace_id
  limit greatest(1, least(coalesce(p_limit, 2000), 10000));
$function$;

COMMENT ON FUNCTION "public"."list_spend_block_workspaces"(integer) IS 'Workspaces with an enabled block spend rule or an active spend block, for the scheduled republish of the gateway''s spend block entries. Service role only.';

REVOKE ALL ON FUNCTION "public"."list_spend_block_workspaces"(integer) FROM PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."list_spend_block_workspaces"(integer) TO "service_role";

-- source: supabase/schemas/public/functions/list_workspace_spend_blocks.sql
CREATE OR REPLACE FUNCTION public.list_workspace_spend_blocks (
  p_workspace_id   uuid,
  p_include_lifted boolean DEFAULT false,
  p_limit          integer DEFAULT 50,
  p_block_id       uuid    DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- A workspace's spend blocks for the control API and Settings, newest first: active ones only,
  -- or with p_include_lifted also lifted ones (up to p_limit, 1-100), or the one p_block_id names.
  -- Each has its rule's current name and the scope's display name. A block whose reset has passed
  -- but that the sweep has not lifted yet is listed as active: false.
  select coalesce(jsonb_agg(item.block order by item.started_at desc, item.id), '[]'::jsonb)
  from (
    select block.id, block.started_at, jsonb_build_object(
      'id', block.id,
      'workspace_id', block.workspace_id,
      'rule_id', block.rule_id,
      'rule_name', rule.name,
      'scope_type', block.scope_type,
      'scope_id', block.scope_id,
      'scope_label', private.spend_scope_label(block.workspace_id, block.scope_type, block.scope_id),
      'block_free_models', block.block_free_models,
      'period_start', block.period_start,
      'resets_at', block.resets_at,
      'spend_nanos', block.spend_nanos,
      'limit_nanos', block.limit_nanos,
      'started_at', block.started_at,
      'lifted_at', block.lifted_at,
      'lifted_by', block.lifted_by,
      'lift_reason', block.lift_reason,
      'active', block.lifted_at is null and (block.resets_at is null or block.resets_at > now())
    ) as block
    from public.workspace_spend_blocks block
    left join public.workspace_spend_rules rule on rule.id = block.rule_id
    where block.workspace_id = p_workspace_id
      and case
        when p_block_id is not null then block.id = p_block_id
        when coalesce(p_include_lifted, false) then true
        else block.lifted_at is null
      end
    order by block.started_at desc, block.id
    limit greatest(1, least(coalesce(p_limit, 50), 100))
  ) item;
$function$;

COMMENT ON FUNCTION "public"."list_workspace_spend_blocks"(uuid, boolean, integer, uuid) IS 'A workspace''s spend blocks, newest first (active only by default), with rule and scope names. Service role only (control API and web-api).';

REVOKE ALL ON FUNCTION "public"."list_workspace_spend_blocks"(uuid, boolean, integer, uuid) FROM PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."list_workspace_spend_blocks"(uuid, boolean, integer, uuid) TO "service_role";

-- source: supabase/schemas/public/functions/list_workspace_spend_rule_history.sql
CREATE OR REPLACE FUNCTION public.list_workspace_spend_rule_history (
  p_workspace_id uuid,
  p_rule_id      uuid,
  p_limit        integer DEFAULT 50,
  p_offset       integer DEFAULT 0
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- A spend rule's history, newest first: the events it queued (email_outbox spend_alert and
-- spend_blocked rows whose payload names the rule, read through
-- email_outbox_spend_rule_events_idx) with their delivery counts, one page of p_limit (1-100)
-- after p_offset, plus its 12 latest workspace_spend_rule_state rows. Test sends write nothing,
-- so they are not here. Errors: spend_rule_not_found, invalid_spend_rule_history_page.
-- Returns {events: [...], has_more, periods: [...]}.
declare
  v_events jsonb;
  v_has_more boolean;
  v_periods jsonb;
begin
  if p_workspace_id is null or p_rule_id is null
    or p_limit is null or p_limit < 1 or p_limit > 100
    or p_offset is null or p_offset < 0 or p_offset > 100000 then
    raise exception 'invalid_spend_rule_history_page' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.workspace_spend_rules rule
    where rule.id = p_rule_id and rule.workspace_id = p_workspace_id and rule.deleted_at is null
  ) then
    raise exception 'spend_rule_not_found' using errcode = 'P0002';
  end if;

  with candidates as (
    select event.id, event.kind, event.created_at, event.payload
    from public.email_outbox event
    where (event.payload ->> 'rule_id') = p_rule_id::text
      and event.kind = any (array['spend_alert', 'spend_blocked'])
      and event.workspace_id = p_workspace_id
    order by event.created_at desc, event.id desc
    limit p_limit + 1
    offset p_offset
  ),
  page as (
    select candidates.*, row_number() over (order by candidates.created_at desc, candidates.id desc) as position
    from candidates
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', page.id,
      'kind', page.kind,
      'created_at', page.created_at,
      'title', page.payload ->> 'title',
      'message', page.payload ->> 'message',
      'state', page.payload ->> 'state',
      'threshold_percent', page.payload -> 'threshold_percent',
      'thresholds_crossed', page.payload -> 'thresholds_crossed',
      'threshold_amount_nanos', page.payload -> 'threshold_amount_nanos',
      'value_nanos', page.payload -> 'value_nanos',
      'base_nanos', page.payload -> 'base_nanos',
      'percent', page.payload -> 'percent',
      'period', page.payload -> 'period',
      'deliveries', jsonb_build_object('sent', deliveries.sent, 'failed', deliveries.failed, 'pending', deliveries.pending)
    ) order by page.position) filter (where page.position <= p_limit), '[]'::jsonb),
    count(*) > p_limit
    into v_events, v_has_more
  from page
  cross join lateral (
    select
      count(*) filter (where attempt.status = 'sent') as sent,
      count(*) filter (where attempt.status = 'failed') as failed,
      count(*) filter (where attempt.status not in ('sent', 'failed')) as pending
    from public.notification_delivery_attempts attempt
    where attempt.event_id = page.id
  ) deliveries;

  select coalesce(jsonb_agg(jsonb_build_object(
      'period_start', case when isfinite(state.period_start) then state.period_start end,
      'period_end', state.period_end,
      'highest_percent_fired', state.highest_percent_fired,
      'amount_fired_at', state.amount_fired_at,
      'last_fired_at', state.last_fired_at,
      'fire_count', state.fire_count,
      'last_value_nanos', state.last_value_nanos,
      'last_base_nanos', state.last_base_nanos
    ) order by state.period_start desc), '[]'::jsonb)
    into v_periods
  from (
    select * from public.workspace_spend_rule_state recent
    where recent.rule_id = p_rule_id and recent.workspace_id = p_workspace_id
    order by recent.period_start desc
    limit 12
  ) state;

  return jsonb_build_object('events', v_events, 'has_more', coalesce(v_has_more, false), 'periods', v_periods);
end;
$function$;

COMMENT ON FUNCTION "public"."list_workspace_spend_rule_history"(uuid, uuid, integer, integer) IS 'One page of a spend rule''s queued events (spend_alert, spend_blocked) with delivery counts, newest first, plus its 12 latest state rows. Service role only (control API and web-api).';

REVOKE ALL ON FUNCTION "public"."list_workspace_spend_rule_history"(uuid, uuid, integer, integer) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."list_workspace_spend_rule_history"(uuid, uuid, integer, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."list_workspace_spend_rule_history"(uuid, uuid, integer, integer) FROM "anon", "authenticated";

-- source: supabase/schemas/public/functions/load_slack_agent_turn_memory.sql
CREATE OR REPLACE FUNCTION public.load_slack_agent_turn_memory (
  p_installation_id uuid,
  p_channel_id      text,
  p_workspace_notes boolean
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
-- What the Slack agent is shown of its memory on every turn: the conversation's
-- pins and, with p_workspace_notes, the whole Slack workspace's, newest first and
-- 10 of each at most, and the names and descriptions of the 20 saved skills
-- changed most recently, with how many there are. No pins while an admin has
-- turned the installation's memory off (memory_enabled), and none of the
-- workspace's for someone from another organisation (the Worker passes false).
-- Expired notes are deleted here first, so none outlasts its date by more than a
-- turn. Returns {pins: [{id, scope, text, created_at}], skills: [{name,
-- description}], skills_total}. Service role only.
declare
  v_memory_enabled boolean := coalesce((
    select installation.memory_enabled from public.slack_installations installation where installation.id = p_installation_id
  ), false);
begin
  delete from public.slack_agent_notes note
  where note.installation_id = p_installation_id and note.expires_at <= now();

  return jsonb_build_object(
    'pins', coalesce((
      select jsonb_agg(jsonb_build_object('id', pin.id, 'scope', pin.scope, 'text', pin.text, 'created_at', pin.created_at)
        order by pin.scope, pin.created_at desc, pin.id)
      from (
        (select note.id, 'channel'::text as scope, note.text, note.created_at
          from public.slack_agent_notes note
          where v_memory_enabled
            and note.installation_id = p_installation_id and note.kind = 'pin' and note.channel_id = p_channel_id
          order by note.created_at desc, note.id
          limit 10)
        union all
        (select note.id, 'workspace'::text, note.text, note.created_at
          from public.slack_agent_notes note
          where v_memory_enabled and coalesce(p_workspace_notes, false)
            and note.installation_id = p_installation_id and note.kind = 'pin' and note.channel_id is null
          order by note.created_at desc, note.id
          limit 10)
      ) pin
    ), '[]'::jsonb),
    'skills', coalesce((
      select jsonb_agg(jsonb_build_object('name', skill.name, 'description', skill.description) order by skill.updated_at desc, skill.name)
      from (
        select recent.name, recent.description, recent.updated_at
        from public.slack_agent_skills recent
        where recent.installation_id = p_installation_id
        order by recent.updated_at desc, recent.name
        limit 20
      ) skill
    ), '[]'::jsonb),
    'skills_total', (select count(*) from public.slack_agent_skills skill where skill.installation_id = p_installation_id)
  );
end;
$function$;

COMMENT ON FUNCTION "public"."load_slack_agent_turn_memory"(uuid, text, boolean) IS 'For the Slack Worker on every turn: up to 10 of the conversation''s pins and, with p_workspace_notes, 10 of the Slack workspace''s (none while the installation''s memory is off), and the 20 most recently changed saved skills'' names and descriptions with the total. Deletes the installation''s expired notes first.';

GRANT EXECUTE ON FUNCTION "public"."load_slack_agent_turn_memory"(uuid, text, boolean) TO "service_role";

REVOKE ALL ON FUNCTION "public"."load_slack_agent_turn_memory"(uuid, text, boolean) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/lock_workspace_budget_change.sql
CREATE OR REPLACE FUNCTION public.lock_workspace_budget_change()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_workspace_id uuid;
begin
  v_workspace_id := case when tg_op = 'DELETE' then old.workspace_id else new.workspace_id end;
  perform pg_advisory_xact_lock(hashtextextended(v_workspace_id::text, 0));
  if tg_op = 'UPDATE' then
    new.updated_at := now();
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."lock_workspace_budget_change"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/machine_payment_attach_job.sql
CREATE OR REPLACE FUNCTION public.machine_payment_attach_job (
  p_authorization_id uuid,
  p_job_kind         text,
  p_job_id           text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  if p_job_kind not in ('video','batch') or nullif(trim(p_job_id),'') is null then raise exception 'invalid_job'; end if;
  update public.machine_payment_authorizations set job_kind=p_job_kind, job_id=p_job_id, status='executing'
  where id=p_authorization_id and status in ('claimed','executing') and (job_id is null or (job_kind=p_job_kind and job_id=p_job_id));
  if not found then raise exception 'authorization_job_conflict'; end if;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."machine_payment_attach_job"(uuid, text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."machine_payment_attach_job"(uuid, text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/machine_payment_claim_authorization.sql
CREATE OR REPLACE FUNCTION public.machine_payment_claim_authorization (
  p_challenge_id              uuid,
  p_protocol                  public.machine_payment_protocol,
  p_mode                      public.machine_payment_mode,
  p_payer_id                  text,
  p_external_authorization_id text,
  p_credential_fingerprint    text,
  p_request_hash              text,
  p_pricing_snapshot_hash     text,
  p_max_amount_nanos          bigint,
  p_expires_at                timestamp with time zone,
  p_request_id                text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare v_challenge public.machine_payment_challenges; v_auth public.machine_payment_authorizations;
begin
  select * into v_challenge from public.machine_payment_challenges where id = p_challenge_id for update;
  if not found or v_challenge.status <> 'open' or v_challenge.expires_at <= now() then raise exception 'challenge_unavailable'; end if;
  if not (p_protocol = any(v_challenge.allowed_protocols)) then raise exception 'protocol_not_allowed'; end if;
  if v_challenge.request_hash <> p_request_hash or v_challenge.pricing_snapshot_hash <> p_pricing_snapshot_hash then raise exception 'payment_binding_mismatch'; end if;
  if p_max_amount_nanos < v_challenge.amount_nanos or p_expires_at <= now() then raise exception 'authorization_insufficient_or_expired'; end if;
  insert into public.machine_payment_authorizations(challenge_id, protocol, mode, payer_id, external_authorization_id, request_hash, pricing_snapshot_hash, max_amount_nanos, credential_fingerprint, expires_at, claimed_request_id, status, claimed_at)
  values (p_challenge_id, p_protocol, p_mode, p_payer_id, p_external_authorization_id, p_request_hash, p_pricing_snapshot_hash, p_max_amount_nanos, p_credential_fingerprint, least(p_expires_at, v_challenge.expires_at), p_request_id, 'claimed', now()) returning * into v_auth;
  update public.machine_payment_challenges set status = 'authorized', updated_at = now() where id = p_challenge_id;
  insert into public.machine_payment_events(authorization_id, challenge_id, event_type, idempotency_key)
  values (v_auth.id, p_challenge_id, 'authorization.claimed', 'authorization.claimed:' || v_auth.id);
  return jsonb_build_object('kind','machine_payment','protocol',v_auth.protocol,'payerId',v_auth.payer_id,'authorizationId',v_auth.id,'challengeId',v_auth.challenge_id,'requestHash',v_auth.request_hash,'pricingSnapshotHash',v_auth.pricing_snapshot_hash,'maxAmountNanos',v_auth.max_amount_nanos,'currency',v_auth.currency,'mode',v_auth.mode);
exception when unique_violation then raise exception 'payment_replay_detected';
end $function$;

GRANT EXECUTE
  ON FUNCTION "public"."machine_payment_claim_authorization"(uuid, public.machine_payment_protocol, public.machine_payment_mode, text, text, text, text, text, bigint, timestamp
    WITH time zone, text)
  TO "service_role";

REVOKE ALL
  ON FUNCTION "public"."machine_payment_claim_authorization"(uuid, public.machine_payment_protocol, public.machine_payment_mode, text, text, text, text, text, bigint, timestamp
    WITH time zone, text)
  FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/machine_payment_create_challenge.sql
CREATE OR REPLACE FUNCTION public.machine_payment_create_challenge (
  p_request_hash          text,
  p_pricing_snapshot_hash text,
  p_endpoint              text,
  p_model                 text,
  p_amount_nanos          bigint,
  p_allowed_protocols     public.machine_payment_protocol[],
  p_expires_at            timestamp with time zone,
  p_metadata              jsonb                             DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare v_row public.machine_payment_challenges;
begin
  if p_expires_at <= now() or p_expires_at > now() + interval '15 minutes' then raise exception 'invalid_challenge_expiry'; end if;
  if p_amount_nanos <= 0 or coalesce(array_length(p_allowed_protocols, 1), 0) = 0 then raise exception 'invalid_challenge'; end if;
  insert into public.machine_payment_challenges(request_hash, pricing_snapshot_hash, endpoint, model, amount_nanos, allowed_protocols, expires_at, metadata)
  values (p_request_hash, p_pricing_snapshot_hash, p_endpoint, p_model, p_amount_nanos, p_allowed_protocols, p_expires_at, coalesce(p_metadata, '{}'::jsonb)) returning * into v_row;
  insert into public.machine_payment_events(challenge_id, event_type, idempotency_key, payload)
  values (v_row.id, 'challenge.created', 'challenge.created:' || v_row.id, jsonb_build_object('amount_nanos', v_row.amount_nanos));
  return to_jsonb(v_row);
end $function$;

GRANT EXECUTE
  ON FUNCTION "public"."machine_payment_create_challenge"(text, text, text, text, bigint, public.machine_payment_protocol[], timestamp WITH time zone, jsonb)
  TO "service_role";

REVOKE ALL
  ON FUNCTION "public"."machine_payment_create_challenge"(text, text, text, text, bigint, public.machine_payment_protocol[], timestamp WITH time zone, jsonb)
  FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/machine_payment_protocol_store_cas.sql
CREATE OR REPLACE FUNCTION public.machine_payment_protocol_store_cas (
  p_key              text,
  p_expected_version bigint,
  p_delete           boolean,
  p_value            jsonb,
  p_expires_at       timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  if p_expected_version = 0 then
    insert into public.machine_payment_protocol_store(key,value,expires_at) values(p_key,p_value,p_expires_at) on conflict do nothing;
  elsif p_delete then
    delete from public.machine_payment_protocol_store where key=p_key and version=p_expected_version;
  else
    update public.machine_payment_protocol_store set value=p_value,version=version+1,expires_at=p_expires_at,updated_at=now() where key=p_key and version=p_expected_version;
  end if;
  if not found then raise exception 'store_version_conflict'; end if;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."machine_payment_protocol_store_cas"(text, bigint, boolean, jsonb, timestamp WITH time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."machine_payment_protocol_store_cas"(text, bigint, boolean, jsonb, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/machine_payment_protocol_store_put.sql
CREATE OR REPLACE FUNCTION public.machine_payment_protocol_store_put (
  p_key        text,
  p_value      jsonb,
  p_expires_at timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS void
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  insert into public.machine_payment_protocol_store(key,value,expires_at) values(p_key,p_value,p_expires_at)
  on conflict(key) do update set value=excluded.value,version=machine_payment_protocol_store.version+1,expires_at=excluded.expires_at,updated_at=now();
$function$;

GRANT EXECUTE ON FUNCTION "public"."machine_payment_protocol_store_put"(text, jsonb, timestamp WITH time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."machine_payment_protocol_store_put"(text, jsonb, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/machine_payment_protocol_store_try_claim.sql
CREATE OR REPLACE FUNCTION public.machine_payment_protocol_store_try_claim (
  p_key        text,
  p_expires_at timestamp with time zone
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  insert into public.machine_payment_protocol_store(key,value,expires_at)
  values(p_key,jsonb_build_object('type','mppx:replay','expires',extract(epoch from p_expires_at)*1000),p_expires_at)
  on conflict(key) do update set value=excluded.value,version=machine_payment_protocol_store.version+1,expires_at=excluded.expires_at,updated_at=now()
  where machine_payment_protocol_store.expires_at is not null and machine_payment_protocol_store.expires_at <= now();
  return found;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."machine_payment_protocol_store_try_claim"(text, timestamp WITH time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."machine_payment_protocol_store_try_claim"(text, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/machine_payment_settle_once.sql
CREATE OR REPLACE FUNCTION public.machine_payment_settle_once (
  p_authorization_id    uuid,
  p_request_id          text,
  p_actual_amount_nanos bigint,
  p_usage               jsonb   DEFAULT NULL::jsonb,
  p_provider            text    DEFAULT NULL::text,
  p_receipt             jsonb   DEFAULT NULL::jsonb,
  p_release             boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare v_auth public.machine_payment_authorizations; v_settlement public.machine_payment_settlements;
begin
  select * into v_auth from public.machine_payment_authorizations where id = p_authorization_id for update;
  if not found or v_auth.claimed_request_id <> p_request_id then raise exception 'authorization_not_claimed_for_request'; end if;
  if v_auth.status in ('settled','released') then
    select * into v_settlement from public.machine_payment_settlements where authorization_id = v_auth.id;
    return jsonb_build_object('idempotent',true,'authorization_id',v_auth.id,'status',v_auth.status,'actual_amount_nanos',coalesce(v_settlement.actual_amount_nanos,0),'receipt',v_settlement.receipt);
  end if;
  if p_actual_amount_nanos < 0 or p_actual_amount_nanos > v_auth.max_amount_nanos then raise exception 'settlement_exceeds_authorization'; end if;
  insert into public.machine_payment_settlements(authorization_id, request_id, actual_amount_nanos, provider, usage, receipt)
  values (v_auth.id, p_request_id, case when p_release then 0 else p_actual_amount_nanos end, p_provider, p_usage, p_receipt) returning * into v_settlement;
  update public.machine_payment_authorizations
  set status = (case when p_release then 'released' else 'settled' end)::public.machine_payment_authorization_status,
      settled_at = now()
  where id = v_auth.id;
  insert into public.machine_payment_events(authorization_id, challenge_id, event_type, idempotency_key, payload)
  values (v_auth.id, v_auth.challenge_id, case when p_release then 'authorization.released' else 'authorization.settled' end, 'authorization.finalized:' || v_auth.id, jsonb_build_object('actual_amount_nanos',v_settlement.actual_amount_nanos));
  return jsonb_build_object('idempotent',false,'authorization_id',v_auth.id,'status',case when p_release then 'released' else 'settled' end,'actual_amount_nanos',v_settlement.actual_amount_nanos);
end $function$;

GRANT EXECUTE ON FUNCTION "public"."machine_payment_settle_once"(uuid, text, bigint, jsonb, text, jsonb, boolean) TO "service_role";

REVOKE ALL ON FUNCTION "public"."machine_payment_settle_once"(uuid, text, bigint, jsonb, text, jsonb, boolean) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/management_decide_workspace_join_request.sql
CREATE OR REPLACE FUNCTION public.management_decide_workspace_join_request (
  p_workspace_id  uuid,
  p_request_id    uuid,
  p_decision      text,
  p_actor_user_id uuid
)
  RETURNS TABLE (
    id                uuid,
    workspace_id      uuid,
    requester_user_id uuid,
    invite_id         uuid,
    status            public.join_request_status,
    decided_at        timestamp with time zone,
    decided_by        uuid
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_request public.workspace_join_requests%rowtype;
  v_role public.workspace_role := 'member'::public.workspace_role;
  v_status public.join_request_status;
begin
  if p_actor_user_id is null then
    raise exception using errcode = '23514', message = 'Decision actor is required';
  end if;
  if p_decision not in ('approve', 'reject') then
    raise exception using errcode = '23514', message = 'Decision must be approve or reject';
  end if;

  select * into v_request
  from public.workspace_join_requests request
  where request.id = p_request_id
    and request.workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'Join request not found';
  end if;
  if v_request.status <> 'pending'::public.join_request_status then
    raise exception using errcode = '23514', message = 'Join request already decided';
  end if;

  if p_decision = 'approve' then
    if v_request.invite_id is not null then
      update public.workspace_invites invite
      set uses_count = coalesce(invite.uses_count, 0) + 1
      where invite.id = v_request.invite_id
        and invite.workspace_id = p_workspace_id
        and (invite.expires_at is null or invite.expires_at > now())
        and (invite.max_uses is null or coalesce(invite.uses_count, 0) < invite.max_uses)
      returning invite.role into v_role;
      if not found then
        raise exception using errcode = '23514', message = 'Invite is no longer valid';
      end if;
    end if;

    insert into public.workspace_members (workspace_id, user_id, role)
    values (p_workspace_id, v_request.requester_user_id, v_role)
    on conflict (workspace_id, user_id) do nothing;
    v_status := 'approved'::public.join_request_status;
  else
    v_status := 'denied'::public.join_request_status;
  end if;

  return query
  update public.workspace_join_requests request
  set status = v_status,
      decided_by = p_actor_user_id,
      decided_at = now()
  where request.id = v_request.id
    and request.status = 'pending'::public.join_request_status
  returning request.id, request.workspace_id, request.requester_user_id,
    request.invite_id, request.status, request.decided_at, request.decided_by;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."management_decide_workspace_join_request"(uuid, uuid, text, uuid) TO "service_role";

COMMENT ON FUNCTION "public"."management_decide_workspace_join_request"(uuid, uuid, text, uuid) IS 'Atomically approves or rejects a workspace join request for the management API service role.';

REVOKE ALL ON FUNCTION "public"."management_decide_workspace_join_request"(uuid, uuid, text, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/management_delete_workspace_department_member.sql
CREATE OR REPLACE FUNCTION public.management_delete_workspace_department_member (
  p_workspace_id  uuid,
  p_department_id uuid,
  p_user_id       uuid,
  p_actor_user_id uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  delete from public.workspace_department_grants
  where workspace_id=p_workspace_id and department_id=p_department_id and user_id=p_user_id and source_type='manual';
  if not found then return false; end if;
  perform public.refresh_workspace_effective_entitlements(p_workspace_id,p_actor_user_id,'department_membership_deleted');
  return true;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."management_delete_workspace_department_member"(uuid, uuid, uuid, uuid) TO "service_role";

