-- source: supabase/schemas/public/functions/mutate_v2_admin_model_graph.sql
CREATE OR REPLACE FUNCTION public.mutate_v2_admin_model_graph (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_payload       jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare v_before jsonb; v_after jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  perform set_config('phaseo.catalogue_actor', p_actor_user_id::text, true);
  select to_jsonb(t) into v_before from public.v2_models t where model_slug=p_model_slug for update;
  if v_before is null then raise exception 'model not found'; end if;

  update public.v2_models set
    name=coalesce(p_payload->>'name',name), lab_slug=coalesce(p_payload->>'organisation_id',lab_slug),
    status=coalesce(lower(p_payload->>'status'),status), hidden=coalesce((p_payload->>'hidden')::boolean,hidden),
    family_slug=case when p_payload ? 'family_id' then nullif(p_payload->>'family_id','') else family_slug end,
    input_modalities=case when p_payload ? 'input_types' then string_to_array(coalesce(p_payload->>'input_types',''),',') else input_modalities end,
    output_modalities=case when p_payload ? 'output_types' then string_to_array(coalesce(p_payload->>'output_types',''),',') else output_modalities end,
    announced_at=case when p_payload ? 'announcement_date' then nullif(p_payload->>'announcement_date','')::timestamptz else announced_at end,
    released_at=case when p_payload ? 'release_date' then nullif(p_payload->>'release_date','')::timestamptz else released_at end,
    deprecated_at=case when p_payload ? 'deprecation_date' then nullif(p_payload->>'deprecation_date','')::timestamptz else deprecated_at end,
    retired_at=case when p_payload ? 'retirement_date' then nullif(p_payload->>'retirement_date','')::timestamptz else retired_at end,
    metadata=metadata||jsonb_strip_nulls(jsonb_build_object('license',p_payload->>'license','previous_model_id',p_payload->>'previous_model_id','source','admin')),updated_at=now()
  where model_slug=p_model_slug;

  if p_payload ? 'family' then
    insert into public.v2_model_families(family_slug,lab_slug,name,metadata,updated_at)
    values(p_payload->'family'->>'family_id',(select lab_slug from public.v2_models where model_slug=p_model_slug),p_payload->'family'->>'family_name',jsonb_strip_nulls(jsonb_build_object('description',p_payload->'family'->>'family_description','source','admin')),now())
    on conflict(family_slug) do update set name=excluded.name,metadata=public.v2_model_families.metadata||excluded.metadata,updated_at=now();
    update public.v2_models set family_slug=p_payload->'family'->>'family_id',updated_at=now() where model_slug=p_model_slug;
  end if;

  if p_payload ? 'model_details' then
    delete from public.v2_model_details where model_slug=p_model_slug;
    insert into public.v2_model_details(model_slug,detail_name,detail_value,detail_order)
    select p_model_slug,x->>'detail_name',coalesce(x->'detail_value',to_jsonb(x->>'detail_value')),100+row_number() over()
    from jsonb_array_elements(p_payload->'model_details') x;
  end if;
  if p_payload ? 'links' then
    delete from public.v2_model_links where model_slug=p_model_slug;
    insert into public.v2_model_links(model_slug,link_kind,title,url,metadata)
    select p_model_slug,coalesce(nullif(x->>'kind',''),x->>'platform'),coalesce(nullif(x->>'title',''),x->>'platform'),x->>'url',jsonb_build_object('source','admin') from jsonb_array_elements(p_payload->'links') x;
  end if;
  if p_payload ? 'benchmark_results' then
    if exists(select 1 from jsonb_array_elements(p_payload->'benchmark_results') x
      join public.v2_benchmark_results r on r.result_id::text=x->>'id' where r.model_slug<>p_model_slug)
      then raise exception 'benchmark result belongs to another model'; end if;
    insert into public.v2_benchmark_results(result_id,model_slug,benchmark_id,score,score_numeric,is_self_reported,other_info,source_link,variant,effective_to,updated_at)
    select coalesce(nullif(x->>'id','')::uuid,gen_random_uuid()),p_model_slug,x->>'benchmark_id',x->>'score',
      case when (x->>'score')~'^[-+]?[0-9]*\.?[0-9]+$' then (x->>'score')::numeric end,
      coalesce((x->>'is_self_reported')::boolean,false),nullif(x->>'other_info',''),nullif(x->>'source_link',''),nullif(x->>'variant',''),nullif(x->>'effective_to','')::timestamptz,now()
    from jsonb_array_elements(p_payload->'benchmark_results') x
    on conflict(result_id) do update set benchmark_id=excluded.benchmark_id,score=excluded.score,score_numeric=excluded.score_numeric,
      is_self_reported=excluded.is_self_reported,other_info=excluded.other_info,source_link=excluded.source_link,variant=excluded.variant,effective_to=excluded.effective_to,updated_at=now();
  end if;
  if p_payload ? 'subscription_plan_models' then
    insert into public.v2_subscription_plan_models(plan_uuid,model_slug,model_info,rate_limit,other_info,effective_to)
    select (x->>'plan_uuid')::uuid,p_model_slug,coalesce(x->'model_info','{}'::jsonb),coalesce(x->'rate_limit','{}'::jsonb),coalesce(x->'other_info','{}'::jsonb),nullif(x->>'effective_to','')::timestamptz
    from jsonb_array_elements(p_payload->'subscription_plan_models') x
    on conflict(plan_uuid,model_slug) do update set model_info=excluded.model_info,rate_limit=excluded.rate_limit,other_info=excluded.other_info,effective_to=excluded.effective_to;
  end if;
  if p_payload ? 'provider_models' then
    if exists(select 1 from jsonb_array_elements(p_payload->'provider_models') x
      join public.v2_model_provider_routes r on r.provider_model_id=x->>'id'
      where r.model_slug<>p_model_slug) then raise exception 'provider route belongs to another model'; end if;
    insert into public.v2_model_provider_routes(provider_model_id,model_slug,provider_slug,provider_model_slug,status,routing_enabled,input_modalities,output_modalities,context_length,max_output_tokens,effective_from,effective_to,metadata,updated_at)
    select
      case when coalesce(x->>'id','') like 'new-%' or coalesce(x->>'id','')='' then (x->>'provider_id')||':'||p_model_slug||':'||coalesce(nullif(x->>'provider_model_slug',''),x->>'api_model_id') else x->>'id' end,
      p_model_slug,x->>'provider_id',coalesce(nullif(x->>'provider_model_slug',''),x->>'api_model_id'),'active',coalesce((x->>'is_active_gateway')::boolean,false),
      case when jsonb_typeof(x->'input_modalities')='array' then array(select jsonb_array_elements_text(x->'input_modalities')) else string_to_array(coalesce(x->>'input_modalities',''),',') end,
      case when jsonb_typeof(x->'output_modalities')='array' then array(select jsonb_array_elements_text(x->'output_modalities')) else string_to_array(coalesce(x->>'output_modalities',''),',') end,
      nullif(x->>'context_length','')::integer,nullif(x->>'max_output_tokens','')::integer,nullif(x->>'effective_from','')::timestamptz,nullif(x->>'effective_to','')::timestamptz,
      jsonb_strip_nulls(jsonb_build_object('prompt_training_policy_override',x->>'prompt_training_policy_override','prompt_training_override_notes',x->>'prompt_training_override_notes','prompt_training_override_source_url',x->>'prompt_training_override_source_url','quantization_scheme',x->>'quantization_scheme','source','admin')),now()
    from (
      select distinct on (
        case when coalesce(entry.value->>'id','') like 'new-%' or coalesce(entry.value->>'id','')=''
          then (entry.value->>'provider_id')||':'||p_model_slug||':'||coalesce(nullif(entry.value->>'provider_model_slug',''),entry.value->>'api_model_id')
          else entry.value->>'id' end
      ) entry.value
      from jsonb_array_elements(p_payload->'provider_models') with ordinality entry(value, position)
      order by
        case when coalesce(entry.value->>'id','') like 'new-%' or coalesce(entry.value->>'id','')=''
          then (entry.value->>'provider_id')||':'||p_model_slug||':'||coalesce(nullif(entry.value->>'provider_model_slug',''),entry.value->>'api_model_id')
          else entry.value->>'id' end,
        entry.position desc
    ) deduplicated(x)
    on conflict(provider_model_id) do update set provider_slug=excluded.provider_slug,provider_model_slug=excluded.provider_model_slug,status=public.v2_model_provider_routes.status,routing_enabled=excluded.routing_enabled,input_modalities=excluded.input_modalities,output_modalities=excluded.output_modalities,context_length=excluded.context_length,max_output_tokens=excluded.max_output_tokens,effective_from=excluded.effective_from,effective_to=excluded.effective_to,metadata=public.v2_model_provider_routes.metadata||excluded.metadata,updated_at=now();
  end if;
  if p_payload ? 'provider_capabilities' then
    if exists (
      select 1 from jsonb_array_elements(p_payload->'provider_capabilities') x
      where not exists (
        select 1 from public.v2_model_provider_routes route
        where route.model_slug=p_model_slug and route.provider_slug=x->>'provider_id'
          and route.provider_model_slug=coalesce(nullif(x->>'provider_model_slug',''),x->>'api_model_id') and (nullif(x->>'provider_model_id','') is null or route.provider_model_id=x->>'provider_model_id')
      )
    ) then raise exception 'provider capability does not match a model route'; end if;
    insert into public.v2_route_capabilities(provider_model_id,capability_id,status,params,effective_from,effective_to,metadata,updated_at)
    select route.provider_model_id,x->>'capability_id',case when x->>'status' like 'deranked_%' then 'degraded' else coalesce(nullif(x->>'status',''),'active') end,coalesce(x->'params','{}'::jsonb),nullif(x->>'effective_from','')::timestamptz,nullif(x->>'effective_to','')::timestamptz,jsonb_build_object('editor_status',x->>'status','source','admin'),now()
    from jsonb_array_elements(p_payload->'provider_capabilities') x join public.v2_model_provider_routes route on route.model_slug=p_model_slug and route.provider_slug=x->>'provider_id' and route.provider_model_slug=coalesce(nullif(x->>'provider_model_slug',''),x->>'api_model_id') and (nullif(x->>'provider_model_id','') is null or route.provider_model_id=x->>'provider_model_id')
    on conflict(provider_model_id,capability_id) do update set status=excluded.status,params=excluded.params,
      effective_from=excluded.effective_from,effective_to=excluded.effective_to,
      metadata=public.v2_route_capabilities.metadata||excluded.metadata,updated_at=now();
  end if;
  select to_jsonb(t) into v_after from public.v2_models t where model_slug=p_model_slug;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state)
  values(p_actor_user_id,'model_graph',p_model_slug,'save',v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at)
  values('model',p_model_slug,'database_managed',p_actor_user_id,p_model_slug,now()) on conflict(source_type,source_key) do update set disposition='database_managed',actor_user_id=excluded.actor_user_id,updated_at=now();
  return jsonb_build_object('model',v_after);
end $function$;

GRANT EXECUTE ON FUNCTION "public"."mutate_v2_admin_model_graph"(uuid, text, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_model_graph"(uuid, text, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/mutate_v2_admin_model_notice.sql
CREATE OR REPLACE FUNCTION public.mutate_v2_admin_model_notice (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_notice        jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_before jsonb;
  v_after jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  if not exists(select 1 from public.v2_models where model_slug=p_model_slug) then raise exception 'model not found'; end if;
  if p_notice is not null and (jsonb_typeof(p_notice)<>'object' or jsonb_typeof(p_notice->'markdown') is distinct from 'string' or length(p_notice->>'markdown')>20000 or coalesce(p_notice->>'tone','') not in ('info','warning','critical')) then raise exception 'invalid model notice'; end if;
  perform pg_advisory_xact_lock(hashtextextended('model-notice:'||p_model_slug,0));
  perform set_config('phaseo.catalogue_actor',p_actor_user_id::text,true);
  select to_jsonb(t) into v_before from public.v2_model_page_notices t where model_slug=p_model_slug for update;
  if p_notice is null or nullif(trim(p_notice->>'markdown'),'') is null then
    delete from public.v2_model_page_notices where model_slug=p_model_slug;
  else
    insert into public.v2_model_page_notices(model_slug,tone,markdown,updated_at)
    values(p_model_slug,p_notice->>'tone',trim(p_notice->>'markdown'),now())
    on conflict(model_slug) do update set tone=excluded.tone,markdown=excluded.markdown,updated_at=now();
  end if;
  select to_jsonb(t) into v_after from public.v2_model_page_notices t where model_slug=p_model_slug;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state)
  values(p_actor_user_id,'model_notice',p_model_slug,case when v_after is null then 'delete' when v_before is null then 'create' else 'update' end,v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at)
  values('model',p_model_slug,'database_managed',p_actor_user_id,p_model_slug,now())
  on conflict(source_type,source_key) do update set disposition='database_managed',actor_user_id=excluded.actor_user_id,resource_id=excluded.resource_id,updated_at=now();
  return v_after;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."mutate_v2_admin_model_notice"(uuid, text, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_model_notice"(uuid, text, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/mutate_v2_admin_model_with_successor.sql
CREATE OR REPLACE FUNCTION public.mutate_v2_admin_model_with_successor (
  p_actor_user_id uuid,
  p_action        text,
  p_model_slug    text,
  p_payload       jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_result jsonb;
begin
  v_result := public.mutate_v2_admin_catalogue(p_actor_user_id, 'models', p_action, p_model_slug, p_payload);
  if p_payload ? 'replacementModelId' then
    perform public.set_v2_model_recommended_successor(p_actor_user_id, p_model_slug, p_payload->>'replacementModelId');
  end if;
  return v_result;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."mutate_v2_admin_model_with_successor"(uuid, text, text, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_model_with_successor"(uuid, text, text, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/mutate_v2_admin_pricing_sku.sql
CREATE OR REPLACE FUNCTION public.mutate_v2_admin_pricing_sku (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_action        text,
  p_sku           jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  v_sku_id uuid;
  v_provider_model_id text;
  v_existing public.v2_pricing_skus%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_meter jsonb;
  v_resource_id text;
  v_starts timestamptz;
  v_version integer;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;
  if coalesce(trim(p_model_slug), '') = '' then
    raise exception 'model_slug is required';
  end if;
  if p_action not in ('save', 'end_date') then
    raise exception 'unsupported pricing mutation action';
  end if;
  if not exists (
    select 1 from public.users
    where user_id = p_actor_user_id
      and lower(coalesce(role::text, '')) = 'admin'
  ) then
    raise exception 'actor must have the admin role';
  end if;

  if nullif(p_sku->>'sku_id', '') is not null then
    begin
      v_sku_id := (p_sku->>'sku_id')::uuid;
    exception when invalid_text_representation then
      raise exception 'sku_id must be a UUID';
    end;
  end if;

  if v_sku_id is not null then
    select * into v_existing
    from public.v2_pricing_skus
    where sku_id = v_sku_id for update;

    if found then
      select jsonb_build_object(
        'sku', to_jsonb(v_existing),
        'meters', coalesce((
          select jsonb_agg(to_jsonb(meter) order by meter.meter_order, meter.meter_key)
          from public.v2_pricing_sku_meters meter
          where meter.sku_id = v_sku_id
        ), '[]'::jsonb)
      ) into v_before;

      if not exists (
        select 1
        from public.v2_model_provider_routes route
        where route.provider_model_id = v_existing.provider_model_id
          and route.model_slug = p_model_slug
      ) then
        raise exception 'pricing SKU does not belong to the requested model';
      end if;
    end if;
  end if;

  if v_sku_id is not null and v_before is null then
    raise exception 'pricing SKU not found';
  end if;
  perform set_config('phaseo.catalogue_actor', p_actor_user_id::text, true);
  if p_action = 'end_date' then
    if v_before is null then raise exception 'pricing SKU not found'; end if;
    v_starts := nullif(p_sku->>'effective_to','')::timestamptz;
    if v_starts is null or v_starts <= v_existing.effective_from then
      raise exception 'end date must be after the start date';
    end if;
    if v_existing.effective_to is not null and v_existing.effective_to <= now() then
      raise exception 'historical prices cannot be changed';
    end if;
    if exists(select 1 from public.v2_pricing_skus where provider_model_id=v_existing.provider_model_id and sku_code=v_existing.sku_code and version>v_existing.version) then
      raise exception 'a superseded version cannot be changed';
    end if;
    update public.v2_pricing_skus set effective_to=v_starts,updated_at=now() where sku_id=v_sku_id;
    select jsonb_build_object('sku',to_jsonb(t),'meters',v_before->'meters') into v_after
      from public.v2_pricing_skus t where sku_id=v_sku_id;
    insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state)
      values(p_actor_user_id,'pricing_sku',v_sku_id::text,'update',v_before,v_after);
    if nullif(v_existing.metadata->>'source_key','') is not null then
      insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at)
        values('pricing_rule',v_existing.metadata->>'source_key','database_managed',p_actor_user_id,v_sku_id::text,now())
        on conflict(source_type,source_key) do update set disposition=excluded.disposition,actor_user_id=excluded.actor_user_id,resource_id=excluded.resource_id,updated_at=now();
    end if;
    return v_after;
  end if;

  v_provider_model_id := nullif(trim(p_sku->>'provider_model_id'), '');
  if v_provider_model_id is null then
    raise exception 'provider_model_id is required';
  end if;
  if not exists (
    select 1
    from public.v2_model_provider_routes route
    where route.provider_model_id = v_provider_model_id
      and route.model_slug = p_model_slug
  ) then
    raise exception 'provider route does not belong to the requested model';
  end if;
  if jsonb_typeof(coalesce(p_sku->'meters', '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_sku->'meters', '[]'::jsonb)) = 0 then
    raise exception 'at least one pricing meter is required';
  end if;

  -- Serialize versions of a price family, including concurrent new prices.
  perform pg_advisory_xact_lock(hashtextextended(v_provider_model_id||':'||lower(trim(p_sku->>'sku_code')),0));
  v_starts := coalesce(nullif(p_sku->>'effective_from','')::timestamptz,now());
  if v_before is not null then
    if v_existing.provider_model_id <> v_provider_model_id or v_existing.sku_code <> lower(trim(p_sku->>'sku_code')) then
      raise exception 'a price revision must keep its provider route and price code';
    end if;
    if v_existing.effective_to is not null then raise exception 'end-dated prices cannot be revised; add a new price group'; end if;
    if v_starts <= v_existing.effective_from then raise exception 'revision must start after the previous version'; end if;
    update public.v2_pricing_skus set effective_to=v_starts,updated_at=now() where sku_id=v_sku_id;
  elsif exists(select 1 from public.v2_pricing_skus where provider_model_id=v_provider_model_id and sku_code=lower(trim(p_sku->>'sku_code'))) then
    raise exception 'price group already exists; reload and create a revision';
  end if;
  select coalesce(max(version),0)+1 into v_version from public.v2_pricing_skus
    where provider_model_id=v_provider_model_id and sku_code=lower(trim(p_sku->>'sku_code'));
  v_sku_id := gen_random_uuid();
  insert into public.v2_pricing_skus (
    sku_id,
    provider_model_id,
    sku_code,
    version,
    operation,
    status,
    region,
    service_tier_slug,
    display_name,
    description,
    currency,
    effective_from,
    effective_to,
    metadata,
    updated_at
  ) values (
    v_sku_id,
    v_provider_model_id,
    lower(trim(p_sku->>'sku_code')),
    v_version,
    coalesce(nullif(trim(p_sku->>'operation'), ''), 'inference'),
    coalesce(nullif(trim(p_sku->>'status'), ''), 'active'),
    nullif(trim(p_sku->>'region'), ''),
    coalesce(nullif(trim(p_sku->>'service_tier_slug'), ''), 'standard'),
    trim(p_sku->>'display_name'),
    nullif(trim(p_sku->>'description'), ''),
    upper(coalesce(nullif(trim(p_sku->>'currency'), ''), 'USD')),
    v_starts,
    nullif(p_sku->>'effective_to', '')::timestamptz,
    coalesce(p_sku->'metadata', '{}'::jsonb) || jsonb_build_object(
      'source', 'admin',
      'authored_by', p_actor_user_id,
      'authored_at', now()
    ),
    now()
  )
  ;

  for v_meter in select value from jsonb_array_elements(p_sku->'meters')
  loop
    insert into public.v2_pricing_sku_meters (
      sku_id,
      meter_key,
      modality,
      direction,
      unit,
      unit_quantity,
      price_nanos,
      display_label,
      display_unit,
      billable,
      meter_order,
      metadata
    ) values (
      v_sku_id,
      lower(trim(v_meter->>'meter_key')),
      lower(trim(v_meter->>'modality')),
      nullif(lower(trim(v_meter->>'direction')), ''),
      lower(trim(v_meter->>'unit')),
      (v_meter->>'unit_quantity')::numeric,
      (v_meter->>'price_nanos')::numeric,
      trim(v_meter->>'display_label'),
      trim(v_meter->>'display_unit'),
      coalesce((v_meter->>'billable')::boolean, true),
      coalesce((v_meter->>'meter_order')::integer, 100),
      coalesce(v_meter->'metadata', '{}'::jsonb) || jsonb_build_object('source', 'admin')
    );
  end loop;

  select jsonb_build_object(
    'sku', to_jsonb(sku),
    'meters', coalesce((
      select jsonb_agg(to_jsonb(meter) order by meter.meter_order, meter.meter_key)
      from public.v2_pricing_sku_meters meter
      where meter.sku_id = v_sku_id
    ), '[]'::jsonb)
  ) into v_after
  from public.v2_pricing_skus sku
  where sku.sku_id = v_sku_id;

  v_resource_id := v_sku_id::text;
  insert into public.v2_catalogue_admin_changes (
    actor_user_id, resource_type, resource_id, action, before_state, after_state
  ) values (
    p_actor_user_id,
    'pricing_sku',
    v_resource_id,
    case when v_before is null then 'create' else 'update' end,
    v_before,
    v_after
  );

  if nullif(p_sku->'metadata'->>'source_key', '') is not null then
    insert into public.v2_catalogue_source_overrides (
      source_type, source_key, disposition, actor_user_id, resource_id, updated_at
    ) values (
      'pricing_rule', p_sku->'metadata'->>'source_key', 'database_managed', p_actor_user_id, v_resource_id, now()
    )
    on conflict (source_type, source_key) do update set
      disposition = excluded.disposition,
      actor_user_id = excluded.actor_user_id,
      resource_id = excluded.resource_id,
      updated_at = now();
  end if;

  return v_after;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."mutate_v2_admin_pricing_sku"(uuid, text, text, jsonb) TO "service_role";

COMMENT ON FUNCTION "public"."mutate_v2_admin_pricing_sku"(uuid, text, text, jsonb) IS 'Atomically creates, updates, or deletes one pricing SKU and its meters. Service role only, with a database-backed admin actor check.';

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_pricing_sku"(uuid, text, text, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/mutate_v2_admin_provider_offer.sql
CREATE OR REPLACE FUNCTION public.mutate_v2_admin_provider_offer (
  p_actor_user_id uuid,
  p_action        text,
  p_provider_slug text,
  p_payload       jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_before jsonb; v_after jsonb; v_family text; v_parent text; v_scope text; v_mode text; v_field text;
  v_exec text[]; v_data text[]; v_metadata jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  if p_action not in ('create','update') then raise exception 'unsupported provider action'; end if;
  if nullif(trim(p_payload->>'api_provider_name'),'') is null then raise exception 'provider name required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('provider-offer:'||p_provider_slug,0));
  select to_jsonb(p) into v_before from public.v2_providers p where provider_slug=p_provider_slug for update;
  if p_action='create' and v_before is not null then raise exception 'provider already exists'; end if;
  if p_action='update' and v_before is null then raise exception 'provider not found'; end if;
  v_scope=coalesce(p_payload->>'offer_scope',v_before->>'offer_scope','global');
  v_mode=coalesce(p_payload->>'residency_mode',v_before->>'residency_mode','unknown');
  if v_scope not in ('global','regional','specialized') then raise exception 'invalid offer scope'; end if;
  if v_mode not in ('unknown','provider_managed','customer_selectable','account_selected') then raise exception 'invalid residency mode'; end if;
  v_parent=nullif(trim(p_payload->>'parent_provider_slug'),'');
  v_family=coalesce(v_before->>'provider_family_slug',p_provider_slug);
  if v_parent is not null then
    if v_parent=p_provider_slug then raise exception 'provider cannot be its own parent'; end if;
    select coalesce(provider_family_slug,provider_slug) into v_family from public.v2_providers where provider_slug=v_parent;
    if not found then raise exception 'parent provider not found'; end if;
  elsif p_action='create' and v_scope='regional' then raise exception 'regional offers require a parent provider';
  end if;
  foreach v_field in array array['default_execution_regions','default_data_regions'] loop
    if p_payload ? v_field then
      if jsonb_typeof(p_payload->v_field) not in ('array','null') then raise exception 'invalid region list'; end if;
      if jsonb_typeof(p_payload->v_field)='array' and exists(select 1 from jsonb_array_elements(p_payload->v_field) x where jsonb_typeof(x)<>'string' or trim(x#>>'{}') !~ '^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$') then raise exception 'invalid region'; end if;
    end if;
  end loop;
  v_exec=case when jsonb_typeof(coalesce(p_payload->'default_execution_regions',v_before->'default_execution_regions'))='array' then array(select distinct lower(trim(value)) from jsonb_array_elements_text(coalesce(p_payload->'default_execution_regions',v_before->'default_execution_regions'))) else null end;
  v_data=case when jsonb_typeof(coalesce(p_payload->'default_data_regions',v_before->'default_data_regions'))='array' then array(select distinct lower(trim(value)) from jsonb_array_elements_text(coalesce(p_payload->'default_data_regions',v_before->'default_data_regions'))) else null end;
  if v_scope='regional' and (coalesce(cardinality(v_exec),0)=0 or 'global'=any(v_exec)) then raise exception 'regional offers require specific execution regions'; end if;
  if v_scope='regional' and nullif(trim(coalesce(p_payload->>'offer_label',v_before->>'offer_label')),'') is null then raise exception 'regional offer label required'; end if;
  v_metadata=coalesce(v_before->'metadata','{}'::jsonb);
  foreach v_field in array array['description','link','prompt_training_policy','prompt_training_notes','prompt_training_source_url','data_policy_tier','data_policy_confidence','data_policy_contract_mode','data_policy_contract_notes'] loop
    if p_payload ? v_field then v_metadata=v_metadata||jsonb_build_object(v_field,p_payload->v_field); end if;
  end loop;
  if p_payload ? 'parent_provider_slug' then v_metadata=v_metadata||jsonb_build_object('parent_provider_slug',v_parent); end if;
  perform set_config('phaseo.catalogue_actor',p_actor_user_id::text,true);
  insert into public.v2_providers(provider_slug,name,provider_family_slug,offer_scope,offer_label,residency_mode,default_execution_regions,default_data_regions,country_code,subdivision_code,base_url,byok_available,credential_mode,status,routing_enabled,routable,metadata,updated_at)
  values(p_provider_slug,trim(p_payload->>'api_provider_name'),v_family,v_scope,
    case when p_payload ? 'offer_label' then nullif(trim(p_payload->>'offer_label'),'') else v_before->>'offer_label' end,
    v_mode,v_exec,v_data,coalesce(nullif(p_payload->>'country_code',''),v_before->>'country_code','xx'),case when p_payload ? 'subdivision_code' then nullif(trim(p_payload->>'subdivision_code'),'') else v_before->>'subdivision_code' end,
    case when p_payload ? 'base_url' then nullif(trim(p_payload->>'base_url'),'') else v_before->>'base_url' end,
    coalesce((p_payload->>'byok_available')::boolean,(v_before->>'byok_available')::boolean,false), coalesce(p_payload->>'credential_mode',v_before->>'credential_mode','managed_and_byok'), lower(coalesce(p_payload->>'status',v_before->>'status','active')),false,false,v_metadata,now())
  on conflict(provider_slug) do update set name=excluded.name,provider_family_slug=excluded.provider_family_slug,offer_scope=excluded.offer_scope,offer_label=excluded.offer_label,residency_mode=excluded.residency_mode,default_execution_regions=excluded.default_execution_regions,default_data_regions=excluded.default_data_regions,country_code=excluded.country_code,subdivision_code=excluded.subdivision_code,base_url=excluded.base_url,byok_available=excluded.byok_available,credential_mode=excluded.credential_mode,status=excluded.status,metadata=excluded.metadata,updated_at=now();
  select to_jsonb(p) into v_after from public.v2_providers p where provider_slug=p_provider_slug;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state) values(p_actor_user_id,'providers',p_provider_slug,p_action,v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at) values('providers',p_provider_slug,'database_managed',p_actor_user_id,p_provider_slug,now()) on conflict(source_type,source_key) do update set disposition=excluded.disposition,actor_user_id=excluded.actor_user_id,updated_at=now();
  return v_after;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."mutate_v2_admin_provider_offer"(uuid, text, text, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_provider_offer"(uuid, text, text, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/mutate_v2_admin_provider_residency.sql
CREATE OR REPLACE FUNCTION public.mutate_v2_admin_provider_residency (
  p_actor_user_id uuid,
  p_provider_slug text,
  p_policy        jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare v_before jsonb; v_after jsonb; v_field text;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  if p_policy->>'residency_mode' is null or p_policy->>'residency_mode' not in ('unknown','provider_managed','customer_selectable','account_selected') then raise exception 'invalid residency mode'; end if;
  foreach v_field in array array['default_execution_regions','default_data_regions'] loop
    if not (p_policy ? v_field) or jsonb_typeof(p_policy->v_field) not in ('array','null') then raise exception 'region list required'; end if;
    if jsonb_typeof(p_policy->v_field)='array' then
      if jsonb_array_length(p_policy->v_field)>100 or exists(select 1 from jsonb_array_elements(p_policy->v_field) x where jsonb_typeof(x)<>'string' or trim(x#>>'{}') !~ '^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$') then raise exception 'invalid region'; end if;
    end if;
  end loop;
  select to_jsonb(p) into v_before from public.v2_providers p where provider_slug=p_provider_slug for update;
  if v_before is null then raise exception 'provider not found'; end if;
  perform set_config('phaseo.catalogue_actor',p_actor_user_id::text,true);
  update public.v2_providers set
    residency_mode=p_policy->>'residency_mode',
    default_execution_regions=case when jsonb_typeof(p_policy->'default_execution_regions')='array' then array(select distinct lower(trim(value)) from jsonb_array_elements_text(p_policy->'default_execution_regions')) else null end,
    default_data_regions=case when jsonb_typeof(p_policy->'default_data_regions')='array' then array(select distinct lower(trim(value)) from jsonb_array_elements_text(p_policy->'default_data_regions')) else null end,
    updated_at=now() where provider_slug=p_provider_slug;
  select to_jsonb(p) into v_after from public.v2_providers p where provider_slug=p_provider_slug;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state) values(p_actor_user_id,'providers',p_provider_slug,'update',v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at) values('providers',p_provider_slug,'database_managed',p_actor_user_id,p_provider_slug,now()) on conflict(source_type,source_key) do update set disposition=excluded.disposition,actor_user_id=excluded.actor_user_id,updated_at=now();
  return v_after;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."mutate_v2_admin_provider_residency"(uuid, text, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_provider_residency"(uuid, text, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/mutate_v2_admin_provider_route.sql
CREATE OR REPLACE FUNCTION public.mutate_v2_admin_provider_route (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_route         jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_provider_slug text := nullif(trim(p_route->>'provider_slug'),'');
  v_provider_model_slug text := nullif(trim(p_route->>'provider_model_slug'),'');
  v_provider_model_id text := nullif(trim(p_route->>'provider_model_id'),'');
  v_before jsonb;
  v_after jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  if not exists(select 1 from public.v2_models where model_slug=p_model_slug) then raise exception 'model not found'; end if;
  if v_provider_slug is null or not exists(select 1 from public.v2_providers where provider_slug=v_provider_slug) then raise exception 'provider not found'; end if;
  if v_provider_model_slug is null then raise exception 'provider_model_slug is required'; end if;
  if v_provider_model_id is null then
    v_provider_model_id := case when coalesce((p_route->>'is_stealth')::boolean,false) then 'stealth:'||gen_random_uuid()::text else v_provider_slug||':'||p_model_slug||':'||v_provider_model_slug end;
  end if;
  if coalesce((p_route->>'is_stealth')::boolean,false) and v_provider_model_id not like 'stealth:%' then
    raise exception 'A public route cannot be converted to stealth. Create a new stealth route to preserve its pricing and usage history.';
  end if;
  select to_jsonb(t) into v_before from public.v2_model_provider_routes t where provider_model_id=v_provider_model_id for update;
  if v_before is not null and v_before->>'model_slug'<>p_model_slug then raise exception 'provider route belongs to another model'; end if;
  perform set_config('phaseo.catalogue_actor',p_actor_user_id::text,true);
  insert into public.v2_model_provider_routes(
    provider_model_id,model_slug,provider_slug,provider_model_slug,status,
    provider_availability_status,phaseo_status,access_scope,routing_enabled,is_stealth,
    input_modalities,output_modalities,regions,context_length,max_output_tokens,
    effective_from,effective_to,metadata,updated_at
  ) values (
    v_provider_model_id,p_model_slug,v_provider_slug,v_provider_model_slug,
    coalesce(nullif(p_route->>'status',''),'active'),
    coalesce(nullif(p_route->>'provider_availability_status',''),'unknown'),
    coalesce(nullif(p_route->>'phaseo_status',''),'disabled'),
    coalesce(nullif(p_route->>'access_scope',''),'public'),
    coalesce((p_route->>'routing_enabled')::boolean,false),
    coalesce((p_route->>'is_stealth')::boolean,false),
    case when jsonb_typeof(p_route->'input_modalities')='array' then array(select jsonb_array_elements_text(p_route->'input_modalities')) else '{}'::text[] end,
    case when jsonb_typeof(p_route->'output_modalities')='array' then array(select jsonb_array_elements_text(p_route->'output_modalities')) else '{}'::text[] end,
    case when jsonb_typeof(p_route->'regions')='array' then array(select jsonb_array_elements_text(p_route->'regions')) else '{}'::text[] end,
    nullif(p_route->>'context_length','')::integer,nullif(p_route->>'max_output_tokens','')::integer,
    nullif(p_route->>'effective_from','')::timestamptz,nullif(p_route->>'effective_to','')::timestamptz,
    coalesce(p_route->'metadata','{}'::jsonb)||jsonb_build_object('source','admin'),now()
  ) on conflict(provider_model_id) do update set
    provider_slug=excluded.provider_slug,provider_model_slug=excluded.provider_model_slug,status=excluded.status,
    provider_availability_status=case when p_route ? 'provider_availability_status' then excluded.provider_availability_status else public.v2_model_provider_routes.provider_availability_status end,
    phaseo_status=case when p_route ? 'phaseo_status' then excluded.phaseo_status else public.v2_model_provider_routes.phaseo_status end,
    access_scope=case when p_route ? 'access_scope' then excluded.access_scope else public.v2_model_provider_routes.access_scope end,
    is_stealth=case when p_route ? 'is_stealth' then excluded.is_stealth else public.v2_model_provider_routes.is_stealth end,
    routing_enabled=excluded.routing_enabled,
    input_modalities=excluded.input_modalities,output_modalities=excluded.output_modalities,
    regions=excluded.regions,context_length=excluded.context_length,max_output_tokens=excluded.max_output_tokens,
    effective_from=excluded.effective_from,effective_to=excluded.effective_to,
    metadata=public.v2_model_provider_routes.metadata||excluded.metadata,updated_at=now();
  if exists(
    select 1 from public.v2_model_provider_routes t
    where t.provider_model_id=v_provider_model_id and t.routing_enabled
      and (t.phaseo_status <> 'enabled' or t.access_scope <> 'public'
        or t.provider_availability_status not in ('available','preview','limited_access'))
  ) then raise exception 'routing requires an enabled public route with available provider access'; end if;
  select to_jsonb(t) into v_after from public.v2_model_provider_routes t where provider_model_id=v_provider_model_id;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state)
  values(p_actor_user_id,'provider_route',v_provider_model_id,case when v_before is null then 'create' else 'update' end,v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at)
  values('provider_route',v_provider_model_id,'database_managed',p_actor_user_id,v_provider_model_id,now())
  on conflict(source_type,source_key) do update set disposition='database_managed',actor_user_id=excluded.actor_user_id,resource_id=excluded.resource_id,updated_at=now();
  return v_after;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."mutate_v2_admin_provider_route"(uuid, text, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_provider_route"(uuid, text, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/mutate_v2_admin_registry.sql
create or replace function public.mutate_v2_admin_registry(
  p_actor_user_id uuid, p_resource text, p_values jsonb, p_before jsonb
) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare
  v_table text; v_keys text[]; v_allowed text[]; v_identity jsonb; v_existing jsonb;
  v_columns text; v_select text; v_updates text; v_result jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  case p_resource
    when 'families' then v_table:='v2_model_families'; v_keys:=array['family_slug']; v_allowed:=array['family_slug','lab_slug','name','metadata'];
    when 'service-tiers' then v_table:='v2_service_tiers'; v_keys:=array['service_tier_slug']; v_allowed:=array['service_tier_slug','display_name','description','status','metadata'];
    when 'meters' then v_table:='v2_meter_definitions'; v_keys:=array['meter_key']; v_allowed:=array['meter_key','display_name','modality','direction','unit','default_unit_quantity','description','status','metadata'];
    when 'regions' then v_table:='v2_provider_regions'; v_keys:=array['provider_region_id']; v_allowed:=array['provider_region_id','provider_slug','region_code','display_name','execution_supported','data_residency_supported','status','routing_enabled','metadata'];
    when 'variants' then v_table:='v2_route_variants'; v_keys:=array['variant_id']; v_allowed:=array['variant_id','provider_model_id','variant_key','provider_region_id','execution_region','data_region','service_tier_slug','status','routing_enabled','endpoint_label','metadata'];
    when 'plans' then v_table:='v2_subscription_plans'; v_keys:=array['plan_uuid']; v_allowed:=array['plan_uuid','plan_id','name','lab_slug','description','audience','status','link','other_info','source_url','verified_at','effective_from','effective_to'];
    when 'plan-features' then v_table:='v2_subscription_plan_features'; v_keys:=array['plan_uuid','feature_name']; v_allowed:=array['plan_uuid','feature_name','feature_value','feature_description','other_info','feature_key','availability','value_number','value_text','conditions','source_url','verified_at','effective_from','effective_to'];
    when 'plan-offers' then v_table:='v2_subscription_plan_offers'; v_keys:=array['offer_uuid']; v_allowed:=array['offer_uuid','plan_uuid','label','billing_interval','billing_interval_count','currency','region_code','minimum_seats','tax_treatment','eligibility','purchase_url','source_url','verified_at','effective_from','effective_to','metadata'];
    when 'offer-prices' then v_table:='v2_subscription_offer_prices'; v_keys:=array['price_uuid']; v_allowed:=array['price_uuid','offer_uuid','component_key','pricing_type','amount','charge_basis','seat_type','unit','unit_quantity','phase','starts_at_cycle','duration_cycles','display_text','source_url','verified_at','effective_from','effective_to'];
    when 'feature-definitions' then v_table:='v2_subscription_feature_definitions'; v_keys:=array['feature_key']; v_allowed:=array['feature_key','label','category','value_type'];
    when 'plan-allowances' then v_table:='v2_subscription_plan_allowances'; v_keys:=array['allowance_uuid']; v_allowed:=array['allowance_uuid','plan_uuid','offer_uuid','feature_key','allowance_key','allowance_kind','quantity','quantity_max','quantity_kind','unit','currency','window_kind','window_unit','window_count','allocation_basis','pool_scope','pool_key','grant_condition','comparison_plan_uuid','comparison_feature_key','overage_policy','overage_price','overage_currency','overage_unit_quantity','overage_source_url','conditions','display_text','source_url','verified_at','effective_from','effective_to','metadata'];
    when 'plan-model-access' then v_table:='v2_subscription_plan_models'; v_keys:=array['plan_uuid','model_slug']; v_allowed:=array['plan_uuid','model_slug','model_info','rate_limit','other_info','access_mode','access_channel','conditions','mapping_status','source_url','verified_at','effective_from','effective_to'];
    else raise exception 'unknown registry';
  end case;
  if p_values is null or jsonb_typeof(p_values)<>'object' then raise exception 'record must be an object'; end if;
  if p_values->'effective_from'='null'::jsonb then p_values:=p_values-'effective_from'; end if;
  if exists(select 1 from jsonb_object_keys(p_values) key where not key=any(v_allowed)) then raise exception 'unknown record field'; end if;
  if exists(select 1 from unnest(v_keys) key where nullif(p_values->>key,'') is null) then raise exception 'record identity required'; end if;
  select jsonb_object_agg(key,p_values->key) into v_identity from unnest(v_keys) key;
  if p_before is not null and not p_before @> v_identity then raise exception 'record identity cannot change'; end if;
  execute format('select to_jsonb(t) from public.%I t where to_jsonb(t) @> $1 for update',v_table) into v_existing using v_identity;
  if v_existing is distinct from p_before then raise exception 'Record changed. Reload before saving.'; end if;
  if p_resource in ('plan-offers','plan-allowances','plan-features','plan-model-access') and not exists
    (select 1 from v2_subscription_plans p where p.plan_uuid=(p_values->>'plan_uuid')::uuid and p.status<>'merged') then
    raise exception 'Use the canonical subscription plan';
  end if;
  if v_existing is not null and p_resource in ('plan-offers','plan-allowances') and p_values->>'plan_uuid' is distinct from v_existing->>'plan_uuid' then
    raise exception 'Subscription record ownership cannot change';
  end if;
  if v_existing is not null and p_resource='offer-prices' and p_values->>'offer_uuid' is distinct from v_existing->>'offer_uuid' then
    raise exception 'Price offer ownership cannot change';
  end if;
  if p_resource='plans' and v_existing->>'status'='merged' then raise exception 'Edit the canonical plan instead'; end if;
  if p_resource='regions' and v_existing is not null and (p_values->>'provider_slug' is distinct from v_existing->>'provider_slug' or p_values->>'region_code' is distinct from v_existing->>'region_code') then raise exception 'provider region identity cannot change'; end if;
  if p_resource='variants' then
    if v_existing is not null and (p_values->>'provider_model_id' is distinct from v_existing->>'provider_model_id' or p_values->>'variant_key' is distinct from v_existing->>'variant_key') then raise exception 'route variant identity cannot change'; end if;
    if p_values->>'provider_region_id' is not null and not exists(select 1 from public.v2_provider_regions r join public.v2_model_provider_routes m on m.provider_slug=r.provider_slug where r.provider_region_id=(p_values->>'provider_region_id')::uuid and m.provider_model_id=p_values->>'provider_model_id') then raise exception 'region belongs to another provider'; end if;
  end if;
  if p_resource in ('regions','variants') and p_values->>'status' in ('disabled','retired','deprecated') then p_values:=p_values||jsonb_build_object('routing_enabled',false); end if;
  if p_resource in ('families','service-tiers','meters','regions','variants','plans') then p_values:=p_values||jsonb_build_object('updated_at',now()); end if;
  perform set_config('phaseo.catalogue_actor',p_actor_user_id::text,true);
  select string_agg(format('%I',key),','), string_agg(format('(jsonb_populate_record(null::public.%I,$1)).%I',v_table,key),','), string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,v_table,key),',')
    into v_columns,v_select,v_updates from jsonb_object_keys(p_values) key;
  if v_existing is null then
    execute format('insert into public.%I (%s) select %s returning to_jsonb(%I.*)',v_table,v_columns,v_select,v_table) into v_result using p_values;
  else
    execute format('update public.%I t set %s where to_jsonb(t) @> $2 returning to_jsonb(t)',v_table,v_updates) into v_result using p_values,v_identity;
  end if;
  return v_result;
end $$;

revoke all on function public.mutate_v2_admin_registry(uuid,text,jsonb,jsonb) from public,anon,authenticated;

grant execute on function public.mutate_v2_admin_registry(uuid,text,jsonb,jsonb) to service_role;

-- source: supabase/schemas/public/functions/mutate_v2_admin_subscription_plan.sql
create function public.mutate_v2_admin_subscription_plan(p_actor_user_id uuid,p_action text,p_plan_uuid uuid,p_payload jsonb)
returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_before jsonb; v_plan jsonb; v_offer jsonb; v_component jsonb; v_offer_uuid uuid;
begin
  if p_action not in ('create','update') then raise exception 'Unsupported subscription action'; end if;
  select to_jsonb(p) into v_before from v2_subscription_plans p where p.plan_uuid=p_plan_uuid for update;
  if p_action='create' and v_before is not null then raise exception 'Plan already exists'; end if;
  if p_action='update' and v_before is null then raise exception 'Plan does not exist'; end if;
  v_plan:=public.mutate_v2_admin_registry(p_actor_user_id,'plans',jsonb_build_object('plan_uuid',p_plan_uuid,
    'plan_id',p_payload->>'plan_id','name',p_payload->>'name','lab_slug',p_payload->>'organisation_id',
    'description',p_payload->>'description','link',p_payload->>'link',
    'audience',coalesce(p_payload->>'audience','unknown'),'status',coalesce(p_payload->>'status','active'),
    'other_info',coalesce(p_payload->'other_info','{}'::jsonb)),v_before);
  if p_payload ? 'offer' and p_payload->'offer'<>'null'::jsonb then
    v_offer_uuid:=coalesce((p_payload->'offer'->>'offer_uuid')::uuid,gen_random_uuid());
    select to_jsonb(o) into v_before from v2_subscription_plan_offers o where o.offer_uuid=v_offer_uuid for update;
    if v_before is not null and (v_before->>'plan_uuid')::uuid<>p_plan_uuid then raise exception 'Offer belongs to another plan'; end if;
    v_offer:=public.mutate_v2_admin_registry(p_actor_user_id,'plan-offers',
      ((p_payload->'offer')-'components')||jsonb_build_object('offer_uuid',v_offer_uuid,'plan_uuid',p_plan_uuid),v_before);
    for v_component in select value from jsonb_array_elements(coalesce(p_payload->'offer'->'components','[]')) loop
      v_component:=v_component||jsonb_build_object('offer_uuid',v_offer_uuid,'price_uuid',coalesce(v_component->>'price_uuid',gen_random_uuid()::text));
      select to_jsonb(c) into v_before from v2_subscription_offer_prices c where c.price_uuid=(v_component->>'price_uuid')::uuid for update;
      if v_before is not null and (v_before->>'offer_uuid')::uuid<>v_offer_uuid then raise exception 'Price belongs to another offer'; end if;
      perform public.mutate_v2_admin_registry(p_actor_user_id,'offer-prices',v_component,v_before);
    end loop;
  end if;
  return v_plan;
end $$;

revoke all on function public.mutate_v2_admin_subscription_plan(uuid,text,uuid,jsonb) from public,anon,authenticated;

grant execute on function public.mutate_v2_admin_subscription_plan(uuid,text,uuid,jsonb) to service_role;

-- source: supabase/schemas/public/functions/normalize_gateway_request_embedding_tokens.sql
CREATE OR REPLACE FUNCTION public.normalize_gateway_request_embedding_tokens()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
begin
  new.usage_embedding_tokens :=
    case
      when coalesce(new.endpoint, '') = 'embeddings' then
        public.gateway_usage_nonnegative_bigint(
          coalesce(
            public.gateway_usage_numeric_field(
              new.usage,
              'embedding_tokens',
              'input_tokens',
              'prompt_tokens',
              'total_tokens'
            ),
            new.usage_embedding_tokens,
            0
          )
        )
      else greatest(coalesce(new.usage_embedding_tokens, 0), 0)
    end;
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."normalize_gateway_request_embedding_tokens"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."normalize_gateway_request_embedding_tokens"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/normalize_gateway_request_usage.sql
CREATE OR REPLACE FUNCTION public.normalize_gateway_request_usage()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_usage jsonb := coalesce(new.usage, '{}'::jsonb);
  v_input_tokens bigint;
  v_output_tokens bigint;
  v_total_tokens bigint;
  v_reasoning_tokens bigint;
  v_input_image_tokens bigint;
  v_output_image_tokens bigint;
  v_input_audio_tokens bigint;
  v_output_audio_tokens bigint;
  v_input_video_tokens bigint;
  v_output_video_tokens bigint;
begin
  v_total_tokens := public.gateway_usage_total_tokens(v_usage);

  v_input_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_tokens',
      'prompt_tokens',
      'inputTokens',
      'promptTokens',
      'promptTokenCount',
      'total_input_tokens',
      'totalInputTokens'
    ), 0)
  );
  v_output_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_tokens',
      'completion_tokens',
      'outputTokens',
      'completionTokens',
      'candidatesTokenCount',
      'total_output_tokens',
      'totalOutputTokens'
    ), 0)
  );
  v_reasoning_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'reasoning_tokens',
      'reasoning_output_tokens',
      'output_reasoning_tokens',
      'completion_tokens_details.reasoning_tokens',
      'output_tokens_details.reasoning_tokens'
    ), 0)
  );
  v_input_image_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_image_tokens',
      'image_input_tokens',
      'prompt_image_tokens',
      'input_tokens_details.image_tokens',
      'prompt_tokens_details.image_tokens'
    ), 0)
  );
  v_output_image_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_image_tokens',
      'image_output_tokens',
      'generated_image_tokens',
      'completion_tokens_details.image_tokens',
      'output_tokens_details.image_tokens'
    ), 0)
  );
  v_input_audio_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_audio_tokens',
      'audio_input_tokens',
      'prompt_audio_tokens',
      'input_tokens_details.audio_tokens',
      'prompt_tokens_details.audio_tokens'
    ), 0)
  );
  v_output_audio_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_audio_tokens',
      'audio_output_tokens',
      'completion_tokens_details.audio_tokens',
      'output_tokens_details.audio_tokens'
    ), 0)
  );
  v_input_video_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_video_tokens',
      'video_input_tokens',
      'input_tokens_details.video_tokens',
      'prompt_tokens_details.video_tokens'
    ), 0)
  );
  v_output_video_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_video_tokens',
      'video_output_tokens',
      'completion_tokens_details.video_tokens',
      'output_tokens_details.video_tokens'
    ), 0)
  );

  if v_total_tokens < v_input_tokens + v_output_tokens + v_reasoning_tokens then
    v_total_tokens := v_input_tokens + v_output_tokens + v_reasoning_tokens;
  end if;

  new.usage_total_tokens := coalesce(v_total_tokens, 0);
  new.usage_input_tokens := v_input_tokens;
  new.usage_output_tokens := v_output_tokens;
  new.usage_reasoning_tokens := v_reasoning_tokens;
  new.usage_input_image_tokens := v_input_image_tokens;
  new.usage_output_image_tokens := v_output_image_tokens;
  new.usage_input_audio_tokens := v_input_audio_tokens;
  new.usage_output_audio_tokens := v_output_audio_tokens;
  new.usage_input_video_tokens := v_input_video_tokens;
  new.usage_output_video_tokens := v_output_video_tokens;
  new.usage_input_text_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(
      public.gateway_usage_numeric_field(v_usage, 'input_text_tokens', 'text_input_tokens'),
      greatest(v_input_tokens - v_input_image_tokens - v_input_audio_tokens - v_input_video_tokens, 0)
    )
  );
  new.usage_output_text_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(
      public.gateway_usage_numeric_field(v_usage, 'output_text_tokens', 'text_output_tokens'),
      greatest(v_output_tokens - v_output_image_tokens - v_output_audio_tokens - v_output_video_tokens - v_reasoning_tokens, 0)
    )
  );

  new.usage_image_inputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_image_count',
      'image_input_count',
      'image_inputs',
      'input_images'
    ), 0)
  );
  new.usage_image_outputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_image_count',
      'image_output_count',
      'image_outputs',
      'output_images',
      'generated_images',
      'image_count'
    ), 0)
  );
  new.usage_audio_inputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_audio_count',
      'audio_input_count',
      'audio_inputs',
      'input_audio'
    ), 0)
  );
  new.usage_audio_outputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_audio_count',
      'audio_output_count',
      'audio_outputs',
      'output_audio'
    ), 0)
  );
  new.usage_video_inputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_video_count',
      'video_input_count',
      'video_inputs',
      'input_videos'
    ), 0)
  );
  new.usage_video_outputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_video_count',
      'video_output_count',
      'video_outputs',
      'output_videos',
      'video_count'
    ), 0)
  );

  new.usage_cached_read_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'cached_read_tokens',
      'cache_read_input_tokens',
      'input_tokens_details.cached_tokens',
      'prompt_tokens_details.cached_tokens'
    ), 0)
  );
  new.usage_cached_write_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'cached_write_tokens',
      'cache_creation_input_tokens',
      'output_tokens_details.cached_tokens'
    ), 0)
  );
  new.usage_cached_read_text_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_read_text_tokens'), 0)
  );
  new.usage_cached_write_text_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(
      public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens'),
      coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens_5m', 'cache_creation.ephemeral_5m_input_tokens'), 0) +
        coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens_1h', 'cache_creation.ephemeral_1h_input_tokens'), 0)
    )
  );
  new.usage_cached_write_text_tokens_5m := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens_5m', 'cache_creation.ephemeral_5m_input_tokens'), 0)
  );
  new.usage_cached_write_text_tokens_1h := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens_1h', 'cache_creation.ephemeral_1h_input_tokens'), 0)
  );
  new.usage_cached_read_image_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_read_image_tokens'), 0)
  );
  new.usage_cached_write_image_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_image_tokens'), 0)
  );
  new.usage_cached_read_audio_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_read_audio_tokens'), 0)
  );
  new.usage_cached_write_audio_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_audio_tokens'), 0)
  );
  new.usage_cached_read_video_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_read_video_tokens'), 0)
  );
  new.usage_cached_write_video_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_video_tokens'), 0)
  );
  new.usage_input_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'input_quad_tokens', 'quad_input_tokens'), new.usage_input_quad_tokens)
  );
  new.usage_output_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'output_quad_tokens', 'quad_output_tokens'), new.usage_output_quad_tokens)
  );
  new.usage_total_quad_tokens := public.gateway_usage_nonnegative_bigint(
    greatest(
      coalesce(public.gateway_usage_numeric_field(v_usage, 'total_quad_tokens', 'quad_total_tokens'), new.usage_total_quad_tokens),
      new.usage_input_quad_tokens + new.usage_output_quad_tokens
    )
  );
  new.usage_text_quad_tokens := public.gateway_usage_nonnegative_bigint(
    greatest(
      coalesce(public.gateway_usage_numeric_field(v_usage, 'text_quad_tokens'), new.usage_text_quad_tokens),
      new.usage_total_quad_tokens
    )
  );
  new.usage_rerank_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'rerank_quad_tokens'), new.usage_rerank_quad_tokens)
  );
  new.usage_embedding_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'embedding_quad_tokens'), new.usage_embedding_quad_tokens)
  );
  new.usage_moderation_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'moderation_quad_tokens'), new.usage_moderation_quad_tokens)
  );
  new.usage_ocr_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'ocr_quad_tokens'), new.usage_ocr_quad_tokens)
  );
  new.usage_image_megapixels := greatest(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'image_megapixels'), new.usage_image_megapixels),
    0
  );
  new.usage_audio_seconds := greatest(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'audio_seconds'), new.usage_audio_seconds),
    0
  );
  new.usage_video_pixel_seconds := greatest(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'video_pixel_seconds'), new.usage_video_pixel_seconds),
    0
  );
  new.usage_input_characters := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'input_characters', 'input_chars'), new.usage_input_characters)
  );
  new.usage_output_characters := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'output_characters', 'output_chars'), new.usage_output_characters)
  );
  new.usage_total_characters := public.gateway_usage_nonnegative_bigint(
    greatest(
      coalesce(public.gateway_usage_numeric_field(v_usage, 'total_characters', 'total_chars'), new.usage_total_characters),
      new.usage_input_characters + new.usage_output_characters
    )
  );
  new.usage_normalized_at := now();

  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."normalize_gateway_request_usage"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."normalize_gateway_request_usage"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/normalize_gateway_request_video_seconds.sql
CREATE OR REPLACE FUNCTION public.normalize_gateway_request_video_seconds()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
begin
  new.usage_video_seconds := greatest(
    coalesce(
      public.gateway_usage_numeric_field(
        new.usage,
        'video_seconds',
        'input_video_seconds',
        'output_video_seconds'
      ),
      new.usage_video_seconds,
      0
    ),
    0
  );
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."normalize_gateway_request_video_seconds"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."normalize_gateway_request_video_seconds"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/normalize_routing_pricing_operation.sql
create function public.normalize_routing_pricing_operation()
returns trigger language plpgsql security invoker
set search_path = pg_catalog, public
as $$
declare canonical text;
begin
  if lower(trim(new.operation)) in ('audio','audio.generate') then
    raise exception 'Generic audio pricing requires a reviewed model operation' using errcode='23514';
  end if;
  canonical := public.canonical_routing_capability_id(new.operation);
  if canonical is not null then new.operation := canonical; end if;
  return new;
end $$;

revoke all on function public.normalize_routing_pricing_operation() from public, anon, authenticated;

grant execute on function public.normalize_routing_pricing_operation() to service_role;

-- source: supabase/schemas/public/functions/normalize_v2_service_tier.sql
CREATE OR REPLACE FUNCTION public.normalize_v2_service_tier (
  p_value text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select case lower(nullif(trim(p_value), ''))
    when 'default' then 'standard'
    when 'fast' then 'priority'
    when 'priority' then 'priority'
    when 'standard' then 'standard'
    when 'ultrafast' then 'ultrafast'
    when 'flex' then 'flex'
    when 'batch' then 'batch'
    else null
  end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."normalize_v2_service_tier"(text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."normalize_v2_service_tier"(text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/opt_out_of_product_emails.sql
CREATE OR REPLACE FUNCTION public.opt_out_of_product_emails (
  p_token uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- One-click unsubscribe from a feedback email: opts the user out of all non-essential
-- email and cancels any of their feedback emails still waiting in the outbox.
-- Repeating it is harmless. Returns null for an unknown token, otherwise the user's
-- addresses (current sign-in and any feedback email was sent to) so the caller can also
-- unsubscribe them in the email provider.
declare
  v_user_id uuid;
  v_emails jsonb;
begin
  update public.feedback_requests
  set opted_out_at = coalesce(opted_out_at, now())
  where access_token = p_token
  returning user_id into v_user_id;

  if v_user_id is null then
    return null;
  end if;

  update public.users
  set product_emails_opted_out_at = coalesce(product_emails_opted_out_at, now())
  where user_id = v_user_id;

  update public.email_outbox
  set attempts = 5, last_error = 'unsubscribed'
  where user_id = v_user_id and kind = 'feedback_request' and sent_at is null;

  select coalesce(jsonb_agg(distinct e.email order by e.email), '[]'::jsonb) into v_emails
  from (
    select lower(trim(a.email)) as email from auth.users a where a.id = v_user_id
    union
    select lower(trim(o.to_email)) from public.email_outbox o
    where o.user_id = v_user_id and o.kind = 'feedback_request'
  ) e
  where nullif(e.email, '') is not null;

  return jsonb_build_object('emails', v_emails);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."opt_out_of_product_emails"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."opt_out_of_product_emails"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/prepare_preset_lineage.sql
CREATE OR REPLACE FUNCTION public.prepare_preset_lineage()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare source_row public.presets%rowtype;
begin
  if new.source_preset_id is null then
    new.root_preset_id := new.id;
    new.fork_depth := 0;
    return new;
  end if;
  select * into source_row from public.presets where id = new.source_preset_id;
  if not found then raise exception 'source_preset_not_found'; end if;
  new.root_preset_id := coalesce(source_row.root_preset_id, source_row.id);
  new.fork_depth := source_row.fork_depth + 1;
  new.source_preset_version_id := coalesce(new.source_preset_version_id, source_row.active_version_id);
  new.upstream_version_id := coalesce(new.upstream_version_id, source_row.active_version_id);
  return new;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."prepare_preset_lineage"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."prepare_preset_lineage"() FROM PUBLIC, "anon", "authenticated";

