-- source: supabase/schemas/public/functions/prevent_published_control_plane_release_mutation.sql
CREATE OR REPLACE FUNCTION public.prevent_published_control_plane_release_mutation()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
begin
  if old.published_once_at is not null then
    if tg_op = 'UPDATE'
      and new.status = 'superseded'
      and new.superseded_at is not null
      and (to_jsonb(new) - 'status' - 'superseded_at') =
        (to_jsonb(old) - 'status' - 'superseded_at') then
      return new;
    end if;
    raise exception 'Published control-plane releases are immutable';
  end if;
  if tg_op = 'UPDATE' and new.status = 'published' then
    new.published_once_at := coalesce(new.published_once_at, new.published_at, now());
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."prevent_published_control_plane_release_mutation"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."prevent_published_control_plane_release_mutation"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/prevent_published_execution_plan_mutation.sql
CREATE OR REPLACE FUNCTION public.prevent_published_execution_plan_mutation()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  old_release_published_at timestamptz;
  new_release_published_at timestamptz;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    select published_once_at into old_release_published_at
      from public.v2_control_plane_releases where release_id = old.release_id;
    if old_release_published_at is not null then
      raise exception 'Execution plans in published releases are immutable';
    end if;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    select published_once_at into new_release_published_at
      from public.v2_control_plane_releases where release_id = new.release_id;
    if new_release_published_at is not null then
      raise exception 'Execution plans in published releases are immutable';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."prevent_published_execution_plan_mutation"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."prevent_published_execution_plan_mutation"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/prevent_reserved_workspace_publisher_handle.sql
CREATE OR REPLACE FUNCTION public.prevent_reserved_workspace_publisher_handle()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  new.publisher_handle := lower(trim(new.publisher_handle));
  if exists (
    select 1 from public.workspace_publisher_handle_aliases alias
    where alias.handle = new.publisher_handle
      and alias.workspace_id <> new.id
  ) then
    raise exception 'publisher_handle_reserved' using errcode = '23505';
  end if;
  return new;
end
$function$;

GRANT EXECUTE ON FUNCTION "public"."prevent_reserved_workspace_publisher_handle"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."prevent_reserved_workspace_publisher_handle"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/preview_key_storage_incident.sql
CREATE OR REPLACE FUNCTION public.preview_key_storage_incident (
  p_location_id         text,
  p_keys_created_before timestamp with time zone,
  p_action              text DEFAULT 'revoke'::text
)
  RETURNS TABLE (
    keys       bigint,
    workspaces bigint
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- The keys apply_key_storage_incident would change. Service-only.
  select count(*), count(distinct key.workspace_id)
  from public.keys as key
  where key.storage_locations @> array[p_location_id]
    and cardinality(key.storage_locations) > 0
    and key.created_at < p_keys_created_before
    and key.key_kind = 'standard'
    and key.status = any(case when p_action = 'pause' then array['active'] else array['active', 'paused'] end)
    and key.name not in ('__chat_route_managed_key__', '__slack_agent_managed_key__');
$function$;

COMMENT ON FUNCTION "public"."preview_key_storage_incident"(text, timestamp with time zone, text) IS 'How many keys and workspaces a key storage incident would revoke or pause. Service-only.';

GRANT EXECUTE ON FUNCTION "public"."preview_key_storage_incident"(text, timestamp with time zone, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."preview_key_storage_incident"(text, timestamp with time zone, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/preview_workspace_spend_rule.sql
CREATE OR REPLACE FUNCTION public.preview_workspace_spend_rule (
  p_workspace_id uuid,
  p_rule_id      uuid,
  p_now          timestamp with time zone DEFAULT now()
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Where a spend rule stands at p_now, computed as the evaluator computes it
-- (private.spend_rule_values) without writing anything: the current period, the value so far,
-- the base and percent, the highest threshold reached, the next threshold, the block point,
-- this period's state row, and the text an alert would carry now (private.spend_rule_alert_text,
-- naming the highest threshold reached, else the first). Used by the control API and web-api
-- preview and by test sends. Balance rules get the rolling burn window as period, the available
-- balance as value, a "balance" object (balance, reserved, available, burn and burn per day,
-- runway, which threshold holds, armed, whether auto top-up covers a drop) and the alert text
-- (private.spend_balance_rule_values / spend_balance_alert_text). Rolling spend and
-- budget_percent rules get their window as period (with window_hours) and their '-infinity'
-- state row. Forecast rules get a "forecast" object (ready, from, projected_nanos and
-- projected_percent, by = the period end, limit_nanos, reaches_at) and their thresholds are
-- measured against the projection; previous_period bases get "previous_period" {start, end}.
-- Spike rules get their window as period, spend over it as value, the median of the same window
-- over the previous 7 days as base_nanos (percent = value / median), the point they fire at as
-- next_threshold (while ready and not spiking), a "spike" object (window_hours, current, baseline,
-- multiple, multiplier, floor, fires_at, baseline_windows, active_windows, history_ready, spiking,
-- cooldown_until) and the alert text (private.spend_spike_rule_values / spend_spike_alert_text).
-- Every other metric gets "spike": null. evaluated is false for rules the evaluator does not
-- handle (private.spend_rule_evaluable). Errors: spend_rule_not_found (deleted, or another
-- workspace).
declare
  v_rule public.workspace_spend_rules;
  v_workspace_name text;
  v_time_zone text;
  v_evaluated boolean;
  v_value record;
  v_state record;
  v_reached integer;
  v_next integer;
  v_next_nanos numeric;
  v_block_nanos numeric;
  v_alert record;
  v_has_alert boolean := false;
  v_has_state boolean := false;
  v_balance record;
  v_has_balance boolean := false;
  v_measure numeric;
  v_spike record;
  v_has_spike boolean := false;
begin
  if p_workspace_id is null or p_rule_id is null or p_now is null then
    raise exception 'invalid_spend_rule_preview' using errcode = '22023';
  end if;

  select rule.* into v_rule
  from public.workspace_spend_rules rule
  where rule.id = p_rule_id and rule.workspace_id = p_workspace_id and rule.deleted_at is null;
  if not found then
    raise exception 'spend_rule_not_found' using errcode = 'P0002';
  end if;

  select w.name, coalesce(v_rule.time_zone, settings.billing_time_zone, 'UTC')
    into v_workspace_name, v_time_zone
  from public.workspaces w
  left join public.workspace_settings settings on settings.workspace_id = w.id
  where w.id = p_workspace_id;

  v_evaluated := private.spend_rule_evaluable(v_rule.metric, v_rule.period, v_rule.base_kind);

  if v_rule.metric = 'balance' then
    -- Balance rules: the available balance, the burn over the lookback window and the runway, as
    -- the evaluator sees them (private.spend_balance_rule_values), the armed state and the text.
    select computed.* into v_balance from private.spend_balance_rule_values(p_workspace_id, p_now, p_rule_id) computed;
    v_has_balance := found;
    select state.armed, state.amount_fired_at, state.last_fired_at, state.fire_count
      into v_state
    from public.workspace_spend_rule_state state
    where state.rule_id = v_rule.id and state.period_start = '-infinity'::timestamptz;
    v_has_state := found;
    if v_has_balance then
      -- The text an alert would carry now: the threshold that holds, else the balance amount if
      -- the rule has one, else the runway.
      select alert.* into v_alert
      from private.spend_balance_alert_text(
        v_rule.name, v_balance.available_nanos, v_rule.threshold_amount_nanos, v_rule.runway_days, v_balance.burn_per_day_nanos,
        v_balance.runway_days_left, v_rule.window_hours,
        case
          when v_balance.low_balance then 'balance'
          when v_balance.low_runway then 'runway'
          when v_rule.threshold_amount_nanos is not null then 'balance'
          else 'runway'
        end
      ) alert;
      v_has_alert := found;
    end if;
    return jsonb_build_object(
      'rule_id', v_rule.id,
      'metric', v_rule.metric,
      'evaluated', v_evaluated,
      'computed_at', p_now,
      'time_zone', v_time_zone,
      'period', case when v_rule.window_hours is not null then jsonb_build_object(
        'kind', 'rolling', 'start', p_now - make_interval(hours => v_rule.window_hours), 'end', p_now) end,
      'value_nanos', case when v_has_balance then v_balance.available_nanos end,
      'base_kind', null,
      'base_ref', null,
      'base_nanos', null,
      'percent', null,
      'threshold_percents', null,
      'threshold_amount_nanos', v_rule.threshold_amount_nanos,
      'reached_threshold_percent', null,
      'next_threshold', null,
      'block_at_nanos', null,
      'balance', case when v_has_balance then jsonb_build_object(
        'balance_nanos', v_balance.balance_nanos,
        'reserved_nanos', v_balance.reserved_nanos,
        'available_nanos', v_balance.available_nanos,
        'window_hours', v_rule.window_hours,
        'burn_nanos', round(v_balance.burn_nanos),
        'burn_per_day_nanos', round(v_balance.burn_per_day_nanos),
        'runway_days_left', v_balance.runway_days_left,
        'runway_days', v_rule.runway_days,
        'low_balance', v_balance.low_balance,
        'low_runway', v_balance.low_runway,
        'armed', coalesce(v_state.armed, true),
        'auto_top_up_covers', private.workspace_auto_top_up_covers(p_workspace_id)
      ) end,
      'state', case when v_has_state then jsonb_build_object(
        'highest_percent_fired', null,
        'amount_fired_at', v_state.amount_fired_at,
        'last_fired_at', v_state.last_fired_at,
        'fire_count', v_state.fire_count,
        'armed', v_state.armed
      ) end,
      'alert', case when v_has_alert then jsonb_build_object(
        'scope_label', coalesce(nullif(btrim(v_workspace_name), ''), 'Workspace'),
        'title', v_alert.title,
        'message', v_alert.message
      ) end
    );
  end if;

  if v_rule.metric = 'spike' then
    -- Spike rules: spend over the window, the median of the same window over the previous 7 days,
    -- the multiple and the point the rule fires at, as the evaluator sees them
    -- (private.spend_spike_rule_values), the cooldown state and the text.
    select computed.* into v_spike from private.spend_spike_rule_values(p_workspace_id, p_now, p_rule_id) computed;
    v_has_spike := found;
    select state.last_fired_at, state.fire_count into v_state
    from public.workspace_spend_rule_state state
    where state.rule_id = v_rule.id and state.period_start = '-infinity'::timestamptz;
    v_has_state := found;
    if v_has_spike and v_spike.baseline_windows >= 3 then
      select alert.* into v_alert
      from private.spend_spike_alert_text(
        v_workspace_name, v_rule.name, v_rule.scope_type, v_rule.scope_id, v_rule.scope_key_id, v_rule.scope_user_id,
        v_rule.scope_department_id, v_rule.window_hours, v_spike.current_nanos, v_spike.baseline_nanos, v_spike.multiple,
        v_rule.spike_multiplier, v_rule.spike_floor_nanos, v_spike.baseline_windows
      ) alert;
      v_has_alert := found;
    end if;
    return jsonb_build_object(
      'rule_id', v_rule.id,
      'metric', v_rule.metric,
      'evaluated', v_evaluated,
      'computed_at', p_now,
      'time_zone', v_time_zone,
      'period', case when v_has_spike then jsonb_build_object(
        'kind', 'rolling', 'start', v_spike.period_start, 'end', v_spike.period_end, 'window_hours', v_rule.window_hours) end,
      'value_nanos', case when v_has_spike then v_spike.current_nanos end,
      'base_kind', null,
      'base_ref', null,
      'base_nanos', case when v_has_spike then v_spike.baseline_nanos end,
      'previous_period', null,
      'forecast', null,
      'percent', case when v_spike.baseline_nanos > 0 then round(v_spike.current_nanos * 100 / v_spike.baseline_nanos, 1) end,
      'threshold_percents', null,
      'threshold_amount_nanos', null,
      'reached_threshold_percent', null,
      'next_threshold', case when v_has_spike and not v_spike.spiking and v_spike.history_ready then jsonb_build_object(
        'percent', null, 'amount_nanos', v_spike.fires_at_nanos) end,
      'block_at_nanos', null,
      'balance', null,
      'spike', case when v_has_spike then jsonb_build_object(
        'window_hours', v_rule.window_hours,
        'current_nanos', v_spike.current_nanos,
        'baseline_nanos', v_spike.baseline_nanos,
        'multiple', v_spike.multiple,
        'multiplier', v_rule.spike_multiplier,
        'floor_nanos', v_rule.spike_floor_nanos,
        'fires_at_nanos', v_spike.fires_at_nanos,
        'baseline_windows', v_spike.baseline_windows,
        'active_windows', v_spike.active_windows,
        'history_ready', v_spike.history_ready,
        'spiking', v_spike.spiking,
        'cooldown_until', case when v_state.last_fired_at + make_interval(mins => v_rule.cooldown_minutes) > p_now
          then v_state.last_fired_at + make_interval(mins => v_rule.cooldown_minutes) end
      ) end,
      'state', case when v_has_state then jsonb_build_object(
        'highest_percent_fired', null,
        'amount_fired_at', null,
        'last_fired_at', v_state.last_fired_at,
        'fire_count', v_state.fire_count
      ) end,
      'alert', case when v_has_alert then jsonb_build_object(
        'scope_label', v_alert.scope_label,
        'title', v_alert.title,
        'message', v_alert.message
      ) end
    );
  end if;

  select computed.* into v_value from private.spend_rule_values(p_workspace_id, p_now, p_rule_id) computed;
  if not found then
    return jsonb_build_object(
      'rule_id', v_rule.id,
      'metric', v_rule.metric,
      'evaluated', v_evaluated,
      'computed_at', p_now,
      'time_zone', v_time_zone,
      'period', null,
      'value_nanos', null,
      'base_kind', v_rule.base_kind,
      'base_ref', v_rule.base_ref,
      'base_nanos', null,
      'previous_period', null,
      'forecast', null,
      'percent', null,
      'threshold_percents', to_jsonb(v_rule.threshold_percents),
      'threshold_amount_nanos', v_rule.threshold_amount_nanos,
      'reached_threshold_percent', null,
      'next_threshold', null,
      'block_at_nanos', null,
      'state', null,
      'alert', null
    );
  end if;

  select state.highest_percent_fired, state.amount_fired_at, state.last_fired_at, state.fire_count
    into v_state
  from public.workspace_spend_rule_state state
  where state.rule_id = v_rule.id
    and state.period_start = case when v_rule.period = 'rolling' then '-infinity'::timestamptz else v_value.period_start end;
  v_has_state := found;

  -- What thresholds are measured against: spend so far, or a forecast's projection (none until
  -- the projection is ready).
  v_measure := case when v_rule.metric = 'forecast' then v_value.projected_nanos else v_value.value_nanos end;

  if v_rule.metric in ('budget_percent', 'forecast') and v_value.base_nanos > 0 and v_rule.threshold_percents is not null then
    if v_measure is not null then
      select
        max(threshold) filter (where v_measure * 100 >= threshold::numeric * v_value.base_nanos),
        min(threshold) filter (where v_measure * 100 < threshold::numeric * v_value.base_nanos)
        into v_reached, v_next
      from unnest(v_rule.threshold_percents) threshold;
    else
      v_next := v_rule.threshold_percents[1];
    end if;
    v_next_nanos := ceil(v_next::numeric * v_value.base_nanos / 100);
  elsif v_rule.threshold_amount_nanos is not null and (v_measure is null or v_measure < v_rule.threshold_amount_nanos) then
    v_next_nanos := v_rule.threshold_amount_nanos;
  end if;

  if v_rule.action = 'block' then
    v_block_nanos := case
      when v_rule.metric = 'spend' then v_rule.block_at_amount_nanos
      when v_value.base_nanos > 0 then ceil(v_rule.block_at_percent::numeric * v_value.base_nanos / 100)
    end;
  end if;

  if v_rule.metric = 'spend'
    or (v_rule.metric = 'budget_percent' and v_value.base_nanos > 0)
    or (v_rule.metric = 'forecast' and v_value.projected_nanos is not null
      and (v_rule.threshold_amount_nanos is not null or v_value.base_nanos > 0)) then
    select alert.* into v_alert
    from private.spend_rule_alert_text(
      v_workspace_name, v_rule.name, v_rule.metric, v_rule.scope_type, v_rule.scope_id, v_rule.scope_key_id,
      v_rule.scope_user_id, v_rule.scope_department_id, v_rule.period, v_value.period_end, v_value.time_zone,
      v_rule.base_kind, v_rule.base_ref, v_value.base_nanos, v_rule.threshold_percents, v_rule.threshold_amount_nanos,
      v_value.value_nanos, coalesce(v_reached, v_rule.threshold_percents[1]), v_rule.window_hours, v_value.projected_nanos,
      v_value.reaches_at
    ) alert;
    v_has_alert := found;
  end if;

  return jsonb_build_object(
    'rule_id', v_rule.id,
    'metric', v_rule.metric,
    'evaluated', v_evaluated,
    'computed_at', p_now,
    'time_zone', v_value.time_zone,
    'period', jsonb_strip_nulls(jsonb_build_object('kind', v_rule.period, 'start', v_value.period_start, 'end', v_value.period_end,
      'window_hours', v_value.window_hours)),
    'value_nanos', v_value.value_nanos,
    'base_kind', v_rule.base_kind,
    'base_ref', v_rule.base_ref,
    'base_nanos', v_value.base_nanos,
    'previous_period', case when v_value.previous_start is not null then jsonb_build_object(
      'start', v_value.previous_start, 'end', v_value.previous_end) end,
    'forecast', case when v_rule.metric = 'forecast' then jsonb_build_object(
      'ready', v_value.projected_nanos is not null,
      'from', v_value.forecast_from,
      'projected_nanos', v_value.projected_nanos,
      'projected_percent', case when v_value.base_nanos > 0 and v_value.projected_nanos is not null
        then round(v_value.projected_nanos * 100 / v_value.base_nanos, 1) end,
      'by', v_value.period_end,
      'limit_nanos', v_value.limit_nanos,
      'reaches_at', v_value.reaches_at
    ) end,
    'percent', case when v_value.base_nanos > 0 then round(v_value.value_nanos * 100 / v_value.base_nanos, 1) end,
    'threshold_percents', to_jsonb(v_rule.threshold_percents),
    'threshold_amount_nanos', v_rule.threshold_amount_nanos,
    'reached_threshold_percent', v_reached,
    'next_threshold', case when v_next_nanos is not null then jsonb_build_object('percent', v_next, 'amount_nanos', v_next_nanos) end,
    'block_at_nanos', v_block_nanos,
    'state', case when v_has_state then jsonb_build_object(
      'highest_percent_fired', v_state.highest_percent_fired,
      'amount_fired_at', v_state.amount_fired_at,
      'last_fired_at', v_state.last_fired_at,
      'fire_count', v_state.fire_count
    ) end,
    'alert', case when v_has_alert then jsonb_build_object(
      'scope_label', v_alert.scope_label,
      'title', v_alert.title,
      'message', v_alert.message
    ) end
  );
end;
$function$;

COMMENT ON FUNCTION "public"."preview_workspace_spend_rule"(uuid, uuid, timestamp with time zone) IS 'Read-only preview of a spend rule at p_now: period, value, base, percent, thresholds reached and next, block point, state and the alert text, computed by the evaluator''s own functions. Service role only (control API and web-api).';

REVOKE ALL ON FUNCTION "public"."preview_workspace_spend_rule"(uuid, uuid, timestamp with time zone) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."preview_workspace_spend_rule"(uuid, uuid, timestamp with time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."preview_workspace_spend_rule"(uuid, uuid, timestamp with time zone) FROM "anon", "authenticated";

-- source: supabase/schemas/public/functions/process_v2_analytics_outbox.sql
CREATE OR REPLACE FUNCTION public.process_v2_analytics_outbox (
  p_limit integer DEFAULT 250
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 250), 2000));
  v_selected integer := 0;
  v_coalesced integer := 0;
  v_private_grains integer := 0;
  v_public_daily_grains integer := 0;
  v_public_hourly_grains integer := 0;
  v_workspace_hours integer := 0;
  v_rollup_id uuid;
  grain record;
begin
  -- Different event batches can rebuild the same summary concurrently.
  if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('public.process_v2_analytics_outbox', 0)) then
    return jsonb_build_object('selected', 0, 'coalesced', 0, 'private_grains', 0,
      'public_daily_grains', 0, 'public_hourly_grains', 0, 'workspace_hours', 0, 'skipped_locked', true);
  end if;
  create temporary table if not exists pg_temp.v2_rollup_batch (
    request_event_id uuid primary key,
    workspace_id uuid not null,
    occurred_at timestamptz not null,
    app_id uuid,
    model_slug text,
    provider_model_id text,
    cloudflare_colo text
  ) on commit drop;
  truncate table pg_temp.v2_rollup_batch;

  insert into pg_temp.v2_rollup_batch (
    request_event_id, workspace_id, occurred_at, app_id, model_slug,
    provider_model_id, cloudflare_colo
  )
  select
    outbox.request_event_id,
    fact.workspace_id,
    fact.occurred_at,
    fact.app_id,
    coalesce(fact.routed_model_slug, fact.requested_model_slug),
    fact.provider_model_id,
    fact.cloudflare_colo
  from public.v2_analytics_outbox outbox
  join public.v2_request_facts fact on fact.request_event_id = outbox.request_event_id
  where outbox.status in ('pending', 'failed')
    and outbox.available_at <= now()
  order by outbox.occurred_at, outbox.request_event_id
  for update of outbox skip locked
  limit case when exists(select 1 from private.v2_analytics_previous_grains)
    then greatest(0,v_limit-least(5,v_limit)) else v_limit end;


  get diagnostics v_selected = row_count;
  create temporary table if not exists pg_temp.v2_previous_grain_batch
    (like private.v2_analytics_previous_grains including defaults) on commit drop;
  truncate table pg_temp.v2_previous_grain_batch;
  alter table pg_temp.v2_previous_grain_batch add column if not exists transaction_id bigint;
  insert into pg_temp.v2_previous_grain_batch(grain_id,workspace_id,occurred_at,app_id,model_slug,provider_model_id,cloudflare_colo,queued_at,transaction_id)
  select previous.* from private.v2_analytics_previous_grains previous
  order by previous.queued_at,previous.grain_id for update skip locked limit greatest(0,v_limit-v_selected);
  insert into pg_temp.v2_rollup_batch
    (request_event_id,workspace_id,occurred_at,app_id,model_slug,provider_model_id,cloudflare_colo)
  select grain_id,workspace_id,occurred_at,app_id,model_slug,provider_model_id,cloudflare_colo
  from pg_temp.v2_previous_grain_batch;
  v_selected := v_selected + (select count(*) from pg_temp.v2_previous_grain_batch);

  if v_selected = 0 then
    return jsonb_build_object(
      'selected', 0,
      'coalesced', 0,
      'private_grains', 0,
      'public_daily_grains', 0,
      'public_hourly_grains', 0,
      'workspace_hours', 0
    );
  end if;

  -- The full-grain rebuild also includes other ready events in these same
  -- workspace/hour identities. Lock them before reading sources: corrections
  -- then re-enqueue after this transaction, even when an existing pending
  -- outbox upsert would otherwise have been a no-op. Cap all acknowledgments
  -- at 2,000; do not enlarge the set of summaries that must be rebuilt.
  insert into pg_temp.v2_rollup_batch (
    request_event_id, workspace_id, occurred_at, app_id, model_slug,
    provider_model_id, cloudflare_colo
  )
  select outbox.request_event_id, fact.workspace_id, fact.occurred_at, fact.app_id,
    coalesce(fact.routed_model_slug, fact.requested_model_slug),
    fact.provider_model_id, fact.cloudflare_colo
  from public.v2_analytics_outbox outbox
  join public.v2_request_facts fact on fact.request_event_id = outbox.request_event_id
  where outbox.status in ('pending', 'failed') and outbox.available_at <= now()
    and outbox.occurred_at >= (select date_trunc('hour', min(occurred_at)) from pg_temp.v2_rollup_batch)
    and outbox.occurred_at < (select date_trunc('hour', max(occurred_at)) + interval '1 hour' from pg_temp.v2_rollup_batch)
    and not exists (select 1 from pg_temp.v2_rollup_batch batch where batch.request_event_id = outbox.request_event_id)
    and exists (
      select 1 from pg_temp.v2_rollup_batch batch
      where batch.model_slug is not null and batch.workspace_id = fact.workspace_id
        and date_trunc('hour', batch.occurred_at) = date_trunc('hour', fact.occurred_at)
        and batch.app_id is not distinct from fact.app_id
        and batch.model_slug = coalesce(fact.routed_model_slug, fact.requested_model_slug)
        and batch.provider_model_id is not distinct from fact.provider_model_id
        and batch.cloudflare_colo is not distinct from fact.cloudflare_colo
    )
  order by outbox.occurred_at, outbox.request_event_id
  for update of outbox skip locked
  limit greatest(0, least(2000, v_limit * 8) - v_selected);
  get diagnostics v_coalesced = row_count;

  update public.v2_analytics_outbox outbox
  set status = 'processing', updated_at = now()
  where outbox.request_event_id in (select batch.request_event_id from pg_temp.v2_rollup_batch batch);

  for grain in
    select distinct
      batch.workspace_id,
      batch.occurred_at::date as usage_date,
      batch.app_id,
      batch.model_slug,
      batch.provider_model_id,
      batch.cloudflare_colo
    from pg_temp.v2_rollup_batch batch
    where batch.model_slug is not null
  loop
    delete from public.v2_private_usage_daily rollup
    where rollup.workspace_id = grain.workspace_id
      and rollup.usage_date = grain.usage_date
      and rollup.app_id is not distinct from grain.app_id
      and rollup.model_slug = grain.model_slug
      and rollup.provider_model_id is not distinct from grain.provider_model_id
      and rollup.cloudflare_colo is not distinct from grain.cloudflare_colo;

    insert into public.v2_private_usage_daily (
      usage_date, workspace_id, app_id, model_slug, provider_model_id, cloudflare_colo,
      requests, successful_requests, failed_requests, rate_limited_requests,
      tool_call_count, tool_call_requests, tool_call_successes,
      structured_output_attempts, structured_output_successes,
      latency_sum_ms, latency_count, generation_sum_ms, generation_count,
      throughput_sum, throughput_count, gateway_total_sum_ms, gateway_total_count,
      internal_dispatch_sum_ms, internal_dispatch_count,
      upstream_attempts, failed_upstream_attempts, cached_input_tokens, input_tokens, cost_nanos
    )
    select
      grain.usage_date, grain.workspace_id, grain.app_id, grain.model_slug,
      grain.provider_model_id, grain.cloudflare_colo,
      count(*), count(*) filter (where fact.success), count(*) filter (where not fact.success),
      count(*) filter (where fact.status_code = 429),
      coalesce(sum(fact.tool_call_count), 0),
      count(*) filter (where fact.tool_call_count > 0),
      count(*) filter (where fact.tool_call_count > 0 and fact.tool_call_succeeded is true),
      count(*) filter (where fact.structured_output_attempted),
      count(*) filter (where fact.structured_output_attempted and fact.structured_output_succeeded),
      coalesce(sum(fact.latency_ms), 0), count(fact.latency_ms),
      coalesce(sum(fact.generation_ms), 0), count(fact.generation_ms),
      coalesce(sum(fact.throughput), 0), count(fact.throughput),
      coalesce(sum(fact.gateway_total_ms), 0), count(fact.gateway_total_ms),
      coalesce(sum(fact.internal_dispatch_ms), 0), count(fact.internal_dispatch_ms),
      coalesce(sum(attempts.attempts), 0), coalesce(sum(attempts.failed_attempts), 0),
      coalesce(sum(usage.cached_input_tokens), 0), coalesce(sum(usage.input_tokens), 0),
      coalesce(sum(fact.cost_nanos), 0)
    from public.v2_request_facts fact
    left join lateral (
      select count(*)::bigint as attempts,
        count(*) filter (where not attempt.success)::bigint as failed_attempts
      from public.v2_request_attempts attempt
      where attempt.request_event_id = fact.request_event_id
    ) attempts on true
    left join lateral (
      select
        coalesce(sum(meter.quantity) filter (where meter.meter_key = 'cached_input_tokens'), 0) as cached_input_tokens,
        coalesce(sum(meter.quantity) filter (where meter.meter_key = 'input_tokens'), 0) as input_tokens
      from public.v2_request_usage meter
      where meter.request_event_id = fact.request_event_id
    ) usage on true
    where fact.workspace_id = grain.workspace_id
      and fact.occurred_at >= grain.usage_date::timestamptz
      and fact.occurred_at < (grain.usage_date + 1)::timestamptz
      and fact.app_id is not distinct from grain.app_id
      and coalesce(fact.routed_model_slug, fact.requested_model_slug) = grain.model_slug
      and fact.provider_model_id is not distinct from grain.provider_model_id
      and fact.cloudflare_colo is not distinct from grain.cloudflare_colo
    having count(*) > 0
    returning rollup_id into v_rollup_id;

    insert into public.v2_private_usage_daily_meters (
      rollup_id, meter_key, modality, unit, quantity
    )
    select v_rollup_id, meter.meter_key, meter.modality, meter.unit, sum(meter.quantity)
    from public.v2_request_usage meter
    join public.v2_request_facts fact on fact.request_event_id = meter.request_event_id
    where fact.workspace_id = grain.workspace_id
      and fact.occurred_at >= grain.usage_date::timestamptz
      and fact.occurred_at < (grain.usage_date + 1)::timestamptz
      and fact.app_id is not distinct from grain.app_id
      and coalesce(fact.routed_model_slug, fact.requested_model_slug) = grain.model_slug
      and fact.provider_model_id is not distinct from grain.provider_model_id
      and fact.cloudflare_colo is not distinct from grain.cloudflare_colo
    group by meter.meter_key, meter.modality, meter.unit;

    v_private_grains := v_private_grains + 1;
  end loop;

  -- The usage overview's 15-minute rollups are rebuilt a whole workspace hour at a
  -- time, so a correction that moves a request to another key or model within the
  -- hour is rebuilt too. v2_usage_overview_requests counts each request as the
  -- overview does; get_private_usage_overview reads requests outside the rollups
  -- from the same view. The 15-minute rollup also keeps each request's actor (key creator
  -- or OAuth user) apart for spend rules; the label rollup does not.
  for grain in
    select distinct batch.workspace_id, date_trunc('hour', batch.occurred_at, 'UTC') as bucket_start
    from pg_temp.v2_rollup_batch batch
  loop
    delete from public.v2_private_usage_15m rollup
    where rollup.workspace_id = grain.workspace_id
      and rollup.bucket_start >= grain.bucket_start
      and rollup.bucket_start < grain.bucket_start + interval '1 hour';
    delete from public.v2_private_usage_labels_15m rollup
    where rollup.workspace_id = grain.workspace_id
      and rollup.bucket_start >= grain.bucket_start
      and rollup.bucket_start < grain.bucket_start + interval '1 hour';

    -- Read each request's usage meters once for both rollups.
    with requests as materialized (
      select request.*, date_bin('15 minutes', request.occurred_at, grain.bucket_start) as bucket_start
      from private.v2_usage_overview_requests request
      where request.workspace_id = grain.workspace_id
        and request.occurred_at >= grain.bucket_start
        and request.occurred_at < grain.bucket_start + interval '1 hour'
    ), totals as (
      insert into public.v2_private_usage_15m (
        workspace_id, bucket_start, model_id, provider_model_id, key_id, app_id, byok, actor_user_id,
        requests, successful_requests, guardrail_blocked, cost_nanos,
        tokens, input_tokens, output_tokens, reasoning_tokens, cached_tokens
      )
      select
        grain.workspace_id, request.bucket_start, request.model_id, request.provider_model_id,
        request.key_id, request.app_id, request.byok, request.actor_user_id,
        count(*), count(*) filter (where request.successful), count(*) filter (where request.guardrail_blocked),
        sum(request.cost_nanos), sum(request.tokens), sum(request.input_tokens), sum(request.output_tokens),
        sum(request.reasoning_tokens), sum(request.cached_tokens)
      from requests request
      group by 2, 3, 4, 5, 6, 7, 8
    )
    insert into public.v2_private_usage_labels_15m (
      workspace_id, bucket_start, label_key, label_value, model_id, provider_model_id, key_id, app_id, byok,
      requests, successful_requests, guardrail_blocked, cost_nanos,
      tokens, input_tokens, output_tokens, reasoning_tokens, cached_tokens
    )
    select
      grain.workspace_id, request.bucket_start, label.label_key, label.label_value,
      request.model_id, request.provider_model_id, request.key_id, request.app_id, request.byok,
      count(*), count(*) filter (where request.successful), count(*) filter (where request.guardrail_blocked),
      sum(request.cost_nanos), sum(request.tokens), sum(request.input_tokens), sum(request.output_tokens),
      sum(request.reasoning_tokens), sum(request.cached_tokens)
    from requests request
    cross join lateral (
      -- A request counts once per label, however often it repeats it.
      select distinct element.value ->> 'key' as label_key, element.value ->> 'value' as label_value
      from jsonb_array_elements(request.labels) element
      where jsonb_typeof(element.value -> 'key') = 'string' and jsonb_typeof(element.value -> 'value') = 'string'
    ) label
    group by 2, 3, 4, 5, 6, 7, 8, 9;

    v_workspace_hours := v_workspace_hours + 1;
  end loop;

  -- Spend rules: mark each rebuilt workspace that has an enabled rule, in one statement, for
  -- public.sweep_spend_rules. A row already there stays as it is.
  insert into public.workspace_spend_rule_dirty (workspace_id)
  select batch.workspace_id
  from (select distinct rollup_batch.workspace_id from pg_temp.v2_rollup_batch rollup_batch) batch
  where exists (
    select 1 from public.workspace_spend_rules rule
    where rule.workspace_id = batch.workspace_id and rule.enabled and rule.deleted_at is null
  )
  on conflict (workspace_id) do nothing;

  for grain in
    select distinct
      batch.occurred_at::date as usage_date,
      batch.app_id,
      batch.model_slug,
      batch.provider_model_id,
      batch.cloudflare_colo
    from pg_temp.v2_rollup_batch batch
    where batch.model_slug is not null
  loop
    delete from public.v2_public_usage_daily rollup
    where rollup.usage_date = grain.usage_date
      and rollup.app_id is not distinct from grain.app_id
      and rollup.model_slug = grain.model_slug
      and rollup.provider_model_id is not distinct from grain.provider_model_id
      and rollup.cloudflare_colo is not distinct from grain.cloudflare_colo;

    insert into public.v2_public_usage_daily (
      usage_date, app_id, model_slug, provider_model_id, cloudflare_colo,
      requests, successful_requests, failed_requests, rate_limited_requests,
      tool_call_count, tool_call_requests, tool_call_successes,
      structured_output_attempts, structured_output_successes,
      latency_sum_ms, latency_count, generation_sum_ms, generation_count,
      throughput_sum, throughput_count, gateway_total_sum_ms, gateway_total_count,
      internal_dispatch_sum_ms, internal_dispatch_count,
      upstream_attempts, failed_upstream_attempts, cached_input_tokens, input_tokens, cost_nanos
    )
    select
      grain.usage_date, grain.app_id, grain.model_slug, grain.provider_model_id, grain.cloudflare_colo,
      count(*), count(*) filter (where fact.success), count(*) filter (where not fact.success),
      count(*) filter (where fact.status_code = 429),
      coalesce(sum(fact.tool_call_count), 0),
      count(*) filter (where fact.tool_call_count > 0),
      count(*) filter (where fact.tool_call_count > 0 and fact.tool_call_succeeded is true),
      count(*) filter (where fact.structured_output_attempted),
      count(*) filter (where fact.structured_output_attempted and fact.structured_output_succeeded),
      coalesce(sum(fact.latency_ms), 0), count(fact.latency_ms),
      coalesce(sum(fact.generation_ms), 0), count(fact.generation_ms),
      coalesce(sum(fact.throughput), 0), count(fact.throughput),
      coalesce(sum(fact.gateway_total_ms), 0), count(fact.gateway_total_ms),
      coalesce(sum(fact.internal_dispatch_ms), 0), count(fact.internal_dispatch_ms),
      coalesce(sum(attempts.attempts), 0), coalesce(sum(attempts.failed_attempts), 0),
      coalesce(sum(usage.cached_input_tokens), 0), coalesce(sum(usage.input_tokens), 0),
      coalesce(sum(fact.cost_nanos), 0)
    from public.reporting_request_facts fact
    left join lateral (
      select count(*)::bigint as attempts,
        count(*) filter (where not attempt.success)::bigint as failed_attempts
      from public.v2_request_attempts attempt
      where attempt.request_event_id = fact.request_event_id
    ) attempts on true
    left join lateral (
      select
        coalesce(sum(meter.quantity) filter (where meter.meter_key = 'cached_input_tokens'), 0) as cached_input_tokens,
        coalesce(sum(meter.quantity) filter (where meter.meter_key = 'input_tokens'), 0) as input_tokens
      from public.v2_request_usage meter
      where meter.request_event_id = fact.request_event_id
    ) usage on true
    where fact.occurred_at >= grain.usage_date::timestamptz
      and fact.occurred_at < (grain.usage_date + 1)::timestamptz
      and fact.app_id is not distinct from grain.app_id
      and coalesce(fact.routed_model_slug, fact.requested_model_slug) = grain.model_slug
      and fact.provider_model_id is not distinct from grain.provider_model_id
      and fact.cloudflare_colo is not distinct from grain.cloudflare_colo
    having count(*) > 0
    returning rollup_id into v_rollup_id;

    insert into public.v2_public_usage_daily_meters (
      rollup_id, meter_key, modality, unit, quantity
    )
    select v_rollup_id, meter.meter_key, meter.modality, meter.unit, sum(meter.quantity)
    from public.v2_request_usage meter
    join public.reporting_request_facts fact on fact.request_event_id = meter.request_event_id
    where fact.occurred_at >= grain.usage_date::timestamptz
      and fact.occurred_at < (grain.usage_date + 1)::timestamptz
      and fact.app_id is not distinct from grain.app_id
      and coalesce(fact.routed_model_slug, fact.requested_model_slug) = grain.model_slug
      and fact.provider_model_id is not distinct from grain.provider_model_id
      and fact.cloudflare_colo is not distinct from grain.cloudflare_colo
    group by meter.meter_key, meter.modality, meter.unit;

    v_public_daily_grains := v_public_daily_grains + 1;
  end loop;

  for grain in
    select distinct
      date_trunc('hour', batch.occurred_at) as bucket_start,
      batch.app_id,
      batch.model_slug,
      batch.provider_model_id,
      batch.cloudflare_colo
    from pg_temp.v2_rollup_batch batch
    where batch.model_slug is not null
  loop
    delete from public.v2_public_usage_hourly rollup
    where rollup.bucket_start = grain.bucket_start
      and rollup.app_id is not distinct from grain.app_id
      and rollup.model_slug = grain.model_slug
      and rollup.provider_model_id is not distinct from grain.provider_model_id
      and rollup.cloudflare_colo is not distinct from grain.cloudflare_colo;

    insert into public.v2_public_usage_hourly (
      bucket_start, app_id, model_slug, provider_model_id, cloudflare_colo,
      requests, successful_requests, failed_requests, rate_limited_requests,
      tool_call_count, tool_call_requests, tool_call_successes,
      structured_output_attempts, structured_output_successes,
      latency_sum_ms, latency_count, generation_sum_ms, generation_count,
      throughput_sum, throughput_count, gateway_total_sum_ms, gateway_total_count,
      internal_dispatch_sum_ms, internal_dispatch_count,
      upstream_attempts, failed_upstream_attempts, cached_input_tokens, input_tokens, cost_nanos
    )
    select
      grain.bucket_start, grain.app_id, grain.model_slug, grain.provider_model_id, grain.cloudflare_colo,
      count(*), count(*) filter (where fact.success), count(*) filter (where not fact.success),
      count(*) filter (where fact.status_code = 429),
      coalesce(sum(fact.tool_call_count), 0),
      count(*) filter (where fact.tool_call_count > 0),
      count(*) filter (where fact.tool_call_count > 0 and fact.tool_call_succeeded is true),
      count(*) filter (where fact.structured_output_attempted),
      count(*) filter (where fact.structured_output_attempted and fact.structured_output_succeeded),
      coalesce(sum(fact.latency_ms), 0), count(fact.latency_ms),
      coalesce(sum(fact.generation_ms), 0), count(fact.generation_ms),
      coalesce(sum(fact.throughput), 0), count(fact.throughput),
      coalesce(sum(fact.gateway_total_ms), 0), count(fact.gateway_total_ms),
      coalesce(sum(fact.internal_dispatch_ms), 0), count(fact.internal_dispatch_ms),
      coalesce(sum(attempts.attempts), 0), coalesce(sum(attempts.failed_attempts), 0),
      coalesce(sum(usage.cached_input_tokens), 0), coalesce(sum(usage.input_tokens), 0),
      coalesce(sum(fact.cost_nanos), 0)
    from public.reporting_request_facts fact
    left join lateral (
      select count(*)::bigint as attempts,
        count(*) filter (where not attempt.success)::bigint as failed_attempts
      from public.v2_request_attempts attempt
      where attempt.request_event_id = fact.request_event_id
    ) attempts on true
    left join lateral (
      select
        coalesce(sum(meter.quantity) filter (where meter.meter_key = 'cached_input_tokens'), 0) as cached_input_tokens,
        coalesce(sum(meter.quantity) filter (where meter.meter_key = 'input_tokens'), 0) as input_tokens
      from public.v2_request_usage meter
      where meter.request_event_id = fact.request_event_id
    ) usage on true
    where fact.occurred_at >= grain.bucket_start
      and fact.occurred_at < grain.bucket_start + interval '1 hour'
      and fact.app_id is not distinct from grain.app_id
      and coalesce(fact.routed_model_slug, fact.requested_model_slug) = grain.model_slug
      and fact.provider_model_id is not distinct from grain.provider_model_id
      and fact.cloudflare_colo is not distinct from grain.cloudflare_colo
    having count(*) > 0
    returning rollup_id into v_rollup_id;

    insert into public.v2_public_usage_hourly_meters (
      rollup_id, meter_key, modality, unit, quantity
    )
    select v_rollup_id, meter.meter_key, meter.modality, meter.unit, sum(meter.quantity)
    from public.v2_request_usage meter
    join public.reporting_request_facts fact on fact.request_event_id = meter.request_event_id
    where fact.occurred_at >= grain.bucket_start
      and fact.occurred_at < grain.bucket_start + interval '1 hour'
      and fact.app_id is not distinct from grain.app_id
      and coalesce(fact.routed_model_slug, fact.requested_model_slug) = grain.model_slug
      and fact.provider_model_id is not distinct from grain.provider_model_id
      and fact.cloudflare_colo is not distinct from grain.cloudflare_colo
    group by meter.meter_key, meter.modality, meter.unit;

    v_public_hourly_grains := v_public_hourly_grains + 1;
  end loop;

  insert into public.v2_rollup_refresh_state (
    rollup_name, bucket_start, last_started_at, last_completed_at, source_watermark, status, error_message, updated_at
  )
  select 'private_daily', date_trunc('day', batch.occurred_at), now(), now(), max(batch.occurred_at), 'complete', null, now()
  from pg_temp.v2_rollup_batch batch
  group by date_trunc('day', batch.occurred_at)
  on conflict (rollup_name, bucket_start) do update set
    last_started_at = excluded.last_started_at,
    last_completed_at = excluded.last_completed_at,
    source_watermark = excluded.source_watermark,
    status = excluded.status,
    error_message = null,
    updated_at = now();

  insert into public.v2_rollup_refresh_state (
    rollup_name, bucket_start, last_started_at, last_completed_at, source_watermark, status, error_message, updated_at
  )
  select 'public_hourly', date_trunc('hour', batch.occurred_at), now(), now(), max(batch.occurred_at), 'complete', null, now()
  from pg_temp.v2_rollup_batch batch
  group by date_trunc('hour', batch.occurred_at)
  on conflict (rollup_name, bucket_start) do update set
    last_started_at = excluded.last_started_at,
    last_completed_at = excluded.last_completed_at,
    source_watermark = excluded.source_watermark,
    status = excluded.status,
    error_message = null,
    updated_at = now();

  update public.v2_analytics_outbox outbox
  set status = 'complete', last_error = null, updated_at = now()
  where outbox.status = 'processing'
    and outbox.request_event_id in (select batch.request_event_id from pg_temp.v2_rollup_batch batch);


  delete from private.v2_analytics_previous_grains
  where grain_id in (select grain_id from pg_temp.v2_previous_grain_batch);
  return jsonb_build_object(
    'selected', v_selected,
    'coalesced', v_coalesced,
    'private_grains', v_private_grains,
    'public_daily_grains', v_public_daily_grains,
    'public_hourly_grains', v_public_hourly_grains,
    'workspace_hours', v_workspace_hours
  );
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."process_v2_analytics_outbox"(integer) TO "service_role";

COMMENT ON FUNCTION "public"."process_v2_analytics_outbox"(integer) IS 'Serializes summary rebuilds, claims a bounded seed batch, and coalesces covered workspace/hour events before idempotent private daily, public daily, public hourly, and usage overview 15-minute rebuilds; the 15-minute and label rollups are rebuilt per touched workspace hour, and rebuilt workspaces with enabled spend rules are marked in workspace_spend_rule_dirty. At most 2000 acknowledgments per run; corrections retain row locks and re-enqueue after commit.';

REVOKE ALL ON FUNCTION "public"."process_v2_analytics_outbox"(integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/promote_provider_catalog_candidate.sql
CREATE OR REPLACE FUNCTION public.promote_provider_catalog_candidate (
  p_run_id               uuid,
  p_submitted_model_slug text
)
  RETURNS text
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  candidate public.provider_catalog_route_candidates%rowtype;
  base_candidate public.provider_catalog_route_candidates%rowtype;
  tier_offer jsonb;
  tier_name text;
  any_route_enabled boolean := false;
  provider_model_id_value text;
  capability jsonb;
  price jsonb;
  sku_id_value uuid;
  sku_version_value integer;
  variant_id_value uuid;
  route_status text;
  provider_availability text;
  phaseo_status_value text;
  access_scope_value text;
  route_enabled boolean;
  release_due boolean;
  provider_approved boolean;
  provider_ready boolean;
  route_blocked boolean := false;
  pricing_changed boolean := true;
  pricing_hash text;
  pricing_operation text;
  sku_code_value text;
begin
  select * into candidate from public.provider_catalog_route_candidates
  where run_id = p_run_id and submitted_model_slug = p_submitted_model_slug for update;
  if not found then raise exception 'provider_catalog_candidate_not_found'; end if;
  select case when p.metadata ? 'self_serve'
    then p.metadata -> 'self_serve' ->> 'provider_review_status' = 'approved'
    else coalesce((select sub.provider_review_status = 'approved'
      from public.provider_onboarding_submissions sub join public.provider_catalog_sources source
        on source.provider_slug = sub.provider_slug and source.created_by = sub.submitted_by
      where source.provider_slug = p.provider_slug order by sub.created_at desc limit 1),
      p.status in ('active', 'beta', 'alpha', 'deprecated')) end,
    coalesce((p.metadata ->> 'adapter_ready')::boolean, false)
      and coalesce((p.metadata ->> 'credentials_ready')::boolean, false)
      and nullif(btrim(p.base_url), '') is not null
    into provider_approved, provider_ready
  from public.v2_providers p where p.provider_slug = candidate.provider_slug for update;
  if not coalesce(provider_approved, false) then raise exception 'provider_catalog_provider_not_approved'; end if;
  if not exists (select 1 from public.provider_catalog_sources s where s.provider_slug = candidate.provider_slug and s.status = 'active') then raise exception 'provider_catalog_source_inactive'; end if;
  if not exists (select 1 from public.v2_models m where m.model_slug = candidate.canonical_model_slug
    and (not m.hidden or (m.metadata ->> 'provider_catalog_owner' = candidate.provider_slug and m.released_at is null))) then raise exception 'provider_catalog_model_unavailable'; end if;
  if candidate.status = 'promoted' then
    select provider_model_id into provider_model_id_value from public.v2_model_provider_routes
    where provider_slug = candidate.provider_slug and model_slug = candidate.canonical_model_slug
      and provider_model_slug = candidate.provider_model_slug order by created_at limit 1;
    return provider_model_id_value;
  end if;
  if candidate.status not in ('pending_probe', 'probe_passed') then raise exception 'provider_catalog_candidate_invalid'; end if;
  if jsonb_array_length(candidate.capabilities) = 0 then raise exception 'provider_catalog_capability_required'; end if;
  base_candidate := candidate;
  for tier_offer in select value from jsonb_array_elements(case when jsonb_array_length(candidate.service_tiers)>0
    then candidate.service_tiers else jsonb_build_array(jsonb_build_object('serviceTier','standard','providerModelSlug',candidate.provider_model_slug,'pricing',candidate.pricing,'availability',candidate.availability)) end)
  loop
  candidate := base_candidate;
  tier_name := tier_offer->>'serviceTier';
  if tier_name not in ('standard','fast','ultrafast','flex','batch') or tier_name is null then raise exception 'provider_catalog_service_tier_invalid'; end if;
  candidate.provider_model_slug := tier_offer->>'providerModelSlug';
  candidate.pricing := coalesce(tier_offer->'pricing','[]'::jsonb);
  candidate.availability := coalesce(tier_offer->>'availability',candidate.availability);
  if exists (
    select 1 from public.provider_catalog_sync_runs newer
    join public.provider_catalog_sync_runs current_run on current_run.id = candidate.run_id
    where newer.provider_slug = candidate.provider_slug and newer.status = 'applied'
      and newer.created_at > current_run.created_at
  ) then raise exception 'provider_catalog_candidate_superseded'; end if;
  if exists (select 1 from jsonb_array_elements(candidate.pricing) p where jsonb_array_length(coalesce(p -> 'conditions', '[]'::jsonb)) > 0) then
    raise exception 'provider_catalog_conditional_pricing_not_supported';
  end if;

  pricing_hash := md5(candidate.pricing::text || coalesce(candidate.available_from::text, '') ||
    coalesce((select string_agg(operation, ',' order by operation) from
      (select distinct public.canonical_routing_capability_id(value ->> 'id') as operation
        from jsonb_array_elements(candidate.capabilities)) operations), ''));
  select route.provider_model_id, route.phaseo_status in ('blocked', 'unsupported'),
      route.metadata ->> 'catalog_pricing_hash' is distinct from pricing_hash
        or exists (select 1 from jsonb_array_elements(candidate.capabilities) cap where not exists (
          select 1 from public.v2_pricing_skus sku where sku.provider_model_id = route.provider_model_id
            and sku.metadata ->> 'managed_by' = 'provider_catalog' and sku.status = 'active'
            and sku.operation = public.canonical_routing_capability_id(cap ->> 'id')))
    into provider_model_id_value, route_blocked, pricing_changed
  from public.v2_model_provider_routes route
  where route.provider_slug = candidate.provider_slug
    and route.model_slug = candidate.canonical_model_slug
    and route.provider_model_slug = candidate.provider_model_slug
    and coalesce(route.metadata->>'catalog_service_tier','standard')=tier_name
  order by route.created_at limit 1 for update of route;
  if provider_model_id_value is null then
    provider_model_id_value := candidate.provider_slug || ':catalog:' || gen_random_uuid()::text;
  end if;

  release_due := (candidate.available_from is null or candidate.available_from <= now())
    and (candidate.shutdown_at is null or candidate.shutdown_at > now());

  route_status := case
    when not release_due and candidate.availability in ('ready', 'degraded') then 'disabled'
    when candidate.availability = 'ready' then 'active'
    when candidate.availability = 'degraded' then 'degraded'
    when candidate.availability = 'retired' then 'disabled'
    else 'disabled'
  end;
  provider_availability := case
    when candidate.availability = 'ready' and release_due then 'available'
    when candidate.availability = 'degraded' and release_due then 'preview'
    when candidate.availability = 'deprecated' then 'deprecated'
    when candidate.availability = 'retired' then 'removed'
    else 'coming_soon'
  end;
  phaseo_status_value := case
    when candidate.availability in ('ready', 'degraded') and release_due then 'enabled'
    when candidate.availability = 'deprecated' then 'disabled'
    when candidate.availability = 'retired' then 'disabled'
    else 'testing'
  end;
  access_scope_value := case when candidate.availability in ('ready', 'degraded') and release_due then 'public' else 'internal' end;
  route_enabled := candidate.availability in ('ready', 'degraded') and release_due and provider_ready and not coalesce(route_blocked, false)
    and jsonb_array_length(candidate.pricing) > 0
    and exists (select 1 from public.v2_models m where m.model_slug = candidate.canonical_model_slug
      and (not m.hidden or (m.metadata ->> 'provider_catalog_owner' = candidate.provider_slug and m.released_at is null)))
    and exists (
      select 1 from public.v2_providers p
      where p.provider_slug = candidate.provider_slug
        and (
          (
            p.metadata ? 'self_serve'
            and p.metadata -> 'self_serve' ->> 'provider_review_status' = 'approved'
            and (p.status = 'not_ready' or (p.status <> 'disabled' and p.routable and p.routing_enabled))
          )
          or (
            not (p.metadata ? 'self_serve')
            and (p.status = 'not_ready' or (p.status <> 'disabled' and p.routable and p.routing_enabled))
          )
        )
    )
    and not exists (select 1 from public.v2_model_provider_routes r
      where r.model_slug = candidate.canonical_model_slug and r.is_stealth);
  any_route_enabled := any_route_enabled or coalesce(route_enabled,false);
  if not route_enabled then
    phaseo_status_value := case when route_blocked then 'blocked' when candidate.available_from > now() then 'testing' else 'planned' end;
    access_scope_value := case when candidate.available_from > now() then 'internal' else 'public' end;
    if route_blocked then route_status := 'disabled'; end if;
  end if;

  insert into public.v2_model_provider_routes (
    provider_model_id, model_slug, provider_slug, provider_model_slug, status,
    routing_enabled, provider_availability_status, phaseo_status, access_scope,
    input_modalities, output_modalities, context_length, max_output_tokens,
    effective_from, effective_to, metadata, updated_at
  ) values (
    provider_model_id_value, candidate.canonical_model_slug, candidate.provider_slug,
    candidate.provider_model_slug, route_status, route_enabled,
    provider_availability, phaseo_status_value, access_scope_value,
    candidate.input_modalities, candidate.output_modalities, candidate.context_length,
    candidate.max_output_tokens, candidate.available_from, candidate.shutdown_at,
    jsonb_build_object(
      'managed_by', 'provider_catalog',
      'source_run_id', candidate.run_id,
      'catalog_pricing_hash', pricing_hash,
      'catalog_service_tier', tier_name,
      'catalog_upstream_service_tier', tier_offer->>'upstreamServiceTier',
      'deprecated_at', candidate.deprecated_at,
      'release_scheduled', candidate.available_from > now() and candidate.availability in ('ready', 'degraded') and not coalesce(route_blocked, false),
      'release_at', candidate.available_from
    ), now()
  )
  on conflict (provider_model_id) do update set
    provider_model_slug = excluded.provider_model_slug, status = excluded.status,
    routing_enabled = excluded.routing_enabled,
    provider_availability_status = excluded.provider_availability_status,
    phaseo_status = excluded.phaseo_status, access_scope = excluded.access_scope,
    input_modalities = excluded.input_modalities, output_modalities = excluded.output_modalities,
    context_length = excluded.context_length, max_output_tokens = excluded.max_output_tokens,
    effective_from = excluded.effective_from, effective_to = excluded.effective_to,
    metadata = public.v2_model_provider_routes.metadata || excluded.metadata, updated_at = now()
  where public.v2_model_provider_routes.provider_slug = excluded.provider_slug
    and public.v2_model_provider_routes.model_slug = excluded.model_slug
    and public.v2_model_provider_routes.provider_model_slug = excluded.provider_model_slug
    and coalesce(public.v2_model_provider_routes.metadata->>'catalog_service_tier','standard') = tier_name
  returning provider_model_id into provider_model_id_value;
  if provider_model_id_value is null then raise exception 'provider_catalog_route_identity_conflict'; end if;

  update public.v2_route_capabilities set status = 'disabled', updated_at = now()
  where provider_model_id = provider_model_id_value
    and capability_id = public.canonical_routing_capability_id(capability_id);

  for capability in
    select jsonb_build_object('id', public.canonical_routing_capability_id(cap.value ->> 'id'),
      'parameters', coalesce(jsonb_agg(distinct param.value) filter (where param.value is not null), '[]'::jsonb))
    from jsonb_array_elements(candidate.capabilities) cap
    left join lateral jsonb_array_elements_text(coalesce(cap.value -> 'parameters', '[]'::jsonb)) param on true
    group by public.canonical_routing_capability_id(cap.value ->> 'id')
  loop
    insert into public.v2_route_capabilities (
      provider_model_id, capability_id, status, max_output_tokens, params,
      effective_from, effective_to, metadata, updated_at
    ) values (
      provider_model_id_value, capability ->> 'id',
      case when route_enabled and candidate.availability = 'ready' then 'active'
           when route_enabled and candidate.availability = 'degraded' then 'degraded'
           when candidate.availability in ('deprecated', 'retired') then 'disabled'
           else 'internal_testing' end,
      candidate.max_output_tokens,
      coalesce((select jsonb_object_agg(p.value, true) from jsonb_array_elements_text(coalesce(capability -> 'parameters', '[]'::jsonb)) as p(value)), '{}'::jsonb)
        || case when tier_offer->>'upstreamServiceTier' is not null then '{"service_tier":true}'::jsonb else '{}'::jsonb end
        || case when jsonb_array_length(base_candidate.service_tiers)>0
          then jsonb_build_object('service_tier', jsonb_build_object('type','string','enum',
            case when tier_name='fast' then '["fast","priority"]'::jsonb
              when tier_name='standard' then '["standard","default"]'::jsonb else jsonb_build_array(tier_name) end,
            'provider_catalog',jsonb_build_object('name',tier_name,'upstream',tier_offer->>'upstreamServiceTier')))
          else '{}'::jsonb end,
      candidate.available_from, candidate.shutdown_at,
      jsonb_build_object('managed_by', 'provider_catalog', 'source_run_id', candidate.run_id), now()
    )
    on conflict (provider_model_id, capability_id) do update set
      status = excluded.status, max_output_tokens = excluded.max_output_tokens,
      params = excluded.params || case
        when jsonb_typeof(public.v2_route_capabilities.metadata->'data_policy') = 'object'
          then jsonb_build_object('data_policy', public.v2_route_capabilities.metadata->'data_policy')
        else '{}'::jsonb end, effective_from = excluded.effective_from,
      effective_to = excluded.effective_to,
      metadata = public.v2_route_capabilities.metadata || excluded.metadata, updated_at = now();
  end loop;

  -- Rich provider claims are retained separately; never enable execution or billing from them.
  update public.v2_model_provider_routes route set metadata=route.metadata || jsonb_build_object(
    'catalog_declarations',jsonb_build_object('status','stored_for_review',
      'model',(select snapshot.metadata->'declarations' from public.provider_catalog_sync_models snapshot
        where snapshot.run_id=candidate.run_id and snapshot.model_slug=candidate.submitted_model_slug),
      'offer',tier_offer->'declarations','sourceRunId',candidate.run_id))
  where route.provider_model_id=provider_model_id_value;

  -- Feed-owned declarations are replaceable, including omission and version downgrade.
  -- Keep the management marker after withdrawal to prevent provider-default Yes fallback.
  -- Offers that have never declared a policy keep inheriting the provider default.
  update public.v2_route_capabilities cap set metadata = cap.metadata || jsonb_build_object(
    'catalog_data_policy', jsonb_build_object('declaration', (
      select value from jsonb_array_elements(coalesce(nullif(tier_offer->'dataPolicy','null'::jsonb)->'capabilities','[]'::jsonb))
      where value->>'id'=cap.capability_id limit 1),
      'sourceRunId',candidate.run_id,'catalogUrl',source.catalog_url,'managementMode',source.management_mode))
  from public.provider_catalog_sources source
  where cap.provider_model_id=provider_model_id_value and source.provider_slug=candidate.provider_slug
    and (nullif(tier_offer->'dataPolicy','null'::jsonb) is not null or cap.metadata ? 'catalog_data_policy');

  insert into public.v2_route_variants (
    provider_model_id, variant_key, service_tier_slug, status,
    routing_enabled, endpoint_label, metadata, updated_at
  ) values (
    provider_model_id_value, 'global:' || tier_name, tier_name,
    case when route_enabled then route_status else 'disabled' end,
    route_enabled, initcap(tier_name),
    jsonb_build_object('managed_by', 'provider_catalog', 'source_run_id', candidate.run_id), now()
  )
  on conflict (provider_model_id, variant_key) do update set
    service_tier_slug = excluded.service_tier_slug,
    status = excluded.status,
    routing_enabled = excluded.routing_enabled,
    endpoint_label = excluded.endpoint_label,
    metadata = public.v2_route_variants.metadata || excluded.metadata,
    updated_at = now()
  returning variant_id into variant_id_value;

  if coalesce(pricing_changed, true) then
  update public.v2_pricing_skus
  set status = case when effective_from >= now() then 'disabled' else 'deprecated' end,
      effective_to = case when effective_from < now() then now() else effective_to end, updated_at = now()
  where provider_model_id = provider_model_id_value
    and status = 'active' and (
      metadata ->> 'managed_by' = 'provider_catalog'
      or (coalesce(service_tier_slug, 'standard') = 'standard' and region is null
        and (operation = 'inference' or operation in (select public.canonical_routing_capability_id(value ->> 'id') from jsonb_array_elements(candidate.capabilities))))
    );
  if jsonb_array_length(candidate.pricing) > 0 then
  for pricing_operation in select distinct public.canonical_routing_capability_id(value ->> 'id') from jsonb_array_elements(candidate.capabilities)
  loop
  sku_code_value := 'provider-catalog-' || pricing_operation;
  select coalesce(max(version), 0) + 1 into sku_version_value
  from public.v2_pricing_skus where provider_model_id = provider_model_id_value and sku_code = sku_code_value;
  insert into public.v2_pricing_skus (
    provider_model_id, route_variant_id, service_tier_slug, sku_code, version, operation, status, display_name,
    currency, effective_from, metadata
  ) values (
    provider_model_id_value, variant_id_value, tier_name, sku_code_value, sku_version_value,
    pricing_operation, 'active', 'Provider catalog pricing', 'USD', greatest(coalesce(candidate.available_from, now()), now()),
    jsonb_build_object('managed_by', 'provider_catalog', 'source_run_id', candidate.run_id, 'release_scheduled', not release_due)
  ) returning sku_id into sku_id_value;
  for price in select value from jsonb_array_elements(candidate.pricing)
  loop
    insert into public.v2_pricing_sku_meters (
      sku_id, meter_key, modality, direction, unit, unit_quantity,
      price_nanos, display_label, display_unit, metadata
    ) values (
      sku_id_value, price ->> 'meterKey', price ->> 'modality', nullif(price ->> 'direction', ''),
      price ->> 'unit', (price ->> 'unitQuantity')::numeric,
      (price ->> 'priceNanos')::numeric, price ->> 'displayLabel', price ->> 'displayUnit',
      jsonb_build_object('managed_by', 'provider_catalog', 'source_run_id', candidate.run_id)
    );
  end loop;
  end loop;
  end if;
  end if;

  update public.v2_providers
  set status = case
        when route_enabled
          and (status = 'not_ready' or (status = 'disabled' and metadata -> 'self_serve' ->> 'status' = 'submitted'))
          then 'beta'
        else status
      end,
      routable = case when route_enabled then true else routable end,
      routing_enabled = case when route_enabled then true else routing_enabled end,
      updated_at = now()
  where provider_slug = candidate.provider_slug;

  if candidate.availability in ('ready', 'degraded') and release_due then
    update public.v2_models
    set hidden = false,
        released_at = coalesce(released_at, coalesce(candidate.available_from, now())),
        updated_at = now()
    where model_slug = candidate.canonical_model_slug
      and metadata ->> 'provider_catalog_owner' = candidate.provider_slug
      and not exists (select 1 from public.v2_model_provider_routes r where r.model_slug = candidate.canonical_model_slug and r.is_stealth);

    update public.v2_labs lab
    set status = case when lab.status = 'disabled' then 'active' else lab.status end,
        updated_at = now()
    where lab.lab_slug = (select model.lab_slug from public.v2_models model where model.model_slug = candidate.canonical_model_slug)
      and lab.metadata ->> 'created_from_provider_proposal' = 'true';
  end if;

  update public.provider_catalog_route_candidates
  set status = 'promoted', promoted_at = now(), updated_at = now()
  where run_id = p_run_id and submitted_model_slug = p_submitted_model_slug;

  update public.provider_catalog_sync_models
  set route_projection_status = case when route_enabled then 'enabled' else 'staged' end,
      route_projection_error = null
  where run_id = p_run_id and model_slug = p_submitted_model_slug;

  end loop;

  update public.provider_catalog_sync_models
  set route_projection_status = case when any_route_enabled then 'enabled' else 'staged' end
  where run_id=p_run_id and model_slug=p_submitted_model_slug;
  return provider_model_id_value;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."promote_provider_catalog_candidate"(uuid, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."promote_provider_catalog_candidate"(uuid, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/protect_data_contribution_settings.sql
CREATE OR REPLACE FUNCTION public.protect_data_contribution_settings()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if current_user in ('anon', 'authenticated') then
    if tg_op = 'INSERT' then
      if new.data_contribution_enabled is distinct from false
        or new.data_contribution_policy_version is not null
        or new.data_contribution_consented_at is not null
        or new.data_contribution_consented_by is not null
        or new.data_contribution_sample_rate_bps is distinct from 10000
        or new.data_contribution_classifier_sample_rate_bps is distinct from 1000
        or new.data_contribution_discount_bps is distinct from 100 then
        raise exception 'data contribution settings are platform controlled'
          using errcode = '42501';
      end if;
    elsif new.data_contribution_enabled is distinct from old.data_contribution_enabled
      or new.data_contribution_policy_version is distinct from old.data_contribution_policy_version
      or new.data_contribution_consented_at is distinct from old.data_contribution_consented_at
      or new.data_contribution_consented_by is distinct from old.data_contribution_consented_by
      or new.data_contribution_sample_rate_bps is distinct from old.data_contribution_sample_rate_bps
      or new.data_contribution_classifier_sample_rate_bps is distinct from old.data_contribution_classifier_sample_rate_bps
      or new.data_contribution_discount_bps is distinct from old.data_contribution_discount_bps then
      raise exception 'data contribution settings are platform controlled'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."protect_data_contribution_settings"() TO "service_role";

COMMENT ON FUNCTION "public"."protect_data_contribution_settings"() IS 'Prevents authenticated workspace administrators from forging platform-controlled contribution consent and billing terms.';

REVOKE ALL ON FUNCTION "public"."protect_data_contribution_settings"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/protect_key_never_store_content.sql
CREATE OR REPLACE FUNCTION public.protect_key_never_store_content()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  -- One-way: a key created to never have its content stored keeps that promise
  -- for every later request, whoever edits the key.
  if old.never_store_content and not new.never_store_content then
    raise exception 'key_never_store_content_locked'
      using errcode = '23514',
        detail = 'This key never has its request or response content stored. Create a new key instead.';
  end if;
  return new;
end;
$function$;

COMMENT ON FUNCTION "public"."protect_key_never_store_content"() IS 'Stops a key''s never_store_content from being turned off once it is on.';

REVOKE ALL ON FUNCTION "public"."protect_key_never_store_content"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/protect_revoked_key_status.sql
CREATE OR REPLACE FUNCTION public.protect_revoked_key_status()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  -- A revoked key was taken out of service because it may be exposed (for
  -- example, a platform it was stored in was breached); a compromised key was
  -- reported as publicly leaked. These and deleted keys are final: they can
  -- move between those states but never become usable again, so revoking then
  -- deleting a key can't be used to bring it back. Rotate it to get a new key.
  if old.status in ('revoked', 'compromised', 'deleted') and new.status not in ('revoked', 'compromised', 'deleted') then
    raise exception 'key_revoked_locked'
      using errcode = '23514',
        detail = 'This key was revoked or deleted and cannot be turned back on. Rotate it or create a new key.';
  end if;
  if new.status = 'revoked' and old.status is distinct from 'revoked' then
    new.revoked_at := coalesce(new.revoked_at, now());
  end if;
  return new;
end;
$function$;

COMMENT ON FUNCTION "public"."protect_revoked_key_status"() IS 'Stops a revoked, compromised or deleted API key from becoming usable again, and stamps revoked_at when a key is revoked.';

REVOKE ALL ON FUNCTION "public"."protect_revoked_key_status"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/protect_slack_agent_guardrail.sql
CREATE OR REPLACE FUNCTION public.protect_slack_agent_guardrail()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  -- Deletes cascading from a deleted key or workspace are allowed: they leave the
  -- installation without a working key, so nothing can run unguarded.
  if tg_op = 'DELETE' and pg_catalog.pg_trigger_depth() > 1 then
    return old;
  end if;

  if tg_table_name = 'workspace_guardrails' then
    -- Renaming or other edits are fine while training and prompt publishing stay off.
    -- Providers that keep logs may serve the agent: they don't train on it, and
    -- Phaseo stores no content for its key (never_store_content).
    if tg_op = 'UPDATE' and new.enabled
      and not new.privacy_enable_paid_may_train and not new.privacy_enable_free_may_train
      and not new.privacy_enable_free_may_publish_prompts then
      return new;
    end if;
    if exists (
      select 1 from public.slack_installations installation
      where installation.guardrail_id = old.id and installation.status <> 'uninstalled'
    ) then
      raise exception 'slack_agent_guardrail_protected'
        using errcode = '23514',
          detail = 'This guardrail keeps Slack data out of training and prompt publishing. Uninstall the Slack agent to change or remove it.';
    end if;
  else
    if tg_op = 'UPDATE' and new.key_id = old.key_id and new.guardrail_id = old.guardrail_id then
      return new;
    end if;
    if exists (
      select 1 from public.slack_installations installation
      where installation.key_id = old.key_id and installation.guardrail_id = old.guardrail_id
        and installation.status <> 'uninstalled'
    ) then
      raise exception 'slack_agent_guardrail_protected'
        using errcode = '23514',
          detail = 'This guardrail keeps Slack data out of training and prompt publishing. Uninstall the Slack agent to change or remove it.';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$;

COMMENT ON FUNCTION "public"."protect_slack_agent_guardrail"() IS 'Keeps a live Slack agent installation''s privacy guardrail in force: it cannot be deleted, disabled, have training or prompt publishing turned back on, or be detached from the installation''s key until the agent is uninstalled.';

REVOKE ALL ON FUNCTION "public"."protect_slack_agent_guardrail"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/protect_users_global_role.sql
CREATE OR REPLACE FUNCTION public.protect_users_global_role()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'pg_catalog', 'public'
  AS $function$
begin
  if auth.uid() is not null
     and coalesce(auth.role(), '') <> 'service_role'
     and new.role is distinct from old.role then
    raise exception 'users.role is managed by administrators'
      using errcode = '42501';
  end if;
  return new;
end;
$function$;

