-- source: supabase/schemas/public/functions/provider_catalog_field_value.sql
CREATE OR REPLACE FUNCTION public.provider_catalog_field_value(p_model jsonb, p_field text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path TO 'public' AS $function$
declare current_value jsonb := p_model; part text;
begin
  if p_model is null then return null; end if;
  if p_field='$model' then return p_model; end if;
  if p_field='$removed' then return 'false'::jsonb; end if;
  if left(p_field,1) <> '/' then return p_model->p_field; end if;
  foreach part in array string_to_array(substr(p_field,2),'/') loop
    part := replace(replace(part,'~1','/'),'~0','~');
    if part='$rate' then return jsonb_build_object('priceNanos',current_value->'priceNanos','unitQuantity',current_value->'unitQuantity','unit',current_value->'unit','displayUnit',current_value->'displayUnit'); end if;
    if jsonb_typeof(current_value)='array' then
      select value into current_value from jsonb_array_elements(current_value) where coalesce(value->>'meterKey',value->>'serviceTier')=part limit 1;
    else current_value := current_value->part;
    end if;
    if current_value is null then return null; end if;
  end loop;
  return current_value;
end;
$function$;

REVOKE ALL ON FUNCTION public.provider_catalog_field_value(jsonb,text) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.provider_catalog_field_value(jsonb,text) TO service_role;

-- source: supabase/schemas/public/functions/provision_department_from_scim_group.sql
CREATE OR REPLACE FUNCTION public.provision_department_from_scim_group()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  department_row public.workspace_departments;
  selected_color text;
begin
  selected_color := case substring(md5(new.id::text),1,1)
    when '0' then 'blue' when '1' then 'cyan' when '2' then 'emerald'
    when '3' then 'amber' when '4' then 'orange' when '5' then 'rose'
    when '6' then 'violet' when '7' then 'fuchsia' else 'slate' end;

  insert into public.workspace_departments(
    workspace_id,name,icon,color,source_type,source_id,directory_name
  ) values (
    new.workspace_id,new.display_name,'users',selected_color,'scim_group',new.id,new.display_name
  )
  on conflict (workspace_id,source_type,source_id) where source_id is not null
  do update set
    directory_name=excluded.directory_name,
    name=case when public.workspace_departments.name_overridden then public.workspace_departments.name else excluded.directory_name end,
    updated_at=now()
  returning * into department_row;

  insert into public.scim_group_mappings(
    workspace_id,scim_group_id,department_id,access_role,department_position
  ) values (
    new.workspace_id,new.id,department_row.id,'member','member'
  ) on conflict (scim_group_id,department_id) do nothing;

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."provision_department_from_scim_group"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/provision_personal_workspace.sql
CREATE OR REPLACE FUNCTION public.provision_personal_workspace (
  p_user_id      uuid,
  p_display_name text DEFAULT NULL::text
)
  RETURNS TABLE (
    workspace_id      uuid,
    created_workspace boolean
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_display_name text;
  v_default_workspace_id uuid;
  v_existing_workspace_id uuid;
  v_has_access boolean := false;
  v_default_workspace_is_owner boolean := false;
  v_created_workspace boolean := false;
  v_base_slug text;
  v_slug_attempt text;
  v_attempt integer := 0;
begin
  if p_user_id is null then
    raise exception using errcode = '22023', message = 'missing_user_id';
  end if;

  v_display_name := nullif(trim(coalesce(p_display_name, '')), '');
  if v_display_name is null then
    v_display_name := 'User';
  end if;

  insert into public.users (user_id, display_name)
  values (p_user_id, v_display_name)
  on conflict (user_id) do update
    set display_name = coalesce(nullif(excluded.display_name, ''), public.users.display_name);

  select u.default_workspace_id
  into v_default_workspace_id
  from public.users u
  where u.user_id = p_user_id
  limit 1;

  if v_default_workspace_id is not null then
    select exists (
      select 1
      from public.workspace_members wm
      where wm.workspace_id = v_default_workspace_id
        and wm.user_id = p_user_id

      union all

      select 1
      from public.workspaces w
      where w.id = v_default_workspace_id
        and w.owner_user_id = p_user_id
    )
    into v_has_access;

    select exists (
      select 1
      from public.workspaces w
      where w.id = v_default_workspace_id
        and w.owner_user_id = p_user_id
    )
    into v_default_workspace_is_owner;

    if v_has_access then
      if v_default_workspace_is_owner then
        insert into public.workspace_members (workspace_id, user_id, role)
        values (v_default_workspace_id, p_user_id, 'owner')
        on conflict on constraint workspace_members_pkey do nothing;
      end if;

      insert into public.workspace_settings (workspace_id)
      values (v_default_workspace_id)
      on conflict on constraint workspace_settings_pkey do nothing;

      return query
      select v_default_workspace_id, false;
      return;
    end if;

    update public.users
    set default_workspace_id = null
    where user_id = p_user_id
      and default_workspace_id = v_default_workspace_id;
  end if;

  select w.id
  into v_existing_workspace_id
  from public.workspaces w
  where w.owner_user_id = p_user_id
  order by w.created_at asc
  limit 1;

  if v_existing_workspace_id is null then
    v_base_slug := regexp_replace(lower(v_display_name), '[^a-z0-9]+', '-', 'g');
    v_base_slug := regexp_replace(v_base_slug, '^-+|-+$', '', 'g');
    if v_base_slug = '' then
      v_base_slug := 'user';
    end if;

    -- The public handle format allows 40 characters and '-personal' uses 9.
    v_base_slug := left(v_base_slug, 40 - length('-personal'));
    v_slug_attempt := v_base_slug || '-personal';

    while v_attempt < 8 and v_existing_workspace_id is null loop
      begin
        insert into public.workspaces (name, slug, owner_user_id)
        values ('Personal', v_slug_attempt, p_user_id)
        returning id into v_existing_workspace_id;

        v_created_workspace := true;
      exception
        when unique_violation then
          v_attempt := v_attempt + 1;
          -- Keep the retry suffix before '-personal' so the trigger cannot
          -- truncate away the uniqueness component.
          v_slug_attempt :=
            left(v_base_slug, 40 - length('-personal') - 1 - 8)
            || '-' || substring(md5(gen_random_uuid()::text), 1, 8)
            || '-personal';
      end;
    end loop;

    if v_existing_workspace_id is null then
      select w.id
      into v_existing_workspace_id
      from public.workspaces w
      where w.owner_user_id = p_user_id
      order by w.created_at asc
      limit 1;
    end if;
  end if;

  if v_existing_workspace_id is null then
    raise exception using errcode = 'P0001', message = 'personal_workspace_provision_failed';
  end if;

  insert into public.workspace_members (workspace_id, user_id, role)
  values (v_existing_workspace_id, p_user_id, 'owner')
  on conflict on constraint workspace_members_pkey do nothing;

  insert into public.workspace_settings (workspace_id)
  values (v_existing_workspace_id)
  on conflict on constraint workspace_settings_pkey do nothing;

  update public.users
  set default_workspace_id = v_existing_workspace_id
  where user_id = p_user_id;

  return query
  select v_existing_workspace_id, v_created_workspace;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."provision_personal_workspace"(uuid, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."provision_personal_workspace"(uuid, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/prune_broadcast_destination_delivery_hourly.sql
CREATE OR REPLACE FUNCTION public.prune_broadcast_destination_delivery_hourly (
  p_limit integer DEFAULT 5000
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  SET statement_timeout TO '10s'
  SET lock_timeout TO '500ms'
  AS $function$
declare
  v_deleted integer;
begin
  -- The dashboard shows the last day; a week is kept for alerts and trends.
  with expired as (
    select destination_id, hour
    from public.broadcast_destination_delivery_hourly
    where hour < now() - interval '8 days'
    order by hour
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 5000), 5000))
  )
  delete from public.broadcast_destination_delivery_hourly hourly
  using expired
  where hourly.destination_id = expired.destination_id
    and hourly.hour = expired.hour;
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."prune_broadcast_destination_delivery_hourly"(integer) TO "service_role";

COMMENT ON FUNCTION "public"."prune_broadcast_destination_delivery_hourly"(integer) IS 'Deletes a bounded batch of Broadcast hourly delivery counts older than eight days.';

REVOKE ALL ON FUNCTION "public"."prune_broadcast_destination_delivery_hourly"(integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/prune_broadcast_event_receipts.sql
CREATE OR REPLACE FUNCTION public.prune_broadcast_event_receipts (
  p_limit integer DEFAULT 5000
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  SET statement_timeout TO '10s'
  SET lock_timeout TO '500ms'
  AS $function$
declare
  v_deleted integer;
begin
  -- Repeat emissions arrive within minutes. Five days outlasts the queue's
  -- default four-day message retention, so no queued message outlives its receipt.
  with expired as (
    select event_id
    from public.broadcast_event_receipts
    where received_at < now() - interval '5 days'
    order by received_at
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 5000), 5000))
  )
  delete from public.broadcast_event_receipts receipts
  using expired
  where receipts.event_id = expired.event_id;
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."prune_broadcast_event_receipts"(integer) TO "service_role";

COMMENT ON FUNCTION "public"."prune_broadcast_event_receipts"(integer) IS 'Deletes a bounded batch of Broadcast event receipts older than five days.';

REVOKE ALL ON FUNCTION "public"."prune_broadcast_event_receipts"(integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/prune_byok_request_metadata.sql
CREATE OR REPLACE FUNCTION public.prune_byok_request_metadata (
  p_retention_days integer DEFAULT 90,
  p_batch_size     integer DEFAULT 10000
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if p_retention_days is null or p_retention_days < 90 or p_retention_days > 3650
    or p_batch_size is null or p_batch_size < 1 or p_batch_size > 50000 then
    raise exception 'Invalid BYOK metadata prune parameters';
  end if;
  return jsonb_build_object('cutoff', now() - make_interval(days => p_retention_days),
    'v2_deleted', 0, 'legacy_deleted', 0, 'retention_policy', 'permanent_usage');
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."prune_byok_request_metadata"(integer, integer) TO "service_role";

COMMENT ON FUNCTION "public"."prune_byok_request_metadata"(integer, integer) IS 'Compatibility no-op: gateway and normalized usage records are retained permanently.';

REVOKE ALL ON FUNCTION "public"."prune_byok_request_metadata"(integer, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/prune_otel_export_outbox.sql
CREATE OR REPLACE FUNCTION public.prune_otel_export_outbox (
  p_limit integer DEFAULT 5000
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  SET statement_timeout TO '10s'
  SET lock_timeout TO '500ms'
  AS $function$
declare
  v_deleted integer;
begin
  -- Delivered rows only back the (destination_id, event_id) dedupe on enqueue,
  -- so they are kept for a day. Failed rows keep their last error for a week,
  -- and rows still pending after a week are past any useful delivery window.
  with expired as (
    select id
    from public.otel_export_outbox
    where created_at < now() - interval '1 day'
      and (status = 'delivered' or created_at < now() - interval '7 days')
    order by created_at
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 5000), 5000))
  )
  delete from public.otel_export_outbox outbox
  using expired
  where outbox.id = expired.id;
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."prune_otel_export_outbox"(integer) TO "service_role";

COMMENT ON FUNCTION "public"."prune_otel_export_outbox"(integer) IS 'Deletes a bounded batch of expired Broadcast export outbox rows: delivered after one day, everything else after seven days.';

REVOKE ALL ON FUNCTION "public"."prune_otel_export_outbox"(integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/public_leaderboard_model_id.sql
CREATE OR REPLACE FUNCTION public.public_leaderboard_model_id (
  p_canonical_model_id text,
  p_model_id           text,
  p_requested_model_id text,
  p_routed_model_id    text,
  p_api_model_id       text,
  p_provider           text,
  p_pricing_plan       text,
  p_is_free_variant    boolean
)
  RETURNS text
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select case
    when coalesce(p_is_free_variant, false)
      or lower(coalesce(p_pricing_plan, '')) = 'free'
      or lower(coalesce(p_api_model_id, '')) like '%:free'
      or lower(coalesce(p_routed_model_id, '')) like '%:free'
      or lower(coalesce(p_model_id, '')) like '%:free'
      or lower(coalesce(p_requested_model_id, '')) like '%:free'
      or lower(coalesce(p_canonical_model_id, '')) like '%:free'
    then coalesce(
      nullif(p_api_model_id, ''),
      nullif(p_routed_model_id, ''),
      nullif(p_model_id, ''),
      nullif(p_requested_model_id, ''),
      nullif(p_canonical_model_id, ''),
      public.resolve_public_model_id(p_model_id, p_provider),
      'unknown'
    )
    else coalesce(
      nullif(p_canonical_model_id, ''),
      public.resolve_public_model_id(p_model_id, p_provider),
      nullif(p_routed_model_id, ''),
      nullif(p_requested_model_id, ''),
      nullif(p_api_model_id, ''),
      nullif(p_model_id, ''),
      'unknown'
    )
  end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."public_leaderboard_model_id"(text, text, text, text, text, text, text, boolean) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."public_leaderboard_model_id"(text, text, text, text, text, text, text, boolean) TO "service_role";

COMMENT ON FUNCTION "public"."public_leaderboard_model_id"(text, text, text, text, text, text, text, boolean) IS 'Returns the model id used for public leaderboard aggregation, preserving free executed variants while keeping paid rows canonical.';

-- source: supabase/schemas/public/functions/public_ranking_metric_value.sql
create or replace function public.public_ranking_metric_value(p_metric text, meters jsonb)
returns numeric
language sql immutable security invoker set search_path = ''
as $$
  select case p_metric
    when 'tokens' then coalesce((meters->>'total_tokens')::numeric,
      case when meters ? 'input_tokens' or meters ? 'output_tokens'
        then coalesce((meters->>'input_tokens')::numeric, 0) + coalesce((meters->>'output_tokens')::numeric, 0)
        else coalesce((meters->>'input_text_tokens')::numeric, 0) + coalesce((meters->>'output_text_tokens')::numeric, 0) end)
    when 'text_tokens' then coalesce((meters->>'input_text_tokens')::numeric, 0) + coalesce((meters->>'output_text_tokens')::numeric, 0)
    when 'image_inputs' then coalesce((meters->>'image_inputs')::numeric, (meters->>'input_images')::numeric, 0)
    when 'image_outputs' then coalesce((meters->>'image_outputs')::numeric, (meters->>'output_images')::numeric, 0)
    when 'audio_tokens' then coalesce((meters->>'input_audio_tokens')::numeric, 0) + coalesce((meters->>'output_audio_tokens')::numeric, 0)
    when 'audio_seconds' then coalesce((meters->>'audio_seconds')::numeric, 0)
    when 'speech_seconds' then coalesce((meters->>'speech_seconds')::numeric, 0)
    when 'transcription_seconds' then coalesce((meters->>'transcription_seconds')::numeric, 0)
    when 'video_tokens' then coalesce((meters->>'input_video_tokens')::numeric, 0) + coalesce((meters->>'output_video_tokens')::numeric, 0)
    when 'video_seconds' then coalesce((meters->>'video_seconds')::numeric, (meters->>'output_video_seconds')::numeric, 0)
    when 'cached_tokens' then coalesce((meters->>'cached_read_tokens')::numeric, (meters->>'cached_input_tokens')::numeric, 0) + coalesce((meters->>'cached_write_tokens')::numeric, (meters->>'cache_write_tokens')::numeric, 0)
    when 'embedding_tokens' then coalesce((meters->>'embedding_tokens')::numeric, 0)
    when 'rerank_quad_tokens' then coalesce((meters->>'rerank_quad_tokens')::numeric, 0)
    else 0
  end;
$$;

revoke all on function public.public_ranking_metric_value(text, jsonb) from public;

grant execute on function public.public_ranking_metric_value(text, jsonb) to service_role;

-- source: supabase/schemas/public/functions/public_reporting_route_is_visible.sql
CREATE OR REPLACE FUNCTION public.public_reporting_route_is_visible (
  p_model_slug        text,
  p_provider_model_id text                     DEFAULT NULL::text,
  p_provider_slug     text                     DEFAULT NULL::text,
  p_occurred_at       timestamp with time zone DEFAULT now()
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from public.v2_models model
    join public.v2_model_provider_routes route on route.model_slug = model.model_slug
    where model.model_slug = p_model_slug
      and model.hidden = false
      and model.status not in ('disabled', 'not_ready', 'coming_soon', 'testing', 'draft', 'pending')
      and (model.released_at is null or model.released_at <= p_occurred_at)
      and route.access_scope = 'public'
      and route.phaseo_status = 'enabled'
      and route.routing_enabled = true
      and route.status in ('active', 'degraded')
      and route.is_stealth = false
      and route.provider_availability_status in ('available', 'preview', 'limited_access')
      and (p_provider_model_id is null or route.provider_model_id = p_provider_model_id)
      and (p_provider_slug is null or route.provider_slug = p_provider_slug)
      and (route.effective_from is null or route.effective_from <= p_occurred_at)
      and (route.effective_to is null or route.effective_to > p_occurred_at)
  );
$function$;

revoke all on function public.public_reporting_route_is_visible(text,text,text,timestamptz) from public;

grant execute on function public.public_reporting_route_is_visible(text,text,text,timestamptz) to anon, authenticated, service_role;

-- source: supabase/schemas/public/functions/publish_artificial_analysis_public_snapshot.sql
CREATE OR REPLACE FUNCTION public.publish_artificial_analysis_public_snapshot(p_snapshot jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path = ''
AS $function$
DECLARE
  saved_id uuid;
  fetched timestamptz := (p_snapshot->>'fetchedAt')::timestamptz;
  version text := p_snapshot->'methodologyVersions'->>0;
  snapshot_hash text := p_snapshot->>'contentHash';
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('artificial-analysis-public-data', 0));
  IF p_snapshot->>'coverage' IS DISTINCT FROM 'full_frontend_dataset'
    OR p_snapshot->>'sourceUrl' IS DISTINCT FROM 'https://artificialanalysis.ai/models'
    OR coalesce(p_snapshot->>'dataUrl', '') !~ '^https://artificialanalysis\.ai/data/[a-f0-9]+\.txt$'
    OR coalesce(snapshot_hash, '') !~ '^[a-f0-9]{64}$'
    OR coalesce(version, '') !~ '^[1-9][0-9]*\.[0-9]+(\.[0-9]+)?$'
    OR jsonb_array_length(p_snapshot->'methodologyVersions') IS DISTINCT FROM 1
    OR fetched IS NULL OR fetched > now() + interval '5 minutes'
    OR jsonb_typeof(p_snapshot->'models') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_snapshot->'matching'->'sources') IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'Invalid full Artificial Analysis public snapshot'; END IF;
  IF jsonb_array_length(p_snapshot->'models') NOT BETWEEN 1 AND 10000
    OR jsonb_array_length(p_snapshot->'matching'->'sources') <> jsonb_array_length(p_snapshot->'models')
    OR pg_column_size(p_snapshot) > 50000000
  THEN RAISE EXCEPTION 'Empty, incomplete or oversized public snapshot'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_snapshot->'models') m
    WHERE coalesce(m->>'id', '') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
      OR coalesce(m->>'slug', '') !~ '^[a-zA-Z0-9._-]+$'
      OR coalesce(m->>'name', '') = ''
      OR jsonb_typeof(m->'sourceData') IS DISTINCT FROM 'object'
  ) OR (SELECT count(DISTINCT m->>'id') FROM jsonb_array_elements(p_snapshot->'models') m) <> jsonb_array_length(p_snapshot->'models')
  THEN RAISE EXCEPTION 'Invalid or duplicate source identities'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_snapshot->'matching'->'sources') owner
    LEFT JOIN public.v2_models model ON model.model_slug = owner->>'model_id'
    WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_snapshot->'models') m WHERE m->>'id' = owner->>'id')
      OR (owner->>'model_id' IS NOT NULL AND model.model_slug IS NULL)
  ) OR (SELECT count(DISTINCT owner->>'id') FROM jsonb_array_elements(p_snapshot->'matching'->'sources') owner) <> jsonb_array_length(p_snapshot->'models')
  THEN RAISE EXCEPTION 'Invalid source ownership'; END IF;
  SELECT snapshot_id INTO saved_id FROM public.artificial_analysis_public_snapshots s WHERE s.content_hash = snapshot_hash;
  IF FOUND THEN
    IF (SELECT payload - 'fetchedAt' - 'extractedAt' - 'contentHash' - 'matching' - 'pageSha256' FROM public.artificial_analysis_public_snapshots WHERE snapshot_id = saved_id)
      IS DISTINCT FROM (p_snapshot - 'fetchedAt' - 'extractedAt' - 'contentHash' - 'matching' - 'pageSha256')
      OR (SELECT payload->'matching'->'sources' FROM public.artificial_analysis_public_snapshots WHERE snapshot_id = saved_id) IS DISTINCT FROM p_snapshot->'matching'->'sources'
    THEN RAISE EXCEPTION 'Public snapshot hash reused with different content'; END IF;
    RETURN saved_id;
  END IF;
  IF EXISTS (SELECT 1 FROM public.artificial_analysis_public_snapshots s WHERE s.fetched_at >= fetched
    OR string_to_array(s.methodology_version, '.')::integer[] > string_to_array(version, '.')::integer[])
  THEN RAISE EXCEPTION 'Stale public snapshot or methodology downgrade'; END IF;
  INSERT INTO public.artificial_analysis_public_snapshots (major_version, methodology_version, fetched_at, content_hash, payload)
  VALUES (split_part(version, '.', 1)::integer, version, fetched, snapshot_hash, p_snapshot)
  RETURNING snapshot_id INTO saved_id;
  RETURN saved_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.publish_artificial_analysis_public_snapshot(jsonb) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.publish_artificial_analysis_public_snapshot(jsonb) TO service_role;

-- source: supabase/schemas/public/functions/publish_artificial_analysis_snapshot.sql
CREATE OR REPLACE FUNCTION public.publish_artificial_analysis_snapshot(p_snapshot jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path = ''
AS $function$
DECLARE
  snapshot_uuid uuid := (p_snapshot->>'snapshot_id')::uuid;
  major integer := (p_snapshot->>'major_version')::integer;
  fetched timestamptz := (p_snapshot->>'fetched_at')::timestamptz;
  expected_ids text[];
  managed_ids text[];
  previous_payload jsonb;
BEGIN
  -- Serialize publishers; failures roll back the snapshot and compatibility rows together.
  PERFORM pg_advisory_xact_lock(hashtextextended('artificial-analysis-publication', 0));
  SELECT payload INTO previous_payload FROM public.artificial_analysis_snapshots WHERE snapshot_id = snapshot_uuid;
  IF FOUND THEN
    IF previous_payload <> p_snapshot THEN RAISE EXCEPTION 'Snapshot identity reused with different content'; END IF;
    RETURN snapshot_uuid;
  END IF;
  IF snapshot_uuid IS NULL OR major IS NULL OR major < 1 OR fetched IS NULL
    OR fetched > now() + interval '5 minutes'
    OR coalesce(p_snapshot->>'methodology_version', '') !~ ('^' || major || '\.[0-9]+(\.[0-9]+)?$')
    OR jsonb_typeof(p_snapshot->'benchmarks') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_snapshot->'results') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_snapshot->'model_slugs') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_snapshot->'source_owners') IS DISTINCT FROM 'object'
  THEN RAISE EXCEPTION 'Invalid Artificial Analysis snapshot'; END IF;
  IF jsonb_array_length(p_snapshot->'results') = 0 OR jsonb_array_length(p_snapshot->'results') > 20000
    OR jsonb_array_length(p_snapshot->'model_slugs') = 0
  THEN RAISE EXCEPTION 'Empty or oversized Artificial Analysis snapshot'; END IF;
  IF EXISTS (SELECT 1 FROM public.artificial_analysis_snapshots WHERE fetched_at >= fetched OR major_version > major
    OR string_to_array(methodology_version, '.')::integer[] > string_to_array(p_snapshot->>'methodology_version', '.')::integer[])
  THEN RAISE EXCEPTION 'Refusing stale Artificial Analysis snapshot'; END IF;
  expected_ids := ARRAY['aa-intelligence-index-v' || major, 'aa-coding-index-v' || major,
    'aa-agentic-index-v' || major, 'aa-intelligence-index-cost-v' || major];
  managed_ids := expected_ids || ARRAY['aa-intelligence-index', 'aa-coding-index', 'aa-agentic-index', 'aa-intelligence-index-cost'];
  IF jsonb_array_length(p_snapshot->'benchmarks') <> 4
    OR (SELECT count(DISTINCT b->>'benchmark_id') FROM jsonb_array_elements(p_snapshot->'benchmarks') b WHERE b->>'benchmark_id' = ANY(expected_ids)) <> 4
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_snapshot->'results') r
      WHERE coalesce(r->>'benchmark_id', '') <> ALL(expected_ids)
        OR nullif(r->>'result_id', '') IS NULL OR nullif(r->>'model_slug', '') IS NULL
        OR NOT (p_snapshot->'model_slugs' ? (r->>'model_slug'))
        OR nullif(r->>'result_key', '') IS NULL
        OR nullif(r->>'score_numeric', '') IS NULL
        OR (r->>'score_numeric')::numeric IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric)
        OR (r->>'score')::numeric IS DISTINCT FROM (r->>'score_numeric')::numeric
        OR substring(r->>'other_info' FROM 'Intelligence Index v([0-9]+\.[0-9]+(?:\.[0-9]+)?)') IS DISTINCT FROM p_snapshot->>'methodology_version'
        OR nullif(substring(r->>'other_info' FROM 'Artificial Analysis ID ([^;]+)'), '') IS NULL
        OR p_snapshot->'source_owners'->>substring(r->>'other_info' FROM 'Artificial Analysis ID ([^;]+)') IS DISTINCT FROM r->>'model_slug')
    OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_snapshot->'results') r WHERE r->>'benchmark_id' = expected_ids[1])
  THEN RAISE EXCEPTION 'Snapshot contains invalid results or benchmark definitions'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_snapshot->'results') r
    JOIN public.v2_benchmark_results old ON old.result_id = (r->>'result_id')::uuid
    WHERE old.model_slug IS DISTINCT FROM r->>'model_slug' OR old.benchmark_id IS DISTINCT FROM r->>'benchmark_id'
      OR old.result_key IS DISTINCT FROM r->>'result_key')
  THEN RAISE EXCEPTION 'Snapshot result identity conflicts with existing catalogue'; END IF;

  INSERT INTO public.artificial_analysis_snapshots(snapshot_id, major_version, methodology_version, fetched_at, payload)
  VALUES(snapshot_uuid, major, p_snapshot->>'methodology_version', fetched, p_snapshot);
  INSERT INTO public.v2_benchmarks(benchmark_id, name, category, ascending_order, benchmark_type, link, total_models, updated_at)
  SELECT b.benchmark_id, b.name, b.category, b.ascending_order, b.benchmark_type, b.link, b.total_models, fetched
  FROM jsonb_to_recordset(p_snapshot->'benchmarks') AS b(benchmark_id text, name text, category text,
    ascending_order boolean, benchmark_type text, link text, total_models integer)
  ON CONFLICT (benchmark_id) DO UPDATE SET name = excluded.name, category = excluded.category,
    ascending_order = excluded.ascending_order, benchmark_type = excluded.benchmark_type,
    link = excluded.link, total_models = excluded.total_models, updated_at = excluded.updated_at;
  INSERT INTO public.v2_benchmark_results(result_id, model_slug, benchmark_id, score, score_numeric,
    is_self_reported, other_info, source_link, rank, occur_idx, variant, result_key, effective_to, updated_at)
  SELECT r.result_id, r.model_slug, r.benchmark_id, r.score, r.score_numeric, false,
    r.other_info, r.source_link, r.rank, r.occur_idx, r.variant, r.result_key, NULL, fetched
  FROM jsonb_to_recordset(p_snapshot->'results') AS r(result_id uuid, model_slug text, benchmark_id text,
    score text, score_numeric numeric, other_info text, source_link text, rank integer, occur_idx integer,
    variant text, result_key text)
  ON CONFLICT (result_id) DO UPDATE SET score = excluded.score, score_numeric = excluded.score_numeric,
    other_info = excluded.other_info, source_link = excluded.source_link, rank = excluded.rank,
    occur_idx = excluded.occur_idx, variant = excluded.variant, effective_to = NULL, updated_at = excluded.updated_at;
  -- Preserve unmatched models and earlier major versions. Retire only matched
  -- replacements and configurations whose source owner has moved to another model.
  WITH incoming_ids AS MATERIALIZED (
    SELECT r.result_id FROM jsonb_to_recordset(p_snapshot->'results') AS r(result_id uuid)
  )
  UPDATE public.v2_benchmark_results old SET effective_to = least(fetched, now()), updated_at = fetched
  WHERE old.effective_to IS NULL AND old.benchmark_id = ANY(managed_ids)
    AND (p_snapshot->'model_slugs' ? old.model_slug
      OR (p_snapshot->'source_owners' ? substring(old.other_info FROM 'Artificial Analysis ID ([^;]+)')
        AND p_snapshot->'source_owners'->>substring(old.other_info FROM 'Artificial Analysis ID ([^;]+)') <> old.model_slug))
    AND NOT EXISTS (SELECT 1 FROM incoming_ids r WHERE r.result_id = old.result_id);
  RETURN snapshot_uuid;
END;
$function$;

REVOKE ALL ON FUNCTION public.publish_artificial_analysis_snapshot(jsonb) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.publish_artificial_analysis_snapshot(jsonb) TO service_role;

-- source: supabase/schemas/public/functions/queue_gateway_billing_alert.sql
CREATE OR REPLACE FUNCTION public.queue_gateway_billing_alert (
  p_alert_id uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  alert public.gateway_billing_alerts%rowtype;
  destination public.notification_destinations%rowtype;
  event_uuid uuid;
begin
  select * into alert from public.gateway_billing_alerts where id = p_alert_id for update;
  if not found or alert.event_id is not null or alert.status <> 'open' then return false; end if;
  select d.* into destination
  from public.gateway_billing_alert_config c
  join public.notification_destinations d on d.id = c.destination_id
  where c.singleton and d.status = 'active' and d.type = 'slack';
  if not found then return false; end if;

  -- email_outbox is the existing notification event store. This event has no
  -- email leg: sent_at closes that legacy drain; Slack delivery has its own status.
  insert into public.email_outbox(kind, template, to_email, subject, workspace_id, dedupe_key, payload, sent_at)
  values ('billing_anomaly', 'notification_only', '', 'Unexpected zero-cost generation',
    destination.workspace_id, 'billing_anomaly:' || alert.id,
    jsonb_build_object(
      'title', 'Unexpected zero-cost generation',
      'message', format('A paid %s job was priced at zero. Workspace: %s. Job: %s. Provider: %s. Review billing and the reservation before releasing credit. Alert: %s.',
        alert.kind, alert.workspace_id, alert.resource_id, coalesce(alert.provider, 'unknown'), alert.id),
      'alert_id', alert.id, 'source_workspace_id', alert.workspace_id,
      'resource_id', alert.resource_id, 'kind', alert.kind, 'reason', alert.reason), now())
  returning id into event_uuid;

  insert into public.notification_routed_events(event_id, workspace_id)
    values(event_uuid, destination.workspace_id);
  insert into public.notification_delivery_attempts(event_id, destination_id, workspace_id)
    values(event_uuid, destination.id, destination.workspace_id);
  update public.gateway_billing_alerts set event_id = event_uuid where id = alert.id;
  return true;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."queue_gateway_billing_alert"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."queue_gateway_billing_alert"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/queue_slack_agent_refusal_email.sql
CREATE OR REPLACE FUNCTION public.queue_slack_agent_refusal_email (
  p_installation_id uuid,
  p_reason          text,
  p_people          integer
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_installation public.slack_installations%rowtype;
  v_month text := to_char(now() at time zone 'UTC', 'YYYY-MM');
  v_queued integer;
begin
  -- Only the refusals that stop the agent for everyone new are emailed. Guests,
  -- Slack Connect users and the hourly limit stay in the audit log.
  if p_reason is null or p_reason not in ('plan_full', 'max_people', 'monthly_cap', 'payment_due') then
    raise exception 'invalid_reason' using errcode = '22023';
  end if;

  select * into v_installation
  from public.slack_installations installation
  where installation.id = p_installation_id;
  if not found or v_installation.status = 'uninstalled' then
    return 0;
  end if;

  -- One email to each owner and admin per installation, reason and UTC month. The
  -- dedupe key turns a repeat (the next refusal, a retried Slack event) into a no-op.
  -- The email names no Slack user and carries no message text.
  with recipient as (
    select workspace.owner_user_id as user_id
    from public.workspaces workspace
    where workspace.id = v_installation.workspace_id
    union
    select member.user_id
    from public.workspace_members member
    where member.workspace_id = v_installation.workspace_id
      and member.role in ('owner', 'admin')
  )
  insert into public.email_outbox (kind, template, to_email, subject, workspace_id, user_id, payload, dedupe_key)
  select
    'slack_agent_refused',
    'slack_agent_refused',
    account.email,
    null,
    v_installation.workspace_id,
    account.id,
    jsonb_build_object(
      'workspace_name', workspace.name,
      'team_name', v_installation.team_name,
      'reason', p_reason,
      'people', greatest(coalesce(p_people, 0), 0),
      'plan_people', v_installation.plan_people,
      'max_people', v_installation.max_people,
      'monthly_cap_usd', round(v_installation.monthly_cap_nanos / 1000000000.0, 2)
    ),
    'slack_agent_refused:' || v_installation.id || ':' || p_reason || ':' || v_month || ':' || account.id
  from recipient
  join auth.users account on account.id = recipient.user_id
  join public.workspaces workspace on workspace.id = v_installation.workspace_id
  where coalesce(account.email, '') <> ''
    and account.deleted_at is null
  on conflict (dedupe_key) do nothing;

  get diagnostics v_queued = row_count;
  return v_queued;
end;
$function$;

COMMENT ON FUNCTION "public"."queue_slack_agent_refusal_email"(uuid, text, integer) IS 'For the Slack Worker when the agent turns someone away because the plan is full, the monthly people limit or spending cap is reached, or a charge is unpaid: queues one slack_agent_refused email to each workspace owner and admin, at most once per installation, reason and UTC month. Returns how many emails were queued.';

GRANT EXECUTE ON FUNCTION "public"."queue_slack_agent_refusal_email"(uuid, text, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."queue_slack_agent_refusal_email"(uuid, text, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/queue_spend_reports.sql
CREATE OR REPLACE FUNCTION public.queue_spend_reports (
  p_now   timestamp with time zone DEFAULT now(),
  p_limit integer                  DEFAULT 50
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Queues the spend reports that are due at p_now. A workspace's report is due from 09:00 to 21:00
-- in its billing_time_zone on the first day after each period (private.spend_report_period):
-- daily for the day before, weekly on Monday for the previous ISO week, monthly on the 1st for the
-- previous month; spend_report_cadence 'off' sends none. Each workspace, cadence and period is
-- handled once (workspace_spend_report_runs):
--   1. Due workspaces with no spend in the rollup and no usage still waiting in the analytics
--      outbox for the period are recorded as skipped in one statement, without computing a report.
--   2. Up to p_limit of the rest get private.spend_report_facts. A report whose total spend is 0
--      (free models only) is skipped too. Otherwise it queues, in email_outbox:
--      * one routed spend_report event (the workspace's spend_report routes, delivered by the
--        notification delivery job), dedupe key spend_report:<workspace>:<cadence>:<period start>;
--      * one spend_report_email per recipient (the legacy email drain sends these): the owner and
--        every member with the owner role, plus admins when spend_report_include_admins is on,
--        less anyone who unsubscribed (workspace_spend_report_recipients.opted_out_at), dedupe key
--        <event key>:email:<user id>. Each payload carries that person's unsubscribe token.
--      Every insert is ON CONFLICT (dedupe_key) DO NOTHING, so a retry or a re-run never sends a
--      report twice.
-- One call at a time (advisory lock); a concurrent call returns skipped_locked. Runs behind
-- SPEND_REPORTS_ENABLED. Service role only.
declare
  v_lock boolean;
  v_skipped_quiet integer := 0;
  v_skipped_zero integer := 0;
  v_queued integer := 0;
  v_emails integer := 0;
  v_due integer := 0;
  v_reports jsonb := '[]'::jsonb;
  v_candidate record;
  v_facts jsonb;
  v_key text;
  v_event_id uuid;
  v_owner_email text;
  v_recipients integer;
begin
  if p_now is null then
    raise exception 'invalid_spend_report_time' using errcode = '22023';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception 'invalid_spend_report_limit' using errcode = '22023';
  end if;

  v_lock := pg_try_advisory_xact_lock(hashtextextended('public.queue_spend_reports', 0));
  if not v_lock then
    return jsonb_build_object('skipped_locked', true, 'due', 0, 'quiet', 0, 'zero_spend', 0, 'queued', 0, 'emails', 0, 'reports', '[]'::jsonb);
  end if;

  -- 1. Quiet workspaces: nothing in the rollup and nothing waiting to be rolled up.
  with due as (
    select candidate.*
    from private.spend_report_due_workspaces(p_now) candidate
  ),
  quiet as (
    insert into public.workspace_spend_report_runs as run (workspace_id, cadence, period_start, period_end, status, spend_nanos, recipients, event_id)
    select due.workspace_id, due.cadence, due.period_start, due.period_end, 'skipped', 0, 0, null
    from due
    where not exists (
        select 1 from public.v2_private_usage_15m rollup
        where rollup.workspace_id = due.workspace_id
          and rollup.bucket_start >= due.period_start
          and rollup.bucket_start < due.period_end
          and rollup.cost_nanos > 0
      )
      and not exists (
        select 1 from public.v2_analytics_outbox outbox
        where outbox.workspace_id = due.workspace_id
          and outbox.status in ('pending', 'failed')
          and outbox.occurred_at >= due.period_start
          and outbox.occurred_at < due.period_end
      )
      and not exists (
        -- gateway_requests_async_spend_idx: async jobs count toward departments and members.
        select 1 from public.gateway_requests request
        where request.success is true
          and request.endpoint = any (array['video.generation', 'batch', 'music.generate', 'audio.realtime'])
          and request.workspace_id = due.workspace_id
          and request.created_at >= due.period_start
          and request.created_at < due.period_end
          and request.cost_nanos > 0
      )
    on conflict (workspace_id, cadence) do update
      set period_start = excluded.period_start, period_end = excluded.period_end, status = 'skipped',
        spend_nanos = 0, recipients = 0, event_id = null, updated_at = now()
      where run.period_start < excluded.period_start
    returning 1
  )
  select count(*) into v_skipped_quiet from quiet;

  -- 2. The rest, oldest period first, then the workspaces whose last handled period is oldest (or
  --    that have none). A backlog bigger than one due window starts next time with the workspaces
  --    it missed, instead of the same lowest workspace ids again.
  for v_candidate in
    select candidate.*
    from private.spend_report_due_workspaces(p_now) candidate
    left join public.workspace_spend_report_runs last_run
      on last_run.workspace_id = candidate.workspace_id and last_run.cadence = candidate.cadence
    order by candidate.period_start, last_run.period_start nulls first, candidate.workspace_id
    limit p_limit
  loop
    v_due := v_due + 1;
    v_facts := private.spend_report_facts(v_candidate.workspace_id, v_candidate.cadence, p_now);

    if v_facts is null or coalesce((v_facts #>> '{totals,spend_nanos}')::numeric, 0) <= 0 then
      insert into public.workspace_spend_report_runs as run (workspace_id, cadence, period_start, period_end, status, spend_nanos, recipients, event_id)
      values (v_candidate.workspace_id, v_candidate.cadence, v_candidate.period_start, v_candidate.period_end, 'skipped', 0, 0, null)
      on conflict (workspace_id, cadence) do update
        set period_start = excluded.period_start, period_end = excluded.period_end, status = 'skipped',
          spend_nanos = 0, recipients = 0, event_id = null, updated_at = now();
      v_skipped_zero := v_skipped_zero + 1;
      continue;
    end if;

    v_key := 'spend_report:' || v_candidate.workspace_id || ':' || v_candidate.cadence || ':'
      || to_char(v_candidate.period_start at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

    select nullif(btrim(account.email), '') into v_owner_email
    from auth.users account where account.id = v_candidate.owner_user_id;

    v_event_id := null;
    insert into public.email_outbox (kind, template, to_email, subject, workspace_id, user_id, payload, dedupe_key)
    values ('spend_report', 'spend_report', coalesce(v_owner_email, ''), v_facts ->> 'title', v_candidate.workspace_id,
      v_candidate.owner_user_id, v_facts, v_key)
    on conflict (dedupe_key) do nothing
    returning id into v_event_id;

    -- Recipients get a stable unsubscribe token the first time they are emailed.
    insert into public.workspace_spend_report_recipients (workspace_id, user_id)
    select v_candidate.workspace_id, person.user_id
    from private.spend_report_people(v_candidate.workspace_id, v_candidate.include_admins) person
    on conflict (workspace_id, user_id) do nothing;

    with sent as (
      insert into public.email_outbox (kind, template, to_email, subject, workspace_id, user_id, payload, dedupe_key)
      select 'spend_report_email', 'spend_report', person.email, v_facts ->> 'title', v_candidate.workspace_id, person.user_id,
        v_facts || jsonb_build_object('recipient', jsonb_build_object('user_id', person.user_id, 'role', person.role,
          'unsubscribe_token', recipient.unsubscribe_token)),
        v_key || ':email:' || person.user_id
      from private.spend_report_people(v_candidate.workspace_id, v_candidate.include_admins) person
      join public.workspace_spend_report_recipients recipient
        on recipient.workspace_id = v_candidate.workspace_id and recipient.user_id = person.user_id
      where recipient.opted_out_at is null
        and person.email is not null
      on conflict (dedupe_key) do nothing
      returning 1
    )
    select count(*) into v_recipients from sent;

    insert into public.workspace_spend_report_runs as run (workspace_id, cadence, period_start, period_end, status, spend_nanos, recipients, event_id)
    values (v_candidate.workspace_id, v_candidate.cadence, v_candidate.period_start, v_candidate.period_end, 'queued',
      (v_facts #>> '{totals,spend_nanos}')::numeric, v_recipients, v_event_id)
    on conflict (workspace_id, cadence) do update
      set period_start = excluded.period_start, period_end = excluded.period_end, status = 'queued',
        spend_nanos = excluded.spend_nanos, recipients = excluded.recipients, event_id = coalesce(excluded.event_id, run.event_id),
        updated_at = now();

    v_queued := v_queued + 1;
    v_emails := v_emails + v_recipients;
    v_reports := v_reports || jsonb_build_array(jsonb_build_object(
      'workspace_id', v_candidate.workspace_id, 'cadence', v_candidate.cadence, 'period_start', v_candidate.period_start,
      'event_id', v_event_id, 'dedupe_key', v_key, 'emails', v_recipients,
      'spend_nanos', (v_facts #>> '{totals,spend_nanos}')::numeric));
  end loop;

  return jsonb_build_object(
    'skipped_locked', false,
    'due', v_due + v_skipped_quiet,
    'quiet', v_skipped_quiet,
    'zero_spend', v_skipped_zero,
    'queued', v_queued,
    'emails', v_emails,
    'reports', v_reports
  );
end;
$function$;

COMMENT ON FUNCTION "public"."queue_spend_reports"(timestamp with time zone, integer) IS 'Queues the spend reports due at p_now (09:00 to 21:00 in each workspace''s billing_time_zone on the first day after a daily, weekly or monthly period): one routed spend_report event and one spend_report_email per subscribed owner (and admin when included), skipping periods without spend. Each workspace, cadence and period is handled once; dedupe keys make retries safe. Service role only.';

REVOKE ALL ON FUNCTION "public"."queue_spend_reports"(timestamp with time zone, integer) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."queue_spend_reports"(timestamp with time zone, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."queue_spend_reports"(timestamp with time zone, integer) FROM "anon", "authenticated";

-- source: supabase/schemas/public/functions/queue_v2_catalogue_price_proposal.sql
CREATE OR REPLACE FUNCTION public.queue_v2_catalogue_price_proposal (
  p_provider_model_id text,
  p_sku_code          text,
  p_proposal_id       text,
  p_source_url        text,
  p_sku               jsonb,
  p_expected_sku      jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
begin
  if nullif(p_sku_code,'') is null then raise exception 'price code required'; end if;
  if p_proposal_id is not null and (p_sku is null or p_sku->>'provider_model_id' is distinct from p_provider_model_id or p_sku->>'sku_code' is distinct from p_sku_code) then raise exception 'proposal identity mismatch'; end if;
  perform pg_advisory_xact_lock(hashtextextended('catalogue-proposal:'||p_provider_model_id||':'||p_sku_code,0));
  update public.v2_catalogue_price_proposals set status='superseded',reviewed_at=now()
    where provider_model_id=p_provider_model_id and sku->>'sku_code'=p_sku_code and status='pending' and proposal_id is distinct from p_proposal_id;
  if p_proposal_id is null then return; end if;
  insert into public.v2_catalogue_price_proposals(proposal_id,provider_model_id,source_url,sku,expected_sku)
    values(p_proposal_id,p_provider_model_id,p_source_url,p_sku,p_expected_sku)
    on conflict(proposal_id) do update set status='pending',created_at=now(),reviewed_at=null,reviewed_by=null
      where v2_catalogue_price_proposals.status='superseded';
end $function$;

GRANT EXECUTE ON FUNCTION "public"."queue_v2_catalogue_price_proposal"(text, text, text, text, jsonb, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."queue_v2_catalogue_price_proposal"(text, text, text, text, jsonb, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/reconcile_scim_entitlements_trigger.sql
CREATE OR REPLACE FUNCTION public.reconcile_scim_entitlements_trigger()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if current_setting('phaseo.scim_group_replace',true)='on' then return coalesce(new,old); end if;
  perform public.reconcile_scim_entitlements(coalesce(new.workspace_id,old.workspace_id));
  return coalesce(new,old);
end $function$;

REVOKE ALL ON FUNCTION "public"."reconcile_scim_entitlements_trigger"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/reconcile_scim_entitlements.sql
CREATE OR REPLACE FUNCTION public.reconcile_scim_entitlements (
  p_workspace_id uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  owner_id uuid;
  previous_reconcile_setting text;
begin
  previous_reconcile_setting := current_setting('phaseo.entitlement_reconcile',true);
  select owner_user_id into owner_id from public.workspaces where id=p_workspace_id;
  delete from public.workspace_access_grants where workspace_id=p_workspace_id and source_type='scim_group';
  insert into public.workspace_access_grants(workspace_id,user_id,source_type,source_id,access_role)
  select distinct m.workspace_id,u.auth_user_id,'scim_group',m.id,m.access_role
  from public.scim_group_mappings m join public.scim_group_members gm on gm.group_id=m.scim_group_id and gm.workspace_id=m.workspace_id
  join public.scim_users u on u.id=gm.user_id and u.workspace_id=m.workspace_id
  where m.workspace_id=p_workspace_id and u.active and u.auth_user_id is not null;
  delete from public.workspace_department_grants where workspace_id=p_workspace_id and source_type='scim_group';
  insert into public.workspace_department_grants(workspace_id,user_id,department_id,source_type,source_id,position,is_primary)
  select distinct m.workspace_id,u.auth_user_id,m.department_id,'scim_group',m.id,m.department_position,false
  from public.scim_group_mappings m join public.scim_group_members gm on gm.group_id=m.scim_group_id and gm.workspace_id=m.workspace_id
  join public.scim_users u on u.id=gm.user_id and u.workspace_id=m.workspace_id
  where m.workspace_id=p_workspace_id and u.active and u.auth_user_id is not null;
  update public.workspace_department_grants g set is_primary=true,updated_at=now()
  from public.scim_users u,public.workspace_departments d
  where g.workspace_id=p_workspace_id and g.source_type='scim_group' and g.user_id=u.auth_user_id
    and u.workspace_id=g.workspace_id and u.active and d.id=g.department_id and d.workspace_id=g.workspace_id
    and u.department is not null and d.name_normalized=lower(btrim(u.department));
  perform set_config('phaseo.entitlement_reconcile','on',true);
  insert into public.workspace_members(workspace_id,user_id,role)
  select workspace_id,user_id,(case when bool_or(access_role='owner') then 'owner' when bool_or(access_role='admin') then 'admin' else 'member' end)::public.workspace_role
  from public.workspace_access_grants where workspace_id=p_workspace_id group by workspace_id,user_id
  on conflict(workspace_id,user_id) do update set role=excluded.role;
  delete from public.workspace_members wm where wm.workspace_id=p_workspace_id and wm.user_id<>owner_id
    and not exists(select 1 from public.workspace_access_grants g where g.workspace_id=wm.workspace_id and g.user_id=wm.user_id);
  perform set_config('phaseo.entitlement_reconcile',case when previous_reconcile_setting='on' then 'on' else 'off' end,true);
end $function$;

GRANT EXECUTE ON FUNCTION "public"."reconcile_scim_entitlements"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."reconcile_scim_entitlements"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/record_broadcast_destination_health.sql
CREATE OR REPLACE FUNCTION public.record_broadcast_destination_health (
  p_results jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  SET statement_timeout TO '5s'
  SET lock_timeout TO '1s'
  AS $function$
declare
  v_recorded integer;
begin
  -- One entry per destination from one consumer batch: events delivered and
  -- finally failed, failed requests since the batch's last success, and the
  -- last success and failure. Batches can commit out of order, so the streak
  -- follows request times: a success newer than every stored failure resets it
  -- to the batch's later failures, failures older than the stored success are
  -- ignored, and other failures extend it. The last error is the newest one.
  -- Destinations deleted since delivery are skipped.
  with results as (
    select distinct on (result.destination_id)
      result.destination_id,
      destination.workspace_id,
      greatest(coalesce(result.delivered, 0), 0) as delivered,
      greatest(coalesce(result.failed, 0), 0) as failed,
      greatest(coalesce(result.failures, 0), 0) as failures,
      result.last_success_at,
      result.last_failure_at,
      result.last_http_status,
      left(result.last_error, 500) as last_error
    from jsonb_to_recordset(case when jsonb_typeof(p_results) = 'array' then p_results else '[]'::jsonb end) as result(
      destination_id uuid,
      delivered integer,
      failed integer,
      failures integer,
      last_success_at timestamptz,
      last_failure_at timestamptz,
      last_http_status integer,
      last_error text
    )
    join public.workspace_broadcast_destinations destination on destination.id = result.destination_id
    order by result.destination_id
  ),
  health as (
    insert into public.broadcast_destination_health as health (
      destination_id, workspace_id, last_success_at, last_failure_at, last_http_status, last_error, consecutive_failures, updated_at
    )
    select destination_id, workspace_id, last_success_at, last_failure_at, last_http_status, last_error, failures, now()
    from results
    where last_success_at is not null or last_failure_at is not null
    on conflict (destination_id) do update set
      last_success_at = greatest(health.last_success_at, excluded.last_success_at),
      last_failure_at = greatest(health.last_failure_at, excluded.last_failure_at),
      last_http_status = case
        when excluded.last_failure_at >= coalesce(health.last_failure_at, '-infinity') then excluded.last_http_status
        else health.last_http_status
      end,
      last_error = case
        when excluded.last_failure_at >= coalesce(health.last_failure_at, '-infinity') then excluded.last_error
        else health.last_error
      end,
      consecutive_failures = case
        when excluded.last_success_at > coalesce(health.last_failure_at, '-infinity') then excluded.consecutive_failures
        when excluded.last_failure_at is null or excluded.last_failure_at < coalesce(health.last_success_at, '-infinity') then health.consecutive_failures
        else health.consecutive_failures + excluded.consecutive_failures
      end,
      updated_at = now()
  ),
  hourly as (
    insert into public.broadcast_destination_delivery_hourly as hourly (destination_id, hour, workspace_id, delivered, failed)
    select destination_id, date_trunc('hour', now(), 'UTC'), workspace_id, delivered, failed
    from results
    where delivered > 0 or failed > 0
    on conflict (destination_id, hour) do update set
      delivered = hourly.delivered + excluded.delivered,
      failed = hourly.failed + excluded.failed
  )
  select count(*) into v_recorded from results;
  return v_recorded;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."record_broadcast_destination_health"(jsonb) TO "service_role";

COMMENT ON FUNCTION "public"."record_broadcast_destination_health"(jsonb) IS 'Records one Broadcast consumer batch''s delivery outcomes per destination: the latest success and failure, the failure streak, and hourly delivered and failed event counts.';

REVOKE ALL ON FUNCTION "public"."record_broadcast_destination_health"(jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/record_credit_topup_payment.sql
CREATE OR REPLACE FUNCTION public.record_credit_topup_payment (
  p_request_id        uuid,
  p_workspace_id      uuid,
  p_payment_intent_id text,
  p_outcome           text,
  p_reason            text DEFAULT NULL::text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Records the Stripe outcome of a credit top-up request. A request belongs to one
-- PaymentIntent: the first one recorded wins and any other is refused (false).
-- paid is final and may follow any other status, since money was taken (a Checkout
-- payment can land after the request expired). failed only follows pending or confirmed.
-- Repeating the same outcome for the same PaymentIntent returns true without changes.
-- Crediting is separate: the webhook credits each PaymentIntent once
-- (public.stripe_apply_payment_intent_credit).
declare
  v_request public.credit_topup_requests%rowtype;
begin
  if p_request_id is null or p_workspace_id is null or p_payment_intent_id is null
    or p_outcome is null or p_outcome not in ('paid', 'failed') then
    raise exception 'credit_topup_invalid_arguments' using errcode = '22023';
  end if;

  select * into v_request
  from public.credit_topup_requests r
  where r.id = p_request_id
    and r.workspace_id = p_workspace_id
  for update;
  if not found then
    return false;
  end if;
  if v_request.stripe_payment_intent_id is not null
    and v_request.stripe_payment_intent_id <> p_payment_intent_id then
    return false;
  end if;

  if p_outcome = 'paid' then
    if v_request.status <> 'paid' then
      update public.credit_topup_requests r
      set status = 'paid', reason = null, paid_at = now(),
          stripe_payment_intent_id = p_payment_intent_id, updated_at = now()
      where r.id = v_request.id;
    end if;
    return true;
  end if;

  if v_request.status = 'failed' then
    return true;
  end if;
  if v_request.status not in ('pending', 'confirmed') then
    return false;
  end if;
  update public.credit_topup_requests r
  set status = 'failed', reason = coalesce(nullif(left(p_reason, 64), ''), 'payment_failed'),
      stripe_payment_intent_id = p_payment_intent_id, updated_at = now()
  where r.id = v_request.id;
  return true;
end;
$function$;

COMMENT ON FUNCTION "public"."record_credit_topup_payment"(uuid, uuid, text, text, text) IS 'Marks a credit top-up request paid or failed for its single Stripe PaymentIntent. Called by the payment webhook and the confirm route. Service role only.';

REVOKE ALL ON FUNCTION "public"."record_credit_topup_payment"(uuid, uuid, text, text, text) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."record_credit_topup_payment"(uuid, uuid, text, text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."record_credit_topup_payment"(uuid, uuid, text, text, text) FROM "anon", "authenticated";

-- source: supabase/schemas/public/functions/record_gateway_async_webhook_result.sql
CREATE OR REPLACE FUNCTION public.record_gateway_async_webhook_result (
  p_workspace_id    uuid,
  p_kind            text,
  p_internal_id     text,
  p_delivery_key    text,
  p_attempt         jsonb,
  p_retry_state     jsonb                    DEFAULT NULL::jsonb,
  p_delivered_at    timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  p_next_retry_at   timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  p_progress        double precision         DEFAULT NULL::double precision,
  p_telemetry_patch jsonb                    DEFAULT NULL::jsonb,
  p_claim_token     text                     DEFAULT NULL::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_meta jsonb;
  v_attempts jsonb;
  v_queue jsonb;
  v_deliveries jsonb;
  v_next_retry_at timestamptz;
  v_telemetry_patch jsonb;
begin
  select coalesce(meta, '{}'::jsonb) into v_meta
  from public.gateway_async_operations
  where workspace_id = p_workspace_id and kind = p_kind and internal_id = p_internal_id
  for update;
  if not found then return; end if;

  -- Lock in the same order as lifecycle updates: operation, then delivery.
  if p_claim_token is not null then
    perform 1 from public.gateway_async_webhook_deliveries
    where workspace_id = p_workspace_id and kind = p_kind
      and internal_id = p_internal_id and delivery_key = p_delivery_key
      and status = 'claimed' and claim_token = p_claim_token
    for update;
    if not found then raise exception 'stale_webhook_delivery_claim'; end if;
  end if;


  v_telemetry_patch := coalesce(p_telemetry_patch, '{}'::jsonb)
    - 'webhookAttempts'
    - 'webhookRetryQueue'
    - 'webhookDeliveries'
    - 'nextWebhookRetryAt'
    - 'lastWebhookDispatchedAt'
    - 'lastWebhookProgress'
    - 'lastWebhookProgressAt';

  v_attempts := coalesce(v_meta->'webhookAttempts', '[]'::jsonb) || jsonb_build_array(p_attempt);
  if jsonb_array_length(v_attempts) > 50 then
    select coalesce(jsonb_agg(value order by ordinality), '[]'::jsonb)
      into v_attempts
    from jsonb_array_elements(v_attempts) with ordinality
    where ordinality > jsonb_array_length(v_attempts) - 50;
  end if;

  v_queue := coalesce(v_meta->'webhookRetryQueue', '{}'::jsonb);
  if p_retry_state is null then
    v_queue := v_queue - p_delivery_key;
  else
    v_queue := jsonb_set(v_queue, array[p_delivery_key], p_retry_state, true);
  end if;

  v_deliveries := coalesce(v_meta->'webhookDeliveries', '{}'::jsonb);
  if p_delivered_at is not null then
    v_deliveries := jsonb_set(v_deliveries, array[p_delivery_key], to_jsonb(p_delivered_at::text), true);
  end if;

  select min(nullif(value->>'nextRetryAt', '')::timestamptz)
    into v_next_retry_at
  from jsonb_each(v_queue);

  v_meta := v_meta || jsonb_build_object(
    'webhookAttempts', v_attempts,
    'webhookRetryQueue', v_queue,
    'webhookDeliveries', v_deliveries,
    'nextWebhookRetryAt', case when v_next_retry_at is null then 'null'::jsonb else to_jsonb(v_next_retry_at::text) end,
    'lastWebhookDispatchedAt', to_jsonb(now()::text)
  ) || v_telemetry_patch;
  if p_progress is not null then
    v_meta := v_meta || jsonb_build_object(
      'lastWebhookProgress', p_progress,
      'lastWebhookProgressAt', to_jsonb(now()::text)
    );
  end if;

  update public.gateway_async_operations
  set meta = v_meta, updated_at = now()
  where workspace_id = p_workspace_id and kind = p_kind and internal_id = p_internal_id;

  update public.gateway_async_webhook_deliveries
  set status = case
        when p_delivered_at is not null then 'delivered'
        when p_next_retry_at is null then 'failed'
        else status
      end,
      claim_token = case when p_next_retry_at is null then null else claim_token end,
      claimed_at = case when p_next_retry_at is null then null else claimed_at end,
      delivered_at = coalesce(p_delivered_at, delivered_at),
      next_attempt_at = p_next_retry_at,
      last_error = p_attempt->>'error_message',
      updated_at = now()
  where workspace_id = p_workspace_id and kind = p_kind
    and internal_id = p_internal_id and delivery_key = p_delivery_key;
end;
$function$;

GRANT EXECUTE
  ON FUNCTION "public"."record_gateway_async_webhook_result"(uuid, text, text, text, jsonb, jsonb, timestamp WITH time zone, timestamp
    WITH time zone, double precision, jsonb, text)
  TO "service_role";

REVOKE ALL
