-- source: supabase/schemas/public/functions/record_mobile_push_receipts.sql
CREATE OR REPLACE FUNCTION public.record_mobile_push_receipts (
  p_results jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Closes the receipts Expo returned: [{ "id", "status": "ok" | "error", "errorCode",
-- "errorMessage" }]. An error marks the push failed, with every row it carried, and
-- DeviceNotRegistered retires the device. Tickets left out stay open, so
-- claim_mobile_push_receipts hands them out again.
declare
  v_result jsonb;
begin
  if jsonb_typeof(p_results) is distinct from 'array' then
    raise exception 'invalid_mobile_push_receipts';
  end if;

  with results as (
    select distinct on (r.id) r.id, r.status, left(r."errorCode", 100) as error_code, left(r."errorMessage", 1000) as error_message
    from jsonb_to_recordset(p_results) as r(id uuid, status text, "errorCode" text, "errorMessage" text)
    where r.id is not null and r.status in ('ok', 'error')
    order by r.id
  ),
  checked as (
    update public.mobile_push_deliveries x
    set status = case when r.status = 'error' then 'failed' else x.status end,
        error_code = case when r.status = 'error' then coalesce(r.error_code, 'receipt_error') else x.error_code end,
        error_message = case when r.status = 'error' then r.error_message else x.error_message end,
        receipt_checked_at = now(),
        updated_at = now()
    from results r
    where x.id = r.id and x.status = 'sent' and x.receipt_checked_at is null
    returning x.id, x.device_id, x.status, x.error_code, x.error_message
  ),
  carried as (
    update public.mobile_push_deliveries x
    set status = 'failed', error_code = c.error_code, error_message = c.error_message, updated_at = now()
    from checked c
    where c.status = 'failed' and x.merged_into = c.id and x.status = 'sent'
    returning x.id
  ),
  invalidated as (
    update public.mobile_push_devices dev
    set status = 'invalid', invalidated_at = now(), updated_at = now()
    where dev.id in (select c.device_id from checked c where c.status = 'failed' and c.error_code = 'DeviceNotRegistered')
      and dev.status = 'active'
    returning dev.id
  )
  select jsonb_build_object(
    'checked', count(*),
    'failed', count(*) filter (where c.status = 'failed'),
    'invalidated', (select count(*) from invalidated)
  ) into v_result
  from checked c;

  return v_result;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."record_mobile_push_receipts"(jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."record_mobile_push_receipts"(jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/record_model_discovery_payload_fingerprints.sql
CREATE OR REPLACE FUNCTION public.record_model_discovery_payload_fingerprints (
  p_rows jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  conflicts integer;
begin
  if jsonb_typeof(p_rows) <> 'array' then
    raise exception 'payload fingerprint rows must be a JSON array';
  end if;

  -- Compare-and-set per provider: record the new fingerprint only while the row still holds the one the
  -- sweep started from. Otherwise an overlapping sweep wrote in between, so clear it; a missing
  -- fingerprint only makes the next sweep re-extract that provider.
  with changes as (
    select
      entry->>'provider_id' as provider_id,
      entry->>'expected' as expected,
      entry->>'next' as next
    from jsonb_array_elements(p_rows) as entries(entry)
    where nullif(trim(entry->>'provider_id'), '') is not null
  ), updated as (
    update public.model_discovery_provider_status as status
    set payload_fingerprint = case
      when status.payload_fingerprint is not distinct from changes.expected then changes.next
      else null
    end
    from changes
    where status.provider_id = changes.provider_id
    returning status.payload_fingerprint is distinct from changes.next as conflicted
  )
  select count(*) filter (where conflicted) into conflicts from updated;

  return conflicts;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."record_model_discovery_payload_fingerprints"(jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."record_model_discovery_payload_fingerprints"(jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/record_model_substitution.sql
CREATE OR REPLACE FUNCTION public.record_model_substitution (
  p_workspace_id   uuid,
  p_model_slug     text,
  p_successor_slug text,
  p_source         text DEFAULT 'approved'::text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  -- Slugs may contain ':' and be long, so the pair is hashed rather than joined.
  v_dedupe_key text := 'model_substitution:' || p_workspace_id::text || ':'
    || md5(length(coalesce(p_model_slug, ''))::text || ':' || coalesce(p_model_slug, '') || coalesce(p_successor_slug, ''));
  v_owner uuid;
  v_email text;
  v_workspace_name text;
  v_model_name text;
  v_successor_name text;
  v_title text;
  v_inserted uuid;
begin
  -- One notice per workspace, model and replacement. The gateway calls this on
  -- every isolate that serves a substitution, so the common case returns here.
  if exists (select 1 from public.email_outbox where dedupe_key = v_dedupe_key) then
    return false;
  end if;

  if p_source not in ('approved', 'workspace') or p_model_slug = p_successor_slug then
    raise exception 'invalid_model_substitution';
  end if;

  select m.name into v_model_name from public.v2_models m where m.model_slug = p_model_slug;
  if not found then return false; end if;
  select m.name into v_successor_name from public.v2_models m where m.model_slug = p_successor_slug;
  if not found then return false; end if;

  select w.owner_user_id, w.name, nullif(trim(a.email), '')
  into v_owner, v_workspace_name, v_email
  from public.workspaces w
  left join auth.users a on a.id = w.owner_user_id
  where w.id = p_workspace_id;
  if v_email is null then return false; end if;

  v_title := 'Model replaced: ' || coalesce(v_model_name, p_model_slug);

  insert into public.email_outbox (dedupe_key, kind, template, to_email, subject, workspace_id, user_id, payload)
  values (
    v_dedupe_key, 'model_substitution', 'model_substitution', v_email, v_title, p_workspace_id, v_owner,
    jsonb_build_object(
      'title', v_title,
      'workspace_name', coalesce(v_workspace_name, 'your workspace'),
      'model_id', p_model_slug,
      'model_name', coalesce(v_model_name, p_model_slug),
      'replacement_model_id', p_successor_slug,
      'replacement_model_name', coalesce(v_successor_name, p_successor_slug),
      'source', p_source
    )
  )
  on conflict (dedupe_key) do nothing
  returning id into v_inserted;

  return v_inserted is not null;
end;
$function$;

COMMENT ON FUNCTION "public"."record_model_substitution"(uuid, text, text, text) IS 'Queues the one-off notice that a workspace''s requests for a model no provider serves are now served by a replacement. Emails the owner and feeds routed notification destinations; returns true only the first time.';

GRANT EXECUTE ON FUNCTION "public"."record_model_substitution"(uuid, text, text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."record_model_substitution"(uuid, text, text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/record_request_classifier_spend.sql
CREATE OR REPLACE FUNCTION public.record_request_classifier_spend (
  p_workspace_id uuid,
  p_classifier_id uuid,
  p_cost_nanos bigint
)
  RETURNS void
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- A classifier deleted mid-request matches no row and records nothing.
  insert into public.workspace_request_classifier_spend_monthly as spend
    (classifier_id, workspace_id, month, classifications, cost_nanos, updated_at)
  select classifier.id, classifier.workspace_id,
    date_trunc('month', now() at time zone 'utc')::date,
    1, greatest(coalesce(p_cost_nanos, 0), 0), now()
  from public.workspace_request_classifiers classifier
  where classifier.id = p_classifier_id and classifier.workspace_id = p_workspace_id
  on conflict (classifier_id, month) do update
  set classifications = spend.classifications + 1,
    cost_nanos = spend.cost_nanos + excluded.cost_nanos,
    updated_at = now();
$function$;

COMMENT ON FUNCTION "public"."record_request_classifier_spend"(uuid, uuid, bigint) IS 'Adds one classification and its cost to the classifier''s current UTC month.';

GRANT EXECUTE ON FUNCTION "public"."record_request_classifier_spend"(uuid, uuid, bigint) TO "service_role";

