-- source: supabase/schemas/public/functions/record_slack_agent_people.sql
CREATE OR REPLACE FUNCTION public.record_slack_agent_people (
  p_installation_id uuid,
  p_period_start    date,
  p_people          jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  if p_period_start is null or p_period_start <> date_trunc('month', p_period_start)::date then
    raise exception 'invalid_period_start' using errcode = '22023';
  end if;
  if p_people is null or jsonb_typeof(p_people) <> 'array' or jsonb_array_length(p_people) > 1000 then
    raise exception 'invalid_people' using errcode = '22023';
  end if;

  -- The meter sends running totals, so a retried or repeated flush can only raise
  -- a count, never add it twice.
  insert into public.slack_agent_monthly_people as person
    (installation_id, period_start, slack_user_id, first_answer_at, answers, updated_at)
  select installation.id, p_period_start, entry.slack_user_id, entry.first_answer_at,
    greatest(coalesce(entry.answers, 0), 0), now()
  from public.slack_installations installation
  -- One row per person: a repeated person would make the upsert touch the same row twice and fail the whole flush.
  cross join (
    select raw.slack_user_id, min(raw.first_answer_at) as first_answer_at, max(raw.answers) as answers
    from jsonb_to_recordset(p_people) as raw(slack_user_id text, first_answer_at timestamptz, answers bigint)
    group by raw.slack_user_id
  ) as entry
  where installation.id = p_installation_id
  on conflict (installation_id, period_start, slack_user_id) do update
  set answers = greatest(person.answers, excluded.answers),
    first_answer_at = least(person.first_answer_at, excluded.first_answer_at),
    updated_at = now()
  where excluded.answers > person.answers or excluded.first_answer_at < person.first_answer_at;

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

COMMENT ON FUNCTION "public"."record_slack_agent_people"(uuid, date, jsonb) IS 'Upserts running totals [{slack_user_id, first_answer_at, answers}] for one installation and UTC month from the Slack Worker''s meter. Counts only ever rise, so repeated flushes are safe. Returns the rows changed.';

GRANT EXECUTE ON FUNCTION "public"."record_slack_agent_people"(uuid, date, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."record_slack_agent_people"(uuid, date, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/record_slack_agent_schedule_run.sql
CREATE OR REPLACE FUNCTION public.record_slack_agent_schedule_run (
  p_schedule_id uuid,
  p_run_at      timestamp with time zone,
  p_result      text,
  p_reason      text,
  p_pause       boolean
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- What became of a claimed run, reported by the Slack Worker when its answer
-- ends or when it skips the run. answered clears the failures in a row; failed
-- and skipped add one. p_pause pauses the schedule at once, with p_reason as the
-- reason (its creator can no longer use the agent, or the agent isn't in the
-- channel); otherwise the third failure in a row pauses it (failures). A run
-- skipped because the agent is paused or a bill is due (installation_paused,
-- payment_due) is neither: it leaves the failures in a row as they were and never
-- pauses the schedule, even with p_pause, so the schedule runs again at its next
-- time once the agent is back on. Only the run claimed last is recorded, and
-- only once: a repeat (a retried Workflow step) or an older run changes nothing
-- and returns recorded false.
-- Returns {recorded, paused (by this call), pause_reason, failures, created_by,
-- channel_id, title}. Service role only.
declare
  v_schedule public.slack_agent_schedules%rowtype;
  v_failures integer;
  v_pause text;
  v_agent_paused boolean := p_result = 'skipped' and coalesce(p_reason in ('installation_paused', 'payment_due'), false);
begin
  if p_result is null or p_result not in ('answered', 'failed', 'skipped') then
    raise exception 'invalid_result' using errcode = '22023';
  end if;
  select * into v_schedule
  from public.slack_agent_schedules schedule
  where schedule.id = p_schedule_id and schedule.last_run_at = p_run_at and schedule.last_result is null
  for update;
  if not found then
    return jsonb_build_object('recorded', false, 'paused', false);
  end if;
  v_failures := case
    when p_result = 'answered' then 0
    when v_agent_paused then v_schedule.failures
    else v_schedule.failures + 1
  end;
  -- One an admin paused meanwhile keeps that reason.
  v_pause := case
    when v_schedule.status <> 'active' or v_agent_paused then null
    when coalesce(p_pause, false) then p_reason
    when v_failures >= 3 then 'failures'
  end;
  update public.slack_agent_schedules schedule
  set last_result = p_result,
      last_result_reason = p_reason,
      failures = v_failures,
      status = case when v_pause is null then schedule.status else 'paused' end,
      pause_reason = coalesce(v_pause, schedule.pause_reason)
  where schedule.id = p_schedule_id;
  return jsonb_build_object(
    'recorded', true,
    'paused', v_pause is not null,
    'pause_reason', v_pause,
    'failures', v_failures,
    'created_by', v_schedule.created_by,
    'channel_id', v_schedule.channel_id,
    'title', v_schedule.title
  );
end;
$function$;

COMMENT ON FUNCTION "public"."record_slack_agent_schedule_run"(uuid, timestamp with time zone, text, text, boolean) IS 'For the Slack Worker: records the result of a schedule''s latest claimed run once, counts failures in a row and pauses the schedule when asked or at the third; a run skipped while the agent is paused or a bill is due neither counts nor pauses it. Returns {recorded, paused, pause_reason, failures, created_by, channel_id, title}.';

GRANT EXECUTE ON FUNCTION "public"."record_slack_agent_schedule_run"(uuid, timestamp with time zone, text, text, boolean) TO "service_role";

REVOKE ALL ON FUNCTION "public"."record_slack_agent_schedule_run"(uuid, timestamp with time zone, text, text, boolean) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/record_spend_limit_reached.sql
CREATE OR REPLACE FUNCTION public.record_spend_limit_reached (
  p_workspace_id uuid,
  p_key_id       uuid,
  p_reason       text,
  p_now          timestamp with time zone DEFAULT now()
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Records that the gateway rejected a request because a workspace budget or an API key limit is
-- used up (p_reason is the rejection reason), as one money push per budget or key limit, period
-- and limit value: owners and admins hear that requests are blocked, and for a key limit so does
-- the key's creator. The gateway calls this in the background after responding, at most once
-- per isolate and period, so a blocked workspace that keeps retrying costs one call per isolate.
-- Returns true only the first time; other rejection reasons are ignored.
declare
  v_match text[];
  v_kind text;
  v_window text;
  v_metric text;
  v_limit numeric;
  v_subject text;
  v_name text;
  v_creator uuid;
  v_key_id uuid;
  v_period record;
  v_until text;
  v_title text;
  v_body text;
  v_href text;
  v_inserted uuid;
begin
  if p_workspace_id is null or p_reason is null or p_now is null then
    return false;
  end if;

  v_match := regexp_match(p_reason, '^workspace_(daily|weekly|monthly|lifetime)_cost_budget_reached$');
  if v_match is not null then
    v_kind := 'budget_reached';
    v_window := v_match[1];
    v_metric := 'cost';
    select 'budget:' || b.id, b.limit_nanos into v_subject, v_limit
    from public.workspace_budgets b
    where b.workspace_id = p_workspace_id and b.interval = v_window;
  else
    v_match := regexp_match(p_reason, '^(daily|weekly|monthly)_(request|cost)_limit_reached$');
    if v_match is null or p_key_id is null then
      return false;
    end if;
    v_kind := 'key_limit_reached';
    v_window := v_match[1];
    v_metric := case when v_match[2] = 'request' then 'requests' else 'cost' end;
    select 'key:' || k.id || ':' || v_metric, k.id, k.name, k.created_by,
      case v_window || ':' || v_metric
        when 'daily:requests' then k.daily_limit_requests
        when 'weekly:requests' then k.weekly_limit_requests
        when 'monthly:requests' then k.monthly_limit_requests
        when 'daily:cost' then k.daily_limit_cost_nanos
        when 'weekly:cost' then k.weekly_limit_cost_nanos
        when 'monthly:cost' then k.monthly_limit_cost_nanos
      end
      into v_subject, v_key_id, v_name, v_creator, v_limit
    from public.keys k
    where k.id = p_key_id and k.workspace_id = p_workspace_id;
  end if;
  if v_subject is null or coalesce(v_limit, 0) <= 0 then
    return false;
  end if;

  select * into v_period from private.spend_limit_period(v_window, p_now);
  v_until := case
    when v_window = 'daily' then 'midnight UTC'
    when v_period.reset_at is not null then to_char(v_period.reset_at at time zone 'UTC', 'Mon FMDD')
  end;

  if v_kind = 'budget_reached' then
    v_title := 'Requests blocked by the ' || v_window || ' budget';
    v_body := 'The ' || private.workspace_push_usd(v_limit) || ' ' || v_window || ' budget is used up. '
      || coalesce('Requests resume ' || case when v_window = 'daily' then 'at ' else '' end || v_until || ', or raise the budget.', 'Raise it to resume requests.');
    v_href := '/settings/usage/overview';
  else
    v_title := 'API key ''' || case when char_length(v_name) > 40 then left(v_name, 39) || '…' else v_name end || ''' hit its ' || v_window || ' limit';
    v_body := 'Requests with it are blocked until ' || v_until || '. The limit is ' || private.spend_limit_amount(v_metric, v_limit)
      || ' a ' || case v_window when 'daily' then 'day' when 'weekly' then 'week' else 'month' end || '.';
    v_href := '/settings/keys';
  end if;

  insert into public.workspace_notification_events (workspace_id, kind, category, dedupe_key, key_id, key_created_by, payload, occurred_at)
  values (
    p_workspace_id,
    v_kind,
    'money',
    v_kind || ':' || v_subject || ':' || v_window || ':' || coalesce(to_char(v_period.period_start at time zone 'UTC', 'YYYY-MM-DD'), 'lifetime') || ':' || v_limit,
    v_key_id,
    v_creator,
    jsonb_build_object(
      'push', jsonb_build_object('title', v_title, 'body', v_body, 'href', v_href, 'lowerLead', v_kind = 'budget_reached'),
      'window', v_window, 'metric', v_metric, 'limit', v_limit, 'reason', p_reason,
      'periodStart', v_period.period_start, 'resetAt', v_period.reset_at
    ),
    p_now
  )
  on conflict (dedupe_key) do nothing
  returning id into v_inserted;

  return v_inserted is not null;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."record_spend_limit_reached"(uuid, uuid, text, timestamp with time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."record_spend_limit_reached"(uuid, uuid, text, timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/record_workspace_sso_active_user.sql
CREATE OR REPLACE FUNCTION public.record_workspace_sso_active_user (
  p_workspace_id uuid,
  p_auth_user_id uuid,
  p_seen_at      timestamp with time zone DEFAULT now()
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_period_start date := date_trunc('month', p_seen_at at time zone 'UTC')::date;
  v_quantity bigint;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_workspace_id::text || ':' || v_period_start::text, 0)
  );

  insert into public.workspace_sso_monthly_active_users (
    workspace_id,
    period_start,
    auth_user_id,
    first_seen_at,
    last_seen_at
  ) values (
    p_workspace_id,
    v_period_start,
    p_auth_user_id,
    p_seen_at,
    p_seen_at
  )
  on conflict (workspace_id, period_start, auth_user_id) do update set
    last_seen_at = greatest(
      public.workspace_sso_monthly_active_users.last_seen_at,
      excluded.last_seen_at
    );

  select count(*)
    into v_quantity
  from public.workspace_sso_monthly_active_users
  where workspace_id = p_workspace_id
    and period_start = v_period_start;

  insert into public.workspace_addon_usage_monthly (
    workspace_id,
    addon_key,
    metric_key,
    period_start,
    quantity,
    updated_at
  ) values (
    p_workspace_id,
    'identity',
    'sso_mau',
    v_period_start,
    v_quantity,
    now()
  )
  on conflict (workspace_id, addon_key, metric_key, period_start) do update set
    quantity = excluded.quantity,
    updated_at = now();

  return v_quantity;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."record_workspace_sso_active_user"(uuid, uuid, timestamp WITH time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."record_workspace_sso_active_user"(uuid, uuid, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/redeem_credit_code.sql
CREATE OR REPLACE FUNCTION public.redeem_credit_code (
  p_code         text,
  p_workspace_id uuid
)
  RETURNS TABLE (
    status               text,
    message              text,
    grant_id             uuid,
    amount_nanos         bigint,
    before_balance_nanos bigint,
    after_balance_nanos  bigint,
    workspace_id         uuid
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_user_id uuid := auth.uid();
  v_code_normalized text;
  v_grant public.credit_grants%rowtype;
  v_wallet public.wallets%rowtype;
  v_team_billing_mode text;
  v_redemption_id uuid;
begin
  if v_user_id is null then
    return query
    select
      'unauthorized'::text,
      'You must be signed in to redeem a credit code.'::text,
      null::uuid,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  if p_workspace_id is null or not public.is_workspace_member(p_workspace_id) then
    return query
    select
      'team_forbidden'::text,
      'You do not have access to this team.'::text,
      null::uuid,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  select lower(coalesce(t.billing_mode::text, 'wallet'))
  into v_team_billing_mode
  from public.workspaces t
  where t.id = p_workspace_id;

  if not found then
    return query
    select
      'team_forbidden'::text,
      'You do not have access to this team.'::text,
      null::uuid,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  if v_team_billing_mode = 'invoice' then
    return query
    select
      'invoice_mode'::text,
      'Credit codes are not available for invoice billing teams.'::text,
      null::uuid,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  v_code_normalized := upper(trim(coalesce(p_code, '')));

  if v_code_normalized = ''
    or length(v_code_normalized) > 64
    or v_code_normalized !~ '^[A-Z0-9][A-Z0-9_-]{1,63}$'
  then
    return query
    select
      'invalid_code_format'::text,
      'Credit code format is invalid.'::text,
      null::uuid,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  select *
  into v_grant
  from public.credit_grants cg
  where cg.code_normalized = v_code_normalized
  for update;

  if not found then
    return query
    select
      'not_found'::text,
      'This credit code is invalid.'::text,
      null::uuid,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  if not coalesce(v_grant.is_active, false) then
    return query
    select
      'inactive'::text,
      'This credit code is inactive.'::text,
      v_grant.id,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  if v_grant.expires_at is not null and v_grant.expires_at <= now() then
    return query
    select
      'expired'::text,
      'This credit code has expired.'::text,
      v_grant.id,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  if coalesce(v_grant.redemptions_count, 0) >= v_grant.max_redemptions then
    return query
    select
      'maxed_out'::text,
      'This credit code has reached its redemption limit.'::text,
      v_grant.id,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  select *
  into v_wallet
  from public.wallets w
  where w.workspace_id = p_workspace_id
  for update;

  if not found then
    return query
    select
      'wallet_not_found'::text,
      'Wallet not found for this team.'::text,
      v_grant.id,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  insert into public.credit_grant_redemptions (
    grant_id,
    user_id,
    workspace_id,
    amount_nanos
  ) values (
    v_grant.id,
    v_user_id,
    p_workspace_id,
    v_grant.amount_nanos
  )
  on conflict on constraint credit_grant_redemptions_grant_user_unique
  do nothing
  returning id
  into v_redemption_id;

  if v_redemption_id is null then
    return query
    select
      'already_redeemed'::text,
      'You have already redeemed this credit code.'::text,
      v_grant.id,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  update public.wallets as w
  set balance_nanos = w.balance_nanos + v_grant.amount_nanos,
      updated_at = now()
  where w.workspace_id = p_workspace_id
  returning w.*
  into v_wallet;

  insert into public.credit_ledger (
    workspace_id,
    event_time,
    kind,
    amount_nanos,
    before_balance_nanos,
    after_balance_nanos,
    ref_type,
    ref_id,
    created_at,
    status
  ) values (
    p_workspace_id,
    now(),
    'promo_code',
    v_grant.amount_nanos,
    v_wallet.balance_nanos - v_grant.amount_nanos,
    v_wallet.balance_nanos,
    'promo_code_redeem',
    v_redemption_id::text,
    now(),
    'paid'
  ) on conflict (ref_type, ref_id) do nothing;

  update public.credit_grants
  set redemptions_count = redemptions_count + 1
  where id = v_grant.id;

  return query
  select
    'succeeded'::text,
    'Promo credit applied successfully.'::text,
    v_grant.id,
    v_grant.amount_nanos,
    v_wallet.balance_nanos - v_grant.amount_nanos,
    v_wallet.balance_nanos,
    p_workspace_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."redeem_credit_code"(text, uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."redeem_credit_code"(text, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."redeem_credit_code"(text, uuid) FROM PUBLIC, "anon";

-- source: supabase/schemas/public/functions/refresh_effective_entitlements_after_directory_change.sql
CREATE OR REPLACE FUNCTION public.refresh_effective_entitlements_after_directory_change()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare target_workspace_id uuid;
begin
  if current_setting('phaseo.scim_group_replace',true)='on' then return coalesce(new,old); end if;
  target_workspace_id := coalesce(new.workspace_id,old.workspace_id);
  perform set_config('phaseo.entitlement_reconcile','on',true);
  update public.workspace_members wm set role=o.access_role::public.workspace_role
  from public.workspace_member_overrides o
  where wm.workspace_id=target_workspace_id and wm.workspace_id=o.workspace_id and wm.user_id=o.user_id and o.access_role is not null
    and lower(wm.role::text) is distinct from o.access_role;
  perform public.refresh_workspace_effective_entitlements(target_workspace_id,null,'directory_sync');
  return coalesce(new,old);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."refresh_effective_entitlements_after_directory_change"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."refresh_effective_entitlements_after_directory_change"() FROM PUBLIC, "anon", "authenticated";

