-- source: supabase/schemas/public/functions/refresh_public_model_task_daily.sql
CREATE OR REPLACE FUNCTION public.refresh_public_model_task_daily (
  p_since date DEFAULT (CURRENT_DATE - 1)
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('refresh_public_model_task_daily')
  );

  delete from public.public_model_task_daily
  where usage_date >= coalesce(p_since, current_date - 1);

  insert into public.public_model_task_daily (
    usage_date, taxonomy_slug, primary_category, model_slug, provider_slug,
    workspace_count, request_count, input_tokens, output_tokens, updated_at
  )
  select
    daily.usage_date,
    classifier.slug,
    daily.primary_category,
    daily.model_slug,
    daily.provider_slug,
    count(*) as workspace_count,
    sum(daily.request_count) as request_count,
    sum(daily.input_tokens) as input_tokens,
    sum(daily.output_tokens) as output_tokens,
    now()
  from public.reporting_classification_daily daily
  join public.workspace_classifiers classifier on classifier.id = daily.classifier_id
  where daily.usage_date >= coalesce(p_since, current_date - 1)
    and classifier.kind = 'phaseo_task'
  group by daily.usage_date, classifier.slug, daily.primary_category,
    daily.model_slug, daily.provider_slug
  on conflict (usage_date, taxonomy_slug, primary_category, model_slug, provider_slug)
  do update set
    workspace_count = excluded.workspace_count,
    request_count = excluded.request_count,
    input_tokens = excluded.input_tokens,
    output_tokens = excluded.output_tokens,
    updated_at = excluded.updated_at;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."refresh_public_model_task_daily"(date) TO "service_role";

REVOKE ALL ON FUNCTION "public"."refresh_public_model_task_daily"(date) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/refresh_public_model_user_usage_daily.sql
CREATE OR REPLACE FUNCTION public.refresh_public_model_user_usage_daily (
  p_since timestamp with time zone DEFAULT (now() - '2 days'::interval),
  p_until timestamp with time zone DEFAULT now()
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_since date := (p_since at time zone 'utc')::date;
  v_until date := ((p_until - interval '1 microsecond') at time zone 'utc')::date;
begin
  delete from public.public_model_user_usage_daily
  where day_bucket >= v_since and day_bucket <= v_until;
  insert into public.public_model_user_usage_daily
    (day_bucket, model_id, provider_id, actor_hash, requests, tokens, refreshed_at)
  with normalized as (
    select (fact.occurred_at at time zone 'utc')::date as day_bucket,
      public.public_leaderboard_model_id(
        coalesce(fact.routed_model_slug, fact.requested_model_slug),
        coalesce(fact.routed_model_slug, fact.requested_model_slug, fact.requested_model_input),
        fact.requested_model_input, fact.routed_model_slug, request.api_model_id,
        route.provider_slug, request.pricing_plan, request.is_free_variant
      ) as model_id,
      coalesce(nullif(route.provider_slug, ''), 'unknown') as provider_id,
      coalesce(
        nullif(fact.safe_metadata->>'oauth_user_id', '')::uuid::text,
        nullif(fact.end_user_id, ''), fact.workspace_id::text, fact.key_id::text
      ) as actor_key,
      public.gateway_usage_nonnegative_bigint(coalesce(
        public.gateway_usage_total_tokens(usage.payload), usage.total_tokens, 0
      )) as total_tokens
    from public.reporting_request_facts fact
    left join public.v2_model_provider_routes route on route.provider_model_id = fact.provider_model_id
    left join public.gateway_requests request
      on request.id = fact.gateway_request_id and request.created_at = fact.gateway_request_created_at
    left join lateral (
      select jsonb_object_agg(meter_key, quantity) as payload,
        sum(quantity) filter (where meter_key in ('input_tokens','output_tokens')) as total_tokens
      from (
        select meter.meter_key, sum(meter.quantity) as quantity
        from public.v2_request_usage meter
        where meter.request_event_id = fact.request_event_id
        group by meter.meter_key
      ) meters
    ) usage on true
    where fact.occurred_at >= (v_since::timestamp at time zone 'utc')
      and fact.occurred_at < p_until and fact.success is true
  )
  select day_bucket, model_id, provider_id, md5('public-model-user:' || actor_key),
    count(*)::bigint, sum(total_tokens)::bigint, now()
  from normalized
  where actor_key is not null and model_id is not null and model_id <> ''
    and lower(model_id) not in ('unknown', 'other')
  group by day_bucket, model_id, provider_id, md5('public-model-user:' || actor_key);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."refresh_public_model_user_usage_daily"(timestamp WITH time zone, timestamp WITH time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."refresh_public_model_user_usage_daily"(timestamp WITH time zone, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/refresh_public_model_workspace_usage_weekly.sql
CREATE OR REPLACE FUNCTION public.refresh_public_model_workspace_usage_weekly (
  p_since timestamp with time zone DEFAULT (now() - '84 days'::interval),
  p_until timestamp with time zone DEFAULT now()
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_since_week date := date_trunc('week', p_since at time zone 'utc')::date;
  v_until_week date := date_trunc('week', (p_until - interval '1 microsecond') at time zone 'utc')::date;
begin
  delete from public.public_model_workspace_usage_weekly
  where week_start >= v_since_week and week_start <= v_until_week;
  insert into public.public_model_workspace_usage_weekly
    (week_start, model_id, workspace_hash, requests, refreshed_at)
  select date_trunc('week', fact.occurred_at at time zone 'utc')::date,
    coalesce(nullif(fact.routed_model_slug,''),nullif(fact.requested_model_slug,'')),
    md5('public-model-workspace:' || fact.workspace_id::text), count(*)::bigint, now()
  from public.reporting_request_facts fact
  where fact.occurred_at >= p_since and fact.occurred_at < p_until
    and fact.success is true and fact.workspace_id is not null
    and coalesce(nullif(fact.routed_model_slug,''),nullif(fact.requested_model_slug,'')) is not null
    and lower(coalesce(nullif(fact.routed_model_slug,''),nullif(fact.requested_model_slug,''))) not in ('unknown','other')
  group by 1,2,3;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."refresh_public_model_workspace_usage_weekly"(timestamp WITH time zone, timestamp WITH time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."refresh_public_model_workspace_usage_weekly"(timestamp WITH time zone, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/refresh_public_monitor_weekly_usage.sql
CREATE OR REPLACE FUNCTION public.refresh_public_monitor_weekly_usage()
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  -- Readers keep the previous snapshot until this transaction commits.
  delete from public.public_monitor_weekly_usage;
  insert into public.public_monitor_weekly_usage
    (model_id, provider_id, total_tokens, throughput_sum, throughput_count,
     latency_sum, latency_count, refreshed_at)
  with weekly_request_groups as materialized (
    -- Resolve model aliases once per group, rather than once per request.
    -- Keep sums and counts separate so combining aliases preserves averages.
    select
      gr.canonical_model_id,
      gr.model_id,
      gr.provider,
      sum(public.gateway_usage_total_tokens(gr.usage)) as total_tokens,
      sum(gr.throughput::numeric) as throughput_sum,
      count(gr.throughput) as throughput_count,
      sum(gr.latency_ms::numeric) as latency_sum,
      count(gr.latency_ms) as latency_count
    from private.v2_rpc_gateway_requests_compat gr
    where gr.created_at >= now() - interval '7 days'
    group by gr.canonical_model_id, gr.model_id, gr.provider
  ),
  normalized_weekly_requests as (
    select
      coalesce(
        nullif(gr.canonical_model_id, ''),
        public.resolve_public_model_id(gr.model_id, gr.provider),
        nullif(gr.model_id, '')
      ) as canonical_model_id,
      coalesce(nullif(gr.provider, ''), 'unknown') as provider_id,
      gr.total_tokens,
      gr.throughput_sum,
      gr.throughput_count,
      gr.latency_sum,
      gr.latency_count
    from weekly_request_groups gr
  )
  select
    r.canonical_model_id,
    r.provider_id,
    sum(r.total_tokens),
    sum(r.throughput_sum),
    sum(r.throughput_count),
    sum(r.latency_sum),
    sum(r.latency_count),
    now()
  from normalized_weekly_requests r
  where r.canonical_model_id is not null
  group by r.canonical_model_id, r.provider_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."refresh_public_monitor_weekly_usage"() TO "service_role";

COMMENT ON FUNCTION "public"."refresh_public_monitor_weekly_usage"() IS 'Replaces the rolling seven-day monitor usage snapshot from raw gateway requests. Runs from cron so public catalogue reads avoid the raw scan.';

REVOKE ALL ON FUNCTION "public"."refresh_public_monitor_weekly_usage"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/refresh_rate_limit_throttle_rollups.sql
CREATE OR REPLACE FUNCTION public.refresh_rate_limit_throttle_rollups (
  p_since timestamp with time zone DEFAULT NULL
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  SET statement_timeout TO '30s'
  SET lock_timeout TO '2s'
  AS $function$
declare
  -- Rebuilding the trailing hour absorbs late audit writes and a few missed runs.
  v_from timestamptz := date_trunc('minute',
    greatest(coalesce(p_since, now() - interval '1 hour'), now() - interval '1 day'));
  v_rows integer;
  v_pruned integer;
begin
  if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('public.refresh_rate_limit_throttle_rollups', 0)) then
    return jsonb_build_object('rows', 0, 'pruned', 0, 'skipped_locked', true);
  end if;

  delete from public.workspace_rate_limit_throttles_minute rollup
  where rollup.bucket_start >= v_from;

  insert into public.workspace_rate_limit_throttles_minute (
    bucket_start, workspace_id, policy_id, limit_scope, key_id, throttled_requests
  )
  select
    date_trunc('minute', fact.occurred_at),
    fact.workspace_id,
    (fact.safe_metadata->'rate_limit'->>'policy_id')::uuid,
    fact.safe_metadata->'rate_limit'->>'limit_scope',
    fact.key_id,
    count(*)
  from public.v2_request_facts fact
  where fact.occurred_at >= v_from
    and fact.error_code = 'user:rate_limit_exceeded'
    and fact.safe_metadata->'rate_limit'->>'policy_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    and fact.safe_metadata->'rate_limit'->>'limit_scope' in ('key', 'member', 'guardrail', 'end_user', 'department')
    -- Facts outlive their workspace; its rollup rows were removed with it.
    and exists (select 1 from public.workspaces workspace where workspace.id = fact.workspace_id)
  group by 1, 2, 3, 4, 5;
  get diagnostics v_rows = row_count;

  delete from public.workspace_rate_limit_throttles_minute rollup
  where rollup.bucket_start < now() - interval '30 days';
  get diagnostics v_pruned = row_count;

  return jsonb_build_object('from', v_from, 'rows', v_rows, 'pruned', v_pruned);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."refresh_rate_limit_throttle_rollups"(timestamp with time zone) TO "service_role";

COMMENT ON FUNCTION "public"."refresh_rate_limit_throttle_rollups"(timestamp with time zone) IS 'Rebuilds per-minute rate limit policy throttle counts from v2_request_facts since p_since (default one hour ago, at most one day), then prunes rows older than 30 days. Runs on the gateway''s five-minute schedule.';

REVOKE ALL ON FUNCTION "public"."refresh_rate_limit_throttle_rollups"(timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/refresh_request_classification_rollup.sql
CREATE OR REPLACE FUNCTION public.refresh_request_classification_rollup(p_contribution_id uuid, p_classifier_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_contribution public.data_contributions%rowtype;
  v_category text;
begin
  select * into v_contribution
  from public.data_contributions
  where id = p_contribution_id;
  if not found then return; end if;

  select primary_category into v_category
  from public.request_classifications
  where contribution_id = p_contribution_id
    and classifier_id = p_classifier_id;
  if not found then return; end if;

  if not exists (
    select 1 from public.workspace_classifiers where id = p_classifier_id
  ) then
    return;
  end if;

  insert into public.request_classification_daily (
    usage_date, workspace_id, classifier_id, primary_category, model_slug,
    provider_slug, request_count, input_tokens, output_tokens, public_request_count, public_input_tokens, public_output_tokens, updated_at
  )
  select
    contribution.occurred_at::date,
    contribution.workspace_id,
    classification.classifier_id,
    classification.primary_category,
    contribution.model_slug,
    coalesce(contribution.provider_slug, ''),
    count(*),
    coalesce(sum(contribution.input_tokens), 0),
    coalesce(sum(contribution.output_tokens), 0),
    count(*) filter (where contribution.public_reporting_allowed),
    coalesce(sum(contribution.input_tokens) filter (where contribution.public_reporting_allowed), 0),
    coalesce(sum(contribution.output_tokens) filter (where contribution.public_reporting_allowed), 0),
    now()
  from public.request_classifications classification
  join public.data_contributions contribution on contribution.id = classification.contribution_id
  where contribution.workspace_id = v_contribution.workspace_id
    and contribution.occurred_at::date = v_contribution.occurred_at::date
    and classification.classifier_id = p_classifier_id
    and classification.primary_category = v_category
    and contribution.model_slug = v_contribution.model_slug
    and coalesce(contribution.provider_slug, '') = coalesce(v_contribution.provider_slug, '')
  group by contribution.occurred_at::date, contribution.workspace_id,
    classification.classifier_id, classification.primary_category,
    contribution.model_slug, coalesce(contribution.provider_slug, '')
  on conflict (usage_date, workspace_id, classifier_id, primary_category, model_slug, provider_slug)
  do update set
    request_count = excluded.request_count,
    input_tokens = excluded.input_tokens,
    output_tokens = excluded.output_tokens,
    public_request_count = excluded.public_request_count,
    public_input_tokens = excluded.public_input_tokens,
    public_output_tokens = excluded.public_output_tokens,
    updated_at = excluded.updated_at;
end;
$function$
;

GRANT EXECUTE ON FUNCTION "public"."refresh_request_classification_rollup"(uuid, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."refresh_request_classification_rollup"(uuid, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/refresh_v2_analytics_range.sql
CREATE OR REPLACE FUNCTION public.refresh_v2_analytics_range (
  p_since        timestamp with time zone,
  p_until        timestamp with time zone DEFAULT now(),
  p_workspace_id uuid                     DEFAULT NULL::uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  result jsonb;
begin
  -- A synchronous refresh must own the processor before enqueueing its range.
  -- Otherwise an overlapping worker cannot see these uncommitted events, and
  -- its skipped result could be mistaken for a fully drained queue.
  if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('public.process_v2_analytics_outbox', 0)) then
    raise exception 'Analytics processor is busy; retry the range refresh after it completes'
      using errcode = '55P03';
  end if;
  insert into public.v2_analytics_outbox (
    request_event_id, workspace_id, occurred_at, status,
    attempt_count, available_at, last_error, updated_at
  )
  select
    fact.request_event_id, fact.workspace_id, fact.occurred_at, 'pending',
    0, now(), null, now()
  from public.v2_request_facts fact
  where fact.occurred_at >= coalesce(p_since, '-infinity'::timestamptz)
    and fact.occurred_at < coalesce(p_until, 'infinity'::timestamptz)
    and (p_workspace_id is null or fact.workspace_id = p_workspace_id)
  on conflict (request_event_id) do update set
    status = 'pending',
    attempt_count = 0,
    available_at = now(),
    last_error = null,
    updated_at = now();

  loop
    result := public.process_v2_analytics_outbox(2000);
    exit when coalesce((result->>'selected')::integer, 0) = 0;
  end loop;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."refresh_v2_analytics_range"(timestamp WITH time zone, timestamp WITH time zone, uuid) TO "service_role";

COMMENT ON FUNCTION "public"."refresh_v2_analytics_range"(timestamp with time zone, timestamp with time zone, uuid) IS 'Queues and recomputes V2 analytics grains for a bounded time/workspace range.';

REVOKE ALL ON FUNCTION "public"."refresh_v2_analytics_range"(timestamp WITH time zone, timestamp WITH time zone, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/refresh_v2_pricing_variant_links.sql
CREATE OR REPLACE FUNCTION public.refresh_v2_pricing_variant_links()
  RETURNS integer
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  with updated as (
    update public.v2_pricing_skus sku
    set route_variant_id = variant.variant_id,
        updated_at = now()
    from public.v2_route_variants variant
    where variant.provider_model_id = sku.provider_model_id
      and variant.service_tier_slug = coalesce(sku.service_tier_slug, 'standard')
      and variant.variant_key = 'global:' || coalesce(sku.service_tier_slug, 'standard')
      and sku.route_variant_id is distinct from variant.variant_id
    returning 1
  )
  select count(*)::integer from updated;
$function$;

GRANT EXECUTE ON FUNCTION "public"."refresh_v2_pricing_variant_links"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."refresh_v2_pricing_variant_links"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/refresh_v2_provider_health_for_attempt.sql
CREATE OR REPLACE FUNCTION public.refresh_v2_provider_health_for_attempt()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  fact_row record;
begin
  if tg_op <> 'INSERT' then
    select occurred_at::date usage_date, coalesce(routed_model_slug, requested_model_slug) model_slug
      into fact_row from public.reporting_request_facts where request_event_id = old.request_event_id;
    perform private.enqueue_provider_health_refresh(fact_row.usage_date, fact_row.model_slug, old.provider_model_id);
  end if;
  if tg_op <> 'DELETE' then
    select occurred_at::date usage_date, coalesce(routed_model_slug, requested_model_slug) model_slug
      into fact_row from public.reporting_request_facts where request_event_id = new.request_event_id;
    perform private.enqueue_provider_health_refresh(fact_row.usage_date, fact_row.model_slug, new.provider_model_id);
  end if;
  return null;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."refresh_v2_provider_health_for_attempt"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."refresh_v2_provider_health_for_attempt"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/refresh_workspace_effective_entitlements.sql
CREATE OR REPLACE FUNCTION public.refresh_workspace_effective_entitlements (
  p_workspace_id uuid,
  p_changed_by   uuid DEFAULT NULL::uuid,
  p_reason       text DEFAULT 'reconcile'::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  candidate record;
  previous record;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext(p_workspace_id::text)::bigint
  );

  for candidate in
    select wm.workspace_id,wm.user_id,
      case when w.owner_user_id=wm.user_id then 'owner'
           when o.access_role is not null then o.access_role
           else lower(wm.role::text) end as access_role,
      case when o.department_override_enabled then o.department_id else dg.department_id end as department_id,
      case when o.department_override_enabled then o.department_position else dg.position end as department_position,
      case when w.owner_user_id=wm.user_id then 'owner'
           when o.access_role is not null then 'manual_override'
           when exists(select 1 from public.workspace_access_grants ag where ag.workspace_id=wm.workspace_id and ag.user_id=wm.user_id and ag.source_type='scim_group') then 'scim'
           else 'workspace' end as access_source,
      case when o.department_override_enabled then 'manual_override'
           when dg.department_id is null then 'none'
           when dg.source_type='scim_group' then 'scim'
           else dg.source_type end as department_source
    from public.workspace_members wm
    join public.workspaces w on w.id=wm.workspace_id
    left join public.workspace_member_overrides o on o.workspace_id=wm.workspace_id and o.user_id=wm.user_id
    left join lateral (
      select g.department_id,g.position,g.source_type
      from public.workspace_department_grants g
      where g.workspace_id=wm.workspace_id and g.user_id=wm.user_id
      order by g.is_primary desc,(g.source_type='manual') desc,g.created_at asc
      limit 1
    ) dg on true
    where wm.workspace_id=p_workspace_id
  loop
    select * into previous from public.workspace_member_effective_entitlements
      where workspace_id=candidate.workspace_id and user_id=candidate.user_id;

    if previous is null
       or previous.access_role is distinct from candidate.access_role
       or previous.department_id is distinct from candidate.department_id
       or previous.department_position is distinct from candidate.department_position
       or previous.access_source is distinct from candidate.access_source
       or previous.department_source is distinct from candidate.department_source then
      update public.workspace_member_entitlement_history
        set effective_to=now()
        where workspace_id=candidate.workspace_id and user_id=candidate.user_id and effective_to is null;

      insert into public.workspace_member_entitlement_history(
        workspace_id,user_id,access_role,department_id,department_name,department_color,department_icon,
        department_position,access_source,department_source,changed_by,change_reason
      )
      select candidate.workspace_id,candidate.user_id,candidate.access_role,candidate.department_id,
        d.name,d.color,d.icon,candidate.department_position,candidate.access_source,candidate.department_source,
        p_changed_by,left(coalesce(p_reason,'reconcile'),200)
      from (select 1) seed left join public.workspace_departments d on d.id=candidate.department_id;
    end if;

    insert into public.workspace_member_effective_entitlements(
      workspace_id,user_id,access_role,department_id,department_position,access_source,department_source,computed_at
    ) values (
      candidate.workspace_id,candidate.user_id,candidate.access_role,candidate.department_id,
      candidate.department_position,candidate.access_source,candidate.department_source,now()
    ) on conflict(workspace_id,user_id) do update set
      access_role=excluded.access_role,department_id=excluded.department_id,
      department_position=excluded.department_position,access_source=excluded.access_source,
      department_source=excluded.department_source,computed_at=excluded.computed_at;
  end loop;

  update public.workspace_member_entitlement_history h set effective_to=now()
  where h.workspace_id=p_workspace_id and h.effective_to is null
    and not exists(select 1 from public.workspace_members wm where wm.workspace_id=h.workspace_id and wm.user_id=h.user_id);
  -- phaseo:allow-destructive-migration reason: Remove derived entitlement rows for members that no longer exist in the authoritative workspace membership set.
  delete from public.workspace_member_effective_entitlements e
  where e.workspace_id=p_workspace_id
    and not exists(select 1 from public.workspace_members wm where wm.workspace_id=e.workspace_id and wm.user_id=e.user_id);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."refresh_workspace_effective_entitlements"(uuid, uuid, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."refresh_workspace_effective_entitlements"(uuid, uuid, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/refresh_workspace_enterprise_member_overage.sql
CREATE OR REPLACE FUNCTION public.refresh_workspace_enterprise_member_overage (
  p_workspace_id uuid
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_period_start date;
  v_included_members integer;
  v_monthly_unique_members bigint;
  v_overage_count bigint;
begin
  select subscription.included_members,
         coalesce(subscription.current_period_start::date, pg_catalog.date_trunc('month', pg_catalog.now() at time zone 'UTC')::date)
  into v_included_members, v_period_start
  from public.workspace_addon_subscriptions subscription
  where subscription.workspace_id = p_workspace_id
    and subscription.addon_key = 'identity'
    and subscription.included_members >= 100000
    and (
      subscription.status in ('active', 'trialing')
      or (subscription.status = 'past_due' and subscription.grace_until > pg_catalog.now())
    );

  if v_included_members is null then return 0; end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('enterprise-member-overage:' || p_workspace_id::text || ':' || v_period_start::text, 0)
  );

  insert into public.workspace_enterprise_member_overages (workspace_id, period_start, user_id)
  select member.workspace_id, v_period_start, member.user_id
  from public.workspace_members member
  where member.workspace_id = p_workspace_id
  on conflict do nothing;

  select pg_catalog.count(*) into v_monthly_unique_members
  from public.workspace_enterprise_member_overages usage
  where usage.workspace_id = p_workspace_id and usage.period_start = v_period_start;

  v_overage_count := greatest(v_monthly_unique_members - v_included_members, 0);

  insert into public.workspace_addon_usage_monthly as usage_monthly (
    workspace_id, addon_key, metric_key, period_start, quantity, updated_at
  ) values (
    p_workspace_id, 'identity', 'member_overage', v_period_start, v_overage_count, pg_catalog.now()
  ) on conflict (workspace_id, addon_key, metric_key, period_start) do update set
    quantity = greatest(usage_monthly.quantity, excluded.quantity),
    updated_at = excluded.updated_at;

  return v_overage_count;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."refresh_workspace_enterprise_member_overage"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."refresh_workspace_enterprise_member_overage"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/register_mobile_push_device.sql
CREATE OR REPLACE FUNCTION public.register_mobile_push_device (
  p_user_id         uuid,
  p_installation_id text,
  p_expo_push_token text,
  p_platform        text,
  p_time_zone       text,
  p_device_name     text,
  p_app_version     text,
  p_channel_scheme  integer DEFAULT 1
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- One row per installation and per Expo token. When a token or installation turns up under
-- another account (sign-out then sign-in as someone else) or another installation, the old
-- row is replaced so the device never receives the previous account's pushes. A user keeps
-- at most 20 active devices; the least recently seen ones beyond that are disabled. The app
-- reports its notification channel scheme each time it registers, so a build that only has
-- the single model-updates channel (scheme 1, the default) is never sent to a channel it lacks.
declare
  v_time_zone text := nullif(btrim(p_time_zone), '');
  v_channel_scheme smallint := least(greatest(coalesce(p_channel_scheme, 1), 1), 100);
  v_device_id uuid;
begin
  if p_user_id is null or p_installation_id is null or p_expo_push_token is null then
    raise exception 'invalid_mobile_push_device';
  end if;

  -- Keep only zones this database can convert; anything else falls back to UTC.
  if v_time_zone is not null then
    begin
      perform now() at time zone v_time_zone;
    exception when others then
      v_time_zone := null;
    end;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('mobile_push_device:' || p_expo_push_token, 0));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('mobile_push_installation:' || p_installation_id, 0));

  delete from public.mobile_push_devices d
  where (d.expo_push_token = p_expo_push_token or d.installation_id = p_installation_id)
    and not (d.user_id = p_user_id and d.installation_id = p_installation_id);

  insert into public.mobile_push_devices as d (
    user_id, installation_id, expo_push_token, platform, status, time_zone, device_name, app_version, channel_scheme,
    last_seen_at, updated_at, invalidated_at
  )
  values (
    p_user_id, p_installation_id, p_expo_push_token, p_platform, 'active', v_time_zone,
    nullif(btrim(p_device_name), ''), nullif(btrim(p_app_version), ''), v_channel_scheme, now(), now(), null
  )
  on conflict (user_id, installation_id) do update
    set expo_push_token = excluded.expo_push_token,
        platform = excluded.platform,
        status = 'active',
        time_zone = excluded.time_zone,
        device_name = excluded.device_name,
        app_version = excluded.app_version,
        channel_scheme = excluded.channel_scheme,
        last_seen_at = now(),
        updated_at = now(),
        invalidated_at = null
  returning d.id into v_device_id;

  update public.mobile_push_devices d
  set status = 'disabled', updated_at = now()
  where d.id in (
    select o.id from public.mobile_push_devices o
    where o.user_id = p_user_id and o.status = 'active' and o.id <> v_device_id
    order by o.last_seen_at desc, o.id
    offset 19
  );

  return v_device_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."register_mobile_push_device"(uuid, text, text, text, text, text, text, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."register_mobile_push_device"(uuid, text, text, text, text, text, text, integer) FROM PUBLIC, "anon", "authenticated";

