-- source: supabase/schemas/public/functions/reorder_mobile_notification_rules.sql
CREATE OR REPLACE FUNCTION public.reorder_mobile_notification_rules (
  p_user_id  uuid,
  p_rule_ids uuid[]
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Numbers the user's rules in the order given. The list must name each of their rules
-- exactly once; otherwise nothing changes and false is returned.
declare
  v_total integer;
begin
  if p_user_id is null or p_rule_ids is null then
    return false;
  end if;

  perform 1 from public.mobile_notification_rules r where r.user_id = p_user_id for update;
  select count(*) into v_total from public.mobile_notification_rules r where r.user_id = p_user_id;

  if cardinality(p_rule_ids) <> v_total
    or (select count(distinct x.rule_id) from unnest(p_rule_ids) as x(rule_id)) <> v_total
    or exists (
      select 1 from unnest(p_rule_ids) as x(rule_id)
      where x.rule_id is null or not exists (
        select 1 from public.mobile_notification_rules r where r.id = x.rule_id and r.user_id = p_user_id
      )
    ) then
    return false;
  end if;

  update public.mobile_notification_rules r
  set "position" = (o.ord - 1)::integer, updated_at = now()
  from unnest(p_rule_ids) with ordinality as o(rule_id, ord)
  where r.id = o.rule_id and r.user_id = p_user_id and r."position" <> (o.ord - 1)::integer;

  return true;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."reorder_mobile_notification_rules"(uuid, uuid[]) TO "service_role";

REVOKE ALL ON FUNCTION "public"."reorder_mobile_notification_rules"(uuid, uuid[]) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/reorder_v2_byok_key.sql
CREATE OR REPLACE FUNCTION public.reorder_v2_byok_key (
  p_workspace_id uuid,
  p_key_id       uuid,
  p_direction    text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  current_key public.byok_keys%rowtype;
  adjacent_key public.byok_keys%rowtype;
begin
  if p_direction not in ('up', 'down') then
    raise exception using errcode = '22023', message = 'invalid_direction';
  end if;
  if not public.is_workspace_admin(p_workspace_id) then
    raise exception using errcode = '42501', message = 'forbidden';
  end if;

  select * into current_key
  from public.byok_keys
  where id = p_key_id and workspace_id = p_workspace_id
  for update;
  if not found then return false; end if;

  if p_direction = 'up' then
    select * into adjacent_key
    from public.byok_keys
    where workspace_id = current_key.workspace_id
      and provider_id = current_key.provider_id
      and routing_mode = current_key.routing_mode
      and (sort_order, created_at, id) < (current_key.sort_order, current_key.created_at, current_key.id)
    order by sort_order desc, created_at desc, id desc
    limit 1
    for update;
  else
    select * into adjacent_key
    from public.byok_keys
    where workspace_id = current_key.workspace_id
      and provider_id = current_key.provider_id
      and routing_mode = current_key.routing_mode
      and (sort_order, created_at, id) > (current_key.sort_order, current_key.created_at, current_key.id)
    order by sort_order, created_at, id
    limit 1
    for update;
  end if;
  if not found then return true; end if;

  update public.byok_keys
  set sort_order = case
    when id = current_key.id then adjacent_key.sort_order
    else current_key.sort_order
  end
  where id in (current_key.id, adjacent_key.id);
  return true;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."reorder_v2_byok_key"(uuid, uuid, text) TO "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."reorder_v2_byok_key"(uuid, uuid, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."reorder_v2_byok_key"(uuid, uuid, text) FROM PUBLIC;

-- source: supabase/schemas/public/functions/reorder_workspace_byok_credentials.sql
CREATE OR REPLACE FUNCTION public.reorder_workspace_byok_credentials (
  p_workspace_id uuid,
  p_provider_id  text,
  p_routing_mode text,
  p_key_ids      uuid[]
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  expected_count integer;
  supplied_count integer;
begin
  if p_routing_mode not in ('priority', 'fallback') then
    return false;
  end if;

  select count(*) into expected_count
  from public.byok_keys
  where workspace_id = p_workspace_id
    and provider_id = p_provider_id
    and routing_mode = p_routing_mode;

  select count(distinct key_id) into supplied_count
  from unnest(p_key_ids) as key_id;

  if expected_count = 0
    or supplied_count <> expected_count
    or cardinality(p_key_ids) <> expected_count
    or exists (
      select 1
      from unnest(p_key_ids) as supplied(key_id)
      left join public.byok_keys credential
        on credential.id = supplied.key_id
        and credential.workspace_id = p_workspace_id
        and credential.provider_id = p_provider_id
        and credential.routing_mode = p_routing_mode
      where credential.id is null
    )
  then
    return false;
  end if;

  update public.byok_keys credential
  set sort_order = ordered.ordinality - 1
  from unnest(p_key_ids) with ordinality as ordered(key_id, ordinality)
  where credential.id = ordered.key_id
    and credential.workspace_id = p_workspace_id;

  return true;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."reorder_workspace_byok_credentials"(uuid, text, text, uuid[]) TO "service_role";

REVOKE ALL ON FUNCTION "public"."reorder_workspace_byok_credentials"(uuid, text, text, uuid[]) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/replace_broadcast_destination_relations.sql
CREATE OR REPLACE FUNCTION public.replace_broadcast_destination_relations (
  p_workspace_id   uuid,
  p_destination_id uuid,
  p_filters        jsonb DEFAULT NULL::jsonb,
  p_groups         jsonb DEFAULT NULL::jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  group_row record;
  created_group_id uuid;
begin
  if not exists (
    select 1 from public.workspace_broadcast_destinations
    where id = p_destination_id and workspace_id = p_workspace_id
  ) then
    raise exception 'observability_destination_not_found';
  end if;

  if p_filters is not null then
    if jsonb_typeof(p_filters) <> 'array' then raise exception 'invalid_destination_filters'; end if;
    delete from public.broadcast_destination_keys where destination_id = p_destination_id;
    insert into public.broadcast_destination_keys (destination_id, key_id, filter_mode)
    select p_destination_id, (item->>'key_id')::uuid, item->>'mode'
    from jsonb_array_elements(p_filters) item;
  end if;

  if p_groups is not null then
    if jsonb_typeof(p_groups) <> 'array' then raise exception 'invalid_destination_rule_groups'; end if;
    delete from public.broadcast_destination_rule_groups where destination_id = p_destination_id;
    for group_row in
      select item, ordinality - 1 as position
      from jsonb_array_elements(p_groups) with ordinality as groups(item, ordinality)
    loop
      insert into public.broadcast_destination_rule_groups (
        destination_id, name, match_operator, position
      ) values (
        p_destination_id,
        'Group ' || (group_row.position + 1),
        group_row.item->>'match',
        group_row.position
      ) returning id into created_group_id;

      insert into public.broadcast_destination_rules (
        rule_group_id, field, condition, value, position
      )
      select
        created_group_id,
        rule->>'field',
        rule->>'condition',
        rule->>'value',
        ordinality - 1
      from jsonb_array_elements(group_row.item->'rules') with ordinality as rules(rule, ordinality);
    end loop;
  end if;

  return true;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."replace_broadcast_destination_relations"(uuid, uuid, jsonb, jsonb) TO "service_role";

REVOKE ALL ON FUNCTION "public"."replace_broadcast_destination_relations"(uuid, uuid, jsonb, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/replace_gateway_dynamic_route_keys.sql
CREATE OR REPLACE FUNCTION public.replace_gateway_dynamic_route_keys (
  p_route_id    uuid,
  p_key_ids     uuid[],
  p_attached_by uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if exists (
    select 1
    from unnest(coalesce(p_key_ids, '{}'::uuid[])) requested(key_id)
    left join public.keys gateway_key on gateway_key.id = requested.key_id
    left join public.gateway_dynamic_routes route on route.id = p_route_id
    where gateway_key.id is null
      or route.id is null
      or gateway_key.workspace_id <> route.workspace_id
  ) then
    raise exception 'dynamic_route_key_workspace_mismatch';
  end if;

  delete from public.gateway_dynamic_route_keys
  where route_id = p_route_id
    or key_id = any(coalesce(p_key_ids, '{}'::uuid[]));

  insert into public.gateway_dynamic_route_keys (route_id, key_id, attached_by)
  select p_route_id, requested.key_id, p_attached_by
  from unnest(coalesce(p_key_ids, '{}'::uuid[])) requested(key_id);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."replace_gateway_dynamic_route_keys"(uuid, uuid[], uuid) TO "anon", "authenticated";

