-- source: supabase/schemas/public/functions/replace_scim_group_members.sql
CREATE OR REPLACE FUNCTION public.replace_scim_group_members (
  p_workspace_id uuid,
  p_group_id     uuid,
  p_user_ids     uuid[]
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if not exists(select 1 from public.scim_groups where id=p_group_id and workspace_id=p_workspace_id) then raise exception 'SCIM group not found' using errcode='P0002'; end if;
  if exists(select 1 from unnest(coalesce(p_user_ids,'{}'::uuid[])) candidate(user_id) where not exists(select 1 from public.scim_users where id=candidate.user_id and workspace_id=p_workspace_id)) then raise exception 'SCIM user not found in workspace' using errcode='23503'; end if;
  perform set_config('phaseo.scim_group_replace','on',true);
  delete from public.scim_group_members where workspace_id=p_workspace_id and group_id=p_group_id;
  insert into public.scim_group_members(workspace_id,group_id,user_id) select p_workspace_id,p_group_id,user_id from (select distinct unnest(coalesce(p_user_ids,'{}'::uuid[])) user_id) users;
  update public.scim_groups set updated_at=now() where id=p_group_id and workspace_id=p_workspace_id;
  perform public.reconcile_scim_entitlements(p_workspace_id);
  perform set_config('phaseo.scim_group_replace','off',true);
  perform public.refresh_workspace_effective_entitlements(p_workspace_id,null,'scim_group_replace');
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."replace_scim_group_members"(uuid, uuid, uuid[]) TO "service_role";

REVOKE ALL ON FUNCTION "public"."replace_scim_group_members"(uuid, uuid, uuid[]) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/replace_subscription_plan_bundle.sql
CREATE OR REPLACE FUNCTION public.replace_subscription_plan_bundle (
  p_plan     jsonb,
  p_models   jsonb DEFAULT '[]'::jsonb,
  p_features jsonb DEFAULT '[]'::jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_plan_uuid uuid;
  v_models jsonb := coalesce(p_models, '[]'::jsonb);
  v_features jsonb := coalesce(p_features, '[]'::jsonb);
begin
  if p_plan is null then raise exception 'p_plan is required'; end if;
  if jsonb_typeof(v_models) <> 'array' then raise exception 'p_models must be a JSON array'; end if;
  if jsonb_typeof(v_features) <> 'array' then raise exception 'p_features must be a JSON array'; end if;

  v_plan_uuid := nullif(p_plan->>'plan_uuid', '')::uuid;
  if v_plan_uuid is null then raise exception 'p_plan.plan_uuid is required'; end if;

  insert into public.v2_subscription_plans (
    plan_uuid, plan_id, name, lab_slug, description, frequency,
    price, currency, link, other_info, created_at, updated_at
  ) values (
    v_plan_uuid,
    p_plan->>'plan_id',
    p_plan->>'name',
    p_plan->>'organisation_id',
    p_plan->>'description',
    p_plan->>'frequency',
    nullif(p_plan->>'price', '')::numeric,
    p_plan->>'currency',
    p_plan->>'link',
    coalesce(p_plan->'other_info', '{}'::jsonb),
    coalesce(nullif(p_plan->>'created_at', '')::timestamptz, now()),
    now()
  )
  on conflict (plan_uuid) do update set
    plan_id = excluded.plan_id,
    name = excluded.name,
    lab_slug = excluded.lab_slug,
    description = excluded.description,
    frequency = excluded.frequency,
    price = excluded.price,
    currency = excluded.currency,
    link = excluded.link,
    other_info = excluded.other_info,
    updated_at = now();

  delete from public.v2_subscription_plan_models where plan_uuid = v_plan_uuid;
  insert into public.v2_subscription_plan_models (
    plan_uuid, model_slug, model_info, rate_limit, other_info
  )
  select
    v_plan_uuid,
    model.model_id,
    coalesce(model.model_info, '{}'::jsonb),
    coalesce(model.rate_limit, '{}'::jsonb),
    coalesce(model.other_info, '{}'::jsonb)
  from jsonb_to_recordset(v_models) as model(
    plan_uuid uuid, model_id text, model_info jsonb, rate_limit jsonb, other_info jsonb
  );

  delete from public.v2_subscription_plan_features where plan_uuid = v_plan_uuid;
  insert into public.v2_subscription_plan_features (
    plan_uuid, feature_name, feature_value, feature_description, other_info
  )
  select
    v_plan_uuid,
    feature.feature_name,
    case
      when feature.feature_value is null then null
      when jsonb_typeof(feature.feature_value) = 'string' then feature.feature_value #>> '{}'
      else feature.feature_value::text
    end,
    feature.feature_description,
    coalesce(feature.other_info, '{}'::jsonb)
  from jsonb_to_recordset(v_features) as feature(
    plan_uuid uuid, feature_name text, feature_value jsonb,
    feature_description text, other_info jsonb
  );
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."replace_subscription_plan_bundle"(jsonb, jsonb, jsonb) TO "service_role";

COMMENT ON FUNCTION "public"."replace_subscription_plan_bundle"(jsonb, jsonb, jsonb) IS 'Atomically replaces a subscription plan bundle in canonical V2 tables.';

REVOKE ALL ON FUNCTION "public"."replace_subscription_plan_bundle"(jsonb, jsonb, jsonb) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/request_workspace_rate_limit_raise.sql
CREATE OR REPLACE FUNCTION public.request_workspace_rate_limit_raise (
  p_workspace_id      uuid,
  p_from_tier         text,
  p_to_tier           text,
  p_requested_by      uuid,
  p_expires_at        timestamp with time zone,
  p_last_requested_at timestamp with time zone
)
  RETURNS TABLE (id uuid, from_tier text, to_tier text, expires_at timestamp with time zone)
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
begin
  -- The caller checked eligibility against the newest raise it saw. Under a
  -- per-workspace lock, insert only if that is still the newest raise, so two
  -- concurrent requests cannot both pass the check; the loser gets no row.
  perform pg_advisory_xact_lock(hashtextextended('workspace_rate_limit_raise:' || p_workspace_id::text, 0));
  if (select max(r.created_at) from public.workspace_rate_limit_raises r where r.workspace_id = p_workspace_id)
      is distinct from p_last_requested_at then
    return;
  end if;
  return query
  insert into public.workspace_rate_limit_raises as r (workspace_id, from_tier, to_tier, requested_by, expires_at)
  values (p_workspace_id, p_from_tier, p_to_tier, p_requested_by, p_expires_at)
  returning r.id, r.from_tier, r.to_tier, r.expires_at;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."request_workspace_rate_limit_raise"(uuid, text, text, uuid, timestamp with time zone, timestamp with time zone) TO "service_role";

COMMENT ON FUNCTION "public"."request_workspace_rate_limit_raise"(uuid, text, text, uuid, timestamp with time zone, timestamp with time zone) IS 'Records a self-serve rate limit raise only if p_last_requested_at is still the workspace''s newest raise (null when it has none), so concurrent requests cannot both pass the eligibility check. Returns no row when another request won.';

REVOKE ALL ON FUNCTION "public"."request_workspace_rate_limit_raise"(uuid, text, text, uuid, timestamp with time zone, timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/reserve_provider_onboarding_submission_slot.sql
CREATE OR REPLACE FUNCTION public.reserve_provider_onboarding_submission_slot (
  p_user_id uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  reservation_count integer;
begin
  if auth.uid() is null or auth.uid() <> p_user_id then
    raise exception 'not authorized';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));

  select count(*)::integer
    into reservation_count
    from public.provider_onboarding_submission_reservations
   where user_id = p_user_id
     and created_at >= now() - interval '24 hours';

  if reservation_count >= 5 then
    return false;
  end if;

  insert into public.provider_onboarding_submission_reservations (user_id)
  values (p_user_id);
  return true;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."reserve_provider_onboarding_submission_slot"(uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."reserve_provider_onboarding_submission_slot"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."reserve_provider_onboarding_submission_slot"(uuid) FROM PUBLIC, "anon";

-- source: supabase/schemas/public/functions/resolve_catalog_data_policy.sql
CREATE OR REPLACE FUNCTION public.resolve_catalog_data_policy(p_provider_model_id text, p_capability_id text)
RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path TO 'public' AS $function$
DECLARE
  cap public.v2_route_capabilities%rowtype;
  route public.v2_model_provider_routes%rowtype;
  source public.provider_catalog_sources%rowtype;
  approval public.provider_catalog_policy_approvals%rowtype;
  declaration jsonb;
  valid_until timestamptz;
  accepted boolean := false;
  guaranteed boolean := false;
  result jsonb;
BEGIN
  SELECT * INTO cap FROM public.v2_route_capabilities WHERE provider_model_id=p_provider_model_id AND capability_id=p_capability_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  -- Existing pins remain admin-owned. Never overwrite them with a feed claim.
  IF jsonb_typeof(cap.metadata->'data_policy')='object' THEN RETURN cap.metadata->'data_policy'; END IF;
  IF NOT coalesce(cap.metadata ? 'catalog_data_policy',false) THEN RETURN NULL; END IF;
  SELECT * INTO route FROM public.v2_model_provider_routes WHERE provider_model_id=p_provider_model_id;
  SELECT * INTO source FROM public.provider_catalog_sources WHERE provider_slug=route.provider_slug;
  SELECT * INTO approval FROM public.provider_catalog_policy_approvals WHERE provider_slug=route.provider_slug;
  declaration := cap.metadata->'catalog_data_policy'->'declaration';
  valid_until := source.last_success_at + interval '24 hours';
  accepted := coalesce(approval.enabled AND source.status='active'
    AND approval.catalog_url IS NOT DISTINCT FROM source.catalog_url
    AND approval.management_mode=source.management_mode
    AND cap.metadata->'catalog_data_policy'->>'catalogUrl' IS NOT DISTINCT FROM source.catalog_url
    AND cap.metadata->'catalog_data_policy'->>'managementMode'=source.management_mode
    AND declaration->>'privacy_policy_url'=approval.privacy_policy_url
    AND declaration->'requirements'->>'contract_mode'='none'
    AND declaration->'requirements'->'account_settings'='[]'::jsonb
    AND declaration->>'training_policy' not in ('opt_out_available','enterprise_no_train')
    AND declaration->>'zdr_eligibility'<>'conditional'
    AND valid_until > now(), false);
  guaranteed := accepted AND p_capability_id='text.generate'
    AND coalesce(route.metadata->>'catalog_service_tier','standard')<>'batch'
    AND declaration->'zero_data_retention'='true'::jsonb
    AND declaration->>'training_policy'='no_train'
    AND declaration->>'retention_mode'='none' AND declaration->'retention_days'='0'::jsonb
    AND declaration->>'zdr_eligibility'='eligible'
    AND declaration->'requirements'->>'contract_mode'='none'
    AND declaration->'requirements'->'account_settings'='[]'::jsonb;
  result := jsonb_build_object('tier',CASE WHEN accepted THEN
      CASE WHEN declaration->>'training_policy'='unknown' THEN 'unknown'
        WHEN declaration->>'training_policy' in ('may_train','opt_out_available','enterprise_no_train') THEN 'trains'
        WHEN guaranteed THEN 'private' ELSE 'logs' END ELSE 'unknown' END,
    'confidence',CASE WHEN accepted THEN 'confirmed' ELSE 'unknown' END,
    'zeroDataRetention',coalesce(guaranteed,false),
    'zdrEligibility',CASE WHEN guaranteed THEN 'eligible' ELSE 'ineligible' END,
    'retentionMode',CASE WHEN accepted THEN declaration->>'retention_mode' ELSE 'unknown' END,
    'retentionDays',CASE WHEN accepted THEN declaration->'retention_days' ELSE 'null'::jsonb END,
    'trainingPolicy',CASE WHEN accepted THEN declaration->>'training_policy' ELSE 'unknown' END,
    'evidenceUrl',declaration->>'privacy_policy_url', 'termsOfServiceUrl',declaration->>'terms_of_service_url',
    'requirements',declaration->'requirements', 'reason',coalesce(declaration->>'notes','Provider catalog declaration.'),
    'validUntil',valid_until, 'catalogManaged',true);
  RETURN result;
END $function$;

REVOKE ALL ON FUNCTION public.resolve_catalog_data_policy(text,text) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.resolve_catalog_data_policy(text,text) TO service_role;

-- source: supabase/schemas/public/functions/resolve_public_model_id.sql
create or replace function public.resolve_public_model_id(p_model_id text, p_provider text default null)
returns text
language plpgsql
stable
set search_path = public, pg_temp
as $function$
declare
  resolved text;
begin
  select dm.model_id into resolved
  from private.v2_rpc_models_compat dm
  where dm.model_id = p_model_id limit 1;
  if resolved is not null and btrim(resolved) <> '' then return resolved; end if;

  select a.model_slug into resolved
  from public.v2_model_aliases a
  where a.alias_slug = p_model_id and coalesce(a.enabled, true) limit 1;
  if resolved is not null and btrim(resolved) <> '' then return resolved; end if;

  select coalesce(nullif(pm.model_id, ''), pm.api_model_id) into resolved
  from private.v2_rpc_routes_compat pm
  where (p_provider is null or pm.provider_id = p_provider)
    and (pm.model_id = p_model_id or pm.api_model_id = p_model_id
      or pm.provider_api_model_id = p_model_id or pm.provider_model_slug = p_model_id)
  order by pm.is_active_gateway desc, pm.updated_at desc nulls last limit 1;
  if resolved is not null and btrim(resolved) <> '' then return resolved; end if;
  return null;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."resolve_public_model_id"(text, text) TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."resolve_public_model_id"(text, text) TO "service_role";

COMMENT ON FUNCTION "public"."resolve_public_model_id"(text, text) IS 'Resolves canonical public model ids from canonical ids, aliases, and provider-facing model identifiers only.';

-- source: supabase/schemas/public/functions/resolve_v2_effective_pricing_plan.sql
CREATE OR REPLACE FUNCTION public.resolve_v2_effective_pricing_plan (
  p_fact_tier text,
  p_sku_tier  text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select case lower(nullif(trim(p_sku_tier), ''))
    when 'free' then 'free'
    else coalesce(
      public.normalize_v2_service_tier(p_fact_tier),
      public.normalize_v2_service_tier(p_sku_tier),
      'standard'
    )
  end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."resolve_v2_effective_pricing_plan"(text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."resolve_v2_effective_pricing_plan"(text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/restore_provider_catalog_feed.sql
CREATE OR REPLACE FUNCTION public.restore_provider_catalog_feed(
  p_provider_slug text, p_actor_id uuid, p_actor_kind text, p_expected_version timestamptz
) RETURNS void LANGUAGE plpgsql SET search_path TO 'public' AS $function$
declare source public.provider_catalog_sources%rowtype; actor_name text;
begin
  select * into source from public.provider_catalog_sources where provider_slug=p_provider_slug for update;
  if not found or source.catalog_url is null then raise exception 'provider_catalog_remote_source_required'; end if;
  if p_expected_version is distinct from coalesce(source.managed_updated_at,source.updated_at) then raise exception 'provider_catalog_version_conflict'; end if;
  if p_actor_id is null or p_actor_kind not in ('phaseo','provider') then raise exception 'provider_catalog_actor_required'; end if;
  if source.management_mode='remote' then return; end if;
  select display_name into actor_name from public.users where user_id=p_actor_id;
  insert into public.provider_catalog_edit_events(provider_slug,model_slug,field,actor_id,actor_kind,actor_name,action,previous_value,value)
  values(p_provider_slug,'*','$catalog',p_actor_id,p_actor_kind,actor_name,'revert',source.managed_catalog,source.feed_models);
  update public.provider_catalog_sources set management_mode='remote',managed_catalog=null,managed_updated_by=null,managed_updated_at=null,catalog_updated_at=now(),refresh_requested=true,next_poll_at=now(),updated_at=now() where provider_slug=p_provider_slug;
end;
$function$;

REVOKE ALL ON FUNCTION public.restore_provider_catalog_feed(text,uuid,text,timestamptz) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.restore_provider_catalog_feed(text,uuid,text,timestamptz) TO service_role;

-- source: supabase/schemas/public/functions/review_provider_application.sql
CREATE OR REPLACE FUNCTION public.review_provider_application (
  p_provider_slug text,
  p_decision      text,
  p_reason        text,
  p_reviewed_by   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  latest_submission public.provider_onboarding_submissions%rowtype;
  source_row public.provider_catalog_sources%rowtype;
  reviewed_at_value timestamptz := now();
  review_message_value text;
  source_created_value boolean := false;
  claim_workspace_id uuid;
  claim_previously_approved boolean := false;
begin
  if p_decision not in ('approved', 'paused', 'rejected', 'needs_changes') then
    raise exception 'invalid_provider_review_decision';
  end if;
  if p_decision <> 'approved' and nullif(btrim(p_reason), '') is null then
    raise exception 'provider_review_reason_required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_provider_slug, 0));
  select * into latest_submission
  from public.provider_onboarding_submissions
  where provider_slug = p_provider_slug
  order by created_at desc
  limit 1
  for update;
  if not found then
    return public.set_self_serve_provider_review(p_provider_slug, p_decision, p_reason, p_reviewed_by);
  end if;
  select exists (
    select 1
    from public.provider_account_links link
    where link.provider_slug = p_provider_slug
      and link.linked_by = latest_submission.submitted_by
      and link.role = 'owner'
      and link.proof_method = 'domain_file'
      and link.status = 'active'
  ) into claim_previously_approved;

  perform 1 from public.v2_providers where provider_slug = p_provider_slug for update;
  if not found then raise exception 'self_serve_provider_not_found'; end if;

  if latest_submission.application_type <> 'claim' then
    update public.provider_onboarding_submissions
    set provider_review_status = p_decision,
        provider_review_reason = case when p_decision = 'approved' then null else btrim(p_reason) end,
        provider_reviewed_by = p_reviewed_by,
        provider_reviewed_at = reviewed_at_value,
        pending_webhook_secret_ciphertext = null,
        pending_webhook_secret_iv = null,
        pending_webhook_secret_hash = null,
      updated_at = reviewed_at_value
    where id = latest_submission.id;
    return public.set_self_serve_provider_review(p_provider_slug, p_decision, p_reason, p_reviewed_by)
      || jsonb_build_object('applicationType', latest_submission.application_type);
  end if;

  update public.provider_onboarding_submissions
  set provider_review_status = p_decision,
      provider_review_reason = case when p_decision = 'approved' then null else btrim(p_reason) end,
      provider_reviewed_by = p_reviewed_by,
      provider_reviewed_at = reviewed_at_value,
      updated_at = reviewed_at_value
  where id = latest_submission.id;

  if p_decision = 'approved' then
    select workspace_id into claim_workspace_id
    from public.provider_account_links
    where provider_slug = p_provider_slug
      and linked_by = latest_submission.submitted_by
      and role = 'owner'
      and status = 'pending'
      and proof_method = 'domain_file'
    order by verified_at desc nulls last, created_at desc
    limit 1
    for update;
    if found then
      update public.provider_account_links
      set status = 'revoked', updated_at = reviewed_at_value
      where provider_slug = p_provider_slug
        and role = 'owner'
        and status = 'active'
        and workspace_id <> claim_workspace_id;
      update public.provider_account_links
      set status = 'active',
          verified_at = coalesce(verified_at, reviewed_at_value),
          updated_at = reviewed_at_value
      where provider_slug = p_provider_slug
        and workspace_id = claim_workspace_id
        and linked_by = latest_submission.submitted_by
        and status = 'pending';
    end if;

    update public.v2_providers provider
    set name = latest_submission.provider_name,
        metadata = (coalesce(provider.metadata, '{}'::jsonb) - 'self_serve')
          || jsonb_build_object(
            'website_url', latest_submission.website_url,
            'logo_url', latest_submission.logo_url,
            'catalog_url', latest_submission.catalog_url,
            'catalog_sha256', latest_submission.catalog_sha256,
            'last_submitted_by', latest_submission.submitted_by,
            'last_submitted_at', latest_submission.submitted_at
          ),
        updated_at = reviewed_at_value
    where provider.provider_slug = p_provider_slug;

    select * into source_row
    from public.provider_catalog_sources
    where provider_slug = p_provider_slug
    for update;
    if found then
      update public.provider_catalog_sources source
      set catalog_url = case when latest_submission.catalog_mode = 'remote' then latest_submission.catalog_url else null end,
          management_mode = latest_submission.catalog_mode,
          managed_catalog = case
            when latest_submission.catalog_mode = 'remote' then null
            when source.management_mode = 'managed' and source.managed_catalog is not null then source.managed_catalog
            else '{"data":[]}'::jsonb
          end,
          managed_updated_by = case when latest_submission.catalog_mode = 'managed' then latest_submission.submitted_by else null end,
          managed_updated_at = case
            when latest_submission.catalog_mode = 'managed' then coalesce(source.managed_updated_at, reviewed_at_value)
            else null
          end,
          status = 'active',
          etag = null,
          last_modified = null,
          last_error = null,
          consecutive_failures = 0,
          refresh_requested = true,
          next_poll_at = case when latest_submission.catalog_mode = 'remote' then reviewed_at_value else null end,
          updated_at = reviewed_at_value
      where source.provider_slug = p_provider_slug;
    else
      insert into public.provider_catalog_sources (
        provider_slug, catalog_url, management_mode, managed_catalog,
        managed_updated_by, managed_updated_at, status, delivery_mode, created_by,
        webhook_secret_ciphertext, webhook_secret_iv, webhook_secret_hash, next_poll_at,
        refresh_requested, updated_at
      ) values (
        p_provider_slug,
        case when latest_submission.catalog_mode = 'remote' then latest_submission.catalog_url else null end,
        latest_submission.catalog_mode,
        case when latest_submission.catalog_mode = 'managed' then '{"data":[]}'::jsonb else null end,
        case when latest_submission.catalog_mode = 'managed' then latest_submission.submitted_by else null end,
        case when latest_submission.catalog_mode = 'managed' then reviewed_at_value else null end,
        'active', 'webhook_and_polling', latest_submission.submitted_by,
        latest_submission.pending_webhook_secret_ciphertext,
        latest_submission.pending_webhook_secret_iv,
        latest_submission.pending_webhook_secret_hash,
        case when latest_submission.catalog_mode = 'remote' then reviewed_at_value else null end,
        true, reviewed_at_value
      );
      source_created_value := true;
    end if;
  elsif p_decision = 'paused' and claim_previously_approved then
    -- A pause after ownership approval is an explicit provider-level action.
    -- Keep the catalog rows intact so they can be reviewed or re-enabled later.
    update public.v2_providers
    set status = 'not_ready', routable = false, routing_enabled = false,
        updated_at = reviewed_at_value
    where provider_slug = p_provider_slug;
    update public.provider_catalog_sources
    set status = 'paused', refresh_requested = false, next_poll_at = null, updated_at = reviewed_at_value
    where provider_slug = p_provider_slug;
  end if;

  update public.provider_onboarding_submissions
  set pending_webhook_secret_ciphertext = null,
      pending_webhook_secret_iv = null,
      pending_webhook_secret_hash = null
  where id = latest_submission.id;

  select case p_decision
    when 'approved' then 'Your provider claim is approved. Validated catalog updates now apply automatically. Public routing requires configured endpoints, adapters, credentials, and prices.'
    when 'needs_changes' then 'Phaseo requested changes to your provider claim: ' || btrim(p_reason)
    when 'rejected' then 'Phaseo rejected your provider claim: ' || btrim(p_reason)
    else 'Phaseo paused your provider claim: ' || btrim(p_reason)
  end into review_message_value;

  insert into public.provider_catalog_events (
    provider_slug, account_user_id, workspace_id, event_type, title, message, payload
  )
  select p_provider_slug, latest_submission.submitted_by, link.workspace_id, 'provider_application_reviewed',
    'Provider claim ' || replace(p_decision, '_', ' '), review_message_value,
    jsonb_build_object('decision', p_decision, 'reason', case when p_decision = 'approved' then null else p_reason end)
  from public.provider_account_links link
  where link.provider_slug = p_provider_slug
    and link.linked_by = latest_submission.submitted_by
    and link.role = 'owner'
    and link.status in ('pending', 'active');

  if p_decision = 'rejected' and not claim_previously_approved then
    update public.provider_account_links
    set status = 'revoked', updated_at = reviewed_at_value
    where provider_slug = p_provider_slug
      and linked_by = latest_submission.submitted_by
      and role = 'owner'
      and proof_method = 'domain_file'
      and status = 'pending';
  end if;

  return jsonb_build_object(
    'providerSlug', p_provider_slug,
    'decision', p_decision,
    'applicationType', 'claim',
    'sourceCreated', source_created_value,
    'providerWorkspaceId', claim_workspace_id
  );
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."review_provider_application"(text, text, text, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."review_provider_application"(text, text, text, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/review_provider_catalog_model_request.sql
CREATE OR REPLACE FUNCTION public.review_provider_catalog_model_request(p_request_id uuid,p_decision text,p_reason text,p_reviewed_by uuid,p_expected_updated_at timestamptz DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SET search_path TO public AS $function$
declare proposal public.provider_catalog_model_requests; provider_id text;
begin
  if p_decision not in ('approved','rejected','needs_changes') then raise exception 'invalid_model_review_decision'; end if;
  if p_decision <> 'approved' and nullif(btrim(p_reason),'') is null then raise exception 'model_review_reason_required'; end if;
  select provider_slug into provider_id from public.provider_catalog_model_requests where id=p_request_id;
  perform 1 from public.v2_providers where provider_slug=provider_id for update;
  select * into proposal from public.provider_catalog_model_requests where id=p_request_id for update;
  if not found or proposal.status='withdrawn' then raise exception 'model_request_unavailable'; end if;
  if p_expected_updated_at is not null and proposal.updated_at <> p_expected_updated_at then raise exception 'model_request_changed'; end if;
  if not exists(select 1 from public.provider_catalog_models where provider_slug=proposal.provider_slug and model_slug=proposal.model_slug and status='active' and source_run_id=proposal.source_run_id) then raise exception 'model_request_superseded'; end if;
  if p_decision='approved' then
    insert into public.v2_labs(lab_slug,name,status,routable,metadata)
    values(split_part(lower(proposal.model_slug),'/',1),split_part(lower(proposal.model_slug),'/',1),'disabled',false,'{"created_from_provider_proposal":true}') on conflict(lab_slug) do nothing;
    insert into public.v2_models(model_slug,lab_slug,name,description,status,hidden,input_modalities,output_modalities,variant_kind,metadata)
    values(lower(proposal.model_slug),split_part(lower(proposal.model_slug),'/',1),proposal.model->>'name',proposal.model->>'description','active',true,
      array(select jsonb_array_elements_text(proposal.model->'inputModalities')),
      array(select jsonb_array_elements_text(proposal.model->'outputModalities')),
      case when proposal.model_slug like '%:free' then 'free' else 'standard' end,
      jsonb_build_object('created_from_provider_proposal',true,'provider_catalog_owner',proposal.provider_slug,'approved_request_id',proposal.id))
    on conflict(model_slug) do nothing;
    update public.provider_catalog_sources set refresh_requested=true,next_poll_at=now(),updated_at=now() where provider_slug=proposal.provider_slug;
  end if;
  update public.provider_catalog_model_requests set status=p_decision,reason=case when p_decision='approved' then null else p_reason end,reviewed_by=p_reviewed_by,reviewed_at=now(),updated_at=now() where id=proposal.id;
  update public.provider_catalog_sync_models set decision=p_decision,decision_reason=p_reason,reviewed_by=p_reviewed_by,reviewed_at=now() where run_id=proposal.source_run_id and model_slug=proposal.model_slug;
  insert into public.provider_catalog_review_events(run_id,model_slug,decision,reason,actor_user_id) values(proposal.source_run_id,proposal.model_slug,p_decision,p_reason,p_reviewed_by);
  return proposal.provider_slug;
end;
$function$;

REVOKE ALL ON FUNCTION public.review_provider_catalog_model_request(uuid,text,text,uuid,timestamptz) FROM PUBLIC,anon,authenticated;

GRANT EXECUTE ON FUNCTION public.review_provider_catalog_model_request(uuid,text,text,uuid,timestamptz) TO service_role;

-- source: supabase/schemas/public/functions/review_v2_catalogue_price_proposal.sql
CREATE OR REPLACE FUNCTION public.review_v2_catalogue_price_proposal (
  p_actor_user_id uuid,
  p_proposal_id   text,
  p_accept        boolean
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare v_proposal public.v2_catalogue_price_proposals%rowtype; v_model text; v_current jsonb; v_result jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  select * into v_proposal from public.v2_catalogue_price_proposals where proposal_id=p_proposal_id;
  if not found then raise exception 'proposal is no longer pending'; end if;
  perform pg_advisory_xact_lock(hashtextextended('catalogue-proposal:'||v_proposal.provider_model_id||':'||(v_proposal.sku->>'sku_code'),0));
  select * into v_proposal from public.v2_catalogue_price_proposals where proposal_id=p_proposal_id for update;
  if not found or v_proposal.status<>'pending' then raise exception 'proposal is no longer pending'; end if;
  if p_accept then
    select model_slug into v_model from public.v2_model_provider_routes where provider_model_id=v_proposal.provider_model_id for update;
    select to_jsonb(s) into v_current from public.v2_pricing_skus s where s.provider_model_id=v_proposal.provider_model_id and s.sku_code=v_proposal.sku->>'sku_code' and effective_to is null order by version desc limit 1 for update;
    if v_current is distinct from v_proposal.expected_sku then raise exception 'Pricing changed since this proposal. Refresh the provider feed.'; end if;
    v_result:=public.mutate_v2_admin_pricing_sku(p_actor_user_id,v_model,'save',v_proposal.sku||jsonb_build_object('effective_from',now()));
  end if;
  update public.v2_catalogue_price_proposals set status=case when p_accept then 'accepted' else 'dismissed' end,reviewed_by=p_actor_user_id,reviewed_at=now() where proposal_id=p_proposal_id;
  return coalesce(v_result,'{}'::jsonb);
end $function$;

GRANT EXECUTE ON FUNCTION "public"."review_v2_catalogue_price_proposal"(uuid, text, boolean) TO "service_role";

REVOKE ALL ON FUNCTION "public"."review_v2_catalogue_price_proposal"(uuid, text, boolean) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/revoke_oauth_delegated_refresh_on_scope_loss.sql
CREATE OR REPLACE FUNCTION public.revoke_oauth_delegated_refresh_on_scope_loss()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  -- Runs while this update holds the authorization row, which a refresh locks first, so no refresh
  -- can slip in between. Same order as consent revocation: authorization -> keys -> refresh tokens.
  --
  -- Without gateway:access, a credit-spending key (unbound, or bound to the Gateway) is revoked
  -- outright, paused and disabled ones included, so its current access token stops spending too and
  -- granting the scope again never revives it. Keys bound to another resource don't spend credits.
  if not (coalesce(new.scopes, array[]::text[]) @> array['gateway:access']::text[]) then
    update public.keys key_row
    set status = 'revoked'
    where key_row.key_kind = 'oauth_delegated'
      and key_row.oauth_user_id = new.user_id
      and key_row.workspace_id = new.workspace_id
      and key_row.oauth_client_id = new.client_id
      and key_row.status not in ('revoked', 'compromised', 'deleted')
      and (
        nullif(btrim(key_row.oauth_resource), '') is null
        or coalesce(btrim(key_row.oauth_resource) ~* '^https://api\.phaseo\.app(?::443)?/v1/*$', false)
      );
  end if;

  -- The same test as rotate_oauth_delegated_refresh_token: nothing left in common, or a
  -- credit-spending key without gateway:access, ends the token's chain for good.
  update public.oauth_refresh_tokens refresh_token
  set revoked_at = now()
  from public.keys key_row
  where key_row.id = refresh_token.key_id
    and refresh_token.user_id = new.user_id
    and refresh_token.workspace_id = new.workspace_id
    and refresh_token.client_id = new.client_id
    and refresh_token.revoked_at is null
    and (
      not exists (
        select 1
        from unnest(coalesce(new.scopes, array[]::text[])) as scope
        where scope = any(refresh_token.scopes)
          and scope = any(coalesce(key_row.oauth_scopes, array[]::text[]))
      )
      or (
        (
          nullif(btrim(key_row.oauth_resource), '') is null
          or coalesce(btrim(key_row.oauth_resource) ~* '^https://api\.phaseo\.app(?::443)?/v1/*$', false)
        )
        and not (coalesce(new.scopes, array[]::text[]) @> array['gateway:access']::text[])
      )
    );

  return null;
end;
$function$;

COMMENT ON FUNCTION "public"."revoke_oauth_delegated_refresh_on_scope_loss"() IS 'When an app''s authorization loses a scope its delegated keys need, ends those keys'' refresh tokens (every scope a token holds gone, or gateway:access gone for a credit-spending key), and without gateway:access revokes its credit-spending keys too, so granting the scope again later never revives them.';

REVOKE ALL ON FUNCTION "public"."revoke_oauth_delegated_refresh_on_scope_loss"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/revoke_oauth_grant_on_authorization_revoke.sql
CREATE OR REPLACE FUNCTION public.revoke_oauth_grant_on_authorization_revoke()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  -- Same order as the member-delete trigger: authorization -> keys -> refresh tokens. Paused and
  -- disabled keys are revoked too, so turning one back on can't bring back the app's access.
  update public.keys
  set status = 'revoked'
  where key_kind = 'oauth_delegated'
    and oauth_user_id = old.user_id
    and workspace_id = old.workspace_id
    and oauth_client_id = old.client_id
    and status not in ('revoked', 'compromised', 'deleted');

  update public.oauth_refresh_tokens
  set revoked_at = coalesce(revoked_at, now())
  where user_id = old.user_id
    and workspace_id = old.workspace_id
    and client_id = old.client_id
    and revoked_at is null;

  return null;
end;
$function$;

COMMENT ON FUNCTION "public"."revoke_oauth_grant_on_authorization_revoke"() IS 'When someone revokes or deletes an app''s authorization, revokes that app''s delegated keys and refresh tokens in the workspace, so authorizing the app again later never revives them.';

REVOKE ALL ON FUNCTION "public"."revoke_oauth_grant_on_authorization_revoke"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/revoke_oauth_on_workspace_member_delete.sql
CREATE OR REPLACE FUNCTION public.revoke_oauth_on_workspace_member_delete()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  update public.oauth_authorizations
  set revoked_at = coalesce(revoked_at, now())
  where user_id = old.user_id
    and workspace_id = old.workspace_id
    and revoked_at is null;

  update public.oauth_refresh_tokens
  set revoked_at = coalesce(revoked_at, now())
  where user_id = old.user_id
    and workspace_id = old.workspace_id
    and revoked_at is null;

  return old;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."revoke_oauth_on_workspace_member_delete"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."revoke_oauth_on_workspace_member_delete"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/revoke_oauth_refresh_token_grant.sql
CREATE OR REPLACE FUNCTION public.revoke_oauth_refresh_token_grant (
  p_token_hashes text[]
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  token_identity public.oauth_refresh_tokens%rowtype;
  current_token public.oauth_refresh_tokens%rowtype;
begin
  -- Any token of the grant identifies it, even one already rotated, so a logout that races a
  -- refresh still ends the token that refresh issued. Read it without a row lock.
  select * into token_identity
  from public.oauth_refresh_tokens
  where token_hash = any(coalesce(p_token_hashes, array[]::text[]))
  limit 1;

  if not found then
    return 'not_found';
  end if;

  -- Lock in the order every OAuth grant change uses (the member-delete trigger, the code exchange,
  -- both refresh-token rotations): membership -> authorization -> key -> refresh tokens. Holding
  -- the authorization first waits out any refresh, renewal or replay of this grant in flight, so
  -- this never holds a token lock one of them is waiting for, and the updates below see the
  -- tokens it committed.
  perform 1
  from public.workspace_members member
  where member.user_id = token_identity.user_id
    and member.workspace_id = token_identity.workspace_id
  for key share;

  perform 1
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = token_identity.user_id
    and authorization_row.workspace_id = token_identity.workspace_id
    and authorization_row.client_id = token_identity.client_id
  for update;

  if token_identity.key_id is null then
    update public.oauth_refresh_tokens
    set revoked_at = now()
    where family_id = token_identity.family_id
      and revoked_at is null;
    return 'revoked';
  end if;

  perform 1
  from public.keys key_row
  where key_row.id = token_identity.key_id
  for update;

  select * into current_token
  from public.oauth_refresh_tokens
  where id = token_identity.id;

  -- Approving the app again retired this token's family and renewed the key with a new one. That
  -- sign-in is already over, and its token doesn't speak for the one that replaced it.
  if not found or current_token.revoked_reason = 'superseded' then
    return 'revoked';
  end if;

  update public.oauth_refresh_tokens
  set revoked_at = now()
  where (key_id = token_identity.key_id or family_id = token_identity.family_id)
    and revoked_at is null;

  -- The app gave up its access: end its delegated key too, even a paused one.
  update public.keys
  set status = 'revoked', revoked_reason = 'oauth_token_revoked'
  where id = token_identity.key_id
    and key_kind = 'oauth_delegated'
    and status not in ('revoked', 'compromised', 'deleted');

  return 'revoked';
end;
$function$;

COMMENT ON FUNCTION "public"."revoke_oauth_refresh_token_grant"(text[]) IS 'RFC 7009 revocation of an OAuth refresh token, in one transaction: revokes the token''s whole family and, for a third-party app''s token, its delegated gateway key and every refresh token bound to it. Matches a token even if it was already rotated; a token from a family that re-approving the app superseded revokes nothing more. Locks the authorization before any key or token, like the rotations. Returns revoked or not_found.';

GRANT EXECUTE ON FUNCTION "public"."revoke_oauth_refresh_token_grant"(text[]) TO "service_role";

REVOKE ALL
  ON FUNCTION "public"."revoke_oauth_refresh_token_grant"(text[])
  FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/revoke_oauth_refresh_tokens_for_inactive_key.sql
CREATE OR REPLACE FUNCTION public.revoke_oauth_refresh_tokens_for_inactive_key()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  update public.oauth_refresh_tokens
  set revoked_at = coalesce(revoked_at, now())
  where key_id = new.id
    and revoked_at is null;

  return new;
end;
$function$;

COMMENT ON FUNCTION "public"."revoke_oauth_refresh_tokens_for_inactive_key"() IS 'Ends the refresh tokens of a delegated OAuth key once it is revoked, disabled, paused or deleted, so the app cannot renew it. Turning the key back on does not revive them.';

REVOKE ALL ON FUNCTION "public"."revoke_oauth_refresh_tokens_for_inactive_key"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/rls_auto_enable.sql
CREATE OR REPLACE FUNCTION public.rls_auto_enable()
  RETURNS event_trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'pg_catalog'
  AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

GRANT EXECUTE ON FUNCTION "public"."rls_auto_enable"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."rls_auto_enable"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/rotate_oauth_delegated_refresh_token.sql
CREATE OR REPLACE FUNCTION public.rotate_oauth_delegated_refresh_token (
  p_current_token_hash text,
  p_next_token_hash    text,
  p_next_expires_at    timestamp with time zone,
  p_key_hash           text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  token_identity public.oauth_refresh_tokens%rowtype;
  current_token public.oauth_refresh_tokens%rowtype;
  delegated_key public.keys%rowtype;
  granted_scopes text[];
  resource_is_gateway boolean;
  key_expires_at timestamp with time zone := now() + interval '7 days';
begin
  if nullif(btrim(p_next_token_hash), '') is null or nullif(btrim(p_key_hash), '') is null then
    return jsonb_build_object('status', 'invalid');
  end if;

  -- Read identity without a row lock, then lock in the order every OAuth grant change uses (the
  -- member-delete trigger, the code exchange, revoke_oauth_refresh_token_grant):
  -- membership -> authorization -> key -> token.
  select * into token_identity
  from public.oauth_refresh_tokens
  where token_hash = p_current_token_hash;

  if not found or token_identity.key_id is null then
    return jsonb_build_object('status', 'invalid');
  end if;

  perform 1
  from public.workspace_members member
  where member.user_id = token_identity.user_id
    and member.workspace_id = token_identity.workspace_id
  for key share;

  if not found then
    return jsonb_build_object('status', 'invalid');
  end if;

  select authorization_row.scopes into granted_scopes
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = token_identity.user_id
    and authorization_row.workspace_id = token_identity.workspace_id
    and authorization_row.client_id = token_identity.client_id
    and authorization_row.revoked_at is null
  for update;

  if not found then
    return jsonb_build_object('status', 'invalid');
  end if;

  select * into delegated_key
  from public.keys key_row
  where key_row.id = token_identity.key_id
  for update;

  if not found then
    return jsonb_build_object('status', 'invalid');
  end if;

  -- Re-read and validate after acquiring locks because another rotation may
  -- have changed this token between the initial identity read and this lock.
  select * into current_token
  from public.oauth_refresh_tokens
  where token_hash = p_current_token_hash
  for update;

  if not found
    or current_token.user_id <> token_identity.user_id
    or current_token.workspace_id <> token_identity.workspace_id
    or current_token.client_id <> token_identity.client_id
    or current_token.key_id is distinct from token_identity.key_id then
    return jsonb_build_object('status', 'invalid');
  end if;

  if current_token.revoked_at is not null then
    -- Approving the app again retired this token's family and renewed the key with a new one. That
    -- sign-in is over, so its token is just refused: the key and the family that replaced it stay.
    if current_token.revoked_reason = 'superseded' then
      return jsonb_build_object('status', 'invalid');
    end if;

    update public.oauth_refresh_tokens
    set revoked_at = coalesce(revoked_at, now())
    where family_id = current_token.family_id;

    -- Presented again after it was rotated (only rotation sets last_used_at), the token may
    -- have leaked: end the key it renews too, even a paused one, so turning it back on can't
    -- revive it. A token revoked any other way just fails.
    if current_token.last_used_at is not null then
      update public.keys
      set status = 'revoked', revoked_reason = 'oauth_refresh_token_reused'
      where id = delegated_key.id
        and status not in ('revoked', 'compromised', 'deleted');
      return jsonb_build_object('status', 'reused');
    end if;
    return jsonb_build_object('status', 'invalid');
  end if;

  if current_token.expires_at is not null and current_token.expires_at <= now() then
    update public.oauth_refresh_tokens set revoked_at = now() where id = current_token.id;
    return jsonb_build_object('status', 'invalid');
  end if;

  -- Revoking, disabling or deleting the key ends its refresh tokens; a refresh never revives it.
  if delegated_key.status <> 'active'
    or delegated_key.key_kind <> 'oauth_delegated'
    or delegated_key.oauth_user_id is distinct from current_token.user_id
    or delegated_key.workspace_id <> current_token.workspace_id
    or delegated_key.oauth_client_id is distinct from current_token.client_id then
    update public.oauth_refresh_tokens
    set revoked_at = coalesce(revoked_at, now())
    where family_id = current_token.family_id;
    return jsonb_build_object('status', 'invalid');
  end if;

  -- Never widen on refresh: keep the scopes this token and its key already hold that the
  -- authorization still grants.
  granted_scopes := array(
    select scope from unnest(coalesce(granted_scopes, array[]::text[])) as scope
    where scope = any(current_token.scopes)
      and scope = any(coalesce(delegated_key.oauth_scopes, array[]::text[]))
  );

  resource_is_gateway := coalesce(
    btrim(delegated_key.oauth_resource) ~* '^https://api\.phaseo\.app(?::443)?/v1/*$',
    false
  );

  -- An unbound or Gateway-bound key spends credits, so it needs gateway:access consent. Losing a
  -- required scope ends the chain for good, so consenting to the scope again doesn't revive it.
  if coalesce(cardinality(granted_scopes), 0) = 0
    or (
      (nullif(btrim(delegated_key.oauth_resource), '') is null or resource_is_gateway)
      and not (granted_scopes @> array['gateway:access']::text[])
    ) then
    update public.oauth_refresh_tokens
    set revoked_at = coalesce(revoked_at, now())
    where family_id = current_token.family_id;
    return jsonb_build_object('status', 'invalid');
  end if;

  update public.oauth_refresh_tokens
  set revoked_at = now(), last_used_at = now()
  where id = current_token.id;

  insert into public.oauth_refresh_tokens (
    token_hash, user_id, workspace_id, client_id, scopes, expires_at,
    rotated_from, family_id, key_id
  ) values (
    p_next_token_hash, current_token.user_id, current_token.workspace_id,
    current_token.client_id, granted_scopes, p_next_expires_at,
    current_token.id, current_token.family_id, current_token.key_id
  );

  -- Same key row, new secret: the previous access token stops working now, and the key's
  -- limits, history and Settings entry carry over.
  update public.keys
  set hash = p_key_hash,
    oauth_scopes = granted_scopes,
    expires_at = key_expires_at
  where id = delegated_key.id;

  return jsonb_build_object(
    'status', 'rotated',
    'kid', delegated_key.kid,
    'scopes', to_jsonb(granted_scopes),
    'resource', delegated_key.oauth_resource,
    'expires_at', key_expires_at
  );
end;
$function$;

COMMENT ON FUNCTION "public"."rotate_oauth_delegated_refresh_token"(text, text, timestamp WITH time zone, text) IS 'Refreshes a third-party app''s delegated gateway key: rotates the refresh token and replaces the same key''s secret, extending it 7 days. Scopes only narrow, and losing a required scope ends the chain. A reused refresh token revokes its chain and the key; a token from a family that re-approving the app superseded is just invalid. Returns {status: rotated|reused|invalid, ...}.';

GRANT EXECUTE ON FUNCTION "public"."rotate_oauth_delegated_refresh_token"(text, text, timestamp WITH time zone, text) TO "service_role";

REVOKE ALL
  ON FUNCTION "public"."rotate_oauth_delegated_refresh_token"(text, text, timestamp WITH time zone, text)
  FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/rotate_oauth_refresh_token.sql
CREATE OR REPLACE FUNCTION public.rotate_oauth_refresh_token (
  p_current_token_hash text,
  p_next_token_hash    text,
  p_next_expires_at    timestamp with time zone,
  p_scopes             text[]
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  token_identity public.oauth_refresh_tokens%rowtype;
  current_token public.oauth_refresh_tokens%rowtype;
  token_family uuid;
  granted_scopes text[];
begin
  -- Read identity without a row lock. Taking the token lock here would invert
  -- the member-delete trigger's membership -> authorization -> token order.
  select * into token_identity
  from public.oauth_refresh_tokens
  where token_hash = p_current_token_hash;

  if not found then
    return 'invalid';
  end if;

  -- A delegated key's refresh token rotates only through rotate_oauth_delegated_refresh_token,
  -- which keeps it bound to its key. A Worker from before that function (during a deploy or a
  -- rollback) still calls this one: refuse it, before any lock or write, rather than mint a
  -- successor with no key that pausing or revoking the key would no longer end.
  if token_identity.key_id is not null then
    return 'invalid';
  end if;

  perform 1
  from public.workspace_members member
  where member.user_id = token_identity.user_id
    and member.workspace_id = token_identity.workspace_id
  for key share;

  if not found then
    return 'invalid';
  end if;

  select authorization_row.scopes into granted_scopes
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = token_identity.user_id
    and authorization_row.workspace_id = token_identity.workspace_id
    and authorization_row.client_id = token_identity.client_id
    and authorization_row.revoked_at is null
  for update;

  if not found then
    return 'invalid';
  end if;

  -- Re-read and validate after acquiring locks because another rotation may
  -- have changed this token between the initial identity read and this lock.
  select * into current_token
  from public.oauth_refresh_tokens
  where token_hash = p_current_token_hash
  for update;

  if not found
    or current_token.user_id <> token_identity.user_id
    or current_token.workspace_id <> token_identity.workspace_id
    or current_token.client_id <> token_identity.client_id then
    return 'invalid';
  end if;

  token_family := coalesce(current_token.family_id, current_token.id);

  if current_token.revoked_at is not null then
    update public.oauth_refresh_tokens
    set revoked_at = coalesce(revoked_at, now())
    where family_id = token_family;
    return 'reused';
  end if;

  if current_token.expires_at is not null and current_token.expires_at <= now() then
    update public.oauth_refresh_tokens set revoked_at = now() where id = current_token.id;
    return 'invalid';
  end if;

  -- Never widen a session on refresh: the new token keeps the scopes of the token it replaces
  -- that the authorization still grants. Only a NULL scope list counts as legacy; it keeps the
  -- authorization's scopes minus opt-in ones (billing:write), which need a new login. An empty
  -- result is refused rather than stored, since an empty list must never grant anything later.
  granted_scopes := case
    when current_token.scopes is null then array_remove(granted_scopes, 'billing:write')
    else array(
      select scope from unnest(granted_scopes) as scope
      where scope = any(current_token.scopes)
    )
  end;
  if coalesce(cardinality(granted_scopes), 0) = 0 then
    return 'invalid';
  end if;

  update public.oauth_refresh_tokens
  set revoked_at = now(), last_used_at = now()
  where id = current_token.id;

  insert into public.oauth_refresh_tokens (
    token_hash, user_id, workspace_id, client_id, scopes, expires_at,
    rotated_from, family_id
  ) values (
    p_next_token_hash, current_token.user_id, current_token.workspace_id,
    current_token.client_id, granted_scopes, p_next_expires_at,
    current_token.id, token_family
  );

  return 'rotated';
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."rotate_oauth_refresh_token"(text, text, timestamp WITH time zone, text[]) TO "service_role";

REVOKE ALL ON FUNCTION "public"."rotate_oauth_refresh_token"(text, text, timestamp WITH time zone, text[]) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/save_provider_catalog_overrides.sql
CREATE OR REPLACE FUNCTION public.save_provider_catalog_overrides(
  p_provider_slug text, p_actor_id uuid, p_actor_kind text, p_expected_version timestamptz, p_changes jsonb, p_feed_models jsonb DEFAULT NULL
) RETURNS void LANGUAGE plpgsql SET search_path TO 'public' AS $function$
declare
  source public.provider_catalog_sources%rowtype;
  change jsonb;
  model_id text;
  field_name text;
  old_value jsonb;
  fields jsonb;
  actor_name text;
  feed_value jsonb;
  feed_model jsonb;
begin
  select * into source from public.provider_catalog_sources where provider_slug = p_provider_slug for update;
  if not found or source.management_mode <> 'remote' then raise exception 'provider_catalog_remote_source_required'; end if;
  if p_actor_kind not in ('phaseo','provider') or p_actor_id is null then raise exception 'provider_catalog_actor_required'; end if;
  select display_name into actor_name from public.users where user_id=p_actor_id;
  if p_expected_version is null or p_expected_version <> coalesce(source.catalog_updated_at,source.updated_at) then raise exception 'provider_catalog_version_conflict'; end if;
  if jsonb_typeof(p_changes) <> 'array' or jsonb_array_length(p_changes) > 16000 then raise exception 'provider_catalog_changes_invalid'; end if;
  source.feed_models := coalesce(source.feed_models,p_feed_models);
  for change in select value from jsonb_array_elements(p_changes) loop
    model_id := change->>'model_id'; field_name := change->>'field';
    if model_id is null or field_name is null or (field_name not in ('$model','$removed','name','description','providerModelSlug','inputModalities','outputModalities','contextLength','maxOutputTokens','availability','availableFrom','deprecatedAt','shutdownAt','capabilities','pricing','serviceTiers')
      and field_name !~ '^/pricing/[^/]+(/(modality|direction|unit|unitQuantity|priceNanos|[$]rate|displayLabel|displayUnit|conditions))?$'
      and field_name !~ '^/serviceTiers/(standard|fast|ultrafast|flex|batch)(/(providerModelSlug|upstreamServiceTier|availability)|/pricing/[^/]+(/(modality|direction|unit|unitQuantity|priceNanos|[$]rate|displayLabel|displayUnit|conditions))?)?$') then raise exception 'provider_catalog_override_field_invalid'; end if;
    fields := coalesce(source.catalog_overrides->model_id, '{}'::jsonb);
    old_value := fields->field_name;
    select model into feed_model from jsonb_array_elements(coalesce(source.feed_models,'[]'::jsonb)) model where model->>'id'=model_id limit 1;
    feed_value := public.provider_catalog_field_value(feed_model,field_name);
    if coalesce((change->>'revert')::boolean, false) then
      if old_value is null then continue; end if;
      fields := fields - field_name;
    else
      fields := fields || jsonb_build_object(field_name, jsonb_build_object('value',coalesce(change->'value','null'::jsonb),'actor_id',p_actor_id,'actor_kind',p_actor_kind,'actor_name',actor_name,'edited_at',now()));
    end if;
    source.catalog_overrides := source.catalog_overrides || jsonb_build_object(model_id,fields);
    insert into public.provider_catalog_edit_events(provider_slug,model_slug,field,actor_id,actor_kind,actor_name,action,previous_value,value)
    values(p_provider_slug,model_id,field_name,p_actor_id,p_actor_kind,actor_name,case when coalesce((change->>'revert')::boolean,false) then 'revert' else 'override' end,coalesce(old_value->'value',feed_value),case when coalesce((change->>'revert')::boolean,false) then feed_value else change->'value' end);
  end loop;
  if jsonb_array_length(p_changes) > 0 then
    update public.provider_catalog_sources set feed_models=source.feed_models,catalog_overrides=source.catalog_overrides,overrides_updated_at=now(),catalog_updated_at=now(),refresh_requested=true,next_poll_at=now(),updated_at=now() where provider_slug=p_provider_slug;
  end if;
end;
$function$;

REVOKE ALL ON FUNCTION public.save_provider_catalog_overrides(text,uuid,text,timestamptz,jsonb,jsonb) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.save_provider_catalog_overrides(text,uuid,text,timestamptz,jsonb,jsonb) TO service_role;

-- source: supabase/schemas/public/functions/save_provider_managed_catalog.sql
CREATE OR REPLACE FUNCTION public.save_provider_managed_catalog(
  p_provider_slug text, p_actor_id uuid, p_actor_kind text, p_expected_version timestamptz, p_document jsonb
) RETURNS void LANGUAGE plpgsql SET search_path TO 'public' AS $function$
declare source public.provider_catalog_sources%rowtype; actor_name text;
begin
  select * into source from public.provider_catalog_sources where provider_slug=p_provider_slug for update;
  if not found or source.management_mode <> 'managed' then raise exception 'provider_catalog_managed_source_required'; end if;
  if p_expected_version is distinct from coalesce(source.managed_updated_at,source.updated_at) then raise exception 'provider_catalog_version_conflict'; end if;
  if p_actor_id is null or p_actor_kind not in ('phaseo','provider') or jsonb_typeof(p_document) <> 'object' then raise exception 'provider_catalog_edit_invalid'; end if;
  select display_name into actor_name from public.users where user_id=p_actor_id;
  insert into public.provider_catalog_edit_events(provider_slug,model_slug,field,actor_id,actor_kind,actor_name,action,previous_value,value)
  values(p_provider_slug,'*','$catalog',p_actor_id,p_actor_kind,actor_name,'override',source.managed_catalog,p_document);
  update public.provider_catalog_sources set managed_catalog=p_document,managed_updated_by=p_actor_id,managed_updated_at=now(),refresh_requested=true,next_poll_at=now(),etag=null,last_modified=null,last_error=null,updated_at=now() where provider_slug=p_provider_slug;
end;
$function$;

REVOKE ALL ON FUNCTION public.save_provider_managed_catalog(text,uuid,text,timestamptz,jsonb) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.save_provider_managed_catalog(text,uuid,text,timestamptz,jsonb) TO service_role;

-- source: supabase/schemas/public/functions/save_provider_rate_limits.sql
CREATE OR REPLACE FUNCTION public.save_provider_rate_limits(
  p_provider_slug text, p_actor_id uuid, p_actor_kind text, p_expected_version timestamptz, p_limits jsonb, p_check_version boolean DEFAULT true
) RETURNS timestamptz LANGUAGE plpgsql SET search_path TO 'public' AS $function$
declare
  source public.provider_catalog_sources%rowtype;
  item jsonb;
  limit_key text;
  limit_value numeric;
  desired jsonb;
  previous jsonb;
  all_enabled boolean;
  actor_name text;
  saved_version timestamptz;
begin
  select * into source from public.provider_catalog_sources where provider_slug=p_provider_slug for update;
  if not found then raise exception 'provider_catalog_source_not_found'; end if;
  -- Feed imports have no signed-in actor and replace the declared limits wholesale.
  if p_actor_kind not in ('phaseo','provider') or (p_check_version and p_actor_id is null) then raise exception 'provider_catalog_actor_required'; end if;
  if p_check_version and p_expected_version is distinct from source.rate_limits_updated_at then raise exception 'provider_catalog_version_conflict'; end if;
  if jsonb_typeof(p_limits) is distinct from 'array' or jsonb_array_length(p_limits) > 1000 then raise exception 'provider_rate_limits_invalid'; end if;
  for item in select value from jsonb_array_elements(p_limits) loop
    if jsonb_typeof(item) <> 'object'
      or exists (select 1 from jsonb_object_keys(item) key where key not in ('model','requests_per_minute','requests_per_day','tokens_per_minute','tokens_per_day'))
      or (item ? 'model' and jsonb_typeof(item->'model') not in ('string','null'))
      or btrim(coalesce(item->>'model','*'))='' or length(item->>'model')>2000 then
      raise exception 'provider_rate_limits_invalid';
    end if;
    for limit_key in select unnest(array['requests_per_minute','requests_per_day','tokens_per_minute','tokens_per_day']) loop
      if jsonb_typeof(item->limit_key) not in ('number','null') then raise exception 'provider_rate_limits_invalid'; end if;
      limit_value := (item->>limit_key)::numeric;
      if limit_value is not null and (limit_value <= 0 or limit_value <> trunc(limit_value) or limit_value > 9007199254740991) then raise exception 'provider_rate_limits_invalid'; end if;
    end loop;
    if coalesce(item->>'requests_per_minute',item->>'requests_per_day',item->>'tokens_per_minute',item->>'tokens_per_day') is null then raise exception 'provider_rate_limits_empty_scope'; end if;
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object(
      'model',scope.model,
      'requests_per_minute',to_jsonb((scope.item->>'requests_per_minute')::bigint),
      'requests_per_day',to_jsonb((scope.item->>'requests_per_day')::bigint),
      'tokens_per_minute',to_jsonb((scope.item->>'tokens_per_minute')::bigint),
      'tokens_per_day',to_jsonb((scope.item->>'tokens_per_day')::bigint)
    ) order by scope.model),'[]'::jsonb)
  into desired
  from (select coalesce(entry->>'model','*') as model, entry as item from jsonb_array_elements(p_limits) entry) scope;
  if (select count(*) <> count(distinct value->>'model') from jsonb_array_elements(desired)) then raise exception 'provider_rate_limits_duplicate_scope'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'model',limits.provider_model_slug,
      'requests_per_minute',to_jsonb(limits.requests_per_minute),
      'requests_per_day',to_jsonb(limits.requests_per_day),
      'tokens_per_minute',to_jsonb(limits.tokens_per_minute),
      'tokens_per_day',to_jsonb(limits.tokens_per_day)
    ) order by limits.provider_model_slug),'[]'::jsonb), coalesce(bool_and(limits.enabled),true)
  into previous, all_enabled
  from public.provider_rate_limits limits where limits.provider_id=p_provider_slug;
  -- Unchanged declarations leave rows, audit history and the routing catalogue revision untouched.
  -- A provider saving them again re-enables disabled rows; a feed re-import never does.
  if previous=desired and (all_enabled or not p_check_version) then return source.rate_limits_updated_at; end if;
  delete from public.provider_rate_limits limits
  where limits.provider_id=p_provider_slug
    and not exists (select 1 from jsonb_array_elements(desired) scope where scope->>'model'=limits.provider_model_slug);
  insert into public.provider_rate_limits(provider_id,provider_model_slug,requests_per_minute,requests_per_day,tokens_per_minute,tokens_per_day,enabled,updated_at)
  select p_provider_slug, scope->>'model', (scope->>'requests_per_minute')::bigint, (scope->>'requests_per_day')::bigint,
    (scope->>'tokens_per_minute')::bigint, (scope->>'tokens_per_day')::bigint, true, now()
  from jsonb_array_elements(desired) scope
  on conflict (provider_id,provider_model_slug) do update set
    requests_per_minute=excluded.requests_per_minute, requests_per_day=excluded.requests_per_day,
    tokens_per_minute=excluded.tokens_per_minute, tokens_per_day=excluded.tokens_per_day,
    enabled=true, updated_at=now();
  select display_name into actor_name from public.users where user_id=p_actor_id;
  insert into public.provider_catalog_edit_events(provider_slug,model_slug,field,actor_id,actor_kind,actor_name,action,previous_value,value)
  values(p_provider_slug,'*','$rate_limits',p_actor_id,p_actor_kind,actor_name,'override',previous,desired);
  update public.provider_catalog_sources set rate_limits_updated_at=now() where provider_slug=p_provider_slug returning rate_limits_updated_at into saved_version;
  return saved_version;
end;
$function$;

REVOKE ALL ON FUNCTION public.save_provider_rate_limits(text,uuid,text,timestamptz,jsonb,boolean) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.save_provider_rate_limits(text,uuid,text,timestamptz,jsonb,boolean) TO service_role;

-- source: supabase/schemas/public/functions/save_slack_agent_note.sql
CREATE OR REPLACE FUNCTION public.save_slack_agent_note (
  p_installation_id uuid,
  p_kind            text,
  p_channel_id      text,
  p_text            text,
  p_created_by      text,
  p_expires_at      timestamp with time zone
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- The Slack agent's remember tool: saves a short note, pin or to-do for one
-- conversation (p_channel_id) or the whole Slack workspace (null). An installation
-- keeps at most 500; the same open note already saved there is returned instead
-- of a second copy. Expired notes are deleted first, so they never count.
-- Nothing is saved while an admin has turned the installation's memory off.
-- Locking the installation row makes saves take turns, so the cap holds, and
-- orders them against uninstalling, which deletes every note in the transaction
-- that marks the installation uninstalled (delete_slack_agent_memory).
-- Returns {status: saved | exists | full | memory_off | not_installed, note?,
-- limit?}.
-- Service role only: the Worker calls it for the installation it is answering for.
declare
  v_note public.slack_agent_notes%rowtype;
  v_text text := btrim(p_text);
  v_memory_enabled boolean;
begin
  if p_kind is null or p_kind not in ('note', 'pin', 'todo') then
    raise exception 'invalid_kind' using errcode = '22023';
  end if;

  select installation.memory_enabled into v_memory_enabled
  from public.slack_installations installation
  where installation.id = p_installation_id and installation.status <> 'uninstalled'
  for no key update;
  if not found then
    return jsonb_build_object('status', 'not_installed');
  end if;
  if not v_memory_enabled then
    return jsonb_build_object('status', 'memory_off');
  end if;

  delete from public.slack_agent_notes note
  where note.installation_id = p_installation_id and note.expires_at <= now();

  select * into v_note
  from public.slack_agent_notes note
  where note.installation_id = p_installation_id
    and note.kind = p_kind
    and note.channel_id is not distinct from p_channel_id
    and note.done_at is null
    and lower(note.text) = lower(v_text)
  limit 1;
  if found then
    return jsonb_build_object('status', 'exists', 'note', to_jsonb(v_note) - 'installation_id');
  end if;

  if (select count(*) from public.slack_agent_notes note where note.installation_id = p_installation_id) >= 500 then
    return jsonb_build_object('status', 'full', 'limit', 500);
  end if;

  insert into public.slack_agent_notes (installation_id, kind, channel_id, text, created_by, expires_at)
  values (p_installation_id, p_kind, p_channel_id, v_text, p_created_by, p_expires_at)
  returning * into v_note;
  return jsonb_build_object('status', 'saved', 'note', to_jsonb(v_note) - 'installation_id');
end;
$function$;

COMMENT ON FUNCTION "public"."save_slack_agent_note"(uuid, text, text, text, text, timestamp with time zone) IS 'For the Slack Worker''s remember tool: saves a note, pin or to-do for a conversation or the whole Slack workspace, at most 500 per installation, without duplicating an open one, and nothing while its memory is off. Returns {status: saved | exists | full | memory_off | not_installed, note?, limit?}.';

GRANT EXECUTE ON FUNCTION "public"."save_slack_agent_note"(uuid, text, text, text, text, timestamp with time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."save_slack_agent_note"(uuid, text, text, text, text, timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/save_slack_agent_schedule.sql
CREATE OR REPLACE FUNCTION public.save_slack_agent_schedule (
  p_installation_id uuid,
  p_channel_id      text,
  p_title           text,
  p_prompt          text,
  p_frequency       text,
  p_hour            integer,
  p_minute          integer,
  p_day_of_week     integer,
  p_day_of_month    integer,
  p_timezone        text,
  p_created_by      text,
  p_creation_key    text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- The Slack agent's schedule_task tool: saves a recurring task for one
-- conversation, which first runs at the next matching local time. Only while the
-- installation's admins allow recurring tasks (schedules_enabled), only for
-- someone who linked their Phaseo account when they allow only that
-- (schedule_creators linked), and at most schedules_max (20 by default) per
-- installation. Hourly is the finest frequency, so nothing runs more often.
-- Locks the installation row like the memory functions, so the cap holds and
-- uninstalling, which deletes every schedule, can't miss one.
-- p_creation_key keys what the tool call sets up (its Slack event, the answer's
-- part, and a digest of the conversation, title and timing): saving again with
-- the same key, as a retried Workflow step does, returns the schedule saved the
-- first time and saves nothing.
-- Returns {status: saved | full | off | link_required | not_installed,
-- schedule?, limit?}. Service role only.
declare
  v_installation public.slack_installations%rowtype;
  v_schedule public.slack_agent_schedules%rowtype;
begin
  select * into v_installation
  from public.slack_installations installation
  where installation.id = p_installation_id and installation.status <> 'uninstalled'
  for no key update;
  if not found then
    return jsonb_build_object('status', 'not_installed');
  end if;
  select * into v_schedule
  from public.slack_agent_schedules schedule
  where schedule.installation_id = p_installation_id and schedule.creation_key = p_creation_key;
  if found then
    return jsonb_build_object('status', 'saved', 'schedule', to_jsonb(v_schedule) - 'installation_id');
  end if;
  if not v_installation.schedules_enabled then
    return jsonb_build_object('status', 'off');
  end if;
  if v_installation.schedule_creators = 'linked' and not exists (
    select 1 from public.slack_user_links link
    where link.installation_id = p_installation_id and link.slack_user_id = p_created_by
  ) then
    return jsonb_build_object('status', 'link_required');
  end if;
  if (select count(*) from public.slack_agent_schedules schedule where schedule.installation_id = p_installation_id) >= v_installation.schedules_max then
    return jsonb_build_object('status', 'full', 'limit', v_installation.schedules_max);
  end if;

  insert into public.slack_agent_schedules (
    installation_id, channel_id, title, prompt, frequency, hour, minute, day_of_week, day_of_month, timezone, created_by, creation_key, next_run_at
  )
  values (
    p_installation_id, p_channel_id, btrim(p_title), btrim(p_prompt), p_frequency, p_hour, p_minute, p_day_of_week, p_day_of_month, p_timezone, p_created_by, p_creation_key,
    public.slack_agent_schedule_next_run(p_frequency, p_hour, p_minute, p_day_of_week, p_day_of_month, p_timezone, now())
  )
  returning * into v_schedule;
  return jsonb_build_object('status', 'saved', 'schedule', to_jsonb(v_schedule) - 'installation_id');
end;
$function$;

COMMENT ON FUNCTION "public"."save_slack_agent_schedule"(uuid, text, text, text, text, integer, integer, integer, integer, text, text, text) IS 'For the Slack Worker''s schedule_task tool: saves a recurring task, at most schedules_max per installation, while recurring tasks are on and the creator may set them up; a repeat with the same p_creation_key returns the one already saved. Returns {status: saved | full | off | link_required | not_installed, schedule?, limit?}.';

GRANT EXECUTE ON FUNCTION "public"."save_slack_agent_schedule"(uuid, text, text, text, text, integer, integer, integer, integer, text, text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."save_slack_agent_schedule"(uuid, text, text, text, text, integer, integer, integer, integer, text, text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/save_slack_agent_skill.sql
CREATE OR REPLACE FUNCTION public.save_slack_agent_skill (
  p_installation_id uuid,
  p_name            text,
  p_description     text,
  p_instructions    text,
  p_created_by      text,
  p_replace         boolean
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- The Slack agent's save_skill tool: saves instructions for a task people repeat,
-- under a name unique in the installation whatever its case. A skill with that
-- name is only overwritten with p_replace (it keeps who first saved it). An
-- installation keeps at most 100. Locks the installation row like
-- save_slack_agent_note, so the cap holds and uninstalling can't miss one.
-- Returns {status: saved | replaced | name_taken | full | not_installed, skill?,
-- limit?}, without the instructions. Service role only.
declare
  v_skill public.slack_agent_skills%rowtype;
  v_name text := btrim(p_name);
begin
  perform 1 from public.slack_installations installation
  where installation.id = p_installation_id and installation.status <> 'uninstalled'
  for no key update;
  if not found then
    return jsonb_build_object('status', 'not_installed');
  end if;

  select * into v_skill
  from public.slack_agent_skills skill
  where skill.installation_id = p_installation_id and lower(skill.name) = lower(v_name);
  if found then
    if not coalesce(p_replace, false) then
      return jsonb_build_object('status', 'name_taken', 'skill', jsonb_build_object('name', v_skill.name, 'description', v_skill.description));
    end if;
    update public.slack_agent_skills skill
    set name = v_name, description = btrim(p_description), instructions = btrim(p_instructions)
    where skill.id = v_skill.id
    returning * into v_skill;
    return jsonb_build_object('status', 'replaced', 'skill', to_jsonb(v_skill) - 'installation_id' - 'instructions');
  end if;

  if (select count(*) from public.slack_agent_skills skill where skill.installation_id = p_installation_id) >= 100 then
    return jsonb_build_object('status', 'full', 'limit', 100);
  end if;

  insert into public.slack_agent_skills (installation_id, name, description, instructions, created_by)
  values (p_installation_id, v_name, btrim(p_description), btrim(p_instructions), p_created_by)
  returning * into v_skill;
  return jsonb_build_object('status', 'saved', 'skill', to_jsonb(v_skill) - 'installation_id' - 'instructions');
end;
$function$;

COMMENT ON FUNCTION "public"."save_slack_agent_skill"(uuid, text, text, text, text, boolean) IS 'For the Slack Worker''s save_skill tool: saves a named skill, at most 100 per installation, overwriting one with the same name only when asked to. Returns {status: saved | replaced | name_taken | full | not_installed, skill?, limit?}.';

GRANT EXECUTE ON FUNCTION "public"."save_slack_agent_skill"(uuid, text, text, text, text, boolean) TO "service_role";

REVOKE ALL ON FUNCTION "public"."save_slack_agent_skill"(uuid, text, text, text, text, boolean) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/save_workspace_spend_rule.sql
CREATE OR REPLACE FUNCTION public.save_workspace_spend_rule (
  p_workspace_id    uuid,
  p_rule_id         uuid,
  p_rule            jsonb,
  p_destination_ids uuid[],
  p_actor_user_id   uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Creates (p_rule_id null) or replaces (p_rule_id set) a spend rule and its destinations in one
-- transaction, for the control API and web-api, which validate the whole rule first and pass
-- every editable column in p_rule. The table's trigger and CHECK constraints still decide.
--   * p_destination_ids null keeps the rule's destinations; an array (at most 50, each an
--     active or disabled notification destination of the workspace) replaces them. An empty
--     array means the workspace's spend_alert routes apply.
--   * An enabled rule marks the workspace in workspace_spend_rule_dirty, so the sweep evaluates
--     it within one tick.
-- Errors: spend_rule_not_found, too_many_spend_rule_destinations,
-- notification_destination_not_found, plus the table's (spend_rule_limit_reached,
-- invalid_time_zone, invalid_spend_rule_scope_id, constraint names).
-- Returns {rule: <row>, destination_ids: [...]}.
declare
  v_input public.workspace_spend_rules;
  v_rule public.workspace_spend_rules;
begin
  if p_workspace_id is null or p_rule is null or jsonb_typeof(p_rule) <> 'object' then
    raise exception 'invalid_spend_rule' using errcode = '22023';
  end if;
  if p_destination_ids is not null then
    if cardinality(p_destination_ids) > 50 then
      raise exception 'too_many_spend_rule_destinations' using errcode = '22023';
    end if;
    if exists (
      select 1 from unnest(p_destination_ids) requested(destination_id)
      where requested.destination_id is null or not exists (
        select 1 from public.notification_destinations destination
        where destination.id = requested.destination_id
          and destination.workspace_id = p_workspace_id
          and destination.status <> 'deleted'
          and not destination.is_ephemeral
      )
    ) then
      raise exception 'notification_destination_not_found' using errcode = '23503';
    end if;
  end if;

  v_input := jsonb_populate_record(null::public.workspace_spend_rules, p_rule);

  if p_rule_id is null then
    insert into public.workspace_spend_rules (
      workspace_id, name, enabled, metric, scope_type, scope_id, period, window_hours, time_zone,
      base_kind, base_ref, base_amount_nanos, threshold_percents, threshold_amount_nanos, runway_days,
      spike_multiplier, spike_floor_nanos, action, block_at_percent, block_at_amount_nanos,
      block_free_models, cooldown_minutes, created_by
    )
    values (
      p_workspace_id, v_input.name, coalesce(v_input.enabled, true), v_input.metric,
      coalesce(v_input.scope_type, 'workspace'), v_input.scope_id, v_input.period, v_input.window_hours,
      v_input.time_zone, v_input.base_kind, v_input.base_ref, v_input.base_amount_nanos, v_input.threshold_percents,
      v_input.threshold_amount_nanos, v_input.runway_days, v_input.spike_multiplier, v_input.spike_floor_nanos,
      coalesce(v_input.action, 'notify'), coalesce(v_input.block_at_percent, 110), v_input.block_at_amount_nanos,
      coalesce(v_input.block_free_models, false), coalesce(v_input.cooldown_minutes, 360), p_actor_user_id
    )
    returning * into v_rule;
  else
    update public.workspace_spend_rules rule set
      name = v_input.name,
      enabled = coalesce(v_input.enabled, true),
      metric = v_input.metric,
      scope_type = coalesce(v_input.scope_type, 'workspace'),
      scope_id = v_input.scope_id,
      period = v_input.period,
      window_hours = v_input.window_hours,
      time_zone = v_input.time_zone,
      base_kind = v_input.base_kind,
      base_ref = v_input.base_ref,
      base_amount_nanos = v_input.base_amount_nanos,
      threshold_percents = v_input.threshold_percents,
      threshold_amount_nanos = v_input.threshold_amount_nanos,
      runway_days = v_input.runway_days,
      spike_multiplier = v_input.spike_multiplier,
      spike_floor_nanos = v_input.spike_floor_nanos,
      action = coalesce(v_input.action, 'notify'),
      block_at_percent = coalesce(v_input.block_at_percent, 110),
      block_at_amount_nanos = v_input.block_at_amount_nanos,
      block_free_models = coalesce(v_input.block_free_models, false),
      cooldown_minutes = coalesce(v_input.cooldown_minutes, 360)
    where rule.id = p_rule_id and rule.workspace_id = p_workspace_id and rule.deleted_at is null
    returning * into v_rule;
    if not found then
      raise exception 'spend_rule_not_found' using errcode = 'P0002';
    end if;
  end if;

  if p_destination_ids is not null then
    delete from public.workspace_spend_rule_destinations link
    where link.rule_id = v_rule.id and not (link.destination_id = any (p_destination_ids));
    insert into public.workspace_spend_rule_destinations (rule_id, destination_id, workspace_id)
    select distinct v_rule.id, requested.destination_id, p_workspace_id
    from unnest(p_destination_ids) requested(destination_id)
    on conflict (rule_id, destination_id) do nothing;
  end if;

  if v_rule.enabled then
    insert into public.workspace_spend_rule_dirty (workspace_id) values (p_workspace_id)
    on conflict (workspace_id) do nothing;
  end if;

  return jsonb_build_object(
    'rule', to_jsonb(v_rule),
    'destination_ids', coalesce((
      select jsonb_agg(link.destination_id order by link.destination_id)
      from public.workspace_spend_rule_destinations link
      where link.rule_id = v_rule.id
    ), '[]'::jsonb)
  );
end;
$function$;

COMMENT ON FUNCTION "public"."save_workspace_spend_rule"(uuid, uuid, jsonb, uuid[], uuid) IS 'Creates or replaces a spend rule and (when p_destination_ids is not null) its destinations in one transaction, and marks the workspace for evaluation. Service role only (control API and web-api).';

REVOKE ALL ON FUNCTION "public"."save_workspace_spend_rule"(uuid, uuid, jsonb, uuid[], uuid) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."save_workspace_spend_rule"(uuid, uuid, jsonb, uuid[], uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."save_workspace_spend_rule"(uuid, uuid, jsonb, uuid[], uuid) FROM "anon", "authenticated";

-- source: supabase/schemas/public/functions/set_model_successor_routing.sql
CREATE OR REPLACE FUNCTION public.set_model_successor_routing (
  p_actor_user_id      uuid,
  p_model_slug         text,
  p_enabled            boolean,
  p_allow_incompatible boolean DEFAULT false,
  p_notes              text DEFAULT NULL
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare v_before jsonb; v_current jsonb; v_compatibility jsonb; v_successor text;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  perform 1 from public.v2_models where model_slug=p_model_slug for update;
  if not found then raise exception 'model % does not exist', p_model_slug; end if;

  v_before := public.get_model_successor_routing(p_model_slug);
  if p_enabled then
    v_successor := v_before->>'replacement_model_slug';
    v_compatibility := v_before->'compatibility';
    if v_successor is null or v_compatibility is null or jsonb_typeof(v_compatibility) <> 'object' then
      raise exception 'Set a replacement model before approving successor routing.';
    end if;
    if jsonb_array_length(v_compatibility->'blocking') > 0 then
      raise exception 'Successor % cannot be approved: %', v_successor, (select string_agg(x,', ') from jsonb_array_elements_text(v_compatibility->'blocking') x);
    end if;
    if jsonb_array_length(v_compatibility->'warnings') > 0 and not coalesce(p_allow_incompatible,false) then
      raise exception 'Successor % has compatibility warnings: %. Accept them to approve.', v_successor, (select string_agg(x,', ') from jsonb_array_elements_text(v_compatibility->'warnings') x);
    end if;
    insert into public.v2_model_successor_routing as s (model_slug, auto_route_enabled, approved_successor_slug, approved_by, approved_at, compatibility, notes, approval_source, auto_approval_blocked)
    values (p_model_slug, true, v_successor, p_actor_user_id, now(),
      v_compatibility || jsonb_build_object('accepted_warnings', jsonb_array_length(v_compatibility->'warnings') > 0), nullif(btrim(p_notes),''), 'admin', false)
    on conflict (model_slug) do update set auto_route_enabled=true, approved_successor_slug=excluded.approved_successor_slug,
      approved_by=excluded.approved_by, approved_at=excluded.approved_at, compatibility=excluded.compatibility,
      notes=coalesce(excluded.notes, s.notes), approval_source='admin', auto_approval_blocked=false, updated_at=now();
  else
    -- Revoking also stops the hourly job from approving the model again;
    -- approving it by hand lifts that block.
    insert into public.v2_model_successor_routing as s (model_slug, notes, auto_approval_blocked)
    values (p_model_slug, nullif(btrim(p_notes),''), true)
    on conflict (model_slug) do update set auto_route_enabled=false, approved_successor_slug=null, approved_by=null,
      approved_at=null, compatibility='{}'::jsonb, approval_source=null, auto_approval_blocked=true,
      notes=coalesce(excluded.notes, s.notes), updated_at=now();
  end if;

  v_current := public.get_model_successor_routing(p_model_slug);
  if v_current is distinct from v_before then
    insert into public.v2_catalogue_admin_changes (actor_user_id, resource_type, resource_id, action, before_state, after_state)
    values (p_actor_user_id, 'models', p_model_slug, 'update',
      jsonb_build_object('successor_routing', v_before), jsonb_build_object('successor_routing', v_current));
  end if;
  return v_current;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."set_model_successor_routing"(uuid, text, boolean, boolean, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."set_model_successor_routing"(uuid, text, boolean, boolean, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/set_notification_event_destinations.sql
CREATE OR REPLACE FUNCTION public.set_notification_event_destinations (
  p_workspace_id    uuid,
  p_event_kind      text,
  p_destination_ids uuid[]
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text || ':' || p_event_kind, 0));

  if p_event_kind not in ('low_balance', 'auto_top_up_failed', 'payment_method_expiring', 'model_deprecation', 'model_substitution', 'rate_limit_throttled', 'broadcast_destination_failing', 'spend_alert', 'spend_blocked', 'spend_report') then
    raise exception 'invalid_notification_event_kind';
  end if;

  if (
    select count(*)
    from public.notification_destinations
    where workspace_id = p_workspace_id
      and status = 'active'
      and id = any(p_destination_ids)
  ) <> cardinality(p_destination_ids) then
    raise exception 'notification_destination_not_found';
  end if;

  delete from public.notification_event_destinations
  where workspace_id = p_workspace_id and event_kind = p_event_kind;

  insert into public.notification_event_destinations (workspace_id, event_kind, destination_id)
  select p_workspace_id, p_event_kind, destination_id
  from unnest(p_destination_ids) as destination_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."set_notification_event_destinations"(uuid, text, uuid[]) TO "service_role";

REVOKE ALL ON FUNCTION "public"."set_notification_event_destinations"(uuid, text, uuid[]) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/set_self_serve_provider_review.sql
CREATE OR REPLACE FUNCTION public.set_self_serve_provider_review (
  p_provider_slug text,
  p_decision      text,
  p_reason        text,
  p_reviewed_by   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  reviewed_at_value timestamptz := now();
  activated_ids text[] := '{}';
  submitted_by_value uuid;
  review_message_value text;
begin
  if p_decision not in ('approved', 'paused', 'rejected', 'needs_changes') then
    raise exception 'invalid_provider_review_decision';
  end if;
  if p_decision <> 'approved' and nullif(btrim(p_reason), '') is null then
    raise exception 'provider_review_reason_required';
  end if;

  update public.v2_providers provider
  set metadata = jsonb_set(
        coalesce(provider.metadata, '{}'::jsonb),
        '{self_serve}',
        coalesce(provider.metadata -> 'self_serve', '{}'::jsonb) || jsonb_build_object(
          'provider_review_status', p_decision,
          'provider_review_reason', case when p_decision = 'approved' then null else p_reason end,
          'provider_reviewed_by', p_reviewed_by,
          'provider_reviewed_at', reviewed_at_value
        ),
        true
      ),
      status = 'not_ready',
      routable = false,
      routing_enabled = false,
      updated_at = reviewed_at_value
  where provider.provider_slug = p_provider_slug
    and provider.metadata ? 'self_serve';
  if not found then raise exception 'self_serve_provider_not_found'; end if;

  update public.provider_catalog_sources
  set status = case when p_decision = 'approved' then 'active' else 'paused' end,
      refresh_requested = p_decision = 'approved',
      next_poll_at = case when p_decision = 'approved' then reviewed_at_value else null end,
      updated_at = reviewed_at_value
  where provider_slug = p_provider_slug;

  if p_decision <> 'approved' then
    update public.v2_model_provider_routes set status = case when status = 'retired' then 'retired' else 'disabled' end, routing_enabled = false,
      access_scope = case when phaseo_status in ('blocked', 'unsupported') then access_scope else 'internal' end,
      phaseo_status = case when phaseo_status in ('blocked', 'unsupported') then phaseo_status else 'testing' end,
      provider_availability_status = case when provider_availability_status = 'removed' then 'removed' else 'coming_soon' end, updated_at = reviewed_at_value
    where provider_slug = p_provider_slug and metadata ->> 'managed_by' = 'provider_catalog';
    update public.v2_route_variants variant set status = 'disabled', routing_enabled = false, updated_at = reviewed_at_value
    from public.v2_model_provider_routes route
    where route.provider_slug = p_provider_slug and variant.provider_model_id = route.provider_model_id
      and variant.metadata ->> 'managed_by' = 'provider_catalog';
    update public.v2_route_capabilities capability set status = 'internal_testing', updated_at = reviewed_at_value
    from public.v2_model_provider_routes route
    where route.provider_slug = p_provider_slug and capability.provider_model_id = route.provider_model_id
      and capability.capability_id = public.canonical_routing_capability_id(capability.capability_id)
      and capability.metadata ->> 'managed_by' = 'provider_catalog';
  end if;

  select submitted_by into submitted_by_value
  from public.provider_onboarding_submissions
  where provider_slug = p_provider_slug and submitted_by is not null
  order by created_at desc limit 1;

  review_message_value := case p_decision
    when 'approved' then 'Your provider application is approved. Validated catalog updates now apply automatically. Public routing requires configured endpoints, adapters, credentials, and prices.'
    when 'needs_changes' then 'Phaseo requested changes to your provider application: ' || btrim(p_reason)
    when 'rejected' then 'Phaseo rejected your provider application: ' || btrim(p_reason)
    else 'Phaseo paused your provider application: ' || btrim(p_reason)
  end;

  insert into public.provider_catalog_events (
    provider_slug, account_user_id, workspace_id, event_type, title, message, payload
  )
  select p_provider_slug, submitted_by_value, link.workspace_id, 'provider_application_reviewed',
    'Provider application ' || replace(p_decision, '_', ' '), review_message_value,
    jsonb_build_object('decision', p_decision, 'reason', case when p_decision = 'approved' then null else p_reason end)
  from public.provider_account_links link
  where link.provider_slug = p_provider_slug and link.status in ('pending', 'active');

  return jsonb_build_object('providerSlug', p_provider_slug, 'decision', p_decision, 'activatedRouteIds', activated_ids);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."set_self_serve_provider_review"(text, text, text, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."set_self_serve_provider_review"(text, text, text, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/set_slack_agent_schedule_status.sql
CREATE OR REPLACE FUNCTION public.set_slack_agent_schedule_status (
  p_installation_id uuid,
  p_schedule_id     uuid,
  p_status          text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Settings > Slack: an owner or admin pauses or resumes one of the
-- installation's schedules (web-api checks who they are). Pausing records the
-- reason admin. Resuming clears the reason and the failures in a row, and the
-- schedule next runs at its next local time after now, and at least 50 minutes
-- after its last run was claimed, so resuming can't make it run more than once
-- an hour.
-- Returns the schedule without its installation id, or null when the
-- installation has no such schedule. Service role only.
declare
  v_schedule public.slack_agent_schedules%rowtype;
begin
  if p_status is null or p_status not in ('active', 'paused') then
    raise exception 'invalid_status' using errcode = '22023';
  end if;
  update public.slack_agent_schedules schedule
  set status = p_status,
      pause_reason = case when p_status = 'paused' then coalesce(case when schedule.status = 'paused' then schedule.pause_reason end, 'admin') end,
      failures = case when p_status = 'active' and schedule.status <> 'active' then 0 else schedule.failures end,
      next_run_at = case
        when p_status = 'active' and schedule.status <> 'active' then public.slack_agent_schedule_next_run(
          schedule.frequency, schedule.hour, schedule.minute, schedule.day_of_week, schedule.day_of_month, schedule.timezone,
          greatest(now(), schedule.last_claimed_at + interval '50 minutes')
        )
        else schedule.next_run_at
      end
  where schedule.id = p_schedule_id and schedule.installation_id = p_installation_id
  returning * into v_schedule;
  if not found then
    return null;
  end if;
  return to_jsonb(v_schedule) - 'installation_id';
end;
$function$;

COMMENT ON FUNCTION "public"."set_slack_agent_schedule_status"(uuid, uuid, text) IS 'For web-api (Settings > Slack): pauses (reason admin) or resumes a schedule. Resuming clears failures and moves next_run_at to its next local time at least 50 minutes after its last run was claimed. Returns the schedule, or null.';

GRANT EXECUTE ON FUNCTION "public"."set_slack_agent_schedule_status"(uuid, uuid, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."set_slack_agent_schedule_status"(uuid, uuid, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/set_spend_report_subscription.sql
CREATE OR REPLACE FUNCTION public.set_spend_report_subscription (
  p_token      uuid,
  p_subscribed boolean DEFAULT NULL::boolean
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- The unsubscribe link in a spend report email (and its RFC 8058 one-click List-Unsubscribe).
-- The unguessable token names one person and one workspace. p_subscribed false unsubscribes them
-- from that workspace's report emails and cancels any of those emails still waiting in the outbox;
-- true subscribes them again; null only reads. Other emails, other workspaces' reports and the
-- routed spend_report events are untouched. Repeating it is harmless. Returns null for an unknown
-- token, otherwise { workspace_name, subscribed }.
declare
  v_workspace_id uuid;
  v_user_id uuid;
  v_opted_out_at timestamp with time zone;
begin
  if p_token is null then
    return null;
  end if;

  if p_subscribed is null then
    select recipient.workspace_id, recipient.user_id, recipient.opted_out_at
    into v_workspace_id, v_user_id, v_opted_out_at
    from public.workspace_spend_report_recipients recipient
    where recipient.unsubscribe_token = p_token;
  else
    update public.workspace_spend_report_recipients recipient
    set opted_out_at = case when p_subscribed then null else coalesce(recipient.opted_out_at, now()) end,
      updated_at = now()
    where recipient.unsubscribe_token = p_token
    returning recipient.workspace_id, recipient.user_id, recipient.opted_out_at
    into v_workspace_id, v_user_id, v_opted_out_at;
  end if;

  if v_workspace_id is null then
    return null;
  end if;

  if p_subscribed is false then
    update public.email_outbox event
    set attempts = 5, last_error = 'unsubscribed'
    where event.user_id = v_user_id
      and event.workspace_id = v_workspace_id
      and event.kind = 'spend_report_email'
      and event.sent_at is null
      and event.attempts < 5;
  end if;

  return jsonb_build_object(
    'workspace_name', (select coalesce(nullif(btrim(workspace.name), ''), 'your workspace') from public.workspaces workspace where workspace.id = v_workspace_id),
    'subscribed', v_opted_out_at is null
  );
end;
$function$;

COMMENT ON FUNCTION "public"."set_spend_report_subscription"(uuid, boolean) IS 'Reads (null), unsubscribes (false) or resubscribes (true) the person and workspace named by a spend report unsubscribe token. Unsubscribing also cancels their unsent report emails for that workspace. Null for an unknown token. Service role only (the public web-api route behind the email link).';

REVOKE ALL ON FUNCTION "public"."set_spend_report_subscription"(uuid, boolean) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."set_spend_report_subscription"(uuid, boolean) TO "service_role";

REVOKE ALL ON FUNCTION "public"."set_spend_report_subscription"(uuid, boolean) FROM "anon", "authenticated";

-- source: supabase/schemas/public/functions/set_updated_at_if_changed.sql
CREATE OR REPLACE FUNCTION public.set_updated_at_if_changed()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
begin
  -- Only bump updated_at if some column changed,
  -- and we haven't already set updated_at in this trigger.
  if row(NEW.*) is distinct from row(OLD.*)
     and NEW.updated_at is not distinct from OLD.updated_at then
    NEW.updated_at := now();
  end if;
  return NEW;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."set_updated_at_if_changed"() TO PUBLIC, "anon", "authenticated";

GRANT EXECUTE ON FUNCTION "public"."set_updated_at_if_changed"() TO "service_role";

-- source: supabase/schemas/public/functions/set_v2_admin_model_availability.sql
CREATE OR REPLACE FUNCTION public.set_v2_admin_model_availability (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_available     boolean
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  model_row public.v2_models%rowtype;
  route_ids text[];
  before_state jsonb;
  after_state jsonb;
begin
  if p_available is null then raise exception 'availability is required'; end if;
  if not exists (select 1 from public.users where user_id = p_actor_user_id and role::text = 'admin') then
    raise exception 'actor must have the admin role';
  end if;
  select * into model_row from public.v2_models where model_slug = p_model_slug for update;
  if not found then raise exception 'model not found'; end if;
  perform 1 from public.v2_model_provider_routes where model_slug = p_model_slug for update;
  before_state := to_jsonb(model_row);

  if p_available then
    if model_row.hidden = false and model_row.status = 'active' then
      return jsonb_build_object('model_slug', p_model_slug, 'available', true);
    end if;
    if model_row.retired_at <= now() then raise exception 'retired models cannot be released'; end if;
    select array_agg(route.provider_model_id) into route_ids
    from public.v2_model_provider_routes route
    join public.v2_providers provider on provider.provider_slug = route.provider_slug
    where route.model_slug = p_model_slug and route.access_scope = 'internal'
      and route.phaseo_status = 'testing' and route.status in ('active', 'degraded')
      and route.is_stealth = false
      and route.provider_availability_status in ('available', 'preview', 'limited_access')
      and (route.effective_from is null or route.effective_from <= now())
      and (route.effective_to is null or route.effective_to > now())
      and provider.routing_enabled = true and provider.routable = true
      and exists (select 1 from public.v2_pricing_skus sku
        join public.v2_pricing_sku_meters meter on meter.sku_id = sku.sku_id
        where sku.provider_model_id = route.provider_model_id and sku.status = 'active'
          and sku.effective_from <= now() and (sku.effective_to is null or sku.effective_to > now()))
      and exists (select 1 from public.v2_route_capabilities capability
        where capability.provider_model_id = route.provider_model_id
          and capability.status in ('active', 'internal_testing')
          and (capability.effective_from is null or capability.effective_from <= now())
          and (capability.effective_to is null or capability.effective_to > now()));
    if coalesce(cardinality(route_ids), 0) = 0 then
      raise exception 'no prepared internal testing routes are ready for release';
    end if;
    update public.v2_model_provider_routes set access_scope = 'public', phaseo_status = 'enabled',
      routing_enabled = true, updated_at = now() where provider_model_id = any(route_ids);
    update public.v2_route_capabilities set status = 'active', updated_at = now()
      where provider_model_id = any(route_ids) and status = 'internal_testing';
    update public.v2_models set hidden = false, status = 'active', catalogue_status = 'available',
      released_at = case when released_at is null or released_at > now() then now() else released_at end,
      updated_at = now() where model_slug = p_model_slug;
  else
    select array_agg(provider_model_id) into route_ids from public.v2_model_provider_routes
      where model_slug = p_model_slug and access_scope = 'public' and phaseo_status = 'enabled';
    update public.v2_models set hidden = true, status = 'draft', updated_at = now()
      where model_slug = p_model_slug;
    update public.v2_model_provider_routes set access_scope = 'internal', phaseo_status = 'testing',
      routing_enabled = false, updated_at = now() where provider_model_id = any(route_ids);
    update public.v2_route_capabilities set status = 'internal_testing', updated_at = now()
      where provider_model_id = any(route_ids) and status = 'active';
  end if;
  select to_jsonb(model) into after_state from public.v2_models model where model_slug = p_model_slug;
  insert into public.v2_catalogue_admin_changes(actor_user_id, resource_type, resource_id, action, before_state, after_state)
    values(p_actor_user_id, 'models', p_model_slug, 'update', before_state, after_state);
  insert into public.v2_catalogue_source_overrides(source_type, source_key, disposition, actor_user_id, resource_id, updated_at)
    values('models', p_model_slug, 'database_managed', p_actor_user_id, p_model_slug, now())
    on conflict(source_type, source_key) do update set disposition = 'database_managed',
      actor_user_id = excluded.actor_user_id, updated_at = now();
  return jsonb_build_object('model_slug', p_model_slug, 'available', p_available, 'routes', to_jsonb(route_ids));
end;
$function$;

revoke all on function public.set_v2_admin_model_availability(uuid,text,boolean) from public, anon, authenticated;

grant execute on function public.set_v2_admin_model_availability(uuid,text,boolean) to service_role;

-- source: supabase/schemas/public/functions/set_v2_model_recommended_successor.sql
CREATE OR REPLACE FUNCTION public.set_v2_model_recommended_successor (
  p_actor_user_id          uuid,
  p_model_slug             text,
  p_replacement_model_slug text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_before jsonb;
  v_after jsonb;
  v_replacement_slug text := nullif(trim(coalesce(p_replacement_model_slug, '')), '');
begin
  if not exists (
    select 1 from public.users
    where user_id = p_actor_user_id
      and lower(coalesce(role::text, '')) = 'admin'
  ) then
    raise exception 'actor must have the admin role';
  end if;

  if v_replacement_slug = p_model_slug then
    raise exception 'recommended successor cannot be the same model';
  end if;

  if v_replacement_slug is not null and not exists (
    select 1 from public.v2_models where model_slug = v_replacement_slug
  ) then
    raise exception 'recommended successor model not found';
  end if;

  select to_jsonb(model) into v_before
  from public.v2_models model
  where model.model_slug = p_model_slug
  for update;

  if v_before is null then
    raise exception 'model not found';
  end if;

  update public.v2_models
  set replacement_model_slug = v_replacement_slug,
      updated_at = now()
  where model_slug = p_model_slug;

  select to_jsonb(model) into v_after
  from public.v2_models model
  where model.model_slug = p_model_slug;

  insert into public.v2_catalogue_admin_changes(
    actor_user_id, resource_type, resource_id, action, before_state, after_state
  ) values (
    p_actor_user_id, 'model_graph', p_model_slug, 'save', v_before, v_after
  );

  return jsonb_build_object('before', v_before, 'after', v_after);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."set_v2_model_recommended_successor"(uuid, text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."set_v2_model_recommended_successor"(uuid, text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/set_v2_request_fact_service_tier.sql
CREATE OR REPLACE FUNCTION public.set_v2_request_fact_service_tier()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  new.service_tier_requested := coalesce(
    public.normalize_v2_service_tier(new.service_tier_requested),
    public.normalize_v2_service_tier(new.safe_metadata->>'service_tier_requested')
  );
  new.service_tier_observed := coalesce(
    public.normalize_v2_service_tier(new.service_tier_observed),
    public.normalize_v2_service_tier(new.safe_metadata->>'service_tier_observed')
  );
  new.service_tier_slug := coalesce(
    public.normalize_v2_service_tier(new.service_tier_slug),
    public.normalize_v2_service_tier(new.safe_metadata->>'service_tier'),
    new.service_tier_observed,
    new.service_tier_requested,
    case when new.endpoint = 'batch' then 'batch' else null end
  );
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."set_v2_request_fact_service_tier"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/set_v2_request_pricing_line_service_tier.sql
CREATE OR REPLACE FUNCTION public.set_v2_request_pricing_line_service_tier()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_provider_model_id text;
  v_occurred_at timestamptz;
  v_service_tier text;
  v_existing_sku_tier text;
  v_sku_id uuid;
  v_sku_meter_id uuid;
begin
  select
    fact.provider_model_id,
    fact.occurred_at,
    fact.service_tier_slug,
    lower(nullif(trim(sku.service_tier_slug), ''))
  into v_provider_model_id, v_occurred_at, v_service_tier, v_existing_sku_tier
  from public.v2_request_facts fact
  left join public.v2_pricing_skus sku on sku.sku_id = new.sku_id
  where fact.request_event_id = new.request_event_id;

  if v_provider_model_id is null or v_service_tier is null then
    return new;
  end if;
  if v_existing_sku_tier = 'free' then
    return new;
  end if;

  select sku.sku_id, sku_meter.sku_meter_id
  into v_sku_id, v_sku_meter_id
  from public.v2_pricing_skus sku
  join public.v2_pricing_sku_meters sku_meter
    on sku_meter.sku_id = sku.sku_id
   and sku_meter.meter_key = lower(trim(new.meter_key))
  where sku.provider_model_id = v_provider_model_id
    and coalesce(public.normalize_v2_service_tier(sku.service_tier_slug), 'standard') = v_service_tier
    and sku.status = 'active'
    and sku.effective_from <= v_occurred_at
    and (sku.effective_to is null or sku.effective_to > v_occurred_at)
  order by sku.version desc, sku.effective_from desc, sku.sku_id
  limit 1;

  if v_sku_id is not null then
    new.sku_id := v_sku_id;
    new.sku_meter_id := v_sku_meter_id;
  end if;
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."set_v2_request_pricing_line_service_tier"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."set_v2_request_pricing_line_service_tier"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/set_v2_request_usage_service_tier.sql
CREATE OR REPLACE FUNCTION public.set_v2_request_usage_service_tier()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_provider_model_id text;
  v_occurred_at timestamptz;
  v_service_tier text;
  v_existing_sku_tier text;
  v_sku_meter_id uuid;
begin
  select
    fact.provider_model_id,
    fact.occurred_at,
    fact.service_tier_slug,
    lower(nullif(trim(sku.service_tier_slug), ''))
  into v_provider_model_id, v_occurred_at, v_service_tier, v_existing_sku_tier
  from public.v2_request_facts fact
  left join public.v2_pricing_sku_meters current_meter
    on current_meter.sku_meter_id = new.sku_meter_id
  left join public.v2_pricing_skus sku on sku.sku_id = current_meter.sku_id
  where fact.request_event_id = new.request_event_id;

  if v_provider_model_id is null or v_service_tier is null then
    return new;
  end if;
  if v_existing_sku_tier = 'free' then
    return new;
  end if;

  select sku_meter.sku_meter_id
  into v_sku_meter_id
  from public.v2_pricing_sku_meters sku_meter
  join public.v2_pricing_skus sku on sku.sku_id = sku_meter.sku_id
  where sku.provider_model_id = v_provider_model_id
    and sku_meter.meter_key = lower(trim(new.meter_key))
    and coalesce(public.normalize_v2_service_tier(sku.service_tier_slug), 'standard') = v_service_tier
    and sku.status = 'active'
    and sku.effective_from <= v_occurred_at
    and (sku.effective_to is null or sku.effective_to > v_occurred_at)
  order by sku.version desc, sku.effective_from desc, sku.sku_id
  limit 1;

  if v_sku_meter_id is not null then
    new.sku_meter_id := v_sku_meter_id;
  end if;
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."set_v2_request_usage_service_tier"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."set_v2_request_usage_service_tier"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/set_workspace_kind.sql
CREATE OR REPLACE FUNCTION public.set_workspace_kind()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
begin
  if new.workspace_kind = 'provider' then return new; end if;
  if lower(coalesce(new.tier, '')) = 'enterprise' then
    new.workspace_kind := 'enterprise';
  elsif lower(coalesce(new.name, '')) = 'personal' then
    new.workspace_kind := 'personal';
  elsif tg_op = 'INSERT' or new.workspace_kind in ('personal', 'enterprise') then
    new.workspace_kind := 'organization';
  end if;
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."set_workspace_kind"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."set_workspace_kind"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/slack_agent_schedule_next_run.sql
CREATE OR REPLACE FUNCTION public.slack_agent_schedule_next_run (
  p_frequency    text,
  p_hour         integer,
  p_minute       integer,
  p_day_of_week  integer,
  p_day_of_month integer,
  p_timezone     text,
  p_after        timestamp with time zone
)
  RETURNS timestamp with time zone
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
-- When a Slack agent schedule runs next: the first time after p_after that
-- matches it, in local time in p_timezone (an IANA name, as Slack gives it).
-- hourly runs at p_minute past every local hour; daily, weekdays (Monday to
-- Friday), weekly (p_day_of_week, 1 Monday to 7 Sunday) and monthly
-- (p_day_of_month, or the month's last day when it is shorter) at
-- p_hour:p_minute. A local time that a daylight saving change skips or repeats
-- resolves as Postgres resolves it; the result is always later than p_after.
-- Raises 22023 for an unknown time zone or a frequency it doesn't know.
declare
  v_local timestamp := p_after at time zone p_timezone;
  v_time interval := make_interval(hours => coalesce(p_hour, 0), mins => p_minute);
  v_candidate timestamp;
  v_month date;
  v_at timestamptz;
begin
  if p_frequency = 'hourly' then
    v_candidate := date_trunc('hour', v_local) + make_interval(mins => p_minute);
    for step in 0..3 loop
      v_at := (v_candidate + make_interval(hours => step)) at time zone p_timezone;
      if v_at > p_after then
        return v_at;
      end if;
    end loop;
  elsif p_frequency = 'monthly' then
    for step in 0..2 loop
      v_month := (date_trunc('month', v_local) + make_interval(months => step))::date;
      v_candidate := v_month
        + (least(p_day_of_month, extract(day from v_month + interval '1 month' - interval '1 day')::integer) - 1)
        + v_time;
      v_at := v_candidate at time zone p_timezone;
      if v_at > p_after then
        return v_at;
      end if;
    end loop;
  elsif p_frequency in ('daily', 'weekdays', 'weekly') then
    for step in 0..8 loop
      v_candidate := (v_local::date + step) + v_time;
      if p_frequency = 'daily'
        or (p_frequency = 'weekdays' and extract(isodow from v_candidate) between 1 and 5)
        or (p_frequency = 'weekly' and extract(isodow from v_candidate) = p_day_of_week) then
        v_at := v_candidate at time zone p_timezone;
        if v_at > p_after then
          return v_at;
        end if;
      end if;
    end loop;
  end if;
  raise exception 'invalid_schedule' using errcode = '22023';
end;
$function$;

COMMENT ON FUNCTION "public"."slack_agent_schedule_next_run"(text, integer, integer, integer, integer, text, timestamp with time zone) IS 'The next time a Slack agent schedule runs after p_after, at its local time in p_timezone. Always later than p_after.';

GRANT EXECUTE ON FUNCTION "public"."slack_agent_schedule_next_run"(text, integer, integer, integer, integer, text, timestamp with time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."slack_agent_schedule_next_run"(text, integer, integer, integer, integer, text, timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/snapshot_gateway_request_entitlement.sql
CREATE OR REPLACE FUNCTION public.snapshot_gateway_request_entitlement()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare entitlement record; identity_user_id uuid;
begin
  identity_user_id := new.oauth_user_id;
  if identity_user_id is null and new.key_id is not null then
    select oauth_user_id into identity_user_id from public.keys where id=new.key_id;
  end if;
  if identity_user_id is null then return new; end if;
  select e.*,d.name,d.color into entitlement
    from public.workspace_member_effective_entitlements e
    left join public.workspace_departments d on d.id=e.department_id
    where e.workspace_id=new.workspace_id and e.user_id=identity_user_id;
  if entitlement is not null then
    new.attributed_user_id=identity_user_id;
    new.attributed_access_role=entitlement.access_role;
    new.attributed_department_id=entitlement.department_id;
    new.attributed_department_name=entitlement.name;
    new.attributed_department_color=entitlement.color;
    new.attribution_basis=case when new.oauth_user_id is not null then 'oauth_user' else 'oauth_key_user' end;
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."snapshot_gateway_request_entitlement"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/stripe_apply_payment_intent_credit.sql
CREATE OR REPLACE FUNCTION public.stripe_apply_payment_intent_credit (
  p_workspace_id      uuid,
  p_payment_intent_id text,
  p_kind              text,
  p_amount_nanos      bigint,
  p_event_time        timestamp with time zone DEFAULT now()
)
  RETURNS TABLE (
    applied              boolean,
    before_balance_nanos bigint,
    after_balance_nanos  bigint,
    status               text
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
    v_existing public.credit_ledger%rowtype;
    v_before bigint;
    v_after bigint;
    v_kind text;
begin
    if p_workspace_id is null then
        raise exception 'missing_workspace_id';
    end if;

    if coalesce(trim(p_payment_intent_id), '') = '' then
        raise exception 'missing_payment_intent_id';
    end if;

    if p_amount_nanos is null or p_amount_nanos <= 0 then
        raise exception 'invalid_amount_nanos';
    end if;

    v_kind := case lower(coalesce(trim(p_kind), ''))
        when 'top_up_one_off' then 'top_up_one_off'
        when 'auto_top_up' then 'auto_top_up'
        else 'top_up'
    end;

    select *
    into v_existing
    from public.credit_ledger
    where ref_type = 'Stripe_Payment_Intent'
      and ref_id = p_payment_intent_id
    for update;

    if found and v_existing.workspace_id is not null and v_existing.workspace_id <> p_workspace_id then
        raise exception 'payment_intent_workspace_mismatch';
    end if;

    if found and lower(coalesce(v_existing.status, '')) in ('paid', 'succeeded') then
        return query
        select
            false,
            coalesce(v_existing.before_balance_nanos, 0)::bigint,
            coalesce(v_existing.after_balance_nanos, 0)::bigint,
            coalesce(v_existing.status, 'Paid');
        return;
    end if;

    if not found then
        insert into public.credit_ledger (
            workspace_id,
            kind,
            amount_nanos,
            before_balance_nanos,
            after_balance_nanos,
            ref_type,
            ref_id,
            status,
            event_time
        ) values (
            p_workspace_id,
            v_kind,
            0,
            0,
            0,
            'Stripe_Payment_Intent',
            p_payment_intent_id,
            'Applying',
            coalesce(p_event_time, now())
        );
    end if;

    update public.wallets
    set balance_nanos = balance_nanos + p_amount_nanos,
        updated_at = now()
    where workspace_id = p_workspace_id
    returning balance_nanos - p_amount_nanos, balance_nanos
    into v_before, v_after;

    if not found then
        raise exception 'wallet_not_found';
    end if;

    update public.credit_ledger
    set workspace_id = p_workspace_id,
        kind = v_kind,
        amount_nanos = p_amount_nanos,
        before_balance_nanos = v_before,
        after_balance_nanos = v_after,
        status = 'Paid',
        event_time = coalesce(p_event_time, now())
    where ref_type = 'Stripe_Payment_Intent'
      and ref_id = p_payment_intent_id;

    return query
    select true, v_before, v_after, 'Paid';
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."stripe_apply_payment_intent_credit"(uuid, text, text, bigint, timestamp WITH time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."stripe_apply_payment_intent_credit"(uuid, text, text, bigint, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/stripe_claim_self_serve_refund.sql
CREATE OR REPLACE FUNCTION public.stripe_claim_self_serve_refund (
  p_team_id           uuid,
  p_payment_intent_id text,
  p_user_id           uuid
)
  RETURNS TABLE (
    ok                   boolean,
    reason               text,
    amount_nanos         bigint,
    before_balance_nanos bigint,
    purchase_time        timestamp with time zone
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
    v_purchase public.credit_ledger%rowtype;
    v_usage_nanos bigint := 0;
    v_has_active_refund boolean := false;
    v_claim_state text;
begin
    select *
    into v_purchase
    from public.credit_ledger
    where team_id = p_team_id
      and ref_type = 'Stripe_Payment_Intent'
      and ref_id = p_payment_intent_id
      and kind in ('top_up', 'top_up_one_off', 'auto_top_up')
    for update;

    if not found then
        return query select false, 'purchase_not_found', 0::bigint, 0::bigint, null::timestamptz;
        return;
    end if;

    if lower(coalesce(v_purchase.status, '')) not in ('paid', 'succeeded') then
        return query select false, 'purchase_not_paid', 0::bigint, 0::bigint, v_purchase.event_time;
        return;
    end if;

    if v_purchase.event_time < now() - interval '24 hours' then
        return query select false, 'window_expired', 0::bigint, 0::bigint, v_purchase.event_time;
        return;
    end if;

    v_claim_state := coalesce(v_purchase.refund_claim_state, '');
    if v_claim_state not in ('', 'Failed', 'Canceled', 'Rejected') then
        return query select false, 'refund_claim_in_progress', 0::bigint, 0::bigint, v_purchase.event_time;
        return;
    end if;

    select exists (
        select 1
        from public.credit_ledger cl
        where cl.team_id = p_team_id
          and cl.kind = 'refund'
          and cl.source_ref_type = 'Stripe_Payment_Intent'
          and cl.source_ref_id = p_payment_intent_id
          and coalesce(cl.status, '') in ('Pending', 'Applying', 'Processing', 'Succeeded')
    ) into v_has_active_refund;

    if v_has_active_refund then
        update public.credit_ledger
        set refund_claim_state = 'Requested',
            refund_claim_reason = 'Refund already in progress.',
            refund_claimed_at = now(),
            refund_claimed_by_user_id = p_user_id
        where id = v_purchase.id;

        return query select false, 'refund_already_exists', 0::bigint, v_purchase.before_balance_nanos, v_purchase.event_time;
        return;
    end if;

    select coalesce(sum(gr.cost_nanos), 0)::bigint
    into v_usage_nanos
    from private.v2_rpc_gateway_requests_compat gr
    where gr.team_id = p_team_id
      and gr.success is true
      and gr.created_at >= v_purchase.event_time;

    if v_usage_nanos > coalesce(v_purchase.before_balance_nanos, 0) then
        update public.credit_ledger
        set refund_claim_state = 'Rejected',
            refund_claim_reason = 'Credits from this top-up have already been used.',
            refund_claimed_at = now(),
            refund_claimed_by_user_id = p_user_id
        where id = v_purchase.id;

        return query select false, 'lot_used', 0::bigint, v_purchase.before_balance_nanos, v_purchase.event_time;
        return;
    end if;

    update public.credit_ledger
    set refund_claim_state = 'Applying',
        refund_claim_reason = null,
        refund_claimed_at = now(),
        refund_claimed_by_user_id = p_user_id
    where id = v_purchase.id;

    return query select true, null::text, v_purchase.amount_nanos, v_purchase.before_balance_nanos, v_purchase.event_time;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."stripe_claim_self_serve_refund"(uuid, text, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."stripe_claim_self_serve_refund"(uuid, text, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/submit_feedback_response.sql
CREATE OR REPLACE FUNCTION public.submit_feedback_response (
  p_token              uuid,
  p_reward_nanos       bigint,
  p_reward_cap         integer,
  p_reward_valid_days  integer
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Records that a feedback token was answered and, while the campaign's reward budget
-- lasts, issues a single-use thank-you credit code. The answers themselves are sent to
-- PostHog by the caller before this runs. Later submissions change nothing and return
-- the original code.
declare
  v_request public.feedback_requests%rowtype;
  v_rewarded integer;
  v_code text;
  v_grant_id uuid;
begin
  select * into v_request
  from public.feedback_requests
  where access_token = p_token
  for update;

  if not found then
    return jsonb_build_object('status', 'not_found');
  end if;

  if v_request.responded_at is not null then
    return jsonb_build_object('status', 'already_submitted', 'rewardCode', v_request.reward_code);
  end if;

  update public.feedback_requests
  set responded_at = now()
  where id = v_request.id;

  if coalesce(p_reward_nanos, 0) <= 0 or coalesce(p_reward_cap, 0) <= 0 then
    return jsonb_build_object('status', 'submitted', 'rewardStatus', 'none');
  end if;

  -- Serialise rewards per campaign so concurrent submissions cannot overrun the cap.
  perform pg_advisory_xact_lock(hashtextextended('feedback_reward:' || v_request.campaign, 0));

  -- Count the codes themselves: a deleted account takes its feedback row with it, but
  -- the code it was given stays redeemable and still spends the budget.
  select count(*)::integer into v_rewarded
  from public.credit_grants
  where note = 'Feedback thank-you (' || v_request.campaign || ')';

  if v_rewarded >= p_reward_cap then
    return jsonb_build_object('status', 'submitted', 'rewardStatus', 'budget_exhausted');
  end if;

  v_code := 'THANKS-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12));

  insert into public.credit_grants (code, code_normalized, amount_nanos, max_redemptions, expires_at, note)
  values (
    v_code,
    v_code,
    p_reward_nanos,
    1,
    now() + make_interval(days => greatest(coalesce(p_reward_valid_days, 90), 1)),
    'Feedback thank-you (' || v_request.campaign || ')'
  )
  returning id into v_grant_id;

  update public.feedback_requests
  set reward_grant_id = v_grant_id, reward_code = v_code
  where id = v_request.id;

  return jsonb_build_object('status', 'submitted', 'rewardStatus', 'issued', 'rewardCode', v_code);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."submit_feedback_response"(uuid, bigint, integer, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."submit_feedback_response"(uuid, bigint, integer, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/sweep_department_budget_alerts.sql
CREATE OR REPLACE FUNCTION public.sweep_department_budget_alerts (
  p_now timestamp with time zone DEFAULT now()
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Sends a money push to owners and admins once per department budget, period and limit value
-- when the department reaches about 80% of the budget (department_budget_warning), and again
-- when it reaches 100% (department_budget_reached). The gateway refuses the department's API-key
-- requests at 100% (batch, realtime and OAuth requests excepted) without sending a push, so the
-- 100% alert comes from this sweep and says those requests are refused until the budget resets.
-- Spend is workspace_department_budget_status's, which lags by up to an hour, so the pushes say
-- "about" and can arrive after blocking has started. No warning is sent once the budget is
-- reached. A limit changed mid-period can alert again. Only workspaces with a department budget
-- are read.
declare
  v_budgets integer;
  v_alerted integer := 0;
  v_count integer;
  v_workspace uuid;
begin
  if p_now is null then
    raise exception 'invalid_department_budget_sweep_time';
  end if;

  select count(*) into v_budgets from public.workspace_department_budgets;
  if v_budgets = 0 then
    return jsonb_build_object('budgets', 0, 'alerted', 0);
  end if;

  for v_workspace in select distinct b.workspace_id from public.workspace_department_budgets b loop
    with status as (
      select
        (s ->> 'id') as budget_id,
        (s ->> 'department_name') as department_name,
        (s ->> 'interval') as time_window,
        (s ->> 'limit_nanos')::numeric as limit_value,
        (s ->> 'usage_nanos')::numeric as used
      from jsonb_array_elements(public.workspace_department_budget_status(v_workspace, p_now)) s
    ),
    due as (
      select
        st.*,
        p.period_start,
        p.reset_at,
        case when st.used >= st.limit_value then 'department_budget_reached' else 'department_budget_warning' end as kind,
        to_char(p.period_start at time zone 'UTC', 'YYYY-MM-DD') || ':' || st.limit_value as period_key,
        case when char_length(st.department_name) > 40 then left(st.department_name, 39) || '…' else st.department_name end as name,
        case st.time_window when 'daily' then ' so far today.' when 'weekly' then ' so far this week.' else ' so far this month.' end as so_far
      from status st
      cross join lateral private.spend_limit_period(st.time_window, p_now) p
      where st.used >= 0.8 * st.limit_value
    ),
    inserted as (
      insert into public.workspace_notification_events (workspace_id, kind, category, dedupe_key, payload, occurred_at)
      select
        v_workspace,
        d.kind,
        'money',
        d.kind || ':department_budget:' || d.budget_id || ':' || d.time_window || ':' || d.period_key,
        jsonb_build_object(
          'push', jsonb_build_object(
            'title', case when d.kind = 'department_budget_reached'
              then d.name || ' has used its ' || d.time_window || ' budget'
              else d.name || ' is at about 80% of its ' || d.time_window || ' budget' end,
            'body', private.spend_limit_amount('cost', d.used) || ' of ' || private.spend_limit_amount('cost', d.limit_value)
              || d.so_far
              || case when d.kind = 'department_budget_reached' then ' Requests from the department''s API keys are now refused until the budget resets (batch jobs, realtime sessions and OAuth requests excepted).' else '' end,
            'href', '/settings/usage/overview'
          ),
          'departmentBudgetId', d.budget_id, 'window', d.time_window, 'metric', 'cost',
          'limit', d.limit_value, 'used', d.used, 'periodStart', d.period_start, 'resetAt', d.reset_at
        ),
        p_now
      from due d
      where d.kind = 'department_budget_reached'
        or not exists (
          select 1 from public.workspace_notification_events e
          where e.dedupe_key = 'department_budget_reached:department_budget:' || d.budget_id || ':' || d.time_window || ':' || d.period_key
        )
      on conflict (dedupe_key) do nothing
      returning 1
    )
    select count(*)::integer into v_count from inserted;
    v_alerted := v_alerted + v_count;
  end loop;

  return jsonb_build_object('budgets', v_budgets, 'alerted', v_alerted);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."sweep_department_budget_alerts"(timestamp with time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."sweep_department_budget_alerts"(timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/sweep_low_balance_emails.sql
CREATE OR REPLACE FUNCTION public.sweep_low_balance_emails (
  p_now       timestamp with time zone DEFAULT now(),
  p_mark_sent boolean                  DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- The low-balance email, off the request path. The API scheduled job runs it every five minutes.
-- It replaces the check the gateway used to make after every charged request, with the same
-- threshold and message, and the armed/unarmed rules of sweep_low_balance_pushes:
--   * Watched: workspaces with low_balance_email_enabled (workspace_settings_low_balance_email_idx)
--     and a wallet. The wallet balance (balance_nanos, as before) is compared with
--     low_balance_email_threshold_nanos; a $0 threshold alerts once the balance reaches $0.
--   * A workspace is armed while its balance is above the threshold. Found armed at or below it,
--     that is a drop: one low_balance email to the owner, and it stays unarmed until a sweep finds
--     the balance back above the threshold (a top-up or credit).
--   * Cooldown: at most one email every six hours, read from
--     workspace_settings.low_balance_email_last_sent_at, which this sweep keeps writing (so the old
--     request-path check and this sweep honour each other's sends during a rollout or rollback).
--     A drop inside the cooldown stays armed and is emailed once the cooldown ends, if the balance
--     is still low. As before, a send whose recorded balance is above today's threshold (the
--     threshold was lowered) does not hold the cooldown.
--   * While auto top-up is on and working (private.workspace_auto_top_up_covers, as for the push),
--     a drop is recorded without an email: the wallet refills, and a failed top-up has its own email.
--   * First seen at or below the threshold, a workspace is armed only if it has credit and was
--     never emailed, which is when the request-path check would still have emailed it on its next
--     charge; otherwise it starts unarmed, so switching to the sweep sends no burst of repeats.
--   * Each email is an email_outbox row of kind and template low_balance with the payload the
--     request path wrote (user_first_name, workspace_id, team_name, balance_nanos, balance_usd,
--     threshold_nanos, threshold_usd), deduped by low_balance_email:<workspace>:<sweep time>.
--     With p_mark_sent (Resend automations on) the row is written as sent, and the job sends the
--     Resend event for each email returned; otherwise the email outbox drain sends it.
--   * State lives in workspace_low_balance_email_state, written only when armed changes or a
--     workspace is first seen, so an idle sweep writes nothing.
-- Sweeps run one at a time; a call that finds another in progress returns at once. Returns the
-- counts and "emails": what was queued, for the Resend events.
declare
  v_cooldown constant interval := interval '6 hours';
  v_result jsonb;
begin
  if p_now is null then
    raise exception 'invalid_low_balance_email_sweep_time';
  end if;
  if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('sweep_low_balance_emails', 0)) then
    return jsonb_build_object('skipped', true, 'watched', 0, 'firstSeen', 0, 'dropped', 0, 'rearmed', 0, 'coveredByTopUp', 0,
      'waiting', 0, 'emailed', 0, 'emails', '[]'::jsonb);
  end if;

  with observed as (
    select
      s.workspace_id,
      w.balance_nanos,
      s.low_balance_email_threshold_nanos as threshold_nanos,
      w.balance_nanos <= s.low_balance_email_threshold_nanos as low,
      st.workspace_id is not null as seen,
      coalesce(st.armed,
        w.balance_nanos > s.low_balance_email_threshold_nanos
          or (w.balance_nanos > 0 and s.low_balance_email_last_sent_at is null)) as armed,
      s.low_balance_email_last_sent_at > p_now - v_cooldown
        and not coalesce(s.low_balance_email_last_sent_balance_nanos > s.low_balance_email_threshold_nanos, false) as cooling
    -- workspace_settings_low_balance_email_idx
    from public.workspace_settings s
    join public.wallets w on w.workspace_id = s.workspace_id
    left join public.workspace_low_balance_email_state st on st.workspace_id = s.workspace_id
    where s.low_balance_email_enabled
      and s.low_balance_email_threshold_nanos >= 0
  ),
  decided as (
    -- alert: a drop to email; covered: a drop auto top-up handles; waiting: a drop inside the
    -- cooldown (stays armed); rearm: back above; idle: nothing changed.
    select observed.*,
      case
        when observed.armed and observed.low and observed.cooling then 'waiting'
        when observed.armed and observed.low and private.workspace_auto_top_up_covers(observed.workspace_id) then 'covered'
        when observed.armed and observed.low then 'alert'
        when not observed.armed and not observed.low then 'rearm'
        else 'idle'
      end as action
    from observed
  ),
  recipients as (
    select decided.workspace_id, decided.balance_nanos, decided.threshold_nanos, ws.owner_user_id, owner.email,
      coalesce(ws.name, 'your team') as team_name,
      coalesce((regexp_split_to_array(coalesce(
        nullif(btrim(owner.raw_user_meta_data ->> 'first_name'), ''),
        nullif(btrim(owner.raw_user_meta_data ->> 'given_name'), ''),
        nullif(btrim(owner.raw_user_meta_data ->> 'full_name'), ''),
        nullif(btrim(owner.raw_user_meta_data ->> 'name'), '')
      ), '\s+'))[1], 'there') as first_name
    from decided
    join public.workspaces ws on ws.id = decided.workspace_id
    join auth.users owner on owner.id = ws.owner_user_id
    where decided.action = 'alert'
      and nullif(btrim(owner.email), '') is not null
  ),
  queued as (
    insert into public.email_outbox (kind, template, to_email, subject, workspace_id, user_id, payload, dedupe_key, sent_at)
    select
      'low_balance',
      'low_balance',
      r.email,
      'Low balance alert',
      r.workspace_id,
      r.owner_user_id,
      jsonb_build_object(
        'user_first_name', r.first_name,
        'workspace_id', r.workspace_id,
        'team_name', r.team_name,
        'balance_nanos', r.balance_nanos,
        'balance_usd', round(greatest(r.balance_nanos, 0)::numeric / 1000000000, 2),
        'threshold_nanos', r.threshold_nanos,
        'threshold_usd', round(r.threshold_nanos::numeric / 1000000000, 2)
      ),
      'low_balance_email:' || r.workspace_id || ':' || to_char(p_now at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
      case when p_mark_sent then p_now end
    from recipients r
    on conflict (dedupe_key) do nothing
    returning id, workspace_id, to_email, payload
  ),
  saved as (
    -- First sight, a drop (emailed, covered by auto top-up or without an owner to email) or a
    -- recovery. A drop waiting out the cooldown keeps its state.
    insert into public.workspace_low_balance_email_state as st (workspace_id, armed, balance_nanos, threshold_nanos, changed_at, last_alert_at, created_at)
    select d.workspace_id,
      case d.action when 'alert' then false when 'covered' then false when 'rearm' then true else d.armed end,
      d.balance_nanos, d.threshold_nanos, p_now,
      case when q.workspace_id is not null then p_now end,
      p_now
    from decided d
    left join queued q on q.workspace_id = d.workspace_id
    where d.action in ('alert', 'covered', 'rearm') or not d.seen
    on conflict (workspace_id) do update set
      armed = excluded.armed,
      balance_nanos = excluded.balance_nanos,
      threshold_nanos = excluded.threshold_nanos,
      changed_at = excluded.changed_at,
      last_alert_at = coalesce(excluded.last_alert_at, st.last_alert_at)
    returning st.workspace_id
  ),
  stamped as (
    -- The cooldown the request-path check used, kept so either side respects the other's sends.
    update public.workspace_settings s
    set low_balance_email_last_sent_at = p_now,
        low_balance_email_last_sent_balance_nanos = queued.balance_nanos,
        updated_at = p_now
    from (select q.workspace_id, (q.payload ->> 'balance_nanos')::bigint as balance_nanos from queued q) queued
    where s.workspace_id = queued.workspace_id
    returning 1
  )
  select jsonb_build_object(
    'watched', (select count(*) from observed),
    'firstSeen', (select count(*) from decided where not decided.seen),
    'dropped', (select count(*) from decided where decided.action in ('alert', 'covered')),
    'rearmed', (select count(*) from decided where decided.action = 'rearm' and decided.seen),
    'coveredByTopUp', (select count(*) from decided where decided.action = 'covered'),
    'waiting', (select count(*) from decided where decided.action = 'waiting'),
    'emailed', (select count(*) from queued),
    'stamped', (select count(*) from stamped),
    'saved', (select count(*) from saved),
    'emails', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', q.id,
        'workspace_id', q.workspace_id,
        'to_email', q.to_email,
        'user_first_name', q.payload -> 'user_first_name',
        'team_name', q.payload -> 'team_name',
        'balance_nanos', q.payload -> 'balance_nanos',
        'balance_usd', q.payload -> 'balance_usd',
        'threshold_nanos', q.payload -> 'threshold_nanos',
        'threshold_usd', q.payload -> 'threshold_usd'
      ) order by q.workspace_id)
      from queued q
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$function$;

COMMENT ON FUNCTION "public"."sweep_low_balance_emails"(timestamp with time zone, boolean) IS 'Queues the low-balance email (kind low_balance) once per drop to or below a workspace''s low_balance_email_threshold_nanos, at most every six hours, never while auto top-up is working; re-arms once the balance is back above. Replaces the request-path check. Called every 5 minutes by the API scheduled job; p_mark_sent writes the rows as sent when Resend automations deliver them.';

GRANT EXECUTE ON FUNCTION "public"."sweep_low_balance_emails"(timestamp with time zone, boolean) TO "service_role";

REVOKE ALL ON FUNCTION "public"."sweep_low_balance_emails"(timestamp with time zone, boolean) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/sweep_low_balance_pushes.sql
CREATE OR REPLACE FUNCTION public.sweep_low_balance_pushes (
  p_now timestamp with time zone DEFAULT now()
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Pushes a low balance once per drop to owners and admins, whatever the workspace's low-balance
-- email setting. The mobile push job runs it every five minutes, just before the workspace fan-out.
--   * Only workspaces where an owner or admin has push on, the money category on and an active
--     device are read: the wallet balance against the workspace's low-balance threshold, or $5
--     without one (an alert switched off in the web settings stores 0).
--   * A workspace is armed while its balance is above the threshold. Found armed at or below it,
--     that is a drop: one low_balance event for the fan-out, and it stays unarmed until a sweep
--     finds the balance back above the threshold (a top-up or credit). First seen, it is armed
--     only if above, so a workspace that never had credits is never told.
--   * While auto top-up is on and working, a drop is recorded but not pushed: the gateway refills
--     the wallet, and a failed top-up has its own push. Working means enabled with at least $1 to
--     add (smaller amounts are skipped without an alert) and a trigger above $0 (a $0 trigger never
--     fires), failure alerts on (the failure push comes from that email), and no failed top-up
--     since the last card payment (private.workspace_auto_top_up_covers, shared with the
--     low-balance email sweep and balance spend rules).
--   * The forecast for the push text, credits charged over the last seven days
--     (get_workspace_recent_credit_spend), is worked out only for a drop that is pushed.
--   * State lives in workspace_low_balance_push_state, written only when it changes, so an idle
--     sweep writes nothing.
-- Sweeps run one at a time; a call that finds another in progress returns at once.
declare
  v_default_threshold constant bigint := 5000000000;
  v_result jsonb;
begin
  if p_now is null then
    raise exception 'invalid_low_balance_sweep_time';
  end if;
  if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('sweep_low_balance_pushes', 0)) then
    return jsonb_build_object('skipped', true, 'watched', 0, 'firstSeen', 0, 'dropped', 0, 'rearmed', 0, 'coveredByTopUp', 0, 'alerted', 0);
  end if;

  with watched as (
    select distinct m.workspace_id
    from public.mobile_notification_preferences p
    join public.workspace_members m on m.user_id = p.user_id and m.role in ('owner', 'admin')
    where p.enabled
      and (p.categories -> 'money') is distinct from 'false'::jsonb
      and exists (select 1 from public.mobile_push_devices d where d.user_id = p.user_id and d.status = 'active')
  ),
  observed as (
    select
      w.workspace_id,
      w.balance_nanos,
      case when s.low_balance_email_threshold_nanos > 0 then s.low_balance_email_threshold_nanos else v_default_threshold end as threshold_nanos,
      coalesce(s.low_balance_email_threshold_nanos > 0, false) as own_threshold,
      private.workspace_auto_top_up_covers(w.workspace_id) as top_up_covers,
      st.workspace_id is not null as seen
    from watched x
    join public.wallets w on w.workspace_id = x.workspace_id
    left join public.workspace_settings s on s.workspace_id = x.workspace_id
    left join public.workspace_low_balance_push_state st on st.workspace_id = x.workspace_id
  ),
  first_seen as (
    insert into public.workspace_low_balance_push_state (workspace_id, armed, balance_nanos, threshold_nanos, changed_at, created_at)
    select o.workspace_id, o.balance_nanos > o.threshold_nanos, o.balance_nanos, o.threshold_nanos, p_now, p_now
    from observed o
    where not o.seen
    on conflict (workspace_id) do nothing
    returning workspace_id
  ),
  changed as (
    -- Only rows whose state flips: armed and now at or below the threshold, or unarmed and above.
    update public.workspace_low_balance_push_state st
    set armed = not st.armed,
        balance_nanos = o.balance_nanos,
        threshold_nanos = o.threshold_nanos,
        changed_at = p_now,
        last_alert_at = case when st.armed and not o.top_up_covers then p_now else st.last_alert_at end
    from observed o
    where o.seen
      and st.workspace_id = o.workspace_id
      and st.armed = (o.balance_nanos <= o.threshold_nanos)
    returning st.workspace_id, st.armed, o.balance_nanos, o.threshold_nanos, o.own_threshold, o.top_up_covers
  ),
  alerted as (
    insert into public.workspace_notification_events (workspace_id, kind, category, dedupe_key, payload, occurred_at)
    select
      c.workspace_id,
      'low_balance',
      'money',
      'low_balance:' || c.workspace_id || ':' || to_char(p_now at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
      jsonb_build_object(
        'balance_nanos', c.balance_nanos,
        'threshold_nanos', c.threshold_nanos,
        'threshold_source', case when c.own_threshold then 'workspace' else 'default' end,
        'recent_spend_nanos', public.get_workspace_recent_credit_spend(c.workspace_id, p_now - interval '7 days'),
        'spend_window_days', 7
      ),
      p_now
    from changed c
    where not c.armed and not c.top_up_covers
    on conflict (dedupe_key) do nothing
    returning 1
  )
  select jsonb_build_object(
    'watched', (select count(*) from observed),
    'firstSeen', (select count(*) from first_seen),
    'dropped', (select count(*) from changed c where not c.armed),
    'rearmed', (select count(*) from changed c where c.armed),
    'coveredByTopUp', (select count(*) from changed c where not c.armed and c.top_up_covers),
    'alerted', (select count(*) from alerted)
  ) into v_result;

  return v_result;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."sweep_low_balance_pushes"(timestamp with time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."sweep_low_balance_pushes"(timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/sweep_spend_limit_warnings.sql
CREATE OR REPLACE FUNCTION public.sweep_spend_limit_warnings (
  p_now timestamp with time zone DEFAULT now()
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Warns once when a workspace budget or an active API key's limit is about 80% used in its
-- current period, as a money push: owners and admins hear about it, and for a key limit so does
-- the key's creator. Usage comes from v2_private_usage_15m (cost, and successful requests for
-- request limits), which is rebuilt hourly and so lags; the push says "about". The rollup leaves
-- out async jobs and realtime sessions, which the gateway's limits count, so their successful
-- requests are added from gateway_requests through a small partial index. Nothing is sent
-- for a limit already reached this period (record_spend_limit_reached), or one the rollup puts
-- at 100% or more: the gateway blocks the next request and that alert follows. Weekly and
-- monthly warnings say when the limit runs out at the period's pace so far, if that is before
-- the period ends. One event per budget or key limit, period and limit value, so a limit raised
-- mid-period can warn again. Only workspaces with a budget or a limited key are read.
declare
  v_day timestamptz := (private.spend_limit_period('daily', p_now)).period_start;
  v_week timestamptz := (private.spend_limit_period('weekly', p_now)).period_start;
  v_month timestamptz := (private.spend_limit_period('monthly', p_now)).period_start;
  v_budgets integer;
  v_keys integer;
  v_warned integer;
begin
  if p_now is null then
    raise exception 'invalid_spend_limit_sweep_time';
  end if;

  select count(*) into v_budgets from public.workspace_budgets;
  select count(*) into v_keys
  from public.keys k
  where k.status = 'active'
    and greatest(k.daily_limit_requests, k.weekly_limit_requests, k.monthly_limit_requests,
      k.daily_limit_cost_nanos, k.weekly_limit_cost_nanos, k.monthly_limit_cost_nanos) > 0;
  if v_budgets = 0 and v_keys = 0 then
    return jsonb_build_object('budgets', 0, 'limitedKeys', 0, 'warned', 0);
  end if;

  with limited_keys as (
    select k.id, k.workspace_id, k.name, k.created_by,
      k.daily_limit_requests, k.weekly_limit_requests, k.monthly_limit_requests,
      k.daily_limit_cost_nanos, k.weekly_limit_cost_nanos, k.monthly_limit_cost_nanos
    from public.keys k
    where k.status = 'active'
      and greatest(k.daily_limit_requests, k.weekly_limit_requests, k.monthly_limit_requests,
        k.daily_limit_cost_nanos, k.weekly_limit_cost_nanos, k.monthly_limit_cost_nanos) > 0
  ),
  async_requests as (
    -- Async jobs and realtime sessions, which the rollup leaves out (gateway_requests_async_spend_idx).
    select r.key_id, r.created_at, 1::bigint as requests, coalesce(r.cost_nanos, 0)::numeric as cost_nanos
    from public.gateway_requests r
    where r.success is true
      and r.endpoint = any (array['video.generation', 'batch', 'music.generate', 'audio.realtime'])
      and r.workspace_id in (select k.workspace_id from limited_keys k)
      and r.created_at >= least(v_week, v_month)
      and r.created_at <= p_now
      and r.key_id in (select k.id from limited_keys k)
  ),
  key_usage as (
    -- One pass over each limited key's workspace since the earlier of this week's and this month's start.
    select
      u.key_id,
      coalesce(sum(u.successful_requests) filter (where u.bucket_start >= v_day), 0) as day_requests,
      coalesce(sum(u.successful_requests) filter (where u.bucket_start >= v_week), 0) as week_requests,
      coalesce(sum(u.successful_requests) filter (where u.bucket_start >= v_month), 0) as month_requests,
      coalesce(sum(u.cost_nanos) filter (where u.bucket_start >= v_day), 0) as day_cost,
      coalesce(sum(u.cost_nanos) filter (where u.bucket_start >= v_week), 0) as week_cost,
      coalesce(sum(u.cost_nanos) filter (where u.bucket_start >= v_month), 0) as month_cost
    from (
      select u.key_id, u.bucket_start, u.successful_requests, u.cost_nanos
      from public.v2_private_usage_15m u
      where u.workspace_id in (select k.workspace_id from limited_keys k)
        and u.bucket_start >= least(v_week, v_month)
        and u.bucket_start <= p_now
        and u.key_id in (select k.id from limited_keys k)
      union all
      select a.key_id, a.created_at, a.requests, a.cost_nanos from async_requests a
    ) u
    group by u.key_id
  ),
  limits as (
    select
      b.workspace_id, null::uuid as key_id, null::text as key_name, null::uuid as key_created_by,
      'budget_warning' as kind, 'budget:' || b.id as subject, b.interval as time_window, 'cost' as metric,
      b.limit_nanos::numeric as limit_value,
      (
        select coalesce(sum(u.cost_nanos), 0)
        from public.v2_private_usage_15m u
        where u.workspace_id = b.workspace_id
          and u.bucket_start >= coalesce((private.spend_limit_period(b.interval, p_now)).period_start, '-infinity'::timestamptz)
          and u.bucket_start <= p_now
      ) + (
        select coalesce(sum(r.cost_nanos), 0)
        from public.gateway_requests r
        where r.success is true
          and r.endpoint = any (array['video.generation', 'batch', 'music.generate', 'audio.realtime'])
          and r.workspace_id = b.workspace_id
          and r.created_at >= coalesce((private.spend_limit_period(b.interval, p_now)).period_start, '-infinity'::timestamptz)
          and r.created_at <= p_now
      ) as used
    from public.workspace_budgets b
    union all
    select
      k.workspace_id, k.id, k.name, k.created_by,
      'key_limit_warning', 'key:' || k.id || ':' || l.metric, l.time_window, l.metric,
      l.limit_value::numeric,
      l.used
    from limited_keys k
    left join key_usage ku on ku.key_id = k.id
    cross join lateral (values
      ('daily', 'requests', k.daily_limit_requests, coalesce(ku.day_requests, 0)::numeric),
      ('weekly', 'requests', k.weekly_limit_requests, coalesce(ku.week_requests, 0)::numeric),
      ('monthly', 'requests', k.monthly_limit_requests, coalesce(ku.month_requests, 0)::numeric),
      ('daily', 'cost', k.daily_limit_cost_nanos, coalesce(ku.day_cost, 0)::numeric),
      ('weekly', 'cost', k.weekly_limit_cost_nanos, coalesce(ku.week_cost, 0)::numeric),
      ('monthly', 'cost', k.monthly_limit_cost_nanos, coalesce(ku.month_cost, 0)::numeric)
    ) l(time_window, metric, limit_value, used)
    where l.limit_value > 0
  ),
  due as (
    select
      l.*,
      p.period_start,
      p.reset_at,
      coalesce(to_char(p.period_start at time zone 'UTC', 'YYYY-MM-DD'), 'lifetime') || ':' || l.limit_value as period_key,
      case
        when l.time_window in ('weekly', 'monthly') and l.used > 0
          and p.period_start + (p_now - p.period_start) * (l.limit_value / l.used)::double precision < p.reset_at
          then p.period_start + (p_now - p.period_start) * (l.limit_value / l.used)::double precision
      end as runs_out_at,
      case when l.key_name is null then null
        when char_length(l.key_name) > 40 then '''' || left(l.key_name, 39) || '…'''
        else '''' || l.key_name || ''''
      end as quoted_key,
      case l.time_window when 'daily' then ' so far today.' when 'weekly' then ' so far this week.' when 'monthly' then ' so far this month.' else ' in total.' end as so_far
    from limits l
    cross join lateral private.spend_limit_period(l.time_window, p_now) p
    where l.used >= 0.8 * l.limit_value
      and l.used < l.limit_value
  ),
  inserted as (
    insert into public.workspace_notification_events (workspace_id, kind, category, dedupe_key, key_id, key_created_by, payload, occurred_at)
    select
      d.workspace_id,
      d.kind,
      'money',
      d.kind || ':' || d.subject || ':' || d.time_window || ':' || d.period_key,
      d.key_id,
      d.key_created_by,
      jsonb_build_object(
        'push', jsonb_build_object(
          'title', case when d.kind = 'budget_warning'
            then 'About 80% of the ' || d.time_window || ' budget used'
            else 'API key ' || d.quoted_key || ' is at about 80% of its ' || d.time_window || ' limit' end,
          'body', case when d.metric = 'cost'
              then private.spend_limit_amount('cost', d.used) || ' of ' || private.spend_limit_amount('cost', d.limit_value)
              else to_char(d.used, 'FM999,999,999,990') || ' of ' || private.spend_limit_amount('requests', d.limit_value) end
            || d.so_far
            || coalesce(' At this pace it runs out around ' || to_char(d.runs_out_at at time zone 'UTC', 'Mon FMDD') || '.', ''),
          'href', case when d.kind = 'budget_warning' then '/settings/usage/overview' else '/settings/keys' end,
          'lowerLead', d.kind = 'budget_warning'
        ),
        'window', d.time_window, 'metric', d.metric, 'limit', d.limit_value, 'used', d.used,
        'periodStart', d.period_start, 'resetAt', d.reset_at, 'runsOutAt', d.runs_out_at
      ),
      p_now
    from due d
    where not exists (
      select 1 from public.workspace_notification_events e
      where e.dedupe_key = replace(d.kind, '_warning', '_reached') || ':' || d.subject || ':' || d.time_window || ':' || d.period_key
    )
    on conflict (dedupe_key) do nothing
    returning 1
  )
  select count(*)::integer into v_warned from inserted;

  return jsonb_build_object('budgets', v_budgets, 'limitedKeys', v_keys, 'warned', v_warned);
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."sweep_spend_limit_warnings"(timestamp with time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."sweep_spend_limit_warnings"(timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/sweep_spend_rules.sql
CREATE OR REPLACE FUNCTION public.sweep_spend_rules (
  p_now   timestamp with time zone DEFAULT now(),
  p_limit  integer                  DEFAULT 100,
  p_blocks boolean                  DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Evaluates spend rules (private.evaluate_workspace_spend_rules) for four sets of workspaces,
-- each up to p_limit, every workspace at most once per call:
--   1. dirty:    workspace_spend_rule_dirty rows, which process_v2_analytics_outbox writes when
--                it rebuilds a workspace's usage. They are claimed with SKIP LOCKED and deleted
--                as they are claimed, oldest first; a workspace marked again while this runs is
--                kept for the next call.
--   2. rollover: workspaces with an enabled rule that has no state row for its current period,
--                so a new day, week or month (in the rule's time zone) or a new rule is picked up
--                within one call, with or without traffic, and workspaces with an active block
--                past its reset, so the block lifts on time.
--   3. periodic: one twelfth of the workspaces with enabled rules, by a hash of the workspace id
--                and the 5-minute slot of p_now, so each is evaluated about once an hour when
--                called every 5 minutes. This catches changes no usage marks: a budget or key
--                limit lowered, a rule edited, rollup hours rebuilt late. A slot over p_limit
--                rotates hourly, so none of its workspaces is skipped for good.
--   4. balance:  workspaces with balance rules, in one of three slices by the same hash (each
--                every 15 minutes): a balance falls or recovers without new usage (reservations,
--                refunds, top-ups, credits), so balance rules cannot wait for the dirty mark.
-- Workspaces that no longer exist are skipped. One sweep runs at a time; a concurrent call
-- returns skipped_locked. p_blocks (SPEND_RULE_BLOCKS_ENABLED) lets block rules start blocks;
-- blocks are lifted either way. Returns the counts, the events queued, the block changes
-- ("blocks": [{workspace_id, block_id, rule_id, state, reason, event_id}]) and "publish": the
-- evaluated workspaces with block rules or blocks, whose gateway entry the job republishes.
declare
  v_slots constant integer := 12;
  v_slot integer;
  v_round bigint;
  v_dirty uuid[];
  v_rollover uuid[];
  v_periodic uuid[];
  v_balance_slots constant integer := 3;
  v_balance_round bigint;
  v_balance uuid[];
  v_workspace uuid;
  v_result jsonb;
  v_events jsonb := '[]'::jsonb;
  v_blocks jsonb := '[]'::jsonb;
  v_publish uuid[] := '{}';
  v_evaluated integer := 0;
  v_rules integer := 0;
  v_fired integer := 0;
  v_state_rows integer := 0;
begin
  if p_now is null then
    raise exception 'invalid_spend_rule_sweep_time';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception 'invalid_spend_rule_sweep_limit';
  end if;
  if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('public.sweep_spend_rules', 0)) then
    return jsonb_build_object('skipped_locked', true, 'dirty', 0, 'rollover', 0, 'periodic', 0, 'balance', 0, 'evaluated', 0,
      'rules', 0, 'fired', 0, 'state_rows', 0, 'events', '[]'::jsonb, 'blocks', '[]'::jsonb, 'publish', '[]'::jsonb);
  end if;

  with claimed as (
    delete from public.workspace_spend_rule_dirty dirty
    where dirty.workspace_id in (
      select candidate.workspace_id
      from public.workspace_spend_rule_dirty candidate
      order by candidate.dirtied_at, candidate.workspace_id
      limit p_limit
      for update skip locked
    )
    returning dirty.workspace_id
  )
  select coalesce(array_agg(claimed.workspace_id), '{}') into v_dirty from claimed;

  select coalesce(array_agg(due.workspace_id), '{}') into v_rollover
  from (
    select rule.workspace_id
    from public.workspace_spend_rules rule
    left join public.workspace_settings settings on settings.workspace_id = rule.workspace_id
    cross join lateral private.spend_rule_period(rule.period, coalesce(rule.time_zone, settings.billing_time_zone, 'UTC'), p_now) period
    where rule.enabled
      and rule.deleted_at is null
      and private.spend_rule_evaluable(rule.metric, rule.period, rule.base_kind)
      and rule.workspace_id <> all (v_dirty)
      and not exists (
        select 1 from public.workspace_spend_rule_state state
        where state.rule_id = rule.id and state.period_start = period.period_start
      )
    union
    -- workspace_spend_blocks_workspace_active_idx
    select block.workspace_id
    from public.workspace_spend_blocks block
    where block.lifted_at is null
      and block.resets_at <= p_now
      and block.workspace_id <> all (v_dirty)
    order by 1
    limit p_limit
  ) due;

  v_slot := (floor(extract(epoch from p_now) / 300)::bigint % v_slots)::integer;
  -- A slot with more than p_limit workspaces starts p_limit further along each hour, so every
  -- workspace in it is reached within ceil(n / p_limit) hours instead of only the first p_limit.
  v_round := floor(extract(epoch from p_now) / 3600)::bigint;
  select coalesce(array_agg(due.workspace_id), '{}') into v_periodic
  from (
    select slot.workspace_id
    from (
      select candidate.workspace_id,
        pg_catalog.row_number() over (order by candidate.workspace_id) - 1 as position,
        pg_catalog.count(*) over () as total
      from (
        select distinct rule.workspace_id
        from public.workspace_spend_rules rule
        where rule.enabled
          and rule.deleted_at is null
          and private.spend_rule_evaluable(rule.metric, rule.period, rule.base_kind)
          and (pg_catalog.hashtextextended(rule.workspace_id::text, 0) % v_slots + v_slots) % v_slots = v_slot
          and rule.workspace_id <> all (v_dirty)
          and rule.workspace_id <> all (v_rollover)
      ) candidate
    ) slot
    where ((slot.position - v_round * p_limit) % slot.total + slot.total) % slot.total < p_limit
  ) due;

  -- Balance rules: a balance moves without usage (reservations, refunds, top-ups, credits), so
  -- workspaces with balance rules are also taken in one of three slices by the same hash, that
  -- is every 15 minutes when called every 5 minutes. Like the periodic slot, a slice with more
  -- than p_limit workspaces starts p_limit further along on each visit. Positions are taken over
  -- the whole slice and workspaces another set already evaluates are dropped afterwards, so the
  -- window does not shift with them and every workspace is reached within ceil(n / p_limit) visits.
  v_balance_round := floor(extract(epoch from p_now) / 900)::bigint;
  select coalesce(array_agg(due.workspace_id), '{}') into v_balance
  from (
    select slice.workspace_id
    from (
      select candidate.workspace_id,
        pg_catalog.row_number() over (order by candidate.workspace_id) - 1 as position,
        pg_catalog.count(*) over () as total
      from (
        select distinct rule.workspace_id
        from public.workspace_spend_rules rule
        where rule.metric = 'balance'
          and rule.enabled
          and rule.deleted_at is null
          and private.spend_rule_evaluable(rule.metric, rule.period, rule.base_kind)
          and (pg_catalog.hashtextextended(rule.workspace_id::text, 0) % v_balance_slots + v_balance_slots) % v_balance_slots
            = v_slot % v_balance_slots
      ) candidate
    ) slice
    where ((slice.position - v_balance_round * p_limit) % slice.total + slice.total) % slice.total < p_limit
      and slice.workspace_id <> all (v_dirty)
      and slice.workspace_id <> all (v_rollover)
      and slice.workspace_id <> all (v_periodic)
  ) due;

  foreach v_workspace in array v_dirty || v_rollover || v_periodic || v_balance loop
    v_result := private.evaluate_workspace_spend_rules(v_workspace, p_now, coalesce(p_blocks, false));
    if coalesce((v_result ->> 'missing')::boolean, false) then
      continue;
    end if;
    v_evaluated := v_evaluated + 1;
    v_rules := v_rules + coalesce((v_result ->> 'rules')::integer, 0);
    v_fired := v_fired + coalesce((v_result ->> 'fired')::integer, 0);
    v_state_rows := v_state_rows + coalesce((v_result ->> 'state_rows')::integer, 0);
    if jsonb_array_length(v_result -> 'events') > 0 then
      v_events := v_events || (
        select jsonb_agg(event || jsonb_build_object('workspace_id', v_workspace))
        from jsonb_array_elements(v_result -> 'events') event
      );
    end if;
    if jsonb_array_length(coalesce(v_result -> 'blocks', '[]'::jsonb)) > 0 then
      v_blocks := v_blocks || (
        select jsonb_agg(block || jsonb_build_object('workspace_id', v_workspace))
        from jsonb_array_elements(v_result -> 'blocks') block
      );
    end if;
    if coalesce((v_result ->> 'block_scope')::boolean, false) then
      v_publish := v_publish || v_workspace;
    end if;
  end loop;

  return jsonb_build_object(
    'dirty', cardinality(v_dirty),
    'rollover', cardinality(v_rollover),
    'periodic', cardinality(v_periodic),
    'balance', cardinality(v_balance),
    'evaluated', v_evaluated,
    'rules', v_rules,
    'fired', v_fired,
    'state_rows', v_state_rows,
    'events', v_events,
    'blocks', v_blocks,
    'publish', to_jsonb(v_publish)
  );
end;
$function$;

COMMENT ON FUNCTION "public"."sweep_spend_rules"(timestamp with time zone, integer, boolean) IS 'Evaluates spend rules for dirty workspaces (claimed with SKIP LOCKED), workspaces whose rule periods rolled over or whose blocks reached their reset, an hourly slice of all workspaces with enabled rules, and a 15-minute slice of workspaces with balance rules. Queues alerts, lifts blocks and, with p_blocks, starts them. Called every 5 minutes by the API scheduled job when SPEND_RULES_ENABLED is true (p_blocks = SPEND_RULE_BLOCKS_ENABLED).';

GRANT EXECUTE ON FUNCTION "public"."sweep_spend_rules"(timestamp with time zone, integer, boolean) TO "service_role";

REVOKE ALL ON FUNCTION "public"."sweep_spend_rules"(timestamp with time zone, integer, boolean) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/sync_legacy_preset_writes_to_draft.sql
CREATE OR REPLACE FUNCTION public.sync_legacy_preset_writes_to_draft()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
begin
  if new.name is distinct from old.name and old.draft_name is not distinct from old.name then new.draft_name := new.name; end if;
  if new.slug is distinct from old.slug and old.draft_slug is not distinct from old.slug then new.draft_slug := new.slug; end if;
  if new.description is distinct from old.description and old.draft_description is not distinct from old.description then new.draft_description := new.description; end if;
  if new.config is distinct from old.config and old.draft_config is not distinct from old.config then new.draft_config := new.config; end if;
  if new.visibility is distinct from old.visibility and old.draft_visibility is not distinct from old.visibility then new.draft_visibility := new.visibility; end if;
  return new;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."sync_legacy_preset_writes_to_draft"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."sync_legacy_preset_writes_to_draft"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/sync_scim_user_workspace_access.sql
CREATE OR REPLACE FUNCTION public.sync_scim_user_workspace_access()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  perform public.reconcile_scim_entitlements(new.workspace_id);
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."sync_scim_user_workspace_access"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."sync_scim_user_workspace_access"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/sync_v2_lab_colour.sql
CREATE OR REPLACE FUNCTION public.sync_v2_lab_colour()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
begin
  new.colour := nullif(new.metadata->>'colour', '');
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."sync_v2_lab_colour"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/sync_v2_public_effective_pricing_daily.sql
CREATE OR REPLACE FUNCTION public.sync_v2_public_effective_pricing_daily()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  source_line public.v2_request_pricing_lines%rowtype;
  direction integer;
  target_model text;
  target_date date;
  target_provider text;
  target_plan text;
  is_input boolean;
  is_output boolean;
  is_cached_read boolean;
  is_cached_write boolean;
begin
  if tg_op = 'DELETE' then
    source_line := old;
    direction := -1;
  else
    source_line := new;
    direction := 1;
  end if;

  select
    coalesce(fact.routed_model_slug, fact.requested_model_slug),
    fact.occurred_at::date,
    route.provider_slug,
    public.resolve_v2_effective_pricing_plan(fact.service_tier_slug, sku.service_tier_slug)
  into target_model, target_date, target_provider, target_plan
  from public.reporting_request_facts fact
  join public.v2_model_provider_routes route on route.provider_model_id = fact.provider_model_id
  left join public.v2_pricing_skus sku on sku.sku_id = source_line.sku_id
  where fact.request_event_id = source_line.request_event_id;

  if target_model is null or target_provider is null then return source_line; end if;

  is_cached_read := source_line.meter_key in (
    'cached_read_tokens', 'cached_read_text_tokens', 'implicit_cached_input_text_tokens'
  );
  is_cached_write := source_line.meter_key in (
    'cached_write_tokens', 'cached_write_text_tokens',
    'cached_write_text_tokens_5m', 'cached_write_text_tokens_1h'
  );
  is_input := source_line.meter_key in ('input_tokens', 'input_text_tokens') or is_cached_read or is_cached_write;
  is_output := source_line.meter_key in ('output_tokens', 'output_text_tokens');

  if direction = -1 then
    update public.v2_public_effective_pricing_daily set
      input_tokens = greatest(0, input_tokens - case when is_input then source_line.quantity else 0 end),
      output_tokens = greatest(0, output_tokens - case when is_output then source_line.quantity else 0 end),
      cached_read_tokens = greatest(0, cached_read_tokens - case when is_cached_read then source_line.quantity else 0 end),
      cached_write_tokens = greatest(0, cached_write_tokens - case when is_cached_write then source_line.quantity else 0 end),
      input_cost_nanos = greatest(0, input_cost_nanos - case when is_input then source_line.charged_nanos else 0 end),
      output_cost_nanos = greatest(0, output_cost_nanos - case when is_output then source_line.charged_nanos else 0 end),
      total_cost_nanos = greatest(0, total_cost_nanos - source_line.charged_nanos),
      updated_at = now()
    where model_slug = target_model
      and usage_date = target_date
      and provider_id = target_provider
      and pricing_plan = target_plan;
    return source_line;
  end if;

  insert into public.v2_public_effective_pricing_daily (
    model_slug, usage_date, provider_id, pricing_plan,
    input_tokens, output_tokens, cached_read_tokens, cached_write_tokens,
    input_cost_nanos, output_cost_nanos, total_cost_nanos
  ) values (
    target_model, target_date, target_provider, target_plan,
    case when is_input then source_line.quantity else 0 end,
    case when is_output then source_line.quantity else 0 end,
    case when is_cached_read then source_line.quantity else 0 end,
    case when is_cached_write then source_line.quantity else 0 end,
    case when is_input then source_line.charged_nanos else 0 end,
    case when is_output then source_line.charged_nanos else 0 end,
    source_line.charged_nanos
  )
  on conflict (model_slug, usage_date, provider_id, pricing_plan) do update set
    input_tokens = greatest(0, public.v2_public_effective_pricing_daily.input_tokens + excluded.input_tokens),
    output_tokens = greatest(0, public.v2_public_effective_pricing_daily.output_tokens + excluded.output_tokens),
    cached_read_tokens = greatest(0, public.v2_public_effective_pricing_daily.cached_read_tokens + excluded.cached_read_tokens),
    cached_write_tokens = greatest(0, public.v2_public_effective_pricing_daily.cached_write_tokens + excluded.cached_write_tokens),
    input_cost_nanos = greatest(0, public.v2_public_effective_pricing_daily.input_cost_nanos + excluded.input_cost_nanos),
    output_cost_nanos = greatest(0, public.v2_public_effective_pricing_daily.output_cost_nanos + excluded.output_cost_nanos),
    total_cost_nanos = greatest(0, public.v2_public_effective_pricing_daily.total_cost_nanos + excluded.total_cost_nanos),
    updated_at = now();

  return source_line;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."sync_v2_public_effective_pricing_daily"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/sync_v2_public_effective_pricing_fact_update.sql
CREATE OR REPLACE FUNCTION public.sync_v2_public_effective_pricing_fact_update()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  source_fact public.v2_request_facts%rowtype;
  old_service_tier text;
  new_service_tier text;
  old_plan text;
  new_plan text;
  source_service_tier text;
  target_model text;
  target_date date;
  target_provider text;
  totals record;
begin
  old_service_tier := coalesce(
    public.normalize_v2_service_tier(old.service_tier_slug),
    public.normalize_v2_service_tier(old.safe_metadata->>'service_tier'),
    public.normalize_v2_service_tier(old.safe_metadata->>'service_tier_observed'),
    public.normalize_v2_service_tier(old.safe_metadata->>'service_tier_requested'),
    case when old.endpoint = 'batch' then 'batch' else null end
  );
  new_service_tier := case
    when new.service_tier_slug is distinct from old.service_tier_slug then coalesce(
      public.normalize_v2_service_tier(new.service_tier_slug),
      public.normalize_v2_service_tier(new.safe_metadata->>'service_tier'),
      public.normalize_v2_service_tier(new.safe_metadata->>'service_tier_observed'),
      public.normalize_v2_service_tier(new.safe_metadata->>'service_tier_requested'),
      old_service_tier
    )
    else coalesce(
      public.normalize_v2_service_tier(new.safe_metadata->>'service_tier'),
      public.normalize_v2_service_tier(new.safe_metadata->>'service_tier_observed'),
      public.normalize_v2_service_tier(new.safe_metadata->>'service_tier_requested'),
      public.normalize_v2_service_tier(new.service_tier_slug),
      case when new.endpoint = 'batch' then 'batch' else old_service_tier end
    )
  end;
  old_plan := public.resolve_v2_effective_pricing_plan(old_service_tier, null);
  new_plan := public.resolve_v2_effective_pricing_plan(new_service_tier, null);

  if tg_when = 'BEFORE' then
    new.service_tier_requested := coalesce(
      public.normalize_v2_service_tier(new.safe_metadata->>'service_tier_requested'),
      public.normalize_v2_service_tier(new.service_tier_requested)
    );
    new.service_tier_observed := coalesce(
      public.normalize_v2_service_tier(new.safe_metadata->>'service_tier_observed'),
      public.normalize_v2_service_tier(new.service_tier_observed)
    );
    new.service_tier_slug := new_service_tier;
  end if;

  if (old.provider_model_id, old.routed_model_slug, old.requested_model_slug, old.occurred_at, old_plan)
    is not distinct from
    (new.provider_model_id, new.routed_model_slug, new.requested_model_slug, new.occurred_at, new_plan)
  then
    return new;
  end if;

  if tg_when = 'BEFORE' then
    source_fact := old;
    source_service_tier := old_service_tier;
  else
    source_fact := new;
    source_service_tier := new_service_tier;
  end if;
  if not source_fact.public_reporting_allowed then return new; end if;
  target_model := coalesce(source_fact.routed_model_slug, source_fact.requested_model_slug);
  target_date := source_fact.occurred_at::date;
  select route.provider_slug into target_provider
  from public.v2_model_provider_routes route
  where route.provider_model_id = source_fact.provider_model_id;

  if target_model is null or target_provider is null then return new; end if;

  for totals in
    select
      public.resolve_v2_effective_pricing_plan(source_service_tier, sku.service_tier_slug) as pricing_plan,
      coalesce(sum(line.quantity) filter (where line.meter_key in (
        'input_tokens', 'input_text_tokens', 'cached_read_tokens', 'cached_read_text_tokens',
        'implicit_cached_input_text_tokens', 'cached_write_tokens', 'cached_write_text_tokens',
        'cached_write_text_tokens_5m', 'cached_write_text_tokens_1h'
      )), 0) as input_tokens,
      coalesce(sum(line.quantity) filter (where line.meter_key in ('output_tokens', 'output_text_tokens')), 0) as output_tokens,
      coalesce(sum(line.quantity) filter (where line.meter_key in (
        'cached_read_tokens', 'cached_read_text_tokens', 'implicit_cached_input_text_tokens'
      )), 0) as cached_read_tokens,
      coalesce(sum(line.quantity) filter (where line.meter_key in (
        'cached_write_tokens', 'cached_write_text_tokens', 'cached_write_text_tokens_5m', 'cached_write_text_tokens_1h'
      )), 0) as cached_write_tokens,
      coalesce(sum(line.charged_nanos) filter (where line.meter_key in (
        'input_tokens', 'input_text_tokens', 'cached_read_tokens', 'cached_read_text_tokens',
        'implicit_cached_input_text_tokens', 'cached_write_tokens', 'cached_write_text_tokens',
        'cached_write_text_tokens_5m', 'cached_write_text_tokens_1h'
      )), 0) as input_cost_nanos,
      coalesce(sum(line.charged_nanos) filter (where line.meter_key in ('output_tokens', 'output_text_tokens')), 0) as output_cost_nanos,
      coalesce(sum(line.charged_nanos), 0) as total_cost_nanos
    from public.v2_request_pricing_lines line
    left join public.v2_pricing_skus sku on sku.sku_id = line.sku_id
    where line.request_event_id = source_fact.request_event_id
    group by public.resolve_v2_effective_pricing_plan(source_service_tier, sku.service_tier_slug)
  loop
    if tg_when = 'BEFORE' then
      update public.v2_public_effective_pricing_daily set
        input_tokens = greatest(0, input_tokens - totals.input_tokens),
        output_tokens = greatest(0, output_tokens - totals.output_tokens),
        cached_read_tokens = greatest(0, cached_read_tokens - totals.cached_read_tokens),
        cached_write_tokens = greatest(0, cached_write_tokens - totals.cached_write_tokens),
        input_cost_nanos = greatest(0, input_cost_nanos - totals.input_cost_nanos),
        output_cost_nanos = greatest(0, output_cost_nanos - totals.output_cost_nanos),
        total_cost_nanos = greatest(0, total_cost_nanos - totals.total_cost_nanos),
        updated_at = now()
      where model_slug = target_model and usage_date = target_date
        and provider_id = target_provider and pricing_plan = totals.pricing_plan;
    else
      insert into public.v2_public_effective_pricing_daily (
        model_slug, usage_date, provider_id, pricing_plan, input_tokens, output_tokens,
        cached_read_tokens, cached_write_tokens, input_cost_nanos, output_cost_nanos, total_cost_nanos
      ) values (
        target_model, target_date, target_provider, totals.pricing_plan, totals.input_tokens,
        totals.output_tokens, totals.cached_read_tokens, totals.cached_write_tokens,
        totals.input_cost_nanos, totals.output_cost_nanos, totals.total_cost_nanos
      ) on conflict (model_slug, usage_date, provider_id, pricing_plan) do update set
        input_tokens = public.v2_public_effective_pricing_daily.input_tokens + excluded.input_tokens,
        output_tokens = public.v2_public_effective_pricing_daily.output_tokens + excluded.output_tokens,
        cached_read_tokens = public.v2_public_effective_pricing_daily.cached_read_tokens + excluded.cached_read_tokens,
        cached_write_tokens = public.v2_public_effective_pricing_daily.cached_write_tokens + excluded.cached_write_tokens,
        input_cost_nanos = public.v2_public_effective_pricing_daily.input_cost_nanos + excluded.input_cost_nanos,
        output_cost_nanos = public.v2_public_effective_pricing_daily.output_cost_nanos + excluded.output_cost_nanos,
        total_cost_nanos = public.v2_public_effective_pricing_daily.total_cost_nanos + excluded.total_cost_nanos,
        updated_at = now();
    end if;
  end loop;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."sync_v2_public_effective_pricing_fact_update"() FROM PUBLIC, "anon", "authenticated", "service_role";

-- source: supabase/schemas/public/functions/sync_v2_request_edge_geography.sql
CREATE OR REPLACE FUNCTION public.sync_v2_request_edge_geography()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  new.edge_country := case
    when nullif(new.safe_metadata->>'edge_country', '') ~ '^[A-Za-z]{2}$'
      then upper(new.safe_metadata->>'edge_country')
    else null
  end;
  new.edge_continent := case
    when nullif(new.safe_metadata->>'edge_continent', '') ~ '^[A-Za-z]{2}$'
      then upper(new.safe_metadata->>'edge_continent')
    else null
  end;
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."sync_v2_request_edge_geography"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."sync_v2_request_edge_geography"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/sync_v2_request_fact_provider_model_id.sql
CREATE OR REPLACE FUNCTION public.sync_v2_request_fact_provider_model_id()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if new.provider_model_id is not null then
    update public.v2_request_facts request
    set provider_model_id = new.provider_model_id,
        routed_model_slug = route.model_slug,
        requested_model_slug = case
          when lower(request.requested_model_input) like '%:free' then route.model_slug
          else request.requested_model_slug
        end
    from public.v2_model_provider_routes route
    where route.provider_model_id = new.provider_model_id
      and request.request_event_id = new.request_event_id
      and (
        request.provider_model_id is distinct from new.provider_model_id
        or request.routed_model_slug is distinct from route.model_slug
        or (
          lower(request.requested_model_input) like '%:free'
          and request.requested_model_slug is distinct from route.model_slug
        )
      );
  end if;
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."sync_v2_request_fact_provider_model_id"() TO "service_role";

REVOKE ALL ON FUNCTION "public"."sync_v2_request_fact_provider_model_id"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/sync_workspace_addon_subscription.sql
CREATE OR REPLACE FUNCTION public.sync_workspace_addon_subscription (
  p_workspace_id               uuid,
  p_addon_key                  text,
  p_provider_customer_id       text,
  p_provider_subscription_id   text,
  p_provider_price_id          text,
  p_quote_id                   uuid,
  p_plan_key                   text,
  p_pricing_version            text,
  p_included_members           integer,
  p_fee_policy                 text,
  p_included_card_top_up_nanos bigint,
  p_status                     text,
  p_current_period_start       timestamp with time zone,
  p_current_period_end         timestamp with time zone,
  p_cancel_at_period_end       boolean,
  p_grace_until                timestamp with time zone,
  p_provider_event_created     bigint,
  p_metadata                   jsonb                    DEFAULT '{}'::jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  insert into public.workspace_addon_subscriptions (
    workspace_id, addon_key, provider, provider_customer_id,
    provider_subscription_id, provider_price_id, quote_id, plan_key,
    pricing_version, included_members, fee_policy,
    included_card_top_up_nanos, status, current_period_start,
    current_period_end, cancel_at_period_end, grace_until,
    last_provider_event_created, metadata, updated_at
  ) values (
    p_workspace_id, p_addon_key, 'stripe', p_provider_customer_id,
    p_provider_subscription_id, p_provider_price_id, p_quote_id, p_plan_key,
    p_pricing_version, p_included_members, p_fee_policy,
    coalesce(p_included_card_top_up_nanos, 0), p_status, p_current_period_start,
    p_current_period_end, coalesce(p_cancel_at_period_end, false), p_grace_until,
    coalesce(p_provider_event_created, 0), coalesce(p_metadata, '{}'::jsonb), now()
  )
  on conflict (workspace_id, addon_key) do update set
    provider = 'stripe',
    provider_customer_id = excluded.provider_customer_id,
    provider_subscription_id = excluded.provider_subscription_id,
    provider_price_id = excluded.provider_price_id,
    quote_id = excluded.quote_id,
    plan_key = excluded.plan_key,
    pricing_version = excluded.pricing_version,
    included_members = excluded.included_members,
    fee_policy = excluded.fee_policy,
    included_card_top_up_nanos = excluded.included_card_top_up_nanos,
    status = excluded.status,
    current_period_start = excluded.current_period_start,
    current_period_end = excluded.current_period_end,
    cancel_at_period_end = excluded.cancel_at_period_end,
    grace_until = case
      when public.workspace_addon_subscriptions.status = 'past_due'
        and excluded.status = 'past_due'
      then public.workspace_addon_subscriptions.grace_until
      else excluded.grace_until
    end,
    last_provider_event_created = excluded.last_provider_event_created,
    metadata = public.workspace_addon_subscriptions.metadata || excluded.metadata,
    updated_at = now()
  where public.workspace_addon_subscriptions.last_provider_event_created <= excluded.last_provider_event_created;
end;
$function$;

GRANT EXECUTE
  ON FUNCTION "public"."sync_workspace_addon_subscription"(uuid, text, text, text, text, uuid, text, text, integer, text, bigint, text, timestamp WITH time zone, timestamp
    WITH time zone, boolean, timestamp WITH time zone, bigint, jsonb)
  TO "service_role";

REVOKE ALL
  ON FUNCTION "public"."sync_workspace_addon_subscription"(uuid, text, text, text, text, uuid, text, text, integer, text, bigint, text, timestamp WITH time zone, timestamp
    WITH time zone, boolean, timestamp WITH time zone, bigint, jsonb)
  FROM PUBLIC, "anon", "authenticated";

