-- source: supabase/schemas/public/functions/validate_workspace_billing_time_zone.sql
CREATE OR REPLACE FUNCTION public.validate_workspace_billing_time_zone()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  new.billing_time_zone := pg_catalog.btrim(new.billing_time_zone);
  -- The default needs no lookup; every other value must be a zone the server knows.
  if new.billing_time_zone is distinct from 'UTC'
    and not private.is_valid_time_zone(new.billing_time_zone) then
    raise exception 'invalid_time_zone'
      using errcode = '22023',
        detail = pg_catalog.format('%s is not an IANA time zone.', new.billing_time_zone);
  end if;
  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."validate_workspace_billing_time_zone"() TO "service_role";

COMMENT ON FUNCTION "public"."validate_workspace_billing_time_zone"() IS 'Rejects a workspace_settings.billing_time_zone that is not an IANA time zone (private.is_valid_time_zone). Definer rights let admins writing through RLS use the private helper.';

REVOKE ALL ON FUNCTION "public"."validate_workspace_billing_time_zone"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/validate_workspace_spend_rule.sql
CREATE OR REPLACE FUNCTION public.validate_workspace_spend_rule()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if tg_op = 'UPDATE' and new.workspace_id is distinct from old.workspace_id then
    raise exception 'spend_rule_workspace_immutable'
      using errcode = '22023',
        detail = 'A spend rule cannot move to another workspace.';
  end if;

  new.name := pg_catalog.btrim(new.name);
  new.scope_id := nullif(pg_catalog.btrim(new.scope_id), '');

  -- Key, member and department scopes hold a uuid. Checked here, before the generated
  -- scope_*_id columns cast it, so the error names the field.
  if new.scope_type in ('key', 'member', 'department') then
    if new.scope_id is null
      or new.scope_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'invalid_spend_rule_scope_id'
        using errcode = '22023',
          detail = pg_catalog.format('A %s scope needs the %s id.', new.scope_type, new.scope_type);
    end if;
    new.scope_id := pg_catalog.lower(new.scope_id);
  end if;

  if new.time_zone is not null then
    new.time_zone := nullif(pg_catalog.btrim(new.time_zone), '');
    if new.time_zone is not null and not private.is_valid_time_zone(new.time_zone) then
      raise exception 'invalid_time_zone'
        using errcode = '22023',
          detail = pg_catalog.format('%s is not an IANA time zone.', new.time_zone);
    end if;
  end if;

  -- Thresholds are stored sorted and distinct; the CHECK constraints then bound them.
  if new.threshold_percents is not null then
    new.threshold_percents := array(
      select distinct threshold
      from pg_catalog.unnest(new.threshold_percents) as threshold
      order by threshold
    );
    if pg_catalog.cardinality(new.threshold_percents) = 0 then
      new.threshold_percents := null;
    end if;
  end if;

  return new;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."validate_workspace_spend_rule"() TO "service_role";

COMMENT ON FUNCTION "public"."validate_workspace_spend_rule"() IS 'Normalizes and validates a spend rule before the CHECK constraints run: keeps the workspace fixed, trims names, requires uuid ids for key, member and department scopes, validates the IANA time zone, and sorts and dedupes threshold_percents.';

REVOKE ALL ON FUNCTION "public"."validate_workspace_spend_rule"() FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/wallet_apply_delta.sql
CREATE OR REPLACE FUNCTION public.wallet_apply_delta (
  p_workspace_id uuid,
  p_delta_nanos  bigint
)
  RETURNS TABLE (
    before_balance_nanos bigint,
    after_balance_nanos  bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
    v_before bigint;
    v_after bigint;
begin
    if p_workspace_id is null then
        raise exception 'missing_workspace_id';
    end if;

    update public.wallets
    set balance_nanos = balance_nanos + p_delta_nanos,
        updated_at = now()
    where workspace_id = p_workspace_id
    returning balance_nanos - p_delta_nanos, balance_nanos
    into v_before, v_after;

    if not found then
        raise exception 'wallet_not_found';
    end if;

    return query select v_before, v_after;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."wallet_apply_delta"(uuid, bigint) TO "service_role";

REVOKE ALL ON FUNCTION "public"."wallet_apply_delta"(uuid, bigint) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/workspace_department_budget_status.sql
CREATE OR REPLACE FUNCTION public.workspace_department_budget_status (
  p_workspace_id uuid,
  p_now          timestamp with time zone DEFAULT now()
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Each department budget in the workspace with its spend so far in the current UTC period, as
-- a JSON array ordered by department and period. A department's spend is the cost of the API
-- keys private.department_budget_key_departments gives it: keys linked to it, plus, for keys not
-- linked to any department, the keys its members created and their OAuth requests. Spend comes from v2_private_usage_15m, which is rebuilt hourly and so lags, plus
-- async jobs and realtime sessions from gateway_requests, which the rollup leaves out.
declare
  v_result jsonb;
begin
  if p_workspace_id is null or p_now is null then
    raise exception 'invalid_department_budget_status_arguments';
  end if;

  with budgets as (
    select b.*, p.period_start, p.reset_at
    from public.workspace_department_budgets b
    cross join lateral private.spend_limit_period(b.interval, p_now) p
    where b.workspace_id = p_workspace_id
  ),
  key_departments as (
    select kd.key_id, kd.department_id
    from private.department_budget_key_departments(p_workspace_id) kd
  ),
  spend as (
    select u.key_id, u.bucket_start as at, u.cost_nanos
    from public.v2_private_usage_15m u
    where u.workspace_id = p_workspace_id
      and u.bucket_start >= (select min(b.period_start) from budgets b)
      and u.bucket_start <= p_now
      and u.key_id in (select kd.key_id from key_departments kd)
    union all
    select r.key_id, r.created_at, coalesce(r.cost_nanos, 0)
    from public.gateway_requests r
    where r.success is true
      and r.endpoint = any (array['video.generation', 'batch', 'music.generate', 'audio.realtime'])
      and r.workspace_id = p_workspace_id
      and r.created_at >= (select min(b.period_start) from budgets b)
      and r.created_at <= p_now
      and r.key_id in (select kd.key_id from key_departments kd)
  ),
  usage as (
    select b.id, coalesce(sum(s.cost_nanos), 0)::numeric as used_nanos
    from budgets b
    left join key_departments kd on kd.department_id = b.department_id
    left join spend s on s.key_id = kd.key_id and s.at >= b.period_start
    group by b.id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', b.id,
    'workspace_id', b.workspace_id,
    'department_id', b.department_id,
    'department_name', d.name,
    'interval', b.interval,
    'limit_nanos', b.limit_nanos,
    'usage_nanos', u.used_nanos,
    'remaining_nanos', greatest(b.limit_nanos - u.used_nanos, 0),
    'exceeded', u.used_nanos >= b.limit_nanos,
    'window_start', b.period_start,
    'reset_at', b.reset_at,
    'created_by', b.created_by,
    'created_at', b.created_at,
    'updated_at', b.updated_at
  ) order by d.name, b.department_id, case b.interval when 'daily' then 1 when 'weekly' then 2 else 3 end), '[]'::jsonb)
  into v_result
  from budgets b
  join usage u on u.id = b.id
  join public.workspace_departments d on d.id = b.department_id;

  return v_result;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."workspace_department_budget_status"(uuid, timestamp with time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."workspace_department_budget_status"(uuid, timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/workspace_key_security_summary.sql
CREATE OR REPLACE FUNCTION public.workspace_key_security_summary (
  p_workspace_id uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- Counts for the Security page overview, and live keys per storage location.
  -- Service-only: callers verify workspace access first.
  with keys as (
    select * from public.workspace_key_security(p_workspace_id)
  )
  select jsonb_build_object(
    'total', count(*),
    'paused', count(*) filter (where keys.status = 'paused'),
    'no_spend_limit', count(*) filter (where not keys.has_spend_limit),
    'never_expires', count(*) filter (where keys.expires_at is null),
    'idle', count(*) filter (where keys.idle),
    'safe_to_remove', count(*) filter (where keys.safe_to_remove),
    'no_ip_allowlist', count(*) filter (where not keys.has_ip_allowlist),
    'no_storage_location', count(*) filter (where cardinality(keys.storage_locations) = 0),
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object('id', location.id, 'keys', location.keys) order by location.keys desc, location.id)
      from (
        select stored.id, count(*) as keys
        from keys, unnest(keys.storage_locations) as stored(id)
        group by stored.id
      ) as location
    ), '[]'::jsonb)
  )
  from keys;
$function$;

COMMENT ON FUNCTION "public"."workspace_key_security_summary"(uuid) IS 'Security page overview counts for a workspace''s live API keys, with live keys per storage location. Service-only; callers verify workspace access.';

GRANT EXECUTE ON FUNCTION "public"."workspace_key_security_summary"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."workspace_key_security_summary"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/workspace_key_security.sql
CREATE OR REPLACE FUNCTION public.workspace_key_security (
  p_workspace_id uuid
)
  RETURNS TABLE (
    id                uuid,
    name              text,
    prefix            text,
    status            text,
    created_by        uuid,
    owner_name        text,
    owner_email       text,
    created_at        timestamp with time zone,
    last_used_at      timestamp with time zone,
    expires_at        timestamp with time zone,
    storage_locations text[],
    has_spend_limit   boolean,
    has_ip_allowlist  boolean,
    never_used        boolean,
    idle              boolean,
    safe_to_remove    boolean,
    risk              integer
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- The workspace's live dashboard keys (active or paused, not expired), with
  -- the risks the Security page reports. Phaseo's own managed keys (Chat, the
  -- Slack agent) and OAuth-delegated keys are left out: the workspace does not
  -- store them. Service-only: callers verify workspace access first.
  with live as (
    select
      key.*,
      -- last_used_at defaults to the creation time, so a key used only at
      -- creation was never used for a request.
      (key.last_used_at is null or key.last_used_at <= key.created_at + interval '1 minute') as never_used,
      coalesce(key.last_used_at, key.created_at) as last_activity
    from public.keys as key
    where key.workspace_id = p_workspace_id
      and key.key_kind = 'standard'
      and key.status in ('active', 'paused')
      and (key.expires_at is null or key.expires_at > now())
      and key.name not in ('__chat_route_managed_key__', '__slack_agent_managed_key__')
  ), flagged as (
    select
      live.*,
      (live.daily_limit_cost_nanos > 0 or live.weekly_limit_cost_nanos > 0 or live.monthly_limit_cost_nanos > 0) as has_spend_limit,
      (jsonb_array_length(live.ip_allowlist) > 0) as has_ip_allowlist,
      -- No request in 90 days; a new key gets 90 days before it counts as idle.
      (live.last_activity < now() - interval '90 days') as idle,
      -- Idle and never used, or idle for 180 days.
      (live.last_activity < now() - interval '90 days' and (live.never_used or live.last_activity < now() - interval '180 days')) as safe_to_remove
    from live
  )
  select
    flagged.id,
    flagged.name,
    flagged.prefix,
    flagged.status,
    flagged.created_by,
    nullif(btrim(profile.display_name), ''),
    account.email::text,
    flagged.created_at,
    case when flagged.never_used then null else flagged.last_used_at end,
    flagged.expires_at,
    flagged.storage_locations,
    flagged.has_spend_limit,
    flagged.has_ip_allowlist,
    flagged.never_used,
    flagged.idle,
    flagged.safe_to_remove,
    ((not flagged.has_spend_limit)::integer
      + (flagged.expires_at is null)::integer
      + flagged.idle::integer
      + flagged.safe_to_remove::integer
      + (not flagged.has_ip_allowlist)::integer
      + (cardinality(flagged.storage_locations) = 0)::integer) as risk
  from flagged
  left join public.users as profile on profile.user_id = flagged.created_by
  left join auth.users as account on account.id = flagged.created_by
  order by risk desc, flagged.created_at;
$function$;

COMMENT ON FUNCTION "public"."workspace_key_security"(uuid) IS 'A workspace''s live dashboard API keys with the risks the Security page reports (no spend limit, no expiry, idle, safe to remove, no IP allowlist, no storage location). Service-only; callers verify workspace access.';

GRANT EXECUTE ON FUNCTION "public"."workspace_key_security"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."workspace_key_security"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/workspace_key_storage_incidents.sql
CREATE OR REPLACE FUNCTION public.workspace_key_storage_incidents (
  p_workspace_id uuid
)
  RETURNS TABLE (
    id               uuid,
    location_id      text,
    action           text,
    title            text,
    customer_message text,
    source_url       text,
    applied_at       timestamp with time zone,
    keys             bigint,
    key_ids          uuid[]
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  -- Incidents from the last 90 days that changed this workspace's keys, newest
  -- first, for the notice on the API keys and Key security pages. Service-only:
  -- callers verify workspace access first.
  select incident.id, incident.location_id, incident.action, incident.title, incident.customer_message,
    incident.source_url, incident.applied_at, count(*), array_agg(changed.key_id order by changed.key_id)
  from public.key_storage_incident_keys as changed
  join public.key_storage_incidents as incident on incident.id = changed.incident_id
  where changed.workspace_id = p_workspace_id
    and incident.applied_at > now() - interval '90 days'
  group by incident.id
  order by incident.applied_at desc;
$function$;

COMMENT ON FUNCTION "public"."workspace_key_storage_incidents"(uuid) IS 'Key storage incidents from the last 90 days that revoked or paused this workspace''s keys. Service-only.';

GRANT EXECUTE ON FUNCTION "public"."workspace_key_storage_incidents"(uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."workspace_key_storage_incidents"(uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/workspace_rate_limit_throttle_summary.sql
CREATE OR REPLACE FUNCTION public.workspace_rate_limit_throttle_summary (
  p_workspace_id uuid,
  p_since        timestamp with time zone DEFAULT (now() - '24:00:00'::interval)
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
-- Requests each rate limit policy rejected in the workspace since p_since, for Settings → Rate
-- limits: a JSON array of {policy_id, throttled_requests, last_throttled_at}, most throttled
-- first. It reads the per-minute rollup through its (workspace_id, bucket_start, ...) unique
-- index, so a day is at most 1,440 buckets per policy, scope and key.
  select coalesce(jsonb_agg(jsonb_build_object(
      'policy_id', summary.policy_id,
      'throttled_requests', summary.throttled_requests,
      'last_throttled_at', summary.last_throttled_at
    ) order by summary.throttled_requests desc, summary.policy_id), '[]'::jsonb)
  from (
    select throttles.policy_id,
           sum(throttles.throttled_requests)::bigint as throttled_requests,
           max(throttles.bucket_start) as last_throttled_at
    from public.workspace_rate_limit_throttles_minute throttles
    where throttles.workspace_id = p_workspace_id
      and throttles.bucket_start >= p_since
    group by throttles.policy_id
  ) summary;
$function$;

GRANT EXECUTE ON FUNCTION "public"."workspace_rate_limit_throttle_summary"(uuid, timestamp with time zone) TO "service_role";

REVOKE ALL ON FUNCTION "public"."workspace_rate_limit_throttle_summary"(uuid, timestamp with time zone) FROM PUBLIC, "anon", "authenticated";

