CREATE TABLE "public"."catalogue_notification_events" (
  "id"                      uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "kind"                    text                     NOT NULL,
  "dedupe_key"              text                     NOT NULL,
  "model_slug"              text,
  "lab_slug"                text,
  "provider_slug"           text,
  "title"                   text                     NOT NULL,
