    (client_source_name = 'Phaseo TypeScript SDK'::text) AND (client_source_kind = 'sdk'::text)) OR
    ((client_source_id = 'phaseo-python'::text) AND (client_source_name = 'Phaseo Python SDK'::text) AND (client_source_kind = 'sdk'::text)) OR
