  "weekly_limit_cost_nanos"  bigint                   NOT NULL DEFAULT 0,
  "monthly_limit_cost_nanos" bigint                   NOT NULL DEFAULT 0,
  CONSTRAINT "management_keys_pkey" PRIMARY KEY (id),
  CONSTRAINT "provisioning_keys_hash_key" UNIQUE (hash)
);

