-- source: supabase/schemas/public/tables/v2_model_provider_routes.sql
CREATE TABLE "public"."v2_model_provider_routes" (
  "provider_model_id"            text                     NOT NULL,
  "model_slug"                   text                     NOT NULL,
  "provider_slug"                text                     NOT NULL,
  "provider_model_slug"          text,
  "status"                       text                     NOT NULL DEFAULT 'active'::text,
  "routing_enabled"              boolean                  NOT NULL DEFAULT false,
  "input_modalities"             text[]                   NOT NULL DEFAULT '{}'::text[],
  "output_modalities"            text[]                   NOT NULL DEFAULT '{}'::text[],
  "regions"                      text[]                   NOT NULL DEFAULT '{}'::text[],
  "context_length"               integer,
  "max_output_tokens"            integer,
  "effective_from"               timestamp with time zone,
  "effective_to"                 timestamp with time zone,
  "metadata"                     jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "created_at"                   timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"                   timestamp with time zone NOT NULL DEFAULT now(),
  "provider_availability_status" text                     NOT NULL DEFAULT 'unknown'::text,
  "phaseo_status"                text                     NOT NULL DEFAULT 'disabled'::text,
  "access_scope"                 text                     NOT NULL DEFAULT 'public'::text,
  "is_stealth"                   boolean                  NOT NULL DEFAULT false,
  "credential_mode"              text                     NOT NULL DEFAULT 'managed_and_byok'::text,
  CONSTRAINT "v2_model_provider_routes_access_scope_check" CHECK ((access_scope = ANY (ARRAY['public'::text, 'internal'::text]))),
  CONSTRAINT "v2_model_provider_routes_context_check" CHECK (((context_length IS NULL) OR (context_length > 0))),
  CONSTRAINT "v2_model_provider_routes_credential_mode_check" CHECK ((credential_mode = ANY (ARRAY['managed_and_byok'::text, 'byok_only'::text]))),
  CONSTRAINT "v2_model_provider_routes_internal_scope_check" CHECK (((access_scope = 'public'::text) OR (phaseo_status = ANY (ARRAY['testing'::text, 'enabled'::text])))),
  CONSTRAINT "v2_model_provider_routes_output_check" CHECK (((max_output_tokens IS NULL) OR (max_output_tokens > 0))),
  CONSTRAINT "v2_model_provider_routes_phaseo_routing_check" CHECK (((NOT routing_enabled) OR (phaseo_status = 'enabled'::text))),
  CONSTRAINT "v2_model_provider_routes_phaseo_status_check"
    CHECK ((phaseo_status = ANY (ARRAY['unsupported'::text, 'planned'::text, 'implementing'::text, 'testing'::text, 'enabled'::text, 'disabled'::text, 'blocked'::text]))),
  CONSTRAINT "v2_model_provider_routes_pkey" PRIMARY KEY (provider_model_id),
  CONSTRAINT "v2_model_provider_routes_provider_availability_check"
    CHECK
    ((provider_availability_status = ANY (ARRAY['unknown'::text, 'coming_soon'::text, 'preview'::text, 'available'::text, 'limited_access'::text, 'deprecated'::text,
    'removed'::text]))),
  CONSTRAINT "v2_model_provider_routes_provider_model_key" UNIQUE (provider_slug, provider_model_id),
  CONSTRAINT "v2_model_provider_routes_provider_model_slug_check" CHECK (((provider_model_slug IS NOT NULL) OR ((status = 'disabled'::text) AND (routing_enabled = false)))),
  CONSTRAINT "v2_model_provider_routes_provider_routing_check"
    CHECK (((NOT routing_enabled) OR (provider_availability_status = ANY (ARRAY['available'::text, 'preview'::text, 'limited_access'::text, 'deprecated'::text])))),
  CONSTRAINT "v2_model_provider_routes_public_routing_check" CHECK (((NOT routing_enabled) OR (access_scope = 'public'::text))),
  CONSTRAINT "v2_model_provider_routes_status_check" CHECK ((status = ANY (ARRAY['active'::text, 'degraded'::text, 'disabled'::text, 'retired'::text]))),
  CONSTRAINT "v2_model_provider_routes_stealth_public_id_check" CHECK (((is_stealth = false) OR (provider_model_id ~~ 'stealth:%'::text))),
  CONSTRAINT "v2_model_provider_routes_window_check" CHECK (((effective_to IS NULL) OR (effective_from IS NULL) OR (effective_to > effective_from)))
);

ALTER TABLE "public"."v2_model_provider_routes"
  ENABLE ROW LEVEL SECURITY;

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."v2_model_provider_routes" TO "anon", "authenticated", "service_role";

COMMENT ON COLUMN "public"."v2_model_provider_routes"."access_scope" IS 'Route audience. Internal routes require authenticated gateway testing mode and are never publicly routing-enabled.';

COMMENT ON COLUMN "public"."v2_model_provider_routes"."credential_mode" IS 'Optional route-level override requiring a workspace BYOK credential for this model offer.';

COMMENT ON COLUMN "public"."v2_model_provider_routes"."is_stealth" IS 'Keeps the real provider target available to internal service-role routing while every public projection exposes provider identity as exactly stealth; provider_model_id remains a synthetic stealth-prefixed identity.';

COMMENT ON COLUMN "public"."v2_model_provider_routes"."phaseo_status" IS 'Phaseo integration readiness. Only enabled routes may set routing_enabled=true.';

COMMENT ON COLUMN "public"."v2_model_provider_routes"."provider_availability_status" IS 'Upstream provider offer availability; does not imply Phaseo support.';

COMMENT ON COLUMN "public"."v2_model_provider_routes"."routing_enabled" IS 'Per provider/model routing switch, evaluated together with provider and model status.';

COMMENT ON TABLE "public"."v2_model_provider_routes" IS 'Provider/model combination anchor. Pricing, capabilities, health, and request facts reference provider_model_id.';

-- source: supabase/schemas/public/tables/v2_model_successor_routing.sql
CREATE TABLE "public"."v2_model_successor_routing" (
  "model_slug"              text                     NOT NULL,
  "unserved_since"          timestamp with time zone,
  "auto_route_enabled"      boolean                  NOT NULL DEFAULT false,
  "approved_successor_slug" text,
  "approved_by"             uuid,
  "approved_at"             timestamp with time zone,
  "compatibility"           jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "notes"                   text,
  "approval_source"         text,
  "auto_approval_blocked"   boolean                  NOT NULL DEFAULT false,
  "reference_prices"        jsonb,
  "reference_price_source"  text,
  "created_at"              timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"              timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "v2_model_successor_routing_approval_check"
    CHECK (((NOT auto_route_enabled) OR ((approved_successor_slug IS NOT NULL) AND (approved_at IS NOT NULL)))),
  CONSTRAINT "v2_model_successor_routing_approval_source_check" CHECK ((approval_source = ANY (ARRAY['admin'::text, 'auto'::text]))),
  CONSTRAINT "v2_model_successor_routing_not_self_check" CHECK (((approved_successor_slug IS NULL) OR (approved_successor_slug <> model_slug))),
  CONSTRAINT "v2_model_successor_routing_reference_prices_check" CHECK (((reference_prices IS NULL) OR (jsonb_typeof(reference_prices) = 'array'::text))),
  CONSTRAINT "v2_model_successor_routing_pkey" PRIMARY KEY (model_slug)
);

ALTER TABLE "public"."v2_model_successor_routing"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."v2_model_successor_routing" FROM "service_role";

GRANT DELETE, INSERT, SELECT, UPDATE ON TABLE "public"."v2_model_successor_routing" TO "service_role";

COMMENT ON TABLE "public"."v2_model_successor_routing" IS 'Approval to route requests for a model to its replacement_model_slug once no provider serves it, plus the time it stopped being served. Approval is tied to approved_successor_slug and lapses if replacement_model_slug changes. approval_source is admin or auto (the hourly job approves replacements with no compatibility issues); auto_approval_blocked is set when an admin revokes, so the job leaves the model alone. reference_prices holds the model''s last published list prices ([{meter_key, unit_quantity, price_nanos}], source in reference_price_source) for retired models whose price rows are gone, so redirects can still compare prices.';

REVOKE ALL ON TABLE "public"."v2_model_successor_routing" FROM "anon", "authenticated";

-- source: supabase/schemas/public/tables/v2_models.sql
CREATE TABLE "public"."v2_models" (
  "model_slug"             text                     NOT NULL,
  "lab_slug"               text                     NOT NULL,
  "name"                   text                     NOT NULL,
  "description"            text,
  "status"                 text                     NOT NULL DEFAULT 'active'::text,
  "hidden"                 boolean                  NOT NULL DEFAULT false,
  "input_modalities"       text[]                   NOT NULL DEFAULT '{}'::text[],
  "output_modalities"      text[]                   NOT NULL DEFAULT '{}'::text[],
  "family_slug"            text,
  "announced_at"           timestamp with time zone,
  "released_at"            timestamp with time zone,
  "deprecated_at"          timestamp with time zone,
  "retired_at"             timestamp with time zone,
  "metadata"               jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "created_at"             timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"             timestamp with time zone NOT NULL DEFAULT now(),
  "license"                text,
  "license_url"            text,
  "previous_model_slug"    text,
  "removal_date"           timestamp with time zone,
  "replacement_model_slug" text,
  "variant_kind"           text                     NOT NULL DEFAULT 'standard'::text,
  "base_model_slug"        text,
  "catalogue_status"       text                     NOT NULL DEFAULT 'unknown'::text,
  CONSTRAINT "v2_models_catalogue_status_check"
    CHECK
    ((catalogue_status = ANY (ARRAY['unknown'::text, 'rumoured'::text, 'announced'::text, 'preview'::text, 'available'::text, 'limited_access'::text, 'deprecated'::text,
    'retired'::text, 'withheld'::text]))),
  CONSTRAINT "v2_models_lab_slug_prefix_check" CHECK (((split_part(model_slug, '/'::text, 1) = lab_slug) AND (split_part(model_slug, '/'::text, 2) <> ''::text))),
  CONSTRAINT "v2_models_pkey" PRIMARY KEY (model_slug),
  CONSTRAINT "v2_models_replacement_not_self_check" CHECK ((replacement_model_slug IS DISTINCT FROM model_slug)),
  CONSTRAINT "v2_models_slug_check" CHECK (((model_slug = lower(model_slug)) AND (model_slug ~ '^[a-z0-9][a-z0-9._:/+@-]*$'::text))),
  CONSTRAINT "v2_models_status_check" CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'deprecated'::text, 'retired'::text, 'disabled'::text]))),
  CONSTRAINT "v2_models_variant_identity_check"
    CHECK
    ((((variant_kind = 'standard'::text) AND (model_slug !~ ':free$'::text) AND (base_model_slug IS NULL)) OR ((variant_kind = 'free'::text) AND (model_slug ~ ':free$'::text) AND
    ((base_model_slug IS NULL) OR (base_model_slug <> model_slug))))),
  CONSTRAINT "v2_models_variant_kind_check" CHECK ((variant_kind = ANY (ARRAY['standard'::text, 'free'::text])))
);

ALTER TABLE "public"."v2_models"
  ENABLE ROW LEVEL SECURITY;

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."v2_models" TO "anon", "authenticated", "service_role";

COMMENT ON COLUMN "public"."v2_models"."base_model_slug" IS 'Optional related standard model. It is not required for standalone free API models.';

COMMENT ON COLUMN "public"."v2_models"."catalogue_status" IS 'Canonical model lifecycle; independent of provider offers and Phaseo routing.';

COMMENT ON COLUMN "public"."v2_models"."license_url" IS 'Authoritative URL for the model licence text or terms; nullable when not verified.';

COMMENT ON COLUMN "public"."v2_models"."replacement_model_slug" IS 'Recommended successor shown to customers when this model is deprecated or retired. Must be an existing model; chains may not loop.';

COMMENT ON COLUMN "public"."v2_models"."variant_kind" IS 'Canonical API model kind. Free models may stand alone or optionally reference a related standard model.';

COMMENT ON TABLE "public"."v2_models" IS 'Authoritative model catalogue. Repository JSON is the sole authoring source.';

