-- source: supabase/schemas/public/tables/workspace_request_classifiers.sql
CREATE TABLE "public"."workspace_request_classifiers" (
  "id"                   uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "workspace_id"         uuid                     NOT NULL,
  "name"                 text                     NOT NULL,
  "description"          text,
  "enabled"              boolean                  NOT NULL DEFAULT true,
  "model"                text                     NOT NULL,
  "instructions"         text                     NOT NULL DEFAULT '',
  "dimensions"           jsonb                    NOT NULL,
  "sample_rate_bps"      integer                  NOT NULL DEFAULT 10000,
  "sample_by"            text                     NOT NULL DEFAULT 'request',
  "input_scope"          text                     NOT NULL DEFAULT 'prompt',
  "scope"                jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "monthly_budget_nanos" bigint,
  "created_by"           uuid,
  "created_at"           timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"           timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "workspace_request_classifiers_description_check" CHECK (((description IS NULL) OR (length(description) <= 500))),
  CONSTRAINT "workspace_request_classifiers_dimensions_check" CHECK (((jsonb_typeof(dimensions) = 'array'::text) AND (jsonb_array_length(dimensions) >= 1) AND (jsonb_array_length(dimensions) <= 12))),
  CONSTRAINT "workspace_request_classifiers_id_workspace_id_key" UNIQUE (id, workspace_id),
  CONSTRAINT "workspace_request_classifiers_input_scope_check" CHECK ((input_scope = ANY (ARRAY['prompt'::text, 'prompt_and_response'::text]))),
  CONSTRAINT "workspace_request_classifiers_instructions_check" CHECK ((length(instructions) <= 8000)),
  CONSTRAINT "workspace_request_classifiers_model_check" CHECK (((length(btrim(model)) >= 1) AND (length(model) <= 200))),
  CONSTRAINT "workspace_request_classifiers_monthly_budget_nanos_check" CHECK (((monthly_budget_nanos IS NULL) OR (monthly_budget_nanos > 0))),
  CONSTRAINT "workspace_request_classifiers_name_check" CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 100))),
  CONSTRAINT "workspace_request_classifiers_pkey" PRIMARY KEY (id),
  CONSTRAINT "workspace_request_classifiers_sample_by_check" CHECK ((sample_by = ANY (ARRAY['request'::text, 'session'::text]))),
  CONSTRAINT "workspace_request_classifiers_sample_rate_bps_check" CHECK (((sample_rate_bps >= 1) AND (sample_rate_bps <= 10000))),
  CONSTRAINT "workspace_request_classifiers_scope_check" CHECK ((jsonb_typeof(scope) = 'object'::text))
);

ALTER TABLE "public"."workspace_request_classifiers"
  ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE "public"."workspace_request_classifiers" IS 'Customer-defined request classifiers. After a request finishes, the gateway asks the chosen model to place the request in each dimension (a fixed list of allowed values) and writes the answers onto the request as labels, so they filter and group like caller-sent labels. A dimension the caller already labelled is skipped. Classifier calls are billed to the workspace at the model''s normal price. At most 5 per workspace (enforce_request_classifier_limit).';

COMMENT ON COLUMN "public"."workspace_request_classifiers"."dimensions" IS 'Array of 1 to 12 dimensions: {key, name, description?, multiple, allow_other, values: [{value, description?}]}. key becomes the request label key. Shape is validated by the management API.';

COMMENT ON COLUMN "public"."workspace_request_classifiers"."sample_rate_bps" IS 'Share of eligible requests to classify, in basis points (10000 = every request).';

COMMENT ON COLUMN "public"."workspace_request_classifiers"."sample_by" IS 'request samples each request independently; session keeps every request in a session in or out together.';

COMMENT ON COLUMN "public"."workspace_request_classifiers"."input_scope" IS 'prompt classifies the request only; prompt_and_response also shows the model the generated response.';

COMMENT ON COLUMN "public"."workspace_request_classifiers"."scope" IS 'Optional filters on which requests are eligible: {key_ids?, app_ids?, models?}. An empty object means every request.';

COMMENT ON COLUMN "public"."workspace_request_classifiers"."monthly_budget_nanos" IS 'Optional cap on classifier spend per UTC calendar month, in nanodollars. Classification pauses for the rest of the month once it is reached.';

REVOKE ALL ON TABLE "public"."workspace_request_classifiers" FROM "service_role";

GRANT DELETE, INSERT, SELECT, UPDATE ON TABLE "public"."workspace_request_classifiers" TO "service_role";

REVOKE ALL ON TABLE "public"."workspace_request_classifiers" FROM "anon", "authenticated";

-- source: supabase/schemas/public/tables/workspace_settings.sql
CREATE TABLE "public"."workspace_settings" (
  "workspace_id"                                 uuid                     NOT NULL,
  "routing_mode"                                 text                     NOT NULL DEFAULT 'balanced'::text,
  "created_at"                                   timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "updated_at"                                   timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "byok_fallback_enabled"                        boolean                  NOT NULL DEFAULT true,
  "beta_channel_enabled"                         boolean                  NOT NULL DEFAULT false,
  "privacy_enable_paid_may_train"                boolean                  NOT NULL DEFAULT true,
  "privacy_enable_free_may_train"                boolean                  NOT NULL DEFAULT true,
  "privacy_enable_free_may_publish_prompts"      boolean                  NOT NULL DEFAULT true,
  "privacy_enable_input_output_logging"          boolean                  NOT NULL DEFAULT true,
  "privacy_zdr_only"                             boolean                  NOT NULL DEFAULT false,
  "provider_restriction_mode"                    text                     NOT NULL DEFAULT 'none'::text,
  "provider_restriction_provider_ids"            text[]                   NOT NULL DEFAULT '{}'::text[],
  "provider_restriction_enforce_allowed"         boolean                  NOT NULL DEFAULT false,
  "sso_enabled"                                  boolean                  NOT NULL DEFAULT false,
  "sso_enforced"                                 boolean                  NOT NULL DEFAULT false,
  "sso_mode"                                     text                     NOT NULL DEFAULT 'none'::text,
  "sso_provider_identifier"                      text,
  "sso_domains"                                  text[]                   NOT NULL DEFAULT '{}'::text[],
  "alpha_channel_enabled"                        boolean                  NOT NULL DEFAULT false,
  "gateway_plugins"                              jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  "io_logging_enabled"                           boolean                  NOT NULL DEFAULT false,
  "io_logging_retention_days"                    integer                  NOT NULL DEFAULT 90,
  "io_logging_include_provider_payloads"         boolean                  NOT NULL DEFAULT true,
  "io_logging_updated_at"                        timestamp with time zone,
  "data_contribution_enabled"                    boolean                  NOT NULL DEFAULT false,
  "data_contribution_policy_version"             text,
  "data_contribution_consented_at"               timestamp with time zone,
  "data_contribution_consented_by"               uuid,
  "data_contribution_sample_rate_bps"            integer                  NOT NULL DEFAULT 10000,
  "data_contribution_classifier_sample_rate_bps" integer                  NOT NULL DEFAULT 1000,
  "data_contribution_discount_bps"               integer                  NOT NULL DEFAULT 100,
  "response_healing_enabled"                     boolean                  NOT NULL DEFAULT false,
  "response_healing_locked"                      boolean                  NOT NULL DEFAULT false,
  "response_healing_mode"                        text                     NOT NULL DEFAULT 'safe'::text,
  "cache_aware_routing_enabled"                  boolean                  NOT NULL DEFAULT true,
  "low_balance_email_enabled"                    boolean                  NOT NULL DEFAULT false,
  "low_balance_email_threshold_nanos"            bigint                   NOT NULL DEFAULT 0,
  "low_balance_email_last_sent_at"               timestamp with time zone,
  "low_balance_email_last_sent_balance_nanos"    bigint,
  "auto_top_up_failure_email_enabled"            boolean                  NOT NULL DEFAULT true,
  "payment_method_expiring_email_enabled"        boolean                  NOT NULL DEFAULT true,
  "model_restriction_mode"                       text                     NOT NULL DEFAULT 'none'::text,
  "model_restriction_model_ids"                  text[]                   NOT NULL DEFAULT '{}'::text[],
  "io_logging_billing_status"                    text                     NOT NULL DEFAULT 'active'::text,
  "io_logging_grace_until"                       timestamp with time zone,
  "io_logging_last_billed_at"                    timestamp with time zone,
  "io_logging_last_billing_warning_at"           timestamp with time zone,
  "io_logging_last_billing_warning_kind"         text,
  "io_logging_price_per_million_units_nanos"     bigint                   NOT NULL DEFAULT 0,
  "model_deprecation_alerts_enabled"             boolean                  NOT NULL DEFAULT false,
  "auto_routing_allowed_patterns"                text[]                   NOT NULL DEFAULT '{}'::text[],
  "auto_routing_spend_profile"                   text                     NOT NULL DEFAULT 'standard'::text,
  "auto_routing_max_input_price_per_million"     numeric,
  "auto_routing_max_output_price_per_million"    numeric,
  "auto_routing_objective"                       text                     NOT NULL DEFAULT 'balanced'::text,
  "auto_routing_fallbacks_enabled"               boolean                  NOT NULL DEFAULT true,
  "auto_routing_revision"                        uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "auto_routing_updated_at"                      timestamp with time zone NOT NULL DEFAULT now(),
  "model_deprecation_alerts_include_admins"      boolean                  NOT NULL DEFAULT false,
  "model_successor_redirect_enabled"             boolean                  NOT NULL DEFAULT false,
  "model_successor_price_policy"                 text                     NOT NULL DEFAULT 'never'::text,
  "model_successor_max_price_increase_percent"   integer                  NOT NULL DEFAULT 0,
  "io_logging_contents_access"                   text                     NOT NULL DEFAULT 'members'::text,
  "department_spend_attribution"                 text                     NOT NULL DEFAULT 'all'::text,
  "billing_time_zone"                            text                     NOT NULL DEFAULT 'UTC'::text,
  "spend_report_cadence"                         text                     NOT NULL DEFAULT 'weekly'::text,
  "spend_report_include_admins"                  boolean                  NOT NULL DEFAULT false,
  CONSTRAINT "workspace_settings_alpha_requires_beta_channel_check" CHECK (((alpha_channel_enabled = false) OR (beta_channel_enabled = true))),
  CONSTRAINT "workspace_settings_auto_routing_custom_prices_valid" CHECK (((auto_routing_spend_profile <> 'custom'::text) OR ((auto_routing_max_input_price_per_million IS
    NOT NULL) AND (auto_routing_max_input_price_per_million >= (0)::numeric) AND (auto_routing_max_output_price_per_million IS
    NOT NULL) AND (auto_routing_max_output_price_per_million >= (0)::numeric)))),
  CONSTRAINT "workspace_settings_auto_routing_objective_valid" CHECK ((auto_routing_objective = ANY (ARRAY['balanced'::text, 'quality'::text, 'cost'::text, 'latency'::text]))),
  CONSTRAINT "workspace_settings_auto_routing_pattern_count_valid" CHECK ((cardinality(auto_routing_allowed_patterns) <= 16)),
  CONSTRAINT "workspace_settings_auto_routing_spend_profile_valid"
    CHECK ((auto_routing_spend_profile = ANY (ARRAY['economy'::text, 'standard'::text, 'premium'::text, 'unrestricted'::text, 'custom'::text]))),
  CONSTRAINT "workspace_settings_billing_time_zone_check" CHECK (((char_length(billing_time_zone) >= 1) AND (char_length(billing_time_zone) <= 64))),
  CONSTRAINT "workspace_settings_data_contribution_classifier_sample_rate_che"
    CHECK (((data_contribution_classifier_sample_rate_bps >= 0) AND (data_contribution_classifier_sample_rate_bps <= 10000))),
  CONSTRAINT "workspace_settings_data_contribution_consent_check" CHECK (((NOT data_contribution_enabled) OR ((data_contribution_policy_version IS
    NOT NULL) AND (data_contribution_consented_at IS NOT NULL)))),
  CONSTRAINT "workspace_settings_data_contribution_discount_check" CHECK (((data_contribution_discount_bps >= 0) AND (data_contribution_discount_bps <= 10000))),
  CONSTRAINT "workspace_settings_data_contribution_sample_rate_check" CHECK (((data_contribution_sample_rate_bps >= 0) AND (data_contribution_sample_rate_bps <= 10000))),
  CONSTRAINT "workspace_settings_department_spend_attribution_check" CHECK ((department_spend_attribution = ANY (ARRAY['all'::text, 'primary'::text]))),
  CONSTRAINT "workspace_settings_io_logging_contents_access_check" CHECK ((io_logging_contents_access = ANY (ARRAY['members'::text, 'admins'::text]))),
  CONSTRAINT "workspace_settings_io_logging_billing_status_check" CHECK ((io_logging_billing_status = ANY (ARRAY['active'::text, 'grace'::text, 'suspended'::text]))),
  CONSTRAINT "workspace_settings_io_logging_price_per_million_units_check" CHECK ((io_logging_price_per_million_units_nanos >= 0)),
  CONSTRAINT "workspace_settings_io_logging_retention_days_check" CHECK (((io_logging_retention_days >= 90) AND (io_logging_retention_days <= 365))),
  CONSTRAINT "workspace_settings_low_balance_threshold_nonnegative" CHECK ((low_balance_email_threshold_nanos >= 0)),
  CONSTRAINT "workspace_settings_model_restriction_mode_valid" CHECK ((model_restriction_mode = ANY (ARRAY['none'::text, 'allowlist'::text, 'blocklist'::text]))),
  CONSTRAINT "workspace_settings_model_successor_max_price_increase_check"
    CHECK (((model_successor_max_price_increase_percent >= 0) AND (model_successor_max_price_increase_percent <= 1000))),
  CONSTRAINT "workspace_settings_model_successor_price_policy_check"
    CHECK ((model_successor_price_policy = ANY (ARRAY['never'::text, 'limit'::text, 'any'::text]))),
  CONSTRAINT "workspace_settings_pkey" PRIMARY KEY (workspace_id),
  CONSTRAINT "workspace_settings_provider_restriction_mode_check" CHECK ((provider_restriction_mode = ANY (ARRAY['none'::text, 'allowlist'::text, 'blocklist'::text]))),
  CONSTRAINT "workspace_settings_response_healing_mode_check" CHECK ((response_healing_mode = ANY (ARRAY['safe'::text, 'strict'::text]))),
  CONSTRAINT "workspace_settings_spend_report_cadence_check" CHECK ((spend_report_cadence = ANY (ARRAY['off'::text, 'daily'::text, 'weekly'::text, 'monthly'::text]))),
  CONSTRAINT "workspace_settings_sso_mode_check" CHECK ((sso_mode = ANY (ARRAY['none'::text, 'saml'::text, 'custom_oidc'::text])))
);

ALTER TABLE "public"."workspace_settings"
  ENABLE ROW LEVEL SECURITY;

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."workspace_settings" TO "anon", "authenticated", "service_role";

COMMENT ON COLUMN "public"."workspace_settings"."auto_routing_allowed_patterns" IS 'Optional glob patterns that narrow the managed phaseo/auto text-model universe.';

COMMENT ON COLUMN "public"."workspace_settings"."auto_routing_revision" IS 'Immutable revision identifier replaced whenever the auto-routing configuration changes.';

COMMENT ON COLUMN "public"."workspace_settings"."auto_routing_spend_profile" IS 'Hard price-ceiling profile applied before phaseo/auto scores candidates.';

COMMENT ON COLUMN "public"."workspace_settings"."auto_top_up_failure_email_enabled" IS 'Email the workspace owner when an automatic credit top-up cannot be completed.';

COMMENT ON COLUMN "public"."workspace_settings"."billing_time_zone" IS 'IANA time zone for spend rule calendar periods (rules with a null time_zone) and spend reports. Validated against pg_timezone_names by public.validate_workspace_billing_time_zone. Enforced key limits and workspace budgets stay on UTC.';

COMMENT ON COLUMN "public"."workspace_settings"."department_spend_attribution" IS 'How spend rules, department budgets and department rate limits count a person''s requests toward departments when their key has no department: all (every department they belong to) or primary (only their primary one). A key''s own department and a directory override always win. See private.spend_scope_departments and private.department_budget_key_departments.';

COMMENT ON COLUMN "public"."workspace_settings"."data_contribution_classifier_sample_rate_bps" IS 'Independent upstream classifier submission rate in basis points. Platform controlled; initially 1000 (10%).';

COMMENT ON COLUMN "public"."workspace_settings"."data_contribution_discount_bps" IS 'Discount applied to eligible non-BYOK request charges in basis points. Platform controlled; initially 100 (1%).';

COMMENT ON COLUMN "public"."workspace_settings"."data_contribution_enabled" IS 'Explicit workspace opt-in to contribute a deterministic sample of prompts and completions for a billing discount.';

COMMENT ON COLUMN "public"."workspace_settings"."data_contribution_sample_rate_bps" IS 'Deterministic redacted I/O retention rate in basis points. Platform controlled; initially 10000 (100%).';

COMMENT ON COLUMN "public"."workspace_settings"."io_logging_billing_status" IS 'Extended-retention state consumed by the gateway I/O logging path.';

COMMENT ON COLUMN "public"."workspace_settings"."io_logging_contents_access" IS 'Who may read stored request and response payloads: members (any workspace member) or admins (owners and admins only).';

COMMENT ON COLUMN "public"."workspace_settings"."io_logging_price_per_million_units_nanos" IS 'Reserved extended-retention price override; zero uses the default.';

COMMENT ON COLUMN "public"."workspace_settings"."model_deprecation_alerts_include_admins" IS 'Also email workspace admins, not only the owner, when a model the workspace recently called is deprecated.';

COMMENT ON COLUMN "public"."workspace_settings"."model_restriction_model_ids" IS 'Canonical API model slugs used by the workspace-wide model restriction mode.';

COMMENT ON COLUMN "public"."workspace_settings"."model_successor_max_price_increase_percent" IS 'With the limit price policy, the largest price increase allowed when redirecting to a successor, as a percentage.';

COMMENT ON COLUMN "public"."workspace_settings"."model_successor_price_policy" IS 'Whether a successor that costs more may serve redirected requests: never, limit (up to the percentage) or any.';

COMMENT ON COLUMN "public"."workspace_settings"."model_successor_redirect_enabled" IS 'Route requests for a model no provider serves any more to its admin-approved successor.';

COMMENT ON COLUMN "public"."workspace_settings"."spend_report_cadence" IS 'How often owners (and admins with spend_report_include_admins) get a spend report email: off, daily (09:00 for the day before), weekly (Monday 09:00 for the previous ISO week) or monthly (the 1st at 09:00 for the previous month), in billing_time_zone. Periods without spend are skipped. Queued by public.queue_spend_reports behind SPEND_REPORTS_ENABLED.';

COMMENT ON COLUMN "public"."workspace_settings"."spend_report_include_admins" IS 'Also email the spend report to workspace admins, not only owners. Anyone can unsubscribe from the link in the email.';

COMMENT ON COLUMN "public"."workspace_settings"."payment_method_expiring_email_enabled" IS 'Email the workspace owner before a saved card used for billing expires.';

-- source: supabase/schemas/public/tables/workspace_spend_blocks.sql
CREATE TABLE "public"."workspace_spend_blocks" (
  "id"                uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "workspace_id"      uuid                     NOT NULL,
  "rule_id"           uuid,
  "scope_type"        text                     NOT NULL,
  "scope_id"          text,
  "block_free_models" boolean                  NOT NULL DEFAULT false,
  "period_start"      timestamp with time zone NOT NULL,
  "resets_at"         timestamp with time zone,
  "spend_nanos"       bigint                   NOT NULL,
  "limit_nanos"       bigint                   NOT NULL,
  "started_at"        timestamp with time zone NOT NULL DEFAULT now(),
  "lifted_at"         timestamp with time zone,
  "lifted_by"         uuid,
  "lift_reason"       text,
  "created_at"        timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"        timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "workspace_spend_blocks_amounts_check" CHECK (((spend_nanos >= 0) AND (limit_nanos > 0))),
  CONSTRAINT "workspace_spend_blocks_lift_check" CHECK ((((lifted_at IS NULL) = (lift_reason IS NULL)) AND ((lifted_by IS NULL) OR (lift_reason IS NOT DISTINCT FROM 'manual'::text)) AND ((lifted_at IS NULL) OR (lifted_at >= started_at)))),
  CONSTRAINT "workspace_spend_blocks_lift_reason_check" CHECK (((lift_reason IS NULL) OR (lift_reason = ANY (ARRAY['manual'::text, 'period_reset'::text, 'below_limit'::text, 'rule_changed'::text, 'rule_disabled'::text, 'rule_deleted'::text])))),
  CONSTRAINT "workspace_spend_blocks_pkey" PRIMARY KEY (id),
  CONSTRAINT "workspace_spend_blocks_resets_at_check" CHECK (((resets_at IS NULL) OR (resets_at > period_start))),
  CONSTRAINT "workspace_spend_blocks_scope_check" CHECK (((scope_type = ANY (ARRAY['workspace'::text, 'key'::text, 'member'::text, 'department'::text, 'model'::text, 'provider'::text])) AND ((scope_type = 'workspace'::text) = (scope_id IS NULL))))
);

ALTER TABLE "public"."workspace_spend_blocks"
  ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE "public"."workspace_spend_blocks" IS 'Blocks started by spend rules, active (lifted_at null) and lifted. Scope and block_free_models are copied from the rule when the block starts, so the request path can match it without the rule. At most one active block per rule. A block lifted manually is not restarted in the same period (same rule_id and period_start).';

COMMENT ON COLUMN "public"."workspace_spend_blocks"."resets_at" IS 'When the block''s period ends and it lifts by itself (the 429 Retry-After). Null for rolling rules, which lift once spend in the window falls below the limit.';

COMMENT ON COLUMN "public"."workspace_spend_blocks"."limit_nanos" IS 'The spend at which the rule blocks: block_at_amount_nanos, or block_at_percent of the base when the block started.';

COMMENT ON COLUMN "public"."workspace_spend_blocks"."lift_reason" IS 'manual (lifted_by set), period_reset, below_limit (rolling window or a raised base), rule_changed, rule_disabled or rule_deleted.';

REVOKE ALL ON TABLE "public"."workspace_spend_blocks" FROM "service_role";

