-- source: supabase/schemas/private/functions/mobile_notification_rule_matches.sql
CREATE OR REPLACE FUNCTION private.mobile_notification_rule_matches (
  p_rule              public.mobile_notification_rules,
  p_kind              text,
  p_lab_slug          text,
  p_provider_slug     text,
  p_model_slug        text,
  p_input_modalities  text[],
  p_output_modalities text[],
  p_on_phaseo         boolean
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  -- Lists left empty match anything. An event without a lab or provider matches "all" and
  -- "except" but never "only". Modality lists are all required. Mute rules ignore
  -- include_free_variants, so muting a lab also mutes its free variants. A provider launching
  -- on Phaseo (provider_launched, which has no model or lab) is matched by rules about Phaseo
  -- availability or new providers, so rules written before it existed pick it up.
  select p_rule.enabled
    and (
      p_kind = any (p_rule.event_kinds)
      or (p_kind = 'provider_launched' and p_rule.event_kinds && ARRAY['gateway_available', 'provider_added'])
    )
    and (
      p_rule.lab_mode = 'all'
      or (p_rule.lab_mode = 'only' and coalesce(p_lab_slug = any (p_rule.lab_slugs), false))
      or (p_rule.lab_mode = 'except' and not coalesce(p_lab_slug = any (p_rule.lab_slugs), false))
    )
    and (
      p_rule.provider_mode = 'all'
      or (p_rule.provider_mode = 'only' and coalesce(p_provider_slug = any (p_rule.provider_slugs), false))
      or (p_rule.provider_mode = 'except' and not coalesce(p_provider_slug = any (p_rule.provider_slugs), false))
    )
    and (cardinality(p_rule.model_slugs) = 0 or coalesce(p_model_slug = any (p_rule.model_slugs), false))
    and (cardinality(p_rule.input_modalities) = 0 or coalesce(p_input_modalities @> p_rule.input_modalities, false))
    and (cardinality(p_rule.output_modalities) = 0 or coalesce(p_output_modalities @> p_rule.output_modalities, false))
    and (not p_rule.only_on_phaseo or coalesce(p_on_phaseo, false))
    and (p_rule.action = 'mute' or p_rule.include_free_variants or p_model_slug is null or p_model_slug !~ ':free$');
$function$;

REVOKE ALL ON FUNCTION "private"."mobile_notification_rule_matches"(public.mobile_notification_rules, text, text, text, text, text[], text[], boolean) FROM PUBLIC;

-- source: supabase/schemas/public/functions/apply_preset_upstream_version.sql
CREATE OR REPLACE FUNCTION public.apply_preset_upstream_version (
  target_preset_id  uuid,
  target_version_id uuid,
  actor_user_id     uuid
)
  RETURNS public.presets
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  p public.presets%rowtype;
  source public.presets%rowtype;
  upstream public.preset_versions%rowtype;
  updated public.presets%rowtype;
begin
  select * into p from public.presets where id = target_preset_id and archived_at is null for update;
  if not found or p.created_by <> actor_user_id then raise exception 'preset_update_forbidden'; end if;
  if p.source_preset_id is null then raise exception 'preset_has_no_upstream'; end if;
  if p.draft_name is distinct from p.name
    or p.draft_slug is distinct from p.slug
    or p.draft_description is distinct from p.description
    or p.draft_config is distinct from p.config
    or p.draft_visibility is distinct from p.visibility
  then raise exception 'preset_has_local_draft_changes'; end if;

  select * into source from public.presets
  where id = p.source_preset_id and visibility = 'public' and archived_at is null;
  if not found then raise exception 'upstream_preset_not_public'; end if;

  select * into upstream from public.preset_versions
  where id = target_version_id and preset_id = source.id and visibility = 'public';
  if not found then raise exception 'upstream_version_not_public'; end if;

  update public.presets set draft_name = upstream.name, draft_slug = upstream.slug,
    draft_description = upstream.description, draft_config = upstream.config,
    upstream_version_id = upstream.id, updated_at = now()
  where id = p.id returning * into updated;
  return updated;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."apply_preset_upstream_version"(uuid, uuid, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."apply_preset_upstream_version"(uuid, uuid, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_account_deletion_jobs.sql
CREATE OR REPLACE FUNCTION public.claim_account_deletion_jobs (
  p_limit         integer DEFAULT 5,
  p_lease_seconds integer DEFAULT 300
)
  RETURNS SETOF public.account_deletion_jobs
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  return query
  with candidates as (
    select job.id
    from public.account_deletion_jobs as job
    where job.status in ('pending', 'purging', 'failed')
      and job.next_attempt_at <= now()
      and (job.lease_expires_at is null or job.lease_expires_at <= now())
      and job.completed_at is null
    order by job.deadline_at asc, job.next_attempt_at asc, job.requested_at asc
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 5), 25))
  )
  update public.account_deletion_jobs as job
  set status = 'purging',
      lease_expires_at = now() + make_interval(secs => greatest(30, least(coalesce(p_lease_seconds, 300), 900))),
      last_attempt_at = now(),
      attempts = job.attempts + 1,
      last_error = null,
      updated_at = now()
  from candidates
  where job.id = candidates.id
  returning job.*;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_account_deletion_jobs"(integer, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."claim_account_deletion_jobs"(integer, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_data_contributions.sql
CREATE OR REPLACE FUNCTION public.claim_data_contributions (
  p_limit         integer DEFAULT 25,
  p_lease_seconds integer DEFAULT 300
)
  RETURNS SETOF public.data_contributions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return query
  with candidates as (
    select contribution.id
    from public.data_contributions contribution
    where contribution.status in ('pending', 'failed', 'processing')
      and case
        when contribution.status = 'processing' then contribution.lease_expires_at
        else contribution.available_at
      end <= now()
      and contribution.retention_until > now()
    order by
      case
        when contribution.status = 'processing' then contribution.lease_expires_at
        else contribution.available_at
      end,
      contribution.occurred_at,
      contribution.id
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 25), 250))
  )
  update public.data_contributions contribution
  set status = 'processing',
      attempt_count = contribution.attempt_count + 1,
      lease_expires_at = now() + make_interval(secs => greatest(30, least(coalesce(p_lease_seconds, 300), 3600))),
      updated_at = now()
  from candidates
  where contribution.id = candidates.id
  returning contribution.*;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_data_contributions"(integer, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."claim_data_contributions"(integer, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/claim_otel_export_outbox.sql
CREATE OR REPLACE FUNCTION public.claim_otel_export_outbox (
  p_limit integer DEFAULT 100
)
  RETURNS SETOF public.otel_export_outbox
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  return query
  with candidates as (
    select id
    from public.otel_export_outbox
    where (
      status = 'pending'
      or (status = 'processing' and lease_expires_at < now())
    )
      and next_attempt_at <= now()
    order by next_attempt_at, created_at
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 100), 500))
  ),
  claimed as (
    update public.otel_export_outbox outbox
    set status = 'processing',
        attempts = attempts + 1,
        lease_expires_at = now() + interval '15 minutes',
        updated_at = now()
    from candidates
    where outbox.id = candidates.id
    returning outbox.*
  )
  select * from claimed;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."claim_otel_export_outbox"(integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."claim_otel_export_outbox"(integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/create_workspace_department.sql
CREATE OR REPLACE FUNCTION public.create_workspace_department (
  p_workspace_id  uuid,
  p_name          text,
  p_icon          text,
  p_color         text,
  p_actor_user_id uuid,
  p_request_id    text DEFAULT NULL::text
)
  RETURNS public.workspace_departments
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare created public.workspace_departments;
begin
  insert into public.workspace_departments(workspace_id,name,icon,color,source_type)
  values(p_workspace_id,btrim(p_name),p_icon,p_color,'manual') returning * into created;
  insert into public.workspace_directory_audit_events(workspace_id,actor_user_id,action,target_type,target_id,after_state,request_id)
  values(p_workspace_id,p_actor_user_id,'workspace.department.create','workspace_department',created.id::text,to_jsonb(created),p_request_id);
  return created;
end;
$function$;

