-- source: supabase/schemas/public/functions/gateway_claim_provider_events.sql
CREATE OR REPLACE FUNCTION public.gateway_claim_provider_events (
  p_providers     text[],
  p_limit         integer DEFAULT 100,
  p_worker_id     text    DEFAULT 'batch-provider-event-replay'::text,
  p_lease_seconds integer DEFAULT 120
)
  RETURNS SETOF public.gateway_provider_events
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return query
  with candidates as (
    select event.id
    from public.gateway_provider_events event
    where event.provider = any(p_providers)
      and event.processed_at is null
      and event.dead_lettered_at is null
      and (event.next_attempt_at is null or event.next_attempt_at <= now())
      and (
        event.replay_locked_at is null
        or event.replay_locked_at < now() - make_interval(secs => greatest(30, least(coalesce(p_lease_seconds, 120), 3600)))
      )
    order by event.created_at asc
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 100), 500))
  )
  update public.gateway_provider_events event
  set replay_locked_at = now(),
      replay_locked_by = left(coalesce(nullif(trim(p_worker_id), ''), 'batch-provider-event-replay'), 200),
      updated_at = now()
  from candidates
  where event.id = candidates.id
  returning event.*;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_claim_provider_events"(text[], integer, text, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_claim_provider_events"(text[], integer, text, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_realtime_claim_connection.sql
CREATE OR REPLACE FUNCTION public.gateway_realtime_claim_connection (
  p_session_id         text,
  p_client_secret_hash text
)
  RETURNS SETOF public.gateway_realtime_sessions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_session public.gateway_realtime_sessions%rowtype;
begin
  select * into v_session
  from public.gateway_realtime_sessions
  where session_id = p_session_id
  for update;

  if not found then raise exception 'realtime_session_not_found'; end if;
  if coalesce(v_session.provider_client_secret_hash, '') <> coalesce(p_client_secret_hash, '') then
    raise exception 'realtime_relay_forbidden';
  end if;
  if v_session.status <> 'created' then
    raise exception 'realtime_relay_already_connected';
  end if;
  if v_session.expires_at is not null and v_session.expires_at <= now() then
    raise exception 'realtime_session_expired';
  end if;

  update public.gateway_realtime_sessions
  set status = 'connecting', last_event_at = now(), updated_at = now()
  where id = v_session.id and status = 'created'
  returning * into v_session;

  if not found then raise exception 'realtime_relay_already_connected'; end if;
  return next v_session;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_realtime_claim_connection"(text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_realtime_claim_connection"(text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_realtime_create_with_hold_without_workspace_budget.sql
CREATE OR REPLACE FUNCTION public.gateway_realtime_create_with_hold_without_workspace_budget (
  p_workspace_id             uuid,
  p_session_id               text,
  p_key_id                   uuid,
  p_user_id                  text,
  p_source                   text,
  p_provider                 text,
  p_model_id                 text,
  p_provider_model_id        text,
  p_voice                    text,
  p_expires_at               timestamp with time zone,
  p_reservation_prefix       text,
  p_reservation_id           text,
  p_hold_nanos               bigint,
  p_client_secret_hash       text,
  p_metadata                 jsonb                    DEFAULT '{}'::jsonb,
  p_max_workspace_sessions   integer                  DEFAULT 8,
  p_max_key_sessions         integer                  DEFAULT 4,
  p_max_user_sessions        integer                  DEFAULT 1,
  p_max_creations_per_minute integer                  DEFAULT 8
)
  RETURNS SETOF public.gateway_realtime_sessions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_wallet public.wallets%rowtype;
  v_session public.gateway_realtime_sessions%rowtype;
  v_count integer;
begin
  if p_workspace_id is null or coalesce(trim(p_session_id), '') = '' then
    raise exception 'invalid_realtime_session_identity';
  end if;
  if p_key_id is null then
    raise exception 'invalid_realtime_key';
  end if;
  if p_hold_nanos is null or p_hold_nanos <= 0 then
    raise exception 'invalid_realtime_hold';
  end if;
  if p_source not in ('api', 'chat') then
    raise exception 'invalid_realtime_source';
  end if;
  if p_expires_at is null or p_expires_at <= now() then
    raise exception 'invalid_realtime_expiry';
  end if;

  -- The wallet row serializes create/limit checks for the workspace.
  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception 'wallet_not_found';
  end if;

  select count(*)::integer into v_count
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id
    and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved');
  if v_count >= greatest(1, p_max_workspace_sessions) then
    raise exception 'realtime_workspace_concurrency_limit';
  end if;

  select count(*)::integer into v_count
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id
    and key_id = p_key_id
    and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved');
  if v_count >= greatest(1, p_max_key_sessions) then
    raise exception 'realtime_key_concurrency_limit';
  end if;

  if nullif(trim(coalesce(p_user_id, '')), '') is not null then
    select count(*)::integer into v_count
    from public.gateway_realtime_sessions
    where workspace_id = p_workspace_id
      and user_id = p_user_id
      and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved');
    if v_count >= greatest(1, p_max_user_sessions) then
      raise exception 'realtime_user_concurrency_limit';
    end if;
  end if;

  select count(*)::integer into v_count
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id
    and created_at >= now() - interval '1 minute';
  if v_count >= greatest(1, p_max_creations_per_minute) then
    raise exception 'realtime_creation_rate_limit';
  end if;

  if coalesce(v_wallet.balance_nanos, 0) - coalesce(v_wallet.reserved_nanos, 0) < p_hold_nanos then
    raise exception 'insufficient_funds';
  end if;

  insert into public.gateway_realtime_sessions (
    session_id, workspace_id, key_id, user_id, source, provider, model_id,
    provider_model_id, voice, status, expires_at, reservation_prefix,
    reservation_count, reserved_nanos, provider_client_secret_hash, metadata
  ) values (
    p_session_id, p_workspace_id, p_key_id, nullif(trim(coalesce(p_user_id, '')), ''),
    p_source, p_provider, p_model_id, p_provider_model_id, p_voice, 'created',
    p_expires_at, p_reservation_prefix, 1, p_hold_nanos,
    p_client_secret_hash, coalesce(p_metadata, '{}'::jsonb)
  ) returning * into v_session;

  insert into public.gateway_wallet_reservations (
    reservation_id, workspace_id, amount_nanos, status, hold_ref_id,
    captured_nanos, released_nanos, created_at, updated_at
  ) values (
    p_reservation_id, p_workspace_id, p_hold_nanos, 'reserved', p_session_id,
    0, 0, now(), now()
  );

  insert into public.gateway_requests (
    workspace_id, request_id, realtime_session_id, endpoint, model_id, provider,
    stream, byok, status_code, success, usage, cost_nanos, currency,
    pricing_lines, key_id, created_at
  ) values (
    p_workspace_id, 'realtime:' || p_session_id, p_session_id, 'audio.realtime',
    p_model_id, p_provider, true, false, 102, false, '{}'::jsonb, 0, 'USD',
    '[]'::jsonb, p_key_id, v_session.started_at
  );

  update public.wallets
  set reserved_nanos = coalesce(reserved_nanos, 0) + p_hold_nanos,
      updated_at = now()
  where workspace_id = p_workspace_id;

  return next v_session;
end;
$function$;

GRANT EXECUTE
  ON FUNCTION "public"."gateway_realtime_create_with_hold_without_workspace_budget"(uuid, text, uuid, text, text, text, text, text, text, timestamp
    WITH time zone, text, text, bigint, text, jsonb, integer, integer, integer, integer)
  TO "service_role";

REVOKE ALL
  ON FUNCTION "public"."gateway_realtime_create_with_hold_without_workspace_budget"(uuid, text, uuid, text, text, text, text, text, text, timestamp
    WITH time zone, text, text, bigint, text, jsonb, integer, integer, integer, integer)
  FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_realtime_create_with_hold.sql
CREATE OR REPLACE FUNCTION public.gateway_realtime_create_with_hold (
  p_workspace_id             uuid,
  p_session_id               text,
  p_key_id                   uuid,
  p_user_id                  text,
  p_source                   text,
  p_provider                 text,
  p_model_id                 text,
  p_provider_model_id        text,
  p_voice                    text,
  p_expires_at               timestamp with time zone,
  p_reservation_prefix       text,
  p_reservation_id           text,
  p_hold_nanos               bigint,
  p_client_secret_hash       text,
  p_metadata                 jsonb                    DEFAULT '{}'::jsonb,
  p_max_workspace_sessions   integer                  DEFAULT 8,
  p_max_key_sessions         integer                  DEFAULT 4,
  p_max_user_sessions        integer                  DEFAULT 1,
  p_max_creations_per_minute integer                  DEFAULT 8
)
  RETURNS SETOF public.gateway_realtime_sessions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_budget_status jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text, 0));
  v_budget_status := public.gateway_workspace_budget_status(p_workspace_id, p_hold_nanos);
  if not coalesce((v_budget_status->>'ok')::boolean, true) then
    raise exception '%', v_budget_status->>'reason';
  end if;

  return query select * from public.gateway_realtime_create_with_hold_without_workspace_budget(
    p_workspace_id, p_session_id, p_key_id, p_user_id, p_source, p_provider,
    p_model_id, p_provider_model_id, p_voice, p_expires_at, p_reservation_prefix,
    p_reservation_id, p_hold_nanos, p_client_secret_hash, p_metadata,
    p_max_workspace_sessions, p_max_key_sessions, p_max_user_sessions,
    p_max_creations_per_minute
  );
end;
$function$;

GRANT EXECUTE
  ON FUNCTION "public"."gateway_realtime_create_with_hold"(uuid, text, uuid, text, text, text, text, text, text, timestamp
    WITH time zone, text, text, bigint, text, jsonb, integer, integer, integer, integer)
  TO "service_role";

REVOKE ALL
  ON FUNCTION "public"."gateway_realtime_create_with_hold"(uuid, text, uuid, text, text, text, text, text, text, timestamp
    WITH time zone, text, text, bigint, text, jsonb, integer, integer, integer, integer)
  FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_realtime_extend_hold_once_without_workspace_budget.sql
CREATE OR REPLACE FUNCTION public.gateway_realtime_extend_hold_once_without_workspace_budget (
  p_workspace_id          uuid,
  p_session_id            text,
  p_reservation_id        text,
  p_target_reserved_nanos bigint,
  p_estimated_cost_nanos  bigint DEFAULT 0
)
  RETURNS SETOF public.gateway_realtime_sessions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_wallet public.wallets%rowtype;
  v_session public.gateway_realtime_sessions%rowtype;
  v_additional bigint;
begin
  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;
  if not found then raise exception 'wallet_not_found'; end if;

  select * into v_session
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id
  for update;
  if not found then raise exception 'realtime_session_not_found'; end if;
  if v_session.status not in ('created', 'connecting', 'connected', 'ending') then
    raise exception 'realtime_session_terminal';
  end if;

  v_additional := greatest(0, coalesce(p_target_reserved_nanos, 0) - coalesce(v_session.reserved_nanos, 0));
  if v_additional > 0 then
    -- The relay begins the budget close when this raises.
    if coalesce(v_wallet.balance_nanos, 0) - coalesce(v_wallet.reserved_nanos, 0) < v_additional then
      raise exception 'insufficient_funds';
    end if;

    insert into public.gateway_wallet_reservations (
      reservation_id, workspace_id, amount_nanos, status, hold_ref_id,
      captured_nanos, released_nanos, created_at, updated_at
    ) values (
      p_reservation_id, p_workspace_id, v_additional, 'reserved', p_session_id,
      0, 0, now(), now()
    );
    update public.wallets
    set reserved_nanos = coalesce(reserved_nanos, 0) + v_additional,
        updated_at = now()
    where workspace_id = p_workspace_id;
  end if;

  update public.gateway_realtime_sessions
  set reservation_count = reservation_count + case when v_additional > 0 then 1 else 0 end,
      reserved_nanos = reserved_nanos + v_additional,
      estimated_cost_nanos = greatest(estimated_cost_nanos, coalesce(p_estimated_cost_nanos, 0)),
      last_event_at = now(), updated_at = now()
  where id = v_session.id
  returning * into v_session;

  return next v_session;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_realtime_extend_hold_once_without_workspace_budget"(uuid, text, text, bigint, bigint) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_realtime_extend_hold_once_without_workspace_budget"(uuid, text, text, bigint, bigint) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_realtime_extend_hold_once.sql
CREATE OR REPLACE FUNCTION public.gateway_realtime_extend_hold_once (
  p_workspace_id          uuid,
  p_session_id            text,
  p_reservation_id        text,
  p_target_reserved_nanos bigint,
  p_estimated_cost_nanos  bigint DEFAULT 0
)
  RETURNS SETOF public.gateway_realtime_sessions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_current_reserved_nanos bigint;
  v_additional_nanos bigint;
  v_budget_status jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text, 0));
  select reserved_nanos into v_current_reserved_nanos
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id;
  if not found then raise exception 'realtime_session_not_found'; end if;

  v_additional_nanos := greatest(0, coalesce(p_target_reserved_nanos, 0) - coalesce(v_current_reserved_nanos, 0));
  if v_additional_nanos > 0 then
    v_budget_status := public.gateway_workspace_budget_status(p_workspace_id, v_additional_nanos);
    if not coalesce((v_budget_status->>'ok')::boolean, true) then
      raise exception '%', v_budget_status->>'reason';
    end if;
  end if;

  return query select * from public.gateway_realtime_extend_hold_once_without_workspace_budget(
    p_workspace_id, p_session_id, p_reservation_id, p_target_reserved_nanos,
    p_estimated_cost_nanos
  );
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_realtime_extend_hold_once"(uuid, text, text, bigint, bigint) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_realtime_extend_hold_once"(uuid, text, text, bigint, bigint) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/gateway_realtime_mark_billing_unresolved.sql
CREATE OR REPLACE FUNCTION public.gateway_realtime_mark_billing_unresolved (
  p_workspace_id          uuid,
  p_session_id            text,
  p_usage                 jsonb,
  p_reason                text,
  p_confirmed_cost_nanos  bigint DEFAULT 0
)
  RETURNS SETOF public.gateway_realtime_sessions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_session public.gateway_realtime_sessions%rowtype;
  v_reservation public.gateway_wallet_reservations%rowtype;
  v_wallet_found boolean;
  v_held bigint;
  v_capture bigint := 0;
  v_remaining bigint;
  v_row_capture bigint;
  v_captured_total bigint;
  v_before_balance bigint;
  v_before_reserved bigint;
begin
  select * into v_session
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id;
  if not found then raise exception 'realtime_session_not_found'; end if;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return next v_session;
    return;
  end if;

  -- Same lock order as settlement: reservations, wallet, session.
  perform 1 from public.gateway_wallet_reservations r
  where r.workspace_id = p_workspace_id and r.status in ('held', 'reserved')
    and (r.hold_ref_id = p_session_id or r.reservation_id like v_session.reservation_prefix || '%')
  order by r.created_at, r.reservation_id
  for update;
  perform 1 from public.wallets where workspace_id = p_workspace_id for update;
  v_wallet_found := found;
  select * into v_session
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id
  for update;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return next v_session;
    return;
  end if;

  -- Capture the provider-confirmed portion now, from the session holds, so a
  -- review only has to decide the unconfirmed remainder.
  v_capture := greatest(0, coalesce(p_confirmed_cost_nanos, 0) - coalesce(v_session.captured_nanos, 0));
  if v_capture > 0 and v_wallet_found then
    select coalesce(sum(r.amount_nanos), 0)::bigint into v_held
    from public.gateway_wallet_reservations r
    where r.workspace_id = p_workspace_id and r.status in ('held', 'reserved')
      and (r.hold_ref_id = p_session_id or r.reservation_id like v_session.reservation_prefix || '%');
    select w.balance_nanos, w.reserved_nanos into v_before_balance, v_before_reserved
    from public.wallets w where w.workspace_id = p_workspace_id;
    v_capture := least(v_capture, v_held, greatest(0, coalesce(v_before_reserved, 0)));
  else
    v_capture := 0;
  end if;

  if v_capture > 0 then
    v_captured_total := coalesce(v_session.captured_nanos, 0) + v_capture;
    v_remaining := v_capture;
    for v_reservation in
      select r.* from public.gateway_wallet_reservations r
      where r.workspace_id = p_workspace_id and r.status in ('held', 'reserved')
        and (r.hold_ref_id = p_session_id or r.reservation_id like v_session.reservation_prefix || '%')
      order by r.created_at, r.reservation_id
      for update
    loop
      exit when v_remaining <= 0;
      v_row_capture := least(v_reservation.amount_nanos, v_remaining);
      if v_row_capture = v_reservation.amount_nanos then
        update public.gateway_wallet_reservations
        set status = 'captured', captured_nanos = v_row_capture, released_nanos = 0,
            capture_ref_id = p_session_id, captured_at = now(), updated_at = now()
        where workspace_id = p_workspace_id and reservation_id = v_reservation.reservation_id;
      else
        -- Split the hold: the captured part becomes its own captured row.
        update public.gateway_wallet_reservations
        set amount_nanos = v_reservation.amount_nanos - v_row_capture, updated_at = now()
        where workspace_id = p_workspace_id and reservation_id = v_reservation.reservation_id;
        insert into public.gateway_wallet_reservations (
          reservation_id, workspace_id, amount_nanos, status, hold_ref_id, capture_ref_id,
          captured_nanos, released_nanos, captured_at, created_at, updated_at
        ) values (
          v_session.reservation_prefix || 'confirmed:' || v_captured_total::text, p_workspace_id,
          v_row_capture, 'captured', p_session_id, p_session_id, v_row_capture, 0, now(), now(), now()
        );
      end if;
      v_remaining := v_remaining - v_row_capture;
    end loop;

    update public.wallets
    set balance_nanos = balance_nanos - v_capture,
        reserved_nanos = greatest(0, reserved_nanos - v_capture),
        updated_at = now()
    where workspace_id = p_workspace_id;

    insert into public.credit_ledger (
      workspace_id, event_time, kind, amount_nanos, before_balance_nanos,
      after_balance_nanos, before_reserved_nanos, after_reserved_nanos,
      ref_type, ref_id, created_at, status
    ) values (
      p_workspace_id, now(), 'charge', -v_capture, v_before_balance,
      v_before_balance - v_capture, v_before_reserved, greatest(0, v_before_reserved - v_capture),
      'realtime_session', p_session_id || ':confirmed:' || v_captured_total::text, now(), 'captured'
    ) on conflict (ref_type, ref_id) do nothing;
  end if;

  update public.gateway_realtime_sessions
  set status = 'billing_unresolved',
      usage = coalesce(p_usage, '{}'::jsonb),
      captured_nanos = coalesce(captured_nanos, 0) + v_capture,
      disconnect_reason = left(coalesce(nullif(trim(p_reason), ''), 'authoritative_usage_missing'), 240),
      error_code = 'realtime_authoritative_usage_missing',
      last_event_at = now(),
      updated_at = now()
  where id = v_session.id
  returning * into v_session;

  update public.gateway_requests
  set status_code = 202,
      success = false,
      error_code = 'realtime_authoritative_usage_missing',
      error_message = 'Realtime billing requires reconciliation.',
      usage = coalesce(p_usage, '{}'::jsonb),
      cost_nanos = v_session.captured_nanos
  where realtime_session_id = p_session_id
    and created_at = v_session.started_at;

  return next v_session;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."gateway_realtime_mark_billing_unresolved"(uuid, text, jsonb, text, bigint) TO "service_role";

REVOKE ALL ON FUNCTION "public"."gateway_realtime_mark_billing_unresolved"(uuid, text, jsonb, text, bigint) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/get_slack_agent_skill.sql
CREATE OR REPLACE FUNCTION public.get_slack_agent_skill (
  p_installation_id uuid,
  p_name            text
)
  RETURNS SETOF public.slack_agent_skills
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  -- The Slack agent's use_skill tool: a saved skill by name, whatever its case.
  -- No row when there is none. Service role only.
  select skill.*
  from public.slack_agent_skills skill
  where skill.installation_id = p_installation_id and lower(skill.name) = lower(btrim(p_name))
  limit 1;
$function$;

COMMENT ON FUNCTION "public"."get_slack_agent_skill"(uuid, text) IS 'For the Slack Worker''s use_skill tool: one saved skill by name, case-insensitively, or no row.';

GRANT EXECUTE ON FUNCTION "public"."get_slack_agent_skill"(uuid, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."get_slack_agent_skill"(uuid, text) FROM PUBLIC, "anon", "authenticated";

