-- source: supabase/schemas/public/functions/publish_preset_version.sql
CREATE OR REPLACE FUNCTION public.publish_preset_version (
  target_preset_id uuid,
  actor_user_id    uuid,
  notes            text DEFAULT NULL::text,
  requested_label  text DEFAULT NULL::text
)
  RETURNS public.preset_versions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare p public.presets%rowtype; next_number integer; next_label text; date_base text; date_count integer; published public.preset_versions%rowtype;
begin
  select * into p from public.presets where id = target_preset_id and archived_at is null for update;
  if not found then raise exception 'preset_not_found'; end if;
  if p.created_by <> actor_user_id and (
    coalesce(p.draft_visibility, p.visibility) = 'private' or not exists (
      select 1 from public.workspace_members member
      where member.workspace_id = p.workspace_id
        and member.user_id = actor_user_id
        and member.role in ('owner', 'admin')
    )
  ) then raise exception 'preset_publish_forbidden'; end if;
  select coalesce(max(version_number), 0) + 1 into next_number from public.preset_versions where preset_id = p.id;
  if p.versioning_method = 'semver' then
    next_label := regexp_replace(trim(coalesce(requested_label, '')), '^v', '');
    if next_label !~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?(\+[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$' then raise exception 'invalid_semver_label'; end if;
  elsif p.versioning_method = 'date' then
    date_base := to_char(current_date, 'YYYY.MM.DD');
    select count(*) into date_count from public.preset_versions where preset_id = p.id and version_label like date_base || '%';
    next_label := case when date_count = 0 then date_base else date_base || '.' || (date_count + 1)::text end;
  else next_label := 'v' || next_number::text;
  end if;
  insert into public.preset_versions (preset_id, version_number, version_label, versioning_method, name, slug, description, config, visibility, release_notes, created_by)
  values (p.id, next_number, next_label, p.versioning_method, p.draft_name, p.draft_slug, p.draft_description, p.draft_config, p.draft_visibility, nullif(trim(notes), ''), actor_user_id)
  returning * into published;
  update public.presets set name = published.name, slug = published.slug, description = published.description,
    config = published.config, visibility = published.visibility, active_version_id = published.id, updated_at = now()
  where id = p.id;
  return published;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."publish_preset_version"(uuid, uuid, text, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."publish_preset_version"(uuid, uuid, text, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/replace_scim_group.sql
CREATE OR REPLACE FUNCTION public.replace_scim_group (
  p_workspace_id uuid,
  p_group_id     uuid,
  p_external_id  text,
  p_display_name text,
  p_user_ids     uuid[]
)
  RETURNS public.scim_groups
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare replaced public.scim_groups;
begin
  if not exists(select 1 from public.scim_groups where id=p_group_id and workspace_id=p_workspace_id) then raise exception 'SCIM group not found' using errcode='P0002'; end if;
  if exists(select 1 from unnest(coalesce(p_user_ids,'{}'::uuid[])) candidate(user_id) where not exists(select 1 from public.scim_users where id=candidate.user_id and workspace_id=p_workspace_id)) then raise exception 'SCIM user not found in workspace' using errcode='23503'; end if;
  perform set_config('phaseo.scim_group_replace','on',true);
  update public.scim_groups set external_id=p_external_id,display_name=p_display_name where id=p_group_id and workspace_id=p_workspace_id returning * into replaced;
  delete from public.scim_group_members where workspace_id=p_workspace_id and group_id=p_group_id;
  insert into public.scim_group_members(workspace_id,group_id,user_id) select p_workspace_id,p_group_id,user_id from (select distinct unnest(coalesce(p_user_ids,'{}'::uuid[])) user_id) users;
  perform public.reconcile_scim_entitlements(p_workspace_id);
  perform set_config('phaseo.scim_group_replace','off',true);
  perform public.refresh_workspace_effective_entitlements(p_workspace_id,null,'scim_group_replace');
  return replaced;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."replace_scim_group"(uuid, uuid, text, text, uuid[]) TO "service_role";

REVOKE ALL ON FUNCTION "public"."replace_scim_group"(uuid, uuid, text, text, uuid[]) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/search_slack_agent_notes.sql
CREATE OR REPLACE FUNCTION public.search_slack_agent_notes (
  p_installation_id uuid,
  p_channel_id      text,
  p_workspace_notes boolean,
  p_query           text,
  p_kind            text,
  p_include_done    boolean,
  p_limit           integer
)
  RETURNS SETOF public.slack_agent_notes
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  -- The Slack agent's recall tool: the notes one conversation can see (its own
  -- and, with p_workspace_notes, the whole Slack workspace's), optionally of one
  -- kind. With search words (up to 8, of 2 characters or more, matched
  -- case-insensitively anywhere in the text), only notes holding at least one
  -- come back, those holding more first; then newest first. Done to-dos only with
  -- p_include_done, expired notes never, and nothing while the installation's
  -- memory is off. At most 50 (default 10). Service role only.
  with words as (
    select distinct word
    from regexp_split_to_table(lower(coalesce(p_query, '')), '[\s,.;:!?()"]+') as word
    where char_length(word) >= 2
    limit 8
  )
  select note.*
  from public.slack_agent_notes note
  join public.slack_installations installation on installation.id = note.installation_id and installation.memory_enabled
  cross join lateral (
    select count(*) as hits from words where strpos(lower(note.text), words.word) > 0
  ) matched
  where note.installation_id = p_installation_id
    and (note.channel_id = p_channel_id or (note.channel_id is null and coalesce(p_workspace_notes, false)))
    and (p_kind is null or note.kind = p_kind)
    and (coalesce(p_include_done, false) or note.done_at is null)
    and (note.expires_at is null or note.expires_at > now())
    and (matched.hits > 0 or not exists (select 1 from words))
  order by matched.hits desc, note.created_at desc, note.id
  limit least(greatest(coalesce(p_limit, 10), 1), 50);
$function$;

COMMENT ON FUNCTION "public"."search_slack_agent_notes"(uuid, text, boolean, text, text, boolean, integer) IS 'For the Slack Worker''s recall tool: a conversation''s notes and, with p_workspace_notes, the Slack workspace''s, matching search words first, then newest first, at most 50. Leaves out done to-dos unless asked and expired notes always; none while the installation''s memory is off.';

GRANT EXECUTE ON FUNCTION "public"."search_slack_agent_notes"(uuid, text, boolean, text, text, boolean, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."search_slack_agent_notes"(uuid, text, boolean, text, text, boolean, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/set_data_contribution_consent.sql
CREATE OR REPLACE FUNCTION public.set_data_contribution_consent (
  p_workspace_id               uuid,
  p_enabled                    boolean,
  p_actor_type                 text,
  p_actor_user_id              uuid    DEFAULT NULL::uuid,
  p_actor_key_id               uuid    DEFAULT NULL::uuid,
  p_reason                     text    DEFAULT NULL::text,
  p_policy_version             text    DEFAULT '2026-07-26-v2'::text,
  p_sample_rate_bps            integer DEFAULT 10000,
  p_classifier_sample_rate_bps integer DEFAULT 1000,
  p_discount_bps               integer DEFAULT 100
)
  RETURNS public.workspace_settings
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_settings public.workspace_settings%rowtype;
begin
  if p_actor_type not in ('user', 'management_key', 'system') then
    raise exception 'invalid actor type';
  end if;
  if p_sample_rate_bps not between 0 and 10000
    or p_classifier_sample_rate_bps not between 0 and 10000
    or p_discount_bps not between 0 and 10000 then
    raise exception 'invalid contribution rates';
  end if;

  insert into public.workspace_settings (
    workspace_id, data_contribution_enabled, data_contribution_policy_version,
    data_contribution_consented_at, data_contribution_consented_by,
    data_contribution_sample_rate_bps, data_contribution_classifier_sample_rate_bps,
    data_contribution_discount_bps, updated_at
  ) values (
    p_workspace_id, p_enabled, p_policy_version,
    case when p_enabled then now() else null end,
    case when p_enabled then p_actor_user_id else null end,
    p_sample_rate_bps, p_classifier_sample_rate_bps, p_discount_bps, now()
  )
  on conflict (workspace_id) do update set
    data_contribution_enabled = excluded.data_contribution_enabled,
    data_contribution_policy_version = excluded.data_contribution_policy_version,
    data_contribution_consented_at = excluded.data_contribution_consented_at,
    data_contribution_consented_by = excluded.data_contribution_consented_by,
    data_contribution_sample_rate_bps = excluded.data_contribution_sample_rate_bps,
    data_contribution_classifier_sample_rate_bps = excluded.data_contribution_classifier_sample_rate_bps,
    data_contribution_discount_bps = excluded.data_contribution_discount_bps,
    updated_at = excluded.updated_at
  returning * into v_settings;

  insert into public.data_contribution_consent_events (
    workspace_id, actor_type, actor_user_id, actor_key_id, action, outcome,
    policy_version, sample_rate_bps, classifier_sample_rate_bps, discount_bps, reason
  ) values (
    p_workspace_id, p_actor_type, p_actor_user_id, p_actor_key_id,
    case when p_enabled then 'enabled' else 'disabled' end,
    'succeeded', p_policy_version, p_sample_rate_bps, p_classifier_sample_rate_bps, p_discount_bps,
    left(p_reason, 500)
  );

  if not p_enabled then
    update public.data_contributions
    set retention_until = least(retention_until, now()),
        available_at = greatest(available_at, now()),
        updated_at = now()
    where workspace_id = p_workspace_id
      and status <> 'deleted';
  end if;

  return v_settings;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."set_data_contribution_consent"(uuid, boolean, text, uuid, uuid, text, text, integer, integer, integer) TO "service_role";

REVOKE ALL ON FUNCTION "public"."set_data_contribution_consent"(uuid, boolean, text, uuid, uuid, text, text, integer, integer, integer) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/set_preset_version_label.sql
CREATE OR REPLACE FUNCTION public.set_preset_version_label (
  p_preset_id   uuid,
  p_label       text,
  p_version_id  uuid,
  actor_user_id uuid
)
  RETURNS public.preset_version_labels
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare p public.presets%rowtype; normalized text := lower(btrim(coalesce(p_label, ''))); saved public.preset_version_labels%rowtype;
begin
  select * into p from public.presets where id = p_preset_id and archived_at is null;
  if not found then raise exception 'preset_not_found'; end if;
  -- Same rule as publish_preset_version: a label decides what requests run.
  if p.created_by is distinct from actor_user_id and (
    coalesce(p.draft_visibility, p.visibility) = 'private' or not exists (
      select 1 from public.workspace_members member
      where member.workspace_id = p.workspace_id
        and member.user_id = actor_user_id
        and member.role in ('owner', 'admin')
    )
  ) then raise exception 'preset_label_forbidden'; end if;
  if normalized !~ '^[a-z][a-z0-9_-]{0,31}$' or normalized ~ '^v[0-9]+$' then raise exception 'invalid_preset_label'; end if;
  if not exists (select 1 from public.preset_versions v where v.id = p_version_id and v.preset_id = p.id) then
    raise exception 'preset_version_not_found';
  end if;
  insert into public.preset_version_labels as l (preset_id, label, version_id, updated_by)
  values (p.id, normalized, p_version_id, actor_user_id)
  on conflict (preset_id, label) do update
    set version_id = excluded.version_id, updated_by = excluded.updated_by, updated_at = now()
  returning * into saved;
  return saved;
end $function$;

GRANT EXECUTE ON FUNCTION "public"."set_preset_version_label"(uuid, text, uuid, uuid) TO "service_role";

REVOKE ALL ON FUNCTION "public"."set_preset_version_label"(uuid, text, uuid, uuid) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/set_slack_agent_todo_done.sql
CREATE OR REPLACE FUNCTION public.set_slack_agent_todo_done (
  p_installation_id uuid,
  p_channel_id      text,
  p_workspace_notes boolean,
  p_note_id         uuid,
  p_done            boolean
)
  RETURNS SETOF public.slack_agent_notes
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  -- The Slack agent's update_todo tool: marks a to-do done or not done. Only a
  -- to-do the conversation can see (its own or, with p_workspace_notes, the whole
  -- Slack workspace's) that hasn't expired, while the installation's memory is
  -- on; no row when there is none. Marking a done to-do done again keeps when it
  -- was done. Service role only.
  update public.slack_agent_notes note
  set done_at = case when coalesce(p_done, false) then coalesce(note.done_at, now()) end
  from public.slack_installations installation
  where note.id = p_note_id
    and note.installation_id = p_installation_id
    and installation.id = note.installation_id and installation.memory_enabled
    and note.kind = 'todo'
    and (note.channel_id = p_channel_id or (note.channel_id is null and coalesce(p_workspace_notes, false)))
    and (note.expires_at is null or note.expires_at > now())
  returning note.*;
$function$;

COMMENT ON FUNCTION "public"."set_slack_agent_todo_done"(uuid, text, boolean, uuid, boolean) IS 'For the Slack Worker''s update_todo tool: marks a to-do the conversation can see (the workspace''s only with p_workspace_notes) done or not done, while the installation''s memory is on. Returns the to-do, or no row when there is none.';

GRANT EXECUTE ON FUNCTION "public"."set_slack_agent_todo_done"(uuid, text, boolean, uuid, boolean) TO "service_role";

REVOKE ALL ON FUNCTION "public"."set_slack_agent_todo_done"(uuid, text, boolean, uuid, boolean) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/update_workspace_auto_top_up.sql
CREATE OR REPLACE FUNCTION public.update_workspace_auto_top_up (
  p_workspace_id            uuid,
  p_enabled                 boolean,
  p_balance_threshold_nanos bigint,
  p_amount_nanos            bigint,
  p_payment_method_id       text,
  p_mfa_enabled             boolean,
  p_mfa_bypass_acknowledged boolean,
  p_mfa_bypass_phrase       text,
  p_actor_user_id           uuid    DEFAULT NULL::uuid,
  p_request_id              text    DEFAULT NULL::text
)
  RETURNS SETOF public.wallets
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_wallet public.wallets%rowtype;
  v_requires_mfa boolean;
begin
  if p_workspace_id is null then
    raise exception 'missing_workspace_id';
  end if;

  select *
  into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception 'wallet_not_found';
  end if;

  v_requires_mfa := p_enabled
    and not coalesce(p_mfa_enabled, false)
    and not coalesce(v_wallet.auto_top_up_enabled, false);

  if v_requires_mfa
    and not (
      coalesce(p_mfa_bypass_acknowledged, false)
      and coalesce(p_mfa_bypass_phrase, '') = 'I ACCEPT THE RISK'
    ) then
    raise exception 'mfa_required';
  end if;

  update public.wallets
  set auto_top_up_enabled = p_enabled,
      low_balance_threshold = case when p_enabled then coalesce(p_balance_threshold_nanos, 0) else 0 end,
      auto_top_up_amount = case when p_enabled then coalesce(p_amount_nanos, 0) else 0 end,
      auto_top_up_account_id = case when p_enabled then p_payment_method_id else null end,
      updated_at = now()
  where workspace_id = p_workspace_id;

  if v_requires_mfa then
    insert into public.workspace_audit_events (
      workspace_id,
      actor_user_id,
      action,
      target_type,
      target_id,
      metadata,
      request_id
    ) values (
      p_workspace_id,
      p_actor_user_id,
      'auto_top_up.enabled_without_mfa',
      'wallet',
      p_workspace_id::text,
      jsonb_build_object('consentVersion', 'mfa-bypass-v1', 'mfaEnabled', false),
      nullif(left(trim(coalesce(p_request_id, '')), 200), '')
    );
  end if;

  return query
  select updated_wallet.*
  from public.wallets as updated_wallet
  where updated_wallet.workspace_id = p_workspace_id;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."update_workspace_auto_top_up"(uuid, boolean, bigint, bigint, text, boolean, boolean, text, uuid, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."update_workspace_auto_top_up"(uuid, boolean, bigint, bigint, text, boolean, boolean, text, uuid, text) FROM PUBLIC, "anon", "authenticated";

-- source: supabase/schemas/public/functions/update_workspace_department.sql
CREATE OR REPLACE FUNCTION public.update_workspace_department (
  p_workspace_id  uuid,
  p_department_id uuid,
  p_name          text,
  p_icon          text,
  p_color         text,
  p_actor_user_id uuid,
  p_request_id    text DEFAULT NULL::text
)
  RETURNS public.workspace_departments
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare before_row public.workspace_departments; updated public.workspace_departments;
begin
  select * into before_row from public.workspace_departments where id=p_department_id and workspace_id=p_workspace_id for update;
  if before_row is null then raise exception 'Department not found'; end if;
  update public.workspace_departments set name=btrim(p_name),icon=p_icon,color=p_color,
    name_overridden=case when source_type='scim_group' and btrim(p_name) is distinct from directory_name then true else name_overridden end,
    updated_at=now()
  where id=p_department_id and workspace_id=p_workspace_id returning * into updated;
  perform public.refresh_workspace_effective_entitlements(p_workspace_id,p_actor_user_id,'department_updated');
  insert into public.workspace_directory_audit_events(workspace_id,actor_user_id,action,target_type,target_id,before_state,after_state,request_id)
  values(p_workspace_id,p_actor_user_id,'workspace.department.update','workspace_department',p_department_id::text,to_jsonb(before_row),to_jsonb(updated),p_request_id);
  return updated;
end;
$function$;

GRANT EXECUTE ON FUNCTION "public"."update_workspace_department"(uuid, uuid, text, text, text, uuid, text) TO "service_role";

REVOKE ALL ON FUNCTION "public"."update_workspace_department"(uuid, uuid, text, text, text, uuid, text) FROM PUBLIC, "anon", "authenticated";

