  FOR UPDATE
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.workspace_broadcast_destinations d
  WHERE ((d.id = broadcast_destination_keys.destination_id) AND public.is_workspace_admin(d.workspace_id)))))
  WITH CHECK ((EXISTS ( SELECT 1
   FROM public.workspace_broadcast_destinations d
  WHERE ((d.id = broadcast_destination_keys.destination_id) AND public.is_workspace_admin(d.workspace_id)))));

