-- ============================================================================
-- Event trigger and default privileges
-- ============================================================================

-- source: supabase/schemas/_cluster/event_triggers.sql
DO $event_trigger$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_event_trigger WHERE evtname = 'ensure_rls') THEN
    CREATE EVENT TRIGGER "ensure_rls"
      ON ddl_command_end
      WHEN TAG IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      EXECUTE FUNCTION "public"."rls_auto_enable"();
  END IF;
EXCEPTION WHEN insufficient_privilege THEN
  -- Event triggers need superuser. Without one, new tables in public do not get
  -- RLS switched on automatically, so every migration must enable it explicitly.
  RAISE WARNING 'event trigger ensure_rls not created: %', SQLERRM;
END
$event_trigger$;

-- source: supabase/schemas/_cluster/default_privileges.sql
ALTER DEFAULT PRIVILEGES REVOKE ALL ON FUNCTIONS FROM PUBLIC;

-- source: supabase/schemas/public/default_privileges.sql
ALTER DEFAULT PRIVILEGES IN SCHEMA "public" REVOKE ALL ON FUNCTIONS FROM PUBLIC;

RESET check_function_bodies;
RESET client_min_messages;
